INSERT INTO personas (id,name,age,background,personality_traits) VALUES ('P1','Nguyễn Minh (阮明)',22,'Du học sinh Việt Nam mới đến Trung Quốc, học Thương mại quốc tế','Lễ phép, hơi rón rén, tiếng Trung mức trung bình, cẩn thận') ON CONFLICT DO NOTHING;
INSERT INTO personas (id,name,age,background,personality_traits) VALUES ('P2','Lâm Vũ (林宇)',23,'Bạn cùng phòng người Trung Quốc','Nhiệt tình, thoải mái, hay giúp đỡ') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM01','呀','Hỏi/đáp nhẹ nhàng, giảm cảm giác cứng nhắc') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM02','啦','Nhẹ nhõm, vui vẻ, hoặc dứt điểm một việc') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM03','哦','Chỉnh/bổ sung thông tin nhẹ nhàng, không phủ định gắt') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM04','呢','Bổ sung/giải thích, hoặc thể hiện hơi bối rối/băn khoăn') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM05','啊','Hỏi lịch sự hoặc biểu lộ ngạc nhiên nhẹ') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM06','哈','Nhắc nhẹ, thân thiện, kéo gần khoảng cách hội thoại') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM07','吧','Đề nghị/xác nhận mang tính dò hỏi, không chắc chắn tuyệt đối') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM08','嘞','Đáp lời sảng khoái, đậm chất khẩu ngữ') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM09','嘛','Giọng hiển nhiên, thân mật, xoa dịu') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM10','哎呀','Tự trách/ngại ngùng bất ngờ') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM11','咯','Xác nhận nhẹ nhàng, coi như hiển nhiên/dứt khoát, giọng thân mật') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_A','Gọi lái xe taxi/xe công nghệ là ''thầy'' (师傅) bất kể tuổi','Cách gọi phổ biến, thể hiện sự tôn trọng, không phân biệt tuổi tác. Lặp lại ở các tình huống đi taxi/xe công nghệ.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_B','Ưu tiên thanh toán quét mã; mạng chậm thì chờ, không thúc ép; một số quán chỉ nhận quét mã','Thanh toán điện tử là chủ đạo ở Trung Quốc; tài xế/người bán thường kiên nhẫn chờ khách quét mã, và nhiều cửa hàng nhỏ không nhận tiền mặt.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_C','Ký túc xá quản lý theo quy định thống nhất, không có ngoại lệ','Giờ đóng cửa và quy định khách thăm áp dụng chung cho mọi sinh viên, kể cả sinh viên quốc tế.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_D','Thiết bị công cộng (đèn, máy giặt...) hỏng thì báo quản lý, không tự sửa','Trường/ký túc xá chịu trách nhiệm sửa chữa miễn phí; có thể đổi sang thiết bị khác dùng tạm trong lúc chờ.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_E','Thủ tục hành chính với sinh viên quốc tế cần thêm giấy xác nhận đang học','Chỉ hộ chiếu và visa thường chưa đủ để mở tài khoản ngân hàng hay làm một số thủ tục, cần bổ sung giấy xác nhận đang học.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_F','Thanh toán di động bắt buộc xác thực danh tính thật','Sinh viên nước ngoài dùng hộ chiếu để xác thực, không cần CMND Trung Quốc.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_G','Hồ sơ thiếu giấy tờ thường được cho nộp bổ sung có thời hạn','Chỉ cần thành thật xin lỗi và có kế hoạch bổ sung rõ ràng, không cần quá lo lắng.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_H','Biên phòng/hải quan làm việc theo nguyên tắc trung thực, ngắn gọn','Không cần giải thích dài dòng, chỉ cần trả lời đúng và đủ thông tin được hỏi.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_I','Đi nhầm chiều tàu điện ngầm có thể đổi chiều miễn phí ngay tại sân ga đối diện','Không cần ra cổng mua lại vé, chỉ cần sang sân ga đối diện, việc chuyển tuyến trong nhà ga là miễn phí.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_J','Có thể lịch sự đề nghị lái xe đổi lộ trình khi tắc đường mà không bị phụ thu thêm','Tài xế taxi/xe công nghệ thường chủ động hợp tác khi khách giải thích lý do gấp.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_K','Phí vận chuyển thực tế có thể cao hơn phí dự tính trên app nếu hàng quá cân','Đây là phụ thu hợp lệ theo cân nặng thật, không phải shipper tự ý tính thêm.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_M','Nên chủ động hỏi lại nhân viên nếu nghi ngờ thông tin vừa thay đổi (băng chuyền, cổng ra...)','Không nên tự đoán theo đám đông; thông tin sân bay có thể thay đổi tạm thời so với bảng hiển thị ban đầu.') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT201','S1','Điền tờ khai nhập cảnh trên máy bay','Nhờ tiếp viên hướng dẫn điền tờ khai nhập cảnh','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V201','SIT201','P1','suon_se','ban_chinh_thuc','Nhờ tiếp viên hướng dẫn điền tờ khai nhập cảnh','Tiếp viên trên máy bay giữ giọng mềm mỏng, hành khách hỏi thoải mái không cần quá rón rén.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_01','V201','Nguyễn Minh',1,'乘务员您好，我不太会填这个入境登记卡，能麻烦您教教我吗？','chéng wù yuán nín hǎo， wǒ bù tài huì tián zhè ge rù jìng dēng jì kǎ， néng má fán nín jiāo jiāo wǒ ma？','Chào tiếp viên, tôi không rành lắm việc điền tờ khai nhập cảnh này, phiền tiếp viên chỉ giúp tôi được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_02','V201','Tiếp viên',2,'没问题呀，我来跟你说。你护照上的信息照着填就行啦。','méi wèn tí ya， wǒ lái gēn nǐ shuō。 nǐ hù zhào shàng de xìn xī zhào zhe tián jiù xíng la。','Không vấn đề gì đâu, để tôi hướng dẫn bạn nhé. Cứ theo thông tin trên hộ chiếu mà điền là được rồi.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_03','V201','Nguyễn Minh',3,'好的，请问“来华事由”这一栏，我填“留学”就可以了吧？','hǎo de， qǐng wèn “lái huá shì yóu” zhè yī lán， wǒ tián “liú xué” jiù kě yǐ le ba？','Vâng, cho tôi hỏi ở mục "lý do đến Trung Quốc", tôi ghi "du học" là được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_04','V201','Tiếp viên',4,'对的，完全没问题。停留时间就写你签证上的时长哦。','duì de， wán quán méi wèn tí。 tíng liú shí jiān jiù xiě nǐ qiān zhèng shàng de shí cháng ó。','Đúng rồi, hoàn toàn ổn. Thời gian lưu trú thì bạn ghi theo thời hạn trên visa nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_05','V201','Nguyễn Minh',5,'那籍贯和出生地，直接填越南可以吗？','nà jí guàn hé chū shēng dì， zhí jiē tián yuè nán kě yǐ ma？','Vậy còn nguyên quán và nơi sinh, tôi ghi thẳng là Việt Nam có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_06','V201','Tiếp viên',6,'可以的，不用写太详细，简洁填写就好啦。','kě yǐ de， bù yòng xiě tài xiáng xì， jiǎn jié tián xiě jiù hǎo la。','Được chứ, không cần ghi quá chi tiết đâu, điền ngắn gọn là được rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_07','V201','Nguyễn Minh',7,'太谢谢您了，帮了我大忙！','tài xiè xiè nín le， bāng le wǒ dà máng！','Cảm ơn tiếp viên nhiều lắm, đã giúp tôi một việc lớn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_08','V201','Tiếp viên',8,'不客气哈，有不懂的随时再问我。','bú kè qì hā， yǒu bù dǒng de suí shí zài wèn wǒ。','Không có gì đâu, có gì chưa hiểu cứ hỏi tôi bất cứ lúc nào nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT202','S1','Hỏi lối ra sân bay','Hỏi hướng ra sân bay sau khi hạ cánh, được chỉ dẫn rõ ràng','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V202','SIT202','P1','suon_se','ban_chinh_thuc','Hỏi hướng ra sân bay sau khi hạ cánh, được chỉ dẫn rõ ràng','Nhân viên sân bay chỉ đường thường dùng cách nói dễ hiểu, không dùng thuật ngữ phức tạp.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_01','V202','Nguyễn Minh',1,'您好，麻烦问一下，机场出口是往这边走吗？','nín hǎo， má fán wèn yī xià， jī chǎng chū kǒu shì wǎng zhè biān zǒu ma？','Chào bạn, phiền hỏi một chút, lối ra sân bay là đi hướng này đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_02','V202','Nhân viên',2,'不是哦，这边是转机通道，出口在你的左手边呢。','bú shì ó， zhè biān shì zhuǎn jī tōng dào， chū kǒu zài nǐ de zuǒ shǒu biān ne。','Không phải đâu, bên này là lối nối chuyến, lối ra nằm ở phía tay trái của bạn đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_03','V202','Nguyễn Minh',3,'左手边是吗？一直直走就到了吧？','zuǒ shǒu biān shì ma？ yì zhí zhí zǒu jiù dào le ba？','Tay trái đúng không ạ? Cứ đi thẳng là tới phải không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_04','V202','Nhân viên',4,'对的，直走到底左转，跟着“国内到达”的牌子走就行啦。','duì de， zhí zǒu dào dǐ zuǒ zhuǎn， gēn zhe “guó nèi dào dá” de pái zi zǒu jiù xíng la。','Đúng vậy, đi thẳng đến cuối rồi rẽ trái, cứ theo biển "Đến trong nước" mà đi là được.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_05','V202','Nguyễn Minh',5,'好的，我明白了，谢谢您！','hǎo de， wǒ míng bái le， xiè xiè nín！','Vâng, tôi hiểu rồi, cảm ơn bạn nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_06','V202','Nhân viên',6,'没事的，慢走哈！','méi shì de， màn zǒu hā！','Không có gì đâu, đi cẩn thận nhé!','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT203','S1','Hỏi băng chuyền nhận hành lý','Băng chuyền bị đổi tạm thời so với thông tin ban đầu','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V203','SIT203','P1','twist','chinh_thuc','Băng chuyền bị đổi tạm thời so với thông tin ban đầu',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_01','V203','Nguyễn Minh',1,'您好，我想请问一下，国际航班的行李在哪里领取啊？','nín hǎo， wǒ xiǎng qǐng wèn yī xià， guó jì háng bān de xíng lǐ zài nǎ lǐ lǐng qǔ a？','Chào chị, tôi muốn hỏi hành lý của chuyến bay quốc tế thì nhận ở đâu ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_02','V203','Nhân viên',2,'您好，请问你的航班号是多少呢？','nín hǎo， qǐng wèn nǐ de háng bān hào shì duō shǎo ne？','Chào anh, cho tôi hỏi số hiệu chuyến bay của anh là bao nhiêu ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_03','V203','Nguyễn Minh',3,'是VN520航班，麻烦您查一下。','shì VN520 háng bān， má fán nín chá yī xià。','Là chuyến VN520, phiền chị kiểm tra giúp tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_04','V203','Nhân viên',4,'稍等，这班航班原本在3号转盘，刚刚临时调整到5号转盘了哦。','shāo děng， zhè bān háng bān yuán běn zài 3 hào zhuàn pán， gāng gāng lín shí diào zhěng dào 5 hào zhuàn pán le ó。','Anh chờ một chút, chuyến bay này ban đầu ở băng chuyền số 3, nhưng vừa mới được điều chỉnh tạm thời sang băng chuyền số 5 rồi ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_05','V203','Nguyễn Minh',5,'原来是这样，还好我问了，不然就走错啦。','yuán lái shì zhè yàng， hái hǎo wǒ wèn le， bù rán jiù zǒu cuò la。','Thì ra là vậy, may mà tôi hỏi, không thì đã đi nhầm rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_06','V203','Nhân viên',6,'是的，近期偶尔会调整，你直接去5号转盘等候就行。','shì de， jìn qī ǒu ěr huì tiáo zhěng， nǐ zhí jiē qù 5 hào zhuàn pán děng hòu jiù xíng。','Vâng, gần đây thỉnh thoảng có điều chỉnh, anh cứ đến thẳng băng chuyền số 5 chờ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_07','V203','Nguyễn Minh',7,'好的，非常感谢您！','hǎo de， fēi cháng gǎn xiè nín！','Vâng, cảm ơn chị rất nhiều!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT204','S5','Mua SIM và tư vấn gói cước','Chọn gói data phù hợp, hệ thống cửa hàng chậm phải chờ kích hoạt','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V204','SIT204','P1','twist','tuy_y','Chọn gói data phù hợp, hệ thống cửa hàng chậm phải chờ kích hoạt',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_01','V204','Nguyễn Minh',1,'你好，我是留学生，想办一张流量多的电话卡，有合适的套餐吗？','nǐ hǎo， wǒ shì liú xué shēng， xiǎng bàn yī zhāng liú liàng duō de diàn huà kǎ， yǒu hé shì de tào cān ma？','Chào bạn, mình là du học sinh, muốn đăng ký một sim có nhiều data, có gói nào phù hợp không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_02','V204','Nhân viên',2,'有的呀，这款学生套餐性价比超高，每月超多流量呢。','yǒu de ya， zhè kuǎn xué shēng tào cān xìng jià bǐ chāo gāo， měi yuè chāo duō liú liàng ne。','Có chứ, gói sinh viên này giá rất hời, mỗi tháng nhiều data lắm đó.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_03','V204','Nguyễn Minh',3,'那这个套餐可以直接当场激活吧？','nà zhè ge tào cān kě yǐ zhí jiē dāng chǎng jī huó ba？','Vậy gói này có thể kích hoạt luôn tại chỗ được không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_04','V204','Nhân viên',4,'本来可以的，不过今天系统有点卡，需要等两分钟哦。','běn lái kě yǐ de， bù guò jīn tiān xì tǒng yǒu diǎn kǎ， xū yào děng liǎng fēn zhōng ó。','Bình thường thì được, nhưng hôm nay hệ thống hơi chậm, phải đợi khoảng hai phút nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_05','V204','Nguyễn Minh',5,'没事的，我可以等，麻烦你啦。','méi shì de， wǒ kě yǐ děng， má fán nǐ la。','Không sao, mình đợi được, phiền bạn nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_06','V204','Nhân viên',6,'不麻烦！马上就好，激活后我帮你调好网络设置哈。','bù má fán！ mǎ shàng jiù hǎo， jī huó hòu wǒ bāng nǐ diào hǎo wǎng luò shè zhì hā。','Không phiền đâu! Xong ngay thôi, kích hoạt xong mình sẽ chỉnh giúp bạn cài đặt mạng luôn nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_07','V204','Nguyễn Minh',7,'太好了，谢谢你！','tài hǎo le， xiè xiè nǐ！','Tuyệt quá, cảm ơn bạn nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT205','S4','Trả lời biên phòng khi nhập cảnh','Trình bày mục đích, trường học, chuyên ngành, thời gian học, nguồn tài trợ','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V205','SIT205','P1','suon_se','chinh_thuc','Trình bày mục đích, trường học, chuyên ngành, thời gian học, nguồn tài trợ',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_01','V205','Biên phòng',1,'你好，出示一下护照和签证。来华目的是什么？','nǐ hǎo， chū shì yī xià hù zhào hé qiān zhèng。 lái huá mù dì shì shén me？','Chào anh, xuất trình hộ chiếu và visa. Mục đích đến Trung Quốc là gì?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_02','V205','Nguyễn Minh',2,'您好，我来中国留学的。','nín hǎo， wǒ lái zhōng guó liú xué de。','Chào chị, tôi đến Trung Quốc để du học ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_03','V205','Biên phòng',3,'在哪所学校就读？什么专业？','zài nǎ suǒ xué xiào jiù dú？ shén me zhuān yè？','Anh học ở trường nào? Chuyên ngành gì?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_04','V205','Nguyễn Minh',4,'我在省城理工大学，就读国际贸易专业。','wǒ zài shěng chéng lǐ gōng dà xué， jiù dú guó jì mào yì zhuān yè。','Tôi học tại Đại học Bách khoa tỉnh thành, chuyên ngành Thương mại quốc tế.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_05','V205','Biên phòng',5,'学习时长多久？资金来源是哪里？','xué xí shí cháng duō jiǔ？ zī jīn lái yuán shì nǎ lǐ？','Thời gian học bao lâu? Nguồn tài chính từ đâu?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_06','V205','Nguyễn Minh',6,'我学习四年，学费和生活费由家里提供。','wǒ xué xí sì nián， xué fèi hé shēng huó fèi yóu jiā lǐ tí gōng。','Tôi học bốn năm, học phí và sinh hoạt phí do gia đình chu cấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_07','V205','Biên phòng',7,'好的，信息核对无误，入境通过。','hǎo de， xìn xī hé duì wú wù， rù jìng tōng guò。','Được rồi, thông tin đối chiếu chính xác, cho phép nhập cảnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_08','V205','Nguyễn Minh',8,'谢谢工作人员！','xiè xiè gōng zuò rén yuán！','Cảm ơn cán bộ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT206','S4','Xin biên phòng nói chậm/lặp lại','Nghe không rõ câu hỏi, xin lỗi và đề nghị nói chậm hơn','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V206','SIT206','P1','suon_se','chinh_thuc','Nghe không rõ câu hỏi, xin lỗi và đề nghị nói chậm hơn',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_01','V206','Biên phòng',1,'你本次入境是否携带校外兼职相关材料？','nǐ běn cì rù jìng shì fǒu xié dài xiào wài jiān zhí xiāng guān cái liào？','Lần nhập cảnh này anh có mang theo giấy tờ liên quan đến việc làm thêm ngoài trường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_02','V206','Nguyễn Minh',2,'不好意思，我没太听懂您的问题呢。','bù hǎo yì sī， wǒ méi tài tīng dǒng nín de wèn tí ne。','Xin lỗi, tôi chưa nghe rõ câu hỏi của chị lắm ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_03','V206','Biên phòng',3,'没关系，那我放慢语速，再说一遍。','méi guān xì， nà wǒ fàng màn yǔ sù， zài shuō yī biàn。','Không sao, để tôi nói chậm lại, nhắc lại một lần nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_04','V206','Nguyễn Minh',4,'麻烦您了，我的中文听力还不太好。','má fán nín le， wǒ de zhōng wén tīng lì hái bù tài hǎo。','Phiền chị quá, khả năng nghe tiếng Trung của tôi chưa tốt lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_05','V206','Biên phòng',5,'没事，我问你有没有带校外工作、兼职的证明材料？','méi shì， wǒ wèn nǐ yǒu méi yǒu dài xiào wài gōng zuò、 jiān zhí de zhèng míng cái liào？','Không sao, tôi hỏi là anh có mang theo giấy tờ chứng minh việc làm thêm bên ngoài trường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_06','V206','Nguyễn Minh',6,'没有的，我目前只专注学业，没有准备兼职材料。','méi yǒu de， wǒ mù qián zhǐ zhuān zhù xué yè， méi yǒu zhǔn bèi jiān zhí cái liào。','Dạ không có, hiện tại tôi chỉ tập trung học tập, không chuẩn bị giấy tờ làm thêm gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_07','V206','Biên phòng',7,'好的，了解了。','hǎo de， liǎo jiě le。','Được rồi, tôi hiểu rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT207','S4','Khai báo hải quan','Trả lời không có gì khai báo, nhưng vẫn bị mở vali kiểm tra ngẫu nhiên','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V207','SIT207','P1','suon_se','chinh_thuc','Trả lời không có gì khai báo, nhưng vẫn bị mở vali kiểm tra ngẫu nhiên',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_01','V207','Hải quan',1,'你好，请问你本次入境有没有需要申报的物品？','nǐ hǎo， qǐng wèn nǐ běn cì rù jìng yǒu méi yǒu xū yào shēn bào de wù pǐn？','Chào anh, cho tôi hỏi lần nhập cảnh này anh có đồ gì cần khai báo không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_02','V207','Nguyễn Minh',2,'您好，我没有贵重物品，也没有超额物品，不需要申报的。','nín hǎo， wǒ méi yǒu guì zhòng wù pǐn， yě méi yǒu chāo é wù pǐn， bù xū yào shēn bào de。','Chào chị, tôi không có đồ vật giá trị, cũng không mang quá định mức, không cần khai báo ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_03','V207','Hải quan',3,'有没有携带大量现金、电子产品或者管制物品？','yǒu méi yǒu xié dài dà liàng xiàn jīn、 diàn zi chǎn pǐn huò zhě guǎn zhì wù pǐn？','Anh có mang theo nhiều tiền mặt, đồ điện tử hoặc vật phẩm bị kiểm soát không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_04','V207','Nguyễn Minh',4,'没有的，只带了个人生活用品和少量现金。','méi yǒu de， zhǐ dài le gè rén shēng huó yòng pǐn hé shǎo liàng xiàn jīn。','Dạ không có, tôi chỉ mang đồ dùng sinh hoạt cá nhân và một ít tiền mặt thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_05','V207','Hải quan',5,'好的，确认无申报物品，可以通行了。','hǎo de， què rèn wú shēn bào wù pǐn， kě yǐ tōng xíng le。','Được rồi, xác nhận không có đồ khai báo, anh có thể đi qua được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_06','V207','Nguyễn Minh',6,'好的，谢谢您！','hǎo de， xiè xiè nín！','Vâng, cảm ơn chị!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT208','S4','Khai báo thuốc mang theo','Phải khai báo thuốc tự dùng, không có đơn thuốc dịch sang tiếng Trung','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V208','SIT208','P1','twist','chinh_thuc','Phải khai báo thuốc tự dùng, không có đơn thuốc dịch sang tiếng Trung','Có thể mang theo thuốc tự dùng số lượng nhỏ; thuốc kê đơn nên có đơn thuốc dịch sang tiếng Trung và giữ lại vỏ hộp để thuận tiện khi kiểm tra.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_01','V208','Hải quan',1,'除了生活用品，还有其他需要申报的东西吗？','chú le shēng huó yòng pǐn， hái yǒu qí tā xū yào shēn bào de dōng xī ma？','Ngoài đồ dùng sinh hoạt ra, còn thứ gì khác cần khai báo không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_02','V208','Nguyễn Minh',2,'有的，我随身带了一些常用感冒药和肠胃药，需要申报吧？','yǒu de， wǒ suí shēn dài le yī xiē cháng yòng gǎn mào yào hé cháng wèi yào， xū yào shēn bào ba？','Có ạ, tôi có mang theo một ít thuốc cảm và thuốc đau bụng thông thường, cái này cần khai báo phải không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_03','V208','Hải quan',3,'是的，自用药品需要报备，带了多少数量呢？','shì de， zì yòng yào pǐn xū yào bào bèi， dài le duō shǎo shù liàng ne？','Đúng vậy, thuốc dùng cho cá nhân cần khai báo, anh mang theo số lượng bao nhiêu?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_04','V208','Nguyễn Minh',4,'都是个人短期自用的，没有大批量携带哦。','dōu shì gè rén duǎn qī zì yòng de， méi yǒu dà pī liàng xié dài ó。','Đều là dùng ngắn hạn cho cá nhân thôi, không mang số lượng lớn đâu ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_05','V208','Hải quan',5,'我看一下，没问题，自用常规药品可以放行，无需登记。','wǒ kàn yī xià， méi wèn tí， zì yòng cháng guī yào pǐn kě yǐ fàng xíng， wú xū dēng jì。','Để tôi xem qua, không có vấn đề gì, thuốc thông thường dùng cá nhân thì cho qua, không cần đăng ký.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_06','V208','Nguyễn Minh',6,'太好了，谢谢您的耐心核对！','tài hǎo le， xiè xiè nín de nài xīn hé duì！','Tuyệt quá, cảm ơn chị đã kiên nhẫn kiểm tra giúp tôi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_07','V208','Hải quan',7,'不客气，下次尽量保留药品外包装哦。','bú kè qì， xià cì jǐn liàng bǎo liú yào pǐn wài bāo zhuāng ó。','Không có gì, lần sau cố gắng giữ lại bao bì thuốc bên ngoài nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT209','S1','Báo hành lý hư hỏng','Hành lý bị vỡ, cần đăng ký để xử lý bồi thường','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V209','SIT209','P1','that_bai_nhe','ban_chinh_thuc','Hành lý bị vỡ, cần đăng ký để xử lý bồi thường','Hành lý hư hỏng ở sân bay được đăng ký bồi thường miễn phí; cần giữ thẻ hành lý và thẻ lên máy bay, không tự bỏ đi rồi mới báo sau.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_01','V209','Nguyễn Minh',1,'您好，麻烦您，我的行李箱好像被摔坏了。','nín hǎo， má fán nín， wǒ de xíng lǐ xiāng hǎo xiàng bèi shuāi huài le。','Chào chị, phiền chị xem giúp, va li của tôi hình như bị va đập hư rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_02','V209','Nhân viên',2,'别着急，我看一下，是箱体破损还是轮子损坏呀？','bié zháo jí， wǒ kàn yī xià， shì xiāng tǐ pò sǔn hái shì lún zi sǔn huài ya？','Anh đừng lo, để tôi xem thử, là vỏ va li bị nứt hay bánh xe bị hỏng vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_03','V209','Nguyễn Minh',3,'箱体侧面裂开了，里面的东西没坏，但是箱子没法用了。','xiāng tǐ cè miàn liè kāi le， lǐ miàn de dōng xī méi huài， dàn shì xiāng zi méi fǎ yòng le。','Mặt bên hông va li bị nứt ra, đồ bên trong không sao, nhưng va li thì không dùng được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_04','V209','Nhân viên',4,'我明白了，需要登记你的航班信息和行李牌，后续走理赔流程呢。','wǒ míng bái le， xū yào dēng jì nǐ de háng bān xìn xī hé xíng lǐ pái， hòu xù zǒu lǐ péi liú chéng ne。','Tôi hiểu rồi, cần đăng ký thông tin chuyến bay và thẻ hành lý của anh, sau đó sẽ tiến hành quy trình bồi thường ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_05','V209','Nguyễn Minh',5,'好的，我马上提供，大概多久能处理好呀？','hǎo de， wǒ mǎ shàng tí gōng， dà gài duō jiǔ néng chǔ lǐ hǎo ya？','Dạ được, tôi cung cấp ngay đây, khoảng bao lâu thì xử lý xong ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_06','V209','Nhân viên',6,'三个工作日内会有结果，你耐心等待通知就行。','sān gè gōng zuò rì nèi huì yǒu jié guǒ， nǐ nài xīn děng dài tōng zhī jiù xíng。','Trong vòng ba ngày làm việc sẽ có kết quả, anh cứ yên tâm chờ thông báo nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_07','V209','Nguyễn Minh',7,'辛苦您了，谢谢！','xīn kǔ nín le， xiè xiè！','Cảm ơn chị đã vất vả giúp đỡ, cảm ơn nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT210','S6','Đổi tiền và hỏi tỷ giá','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V210','SIT210','P1','twist','ban_chinh_thuc','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố','机场外币兑换汇率略低于市区银行，适合小额应急兑换，大额兑换建议去正规银行；往返双向兑换会产生双重汇兑损耗，尽量按需兑换。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_01','V210','阮明',1,'您好，我刚落地机场，想把随身带的越南盾兑换成人民币。','nín hǎo， wǒ gāng luò dì jī chǎng， xiǎng bǎ suí shēn dài de yuè nán dùn duì huàn chéng rén mín bì。','Chào anh/chị, tôi vừa hạ cánh xuống sân bay, muốn đổi số tiền Việt Nam đồng mang theo sang nhân dân tệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_02','V210','职员',2,'您好，先跟您确认一下，您清楚机场兑换点和市区银行汇率有差别吗？','nín hǎo， xiān gēn nín què rèn yī xià， nín qīng chǔ jī chǎng duì huàn diǎn hé shì qū yín háng huì lǜ yǒu chā bié ma？','Chào anh, để tôi xác nhận trước, anh có biết tỷ giá đổi ở sân bay và ngân hàng trong thành phố chênh lệch nhau không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_03','V210','阮明',3,'之前听同学提过一句，但具体差多少我不太了解啊。','zhī qián tīng tóng xué tí guò yī jù， dàn jù tǐ chà duō shǎo wǒ bù tài liǎo jiě a。','Trước đây tôi có nghe bạn học nhắc qua, nhưng chênh lệch cụ thể bao nhiêu thì tôi không rõ lắm.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_04','V210','职员',4,'今日实时汇率牌价就在柜台上方，机场汇率会比市区银行低三个点哦。','jīn rì shí shí huì lǜ pái jià jiù zài guì tái shàng fāng， jī chǎng huì lǜ huì bǐ shì qū yín háng dī sān gè diǎn ó。','Bảng tỷ giá thực tế hôm nay ở ngay phía trên quầy, tỷ giá ở sân bay sẽ thấp hơn ngân hàng trong thành phố khoảng ba điểm phần trăm ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_05','V210','阮明',5,'这样啊，差价还挺明显，那我先兑换一千元人民币应急可以吗？','zhè yàng a， chā jià hái tǐng míng xiǎn， nà wǒ xiān duì huàn yī qiān yuán rén mín bì yìng jí kě yǐ ma？','Vậy à, chênh lệch cũng khá rõ đấy, vậy tôi đổi trước một nghìn nhân dân tệ để dùng tạm được không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_06','V210','职员',6,'兑换外币有流程要求，需要出示护照登记个人信息哈。','duì huàn wài bì yǒu liú chéng yāo qiú， xū yào chū shì hù zhào dēng jì gè rén xìn xī hā。','Đổi ngoại tệ có quy trình yêu cầu, cần xuất trình hộ chiếu để đăng ký thông tin cá nhân ạ.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_07','V210','阮明',7,'没问题，护照我一直随身带着，现在递给您。那手续费是单独收取的吗？','méi wèn tí， hù zhào wǒ yì zhí suí shēn dài zhe， xiàn zài dì gěi nín。 nà shǒu xù fèi shì dān dú shōu qǔ de ma？','Không vấn đề gì, hộ chiếu tôi luôn mang theo bên người, đưa cho anh/chị đây. Vậy phí dịch vụ có tính riêng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_08','V210','职员',8,'单笔一千元以内的小额兑换免手续费，系统已经直接帮您核算完毕。','dān bǐ yī qiān yuán yǐ nèi de xiǎo é duì huàn miǎn shǒu xù fèi， xì tǒng yǐ jīng zhí jiē bāng nín hé suàn wán bì。','Giao dịch đổi nhỏ dưới một nghìn tệ mỗi lần thì được miễn phí, hệ thống đã tính toán xong cho anh rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_09','V210','阮明',9,'我再多问一句，如果剩下没花完的人民币，还能在这里换回越南盾吗？','wǒ zài duō wèn yī jù， rú guǒ shèng xià méi huā wán de rén mín bì， hái néng zài zhè lǐ huàn huí yuè nán dùn ma？','Tôi hỏi thêm một chút, nếu số nhân dân tệ còn dư chưa tiêu hết, có thể đổi lại thành tiền Việt ở đây không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_10','V210','职员',10,'可以兑换返程外币，但二次兑换会再收取一笔汇兑差价，不太划算。','kě yǐ duì huàn fǎn chéng wài bì， dàn èr cì duì huàn huì zài shōu qǔ yī bǐ huì duì chā jià， bù tài huá suàn。','Có thể đổi lại ngoại tệ khi về, nhưng đổi lần thứ hai sẽ bị tính thêm một khoản chênh lệch tỷ giá, không có lợi lắm đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_11','V210','阮明',11,'明白了，那我就只换一千元，够用今天打车吃饭就行。','míng bái le， nà wǒ jiù zhǐ huàn yī qiān yuán， gòu yòng jīn tiān dǎ chē chī fàn jiù xíng。','Tôi hiểu rồi, vậy tôi chỉ đổi một nghìn tệ thôi, đủ để đi taxi với ăn uống hôm nay là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_12','V210','职员',12,'好，我现在按实时汇率帮您清点现金，稍等片刻。','hǎo， wǒ xiàn zài àn shí shí huì lǜ bāng nín qīng diǎn xiàn jīn， shāo děng piàn kè。','Được, giờ tôi tính theo tỷ giá thực tế và đếm tiền mặt cho anh, chờ một chút nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_13','V210','阮明',13,'辛苦您了，汇率有变动也麻烦您再跟我说一声。','xīn kǔ nín le， huì lǜ yǒu biàn dòng yě má fán nín zài gēn wǒ shuō yī shēng。','Cảm ơn anh/chị đã vất vả, nếu tỷ giá có thay đổi thì phiền báo lại cho tôi biết với.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_14','V210','职员',14,'刚刚已经核对过牌价，短时间不会波动，现金给您收好。','gāng gāng yǐ jīng hé duì guò pái jià， duǎn shí jiān bú huì bō dòng， xiàn jīn gěi nín shōu hǎo。','Tôi vừa đối chiếu lại bảng giá rồi, trong thời gian ngắn sẽ không biến động đâu, tiền mặt anh cầm giữ kỹ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_15','V210','阮明',15,'太感谢您耐心讲解，省去我不少麻烦，那就兑换吧！','tài gǎn xiè nín nài xīn jiǎng jiě， shěng qù wǒ bù shǎo má fán， nà jiù duì huàn ba！','Cảm ơn anh/chị đã kiên nhẫn giải thích, đỡ cho tôi bao nhiêu phiền phức, vậy thì đổi luôn nhé!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT211','S5','Kết nối WiFi sân bay','Xin mật khẩu wifi, phải xác thực qua số điện thoại','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V211','SIT211','P1','suon_se','tuy_y','Xin mật khẩu wifi, phải xác thực qua số điện thoại',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_01','V211','Nguyễn Minh',1,'你好，请问机场的免费WiFi密码是多少呀？','nǐ hǎo， qǐng wèn jī chǎng de miǎn fèi WiFi mì mǎ shì duō shǎo ya？','Chào bạn, cho mình hỏi mật khẩu WiFi miễn phí của sân bay là gì vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_02','V211','Nhân viên',2,'很简单的，密码是机场全称的首字母加八个八哦。','hěn jiǎn dān de， mì mǎ shì jī chǎng quán chēng de shǒu zì mǔ jiā bā gè bā ó。','Đơn giản lắm, mật khẩu là chữ cái đầu của tên đầy đủ sân bay cộng với tám số 8 đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_03','V211','Nguyễn Minh',3,'我试了一下，怎么连不上呢？','wǒ shì le yī xià， zěn me lián bù shàng ne？','Mình thử rồi mà sao không kết nối được nhỉ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_04','V211','Nhân viên',4,'需要先打开浏览器验证一下，登录之后就能用啦。','xū yào xiān dǎ kāi liú lǎn qì yàn zhèng yī xià， dēng lù zhī hòu jiù néng yòng la。','Phải mở trình duyệt lên xác thực trước đã, đăng nhập xong là dùng được liền à.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_05','V211','Nguyễn Minh',5,'原来是这样，太感谢你啦！','yuán lái shì zhè yàng， tài gǎn xiè nǐ la！','Ra là vậy, cảm ơn bạn nhiều nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_06','V211','Nhân viên',6,'没事哒，有问题再问哈！','méi shì dá， yǒu wèn tí zài wèn hā！','Có gì đâu, có vấn đề gì cứ hỏi tiếp nha!','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT212','S1','Gọi người đón, báo vị trí','Báo cho bạn đến đón biết mình đã tới và đang ở đâu','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V212','SIT212','P1','suon_se','tuy_y','Báo cho bạn đến đón biết mình đã tới và đang ở đâu',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_01','V212','Nguyễn Minh',1,'宇哥，我已经到机场啦，顺利入境了！','yǔ gē， wǒ yǐ jīng dào jī chǎng la， shùn lì rù jìng le！','Anh Vũ ơi, em đến sân bay rồi nè, nhập cảnh suôn sẻ luôn!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_02','V212','Đón (Trần Vũ)',2,'太好了！你现在在哪个位置呀？','tài hǎo le！ nǐ xiàn zài zài nǎ ge wèi zhì ya？','Tốt quá! Giờ em đang ở chỗ nào vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_03','V212','Nguyễn Minh',3,'我在国内到达出口的问询台旁边呢。','wǒ zài guó nèi dào dá chū kǒu de wèn xún tái páng biān ne。','Em đang ở gần quầy hỏi đáp chỗ cửa ra đến trong nước nè.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_04','V212','Đón (Trần Vũ)',4,'好的，我马上就到，你就在原地等我别乱跑哈。','hǎo de， wǒ mǎ shàng jiù dào， nǐ jiù zài yuán dì děng wǒ bié luàn pǎo hā。','Ok, anh đến ngay đây, em cứ đứng yên đó chờ anh, đừng đi lung tung nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_05','V212','Nguyễn Minh',5,'没问题，我就在这里等你，不着急的。','méi wèn tí， wǒ jiù zài zhè lǐ děng nǐ， bù zháo jí de。','Không sao đâu, em đứng đây đợi anh, không vội đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_06','V212','Đón (Trần Vũ)',6,'五分钟就到，一会儿见！','wǔ fēn zhōng jiù dào， yī huì er jiàn！','Năm phút nữa là tới, lát gặp nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT213','S1','Không thấy người đón, gọi xác nhận','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V213','SIT213','P1','twist','tuy_y','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_01','V213','Nguyễn Minh',1,'宇哥，我已经在出口等了十分钟了，没看到你呀。','yǔ gē， wǒ yǐ jīng zài chū kǒu děng le shí fēn zhōng le， méi kàn dào nǐ ya。','Anh Vũ ơi, em đợi ở cửa ra mười phút rồi mà không thấy anh đâu cả.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_02','V213','Đón (Trần Vũ)',2,'哎呀抱歉！我走错出口了，我在二号出口，你在几号呀？','āi yā bào qiàn！ wǒ zǒu cuò chū kǒu le， wǒ zài èr hào chū kǒu， nǐ zài jǐ hào ya？','Ôi xin lỗi em! Anh đi lộn cửa ra rồi, anh đang ở cửa số 2, em ở cửa số mấy vậy?','AM10') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_03','V213','Nguyễn Minh',3,'我在一号出口，难怪看不到呢。','wǒ zài yī hào chū kǒu， nán guài kàn bú dào ne。','Em ở cửa số 1, thảo nào không thấy anh đâu.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_04','V213','Đón (Trần Vũ)',4,'太不好意思了！我马上走通道过来，两分钟就到你那边。','tài bù hǎo yì sī le！ wǒ mǎ shàng zǒu tōng dào guò lái， liǎng fēn zhōng jiù dào nǐ nà biān。','Ngại quá đi! Anh đi lối này qua ngay đây, hai phút nữa là tới chỗ em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_05','V213','Nguyễn Minh',5,'没事没事，不着急，我慢慢等你就好啦。','méi shì méi shì， bù zháo jí， wǒ màn màn děng nǐ jiù hǎo la。','Không sao đâu, không vội, em từ từ đợi anh là được rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_06','V213','Đón (Trần Vũ)',6,'辛苦你啦，马上汇合！','xīn kǔ nǐ la， mǎ shàng huì hé！','Cảm ơn em đã chờ nha, sắp gặp nhau rồi!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT214','S2','Đặt xe công nghệ, xác nhận tài xế','Xác nhận đúng tài xế và biển số trước khi lên xe','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V214','SIT214','P1','suon_se','tuy_y','Xác nhận đúng tài xế và biển số trước khi lên xe',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_01','V214','Tài xế',1,'你好，是尾号3621的乘客吧？我到机场上车点了。','nǐ hǎo， shì wěi hào 3621 de chéng kè ba？ wǒ dào jī chǎng shàng chē diǎn le。','Chào bạn, có phải khách hàng số điện thoại đuôi 3621 không? Mình đến điểm đón ở sân bay rồi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_02','V214','Nguyễn Minh',2,'对的是我！麻烦问一下，您的车牌号是多少呀？','duì de shì wǒ！ má fán wèn yī xià， nín de chē pái hào shì duō shǎo ya？','Đúng là mình đây! Cho mình hỏi, biển số xe của bạn là gì vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_03','V214','Tài xế',3,'车牌是浙A8523K，黑色轿车，很好认的。','chē pái shì zhè A8523K， hēi sè jiào chē， hěn hǎo rèn de。','Biển số xe là 浙A8523K, xe màu đen, dễ nhận ra lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_04','V214','Nguyễn Minh',4,'好的，我看到您的车了，马上走过去哈。','hǎo de， wǒ kàn dào nín de chē le， mǎ shàng zǒu guò qù hā。','Ok, mình thấy xe bạn rồi, mình đi qua ngay nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_05','V214','Tài xế',5,'不急，慢慢走，注意身边行李就行。','bù jí， màn màn zǒu， zhù yì shēn biān xíng lǐ jiù xíng。','Không vội đâu, cứ đi từ từ, chú ý hành lý bên cạnh là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_06','V214','Nguyễn Minh',6,'好嘞，辛苦您等我一下！','hǎo lei， xīn kǔ nín děng wǒ yī xià！','Dạ được, cảm ơn bạn đã đợi mình nha!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT215','S2','Báo địa chỉ đến cho tài xế','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V215','SIT215','P1','suon_se','tuy_y','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_01','V215','Tài xế',1,'同学，我们现在出发，你去哪里呀？','tóng xué， wǒ men xiàn zài chū fā， nǐ qù nǎ lǐ ya？','Bạn ơi, mình xuất phát luôn nhé, bạn đi đâu vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_02','V215','Nguyễn Minh',2,'师傅您好，麻烦去省城理工大学留学生公寓。','shī fù nín hǎo， má fán qù shěng chéng lǐ gōng dà xué liú xué shēng gōng yù。','Chào bác tài, phiền bác cho cháu đến ký túc xá lưu học sinh trường Đại học Bách khoa tỉnh thành ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_03','V215','Tài xế',3,'是新校区那个留学生宿舍吧？','shì xīn xiào qū nà ge liú xué shēng sù shè ba？','Là ký túc xá lưu học sinh ở khu campus mới đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_04','V215','Nguyễn Minh',4,'对的！我第一次去，辛苦您多留意路线呢。','duì de！ wǒ dì yī cì qù， xīn kǔ nín duō liú yì lù xiàn ne。','Dạ đúng rồi! Cháu đi lần đầu, phiền bác để ý đường đi giúp cháu nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_05','V215','Tài xế',5,'放心吧，这条路我常跑，不会走错的。','fàng xīn ba， zhè tiáo lù wǒ cháng pǎo， bú huì zǒu cuò de。','Yên tâm đi, con đường này bác chạy hoài rồi, không đi lộn đâu.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_06','V215','Nguyễn Minh',6,'那就太好了，谢谢您！','nà jiù tài hǎo le， xiè xiè nín！','Vậy thì tốt quá, cảm ơn bác nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT216','S2','Thanh toán quét mã sau khi đi taxi','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V216','SIT216','P1','twist','tuy_y','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_01','V216','Tài xế',1,'同学，我们到学校门口啦，车程结束了。','tóng xué， wǒ men dào xué xiào mén kǒu la， chē chéng jié shù le。','Bạn ơi, tới cổng trường rồi nè, chuyến đi kết thúc rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_02','V216','Nguyễn Minh',2,'好的！我想扫码支付，可是手机网络有点慢怎么办？','hǎo de！ wǒ xiǎng sǎo mǎ zhī fù， kě shì shǒu jī wǎng luò yǒu diǎn màn zěn me bàn？','Dạ vâng! Cháu muốn quét mã thanh toán, nhưng mạng điện thoại hơi chậm thì làm sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_03','V216','Tài xế',3,'没关系呀，不急，你慢慢加载就行。','méi guān xì ya， bù jí， nǐ màn màn jiā zài jiù xíng。','Không sao đâu, đừng vội, cứ từ từ để nó tải là được.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_04','V216','Nguyễn Minh',4,'终于好了，已经支付成功啦，您看一下！','zhōng yú hǎo le， yǐ jīng zhī fù chéng gōng la， nín kàn yī xià！','Cuối cùng cũng được rồi, thanh toán thành công rồi ạ, bác xem giúp cháu với!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_05','V216','Tài xế',5,'收到了，没问题。路上辛苦了，欢迎下次坐车哈！','shōu dào le， méi wèn tí。 lù shàng xīn kǔ le， huān yíng xià cì zuò chē hā！','Nhận được rồi, không sao. Đi đường vất vả rồi, lần sau cứ đi xe bác nha!','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_06','V216','Nguyễn Minh',6,'谢谢师傅，再见！','xiè xiè shī fù， zài jiàn！','Cảm ơn bác tài, chào bác ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT217','S7','Nhận phòng ký túc xá','Xuất trình giấy tờ, nhận phòng và chìa khóa','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V217','SIT217','P1','suon_se','ban_chinh_thuc','Xuất trình giấy tờ, nhận phòng và chìa khóa',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_01','V217','Nguyễn Minh',1,'老师您好，我是新来的留学生，今天来办理宿舍入住。','lǎo shī nín hǎo， wǒ shì xīn lái de liú xué shēng， jīn tiān lái bàn lǐ sù shè rù zhù。','Chào cô ạ, em là du học sinh mới, hôm nay em đến làm thủ tục nhận phòng ký túc xá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_02','V217','Tiền sảnh',2,'好的，请出示你的护照和入学通知书哦。','hǎo de， qǐng chū shì nǐ de hù zhào hé rù xué tōng zhī shū ó。','Được rồi, em cho cô xem hộ chiếu và giấy báo nhập học nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_03','V217','Nguyễn Minh',3,'好的，这是我的证件和录取文件，您看一下。','hǎo de， zhè shì wǒ de zhèng jiàn hé lù qǔ wén jiàn， nín kàn yī xià。','Dạ vâng, đây là giấy tờ và giấy báo trúng tuyển của em, cô xem giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_04','V217','Tiền sảnh',4,'信息核对无误，这是你的宿舍钥匙和门禁卡。','xìn xī hé duì wú wù， zhè shì nǐ de sù shè yào shi hé mén jìn kǎ。','Thông tin khớp rồi, đây là chìa khóa phòng và thẻ ra vào của em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_05','V217','Nguyễn Minh',5,'请问我的宿舍是几楼几号呀？','qǐng wèn wǒ de sù shè shì jǐ lóu jǐ hào ya？','Cô ơi cho em hỏi phòng em ở tầng mấy, số mấy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_06','V217','Tiền sảnh',6,'四楼408室，单人留学生宿舍，条件还不错呢。','sì lóu 408 shì， dān rén liú xué shēng sù shè， tiáo jiàn hái bú cuò ne。','Tầng 4, phòng 408, phòng đơn dành cho du học sinh, điều kiện cũng ổn đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_07','V217','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn cô nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT218','S7','Ký hợp đồng ở ký túc xá','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V218','SIT218','P1','suon_se','ban_chinh_thuc','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_01','V218','Tiền sảnh',1,'这是留学生住宿合同，你仔细看一下条款哦。','zhè shì liú xué shēng zhù sù hé tóng， nǐ zǐ xì kàn yī xià tiáo kuǎn ó。','Đây là hợp đồng ở ký túc xá dành cho du học sinh, em xem kỹ các điều khoản nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_02','V218','Nguyễn Minh',2,'好的，请问主要是住宿规定和缴费事项吧？','hǎo de， qǐng wèn zhǔ yào shì zhù sù guī dìng hé jiǎo fèi shì xiàng ba？','Dạ vâng, chủ yếu là quy định ở và các khoản phí phải nộp đúng không cô?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_03','V218','Tiền sảnh',3,'对的，还有作息时间、宿舍安全的相关要求呢。','duì de， hái yǒu zuò xī shí jiān、 sù shè ān quán de xiāng guān yāo qiú ne。','Đúng vậy, còn có giờ giấc sinh hoạt và các yêu cầu về an toàn ký túc xá nữa nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_04','V218','Nguyễn Minh',4,'我看完了，没有疑问，可以签字了吗？','wǒ kàn wán le， méi yǒu yí wèn， kě yǐ qiān zì le ma？','Em xem xong rồi, không có thắc mắc gì, giờ em ký được chưa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_05','V218','Tiền sảnh',5,'可以的，在这里签上你的中文或英文姓名就行。','kě yǐ de， zài zhè lǐ qiān shàng nǐ de zhōng wén huò yīng wén xìng míng jiù xíng。','Được rồi, em ký tên tiếng Trung hoặc tiếng Anh vào đây là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_06','V218','Nguyễn Minh',6,'好的，我签好了，交给您。','hǎo de， wǒ qiān hǎo le， jiāo gěi nín。','Dạ vâng, em ký xong rồi, gửi lại cô đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_07','V218','Tiền sảnh',7,'手续办完，祝你入住愉快！','shǒu xù bàn wán， zhù nǐ rù zhù yú kuài！','Xong thủ tục rồi, chúc em ở vui vẻ nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT219','S7','Hỏi WiFi, phòng giặt, giờ đóng cửa ký túc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V219','SIT219','P1','suon_se','ban_chinh_thuc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_01','V219','Nguyễn Minh',1,'老师您好，我想咨询几个宿舍的相关问题可以吗？','lǎo shī nín hǎo， wǒ xiǎng zī xún jǐ gè sù shè de xiāng guān wèn tí kě yǐ ma？','Chào cô ạ, em muốn hỏi mấy vấn đề về ký túc xá được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_02','V219','Tiền sảnh',2,'当然可以，你尽管问哈。','dāng rán kě yǐ， nǐ jǐn guǎn wèn hā。','Được chứ, em cứ hỏi thoải mái đi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_03','V219','Nguyễn Minh',3,'请问宿舍WiFi密码是多少？洗衣房在哪个位置啊？','qǐng wèn sù shè WiFi mì mǎ shì duō shǎo？ xǐ yī fáng zài nǎ ge wèi zhì a？','Cho em hỏi mật khẩu WiFi ký túc xá là gì ạ? Phòng giặt ở đâu vậy cô?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_04','V219','Tiền sảnh',4,'WiFi密码贴在房门背后，洗衣房在二楼楼梯口呢。','WiFi mì mǎ tiē zài fáng mén bèi hòu， xǐ yī fáng zài èr lóu lóu tī kǒu ne。','Mật khẩu WiFi dán ở mặt sau cửa phòng, phòng giặt ở đầu cầu thang tầng 2 nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_05','V219','Nguyễn Minh',5,'那宿舍门禁的开关时间是几点呀？','nà sù shè mén jìn de kāi guān shí jiān shì jǐ diǎn ya？','Vậy cửa ký túc xá mở và đóng vào giờ nào ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_06','V219','Tiền sảnh',6,'早上六点开门，晚上十一点关门，记得按时回寝哦。','zǎo shàng liù diǎn kāi mén， wǎn shàng shí yì diǎn guān mén， jì de àn shí huí qǐn ó。','Sáng 6 giờ mở cửa, tối 11 giờ đóng cửa, nhớ về phòng đúng giờ đấy nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_07','V219','Nguyễn Minh',7,'好的，我都记住了，谢谢您！','hǎo de， wǒ dōu jì zhù le， xiè xiè nín！','Dạ em nhớ hết rồi ạ, em cảm ơn cô!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT220','S7','Báo hỏng đèn phòng','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V220','SIT220','P1','that_bai_nhe','tuy_y','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_01','V220','Nguyễn Minh',1,'阿姨您好，我是408宿舍的同学，房间的顶灯不亮了。','ā yí nín hǎo， wǒ shì 408 sù shè de tóng xué， fáng jiān de dǐng dēng bù liàng le。','Cô ơi, em là sinh viên phòng 408, đèn trần phòng em không sáng nữa rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_02','V220','Quản lý',2,'是完全不亮，还是一闪一闪的呀？','shì wán quán bù liàng， hái shì yī shǎn yī shǎn de ya？','Là tắt hẳn luôn hay chớp chớp vậy con?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_03','V220','Nguyễn Minh',3,'完全打不开，应该是坏掉了呢。','wán quán dǎ bù kāi， yīng gāi shì huài diào le ne。','Tắt hẳn luôn ạ, chắc là hỏng rồi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_04','V220','Quản lý',4,'好的，我帮你登记报修，维修师傅明天上午过来修哈。','hǎo de， wǒ bāng nǐ dēng jì bào xiū， wéi xiū shī fù míng tiān shàng wǔ guò lái xiū hā。','Được rồi, cô ghi báo sửa giúp con, sáng mai thợ sẽ qua sửa nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_05','V220','Nguyễn Minh',5,'好的，今晚只能先开台灯了，麻烦阿姨啦！','hǎo de， jīn wǎn zhǐ néng xiān kāi tái dēng le， má fán ā yí la！','Dạ vâng, tối nay con đành bật đèn bàn tạm vậy, phiền cô quá!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_06','V220','Quản lý',6,'没事的，小事而已，明天肯定修好。','méi shì de， xiǎo shì ér yǐ， míng tiān kěn dìng xiū hǎo。','Không sao đâu, chuyện nhỏ thôi, mai chắc chắn sửa xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT221','S6','Mở tài khoản ngân hàng, lấy số','Lấy số thứ tự và điền đơn mở tài khoản','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V221','SIT221','P1','suon_se','chinh_thuc','Lấy số thứ tự và điền đơn mở tài khoản',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_01','V221','Nguyễn Minh',1,'您好，我想办理银行卡开户业务，请问怎么操作？','nín hǎo， wǒ xiǎng bàn lǐ yín háng kǎ kāi hù yè wù， qǐng wèn zěn me cāo zuò？','Chào anh/chị, tôi muốn làm thủ tục mở thẻ ngân hàng, xin hỏi cần làm như thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_02','V221','Quản lý sảnh',2,'您好，先在取号机取个排队号，再填写这份开户申请表哦。','nín hǎo， xiān zài qǔ hào jī qǔ gè pái duì hào， zài tián xiě zhè fèn kāi hù shēn qǐng biǎo ó。','Chào anh/chị, trước tiên anh/chị lấy số thứ tự ở máy lấy số, sau đó điền vào phiếu đăng ký mở tài khoản này ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_03','V221','Nguyễn Minh',3,'好的，表格上的信息我都如实填写就可以吧？','hǎo de， biǎo gé shàng de xìn xī wǒ dōu rú shí tián xiě jiù kě yǐ ba？','Vâng, thông tin trên phiếu tôi cứ điền đúng theo giấy tờ thật là được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_04','V221','Quản lý sảnh',4,'对的，姓名、证件信息、住址全部填完整就行。','duì de， xìng míng、 zhèng jiàn xìn xī、 zhù zhǐ quán bù tián wán zhěng jiù xíng。','Đúng vậy, họ tên, thông tin giấy tờ, địa chỉ cứ điền đầy đủ là được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_05','V221','Nguyễn Minh',5,'表格填好了，号也取到了，接下来等待叫号吗？','biǎo gé tián hǎo le， hào yě qǔ dào le， jiē xià lái děng dài jiào hào ma？','Tôi điền xong phiếu rồi, cũng đã lấy số rồi, tiếp theo là chờ gọi số phải không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_06','V221','Quản lý sảnh',6,'是的，轮到你的时候直接去柜台办理即可。','shì de， lún dào nǐ de shí hòu zhí jiē qù guì tái bàn lǐ jí kě。','Vâng đúng vậy, đến lượt anh/chị thì ra quầy làm thủ tục là được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_07','V221','Nguyễn Minh',7,'好的，谢谢您的指导！','hǎo de， xiè xiè nín de zhǐ dǎo！','Vâng, cảm ơn anh/chị đã hướng dẫn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT222','S6','Xuất trình giấy tờ mở thẻ ngân hàng','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V222','SIT222','P1','twist','chinh_thuc','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_01','V222','Nhân viên',1,'您好，请问办理什么业务？','nín hǎo， qǐng wèn bàn lǐ shén me yè wù？','Chào anh/chị, anh/chị muốn làm thủ tục gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_02','V222','Nguyễn Minh',2,'您好，我是留学生，想办理储蓄卡开户。','nín hǎo， wǒ shì liú xué shēng， xiǎng bàn lǐ chǔ xù kǎ kāi hù。','Chào anh/chị, tôi là du học sinh, muốn làm thủ tục mở thẻ tiết kiệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_03','V222','Nhân viên',3,'麻烦出示你的护照、签证和学校在读证明哦。','má fán chū shì nǐ de hù zhào、 qiān zhèng hé xué xiào zài dú zhèng míng ó。','Phiền anh/chị xuất trình hộ chiếu, visa và giấy xác nhận đang học ở trường ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_04','V222','Nguyễn Minh',4,'证件都在这里，在读证明我打印的黑白版可以吗？','zhèng jiàn dōu zài zhè lǐ， zài dú zhèng míng wǒ dǎ yìn de hēi bái bǎn kě yǐ ma？','Giấy tờ tôi để đây cả rồi, giấy xác nhận đang học tôi in bản đen trắng có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_05','V222','Nhân viên',5,'可以的，黑白有效，我帮你录入系统信息。','kě yǐ de， hēi bái yǒu xiào， wǒ bāng nǐ lù rù xì tǒng xìn xī。','Được ạ, bản đen trắng vẫn có giá trị, tôi nhập thông tin vào hệ thống cho anh/chị nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_06','V222','Nguyễn Minh',6,'好的，辛苦您了！大概多久能办好呀？','hǎo de， xīn kǔ nín le！ dà gài duō jiǔ néng bàn hǎo ya？','Vâng, cảm ơn anh/chị đã vất vả! Khoảng bao lâu thì xong được ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_07','V222','Nhân viên',7,'很快的，三分钟就能完成开卡流程。','hěn kuài de， sān fēn zhōng jiù néng wán chéng kāi kǎ liú chéng。','Nhanh thôi ạ, khoảng ba phút là hoàn tất thủ tục mở thẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT223','S6','Kích hoạt thẻ ngân hàng mới','Đổi mật khẩu ban đầu để kích hoạt thẻ','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V223','SIT223','P1','suon_se','chinh_thuc','Đổi mật khẩu ban đầu để kích hoạt thẻ',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_01','V223','Nhân viên',1,'银行卡已经办好了，需要现场激活修改初始密码哦。','yín háng kǎ yǐ jīng bàn hǎo le， xū yào xiàn chǎng jī huó xiū gǎi chū shǐ mì mǎ ó。','Thẻ ngân hàng đã làm xong rồi, anh/chị cần kích hoạt tại chỗ và đổi mật khẩu ban đầu ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_02','V223','Nguyễn Minh',2,'好的，请问我怎么操作呢？我不太会用机器。','hǎo de， qǐng wèn wǒ zěn me cāo zuò ne？ wǒ bù tài huì yòng jī qì。','Vâng, xin hỏi tôi phải làm như thế nào ạ? Tôi không rành dùng máy lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_03','V223','Nhân viên',3,'没关系，我一步步教你，先输入初始密码，再设置新密码。','méi guān xì， wǒ yí bù bù jiāo nǐ， xiān shū rù chū shǐ mì mǎ， zài shè zhì xīn mì mǎ。','Không sao ạ, tôi sẽ hướng dẫn từng bước, trước tiên nhập mật khẩu ban đầu, sau đó đặt mật khẩu mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_04','V223','Nguyễn Minh',4,'好，我设置好了，这样就激活成功了吧？','hǎo， wǒ shè zhì hǎo le， zhè yàng jiù jī huó chéng gōng le ba？','Vâng, tôi đặt xong rồi, vậy là kích hoạt thành công rồi phải không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_05','V223','Nhân viên',5,'对的，现在可以正常存取款、扫码支付了。','duì de， xiàn zài kě yǐ zhèng cháng cún qǔ kuǎn、 sǎo mǎ zhī fù le。','Đúng vậy, bây giờ anh/chị có thể gửi rút tiền, quét mã thanh toán bình thường rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_06','V223','Nguyễn Minh',6,'太好了，非常感谢您的帮助！','tài hǎo le， fēi cháng gǎn xiè nín de bāng zhù！','Tuyệt quá, cảm ơn anh/chị đã giúp đỡ nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT224','S5','Đăng ký thanh toán điện tử, xác thực danh tính','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V224','SIT224','P1','suon_se','tuy_y','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_01','V224','Nguyễn Minh',1,'小杨，我想注册微信支付，还要实名认证对吧？','xiǎo yáng， wǒ xiǎng zhù cè wēi xìn zhī fù， hái yào shí míng rèn zhèng duì ba？','Tiểu Dương ơi, tớ muốn đăng ký WeChat Pay, còn phải xác thực danh tính thật đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_02','V224','Bạn (Tiểu Dương)',2,'对呀，不认证没法扫码付钱、转账的。','duì ya， bù rèn zhèng méi fǎ sǎo mǎ fù qián、 zhuǎn zhàng de。','Đúng rồi đó, không xác thực thì không quét mã trả tiền, chuyển khoản được đâu.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_03','V224','Nguyễn Minh',3,'那留学生用护照也能认证吗？我没有身份证呢。','nà liú xué shēng yòng hù zhào yě néng rèn zhèng ma？ wǒ méi yǒu shēn fèn zhèng ne。','Vậy du học sinh dùng hộ chiếu cũng xác thực được à? Tớ đâu có chứng minh thư đâu.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_04','V224','Bạn (Tiểu Dương)',4,'可以的！直接选择护照认证，按提示上传照片就行啦。','kě yǐ de！ zhí jiē xuǎn zé hù zhào rèn zhèng， àn tí shì shàng chuán zhào piān jiù xíng la。','Được chứ! Cứ chọn xác thực bằng hộ chiếu, làm theo hướng dẫn tải ảnh lên là xong ấy mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_05','V224','Nguyễn Minh',5,'原来这么简单，我马上试试！','yuán lái zhè me jiǎn dān， wǒ mǎ shàng shì shì！','Hóa ra đơn giản vậy thôi à, tớ thử ngay đây!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_06','V224','Bạn (Tiểu Dương)',6,'弄不懂随时喊我，我教你哈。','nòng bù dǒng suí shí hǎn wǒ， wǒ jiāo nǐ hā。','Không hiểu gì cứ gọi tớ, tớ chỉ cho.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT225','S11','Thanh toán quét mã ở cửa hàng tiện lợi','Thanh toán nhanh bằng ví điện tử khi mua đồ','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V225','SIT225','P1','suon_se','tuy_y','Thanh toán nhanh bằng ví điện tử khi mua đồ',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_01','V225','Nhân viên',1,'一共二十五元，你扫码支付就可以啦。','yī gòng èr shí wǔ yuán， nǐ sǎo mǎ zhī fù jiù kě yǐ la。','Tổng cộng hai mươi lăm tệ, bạn quét mã thanh toán là được nha.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_02','V225','Nguyễn Minh',2,'好的，我打开微信二维码，您扫我吧？','hǎo de， wǒ dǎ kāi wēi xìn èr wéi mǎ， nín sǎo wǒ ba？','Dạ được, em mở mã QR WeChat, chị quét cho em nhé?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_03','V225','Nhân viên',3,'可以的，或者你扫收银台的码也行哦。','kě yǐ de， huò zhě nǐ sǎo shōu yín tái de mǎ yě xíng ó。','Được đó, hoặc em quét mã ở quầy thu ngân cũng được nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_04','V225','Nguyễn Minh',4,'我扫好了，支付成功了，您看一下！','wǒ sǎo hǎo le， zhī fù chéng gōng le， nín kàn yī xià！','Em quét xong rồi, thanh toán thành công rồi ạ, chị xem thử nha!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_05','V225','Nhân viên',5,'收到啦，没问题！东西拿好，慢走哈。','shōu dào la， méi wèn tí！ dōng xī ná hǎo， màn zǒu hā。','Nhận được rồi, không có vấn đề gì! Cầm đồ cẩn thận, đi cẩn thận nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_06','V225','Nguyễn Minh',6,'谢谢！','xiè xiè！','Cảm ơn chị!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT226','S8','Báo danh văn phòng sinh viên quốc tế','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V226','SIT226','P1','suon_se','ban_chinh_thuc','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_01','V226','Nguyễn Minh',1,'老师您好，我是新生阮明，今天来国际学生办公室报到。','lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， jīn tiān lái guó jì xué shēng bàn gōng shì bào dào。','Chào thầy/cô, em là sinh viên mới Nguyễn Minh, hôm nay em đến văn phòng sinh viên quốc tế để báo danh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_02','V226','Cán bộ',2,'你好！麻烦提交一下你的护照、签证和录取通知书哦。','nǐ hǎo！ má fán tí jiāo yī xià nǐ de hù zhào、 qiān zhèng hé lù qǔ tōng zhī shū ó。','Chào em! Phiền em nộp hộ passport, visa và giấy báo nhập học nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_03','V226','Nguyễn Minh',3,'好的，这是我的全部材料，您查收一下。','hǎo de， zhè shì wǒ de quán bù cái liào， nín chá shōu yī xià。','Dạ vâng, đây là toàn bộ giấy tờ của em, thầy/cô kiểm tra giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_04','V226','Cán bộ',4,'材料齐全无误，这边帮你完成新生注册啦。','cái liào qí quán wú wù， zhè biān bāng nǐ wán chéng xīn shēng zhù cè la。','Giấy tờ đầy đủ và chính xác, để đây làm thủ tục đăng ký sinh viên mới cho em nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_05','V226','Nguyễn Minh',5,'请问接下来还有其他报到流程吗？','qǐng wèn jiē xià lái hái yǒu qí tā bào dào liú chéng ma？','Dạ cho em hỏi tiếp theo còn quy trình báo danh nào khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_06','V226','Cán bộ',6,'基本完成了，后续选课、体检通知会统一发群里呢。','jī běn wán chéng le， hòu xù xuǎn kè、 tǐ jiǎn tōng zhī huì tǒng yī fā qún lǐ ne。','Cơ bản là xong rồi, thông báo chọn môn và khám sức khỏe sau này sẽ gửi chung trong nhóm nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_07','V226','Nguyễn Minh',7,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Dạ vâng, em cảm ơn thầy/cô ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT227','S8','Thiếu giấy tờ, xin nộp bổ sung','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V227','SIT227','P1','twist','ban_chinh_thuc','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','新生报到材料缺失，多数学校允许限期补交，态度诚恳致歉即可，无需过度紧张；线上截图、电子版打印件大多不具备归档效力，必须纸质复印件。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_01','V227','老师',1,'同学你先坐，我们核对一下新生报到需要提交的全套材料。','tóng xué nǐ xiān zuò， wǒ men hé duì yī xià xīn shēng bào dào xū yào tí jiāo de quán tào cái liào。','Em ngồi trước đi, chúng ta cùng đối chiếu lại toàn bộ giấy tờ cần nộp khi báo danh sinh viên mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_02','V227','阮明',2,'好的老师，我把手里的文件都拿出来给您核对。','hǎo de lǎo shī， wǒ bǎ shǒu lǐ de wén jiàn dōu ná chū lái gěi nín hé duì。','Dạ vâng thầy/cô, em lấy hết giấy tờ đang có ra để thầy/cô kiểm tra ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_03','V227','老师',3,'毕业证复印件、签证页、体检表都齐了，还差一份疫苗接种证明，你带过来了吗？','bì yè zhèng fù yìn jiàn、 qiān zhèng yè、 tǐ jiǎn biǎo dōu qí le， hái chà yī fèn yì miáo jiē zhǒng zhèng míng， nǐ dài guò lái le ma？','Bản sao bằng tốt nghiệp, trang visa, giấy khám sức khỏe đều đủ rồi, còn thiếu giấy chứng nhận tiêm vaccine, em có mang theo không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_04','V227','阮明',4,'不好意思老师，出门收拾行李的时候漏掉这份材料，我完全忘记带了，非常抱歉。','bù hǎo yì sī lǎo shī， chū mén shōu shí xíng lǐ de shí hòu lòu diào zhè fèn cái liào， wǒ wán quán wàng jì dài le， fēi cháng bào qiàn。','Em xin lỗi thầy/cô, lúc thu dọn hành lý em đã sót mất giấy tờ này, em hoàn toàn quên mang theo, em thật sự rất xin lỗi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_05','V227','老师',5,'没事的，不用紧张，很多新生都会出现材料遗漏的情况。','méi shì de， bù yòng jǐn zhāng， hěn duō xīn shēng dōu huì chū xiàn cái liào yí lòu de qíng kuàng。','Không sao đâu, em đừng căng thẳng, rất nhiều sinh viên mới cũng bị thiếu giấy tờ như vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_06','V227','阮明',6,'我心里特别着急，怕耽误今天的新生登记流程，影响后续选课住宿。','wǒ xīn lǐ tè bié zháo jí， pà dān wù jīn tiān de xīn shēng dēng jì liú chéng， yǐng xiǎng hòu xù xuǎn kè zhù sù。','Trong lòng em rất lo lắng, sợ làm chậm trễ quy trình đăng ký sinh viên mới hôm nay, ảnh hưởng đến việc chọn môn và ở ký túc xá sau này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_07','V227','老师',7,'我先跟你说明学校的规定，所有材料必须完整归档，不能长期缺件。','wǒ xiān gēn nǐ shuō míng xué xiào de guī dìng， suǒ yǒu cái liào bì xū wán zhěng guī dàng， bù néng cháng qī quē jiàn。','Thầy/cô nói trước cho em rõ quy định của trường, tất cả giấy tờ đều phải nộp đầy đủ, không được thiếu kéo dài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_08','V227','阮明',8,'那请问我明天补交可以吗？明天补交完整不会影响我的新生报到手续吧？','nà qǐng wèn wǒ míng tiān bǔ jiāo kě yǐ ma？ míng tiān bǔ jiāo wán zhěng bú huì yǐng xiǎng wǒ de xīn shēng bào dào shǒu xù ba？','Vậy cho em hỏi ngày mai em nộp bổ sung có được không ạ? Ngày mai nộp đầy đủ thì có ảnh hưởng đến thủ tục báo danh sinh viên mới của em không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_09','V227','老师',9,'正常截止时间是今天下午五点，严格来说逾期不予受理，不过可以给你特殊放宽一天。','zhèng cháng jié zhǐ shí jiān shì jīn tiān xià wǔ wǔ diǎn， yán gé lái shuō yú qī bù yǔ shòu lǐ， bù guò kě yǐ gěi nǐ tè shū fàng kuān yī tiān。','Thời hạn bình thường là năm giờ chiều hôm nay, nói nghiêm túc thì quá hạn sẽ không được tiếp nhận nữa, nhưng thầy/cô có thể châm chước cho em thêm một ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_10','V227','阮明',10,'太感谢老师愿意通融，我明天一早就回家找出证明，复印完整送过来。','tài gǎn xiè lǎo shī yuàn yì tōng róng， wǒ míng tiān yī zǎo jiù huí jiā zhǎo chū zhèng míng， fù yìn wán zhěng sòng guò lái。','Em cảm ơn thầy/cô rất nhiều vì đã thông cảm, sáng mai em sẽ về nhà tìm giấy chứng nhận ngay, photo đầy đủ rồi mang đến ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_11','V227','老师',11,'记住一定要带纸质原件复印件，照片截图打印出来是不被认可的。','jì zhù yí dìng yào dài zhǐ zhì yuán jiàn fù yìn jiàn， zhào piān jié tú dǎ yìn chū lái shì bù bèi rèn kě de。','Em nhớ là phải mang bản gốc giấy và bản photo nhé, ảnh chụp màn hình in ra thì không được chấp nhận đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_12','V227','阮明',12,'我记下这条要求了，明天一定准备规范的纸质文件。','wǒ jì xià zhè tiáo yāo qiú le， míng tiān yí dìng zhǔn bèi guī fàn de zhǐ zhì wén jiàn。','Em ghi nhớ yêu cầu này rồi ạ, ngày mai em nhất định chuẩn bị giấy tờ đúng chuẩn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_13','V227','老师',13,'行，我先把你现有材料临时存档，等你补齐再统一录入系统。','xíng， wǒ xiān bǎ nǐ xiàn yǒu cái liào lín shí cún dàng， děng nǐ bǔ qí zài tǒng yī lù rù xì tǒng。','Được rồi, thầy/cô sẽ lưu tạm hồ sơ hiện có của em, đợi em bổ sung đủ rồi sẽ nhập vào hệ thống luôn thể.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_14','V227','阮明',14,'给老师增添额外工作量实在不好意思，我明天准时送来！','gěi lǎo shī zēng tiān é wài gōng zuò liàng shí zài bù hǎo yì sī， wǒ míng tiān zhǔn shí sòng lái！','Em thật sự áy náy vì làm phiền thầy/cô thêm việc, ngày mai em sẽ mang đến đúng giờ ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT228','S9','Chọn môn, lớp đã đầy phải đổi lớp','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V228','SIT228','P1','that_bai_nhe','ban_chinh_thuc','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','Lớp học đông theo nguyên tắc đăng ký trước được trước; lớp đầy thì chỉ có thể đổi sang lớp/giờ khác, không thể xin thêm suất.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_01','V228','Nguyễn Minh',1,'老师您好，我想选的汉语课已经显示满员了。','lǎo shī nín hǎo， wǒ xiǎng xuǎn de hàn yǔ kè yǐ jīng xiǎn shì mǎn yuán le。','Chào thầy/cô, môn tiếng Hán em muốn chọn hiện đang báo là đã đầy chỗ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_02','V228','Giáo vụ',2,'是的，这个热门班级名额已经抢完了呢。','shì de， zhè ge rè mén bān jí míng é yǐ jīng qiǎng wán le ne。','Đúng vậy, lớp này là lớp hot nên số lượng đã bị đăng ký hết rồi đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_03','V228','Nguyễn Minh',3,'那请问我能不能换到其他时间段的班级呀？','nà qǐng wèn wǒ néng bù néng huàn dào qí tā shí jiān duàn de bān jí ya？','Vậy cho em hỏi em có thể đổi sang lớp ở khung giờ khác được không ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_04','V228','Giáo vụ',4,'可以的，还有周三下午的班级有空位，内容是一样的。','kě yǐ de， hái yǒu zhōu sān xià wǔ de bān jí yǒu kòng wèi， nèi róng shì yī yàng de。','Được chứ, còn lớp chiều thứ Tư vẫn còn chỗ trống, nội dung học là như nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_05','V228','Nguyễn Minh',5,'那就太好了！我直接改选这个班级就可以吧？','nà jiù tài hǎo le！ wǒ zhí jiē gǎi xuǎn zhè ge bān jí jiù kě yǐ ba？','Vậy thì tốt quá ạ! Em chỉ cần đổi trực tiếp sang lớp này là được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_06','V228','Giáo vụ',6,'对的，系统直接操作就行，不用额外申请。','duì de， xì tǒng zhí jiē cāo zuò jiù xíng， bù yòng é wài shēn qǐng。','Đúng rồi, em cứ thao tác trực tiếp trên hệ thống là được, không cần làm đơn xin thêm gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT229','S9','Gặp cố vấn học tập lần đầu','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V229','SIT229','P1','suon_se','ban_chinh_thuc','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','Giảng viên hướng dẫn học tập sẵn sàng tư vấn chọn môn; sinh viên nên chủ động hỏi ngay từ buổi gặp đầu tiên.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_01','V229','Nguyễn Minh',1,'张老师您好，我是新生阮明，来自越南，很高兴成为您的学生。','zhāng lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， lái zì yuè nán， hěn gāo xìng chéng wéi nín de xué shēng。','Chào cô Trương, em là sinh viên mới Nguyễn Minh, đến từ Việt Nam, em rất vui được làm học trò của cô ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_02','V229','Cố vấn',2,'你好！欢迎你来本校就读，适应这边的生活了吗？','nǐ hǎo！ huān yíng nǐ lái běn xiào jiù dú， shì yìng zhè biān de shēng huó le ma？','Chào em! Chào mừng em đến học tại trường mình, em đã quen với cuộc sống ở đây chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_03','V229','Nguyễn Minh',3,'慢慢适应啦，我想咨询一下，本专业选课有什么侧重点呢？','màn màn shì yìng la， wǒ xiǎng zī xún yī xià， běn zhuān yè xuǎn kè yǒu shén me cè zhòng diǎn ne？','Em đang dần quen ạ, em muốn hỏi cô một chút, việc chọn môn của chuyên ngành mình có trọng tâm gì không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_04','V229','Cố vấn',4,'优先选专业基础课，选修课可以选贴合国际贸易的课程哦。','yōu xiān xuǎn zhuān yè jī chǔ kè， xuǎn xiū kè kě yǐ xuǎn tiē hé guó jì mào yì de kè chéng ó。','Ưu tiên chọn các môn cơ sở chuyên ngành trước, môn tự chọn thì em có thể chọn những môn sát với ngành thương mại quốc tế nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_05','V229','Nguyễn Minh',5,'好的，那大一需要多选公共课吗？','hǎo de， nà dà yī xū yào duō xuǎn gōng gòng kè ma？','Dạ vâng, vậy năm nhất có cần chọn nhiều môn đại cương không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_06','V229','Cố vấn',6,'适当选择即可，不用选课太多，避免压力过大哈。','shì dàng xuǎn zé jí kě， bù yòng xuǎn kè tài duō， bì miǎn yā lì guò dà hā。','Chọn vừa phải thôi, không cần chọn quá nhiều môn, tránh áp lực quá lớn nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_07','V229','Nguyễn Minh',7,'我明白了，谢谢老师指导！','wǒ míng bái le， xiè xiè lǎo shī zhǐ dǎo！','Em hiểu rồi ạ, em cảm ơn cô đã hướng dẫn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT230','S9','Chụp ảnh làm thẻ sinh viên','Chụp ảnh đơn giản để làm thẻ sinh viên','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V230','SIT230','P1','suon_se','tuy_y','Chụp ảnh đơn giản để làm thẻ sinh viên',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_01','V230','Nhân viên',1,'同学，过来拍学生证照片啦。','tóng xué， guò lái pāi xué shēng zhèng zhào piān la。','Em ơi, qua đây chụp ảnh làm thẻ sinh viên nè.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_02','V230','Nguyễn Minh',2,'好的，请问拍照有什么要求吗？我不太清楚呢。','hǎo de， qǐng wèn pāi zhào yǒu shén me yāo qiú ma？ wǒ bù tài qīng chǔ ne。','Dạ vâng, cho em hỏi chụp ảnh có yêu cầu gì không ạ? Em chưa rõ lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_03','V230','Nhân viên',3,'很简单，不用戴帽子、墨镜，头发露出额头就行哈。','hěn jiǎn dān， bù yòng dài mào zi、 mò jìng， tóu fà lù chū é tóu jiù xíng hā。','Đơn giản lắm, không cần đội mũ, đeo kính râm, để lộ trán ra là được nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_04','V230','Nguyễn Minh',4,'好，我整理一下，这样可以了吧？','hǎo， wǒ zhěng lǐ yī xià， zhè yàng kě yǐ le ba？','Dạ, em chỉnh lại một chút, thế này được chưa ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_05','V230','Nhân viên',5,'可以！保持微笑，看镜头，马上就好。','kě yǐ！ bǎo chí wēi xiào， kàn jìng tóu， mǎ shàng jiù hǎo。','Được rồi! Giữ nụ cười, nhìn vào ống kính, xong ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_06','V230','Nguyễn Minh',6,'拍完就可以直接办理学生证了吗？','pāi wán jiù kě yǐ zhí jiē bàn lǐ xué shēng zhèng le ma？','Chụp xong là có thể làm thẻ sinh viên luôn được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_07','V230','Nhân viên',7,'对的，照片录入系统，一周后就能拿证啦。','duì de， zhào piān lù rù xì tǒng， yī zhōu hòu jiù néng ná zhèng la。','Đúng rồi, ảnh sẽ được nhập vào hệ thống, một tuần sau là lấy thẻ được nha.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT231','S9','Làm thẻ thư viện, mượn sách đầu tiên','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V231','SIT231','P1','suon_se','ban_chinh_thuc','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_01','V231','Nguyễn Minh',1,'老师您好，我是新生，想办理图书馆借书证。','lǎo shī nín hǎo， wǒ shì xīn shēng， xiǎng bàn lǐ tú shū guǎn jiè shū zhèng。','Chào thầy/cô, em là sinh viên mới, muốn làm thẻ thư viện để mượn sách ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_02','V231','Thủ thư',2,'好的，出示你的学生证就可以免费办理哦。','hǎo de， chū shì nǐ de xué shēng zhèng jiù kě yǐ miǎn fèi bàn lǐ ó。','Được, em xuất trình thẻ sinh viên là làm miễn phí được luôn nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_03','V231','Nguyễn Minh',3,'给您，办好之后一次可以借几本书呀？','gěi nín， bàn hǎo zhī hòu yī cì kě yǐ jiè jǐ běn shū ya？','Dạ gửi thầy/cô, làm xong rồi thì mỗi lần em được mượn mấy cuốn sách ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_04','V231','Thủ thư',4,'留学生一次可以借十本，借阅期限三十天呢。','liú xué shēng yī cì kě yǐ jiè shí běn， jiè yuè qī xiàn sān shí tiān ne。','Sinh viên nước ngoài mỗi lần được mượn mười cuốn, thời hạn mượn là ba mươi ngày đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_05','V231','Nguyễn Minh',5,'那我借这本汉语教材可以吧？','nà wǒ jiè zhè běn hàn yǔ jiào cái kě yǐ ba？','Vậy em mượn cuốn giáo trình tiếng Hán này được chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_06','V231','Thủ thư',6,'没问题，我帮你扫码登记，已经借阅成功啦。','méi wèn tí， wǒ bāng nǐ sǎo mǎ dēng jì， yǐ jīng jiè yuè chéng gōng la。','Không vấn đề gì, để cô quét mã đăng ký cho em, mượn thành công rồi nè.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_07','V231','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn cô rất nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT232','S9','Đổi mật khẩu email trường','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V232','SIT232','P1','twist','tuy_y','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','Tài khoản hệ thống trường phân biệt chữ hoa/thường trong mật khẩu; cần đổi mật khẩu ban đầu ngay lần đăng nhập đầu.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_01','V232','Nguyễn Minh',1,'宇哥，学校邮箱我登不上，初始密码不对呢。','yǔ gē， xué xiào yóu xiāng wǒ dēng bù shàng， chū shǐ mì mǎ bú duì ne。','Anh Vũ ơi, em không đăng nhập được email trường, mật khẩu ban đầu bị sai rồi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_02','V232','Trần Vũ',2,'是吗？你是不是输错大小写了呀？','shì ma？ nǐ shì bú shì shū cuò dà xiǎo xiě le ya？','Vậy hả? Có phải em gõ nhầm chữ hoa chữ thường không đấy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_03','V232','Nguyễn Minh',3,'有可能！我一直没注意大小写区分。','yǒu kě néng！ wǒ yì zhí méi zhù yì dà xiǎo xiě qū fēn。','Có thể lắm! Em toàn không để ý phân biệt hoa thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_04','V232','Trần Vũ',4,'没事，我教你，重新输入区分大小写就能登上啦。','méi shì， wǒ jiāo nǐ， chóng xīn shū rù qū fēn dà xiǎo xiě jiù néng dēng shàng la。','Không sao, anh chỉ em, gõ lại phân biệt hoa thường cho đúng là đăng nhập được liền thôi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_05','V232','Nguyễn Minh',5,'登上了！接下来怎么修改密码呀？','dēng shàng le！ jiē xià lái zěn me xiū gǎi mì mǎ ya？','Đăng nhập được rồi! Tiếp theo làm sao để đổi mật khẩu vậy anh?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_06','V232','Trần Vũ',6,'在个人中心设置新密码，记得设置复杂一点哦。','zài gè rén zhōng xīn shè zhì xīn mì mǎ， jì de shè zhì fù zá yì diǎn ó。','Vào phần cài đặt cá nhân để đặt mật khẩu mới, nhớ đặt phức tạp một chút nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_07','V232','Nguyễn Minh',7,'好嘞，我马上改，太谢谢你啦！','hǎo lei， wǒ mǎ shàng gǎi， tài xiè xiè nǐ la！','Dạ được, em đổi ngay đây, cảm ơn anh nhiều lắm luôn!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT233','S9','Nộp bài trên LMS gặp lỗi hệ thống','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V233','SIT233','P1','that_bai_nhe','ban_chinh_thuc','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','Sự cố kỹ thuật trên hệ thống học tập thường được nhà trường tự động gia hạn, không cần làm đơn xin riêng.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_01','V233','Nguyễn Minh',1,'助教您好，我在教学平台提交作业，一直提交失败呢。','zhù jiào nín hǎo， wǒ zài jiào xué píng tái tí jiāo zuò yè， yì zhí tí jiāo shī bài ne。','Chào trợ giảng, em nộp bài trên nền tảng học tập mà cứ nộp không được ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_02','V233','Trợ giảng',2,'是文件上传不了，还是页面卡顿呀？','shì wén jiàn shàng chuán bù liǎo， hái shì yè miàn kǎ dùn ya？','Là không tải file lên được, hay là trang web bị đơ vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_03','V233','Nguyễn Minh',3,'页面一直加载，点提交没有任何反应。','yè miàn yì zhí jiā zài， diǎn tí jiāo méi yǒu rèn hé fǎn yìng。','Trang cứ load mãi, bấm nộp bài không thấy phản hồi gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_04','V233','Trợ giảng',4,'应该是平台晚间系统卡顿，今天很多同学都遇到了。','yīng gāi shì píng tái wǎn jiān xì tǒng kǎ dùn， jīn tiān hěn duō tóng xué dōu yù dào le。','Chắc là do hệ thống bị nghẽn vào buổi tối, hôm nay nhiều bạn cũng gặp tình trạng này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_05','V233','Nguyễn Minh',5,'那我的作业会不会逾期扣分啊？','nà wǒ de zuò yè huì bú huì yú qī kòu fēn a？','Vậy bài của em có bị trừ điểm vì nộp trễ không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_06','V233','Trợ giảng',6,'不会的，系统问题统一延后提交，明天早上再交就行哈。','bú huì de， xì tǒng wèn tí tǒng yī yán hòu tí jiāo， míng tiān zǎo shàng zài jiāo jiù xíng hā。','Không đâu, lỗi hệ thống thì được gia hạn nộp chung, mai sáng nộp lại là được nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_07','V233','Nguyễn Minh',7,'太好了，谢谢您告诉我！','tài hǎo le， xiè xiè nín gào sù wǒ！','May quá, cảm ơn thầy/cô đã báo cho em!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT234','S10','Hỏi phạm vi bảo hiểm y tế sinh viên','Hỏi rõ phạm vi được và không được bảo hiểm chi trả','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V234','SIT234','P1','suon_se','ban_chinh_thuc','Hỏi rõ phạm vi được và không được bảo hiểm chi trả',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_01','V234','Nguyễn Minh',1,'老师您好，我想咨询一下留学生医保的报销范围呢。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià liú xué shēng yī bǎo de bào xiāo fàn wéi ne。','Chào cán bộ, em muốn hỏi về phạm vi được bảo hiểm y tế sinh viên nước ngoài chi trả ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_02','V234','Cán bộ',2,'没问题，学校医保主要报销公立医院的门诊和住院费用哦。','méi wèn tí， xué xiào yī bǎo zhǔ yào bào xiāo gōng lì yī yuàn de mén zhěn hé zhù yuàn fèi yòng ó。','Không vấn đề gì, bảo hiểm của trường chủ yếu chi trả chi phí khám ngoại trú và nội trú ở bệnh viện công đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_03','V234','Nguyễn Minh',3,'那感冒、肠胃炎这类普通小病也能报销吧？','nà gǎn mào、 cháng wèi yán zhè lèi pǔ tōng xiǎo bìng yě néng bào xiāo ba？','Vậy những bệnh thông thường như cảm cúm, viêm dạ dày ruột cũng được chi trả chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_04','V234','Cán bộ',4,'可以的，常规疾病都在报销范围内，意外受伤也能理赔。','kě yǐ de， cháng guī jí bìng dōu zài bào xiāo fàn wéi nèi， yì wài shòu shāng yě néng lǐ péi。','Được chứ, các bệnh thông thường đều nằm trong phạm vi bảo hiểm, tai nạn cũng được bồi thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_05','V234','Nguyễn Minh',5,'请问有不能报销的项目吗？','qǐng wèn yǒu bù néng bào xiāo de xiàng mù ma？','Vậy có mục nào không được chi trả không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_06','V234','Cán bộ',6,'私立医院、美容整形、牙科美白这些是不报销的哈。','sī lì yī yuàn、 měi róng zhěng xíng、 yá kē měi bái zhè xiē shì bù bào xiāo de hā。','Bệnh viện tư, làm đẹp thẩm mỹ, tẩy trắng răng thì không được chi trả nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_07','V234','Nguyễn Minh',7,'我清楚了，谢谢老师详细讲解！','wǒ qīng chǔ le， xiè xiè lǎo shī xiáng xì jiǎng jiě！','Em hiểu rồi ạ, cảm ơn cán bộ đã giải thích chi tiết!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT235','S10','Khám sức khỏe nhập học','Lấy số và điền thông tin cá nhân trước khi khám','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V235','SIT235','P1','suon_se','ban_chinh_thuc','Lấy số và điền thông tin cá nhân trước khi khám','Khám sức khỏe đầu năm là yêu cầu bắt buộc với mọi sinh viên, không riêng sinh viên quốc tế; thông tin sẽ lưu vào hồ sơ sinh viên.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_01','V235','Nguyễn Minh',1,'您好，我是新生，过来做入学体检，请问怎么办理呀？','nín hǎo， wǒ shì xīn shēng， guò lái zuò rù xué tǐ jiǎn， qǐng wèn zěn me bàn lǐ ya？','Chào anh/chị, em là sinh viên mới, đến khám sức khỏe nhập học, cho em hỏi làm thủ tục thế nào ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_02','V235','Nhân viên',2,'先在自助机取个体检号，再填写这份个人信息表哦。','xiān zài zì zhù jī qǔ gè tǐ jiǎn hào， zài tián xiě zhè fèn gè rén xìn xī biǎo ó。','Em lấy số khám ở máy tự động trước, rồi điền vào tờ thông tin cá nhân này nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_03','V235','Nguyễn Minh',3,'好的，表格里的国籍和证件类型如实填写就可以吧？','hǎo de， biǎo gé lǐ de guó jí hé zhèng jiàn lèi xíng rú shí tián xiě jiù kě yǐ ba？','Dạ, phần quốc tịch và loại giấy tờ trong biểu mẫu cứ điền đúng sự thật là được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_04','V235','Nhân viên',4,'对的，信息全部填准确，避免体检单出错呢。','duì de， xìn xī quán bù tián zhǔn què， bì miǎn tǐ jiǎn dān chū cuò ne。','Đúng rồi, thông tin phải điền chính xác hết, tránh để phiếu khám bị sai đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_05','V235','Nguyễn Minh',5,'表格填完、号也取好了，接下来做什么？','biǎo gé tián wán、 hào yě qǔ hǎo le， jiē xià lái zuò shén me？','Em điền xong biểu mẫu và lấy số rồi, tiếp theo làm gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_06','V235','Nhân viên',6,'拿着单据依次做各项检查就行，流程很简单的哈。','ná zhe dān jù yī cì zuò gè xiàng jiǎn chá jiù xíng， liú chéng hěn jiǎn dān de hā。','Em cầm phiếu đi khám lần lượt từng mục là được, quy trình đơn giản lắm nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_07','V235','Nguyễn Minh',7,'明白了，谢谢您！','míng bái le， xiè xiè nín！','Em hiểu rồi ạ, cảm ơn anh/chị!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT236','S2','Tắc đường, xin đổi lộ trình vì sắp trễ học','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V236','SIT236','P1','twist','tuy_y','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','早高峰城市主干道普遍拥堵，乘客可礼貌请求司机绕路，司机一般会主动配合，不会额外加价；支路人流密集，司机通常会减速慢行保障安全。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_01','V236','司机',1,'小伙子，跟你说一下，前方主干道早高峰全线拥堵，车速特别慢哦。','xiǎo huǒ zi， gēn nǐ shuō yī xià， qián fāng zhǔ gàn dào zǎo gāo fēng quán xiàn yōng dǔ， chē sù tè bié màn ó。','Cậu ơi, nói cho cậu biết, đường lớn phía trước giờ cao điểm sáng đang kẹt cứng cả tuyến, xe chạy chậm lắm đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_02','V236','阮明',2,'师傅，我上午有专业课，还有十分钟就要上课，再堵下去肯定要迟到了呢！','shī fù， wǒ shàng wǔ yǒu zhuān yè kè， hái yǒu shí fēn zhōng jiù yào shàng kè， zài dǔ xià qù kěn dìng yào chí dào le ne！','Bác tài ơi, sáng nay em có tiết chuyên ngành, còn mười phút nữa là vào học rồi, kẹt thêm chắc trễ học mất!','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_03','V236','司机',3,'我打开导航看看路况，主干道三条车道全部堵死，短时间疏通不开。','wǒ dǎ kāi dǎo háng kàn kàn lù kuàng， zhǔ gàn dào sān tiáo chē dào quán bù dǔ sǐ， duǎn shí jiān shū tōng bù kāi。','Để tôi mở bản đồ xem tình hình đường xá, ba làn đường chính đều kẹt cứng, khó thông trong thời gian ngắn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_04','V236','阮明',4,'那有没有别的小路可以绕一下，只要能赶在上课前到学校就行呀？','nà yǒu méi yǒu bié de xiǎo lù kě yǐ rào yī xià， zhǐ yào néng gǎn zài shàng kè qián dào xué xiào jiù xíng ya？','Vậy có đường nhỏ nào đi vòng được không, miễn kịp đến trường trước giờ học là được ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_05','V236','司机',5,'倒是有一条居民区小路能绕行，唯一问题是路程会多两公里，稍微远一点。','dǎo shì yǒu yī tiáo jū mín qū xiǎo lù néng rào xíng， wéi yī wèn tí shì lù chéng huì duō liǎng gōng lǐ， shāo wēi yuǎn yì diǎn。','Có một con đường nhỏ trong khu dân cư có thể đi vòng, chỉ có điều sẽ xa hơn hai cây số, hơi vòng vèo một chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_06','V236','阮明',6,'没关系的，多绕一点路完全没问题，只要别耽误上课就好，麻烦您绕路啦！','méi guān xì de， duō rào yì diǎn lù wán quán méi wèn tí， zhǐ yào bié dān wù shàng kè jiù hǎo， má fán nín rào lù la！','Không sao đâu ạ, đi vòng thêm chút cũng được, miễn đừng trễ học là được, phiền bác đi vòng giúp em nhé!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_07','V236','司机',7,'绕行小路里面行人、电动车多，车速提不上来，最多只能匀速慢慢开。','rào xíng xiǎo lù lǐ miàn xíng rén、 diàn dòng chē duō， chē sù tí bù shàng lái， zuì duō zhǐ néng yún sù màn màn kāi。','Đường nhỏ đi vòng đó nhiều người đi bộ với xe điện, xe không chạy nhanh được, chỉ có thể chạy đều đều thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_08','V236','阮明',8,'我能理解，安全第一，只要能避开主干道的长堵车我就很满足。','wǒ néng lǐ jiě， ān quán dì yī， zhǐ yào néng bì kāi zhǔ gàn dào de zhǎng dǔ chē wǒ jiù hěn mǎn zú。','Em hiểu mà, an toàn là trên hết, chỉ cần tránh được cảnh kẹt xe dài trên đường lớn là em thấy ổn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_09','V236','司机',9,'没问题，我现在立刻变道下高架，转入旁边的支路绕行。','méi wèn tí， wǒ xiàn zài lì kè biàn dào xià gāo jià， zhuǎn rù páng biān de zhī lù rào xíng。','Được rồi, giờ tôi chuyển làn xuống đường trên cao ngay, rẽ vào đường nhánh bên cạnh để đi vòng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_10','V236','阮明',10,'大概还需要几分钟能抵达学校校门，我心里好有个数。','dà gài hái xū yào jǐ fēn zhōng néng dǐ dá xué xiào xiào mén， wǒ xīn lǐ hǎo yǒu gè shù。','Còn khoảng mấy phút nữa thì tới cổng trường ạ, để em ước lượng thời gian.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_11','V236','司机',11,'顺利的话七八分钟就能到，比原地干等快二十分钟不止。','shùn lì de huà qī bā fēn zhōng jiù néng dào， bǐ yuán dì gàn děng kuài èr shí fēn zhōng bù zhǐ。','Thuận lợi thì bảy tám phút là tới, nhanh hơn ngồi đợi tại chỗ những hai mươi phút chứ chẳng ít.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_12','V236','阮明',12,'太好了，这下不用担心迟到被扣平时分，辛苦您特意绕路！','tài hǎo le， zhè xià bù yòng dān xīn chí dào bèi kòu píng shí fēn， xīn kǔ nín tè yì rào lù！','Tuyệt quá, vậy là khỏi lo bị trễ học mà bị trừ điểm chuyên cần, cảm ơn bác đã cố tình đi vòng giúp em!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_13','V236','司机',13,'小事一桩，学生上课要紧，我尽量平稳开车不耽误你。','xiǎo shì yī zhuāng， xué shēng shàng kè yào jǐn， wǒ jǐn liàng píng wěn kāi chē bù dān wù nǐ。','Chuyện nhỏ thôi, học sinh đi học là quan trọng, tôi cố lái xe êm để không làm chậm trễ cậu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_14','V236','阮明',14,'等下车我给您五星好评，真的太感谢您了！','děng xià chē wǒ gěi nín wǔ xīng hǎo píng， zhēn de tài gǎn xiè nín le！','Lát xuống xe em đánh giá năm sao cho bác, thật sự cảm ơn bác nhiều lắm!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT237','S11','Siêu thị không nhận tiền mặt, phải quét mã','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V237','SIT237','P1','twist','tuy_y','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_01','V237','Thu ngân',1,'一共三十八元，麻烦您结账哦。','yī gòng sān shí bā yuán， má fán nín jié zhàng ó。','Tổng cộng ba mươi tám tệ, phiền bạn thanh toán giúp nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_02','V237','Nguyễn Minh',2,'好的，我给您现金可以吗？我没带手机扫码呢。','hǎo de， wǒ gěi nín xiàn jīn kě yǐ ma？ wǒ méi dài shǒu jī sǎo mǎ ne。','Dạ, em đưa tiền mặt được không ạ? Em không mang điện thoại để quét mã.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_03','V237','Thu ngân',3,'不好意思呀，本店现在不收现金，只能微信、支付宝扫码支付。','bù hǎo yì sī ya， běn diàn xiàn zài bù shōu xiàn jīn， zhǐ néng wēi xìn、 zhī fù bǎo sǎo mǎ zhī fù。','Xin lỗi bạn nha, cửa hàng bây giờ không nhận tiền mặt, chỉ nhận thanh toán quét mã qua WeChat hay Alipay thôi.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_04','V237','Nguyễn Minh',4,'这样啊，那我现在打开手机马上扫码哈。','zhè yàng a， nà wǒ xiàn zài dǎ kāi shǒu jī mǎ shàng sǎo mǎ hā。','Vậy à, để em lấy điện thoại ra quét mã ngay đây.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_05','V237','Thu ngân',5,'不急，您慢慢操作，支付成功我就出小票。','bù jí， nín màn màn cāo zuò， zhī fù chéng gōng wǒ jiù chū xiǎo piào。','Không vội đâu, bạn cứ từ từ thao tác, thanh toán xong chị xuất hóa đơn cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_06','V237','Nguyễn Minh',6,'付好啦，谢谢您提醒！','fù hǎo la， xiè xiè nín tí xǐng！','Thanh toán xong rồi ạ, cảm ơn chị đã nhắc!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT238','S7','Máy giặt hỏng, đổi sang máy khác','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V238','SIT238','P1','that_bai_nhe','tuy_y','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_01','V238','Nguyễn Minh',1,'阿姨您好，洗衣房的投币机坏了，投钱没反应呢。','ā yí nín hǎo， xǐ yī fáng de tóu bì jī huài le， tóu qián méi fǎn yìng ne。','Chào cô, máy giặt bằng tiền xu trong phòng giặt bị hỏng rồi, bỏ tiền vào không thấy phản ứng gì ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_02','V238','Quản lý',2,'是卡住了吗？我过去看一下哦。','shì kǎ zhù le ma？ wǒ guò qù kàn yī xià ó。','Bị kẹt à? Để cô qua xem thử nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_03','V238','Nguyễn Minh',3,'对的，我试了两次都没用，衣服放进去没法洗。','duì de， wǒ shì le liǎng cì dōu méi yòng， yī fú fàng jìn qù méi fǎ xǐ。','Dạ đúng ạ, con thử hai lần rồi mà không được, bỏ đồ vào không giặt được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_04','V238','Quản lý',4,'这台机器临时故障了，你换旁边那台用就行哈。','zhè tái jī qì lín shí gù zhàng le， nǐ huàn páng biān nà tái yòng jiù xíng hā。','Máy này tạm thời bị trục trặc rồi, con đổi sang cái máy bên cạnh dùng tạm nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_05','V238','Nguyễn Minh',5,'好的，那故障机器什么时候能修好呀？','hǎo de， nà gù zhàng jī qì shén me shí hòu néng xiū hǎo ya？','Dạ, vậy máy hỏng chừng nào mới sửa xong ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_06','V238','Quản lý',6,'明天师傅过来检修，今晚先用别的机器吧。','míng tiān shī fù guò lái jiǎn xiū， jīn wǎn xiān yòng bié de jī qì ba。','Mai có thợ đến kiểm tra sửa chữa, tối nay cứ dùng máy khác trước đi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_07','V238','Nguyễn Minh',7,'麻烦您了，谢谢阿姨！','má fán nín le， xiè xiè ā yí！','Phiền cô rồi ạ, cảm ơn cô!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT239','S3','Đi nhầm chiều tàu điện ngầm','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V239','SIT239','P1','twist','ban_chinh_thuc','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_01','V239','Nguyễn Minh',1,'您好，不好意思打扰您啦！我好像坐错地铁了。','nín hǎo， bù hǎo yì sī dǎ rǎo nín la！ wǒ hǎo xiàng zuò cuò dì tiě le。','Chào chị, cho em xin lỗi làm phiền chị ạ! Hình như em đi nhầm chiều tàu điện ngầm rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_02','V239','Nhân viên nhà ga',2,'没事的啊，别着急，你要去哪里呀？','méi shì de a， bié zháo jí， nǐ yào qù nǎ lǐ ya？','Không sao đâu, đừng lo lắng, em muốn đi đâu vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_03','V239','Nguyễn Minh',3,'我想去大学城校区，刚刚上车坐反方向了，现在不知道怎么换乘呢。','wǒ xiǎng qù dà xué chéng xiào qū， gāng gāng shàng chē zuò fǎn fāng xiàng le， xiàn zài bù zhī dào zěn me huàn chéng ne。','Em muốn đến khu campus Đại học Thành, vừa rồi lên tàu đi ngược chiều mất rồi, giờ em không biết đổi tàu thế nào ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_04','V239','Nhân viên nhà ga',4,'难怪呢！你不用出站，下一站下车，对面站台坐二号线就可以直达啦。','nán guài ne！ nǐ bù yòng chū zhàn， xià yī zhàn xià chē， duì miàn zhàn tái zuò èr hào xiàn jiù kě yǐ zhí dá la。','Thảo nào! Em không cần ra khỏi ga đâu, xuống ga tiếp theo, sang sân ga đối diện đi tuyến số 2 là tới thẳng luôn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_05','V239','Nguyễn Minh',5,'好的，那我不用重新买票吧？','hǎo de， nà wǒ bù yòng chóng xīn mǎi piào ba？','Dạ, vậy em không cần mua vé lại đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_06','V239','Nhân viên nhà ga',6,'不用的，站内换乘都免费的，放心坐吧。','bù yòng de， zhàn nèi huàn chéng dōu miǎn fèi de， fàng xīn zuò ba。','Không cần đâu, đổi chiều trong nội bộ ga đều miễn phí, cứ yên tâm đi nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_07','V239','Nguyễn Minh',7,'太谢谢您了，真是帮大忙了！','tài xiè xiè nín le， zhēn shì bāng dà máng le！','Cảm ơn chị nhiều lắm, chị giúp em một việc lớn rồi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_08','V239','Nhân viên nhà ga',8,'不客气，下次看清楚方向再上车就好啦。','bú kè qì， xià cì kàn qīng chǔ fāng xiàng zài shàng chē jiù hǎo la。','Không có gì, lần sau nhớ nhìn kỹ hướng rồi hẵng lên tàu nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT240','S11','Nhận hàng giao COD, đối chiếu thông tin','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V240','SIT240','P1','twist','tuy_y','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_01','V240','Shipper',1,'你好，是阮明吧？你的到付快递到啦，是被褥和厨具对吧？','nǐ hǎo， shì ruǎn míng ba？ nǐ de dào fù kuài dì dào la， shì bèi rù hé chú jù duì ba？','Chào bạn, có phải Nguyễn Minh không? Kiện hàng phát thu tiền của bạn đến rồi nè, là chăn ga và dụng cụ bếp đúng không?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_02','V240','Nguyễn Minh',2,'对的，麻烦你帮我核对一下信息哈！手机号是尾号3621没错吧？','duì de， má fán nǐ bāng wǒ hé duì yī xià xìn xī hā！ shǒu jī hào shì wěi hào 3621 méi cuò ba？','Đúng rồi ạ, phiền anh giúp em đối chiếu thông tin nhé! Số điện thoại đuôi 3621 đúng không ạ?','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_03','V240','Shipper',3,'没错的！地址也是学校留学生宿舍。运费一共28块哦。','méi cuò de！ dì zhǐ yě shì xué xiào liú xué shēng sù shè。 yùn fèi yī gòng 28 kuài ó。','Đúng đó! Địa chỉ cũng là ký túc xá lưu học sinh của trường. Tiền vận chuyển tổng cộng 28 tệ nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_04','V240','Nguyễn Minh',4,'咦？我看页面预估是22块，怎么多了6块呀？','yí？ wǒ kàn yè miàn yù gū shì 22 kuài， zěn me duō le 6 kuài ya？','Ủa? Em thấy trên app dự tính là 22 tệ, sao lại dư ra 6 tệ vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_05','V240','Shipper',5,'你这个被子超重啦，超重部分需要补运费，平台预估不准的。','nǐ zhè ge bèi zi chāo zhòng la， chāo zhòng bù fèn xū yào bǔ yùn fèi， píng tái yù gū bù zhǔn de。','Cái chăn của bạn quá cân rồi, phần vượt cân phải bù thêm phí vận chuyển, app dự tính không chính xác đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_06','V240','Nguyễn Minh',6,'原来是这样，那没问题，我扫码付钱吧。','yuán lái shì zhè yàng， nà méi wèn tí， wǒ sǎo mǎ fù qián ba。','Ra là vậy ạ, không sao đâu, để em quét mã trả tiền.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_07','V240','Shipper',7,'好嘞！付完我给你签收，东西都完好着呢，你可以检查一下。','hǎo lei！ fù wán wǒ gěi nǐ qiān shōu， dōng xī dōu wán hǎo zhe ne， nǐ kě yǐ jiǎn chá yī xià。','Được rồi đó! Trả xong tôi ký nhận cho bạn, đồ đạc đều nguyên vẹn cả, bạn kiểm tra thử xem.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_08','V240','Nguyễn Minh',8,'不用检查啦，谢谢你辛苦跑一趟！','bù yòng jiǎn chá la， xiè xiè nǐ xīn kǔ pǎo yī tàng！','Không cần kiểm tra đâu ạ, cảm ơn anh đã vất vả chạy một chuyến!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT241','S12','Gọi món ở nhà ăn, xin không cay','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V241','SIT241','P1','suon_se','tuy_y','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_01','V241','Nhân viên nhà ăn',1,'同学，今天想吃点什么呀？米饭还是面条？','tóng xué， jīn tiān xiǎng chī diǎn shén me ya？ mǐ fàn hái shì miàn tiáo？','Bạn ơi, hôm nay muốn ăn gì nào? Cơm hay mì?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_02','V241','Nguyễn Minh',2,'阿姨，我要一份番茄炒蛋盖饭，谢谢！','ā yí， wǒ yào yī fèn fān qié chǎo dàn gài fàn， xiè xiè！','Cô ơi, cho con một suất cơm trứng xào cà chua, cảm ơn cô!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_03','V241','Nhân viên nhà ăn',3,'好嘞！要不要加点配菜？青菜和土豆都新鲜的。','hǎo lei！ yào bù yào jiā diǎn pèi cài？ qīng cài hé tǔ dòu dōu xīn xiān de。','Được đó! Có muốn thêm món phụ không? Rau xanh với khoai tây đều tươi lắm.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_04','V241','Nguyễn Minh',4,'不用啦阿姨！麻烦您一定不要放辣哦，我完全吃不了辣的。','bù yòng la ā yí！ má fán nín yí dìng bú yào fàng là ó， wǒ wán quán chī bù liǎo là de。','Thôi khỏi cô ơi! Phiền cô đừng cho cay nha, con không ăn được cay chút nào luôn.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_05','V241','Nhân viên nhà ăn',5,'放心吧！我记住啦，给你做清淡口味的。','fàng xīn ba！ wǒ jì zhù la， gěi nǐ zuò qīng dàn kǒu wèi de。','Yên tâm đi! Cô nhớ rồi, cô làm vị nhạt cho con.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_06','V241','Nguyễn Minh',6,'太好啦，谢谢阿姨！','tài hǎo la， xiè xiè ā yí！','Tuyệt quá, cảm ơn cô nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_07','V241','Nhân viên nhà ăn',7,'小事一桩！马上就好，你稍微等一下哈。','xiǎo shì yī zhuāng！ mǎ shàng jiù hǎo， nǐ shāo wēi děng yí xià hā。','Chuyện nhỏ thôi! Xong ngay đây, con đợi một chút nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT242','S13','Xin nghỉ vì thủy thổ bất phục, nhờ bạn cùng phòng thông cảm','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V242','SIT242','P1','suon_se','tuy_y','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_01','V242','Nguyễn Minh',1,'宇哥，我这两天有点难受，想跟你说个事呢。','yǔ gē， wǒ zhè liǎng tiān yǒu diǎn nán shòu， xiǎng gēn nǐ shuō gè shì ne。','Anh Vũ ơi, mấy hôm nay em thấy hơi khó chịu, em muốn nói với anh chuyện này.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_02','V242','Lâm Vũ',2,'怎么了？你看着气色不太好，是不舒服吗？','zěn me le？ nǐ kàn zhe qì sè bù tài hǎo， shì bù shū fú ma？','Sao vậy? Nhìn sắc mặt em không được tốt lắm, có phải khó ở không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_03','V242','Nguyễn Minh',3,'应该是水土不服，晚上总睡不好，白天上课特别困。','yīng gāi shì shuǐ tǔ bù fú， wǎn shàng zǒng shuì bù hǎo， bái tiān shàng kè tè bié kùn。','Chắc là bị thủy thổ bất phục, tối nào cũng ngủ không ngon, ban ngày lên lớp thì buồn ngủ kinh khủng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_04','V242','Lâm Vũ',4,'难怪你这两天都没怎么说话！那你打算怎么办呀？','nán guài nǐ zhè liǎng tiān dōu méi zěn me shuō huà！ nà nǐ dǎ suàn zěn me bàn ya？','Thảo nào mấy hôm nay em ít nói hẳn! Vậy em định làm sao?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_05','V242','Nguyễn Minh',5,'我想今天下午请假休息，晚上也早点睡觉，咱们作息稍微调整一下可以吗？','wǒ xiǎng jīn tiān xià wǔ qǐng jià xiū xī， wǎn shàng yě zǎo diǎn shuì jiào， zán men zuò xī shāo wēi tiáo zhěng yī xià kě yǐ ma？','Em định chiều nay xin nghỉ để nghỉ ngơi, tối cũng ngủ sớm hơn, mình điều chỉnh giờ giấc một chút được không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_06','V242','Lâm Vũ',6,'当然没问题啊！你好好休息就行，我晚上小声一点，不打扰你。','dāng rán méi wèn tí a！ nǐ hǎo hǎo xiū xī jiù xíng， wǒ wǎn shàng xiǎo shēng yì diǎn， bù dǎ rǎo nǐ。','Đương nhiên không vấn đề gì! Em cứ nghỉ ngơi cho khỏe, tối anh nói nhỏ lại, không làm phiền em đâu.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_07','V242','Nguyễn Minh',7,'太谢谢你了，真的麻烦你啦！','tài xiè xiè nǐ le， zhēn de má fán nǐ la！','Cảm ơn anh nhiều lắm, thật sự phiền anh quá!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_08','V242','Lâm Vũ',8,'客气啥，室友本来就该互相照顾的嘛。','kè qì shá， shì yǒu běn lái jiù gāi hù xiāng zhào gù de ma。','Khách sáo gì chứ, ở chung phòng vốn dĩ phải chăm sóc lẫn nhau mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT243','S7','Hỏi quy định đăng ký khách đến thăm ký túc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V243','SIT243','P1','twist','ban_chinh_thuc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_01','V243','Nguyễn Minh',1,'王阿姨您好，打扰您了！我想咨询一下访客入校的规定。','wáng ā yí nín hǎo， dǎ rǎo nín le！ wǒ xiǎng zī xún yī xià fǎng kè rù xiào de guī dìng。','Chào cô Vương, làm phiền cô rồi ạ! Em muốn hỏi thăm về quy định khách đến thăm trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_02','V243','Quản lý',2,'你好，是有朋友要来宿舍找你吗？','nǐ hǎo， shì yǒu péng yǒu yào lái sù shè zhǎo nǐ ma？','Chào em, có phải bạn của em muốn đến ký túc xá tìm em không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_03','V243','Nguyễn Minh',3,'对的，我同学明天想来宿舍找我，需要怎么登记呀？','duì de， wǒ tóng xué míng tiān xiǎng lái sù shè zhǎo wǒ， xū yào zěn me dēng jì ya？','Dạ đúng rồi ạ, bạn học của em ngày mai muốn đến ký túc xá tìm em, cần đăng ký như thế nào ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_04','V243','Quản lý',4,'很简单的，白天来访带身份证，在门卫处登记信息就可以啦。','hěn jiǎn dān de， bái tiān lái fǎng dài shēn fèn zhèng， zài mén wèi chù dēng jì xìn xī jiù kě yǐ la。','Đơn giản thôi, ban ngày đến thăm thì mang theo chứng minh thư, đăng ký thông tin ở chỗ bảo vệ là được.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_05','V243','Nguyễn Minh',5,'那晚上可以来访吗？我本来约了晚上见面的。','nà wǎn shàng kě yǐ lái fǎng ma？ wǒ běn lái yuē le wǎn shàng jiàn miàn de。','Vậy buổi tối có thể đến thăm được không ạ? Em vốn định hẹn gặp vào buổi tối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_06','V243','Quản lý',6,'晚上不行哦，宿舍十点锁门，晚间禁止外来人员入校的。','wǎn shàng bù xíng ó， sù shè shí diǎn suǒ mén， wǎn jiān jìn zhǐ wài lái rén yuán rù xiào de。','Buổi tối thì không được đâu, ký túc xá khóa cửa lúc mười giờ, ban đêm cấm người ngoài vào trường.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_07','V243','Nguyễn Minh',7,'原来是这样，那我改到白天吧，谢谢您告知我！','yuán lái shì zhè yàng， nà wǒ gǎi dào bái tiān ba， xiè xiè nín gào zhī wǒ！','Thì ra là vậy, vậy em đổi sang ban ngày ạ, cảm ơn cô đã cho em biết!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_08','V243','Quản lý',8,'没事的，提前安排好就行，记得让你朋友带证件哈。','méi shì de， tí qián ān pái hǎo jiù xíng， jì de ràng nǐ péng yǒu dài zhèng jiàn hā。','Không sao đâu, sắp xếp trước là được, nhớ nhắc bạn em mang theo giấy tờ nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT244','S7','Báo chủ nhà đổi giờ nhận phòng vì chuyến bay trễ','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V244','SIT244','P1','that_bai_nhe','ban_chinh_thuc','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','提前主动告知行程变动，中国人一般不会严厉追责，但短期房屋预留存在时间限制，过夜空置房东有权收取空置费用；诚恳沟通大多可以免除额外收费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_01','V244','阮明',1,'刘哥您好，不好意思打扰您休息，有件事需要跟您协商调整。','liú gē nín hǎo， bù hǎo yì sī dǎ rǎo nín xiū xī， yǒu jiàn shì xū yào gēn nín xié shāng diào zhěng。','Chào anh Lưu, xin lỗi đã làm phiền anh nghỉ ngơi, có một việc em cần trao đổi và điều chỉnh với anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_02','V244','房东',2,'你好同学，我记得咱们约定好今天下午两点过来办理房屋入住的对吧？','nǐ hǎo tóng xué， wǒ jì de zán men yuē dìng hǎo jīn tiān xià wǔ liǎng diǎn guò lái bàn lǐ fáng wū rù zhù de duì ba？','Chào em, anh nhớ là chúng ta đã hẹn hai giờ chiều nay đến làm thủ tục nhận phòng đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_03','V244','阮明',3,'非常抱歉！我乘坐的入境航班大面积延误，落地时间推迟六个小时，今天肯定赶不过来了呢。','fēi cháng bào qiàn！ wǒ chéng zuò de rù jìng háng bān dà miàn jī yán wù， luò dì shí jiān tuī chí liù gè xiǎo shí， jīn tiān kěn dìng gǎn bù guò lái le ne。','Em thật sự xin lỗi! Chuyến bay nhập cảnh của em bị hoãn trên diện rộng, giờ hạ cánh bị lùi đến sáu tiếng, hôm nay chắc chắn em không đến kịp rồi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_04','V244','房东',4,'这样啊？我今天专门空出一下午在家等你交接，临时变动确实有点麻烦。','zhè yàng a？ wǒ jīn tiān zhuān mén kòng chū yī xià wǔ zài jiā děng nǐ jiāo jiē， lín shí biàn dòng què shí yǒu diǎn má fán。','Vậy à? Hôm nay anh đã sắp xếp dành hẳn cả buổi chiều ở nhà đợi em bàn giao, thay đổi đột xuất thế này thật sự hơi phiền.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_05','V244','阮明',5,'我特别理解您的不便，机场工作人员说最快明天下午两点才能抵达市区。','wǒ tè bié lǐ jiě nín de bù biàn， jī chǎng gōng zuò rén yuán shuō zuì kuài míng tiān xià wǔ liǎng diǎn cái néng dǐ dá shì qū。','Em rất hiểu sự bất tiện của anh, nhân viên sân bay nói nhanh nhất cũng phải đến hai giờ chiều mai mới đến được trung tâm thành phố.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_06','V244','房东',6,'我原本计划今天交接完房屋，晚上出门办事，现在行程全部打乱了。','wǒ yuán běn jì huà jīn tiān jiāo jiē wán fáng wū， wǎn shàng chū mén bàn shì， xiàn zài háng chéng quán bù dǎ luàn le。','Anh vốn định hôm nay bàn giao xong nhà là tối ra ngoài giải quyết việc, giờ thì lịch trình bị đảo lộn hết cả rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_07','V244','阮明',7,'能不能麻烦您帮我延后一天入住，明天下午我准时到，绝不再次迟到？','néng bù néng má fán nín bāng wǒ yán hòu yī tiān rù zhù， míng tiān xià wǔ wǒ zhǔn shí dào， jué bù zài cì chí dào？','Anh có thể giúp em dời việc nhận phòng lại một ngày được không, chiều mai em sẽ đến đúng giờ, tuyệt đối không trễ nữa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_08','V244','房东',8,'按理当天预留的房间只能保留至当日深夜，过夜预留需要额外收取半天空置费。','àn lǐ dàng tiān yù liú de fáng jiān zhǐ néng bǎo liú zhì dāng rì shēn yè， guò yè yù liú xū yào é wài shōu qǔ bàn tiān kōng zhì fèi。','Theo quy định thì phòng giữ trong ngày chỉ được giữ đến khuya hôm đó thôi, giữ qua đêm thì phải thu thêm phí bỏ trống nửa ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_09','V244','阮明',9,'我明白规则，只要能保留房间，相关费用我可以正常承担。','wǒ míng bái guī zé， zhǐ yào néng bǎo liú fáng jiān， xiāng guān fèi yòng wǒ kě yǐ zhèng cháng chéng dān。','Em hiểu quy định ạ, chỉ cần giữ được phòng, khoản phí liên quan em có thể chi trả bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_10','V244','房东',10,'看你是留学生刚来国内不容易，空置费我就不收了，但今天房间不再单独为你预留。','kàn nǐ shì liú xué shēng gāng lái guó nèi bù róng yì， kōng zhì fèi wǒ jiù bù shōu le， dàn jīn tiān fáng jiān bù zài dān dú wèi nǐ yù liú。','Thấy em là du học sinh mới sang cũng không dễ dàng gì, phí bỏ trống anh sẽ không thu, nhưng hôm nay anh sẽ không giữ riêng phòng cho em nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_11','V244','阮明',11,'太感谢您的理解和体谅，临时行程变动给您添了不少麻烦，真的不好意思！','tài gǎn xiè nín de lǐ jiě hé tǐ liàng， lín shí xíng chéng biàn dòng gěi nín tiān le bù shǎo má fán， zhēn de bù hǎo yì sī！','Em cảm ơn anh rất nhiều vì đã thông cảm và thấu hiểu, việc thay đổi lịch trình đột xuất đã gây phiền cho anh không ít, em thật sự xin lỗi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_12','V244','房东',12,'不用客气，出门在外难免有突发变动嘛，但是明天抵达前一小时一定要提前跟我说一声。','bù yòng kè qì， chū mén zài wài nán miǎn yǒu tū fā biàn dòng ma， dàn shì míng tiān dǐ dá qián yī xiǎo shí yí dìng yào tí qián gēn wǒ shuō yī shēng。','Không cần khách sáo, đi xa khó tránh khỏi có thay đổi bất ngờ mà, nhưng ngày mai trước khi đến một tiếng thì nhất định phải báo trước cho anh một tiếng.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_13','V244','阮明',13,'我一定提前发消息告知您到站时间，方便您提前到家等候。','wǒ yí dìng tí qián fā xiāo xī gào zhī nín dào zhàn shí jiān， fāng biàn nín tí qián dào jiā děng hòu。','Em nhất định sẽ nhắn tin báo trước giờ em đến để anh tiện sắp xếp về nhà đợi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_14','V244','房东',14,'好，那我们就约定明天下午两点办理入住，明天见！','hǎo， nà wǒ men jiù yuē dìng míng tiān xià wǔ liǎng diǎn bàn lǐ rù zhù， míng tiān jiàn！','Được, vậy chúng ta hẹn hai giờ chiều mai làm thủ tục nhận phòng nhé, hẹn gặp mai!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT301','S101','Hỏi giá và khuyến mãi ở siêu thị',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V301','SIT301','P1','suon_se','tuy_y',NULL,'国内商超日常促销多为即时抵扣、买赠模式，无需凑单，活动规则简单直白。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_01','V301','阮明',1,'你好，请问这款纯牛奶多少钱一箱啊？','nǐ hǎo， qǐng wèn zhè kuǎn chún niú nǎi duō shǎo qián yī xiāng a？','Chào chị, cho em hỏi loại sữa tươi nguyên chất này giá bao nhiêu một thùng vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_02','V301','导购员',2,'这款68一箱，我们这两天刚好有活动呢。','zhè kuǎn 68 yī xiāng， wǒ men zhè liǎng tiān gāng hǎo yǒu huó dòng ne。','Loại này 68 tệ một thùng, mấy hôm nay bên em đang có chương trình khuyến mãi đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_03','V301','阮明',3,'那是什么优惠呀，划算吗？','nà shì shén me yōu huì ya， huá suàn ma？','Vậy khuyến mãi gì vậy, có lời không?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_04','V301','导购员',4,'买一箱送一小盒酸奶，买两箱直接减20块，很划算的。','mǎi yī xiāng sòng yī xiǎo hé suān nǎi， mǎi liǎng xiāng zhí jiē jiǎn 20 kuài， hěn huá suàn de。','Mua một thùng tặng một hộp sữa chua nhỏ, mua hai thùng thì giảm thẳng 20 tệ, lời lắm luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_05','V301','阮明',5,'这样啊，那我买两箱吧，平时喝得多。','zhè yàng a， nà wǒ mǎi liǎng xiāng ba， píng shí hē dé duō。','Vậy à, vậy em mua hai thùng luôn, bình thường em uống nhiều mà.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_06','V301','导购员',6,'可以的，我帮你扫一下，结账自动抵扣。','kě yǐ de， wǒ bāng nǐ sǎo yī xià， jié zhàng zì dòng dǐ kòu。','Được đó, để chị quét mã cho, lúc thanh toán tự động trừ luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_07','V301','阮明',7,'好嘞，谢谢你！','hǎo lei， xiè xiè nǐ！','Dạ được, cảm ơn chị nha!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT302','S101','Cân rau quả và tự thanh toán',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V302','SIT302','P1','twist','tuy_y',NULL,'国内超市生鲜蔬果必须自助称重贴价签，无标签商品无法通过自助结账，是通用规则。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_01','V302','阮明',1,'阿姨，请问蔬菜水果是在这里称重的吧？','ā yí， qǐng wèn shū cài shuǐ guǒ shì zài zhè lǐ chēng zhòng de ba？','Cô ơi, cho con hỏi rau củ quả cân ở đây đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_02','V302','阿姨',2,'对的呀，把东西放上去选对应的菜名就行。','duì de ya， bǎ dōng xī fàng shàng qù xuǎn duì yìng de cài míng jiù xíng。','Đúng rồi, con đặt đồ lên rồi chọn đúng tên loại rau là được.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_03','V302','阮明',3,'奇怪，我按了好几次，怎么都不出标签呢？','qí guài， wǒ àn le hǎo jǐ cì， zěn me dōu bù chū biāo qiān ne？','Lạ ghê, con bấm mấy lần rồi mà sao không ra tem vậy cô?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_04','V302','阿姨',4,'我看看，你选的是大白菜，你拿的是青菜，选错品类啦。','wǒ kàn kàn， nǐ xuǎn de shì dà bái cài， nǐ ná de shì qīng cài， xuǎn cuò pǐn lèi la。','Để cô xem, con chọn là cải thảo, nhưng đồ con cầm là rau xanh, chọn nhầm loại rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_05','V302','阮明',5,'原来是这样，难怪一直不行，我重新弄一下。','yuán lái shì zhè yàng， nán guài yì zhí bù xíng， wǒ chóng xīn nòng yī xià。','Thì ra là vậy, thảo nào không được, để con làm lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_06','V302','阿姨',6,'没事，慢慢来，打好标签就可以去自助机结账了。','méi shì， màn màn lái， dǎ hǎo biāo qiān jiù kě yǐ qù zì zhù jī jié zhàng le。','Không sao, từ từ thôi, in tem xong là có thể ra máy tự thanh toán rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_07','V302','阮明',7,'太感谢您了，不然我得卡好久。','tài gǎn xiè nín le， bù rán wǒ dé kǎ hǎo jiǔ。','Cảm ơn cô nhiều lắm, không thì con chắc phải loay hoay lâu lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT303','S101','Đổi trả hàng bị lỗi',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V303','SIT303','P1','suon_se','ban_chinh_thuc',NULL,'国内正规商超在售后期内，非人为损坏的商品，可凭购物凭证无条件退换货；生鲜食品变质优先全额退款，避免顾客再次购买同类问题产品。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_01','V303','阮明',1,'你好，我有一件商品存在质量问题，想来售后窗口处理退换。','nǐ hǎo， wǒ yǒu yī jiàn shāng pǐn cún zài zhì liàng wèn tí， xiǎng lái shòu hòu chuāng kǒu chǔ lǐ tuì huàn。','Chào chị, sản phẩm em mua có vấn đề về chất lượng, em muốn đến quầy hậu mãi để xử lý đổi trả ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_02','V303','店员',2,'您好，麻烦先跟我说一下是什么商品，什么时候在店内购买的？','nín hǎo， má fán xiān gēn wǒ shuō yī xià shì shén me shāng pǐn， shén me shí hòu zài diàn nèi gòu mǎi de？','Chào anh, phiền anh cho em biết trước đó là sản phẩm gì, mua tại cửa hàng lúc nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_03','V303','阮明',3,'是一款全麦吐司面包，昨天傍晚在生鲜烘焙区选购的，今天早上拆开就发霉了。','shì yī kuǎn quán mài tǔ sī miàn bāo， zuó tiān bàng wǎn zài shēng xiān hōng bèi qū xuǎn gòu de， jīn tiān zǎo shàng chāi kāi jiù fā méi le。','Là một loại bánh mì sandwich nguyên cám, em mua ở khu bánh tươi chiều tối hôm qua, sáng nay mở ra thì đã bị mốc rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_04','V303','店员',4,'麻烦出示一下对应的购物小票，我们需要核对购买时间和批次信息。','má fán chū shì yī xià duì yìng de gòu wù xiǎo piào， wǒ men xū yào hé duì gòu mǎi shí jiān hé pī cì xìn xī。','Phiền anh cho em xem hóa đơn mua hàng tương ứng, bên em cần đối chiếu thời gian mua và thông tin lô hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_05','V303','阮明',5,'小票我一直妥善收在钱包里，现在拿给您，我全程常温存放，根本没放多久呀。','xiǎo piào wǒ yì zhí tuǒ shàn shōu zài qián bāo lǐ， xiàn zài ná gěi nín， wǒ quán chéng cháng wēn cún fàng， gēn běn méi fàng duō jiǔ ya。','Hóa đơn em vẫn giữ cẩn thận trong ví, đây em đưa cho chị, em bảo quản ở nhiệt độ thường suốt, có để lâu đâu ạ.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_06','V303','店员',6,'我对照系统入库记录核对面包批次，确认是商品本身出厂保鲜出现问题，非常抱歉哈。','wǒ duì zhào xì tǒng rù kù jì lù hé duì miàn bāo pī cì， què rèn shì shāng pǐn běn shēn chū chǎng bǎo xiān chū xiàn wèn tí， fēi cháng bào qiàn hā。','Em đối chiếu với hồ sơ nhập kho trên hệ thống để kiểm tra lô bánh, xác nhận là do bản thân sản phẩm gặp vấn đề bảo quản từ khi xuất xưởng, thành thật xin lỗi anh.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_07','V303','阮明',7,'没关系，我也不是故意为难店里，只是担心同类商品其他顾客买到。','méi guān xì， wǒ yě bú shì gù yì wéi nán diàn lǐ， zhǐ shì dān xīn tóng lèi shāng pǐn qí tā gù kè mǎi dào。','Không sao đâu, em cũng không cố ý làm khó cửa hàng, chỉ là lo những khách hàng khác mua phải sản phẩm cùng loại thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_08','V303','店员',8,'您愿意换新商品，还是直接申请全额退款，两种方案都可以执行。','nín yuàn yì huàn xīn shāng pǐn， hái shì zhí jiē shēn qǐng quán é tuì kuǎn， liǎng zhǒng fāng àn dōu kě yǐ zhí xíng。','Anh muốn đổi sản phẩm mới hay là xin hoàn tiền toàn bộ luôn ạ, cả hai phương án đều thực hiện được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_09','V303','阮明',9,'这款面包我不敢再选购同款，直接办理全额退款会更合适。','zhè kuǎn miàn bāo wǒ bù gǎn zài xuǎn gòu tóng kuǎn， zhí jiē bàn lǐ quán é tuì kuǎn huì gèng hé shì。','Loại bánh này em không dám mua lại nữa, hoàn tiền toàn bộ luôn sẽ hợp lý hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_10','V303','店员',10,'没问题，我现在操作后台退款，资金会原路返还到您付款的支付软件。','méi wèn tí， wǒ xiàn zài cāo zuò hòu tái tuì kuǎn， zī jīn huì yuán lù fǎn huán dào nín fù kuǎn de zhī fù ruǎn jiàn。','Không vấn đề gì, em thao tác hoàn tiền trên hệ thống ngay đây, tiền sẽ được hoàn về đúng phần mềm thanh toán mà anh đã dùng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_11','V303','阮明',11,'退款到账大概需要多长时间，会不会有延迟？','tuì kuǎn dào zhàng dà gài xū yào duō zhǎng shí jiān， huì bú huì yǒu yán chí？','Tiền hoàn về khoảng bao lâu thì tới ạ, có bị chậm trễ gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_12','V303','店员',12,'线上支付退款实时到账，您现在打开手机就能查到余额变动。','xiàn shàng zhī fù tuì kuǎn shí shí dào zhàng， nín xiàn zài dǎ kāi shǒu jī jiù néng chá dào yú é biàn dòng。','Hoàn tiền qua thanh toán online là về ngay lập tức, anh mở điện thoại lên là kiểm tra được biến động số dư liền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_13','V303','阮明',13,'清楚流程了，给您添麻烦实在不好意思。','qīng chǔ liú chéng le， gěi nín tiān má fán shí zài bù hǎo yì sī。','Em hiểu quy trình rồi ạ, làm phiền chị thật sự có lỗi quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_14','V303','店员',14,'是我们商品存在质量瑕疵，本该向您致歉，您慢走。','shì wǒ men shāng pǐn cún zài zhì liàng xiá cī， běn gāi xiàng nín zhì qiàn， nín màn zǒu。','Là do sản phẩm bên em có lỗi chất lượng, đáng lẽ phải xin lỗi anh mới đúng, anh đi cẩn thận nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_15','V303','阮明',15,'好的，麻烦你啦。','hǎo de， má fán nǐ la。','Dạ vâng, phiền chị rồi ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT304','S102','Mua chăn, gối, nồi, ly cho phòng mới',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V304','SIT304','P1','twist','tuy_y',NULL,'国内高校宿舍严禁大功率电器，校园店铺售卖的煮锅均为合规小功率产品，不会违规跳闸。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_01','V304','阮明',1,'老板，我是新生，想买一套宿舍被褥、枕头还有小煮锅。','lǎo bǎn， wǒ shì xīn shēng， xiǎng mǎi yī tào sù shè bèi rù、 zhěn tou hái yǒu xiǎo zhǔ guō。','Anh chủ ơi, em là sinh viên mới, em muốn mua một bộ chăn ga gối ký túc xá với cả nồi nấu nhỏ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_02','V304','老板',2,'有的，这些都是学生专用的，厚度和功率都适配宿舍的。','yǒu de， zhè xiē dōu shì xué shēng zhuān yòng de， hòu dù hé gōng lǜ dōu shì pèi sù shè de。','Có chứ, mấy món này đều là chuyên dùng cho sinh viên, độ dày với công suất đều hợp với ký túc xá hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_03','V304','阮明',3,'这个被子冬天盖够厚吗？我怕冷的。','zhè ge bèi zi dōng tiān gài gòu hòu ma？ wǒ pà lěng de。','Cái chăn này mùa đông đắp có đủ ấm không anh? Em sợ lạnh lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_04','V304','老板',4,'足够过冬的，就是宿舍小煮锅今天刚卖断货了嘛。','zú gòu guò dōng de， jiù shì sù shè xiǎo zhǔ guō jīn tiān gāng mài duàn huò le ma。','Đủ ấm qua mùa đông luôn, chỉ có nồi nấu ký túc xá hôm nay vừa bán hết hàng thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_05','V304','阮明',5,'啊？那什么时候能补货呀？我急用。','a？ nà shén me shí hòu néng bǔ huò ya？ wǒ jí yòng。','Hả? Vậy khi nào có hàng lại vậy anh? Em cần gấp lắm.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_06','V304','老板',6,'明天中午就到货，你明天过来拿就行。','míng tiān zhōng wǔ jiù dào huò， nǐ míng tiān guò lái ná jiù xíng。','Trưa mai là có hàng về rồi, mai em qua lấy là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_07','V304','阮明',7,'行，那我今天先买被子、枕头和水杯。','xíng， nà wǒ jīn tiān xiān mǎi bèi zi、 zhěn tou hé shuǐ bēi。','Dạ được, vậy hôm nay em mua chăn, gối với ly nước trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT305','S103','Mua nước giặt và dùng máy giặt tự động',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V305','SIT305','P1','suon_se','tuy_y',NULL,'国内高校宿舍洗衣房均为无人自助设备，按次计费，无需人工值守，操作简单。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_01','V305','阮明',1,'学姐，请问哪种洗衣液好用啊？我第一次在宿舍洗衣服。','xué jiě， qǐng wèn nǎ zhǒng xǐ yī yè hǎo yòng a？ wǒ dì yī cì zài sù shè xǐ yī fú。','Chị ơi, cho em hỏi loại nước giặt nào dùng tốt vậy? Đây là lần đầu em giặt đồ trong ký túc xá đó.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_02','V305','学姐',2,'你买这款瓶装的就行，味道清淡，去污力也不错呢。','nǐ mǎi zhè kuǎn píng zhuāng de jiù xíng， wèi dào qīng dàn， qù wū lì yě bù cuò ne。','Em mua loại đóng chai này là được, mùi nhẹ nhàng, tẩy sạch cũng ổn lắm nè.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_03','V305','阮明',3,'好嘞，那楼下自助洗衣机难操作吗？','hǎo lei， nà lóu xià zì zhù xǐ yī jī nán cāo zuò ma？','Được rồi, vậy máy giặt tự động ở dưới lầu có khó dùng không chị?','AM08') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_04','V305','学姐',4,'一点不难，扫码付款、放衣服和洗衣液就可以啦。','yì diǎn bù nán， sǎo mǎ fù kuǎn、 fàng yī fú hé xǐ yī yè jiù kě yǐ la。','Không khó đâu, quét mã thanh toán rồi cho đồ với nước giặt vào là xong à.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_05','V305','阮明',5,'需要自己调时间和模式吗？','xū yào zì jǐ diào shí jiān hé mó shì ma？','Em có cần tự chỉnh thời gian với chế độ giặt không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_06','V305','学姐',6,'不用，默认标准模式，洗得很干净的。','bù yòng， mò rèn biāo zhǔn mó shì， xǐ dé hěn gān jìng de。','Không cần, cứ để chế độ chuẩn mặc định, giặt sạch lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_07','V305','阮明',7,'明白了，太谢谢你啦！','míng bái le， tài xiè xiè nǐ la！','Em hiểu rồi, cảm ơn chị nhiều nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT306','S103','Máy giặt hết tiền giữa chừng, xin hoàn tiền',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V306','SIT306','P1','suon_se','ban_chinh_thuc',NULL,'校园自助设备出现扣费异常、中途停机等问题，均可找宿管统一走后勤退款流程；退款不会即时处理，学校后勤固定日期批量结算。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_01','V306','阮明',1,'阿姨您好，我刚刚在宿舍楼自助洗衣房洗衣服，机器运行一半突然停机了。','ā yí nín hǎo， wǒ gāng gāng zài sù shè lóu zì zhù xǐ yī fáng xǐ yī fú， jī qì yùn xíng yí bàn tū rán tíng jī le。','Cô ơi, cháu vừa giặt đồ ở phòng giặt tự động của khu ký túc xá, máy đang chạy nửa chừng thì tự dưng dừng lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_02','V306','宿管阿姨',2,'别着急，你先回忆一下，机器停机的时候屏幕有没有弹出提示文字？','bié zháo jí， nǐ xiān huí yì yī xià， jī qì tíng jī de shí hòu píng mù yǒu méi yǒu dàn chū tí shì wén zì？','Đừng lo, cháu thử nhớ lại xem, lúc máy dừng màn hình có hiện thông báo gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_03','V306','阮明',3,'屏幕显示账户余额不足，自动中断洗涤程序，衣服只洗了一半。','píng mù xiǎn shì zhàng hù yú é bù zú， zì dòng zhōng duàn xǐ dí chéng xù， yī fú zhǐ xǐ le yí bàn。','Màn hình báo là số dư tài khoản không đủ, nên tự ngắt chương trình giặt, đồ chỉ mới giặt được nửa thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_04','V306','宿管阿姨',4,'原来是扣费余额耗尽，这种情况在自助设备使用里十分常见。','yuán lái shì kòu fèi yú é hào jìn， zhè zhǒng qíng kuàng zài zì zhù shè bèi shǐ yòng lǐ shí fēn cháng jiàn。','Ra là do hết tiền trong thẻ, trường hợp này khi dùng thiết bị tự động thì rất thường gặp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_05','V306','阮明',5,'我之前查看余额还有几块钱，以为完全够完整洗完一整轮，没想到中途欠费了。','wǒ zhī qián chá kàn yú é hái yǒu jǐ kuài qián， yǐ wéi wán quán gòu wán zhěng xǐ wán yī zhěng lún， méi xiǎng dào zhōng tú qiàn fèi le。','Trước đó cháu kiểm tra thấy còn vài đồng, nghĩ là đủ để giặt xong hết một chu trình, không ngờ giữa đường lại thiếu tiền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_06','V306','宿管阿姨',6,'洗衣程序分为洗涤、漂洗、脱水三段，分段扣取费用，余额不够就会中途停机。','xǐ yī chéng xù fēn wéi xǐ dí、 piǎo xǐ、 tuō shuǐ sān duàn， fēn duàn kòu qǔ fèi yòng， yú é bù gòu jiù huì zhōng tú tíng jī。','Chương trình giặt chia làm ba đoạn: giặt, xả, vắt, mỗi đoạn trừ tiền riêng, hết tiền là máy dừng giữa chừng luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_07','V306','阮明',7,'那像我这种只洗一半就停机的情况，可以申请退还部分洗衣费用吗？','nà xiàng wǒ zhè zhǒng zhǐ xǐ yí bàn jiù tíng jī de qíng kuàng， kě yǐ shēn qǐng tuì huán bù fèn xǐ yī fèi yòng ma？','Vậy trường hợp như cháu chỉ giặt được nửa rồi dừng thì có thể xin hoàn lại một phần tiền giặt không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_08','V306','宿管阿姨',8,'完全可以，后勤处专门有异常扣费退款登记流程，我帮你上报。','wán quán kě yǐ， hòu qín chù zhuān mén yǒu yì cháng kòu fèi tuì kuǎn dēng jì liú chéng， wǒ bāng nǐ shàng bào。','Được chứ, phòng hậu cần có quy trình đăng ký hoàn tiền cho trường hợp trừ tiền bất thường, cô sẽ báo lên giúp cháu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_09','V306','阮明',9,'办理退款需要打印纸质付款凭证，还是只提供手机截图就行？','bàn lǐ tuì kuǎn xū yào dǎ yìn zhǐ zhì fù kuǎn píng zhèng， hái shì zhǐ tí gōng shǒu jī jié tú jiù xíng？','Làm thủ tục hoàn tiền có cần in hóa đơn thanh toán giấy không, hay chỉ cần gửi ảnh chụp màn hình điện thoại thôi?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_10','V306','宿管阿姨',10,'不用打印纸质单据，直接把当时的付款截图微信发给我即可。','bù yòng dǎ yìn zhǐ zhì dān jù， zhí jiē bǎ dāng shí de fù kuǎn jié tú wēi xìn fā gěi wǒ jí kě。','Không cần in giấy đâu, cháu cứ chụp lại màn hình lúc thanh toán rồi gửi qua WeChat cho cô là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_11','V306','阮明',11,'截图我马上调取发送，大概多久能完成退款到账？','jié tú wǒ mǎ shàng diào qǔ fā sòng， dà gài duō jiǔ néng wán chéng tuì kuǎn dào zhàng？','Cháu chụp gửi ngay đây, khoảng bao lâu thì tiền hoàn về ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_12','V306','宿管阿姨',12,'统一每周五集中处理退款申请，最晚本周五资金原路退回。','tǒng yī měi zhōu wǔ jí zhōng chǔ lǐ tuì kuǎn shēn qǐng， zuì wǎn běn zhōu wǔ zī jīn yuán lù tuì huí。','Cứ thứ Sáu hàng tuần là xử lý gộp các yêu cầu hoàn tiền, chậm nhất thứ Sáu tuần này tiền sẽ hoàn về đúng nguồn ban đầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_13','V306','阮明',13,'我明白需要等待统一处理，辛苦阿姨帮忙登记上报就行。','wǒ míng bái xū yào děng dài tǒng yī chǔ lǐ， xīn kǔ ā yí bāng máng dēng jì shàng bào jiù xíng。','Cháu hiểu là phải chờ xử lý theo lịch chung, cô giúp cháu đăng ký báo lên là được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_14','V306','宿管阿姨',14,'小事，下次洗衣前记得多充一点余额，避免中途停机。','xiǎo shì， xià cì xǐ yī qián jì de duō chōng yì diǎn yú é， bì miǎn zhōng tú tíng jī。','Chuyện nhỏ mà, lần sau giặt đồ nhớ nạp thêm chút tiền vào thẻ để tránh bị dừng giữa chừng nữa nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_15','V306','阮明',15,'好的，辛苦阿姨啦！','hǎo de， xīn kǔ ā yí la！','Vâng, cảm ơn cô nhiều lắm ạ!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT307','S104','Gọi món mang đi ở quán gần trường',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V307','SIT307','P1','suon_se','tuy_y',NULL,'国内街边小吃支持自由调整口味、增减食材，常规外带打包无需额外收费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_01','V307','阮明',1,'你好，我要一份杂粮煎饼，打包外带哦。','nǐ hǎo， wǒ yào yī fèn zá liáng jiān bǐng， dǎ bāo wài dài ó。','Chào anh/chị, cho em một cái bánh crepe ngũ cốc, gói mang đi nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_02','V307','店员',2,'好嘞，要不要加烤肠、生菜这些配菜呀？','hǎo lei， yào bù yào jiā kǎo cháng、 shēng cài zhè xiē pèi cài ya？','Được rồi, em có muốn thêm xúc xích nướng, xà lách gì không?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_03','V307','阮明',3,'加一根烤肠就好，少放辣椒吧，我不太能吃辣。','jiā yī gēn kǎo cháng jiù hǎo， shǎo fàng là jiāo ba， wǒ bù tài néng chī là。','Thêm một cây xúc xích nướng thôi, ớt cho ít lại nhé, em không ăn cay được lắm.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_04','V307','店员',4,'没问题，微辣口味，两分钟就好哈。','méi wèn tí， wēi là kǒu wèi， liǎng fēn zhōng jiù hǎo hā。','Không thành vấn đề, vị cay nhẹ, hai phút là xong ngay nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_05','V307','阮明',5,'麻烦帮我封紧一点，我带回宿舍吃。','má fán bāng wǒ fēng jǐn yì diǎn， wǒ dài huí sù shè chī。','Anh/chị làm ơn gói kỹ một chút giúp em, em mang về ký túc xá ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_06','V307','店员',6,'放心，肯定给你包得严严实实的。','fàng xīn， kěn dìng gěi nǐ bāo dé yán yán shí shí de。','Yên tâm, chắc chắn gói cho em kín kẽ luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_07','V307','阮明',7,'谢谢老板！','xiè xiè lǎo bǎn！','Cảm ơn chủ quán!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT308','S104','Báo dị ứng thực phẩm khi đặt món online',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V308','SIT308','P1','twist','ban_chinh_thuc',NULL,'国内外卖平台的用餐备注优先级很高，食材过敏、特殊口味等需求，正规商家都会优先遵从。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_01','V308','阮明',1,'你好，我刚下的订单，有重要的忌口需要备注。','nǐ hǎo， wǒ gāng xià de dìng dān， yǒu zhòng yào de jì kǒu xū yào bèi zhù。','Chào bạn, tôi vừa đặt đơn hàng, có một điều kiêng cữ quan trọng cần ghi chú lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_02','V308','客服',2,'您好，请您说明具体要求，我们同步给后厨。','nín hǎo， qǐng nín shuō míng jù tǐ yāo qiú， wǒ men tóng bù gěi hòu chú。','Chào anh/chị, xin anh/chị nói rõ yêu cầu cụ thể, chúng tôi sẽ báo ngay cho nhà bếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_03','V308','阮明',3,'我严重对花生过敏，餐品里千万不要放任何花生制品啊。','wǒ yán zhòng duì huā shēng guò mǐn， cān pǐn lǐ qiān wàn bú yào fàng rèn hé huā shēng zhì pǐn a。','Tôi bị dị ứng đậu phộng rất nặng, món ăn tuyệt đối không được cho bất kỳ sản phẩm nào có đậu phộng nhé.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_04','V308','客服',4,'好的，已经为您重点备注忌口花生。','hǎo de， yǐ jīng wèi nín zhòng diǎn bèi zhù jì kǒu huā shēng。','Được rồi, chúng tôi đã ghi chú nổi bật là kiêng đậu phộng cho đơn của anh/chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_05','V308','阮明',5,'之前有商家忽略备注，差点出问题呢。','zhī qián yǒu shāng jiā hū lüè bèi zhù， chà diǎn chū wèn tí ne。','Trước đây có cửa hàng bỏ qua ghi chú này, suýt thì xảy ra chuyện đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_06','V308','客服',6,'非常抱歉让您有顾虑，我们会单独叮嘱后厨的。','fēi cháng bào qiàn ràng nín yǒu gù lǜ， wǒ men huì dān dú dīng zhǔ hòu chú de。','Chúng tôi rất xin lỗi vì đã khiến anh/chị lo lắng, chúng tôi sẽ nhắc riêng nhà bếp lưu ý kỹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_07','V308','阮明',7,'那就麻烦你们多留意一下。','nà jiù má fán nǐ men duō liú yì yī xià。','Vậy thì mong các bạn chú ý thêm giúp tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT309','S101','Hỏi hạn sử dụng và bảo quản thực phẩm',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V309','SIT309','P1','suon_se','tuy_y',NULL,'食品分常温、冷藏两类储存方式，错误存放会大幅缩短保质期，是日常收纳的基本常识。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_01','V309','阮明',1,'你好，我想问一下这款酸奶的保质期是多久呀？','nǐ hǎo， wǒ xiǎng wèn yī xià zhè kuǎn suān nǎi de bǎo zhì qī shì duō jiǔ ya？','Chào chị, em muốn hỏi hạn sử dụng của loại sữa chua này là bao lâu ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_02','V309','店员',2,'这款常温酸奶保质期三个月，不用放冰箱的。','zhè kuǎn cháng wēn suān nǎi bǎo zhì qī sān gè yuè， bù yòng fàng bīng xiāng de。','Loại sữa chua để nhiệt độ thường này có hạn ba tháng, không cần để tủ lạnh đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_03','V309','阮明',3,'那开封之后可以放多久呢？','nà kāi fēng zhī hòu kě yǐ fàng duō jiǔ ne？','Vậy sau khi mở hộp thì để được bao lâu ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_04','V309','店员',4,'开封后最好当天喝完，放久容易变质哦。','kāi fēng hòu zuì hǎo dàng tiān hē wán， fàng jiǔ róng yì biàn zhì ó。','Mở hộp rồi thì nên uống hết trong ngày, để lâu dễ bị hỏng đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_05','V309','阮明',5,'原来是这样，常温存放就可以是吧？','yuán lái shì zhè yàng， cháng wēn cún fàng jiù kě yǐ shì ba？','Ra là vậy, cứ để ở nhiệt độ thường là được đúng không chị?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_06','V309','店员',6,'对的，避开阳光暴晒就行，很方便的。','duì de， bì kāi yáng guāng pù shài jiù xíng， hěn fāng biàn de。','Đúng rồi, tránh ánh nắng chiếu trực tiếp là được, tiện lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_07','V309','阮明',7,'清楚了，谢谢你！','qīng chǔ le， xiè xiè nǐ！','Em rõ rồi, cảm ơn chị!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT310','S105','Thương lượng với hàng xóm về tiếng ồn',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V310','SIT310','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍普遍默认夜间十点为安静作息时间，邻里噪音问题友好协商即可解决。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_01','V310','阮明',1,'同学你好，不好意思打扰你一下哈。','tóng xué nǐ hǎo， bù hǎo yì sī dǎ rǎo nǐ yī xià hā。','Chào bạn, xin lỗi làm phiền bạn một chút nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_02','V310','邻居',2,'没事的，你有什么事直接说就好呀。','méi shì de， nǐ yǒu shén me shì zhí jiē shuō jiù hǎo ya。','Không sao đâu, bạn có việc gì thì cứ nói thẳng ra nhé.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_03','V310','阮明',3,'我晚上要复习备考，你们宿舍声音稍微有点大呢。','wǒ wǎn shàng yào fù xí bèi kǎo， nǐ men sù shè shēng yīn shāo wēi yǒu diǎn dà ne。','Tối nay tôi phải ôn bài chuẩn bị thi, phòng các bạn hình như hơi ồn một chút.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_04','V310','邻居',4,'天啊，真的不好意思，我们没注意音量。','tiān a， zhēn de bù hǎo yì sī， wǒ men méi zhù yì yīn liàng。','Ôi trời, thật xin lỗi bạn nhiều, chúng tôi không để ý âm lượng.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_05','V310','阮明',5,'没关系的，就是希望晚上十点后可以安静一点。','méi guān xì de， jiù shì xī wàng wǎn shàng shí diǎn hòu kě yǐ ān jìng yì diǎn。','Không sao cả, tôi chỉ mong là sau 10 giờ tối có thể yên tĩnh hơn một chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_06','V310','邻居',6,'没问题，我们马上小声，之后一定注意！','méi wèn tí， wǒ men mǎ shàng xiǎo shēng， zhī hòu yí dìng zhù yì！','Không vấn đề gì, chúng tôi nhỏ tiếng ngay đây, sau này chắc chắn sẽ chú ý!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_07','V310','阮明',7,'太感谢你的理解啦！','tài gǎn xiè nǐ de lǐ jiě la！','Cảm ơn bạn đã thông cảm nhiều lắm nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT311','S106','Xin phép vào lớp muộn',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V311','SIT311','P1','suon_se','ban_chinh_thuc',NULL,'国内课堂迟到必须主动致歉并说明原因，征得老师同意后方可进入教室，是基本课堂礼仪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_01','V311','阮明',1,'老师对不起，我上课迟到了，非常抱歉！','lǎo shī duì bù qǐ， wǒ shàng kè chí dào le， fēi cháng bào qiàn！','Em xin lỗi thầy/cô, em đến lớp muộn rồi, thật sự rất xin lỗi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_02','V311','老师',2,'怎么迟到了呢？是什么原因造成的？','zěn me chí dào le ne？ shì shén me yuán yīn zào chéng de？','Sao lại đến muộn vậy? Là do nguyên nhân gì?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_03','V311','阮明',3,'我早上出门晚了，遇上堵车，耽误了时间。','wǒ zǎo shàng chū mén wǎn le， yù shàng dǔ chē， dān wù le shí jiān。','Em ra khỏi nhà trễ vào buổi sáng, lại gặp kẹt xe nên bị chậm giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_04','V311','老师',4,'下次一定要把控好时间，不要再迟到了。','xià cì yí dìng yào bǎ kòng hǎo shí jiān， bú yào zài chí dào le。','Lần sau phải sắp xếp thời gian cho tốt, đừng để đến muộn nữa nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_05','V311','阮明',5,'我记住了，以后肯定提前出门。','wǒ jì zhù le， yǐ hòu kěn dìng tí qián chū mén。','Em nhớ rồi, sau này em chắc chắn sẽ ra khỏi nhà sớm hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_06','V311','老师',6,'行，快进来入座听课吧，不要耽误学习。','xíng， kuài jìn lái rù zuò tīng kè ba， bú yào dān wù xué xí。','Được rồi, vào lớp ngồi vào chỗ nghe giảng đi, đừng để ảnh hưởng đến việc học nữa.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_07','V311','阮明',7,'谢谢老师谅解！','xiè xiè lǎo shī liàng jiě！','Em cảm ơn thầy/cô đã thông cảm!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT312','S106','Xin nghỉ học vì lý do cá nhân',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V312','SIT312','P1','suon_se','ban_chinh_thuc',NULL,'国内高校禁止无故缺课，所有缺勤都需要提前报备请假，否则会记录考勤扣分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_01','V312','阮明',1,'辅导员您好，我想申请今天下午的事假。','fǔ dǎo yuán nín hǎo， wǒ xiǎng shēn qǐng jīn tiān xià wǔ de shì jià。','Chào thầy/cô chủ nhiệm, em muốn xin nghỉ việc riêng buổi chiều hôm nay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_02','V312','辅导员',2,'可以的，简单说一下请假的原因吧。','kě yǐ de， jiǎn dān shuō yī xià qǐng jià de yuán yīn ba。','Được, em nói qua lý do xin nghỉ xem sao.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_03','V312','阮明',3,'我有重要的个人私事需要处理，没办法延后。','wǒ yǒu zhòng yào de gè rén sī shì xū yào chǔ lǐ， méi bàn fǎ yán hòu。','Em có việc riêng quan trọng cần giải quyết, không thể trì hoãn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_04','V312','辅导员',4,'了解了，我给你登记考勤，准予请假。','liǎo jiě le， wǒ gěi nǐ dēng jì kǎo qín， zhǔn yǔ qǐng jià。','Cô hiểu rồi, cô sẽ ghi vào chuyên cần và cho em nghỉ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_05','V312','阮明',5,'谢谢老师，落下的课程我会及时补回来的。','xiè xiè lǎo shī， là xià de kè chéng wǒ huì jí shí bǔ huí lái de。','Em cảm ơn cô, phần bài học bị lỡ em sẽ bù lại kịp thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_06','V312','辅导员',6,'一定要跟上进度，不要拖欠学习内容。','yí dìng yào gēn shàng jìn dù， bú yào tuō qiàn xué xí nèi róng。','Nhất định phải theo kịp tiến độ, không được để thiếu sót nội dung học nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_07','V312','阮明',7,'我明白的，辛苦老师了！','wǒ míng bái de， xīn kǔ lǎo shī le！','Em hiểu rồi, cảm ơn cô đã vất vả vì em!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT313','S107','Xin gia hạn nộp bài tập',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V313','SIT313','P1','twist','ban_chinh_thuc',NULL,'大学作业延期属于特殊情况，老师会酌情处理，但不支持频繁、长期延期；超规定延期时限会扣除课程平时成绩。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_01','V313','阮明',1,'老师您好，占用您一点课余时间，我想跟您申请课程作业延期提交。','lǎo shī nín hǎo， zhàn yòng nín yì diǎn kè yú shí jiān， wǒ xiǎng gēn nín shēn qǐng kè chéng zuò yè yán qī tí jiāo。','Chào thầy/cô, em xin phép chiếm dụng chút thời gian ngoài giờ của thầy/cô, em muốn xin gia hạn nộp bài tập ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_02','V313','老师',2,'你先简单说明理由，课堂规定无故拖延作业提交时间是不允许的哦。','nǐ xiān jiǎn dān shuō míng lǐ yóu， kè táng guī dìng wú gù tuō yán zuò yè tí jiāo shí jiān shì bù yǔn xǔ de ó。','Em nói lý do đơn giản trước đi, quy định lớp là không cho phép trì hoãn nộp bài mà không có lý do chính đáng đâu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_03','V313','阮明',3,'昨天一整天突发肠胃不适，头晕乏力卧床休息，完全没有精力动笔写作业。','zuó tiān yī zhěng tiān tū fā cháng wèi bù shì， tóu yūn fá lì wò chuáng xiū xī， wán quán méi yǒu jīng lì dòng bǐ xiě zuò yè。','Hôm qua cả ngày em bị đau bụng, đi ngoài, chóng mặt mệt mỏi phải nằm nghỉ, hoàn toàn không còn sức để làm bài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_04','V313','老师',4,'身体不舒服我可以理解，生病属于合理特殊情况，不过延期有严格时限要求。','shēn tǐ bù shū fú wǒ kě yǐ lǐ jiě， shēng bìng shǔ yú hé lǐ tè shū qíng kuàng， bù guò yán qī yǒu yán gé shí xiàn yāo qiú。','Việc em ốm mệt thầy/cô hiểu, bệnh thì là trường hợp đặc biệt hợp lý, nhưng gia hạn phải theo quy định thời hạn nghiêm ngặt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_05','V313','阮明',5,'我原本计划今天傍晚准时上交，现在还差一半内容没能完成。','wǒ yuán běn jì huà jīn tiān bàng wǎn zhǔn shí shàng jiāo， xiàn zài hái chà yí bàn nèi róng méi néng wán chéng。','Em vốn định chiều nay nộp đúng hạn, nhưng giờ vẫn còn thiếu một nửa nội dung chưa hoàn thành.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_06','V313','老师',6,'按照学院统一规定，单次作业最多只能延期一天，不能无限延后。','àn zhào xué yuàn tǒng yī guī dìng， dān cì zuò yè zuì duō zhǐ néng yán qī yī tiān， bù néng wú xiàn yán hòu。','Theo quy định chung của khoa, mỗi bài chỉ được gia hạn tối đa một ngày thôi, không thể kéo dài mãi được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_07','V313','阮明',7,'只延期一天对我来说完全足够，今晚我熬夜赶工，保证完整写完所有内容。','zhǐ yán qī yī tiān duì wǒ lái shuō wán quán zú gòu， jīn wǎn wǒ áo yè gǎn gōng， bǎo zhèng wán zhěng xiě wán suǒ yǒu nèi róng。','Chỉ cần gia hạn một ngày là đủ với em rồi, tối nay em sẽ thức làm cho xong, đảm bảo hoàn thành đầy đủ nội dung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_08','V313','老师',8,'这次看你身体不适特殊通融一次，往后不管任何理由都尽量按时完成。','zhè cì kàn nǐ shēn tǐ bù shì tè shū tōng róng yī cì， wǎng hòu bù guǎn rèn hé lǐ yóu dōu jǐn liàng àn shí wán chéng。','Lần này thấy em ốm nên thầy/cô châm chước một lần, sau này dù lý do gì cũng cố gắng nộp đúng hạn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_09','V313','阮明',9,'我记下老师的提醒，下次一定提前规划时间，不会再出现延期情况。','wǒ jì xià lǎo shī de tí xǐng， xià cì yí dìng tí qián guī huà shí jiān， bú huì zài chū xiàn yán qī qíng kuàng。','Em ghi nhớ lời nhắc của thầy/cô rồi, lần sau em sẽ sắp xếp thời gian trước, không để xảy ra chuyện xin gia hạn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_10','V313','老师',10,'延期提交的作业明天傍晚六点前必须交到办公室，逾期依旧会扣除平时分。','yán qī tí jiāo de zuò yè míng tiān bàng wǎn liù diǎn qián bì xū jiāo dào bàn gōng shì， yú qī yī jiù huì kòu chú píng shí fēn。','Bài nộp gia hạn phải mang đến văn phòng trước 6 giờ chiều mai, nộp trễ vẫn sẽ bị trừ điểm chuyên cần đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_11','V313','阮明',11,'我会定好闹钟准时送达，不会错过截止时间。','wǒ huì dìng hǎo nào zhōng zhǔn shí sòng dá， bú huì cuò guò jié zhǐ shí jiān。','Em sẽ đặt báo thức để nộp đúng giờ, không bỏ lỡ hạn chót đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_12','V313','老师',12,'作业提交后我会优先批改，有错误再单独跟你讲解。','zuò yè tí jiāo hòu wǒ huì yōu xiān pī gǎi， yǒu cuò wù zài dān dú gēn nǐ jiǎng jiě。','Sau khi em nộp bài thầy/cô sẽ chấm ưu tiên, có chỗ nào sai thầy/cô sẽ giảng riêng cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_13','V313','阮明',13,'太感谢老师体谅我的身体状况，我一定认真完成作业。','tài gǎn xiè lǎo shī tǐ liàng wǒ de shēn tǐ zhuàng kuàng， wǒ yí dìng rèn zhēn wán chéng zuò yè。','Em cảm ơn thầy/cô rất nhiều vì đã thông cảm cho tình trạng sức khỏe của em, em chắc chắn sẽ làm bài thật nghiêm túc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_14','V313','老师',14,'好好休息，别过度熬夜伤身体。','hǎo hǎo xiū xī， bié guò dù áo yè shāng shēn tǐ。','Nghỉ ngơi cho khỏe đi, đừng thức khuya quá mà hại sức khỏe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_15','V313','阮明',15,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Dạ vâng, em cảm ơn thầy/cô ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT314','S107','Trao đổi phân công trong làm việc nhóm',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V314','SIT314','P1','suon_se','tuy_y',NULL,'国内大学小组作业讲究全员参与、公平分工，团队协作度是评分的重要标准。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_01','V314','张浩',1,'我们小组作业还没分工，今天赶紧定一下吧？','wǒ men xiǎo zǔ zuò yè hái méi fēn gōng， jīn tiān gǎn jǐn dìng yī xià ba？','Nhóm mình vẫn chưa phân công gì cả, hôm nay chốt luôn nhé?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_02','V314','阮明',2,'好呀，我们按各自特长分工，效率会更高。','hǎo ya， wǒ men àn gè zì tè cháng fēn gōng， xiào lǜ huì gèng gāo。','Ừ được đó, mình chia việc theo sở trường của mỗi người, làm vậy hiệu quả hơn.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_03','V314','张浩',3,'我擅长搜集资料和写文稿，PPT制作你可以吗？','wǒ shàn cháng sōu jí zī liào hé xiě wén gǎo，PPT zhì zuò nǐ kě yǐ ma？','Tớ giỏi tìm tài liệu với viết nội dung, còn làm PPT cậu ổn không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_04','V314','阮明',4,'没问题，我很擅长做PPT，这个交给我。','méi wèn tí， wǒ hěn shàn cháng zuò PPT， zhè ge jiāo gěi wǒ。','Không thành vấn đề, tớ làm PPT khá tốt, để đó cho tớ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_05','V314','张浩',5,'那最后课堂汇报，我们两个人一起配合。','nà zuì hòu kè táng huì bào， wǒ men liǎng gè rén yì qǐ pèi hé。','Vậy đến lúc thuyết trình trên lớp thì hai đứa mình phối hợp với nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_06','V314','阮明',6,'可以，我们做完互相检查，避免出错。','kě yǐ， wǒ men zuò wán hù xiāng jiǎn chá， bì miǎn chū cuò。','Được, làm xong mình kiểm tra chéo lại cho nhau, tránh sai sót.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_07','V314','张浩',7,'完美，那我们各自开工！','wán měi， nà wǒ men gè zì kāi gōng！','Tuyệt vời, vậy mỗi đứa bắt tay vào làm phần của mình thôi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT315','S106','Thuyết trình trước lớp, xin lỗi vì thiếu chuẩn bị',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V315','SIT315','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂展示允许轻微失误，主动诚恳认错、复盘问题，不会大幅扣分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_01','V315','阮明',1,'老师、各位同学，非常抱歉，我本次的课堂汇报准备不足。','lǎo shī、 gè wèi tóng xué， fēi cháng bào qiàn， wǒ běn cì de kè táng huì bào zhǔn bèi bù zú。','Thưa thầy/cô và các bạn, em rất xin lỗi vì bài thuyết trình lần này em chuẩn bị chưa kỹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_02','V315','老师',2,'没关系，正常展示就好，说说问题在哪？','méi guān xì， zhèng cháng zhǎn shì jiù hǎo， shuō shuō wèn tí zài nǎ？','Không sao, cứ trình bày bình thường thôi, nói xem vấn đề nằm ở đâu?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_03','V315','阮明',3,'我前期资料整理不够细致，内容细节缺失很多。','wǒ qián qī zī liào zhěng lǐ bù gòu xì zhì， nèi róng xì jié quē shī hěn duō。','Giai đoạn đầu em chuẩn bị tài liệu chưa kỹ, nên nội dung thiếu khá nhiều chi tiết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_04','V315','阮明',4,'这是我的疏忽，没有提前充分打磨内容。','zhè shì wǒ de shū hū， méi yǒu tí qián chōng fèn dǎ mó nèi róng。','Đây là sơ suất của em, em đã không dành đủ thời gian trau chuốt nội dung trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_05','V315','老师',5,'敢于正视问题就很好，下次提前准备充分就行。','gǎn yú zhèng shì wèn tí jiù hěn hǎo， xià cì tí qián zhǔn bèi chōng fèn jiù xíng。','Dám nhìn thẳng vào vấn đề là tốt rồi, lần sau chuẩn bị kỹ trước là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_06','V315','阮明',6,'我记住了，感谢老师和同学们的包容！','wǒ jì zhù le， gǎn xiè lǎo shī hé tóng xué men de bāo róng！','Em ghi nhớ rồi ạ, em cảm ơn thầy/cô và các bạn đã thông cảm!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT316','S107','Hỏi lại bài giảng chưa hiểu với giáo viên',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V316','SIT316','P1','suon_se','ban_chinh_thuc',NULL,'国内高校老师普遍鼓励课后答疑，主动提问是被认可的良好学习习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_01','V316','阮明',1,'老师您好，刚才课堂讲的知识点我没太听懂。','lǎo shī nín hǎo， gāng cái kè táng jiǎng de zhī shí diǎn wǒ méi tài tīng dǒng。','Chào thầy/cô, phần kiến thức thầy/cô vừa giảng em chưa hiểu lắm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_02','V316','老师',2,'哪一部分不理解？我再给你讲一遍。','nǎ yī bù fèn bù lǐ jiě？ wǒ zài gěi nǐ jiǎng yī biàn。','Phần nào em chưa hiểu? Thầy/cô giảng lại cho em nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_03','V316','阮明',3,'就是公式的运用逻辑，我还是有点模糊。','jiù shì gōng shì de yùn yòng luó jí， wǒ hái shì yǒu diǎn mó hú。','Là logic áp dụng công thức ấy ạ, em vẫn còn hơi mơ hồ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_04','V316','老师',4,'没事，我简单梳理一遍，你仔细听。','méi shì， wǒ jiǎn dān shū lǐ yī biàn， nǐ zǐ xì tīng。','Không sao, thầy/cô sẽ tóm lại một lượt, em nghe kỹ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_05','V316','阮明',5,'好的，麻烦老师费心讲解了。','hǎo de， má fán lǎo shī fèi xīn jiǎng jiě le。','Dạ vâng, phiền thầy/cô giảng giải giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_06','V316','老师',6,'不懂就问是好习惯，不用不好意思。','bù dǒng jiù wèn shì hǎo xí guàn， bù yòng bù hǎo yì sī。','Không hiểu thì hỏi là thói quen tốt, đừng ngại nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_07','V316','阮明',7,'听完我完全懂了，谢谢老师！','tīng wán wǒ wán quán dǒng le， xiè xiè lǎo shī！','Nghe xong em hiểu hết rồi ạ, em cảm ơn thầy/cô!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT317','S108','Hỏi quy định phòng thi',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V317','SIT317','P1','suon_se','chinh_thuc',NULL,'国内标准化考试严禁携带私人物品入场，违规携带会被判定为考试违纪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_01','V317','阮明',1,'老师您好，我想咨询一下本次期末考试的考场规则。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià běn cì qī mò kǎo shì de kǎo chǎng guī zé。','Chào thầy/cô, em muốn hỏi về quy chế phòng thi của kỳ thi cuối kỳ lần này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_02','V317','监考老师',2,'你有不清楚的地方可以直接提问。','nǐ yǒu bù qīng chǔ de dì fāng kě yǐ zhí jiē tí wèn。','Chỗ nào em chưa rõ thì cứ hỏi trực tiếp nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_03','V317','阮明',3,'请问考试期间可以自带草稿纸和文具吗？','qǐng wèn kǎo shì qī jiān kě yǐ zì dài cǎo gǎo zhǐ hé wén jù ma？','Cho em hỏi trong lúc thi có được mang theo giấy nháp và dụng cụ học tập riêng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_04','V317','监考老师',4,'不可以，考场会统一发放所有考试用品。','bù kě yǐ， kǎo chǎng huì tǒng yī fā fàng suǒ yǒu kǎo shì yòng pǐn。','Không được, phòng thi sẽ phát đầy đủ mọi vật dụng thi thống nhất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_05','V317','阮明',5,'那电子手表需要摘下来存放吗？','nà diàn zi shǒu biǎo xū yào zhāi xià lái cún fàng ma？','Vậy đồng hồ điện tử có cần tháo ra để riêng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_06','V317','监考老师',6,'是的，所有电子设备都需统一收纳。','shì de， suǒ yǒu diàn zi shè bèi dōu xū tǒng yī shōu nà。','Đúng vậy, tất cả thiết bị điện tử đều phải cất riêng theo quy định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_07','V317','阮明',7,'我清楚所有规则了，谢谢老师！','wǒ qīng chǔ suǒ yǒu guī zé le， xiè xiè lǎo shī！','Em đã nắm rõ hết quy định rồi ạ, em cảm ơn thầy/cô!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT318','S108','Xem điểm thi trên hệ thống bị sai, hỏi lại giáo viên',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V318','SIT318','P1','twist','ban_chinh_thuc',NULL,'校园教务系统偶有BUG，学生成绩最终以老师线下备案记录为准，可随时核实修正。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_01','V318','阮明',1,'老师您好，我想核实一下我的课程期末成绩。','lǎo shī nín hǎo， wǒ xiǎng hé shí yī xià wǒ de kè chéng qī mò chéng jì。','Chào thầy/cô, em muốn kiểm tra lại điểm cuối kỳ môn học của em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_02','V318','老师',2,'好的，具体是什么问题？','hǎo de， jù tǐ shì shén me wèn tí？','Được, cụ thể vấn đề là gì?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_03','V318','阮明',3,'我所有作业、考勤、考试都正常完成，但系统显示无成绩。','wǒ suǒ yǒu zuò yè、 kǎo qín、 kǎo shì dōu zhèng cháng wán chéng， dàn xì tǒng xiǎn shì wú chéng jì。','Em đã hoàn thành đầy đủ bài tập, điểm danh, thi cử, nhưng hệ thống lại hiện là chưa có điểm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_04','V318','老师',4,'应该是教务系统录入卡顿，出现数据异常了。','yīng gāi shì jiào wù xì tǒng lù rù kǎ dùn， chū xiàn shù jù yì cháng le。','Chắc là hệ thống giáo vụ nhập liệu bị trục trặc, nên dữ liệu bị lỗi rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_05','V318','阮明',5,'我一直担心是自己漏交作业，心里很不安。','wǒ yì zhí dān xīn shì zì jǐ lòu jiāo zuò yè， xīn lǐ hěn bù ān。','Em cứ lo là do mình bỏ sót bài nào chưa nộp, trong lòng bất an lắm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_06','V318','老师',6,'你放心，我手动核对备案，重新给你录入成绩。','nǐ fàng xīn， wǒ shǒu dòng hé duì bèi àn， chóng xīn gěi nǐ lù rù chéng jì。','Em cứ yên tâm, thầy/cô sẽ tự tay đối chiếu lại hồ sơ và nhập lại điểm cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_07','V318','阮明',7,'太感谢老师帮忙处理了！','tài gǎn xiè lǎo shī bāng máng chǔ lǐ le！','Em cảm ơn thầy/cô rất nhiều vì đã giúp em xử lý chuyện này ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT319','S108','Xin phúc khảo bài thi',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V319','SIT319','P1','suon_se','chinh_thuc',NULL,'国内高校成绩复核仅核查卷面分数统计错误，不重新评判答题内容，是正规申诉渠道；复核结果统一公示，具备官方效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_01','V319','阮明',1,'老师您好，今天来找您，是想正式提交本次期末试卷成绩复核申请。','lǎo shī nín hǎo， jīn tiān lái zhǎo nín， shì xiǎng zhèng shì tí jiāo běn cì qī mò shì juàn chéng jì fù hé shēn qǐng。','Chào thầy/cô, hôm nay em đến gặp thầy/cô là để chính thức nộp đơn xin phúc khảo điểm thi cuối kỳ lần này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_02','V319','老师',2,'先坐，我先跟你确认，你清楚学校成绩复核的具体范围和规则吗？','xiān zuò， wǒ xiān gēn nǐ què rèn， nǐ qīng chǔ xué xiào chéng jì fù hé de jù tǐ fàn wéi hé guī zé ma？','Ngồi xuống đã, để thầy/cô xác nhận trước, em đã nắm rõ phạm vi và quy định phúc khảo điểm của trường chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_03','V319','阮明',3,'只听说可以核对卷面总分统计，不能重新评判答题内容，细节了解不多。','zhǐ tīng shuō kě yǐ hé duì juàn miàn zǒng fēn tǒng jì， bù néng chóng xīn píng pàn dá tí nèi róng， xì jié liǎo jiě bù duō。','Em chỉ nghe nói là có thể đối chiếu lại tổng điểm bài thi, chứ không được chấm lại nội dung bài làm, chi tiết thì em chưa nắm rõ lắm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_04','V319','老师',4,'没错，复核仅检查每道小题得分相加是否计算错误，不会更改主观题打分。','méi cuò， fù hé jǐn jiǎn chá měi dào xiǎo tí dé fēn xiāng jiā shì fǒu jì suàn cuò wù， bú huì gēng gǎi zhǔ guān tí dǎ fēn。','Đúng vậy, phúc khảo chỉ kiểm tra xem cộng điểm từng câu có bị tính sai hay không, chứ không thay đổi điểm phần tự luận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_05','V319','阮明',5,'我自己对照参考答案预估的分数，和最终系统录入成绩差距很大，心里比较疑惑。','wǒ zì jǐ duì zhào cān kǎo dá àn yù gū de fēn shù， hé zuì zhōng xì tǒng lù rù chéng jì chā jù hěn dà， xīn lǐ bǐ jiào yí huò。','Em tự đối chiếu với đáp án tham khảo để ước tính điểm, thấy chênh lệch khá nhiều so với điểm hệ thống ghi nhận, nên em thấy khá thắc mắc ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_06','V319','老师',6,'我理解你的顾虑，我可以协助你向学院教学办提交官方书面复核申请。','wǒ lǐ jiě nǐ de gù lǜ， wǒ kě yǐ xié zhù nǐ xiàng xué yuàn jiào xué bàn tí jiāo guān fāng shū miàn fù hé shēn qǐng。','Thầy/cô hiểu băn khoăn của em, thầy/cô có thể hỗ trợ em nộp đơn phúc khảo chính thức bằng văn bản lên văn phòng đào tạo của khoa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_07','V319','阮明',7,'提交申请的时候，需要附带什么证明材料，填写专用表格吗？','tí jiāo shēn qǐng de shí hòu， xū yào fù dài shén me zhèng míng cái liào， tián xiě zhuān yòng biǎo gé ma？','Khi nộp đơn thì em có cần đính kèm giấy tờ chứng minh gì không ạ, có phải điền vào mẫu đơn riêng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_08','V319','老师',8,'我这边给你打印统一的复核申请表，填写姓名、学号、科目和申请理由即可。','wǒ zhè biān gěi nǐ dǎ yìn tǒng yī de fù hé shēn qǐng biǎo， tián xiě xìng míng、 xué hào、 kē mù hé shēn qǐng lǐ yóu jí kě。','Thầy/cô sẽ in cho em mẫu đơn phúc khảo thống nhất, em chỉ cần điền họ tên, mã số sinh viên, môn học và lý do xin phúc khảo là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_09','V319','阮明',9,'请问提交申请表之后，大概多久可以出具最终复核结果呢？','qǐng wèn tí jiāo shēn qǐng biǎo zhī hòu， dà gài duō jiǔ kě yǐ chū jù zuì zhōng fù hé jié guǒ ne？','Cho em hỏi sau khi nộp đơn thì khoảng bao lâu sẽ có kết quả phúc khảo cuối cùng ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_10','V319','老师',10,'学院统一收集申请，三个工作日内完成卷面核对并公示修正后的成绩。','xué yuàn tǒng yī shōu jí shēn qǐng， sān gè gōng zuò rì nèi wán chéng juàn miàn hé duì bìng gōng shì xiū zhèng hòu de chéng jì。','Khoa sẽ tập hợp đơn thống nhất, trong vòng ba ngày làm việc sẽ hoàn tất đối chiếu bài thi và công bố điểm đã điều chỉnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_11','V319','阮明',11,'如果复核后分数有调整，系统成绩会同步更新对吧？','rú guǒ fù hé hòu fēn shù yǒu tiáo zhěng， xì tǒng chéng jì huì tóng bù gēng xīn duì ba？','Nếu sau phúc khảo điểm có thay đổi thì điểm trên hệ thống sẽ được cập nhật đồng bộ đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_12','V319','老师',12,'是的，核对出计算失误会直接修改教务系统内你的期末分数。','shì de， hé duì chū jì suàn shī wù huì zhí jiē xiū gǎi jiào wù xì tǒng nèi nǐ de qī mò fēn shù。','Đúng vậy, nếu phát hiện tính sai điểm thì sẽ cập nhật ngay điểm cuối kỳ của em trong hệ thống giáo vụ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_13','V319','阮明',13,'我现在填写申请表，麻烦老师帮忙转交教学办。','wǒ xiàn zài tián xiě shēn qǐng biǎo， má fán lǎo shī bāng máng zhuǎn jiāo jiào xué bàn。','Vậy giờ em điền đơn luôn, phiền thầy/cô giúp em chuyển lên văn phòng đào tạo ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_14','V319','老师',14,'放心，流程我全程跟进，有结果第一时间通知你。','fàng xīn， liú chéng wǒ quán chéng gēn jìn， yǒu jié guǒ dì yī shí jiān tōng zhī nǐ。','Em cứ yên tâm, thầy/cô sẽ theo sát toàn bộ quy trình, có kết quả sẽ báo cho em ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_15','V319','阮明',15,'辛苦老师费心办理，非常感谢！','xīn kǔ lǎo shī fèi xīn bàn lǐ， fēi cháng gǎn xiè！','Em cảm ơn thầy/cô đã vất vả giúp em xử lý việc này ạ, em cảm kích lắm!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT320','S106','Mượn vở ghi chép của bạn vì nghỉ học',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V320','SIT320','P1','suon_se','tuy_y',NULL,'同学之间互借笔记、补全知识点是国内大学校园最普遍的互助行为。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_01','V320','阮明',1,'琪琪，我昨天请假缺课了，能借我一下你的课堂笔记吗？','qí qí， wǒ zuó tiān qǐng jià quē kè le， néng jiè wǒ yī xià nǐ de kè táng bǐ jì ma？','Kỳ Kỳ ơi, hôm qua tớ xin nghỉ nên bỏ lỡ buổi học, cho tớ mượn vở ghi chép của cậu được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_02','V320','李琪',2,'当然可以，我记得特别详细，重难点都标出来了。','dāng rán kě yǐ， wǒ jì de tè bié xiáng xì， zhòng nán diǎn dōu biāo chū lái le。','Được chứ, tớ ghi khá chi tiết đấy, chỗ nào quan trọng khó hiểu tớ đều đánh dấu hết rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_03','V320','阮明',3,'太好了，我刚好错过最重要的知识点。','tài hǎo le， wǒ gāng hǎo cuò guò zuì zhòng yào de zhī shí diǎn。','Tuyệt quá, tớ vừa lỡ đúng phần kiến thức quan trọng nhất luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_04','V320','李琪',4,'没事，你慢慢看，看完再还我就行。','méi shì， nǐ màn màn kàn， kàn wán zài hái wǒ jiù xíng。','Không sao đâu, cậu cứ xem từ từ, xem xong trả lại tớ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_05','V320','阮明',5,'太感谢了，有不懂的地方我再问你哈。','tài gǎn xiè le， yǒu bù dǒng de dì fāng wǒ zài wèn nǐ hā。','Cảm ơn cậu nhiều nha, chỗ nào không hiểu tớ hỏi lại cậu nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_06','V320','李琪',6,'没问题，同学之间本来就该互相帮忙。','méi wèn tí， tóng xué zhī jiān běn lái jiù gāi hù xiāng bāng máng。','Không vấn đề gì, bạn bè với nhau vốn dĩ phải giúp đỡ nhau mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_07','V320','阮明',7,'真的太贴心啦！','zhēn de tài tiē xīn la！','Cậu tốt bụng quá đi mất!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT321','S109','Đặt lịch khám qua ứng dụng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V321','SIT321','P1','twist','ban_chinh_thuc',NULL,'国内公立医院热门科室号源紧张，必须提前线上预约，现场基本无剩余号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_01','V321','阮明',1,'你好，我想在APP上预约今天的内科门诊。','nǐ hǎo， wǒ xiǎng zài APP shàng yù yuē jīn tiān de nèi kē mén zhěn。','Chào chị, tôi muốn đặt lịch khám nội khoa hôm nay trên ứng dụng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_02','V321','客服',2,'您好，请问您需要普通号还是专家号？','nín hǎo， qǐng wèn nín xū yào pǔ tōng hào hái shì zhuān jiā hào？','Chào anh, anh muốn khám số thường hay số chuyên gia ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_03','V321','阮明',3,'普通号就可以，我只是轻微头晕乏力。','pǔ tōng hào jiù kě yǐ， wǒ zhǐ shì qīng wēi tóu yūn fá lì。','Số thường là được rồi, tôi chỉ hơi chóng mặt với mệt mỏi thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_04','V321','客服',4,'非常抱歉，今天内科普通号已经全部约满了。','fēi cháng bào qiàn， jīn tiān nèi kē pǔ tōng hào yǐ jīng quán bù yuē mǎn le。','Tôi xin lỗi, hôm nay số thường khoa nội đã kín hết rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_05','V321','阮明',5,'这样啊，那明天的号还有空位吗？','zhè yàng a， nà míng tiān de hào hái yǒu kòng wèi ma？','Vậy à, thế ngày mai còn suất trống không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_06','V321','客服',6,'明天上午号源充足，我可以指导您预约。','míng tiān shàng wǔ hào yuán chōng zú， wǒ kě yǐ zhǐ dǎo nín yù yuē。','Sáng mai còn nhiều suất lắm, để tôi hướng dẫn anh đặt lịch nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_07','V321','阮明',7,'好的，麻烦你教我操作一下！','hǎo de， má fán nǐ jiāo wǒ cāo zuò yī xià！','Được đó, phiền chị chỉ tôi thao tác với!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT322','S109','Đăng ký khoa khám phù hợp tại quầy',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V322','SIT322','P1','suon_se','ban_chinh_thuc',NULL,'医院科室划分精细，身体不适不确定科室，可咨询挂号窗口精准分诊，避免挂错号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_01','V322','阮明',1,'你好，我最近经常头晕、睡眠不好，该挂什么科室？','nǐ hǎo， wǒ zuì jìn jīng cháng tóu yūn、 shuì mián bù hǎo， gāi guà shén me kē shì？','Chào chị, dạo này tôi hay bị chóng mặt, ngủ không ngon, vậy nên khám khoa nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_02','V322','工作人员',2,'你这个症状挂神经内科是最合适的。','nǐ zhè ge zhèng zhuàng guà shén jīng nèi kē shì zuì hé shì de。','Triệu chứng của anh thì khám khoa nội thần kinh là hợp nhất đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_03','V322','阮明',3,'那帮我挂一个今天下午的普通门诊吧。','nà bāng wǒ guà yí gè jīn tiān xià wǔ de pǔ tōng mén zhěn ba。','Vậy chị đăng ký giúp tôi khám thường chiều nay nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_04','V322','工作人员',4,'好的，请问使用医保结算还是自费？','hǎo de， qǐng wèn shǐ yòng yī bǎo jié suàn hái shì zì fèi？','Được ạ, anh thanh toán bằng bảo hiểm y tế hay tự chi trả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_05','V322','阮明',5,'我用学生医保结算。','wǒ yòng xué shēng yī bǎo jié suàn。','Tôi dùng bảo hiểm y tế học sinh sinh viên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_06','V322','工作人员',6,'已为您挂号成功，请前往二楼诊室等候。','yǐ wèi nín guà hào chéng gōng， qǐng qián wǎng èr lóu zhěn shì děng hòu。','Đã đăng ký thành công cho anh rồi, mời anh lên phòng khám tầng hai chờ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_07','V322','阮明',7,'好的，谢谢你！','hǎo de， xiè xiè nǐ！','Được rồi, cảm ơn chị nha!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT323','S109','Miêu tả triệu chứng với bác sĩ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V323','SIT323','P1','suon_se','ban_chinh_thuc',NULL,'就医时清晰说明症状时长、频率和状态，能帮助医生快速、精准判断病情。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_01','V323','阮明',1,'医生您好，我这三四天一直头晕、浑身没力气。','yī shēng nín hǎo， wǒ zhè sān sì tiān yì zhí tóu yūn、 hún shēn méi lì qì。','Chào bác sĩ, mấy hôm nay tôi cứ bị chóng mặt, người thì mệt lử không còn sức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_02','V323','医生',2,'是一直晕，还是偶尔一阵一阵的？','shì yì zhí yūn， hái shì ǒu ěr yī zhèn yī zhèn de？','Là chóng mặt liên tục hay thỉnh thoảng mới bị từng cơn vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_03','V323','阮明',3,'偶尔发作，尤其是晚上，还经常失眠睡不着。','ǒu ěr fā zuò， yóu qí shì wǎn shàng， hái jīng cháng shī mián shuì bù zhe。','Thỉnh thoảng thôi ạ, nhất là buổi tối, với lại tôi cũng hay mất ngủ không ngủ được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_04','V323','医生',4,'有没有发烧、恶心或者其他不舒服？','yǒu méi yǒu fā shāo、 ě xīn huò zhě qí tā bù shū fú？','Có bị sốt, buồn nôn hay khó chịu gì khác không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_05','V323','阮明',5,'没有的，就只有头晕和乏力这两个症状。','méi yǒu de， jiù zhǐ yǒu tóu yūn hé fá lì zhè liǎng gè zhèng zhuàng。','Không có ạ, chỉ có hai triệu chứng chóng mặt với mệt mỏi thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_06','V323','医生',6,'我大概清楚了，我给你简单检查一下。','wǒ dà gài qīng chǔ le， wǒ gěi nǐ jiǎn dān jiǎn chá yī xià。','Tôi đại khái nắm được rồi, để tôi khám sơ qua cho em nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_07','V323','阮明',7,'好的，麻烦医生了！','hǎo de， má fán yī shēng le！','Vâng ạ, phiền bác sĩ giúp em!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT324','S109','Báo dị ứng thuốc trước khi được kê đơn',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V324','SIT324','P1','suon_se','chinh_thuc',NULL,'国内就医开药必须主动申报过敏史，是保障用药安全的重要医疗规范。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_01','V324','阮明',1,'医生，我需要提前告知您我的药物过敏史。','yī shēng， wǒ xū yào tí qián gào zhī nín wǒ de yào wù guò mǐn shǐ。','Thưa bác sĩ, tôi cần báo trước cho bác sĩ biết tiền sử dị ứng thuốc của tôi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_02','V324','医生',2,'好的，你具体对哪种药物过敏？','hǎo de， nǐ jù tǐ duì nǎ zhǒng yào wù guò mǐn？','Được, cụ thể anh dị ứng với loại thuốc nào?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_03','V324','阮明',3,'我对青霉素类药物过敏，绝对不能使用这类药。','wǒ duì qīng méi sù lèi yào wù guò mǐn， jué duì bù néng shǐ yòng zhè lèi yào。','Tôi dị ứng với các loại thuốc nhóm penicillin, tuyệt đối không được dùng loại này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_04','V324','医生',4,'我记下了，开药时会完全避开致敏药物。','wǒ jì xià le， kāi yào shí huì wán quán bì kāi zhì mǐn yào wù。','Tôi đã ghi nhận rồi, khi kê đơn tôi sẽ tránh hoàn toàn những thuốc gây dị ứng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_05','V324','阮明',5,'我之前过敏反应很严重，所以特别谨慎。','wǒ zhī qián guò mǐn fǎn yìng hěn yán zhòng， suǒ yǐ tè bié jǐn shèn。','Trước đây phản ứng dị ứng của tôi rất nặng, nên tôi đặc biệt cẩn thận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_06','V324','医生',6,'我明白，用药安全是第一位的，你放心。','wǒ míng bái， yòng yào ān quán shì dì yī wèi de， nǐ fàng xīn。','Tôi hiểu, an toàn khi dùng thuốc là ưu tiên hàng đầu, anh cứ yên tâm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_07','V324','阮明',7,'感谢医生细心负责！','gǎn xiè yī shēng xì xīn fù zé！','Xin cảm ơn bác sĩ đã chu đáo và tận tâm!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT325','S110','Mua thuốc theo đơn tại nhà thuốc',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V325','SIT325','P1','suon_se','ban_chinh_thuc',NULL,'医院取药后，药师会逐一告知用法、用量、保存方式，务必严格遵照执行。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_01','V325','阮明',1,'你好，这是我的处方单，麻烦帮我取一下药。','nǐ hǎo， zhè shì wǒ de chǔ fāng dān， má fán bāng wǒ qǔ yī xià yào。','Chào chị, đây là đơn thuốc của tôi, phiền chị lấy thuốc giúp tôi với.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_02','V325','药师',2,'好的，请稍等，我核对一下药品信息。','hǎo de， qǐng shāo děng， wǒ hé duì yī xià yào pǐn xìn xī。','Được ạ, anh chờ một chút, tôi kiểm tra lại thông tin thuốc đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_03','V325','阮明',3,'没问题，这些药具体怎么服用呀？','méi wèn tí， zhè xiē yào jù tǐ zěn me fú yòng ya？','Không sao, mấy loại thuốc này thì uống thế nào vậy chị?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_04','V325','药师',4,'都是一日三次，饭后温水服用，说明书也有标注。','dōu shì yī rì sān cì， fàn hòu wēn shuǐ fú yòng， shuō míng shū yě yǒu biāo zhù。','Đều là uống ngày ba lần, sau bữa ăn với nước ấm, trên tờ hướng dẫn cũng có ghi rõ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_05','V325','阮明',5,'需要低温冷藏保存吗？','xū yào dī wēn lěng cáng bǎo cún ma？','Có cần bảo quản lạnh không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_06','V325','药师',6,'不用，常温避光存放就可以。','bù yòng， cháng wēn bì guāng cún fàng jiù kě yǐ。','Không cần, để ở nhiệt độ thường, tránh ánh sáng là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_07','V325','阮明',7,'明白了，谢谢药师！','míng bái le， xiè xiè yào shī！','Tôi hiểu rồi, cảm ơn dược sĩ nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT326','S109','Hỏi bảo hiểm có chi trả loại thuốc này không',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V326','SIT326','P1','twist','ban_chinh_thuc',NULL,'国内医保仅覆盖基础刚需药品，进口药、高端特效药大多需要个人自费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_01','V326','阮明',1,'你好，我想问一下我开的这些药能不能医保报销？','nǐ hǎo， wǒ xiǎng wèn yī xià wǒ kāi de zhè xiē yào néng bù néng yī bǎo bào xiāo？','Chào chị, tôi muốn hỏi mấy loại thuốc bác sĩ kê cho tôi có được bảo hiểm y tế chi trả không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_02','V326','工作人员',2,'我帮你查询一下药品医保目录。','wǒ bāng nǐ chá xún yī xià yào pǐn yī bǎo mù lù。','Để tôi tra giúp anh trong danh mục thuốc bảo hiểm y tế nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_03','V326','工作人员',3,'查到了，其中两款基础药可以报销，一款进口药不行。','chá dào le， qí zhōng liǎng kuǎn jī chǔ yào kě yǐ bào xiāo， yī kuǎn jìn kǒu yào bù xíng。','Tra ra rồi, trong đó hai loại thuốc cơ bản được chi trả, còn một loại thuốc nhập khẩu thì không.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_04','V326','阮明',4,'这样啊，进口药需要全额自费是吗？','zhè yàng a， jìn kǒu yào xū yào quán é zì fèi shì ma？','Vậy à, thuốc nhập khẩu thì phải tự trả toàn bộ đúng không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_05','V326','工作人员',5,'对的，进口特效药不在医保报销范围内。','duì de， jìn kǒu tè xiào yào bù zài yī bǎo bào xiāo fàn wéi nèi。','Đúng vậy, thuốc đặc trị nhập khẩu không nằm trong phạm vi bảo hiểm y tế chi trả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_06','V326','阮明',6,'我了解了，那麻烦你分开结算吧。','wǒ liǎo jiě le， nà má fán nǐ fēn kāi jié suàn ba。','Tôi hiểu rồi, vậy phiền chị tính riêng ra giúp tôi nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_07','V326','工作人员',7,'没问题，我帮你区分清楚。','méi wèn tí， wǒ bāng nǐ qū fēn qīng chǔ。','Không thành vấn đề, tôi sẽ tách rõ ràng cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT327','S109','Đặt lịch tái khám',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V327','SIT327','P1','suon_se','ban_chinh_thuc',NULL,'慢性病、短期病症恢复都需要复诊，携带既往病历是医院常规要求。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_01','V327','阮明',1,'你好，我想预约下周的复诊门诊。','nǐ hǎo， wǒ xiǎng yù yuē xià zhōu de fù zhěn mén zhěn。','Chào chị, tôi muốn đặt lịch tái khám vào tuần sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_02','V327','工作人员',2,'可以的，你想预约周几的时间段？','kě yǐ de， nǐ xiǎng yù yuē zhōu jǐ de shí jiān duàn？','Được ạ, anh muốn đặt vào khung giờ thứ mấy trong tuần?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_03','V327','阮明',3,'下周二下午吧，我下午没有课程安排。','xià zhōu èr xià wǔ ba， wǒ xià wǔ méi yǒu kè chéng ān pái。','Chiều thứ ba tuần sau nhé, chiều đó tôi không có lịch học.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_04','V327','工作人员',4,'好的，已经为你预约成功。','hǎo de， yǐ jīng wèi nǐ yù yuē chéng gōng。','Được rồi, tôi đã đặt lịch thành công cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_05','V327','阮明',5,'复诊的时候需要带这次的病历本吗？','fù zhěn de shí hòu xū yào dài zhè cì de bìng lì běn ma？','Khi tái khám tôi có cần mang theo sổ khám bệnh lần này không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_06','V327','工作人员',6,'需要的，务必携带方便医生对比恢复情况。','xū yào de， wù bì xié dài fāng biàn yī shēng duì bǐ huī fù qíng kuàng。','Cần đấy ạ, nhất định phải mang theo để bác sĩ tiện so sánh tình trạng hồi phục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_07','V327','阮明',7,'好的，我会妥善保管，谢谢你！','hǎo de， wǒ huì tuǒ shàn bǎo guǎn， xiè xiè nǐ！','Được rồi, tôi sẽ giữ cẩn thận, cảm ơn chị nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT328','S109','Xin giấy chứng nhận nghỉ bệnh cho trường',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V328','SIT328','P1','suon_se','chinh_thuc',NULL,'国内高校只认可医院机打正规病假证明，手写证明无效，是统一考勤制度。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_01','V328','阮明',1,'医生您好，我身体不适需要请假，麻烦您开具一张病假证明。','yī shēng nín hǎo， wǒ shēn tǐ bù shì xū yào qǐng jià， má fán nín kāi jù yī zhāng bìng jià zhèng míng。','Thưa bác sĩ, tôi thấy trong người không khỏe cần xin nghỉ, phiền bác sĩ viết giúp tôi một giấy chứng nhận nghỉ ốm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_02','V328','医生',2,'没问题，你需要请假休养几天？','méi wèn tí， nǐ xū yào qǐng jià xiū yǎng jǐ tiān？','Không vấn đề gì, em cần nghỉ dưỡng mấy ngày?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_03','V328','阮明',3,'我身体比较虚弱，想请假两天调整状态。','wǒ shēn tǐ bǐ jiào xū ruò， xiǎng qǐng jià liǎng tiān tiáo zhěng zhuàng tài。','Người em khá yếu, em muốn xin nghỉ hai ngày để điều chỉnh lại sức khỏe ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_04','V328','医生',4,'可以，我给你开具正规机打病假证明。','kě yǐ， wǒ gěi nǐ kāi jù zhèng guī jī dǎ bìng jià zhèng míng。','Được, tôi sẽ viết cho em giấy chứng nhận nghỉ ốm in chính thức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_05','V328','阮明',5,'证明上会标注就诊时间和请假时长对吧？','zhèng míng shàng huì biāo zhù jiù zhěn shí jiān hé qǐng jià shí cháng duì ba？','Giấy chứng nhận có ghi rõ thời gian khám và số ngày nghỉ đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_06','V328','医生',6,'是的，信息齐全，学校可以直接认可。','shì de， xìn xī qí quán， xué xiào kě yǐ zhí jiē rèn kě。','Đúng vậy, thông tin đầy đủ, nhà trường có thể chấp nhận trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_07','V328','阮明',7,'太感谢医生了！','tài gǎn xiè yī shēng le！','Em cảm ơn bác sĩ nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT329','S111','Tự giới thiệu trong buổi sinh hoạt đầu năm',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V329','SIT329','P1','suon_se','ban_chinh_thuc',NULL,'新生自我介绍简洁谦逊即可，"多多指教"是国内年轻人社交最常用的礼貌用语。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_01','V329','阮明',1,'大家好，我是阮明，一名来自越南的留学生，今年22岁。','dà jiā hǎo， wǒ shì ruǎn míng， yī míng lái zì yuè nán de liú xué shēng， jīn nián 22 suì。','Chào mọi người, mình là Nguyễn Minh, du học sinh đến từ Việt Nam, năm nay 22 tuổi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_02','V329','阮明',2,'目前就读于汉语言文学专业，非常开心加入这个集体。','mù qián jiù dú yú hàn yǔ yán wén xué zhuān yè， fēi cháng kāi xīn jiā rù zhè ge jí tǐ。','Hiện tại mình đang theo học chuyên ngành Ngôn ngữ và Văn học Trung Quốc, rất vui khi được gia nhập tập thể này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_03','V329','阮明',3,'平时我喜欢读书和慢跑，性格比较随和开朗。','píng shí wǒ xǐ huān dú shū hé màn pǎo， xìng gé bǐ jiào suí hé kāi lǎng。','Ngày thường mình thích đọc sách và chạy bộ, tính cách khá hòa đồng và cởi mở.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_04','V329','阮明',4,'我刚来中国，对这边的学习和生活还在适应中。','wǒ gāng lái zhōng guó， duì zhè biān de xué xí hé shēng huó hái zài shì yìng zhōng。','Mình mới sang Trung Quốc nên vẫn đang trong quá trình thích nghi với việc học và cuộc sống ở đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_05','V329','阮明',5,'往后希望可以和各位同学友好相处，互相学习、多多指教。','wǎng hòu xī wàng kě yǐ hé gè wèi tóng xué yǒu hǎo xiāng chǔ， hù xiāng xué xí、 duō duō zhǐ jiào。','Sau này mong được hòa thuận với các bạn, cùng nhau học hỏi, mong mọi người chỉ bảo thêm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_06','V329','辅导员',6,'欢迎阮明加入我们的大家庭！','huān yíng ruǎn míng jiā rù wǒ men de dà jiā tíng！','Hoan nghênh Nguyễn Minh gia nhập đại gia đình của chúng ta!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_07','V329','阮明',7,'谢谢大家！','xiè xiè dà jiā！','Em cảm ơn mọi người ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT330','S111','Hỏi thông tin liên hệ để giữ kết nối',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V330','SIT330','P1','suon_se','tuy_y',NULL,'微信是国内学生唯一主流沟通工具，学习通知、日常交友、小组协作均依托微信完成。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_01','V330','阮明',1,'今天认识你真的太开心了！我们可以加个微信吗？','jīn tiān rèn shí nǐ zhēn de tài kāi xīn le！ wǒ men kě yǐ jiā gè wēi xìn ma？','Hôm nay quen được bạn thật là vui quá! Chúng ta kết bạn Wechat được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_02','V330','林溪',2,'当然可以呀，以后我们就是同班同学了。','dāng rán kě yǐ ya， yǐ hòu wǒ men jiù shì tóng bān tóng xué le。','Được chứ, từ giờ tụi mình là bạn cùng lớp rồi mà.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_03','V330','阮明',3,'太好了，我刚来这边，以后还要多向你请教呢。','tài hǎo le， wǒ gāng lái zhè biān， yǐ hòu hái yào duō xiàng nǐ qǐng jiào ne。','Tuyệt quá, mình mới đến đây nên sau này còn phải nhờ bạn chỉ bảo nhiều nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_04','V330','林溪',4,'不用客气，我们互相帮忙、共同进步。','bù yòng kè qì， wǒ men hù xiāng bāng máng、 gòng tóng jìn bù。','Không cần khách sáo đâu, tụi mình giúp đỡ nhau cùng tiến bộ mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_05','V330','阮明',5,'那我扫你的二维码加好友哈。','nà wǒ sǎo nǐ de èr wéi mǎ jiā hǎo yǒu hā。','Vậy để mình quét mã QR kết bạn với bạn nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_06','V330','林溪',6,'好嘞，以后常联系，有空一起学习！','hǎo lei， yǐ hòu cháng lián xì， yǒu kòng yì qǐ xué xí！','Được đó, sau này thường xuyên liên lạc nhé, rảnh thì học cùng nhau!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_07','V330','阮明',7,'太好啦，谢谢你！','tài hǎo la， xiè xiè nǐ！','Thích quá, cảm ơn bạn nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT331','S112','Mời bạn cùng lớp đi ăn',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V331','SIT331','P1','suon_se','tuy_y',NULL,'中国大学生下课常结伴去食堂就餐，主动邀约同学吃饭是很常见的社交方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_01','V331','阮明',1,'下课啦，等下要不要一起去食堂吃饭啊？','xià kè la， děng xià yào bù yào yì qǐ qù shí táng chī fàn a？','Tan học rồi nè, lát nữa có muốn cùng đi ăn ở căn tin không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_02','V331','王浩',2,'可以呀，我正愁一个人吃饭没意思呢。','kě yǐ ya， wǒ zhèng chóu yí gè rén chī fàn méi yì si ne。','Được chứ, mình đang lo ăn một mình chán lắm luôn nè.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_03','V331','阮明',3,'食堂今天有米线，听说味道很不错的。','shí táng jīn tiān yǒu mǐ xiàn， tīng shuō wèi dào hěn bú cuò de。','Căn tin hôm nay có bún, nghe nói ngon lắm đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_04','V331','王浩',4,'刚好我也想吃米线，咱们现在就走吧。','gāng hǎo wǒ yě xiǎng chī mǐ xiàn， zán men xiàn zài jiù zǒu ba。','Đúng lúc mình cũng thèm ăn bún, đi luôn thôi nào.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_05','V331','阮明',5,'行，那我收拾一下书本，马上就好。','xíng， nà wǒ shōu shí yī xià shū běn， mǎ shàng jiù hǎo。','Ừ, để mình thu dọn sách vở chút, xong ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_06','V331','王浩',6,'没事，我在教室门口等你就行啦。','méi shì， wǒ zài jiào shì mén kǒu děng nǐ jiù xíng la。','Không sao, mình đứng đợi bạn ở cửa lớp là được rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_07','V331','阮明',7,'太感谢啦，有同学一起吃饭热闹多了。','tài gǎn xiè la， yǒu tóng xué yì qǐ chī fàn rè nào duō le。','Cảm ơn nhiều nha, có bạn cùng ăn vui hẳn lên luôn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT332','S112','Từ chối lời mời một cách lịch sự',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V332','SIT332','P1','suon_se','tuy_y',NULL,'拒绝他人邀约时，中国人习惯说明合理理由并主动提出下次赴约，显得有礼貌不扫兴。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_01','V332','林晓',1,'晚上我们宿舍一起去校外吃火锅，你也来吧？','wǎn shàng wǒ men sù shè yì qǐ qù xiào wài chī huǒ guō， nǐ yě lái ba？','Tối nay phòng ký túc xá tụi mình rủ nhau ra ngoài ăn lẩu, bạn đi cùng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_02','V332','阮明',2,'真的很谢谢你邀请我，不过我今晚不行呢。','zhēn de hěn xiè xiè nǐ yāo qǐng wǒ， bù guò wǒ jīn wǎn bù xíng ne。','Thật sự cảm ơn bạn đã rủ mình, nhưng tối nay mình không đi được rồi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_03','V332','林晓',3,'怎么啦，是有别的安排吗？','zěn me la， shì yǒu bié de ān pái ma？','Sao vậy, có việc gì khác à?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_04','V332','阮明',4,'我要完成一篇汉语作文，明天就得提交的。','wǒ yào wán chéng yī piān hàn yǔ zuò wén， míng tiān jiù dé tí jiāo de。','Mình phải hoàn thành một bài văn tiếng Trung, mai phải nộp rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_05','V332','林晓',5,'原来是这样，学习要紧，那下次再约吧。','yuán lái shì zhè yàng， xué xí yào jǐn， nà xià cì zài yuē ba。','Thì ra là vậy, học hành quan trọng hơn, vậy hẹn lần sau nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_06','V332','阮明',6,'好，下次我一定主动找你们，实在抱歉啦。','hǎo， xià cì wǒ yí dìng zhǔ dòng zhǎo nǐ men， shí zài bào qiàn la。','Ừ, lần sau nhất định mình sẽ chủ động rủ mọi người, thật ngại quá.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_07','V332','林晓',7,'没关系，学习完早点休息。','méi guān xì， xué xí wán zǎo diǎn xiū xī。','Không sao đâu, học xong thì nghỉ ngơi sớm nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT333','S112','Xin lỗi vì đến muộn buổi hẹn',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V333','SIT333','P1','twist','ban_chinh_thuc',NULL,'与人线下见面迟到，中国人会主动诚恳道歉，还会主动提出买单、请客作为补偿。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_01','V333','阮明',1,'实在对不起，我路上堵车，迟到二十分钟了。','shí zài duì bù qǐ， wǒ lù shàng dǔ chē， chí dào èr shí fēn zhōng le。','Thật sự xin lỗi, đường tắc xe nên tôi đến muộn hai mươi phút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_02','V333','陈悦',2,'没事，我也刚到一会儿，不用这么愧疚。','méi shì， wǒ yě gāng dào yī huì er， bù yòng zhè me kuì jiù。','Không sao đâu, tôi cũng vừa mới đến thôi, đừng áy náy quá vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_03','V333','阮明',3,'都怪我没提前出门，让你在这里干等啊。','dōu guài wǒ méi tí qián chū mén， ràng nǐ zài zhè lǐ gàn děng a。','Tại tôi không xuất phát sớm hơn, để bạn phải đợi ở đây.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_04','V333','陈悦',4,'还好，这家咖啡店座位挺多，我先点了两杯饮品。','hái hǎo， zhè jiā kā fēi diàn zuò wèi tǐng duō， wǒ xiān diǎn le liǎng bēi yǐn pǐn。','May là quán cà phê này nhiều chỗ ngồi, tôi gọi trước hai ly đồ uống rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_05','V333','阮明',5,'太不好意思了，这杯饮品我来付钱吧。','tài bù hǎo yì sī le， zhè bēi yǐn pǐn wǒ lái fù qián ba。','Ngại quá, để tôi trả tiền ly đồ uống này nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_06','V333','陈悦',6,'不用啦，下次见面你请我就可以咯。','bù yòng la， xià cì jiàn miàn nǐ qǐng wǒ jiù kě yǐ gē。','Thôi khỏi, lần sau gặp lại bạn mời tôi là được rồi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_07','V333','阮明',7,'好，下次我一定提前半小时出门，绝不迟到。','hǎo， xià cì wǒ yí dìng tí qián bàn xiǎo shí chū mén， jué bù chí dào。','Được, lần sau tôi nhất định sẽ xuất phát sớm nửa tiếng, không trễ nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT334','S112','Cảm ơn khi được giúp đỡ đặc biệt',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V334','SIT334','P1','suon_se','ban_chinh_thuc',NULL,'得到他人较大帮助后，中国人常会赠送小零食、小礼物表达谢意，不会只口头道谢。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_01','V334','阮明',1,'班长，这次真的太谢谢你帮我补办签证材料了。','bān zhǎng， zhè cì zhēn de tài xiè xiè nǐ bāng wǒ bǔ bàn qiān zhèng cái liào le。','Lớp trưởng ơi, lần này thật sự cảm ơn bạn đã giúp mình làm lại hồ sơ visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_02','V334','周宇',2,'小事而已，留学生办理手续本来就麻烦嘛。','xiǎo shì ér yǐ， liú xué shēng bàn lǐ shǒu xù běn lái jiù má fán ma。','Chuyện nhỏ thôi mà, du học sinh làm thủ tục vốn dĩ đã rắc rối rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_03','V334','阮明',3,'要是没有你带路讲解，我肯定跑好多趟。','yào shì méi yǒu nǐ dài lù jiǎng jiě， wǒ kěn dìng pǎo hǎo duō tàng。','Nếu không có bạn dẫn đường giải thích, chắc mình phải chạy đi chạy lại bao nhiêu lần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_04','V334','周宇',4,'不用放在心上，班里同学互相帮忙是应该的。','bù yòng fàng zài xīn shàng， bān lǐ tóng xué hù xiāng bāng máng shì yīng gāi de。','Đừng để bụng làm gì, bạn cùng lớp giúp đỡ nhau là chuyện nên làm mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_05','V334','阮明',5,'下周我买了家乡小零食，带给你尝尝吧。','xià zhōu wǒ mǎi le jiā xiāng xiǎo líng shí， dài gěi nǐ cháng cháng ba。','Tuần sau mình mua ít đồ ăn vặt quê nhà, mang cho bạn nếm thử nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_06','V334','周宇',6,'不用这么客气，能帮上忙我也很高兴。','bù yòng zhè me kè qì， néng bāng shàng máng wǒ yě hěn gāo xìng。','Không cần khách sáo vậy đâu, giúp được bạn mình cũng vui rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_07','V334','阮明',7,'一定要收下，不然我心里过意不去呢。','yí dìng yào shōu xià， bù rán wǒ xīn lǐ guò yì bù qù ne。','Bạn nhất định phải nhận, không thì mình áy náy trong lòng lắm đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT335','S113','Hỏi sở thích để tìm điểm chung với bạn mới',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V335','SIT335','P1','suon_se','tuy_y',NULL,'初次认识的年轻人会通过爱好聊天，找到共同兴趣能快速拉近彼此距离。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_01','V335','阮明',1,'课余时间你平时都喜欢做什么呀？','kè yú shí jiān nǐ píng shí dōu xǐ huān zuò shén me ya？','Ngoài giờ học bạn thường thích làm gì vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_02','V335','苏雯',2,'我有空就会追剧、出门爬山，你呢？','wǒ yǒu kòng jiù huì zhuī jù、 chū mén pá shān， nǐ ne？','Rảnh là mình xem phim, đi leo núi, còn bạn thì sao?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_03','V335','阮明',3,'我也很喜欢爬山，只是刚来还不熟悉周边路线。','wǒ yě hěn xǐ huān pá shān， zhǐ shì gāng lái hái bù shú xī zhōu biān lù xiàn。','Mình cũng rất thích leo núi, chỉ là mới đến nên chưa quen đường xá xung quanh thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_04','V335','苏雯',4,'学校附近有一座小山，周末可以一起去的。','xué xiào fù jìn yǒu yī zuò xiǎo shān， zhōu mò kě yǐ yì qǐ qù de。','Gần trường có một ngọn núi nhỏ, cuối tuần có thể đi cùng nhau đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_05','V335','阮明',5,'太棒了，我还担心找不到同好呢。','tài bàng le， wǒ hái dān xīn zhǎo bú dào tóng hào ne。','Tuyệt quá, mình còn đang lo không tìm được người cùng sở thích nữa chứ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_06','V335','苏雯',6,'那我们加个微信，周末约着一起出发吧。','nà wǒ men jiā gè wēi xìn， zhōu mò yuē zhe yì qǐ chū fā ba。','Vậy tụi mình kết bạn Wechat đi, cuối tuần hẹn nhau xuất phát nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_07','V335','阮明',7,'好呀，终于找到一样爱好的朋友啦。','hǎo ya， zhōng yú zhǎo dào yī yàng ài hào de péng yǒu la。','Được đó, cuối cùng cũng tìm được người bạn cùng sở thích rồi nè.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT336','S114','Đăng ký tham gia câu lạc bộ sinh viên',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V336','SIT336','P1','twist','ban_chinh_thuc',NULL,'国内高校社团统一在开学招新，多数社团有活动人数限制，需要提前登记报名。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_01','V336','阮明',1,'学姐你好，我想报名加入咱们汉服社团可以吗？','xué jiě nǐ hǎo， wǒ xiǎng bào míng jiā rù zán men hàn fú shè tuán kě yǐ ma？','Chào chị, em muốn đăng ký tham gia câu lạc bộ Hán phục của trường mình, được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_02','V336','学姐',2,'当然可以，先填一张信息登记表哦。','dāng rán kě yǐ， xiān tián yī zhāng xìn xī dēng jì biǎo ó。','Được chứ, em điền vào một tờ đăng ký thông tin trước nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_03','V336','阮明',3,'好的，我平时很喜欢中国传统服饰和文化。','hǎo de， wǒ píng shí hěn xǐ huān zhōng guó chuán tǒng fú shì hé wén huà。','Dạ vâng, em vốn rất thích trang phục truyền thống và văn hóa Trung Quốc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_04','V336','学姐',4,'咱们每周有线下活动，不过本周活动名额满了。','zán men měi zhōu yǒu xiàn xià huó dòng， bù guò běn zhōu huó dòng míng é mǎn le。','Câu lạc bộ mình mỗi tuần có hoạt động ngoại tuyến, nhưng tuần này đã hết chỗ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_05','V336','阮明',5,'啊？那我下周能正常参与活动吗？','a？ nà wǒ xià zhōu néng zhèng cháng cān yù huó dòng ma？','Ơ? Vậy tuần sau em có thể tham gia hoạt động bình thường được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_06','V336','学姐',6,'没问题，下周名额会重新开放，记得准时来。','méi wèn tí， xià zhōu míng é huì chóng xīn kāi fàng， jì de zhǔn shí lái。','Không vấn đề gì, tuần sau sẽ mở lại chỗ trống, nhớ đến đúng giờ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_07','V336','阮明',7,'好，我会记好时间，麻烦学姐啦。','hǎo， wǒ huì jì hǎo shí jiān， má fán xué jiě la。','Dạ vâng, em sẽ nhớ giờ giấc, cảm ơn chị nhiều ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT337','S112','Giải thích khi hiểu nhầm ý của bạn',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V337','SIT337','P1','suon_se','ban_chinh_thuc',NULL,'朋友产生隔阂后，中国人会主动沟通解释，厘清误会后不会一直记在心里。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_01','V337','阮明',1,'昨天那件事你是不是误会我了，我跟你解释一下吧。','zuó tiān nà jiàn shì nǐ shì bú shì wù huì wǒ le， wǒ gēn nǐ jiě shì yī xià ba。','Chuyện hôm qua chắc bạn hiểu lầm mình rồi, để mình giải thích cho bạn nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_02','V337','李然',2,'我昨天确实有点生气，你说说是什么情况。','wǒ zuó tiān què shí yǒu diǎn shēng qì， nǐ shuō shuō shì shén me qíng kuàng。','Hôm qua mình đúng là có hơi giận, bạn nói xem rốt cuộc là chuyện gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_03','V337','阮明',3,'我不是故意放你鸽子，是老师临时留我补作业呢。','wǒ bú shì gù yì fàng nǐ gē zi， shì lǎo shī lín shí liú wǒ bǔ zuò yè ne。','Mình không cố ý cho bạn leo cây đâu, tại thầy giữ mình lại bù bài tập đột xuất đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_04','V337','李然',4,'原来是这样，我还以为你不想跟我出门。','yuán lái shì zhè yàng， wǒ hái yǐ wéi nǐ bù xiǎng gēn wǒ chū mén。','Hóa ra là vậy, mình còn tưởng bạn không muốn đi chơi với mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_05','V337','阮明',5,'怎么会，我一直很期待和你逛街的。','zěn me huì， wǒ yì zhí hěn qī dài hé nǐ guàng jiē de。','Sao lại thế được, mình luôn mong được đi dạo phố cùng bạn mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_06','V337','李然',6,'行，我明白啦，这件事就翻篇不提了。','xíng， wǒ míng bái la， zhè jiàn shì jiù fān piān bù tí le。','Được rồi, mình hiểu rồi, chuyện này coi như bỏ qua, không nhắc lại nữa.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_07','V337','阮明',7,'太好了，下次出门我提前跟你确认时间。','tài hǎo le， xià cì chū mén wǒ tí qián gēn nǐ què rèn shí jiān。','Tuyệt quá, lần sau đi đâu mình sẽ báo giờ trước cho bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT338','S112','Chúc mừng sinh nhật bạn cùng phòng',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V338','SIT338','P1','suon_se','tuy_y',NULL,'大学生宿舍室友常会合伙买蛋糕、礼物一起过生日，是宿舍常见暖心活动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_01','V338','阮明',1,'张明，生日快乐！快拆开我们准备的蛋糕吧。','zhāng míng， shēng rì kuài lè！ kuài chāi kāi wǒ men zhǔn bèi de dàn gāo ba。','Trương Minh, sinh nhật vui vẻ nhé! Mau mở bánh kem tụi mình chuẩn bị đi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_02','V338','张明',2,'哇，你们居然还记得我的生日，太惊喜了。','wa， nǐ men jū rán hái jì de wǒ de shēng rì， tài jīng xǐ le。','Ồ, không ngờ mọi người còn nhớ sinh nhật mình, bất ngờ quá đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_03','V338','阮明',3,'我们悄悄凑钱买的，还有小礼物送给你呢。','wǒ men qiāo qiāo còu qián mǎi de， hái yǒu xiǎo lǐ wù sòng gěi nǐ ne。','Tụi mình lén góp tiền mua đấy, còn có quà nhỏ tặng bạn nữa nè.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_04','V338','张明',4,'真的不用这么破费，有你们陪伴就足够啦。','zhēn de bù yòng zhè me pò fèi， yǒu nǐ men péi bàn jiù zú gòu la。','Thật sự không cần tốn kém vậy đâu, có mọi người ở bên là đủ rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_05','V338','阮明',5,'室友之间不用客气，赶紧许愿吹蜡烛哦。','shì yǒu zhī jiān bù yòng kè qì， gǎn jǐn xǔ yuàn chuī là zhú ó。','Bạn cùng phòng thì khỏi khách sáo, mau ước nguyện rồi thổi nến đi nào.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_06','V338','张明',6,'好，我许个愿，希望我们宿舍一直和睦。','hǎo， wǒ xǔ gè yuàn， xī wàng wǒ men sù shè yì zhí hé mù。','Được, mình sẽ ước một điều, mong phòng mình luôn hòa thuận vui vẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_07','V338','阮明',7,'一定会的，咱们切蛋糕一起分享！','yí dìng huì de， zán men qiè dàn gāo yì qǐ fēn xiǎng！','Chắc chắn sẽ được vậy, giờ cắt bánh cùng chia nhau ăn nào!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT339','S112','Hỏi mượn đồ dùng cá nhân từ bạn cùng lớp',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V339','SIT339','P1','twist','tuy_y',NULL,'向他人借私人物品需要主动询问，用完及时归还，很多人会用小饮品、零食答谢对方。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_01','V339','阮明',1,'菲菲，能不能借你的笔记本电脑用半小时啊？','fēi fēi， néng bù néng jiè nǐ de bǐ jì běn diàn nǎo yòng bàn xiǎo shí a？','Phi Phi, cho mình mượn laptop dùng nửa tiếng được không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_02','V339','刘菲',2,'不好意思，我电脑拿去图书馆充电了嘛。','bù hǎo yì sī， wǒ diàn nǎo ná qù tú shū guǎn chōng diàn le ma。','Ngại quá, máy tính mình mang đi thư viện sạc pin rồi mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_03','V339','阮明',3,'这样啊，那你有多余的U盘借我拷贝文件吗？','zhè yàng a， nà nǐ yǒu duō yú de U pán jiè wǒ kǎo bèi wén jiàn ma？','Vậy à, thế bạn có USB dư cho mình mượn chép file không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_04','V339','刘菲',4,'这个可以，我包里刚好有一个全新的。','zhè ge kě yǐ， wǒ bāo lǐ gāng hǎo yǒu yí gè quán xīn de。','Cái này thì được, trong túi mình đang có một cái mới toanh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_05','V339','阮明',5,'太感谢了，用完我马上还给你，绝不弄丢。','tài gǎn xiè le， yòng wán wǒ mǎ shàng huán gěi nǐ， jué bù nòng diū。','Cảm ơn bạn nhiều lắm, dùng xong mình trả ngay, tuyệt đối không làm mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_06','V339','刘菲',6,'没关系，你慢慢用，不用着急归还。','méi guān xì， nǐ màn màn yòng， bù yòng zháo jí guī huán。','Không sao đâu, bạn cứ từ từ dùng, không cần vội trả lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_07','V339','阮明',7,'好嘞，等下请你喝奶茶作为答谢。','hǎo lei， děng xià qǐng nǐ hē nǎi chá zuò wéi dá xiè。','Được rồi, lát mình mời bạn uống trà sữa để cảm ơn nhé.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT340','S112','Đề nghị đổi lịch hẹn vì bận đột xuất',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V340','SIT340','P1','suon_se','ban_chinh_thuc',NULL,'临时无法赴约，中国人会第一时间告知对方，主动协商新时间，避免对方空等。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_01','V340','阮明',1,'实在抱歉，我们下午约好逛书店得改时间了。','shí zài bào qiàn， wǒ men xià wǔ yuē hǎo guàng shū diàn dé gǎi shí jiān le。','Thật sự xin lỗi, hẹn đi nhà sách chiều nay mình phải đổi giờ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_02','V340','吴桐',2,'怎么了，是临时有突发事情吗？','zěn me le， shì lín shí yǒu tū fā shì qíng ma？','Sao vậy, có việc gì gấp đột xuất à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_03','V340','阮明',3,'辅导员通知我去办公室提交留学材料呢。','fǔ dǎo yuán tōng zhī wǒ qù bàn gōng shì tí jiāo liú xué cái liào ne。','Cố vấn học tập gọi mình lên văn phòng nộp hồ sơ du học đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_04','V340','吴桐',4,'没事，正事要紧，我们改到明天下午行吗？','méi shì， zhèng shì yào jǐn， wǒ men gǎi dào míng tiān xià wǔ xíng ma？','Không sao, việc quan trọng cứ ưu tiên, tụi mình đổi sang chiều mai được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_05','V340','阮明',5,'明天下午我全天有空，完全没问题的。','míng tiān xià wǔ wǒ quán tiān yǒu kòng， wán quán méi wèn tí de。','Chiều mai mình rảnh cả buổi, hoàn toàn không vấn đề gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_06','V340','吴桐',6,'那就定明天三点，咱们校门口碰面吧。','nà jiù dìng míng tiān sān diǎn， zán men xiào mén kǒu pèng miàn ba。','Vậy chốt ba giờ chiều mai, tụi mình gặp nhau ở cổng trường nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_07','V340','阮明',7,'好，明天我提前十分钟在门口等你啦。','hǎo， míng tiān wǒ tí qián shí fēn zhōng zài mén kǒu děng nǐ la。','Được, mai mình sẽ đến trước mười phút đợi bạn ở cổng nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT341','S114','Xin nghỉ một buổi sinh hoạt câu lạc bộ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V341','SIT341','P1','suon_se','ban_chinh_thuc',NULL,'学生社团有事无法参与活动，需要提前向负责人报备请假，不能无故缺席。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_01','V341','阮明',1,'学姐，我想跟你请假，本周的社团活动没法参加了。','xué jiě， wǒ xiǎng gēn nǐ qǐng jià， běn zhōu de shè tuán huó dòng méi fǎ cān jiā le。','Chị ơi, em muốn xin phép nghỉ, tuần này em không tham gia hoạt động câu lạc bộ được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_02','V341','学姐',2,'可以，你是有什么重要的事情耽误了吗？','kě yǐ， nǐ shì yǒu shén me zhòng yào de shì qíng dān wù le ma？','Được thôi, em có việc gì quan trọng bị vướng à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_03','V341','阮明',3,'下周有汉语考试，我需要全天在家复习嘛。','xià zhōu yǒu hàn yǔ kǎo shì， wǒ xū yào quán tiān zài jiā fù xí ma。','Tuần sau em có bài thi tiếng Trung, em cần ở nhà ôn bài cả ngày ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_04','V341','学姐',4,'原来是备考，学习优先，我帮你登记请假。','yuán lái shì bèi kǎo， xué xí yōu xiān， wǒ bāng nǐ dēng jì qǐng jià。','Thì ra là chuẩn bị thi, việc học ưu tiên trước, chị ghi phép cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_05','V341','阮明',5,'活动的任务我下周会主动补上，不会落下进度。','huó dòng de rèn wù wǒ xià zhōu huì zhǔ dòng bǔ shàng， bú huì là xià jìn dù。','Nhiệm vụ của hoạt động tuần sau em sẽ chủ động bù lại, không để bị trễ đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_06','V341','学姐',6,'不用着急，等你考完试再来参与就行。','bù yòng zháo jí， děng nǐ kǎo wán shì zài lái cān yù jiù xíng。','Không cần vội, đợi em thi xong rồi tham gia lại cũng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_07','V341','阮明',7,'辛苦学姐体谅我啦，非常感谢。','xīn kǔ xué jiě tǐ liàng wǒ la， fēi cháng gǎn xiè。','Cảm ơn chị đã thông cảm cho em ạ, em cảm kích lắm.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT342','S112','Khen món ăn bạn Trung Quốc nấu, đáp lại khi được khen',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V342','SIT342','P1','suon_se','tuy_y',NULL,'品尝他人亲手做的饭菜，中国人会真诚夸赞，还会互相邀约交换拿手菜。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_01','V342','阮明',1,'你做的番茄炒蛋也太好吃了吧，味道超正宗！','nǐ zuò de fān qié chǎo dàn yě tài hǎo chī le ba， wèi dào chāo zhèng zōng！','Món trứng xào cà chua bạn làm ngon quá đi, đúng chuẩn vị luôn!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_02','V342','小雅',2,'没有啦，就是简单家常菜，你喜欢就多吃点。','méi yǒu la， jiù shì jiǎn dān jiā cháng cài， nǐ xǐ huān jiù duō chī diǎn。','Có gì đâu, chỉ là món nhà làm đơn giản thôi, bạn thích thì ăn thêm nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_03','V342','阮明',3,'比校外餐馆做得还香，你厨艺也太好了啊。','bǐ xiào wài cān guǎn zuò dé hái xiāng， nǐ chú yì yě tài hǎo le a。','Còn ngon hơn cả quán ăn ngoài trường, tay nghề nấu ăn của bạn giỏi quá.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_04','V342','小雅',4,'谢谢你夸奖，下次我教你一起做呢。','xiè xiè nǐ kuā jiǎng， xià cì wǒ jiāo nǐ yì qǐ zuò ne。','Cảm ơn bạn khen, lần sau mình chỉ bạn làm cùng nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_05','V342','阮明',5,'那太好了，我还怕自己学不会。','nà tài hǎo le， wǒ hái pà zì jǐ xué bú huì。','Vậy thì tốt quá, chứ mình còn sợ mình không học được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_06','V342','小雅',6,'不难的，下次你做家乡菜给我尝尝吧。','bù nán de， xià cì nǐ zuò jiā xiāng cài gěi wǒ cháng cháng ba。','Không khó đâu, lần sau bạn nấu món quê hương cho mình nếm thử nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_07','V342','阮明',7,'没问题，下次我带食材过来，一定露一手！','méi wèn tí， xià cì wǒ dài shí cái guò lái， yí dìng lòu yī shǒu！','Không thành vấn đề, lần sau mình mang nguyên liệu qua, nhất định trổ tài cho xem!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT343','S115','Mua điện thoại mới, hỏi thông số',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V343','SIT343','P1','suon_se','tuy_y',NULL,'线下买电子产品，顾客可以自由询问全部参数，对比多款机型，店家不会催促下单。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_01','V343','阮明',1,'你好，这款新款手机内存和电池容量是多少啊？','nǐ hǎo， zhè kuǎn xīn kuǎn shǒu jī nèi cún hé diàn chí róng liàng shì duō shǎo a？','Chào bạn, mẫu điện thoại mới này bộ nhớ và dung lượng pin bao nhiêu vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_02','V343','销售员',2,'这款手机256G内存，电池续航一整天没问题。','zhè kuǎn shǒu jī 256G nèi cún， diàn chí xù háng yī zhěng tiān méi wèn tí。','Mẫu này bộ nhớ 256G, pin dùng thoải mái cả ngày không lo hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_03','V343','阮明',3,'拍照像素高吗？我平时很喜欢出门拍照呢。','pāi zhào xiàng sù gāo ma？ wǒ píng shí hěn xǐ huān chū mén pāi zhào ne。','Chụp ảnh độ phân giải có cao không? Mình hay đi ra ngoài chụp ảnh lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_04','V343','销售员',4,'后置五千万像素，夜景拍摄效果特别清晰。','hòu zhì wǔ qiān wàn xiàng sù， yè jǐng pāi shè xiào guǒ tè bié qīng xī。','Camera sau năm mươi triệu điểm ảnh, chụp cảnh đêm nét căng luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_05','V343','阮明',5,'那处理器运行会不会卡顿，适合学习软件吗？','nà chǔ lǐ qì yùn xíng huì bú huì kǎ dùn， shì hé xué xí ruǎn jiàn ma？','Vậy chip xử lý chạy có bị giật lag không, có phù hợp để học phần mềm không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_06','V343','销售员',6,'配置足够流畅运行各类软件，学生用很合适。','pèi zhì zú gòu liú chàng yùn xíng gè lèi ruǎn jiàn， xué shēng yòng hěn hé shì。','Cấu hình chạy mượt đủ loại phần mềm, sinh viên dùng rất hợp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_07','V343','阮明',7,'行，那我再对比一下另一款，等下再来找你。','xíng， nà wǒ zài duì bǐ yī xià lìng yī kuǎn， děng xià zài lái zhǎo nǐ。','Được, để mình so sánh thêm mẫu kia nữa, lát quay lại tìm bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT344','S115','Mang điện thoại đi sửa màn hình vỡ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V344','SIT344','P1','twist','ban_chinh_thuc',NULL,'手机维修更换配件分原装和平价配件，店家会主动区分报价，配件缺货会告知顾客取机时间。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_01','V344','阮明',1,'师傅，我的手机屏幕摔碎了，能帮忙更换吗？','shī fù， wǒ de shǒu jī píng mù shuāi suì le， néng bāng máng gēng huàn ma？','Anh ơi, màn hình điện thoại em bị rơi vỡ rồi, anh giúp thay được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_02','V344','维修师傅',2,'可以，先看看型号，原装屏幕价格贵一点哈。','kě yǐ， xiān kàn kàn xíng hào， yuán zhuāng píng mù jià gé guì yì diǎn hā。','Được, để xem đời máy trước đã, màn hình chính hãng giá hơi cao đấy nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_03','V344','阮明',3,'原装的大概多少钱，维修需要等多久呢？','yuán zhuāng de dà gài duō shǎo qián， wéi xiū xū yào děng duō jiǔ ne？','Hàng chính hãng khoảng bao nhiêu tiền vậy, sửa xong thì mất bao lâu ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_04','V344','维修师傅',4,'三百五十元，可惜现在店里没有现货屏幕。','sān bǎi wǔ shí yuán， kě xī xiàn zài diàn lǐ méi yǒu xiàn huò píng mù。','Ba trăm năm mươi tệ, tiếc là hiện tại cửa hàng không có sẵn màn hình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_05','V344','阮明',5,'啊？那什么时候能到货，我手机每天都要用。','a？ nà shén me shí hòu néng dào huò， wǒ shǒu jī měi tiān dōu yào yòng。','Hả? Vậy bao giờ có hàng vậy, điện thoại em ngày nào cũng phải dùng.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_06','V344','维修师傅',6,'明天中午到货，你明天下午过来取就行。','míng tiān zhōng wǔ dào huò， nǐ míng tiān xià wǔ guò lái qǔ jiù xíng。','Trưa mai hàng về, mai chiều em qua lấy là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_07','V344','阮明',7,'好，我明天准时过来，麻烦师傅预留屏幕。','hǎo， wǒ míng tiān zhǔn shí guò lái， má fán shī fù yù liú píng mù。','Vâng, mai em sẽ đến đúng giờ, phiền anh giữ màn hình cho em nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT345','S116','Mua laptop, hỏi bảo hành',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V345','SIT345','P1','suon_se','ban_chinh_thuc',NULL,'国内数码产品均提供全国联保服务，门店会清晰告知保修时长、售后范围。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_01','V345','阮明',1,'这款笔记本适合留学生写论文、做PPT吗？','zhè kuǎn bǐ jì běn shì hé liú xué shēng xiě lùn wén、 zuò PPT ma？','Chiếc laptop này có phù hợp cho du học sinh viết luận văn, làm PPT không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_02','V345','导购',2,'完全适配，轻薄便携，性能足够日常学习的。','wán quán shì pèi， qīng bó biàn xié， xìng néng zú gòu rì cháng xué xí de。','Hoàn toàn phù hợp, máy mỏng nhẹ dễ mang theo, hiệu năng đủ dùng cho học tập hàng ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_03','V345','阮明',3,'那整机官方保修时长是多久呀？','nà zhěng jī guān fāng bǎo xiū shí cháng shì duō jiǔ ya？','Vậy thời gian bảo hành chính hãng của cả máy là bao lâu vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_04','V345','导购',4,'基础全国联保一年，加钱可以升级到三年哦。','jī chǔ quán guó lián bǎo yī nián， jiā qián kě yǐ shēng jí dào sān nián ó。','Bảo hành toàn quốc cơ bản là một năm, đóng thêm tiền có thể nâng lên ba năm đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_05','V345','阮明',5,'保修期内系统故障能免费上门维修吗？','bǎo xiū qī nèi xì tǒng gù zhàng néng miǎn fèi shàng mén wéi xiū ma？','Trong thời gian bảo hành nếu máy lỗi hệ thống thì có được sửa tận nơi miễn phí không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_06','V345','导购',6,'市区范围内可以免费上门，超出范围需要送店。','shì qū fàn wéi nèi kě yǐ miǎn fèi shàng mén， chāo chū fàn wéi xū yào sòng diàn。','Trong nội thành thì được sửa tận nơi miễn phí, ngoài phạm vi đó thì phải mang ra cửa hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_07','V345','阮明',7,'了解了，我考虑一下，晚点过来付款吧。','liǎo jiě le， wǒ kǎo lǜ yī xià， wǎn diǎn guò lái fù kuǎn ba。','Em hiểu rồi, để em suy nghĩ thêm, lát nữa quay lại thanh toán nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT346','S117','Đăng ký lắp Internet cho phòng trọ',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V346','SIT346','P1','twist','ban_chinh_thuc',NULL,'租房办理宽带需要核验房屋地址，小区宽带端口有限，满员只能排队等待新端口。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_01','V346','阮明',1,'你好，我租的单间想办理宽带安装业务。','nǐ hǎo， wǒ zū de dān jiān xiǎng bàn lǐ kuān dài ān zhuāng yè wù。','Chào chị, phòng trọ của em muốn đăng ký lắp mạng internet ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_02','V346','客服',2,'您好，请提供详细地址，我查询线路覆盖情况。','nín hǎo， qǐng tí gōng xiáng xì dì zhǐ， wǒ chá xún xiàn lù fù gài qíng kuàng。','Chào em, em cho chị xin địa chỉ chi tiết để chị kiểm tra xem khu vực đó có phủ sóng đường truyền không.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_03','V346','阮明',3,'地址是大学周边小区3栋502室，麻烦查一下。','dì zhǐ shì dà xué zhōu biān xiǎo qū 3 dòng 502 shì， má fán chá yī xià。','Địa chỉ là tòa 3, phòng 502, khu chung cư gần trường đại học, chị kiểm tra giúp em với.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_04','V346','客服',4,'不好意思，您小区本周宽带端口已经全部用完了嘛。','bù hǎo yì sī， nín xiǎo qū běn zhōu kuān dài duān kǒu yǐ jīng quán bù yòng wán le ma。','Ngại quá, khu chung cư của em tuần này đã hết cổng lắp mạng rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_05','V346','阮明',5,'这样啊，那下一批端口什么时候开放呢？','zhè yàng a， nà xià yī pī duān kǒu shén me shí hòu kāi fàng ne？','Vậy hả chị, thế đợt cổng tiếp theo bao giờ mới mở ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_06','V346','客服',6,'三天后重新放号，到时候我可以提醒您预约。','sān tiān hòu chóng xīn fàng hào， dào shí hòu wǒ kě yǐ tí xǐng nín yù yuē。','Ba ngày nữa sẽ mở đợt mới, đến lúc đó chị có thể nhắc em đặt lịch.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_07','V346','阮明',7,'好，那麻烦三天后联系我，辛苦你啦。','hǎo， nà má fán sān tiān hòu lián xì wǒ， xīn kǔ nǐ la。','Dạ vâng, vậy nhờ chị ba ngày nữa liên hệ lại với em, cảm ơn chị nhiều nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT347','S115','Chuyển dữ liệu sang điện thoại mới',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V347','SIT347','P1','suon_se','tuy_y',NULL,'国产手机自带一键换机功能，年轻人大多会互相帮忙操作数据迁移。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_01','V347','阮明',1,'我刚换了新手机，不知道怎么转移旧手机数据啊。','wǒ gāng huàn le xīn shǒu jī， bù zhī dào zěn me zhuǎn yí jiù shǒu jī shù jù a。','Tớ vừa đổi điện thoại mới, chẳng biết chuyển dữ liệu từ máy cũ sang thế nào cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_02','V347','小杨',2,'很简单，手机自带换机软件，跟着步骤操作就行啦。','hěn jiǎn dān， shǒu jī zì dài huàn jī ruǎn jiàn， gēn zhe bù zhòu cāo zuò jiù xíng la。','Đơn giản lắm, điện thoại có sẵn phần mềm chuyển máy, cứ làm theo hướng dẫn là được ấy mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_03','V347','阮明',3,'聊天记录、照片和文件都能完整复制过去吗？','liáo tiān jì lù、 zhào piān hé wén jiàn dōu néng wán zhěng fù zhì guò qù ma？','Tin nhắn, ảnh với file có sao chép nguyên vẹn qua được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_04','V347','小杨',4,'全部可以，就是两台手机都要连接同一个WiFi呢。','quán bù kě yǐ， jiù shì liǎng tái shǒu jī dōu yào lián jiē tóng yī gè WiFi ne。','Được hết luôn, chỉ cần hai máy kết nối chung một mạng WiFi thôi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_05','V347','阮明',5,'我还担心会丢失重要的学习资料。','wǒ hái dān xīn huì diū shī zhòng yào de xué xí zī liào。','Tớ còn lo bị mất mấy tài liệu học tập quan trọng nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_06','V347','小杨',6,'放心，我上次换机一点资料都没漏掉。','fàng xīn， wǒ shàng cì huàn jī yì diǎn zī liào dōu méi lòu diào。','Yên tâm đi, lần trước tớ đổi máy chẳng thiếu tí dữ liệu nào cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_07','V347','阮明',7,'太谢谢你了，等下我操作有问题再来问你吧。','tài xiè xiè nǐ le， děng xià wǒ cāo zuò yǒu wèn tí zài lái wèn nǐ ba。','Cảm ơn cậu nhiều lắm, lát nữa thao tác có gì tớ lại hỏi cậu nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT348','S118','Cài đặt và đăng ký app dịch tiếng Trung',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V348','SIT348','P1','suon_se','tuy_y',NULL,'留学生常用翻译APP辅助学习中文，国内软件支持微信、QQ快捷登录，注册流程简单。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_01','V348','阮明',1,'有没有好用的翻译软件推荐我下载一下啊？','yǒu méi yǒu hǎo yòng de fān yì ruǎn jiàn tuī jiàn wǒ xià zài yī xià a？','Có app dịch nào dùng ngon giới thiệu tớ tải với?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_02','V348','小林',2,'这款翻译APP特别适合留学生，离线也能用呢。','zhè kuǎn fān yì APP tè bié shì hé liú xué shēng， lí xiàn yě néng yòng ne。','App dịch này hợp với du học sinh lắm, không có mạng cũng dùng được đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_03','V348','阮明',3,'下载之后注册需要绑定手机号吗？','xià zài zhī hòu zhù cè xū yào bǎng dìng shǒu jī hào ma？','Tải về rồi đăng ký có cần liên kết số điện thoại không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_04','V348','小林',4,'只用微信一键登录就可以，不用额外注册啦。','zhǐ yòng wēi xìn yī jiàn dēng lù jiù kě yǐ， bù yòng é wài zhù cè la。','Chỉ cần đăng nhập bằng WeChat một chạm là xong, khỏi phải đăng ký thêm gì luôn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_05','V348','阮明',5,'还能拍照翻译课本上的汉字，对吗？','hái néng pāi zhào fān yì kè běn shàng de hàn zì， duì ma？','Còn chụp ảnh dịch chữ Hán trong sách giáo trình được nữa đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_06','V348','小林',6,'没错，拍照翻译准确度很高，日常学习够用。','méi cuò， pāi zhào fān yì zhǔn què dù hěn gāo， rì cháng xué xí gòu yòng。','Đúng rồi, chụp ảnh dịch độ chính xác cao lắm, dùng học hàng ngày là đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_07','V348','阮明',7,'太好了，我现在就下载安装试试吧。','tài hǎo le， wǒ xiàn zài jiù xià zài ān zhuāng shì shì ba。','Tuyệt quá, để tớ tải về cài thử luôn bây giờ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT349','S115','Gia hạn gói cước SIM khi hết hạn',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V349','SIT349','P1','twist','ban_chinh_thuc',NULL,'国内手机运营商会推出专属学生优惠套餐，优惠到期或活动结束就无法办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_01','V349','阮明',1,'您好，我的手机流量套餐今天到期，想现场续费。','nín hǎo， wǒ de shǒu jī liú liàng tào cān jīn tiān dào qī， xiǎng xiàn chǎng xù fèi。','Chào anh, gói data điện thoại của em hôm nay hết hạn, em muốn gia hạn luôn tại đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_02','V349','工作人员',2,'可以，出示手机卡号，我帮你查询套餐选项。','kě yǐ， chū shì shǒu jī kǎ hào， wǒ bāng nǐ chá xún tào cān xuǎn xiàng。','Được, em cho anh xem số thuê bao, anh kiểm tra các gói cước cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_03','V349','阮明',3,'我平时流量用得多，有没有不限流量的学生套餐？','wǒ píng shí liú liàng yòng dé duō， yǒu méi yǒu bù xiàn liú liàng de xué shēng tào cān？','Em dùng data nhiều, có gói học sinh không giới hạn dung lượng không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_04','V349','工作人员',4,'学生专属套餐本月已经下架，只能选普通套餐嘛。','xué shēng zhuān shǔ tào cān běn yuè yǐ jīng xià jià， zhǐ néng xuǎn pǔ tōng tào cān ma。','Gói dành riêng cho học sinh tháng này đã ngừng bán rồi, giờ chỉ chọn được gói thường thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_05','V349','阮明',5,'啊，那普通套餐每月多少流量，多少钱月租？','a， nà pǔ tōng tào cān měi yuè duō shǎo liú liàng， duō shǎo qián yuè zū？','Ôi vậy hả, gói thường mỗi tháng bao nhiêu dung lượng, cước phí bao nhiêu vậy anh?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_06','V349','工作人员',6,'每月40G流量，月租三十九元，性价比很高。','měi yuè 40G liú liàng， yuè zū sān shí jiǔ yuán， xìng jià bǐ hěn gāo。','Mỗi tháng 40G, cước tháng ba mươi chín tệ, rất đáng tiền đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_07','V349','阮明',7,'行，那就办理这个普通套餐续费吧。','xíng， nà jiù bàn lǐ zhè ge pǔ tōng tào cān xù fèi ba。','Được đó, vậy em đăng ký gia hạn gói thường này luôn ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT350','S116','Nhờ sửa lỗi kết nối wifi trong phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V350','SIT350','P1','suon_se','ban_chinh_thuc',NULL,'宽带套餐保修期内，线路、WiFi故障可免费上门维修，无需支付人工费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_01','V350','阮明',1,'师傅，我房间WiFi突然连不上了，麻烦上门看看吧。','shī fù， wǒ fáng jiān WiFi tū rán lián bù shàng le， má fán shàng mén kàn kàn ba。','Anh ơi, WiFi phòng em tự nhiên không kết nối được, phiền anh qua xem giúp em với.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_02','V350','维修师傅',2,'好，我先检查光猫和路由器，大概率是线路松动。','hǎo， wǒ xiān jiǎn chá guāng māo hé lù yóu qì， dà gài lǜ shì xiàn lù sōng dòng。','Được, để anh kiểm tra bộ chuyển quang và router trước, chắc là do dây bị lỏng thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_03','V350','阮明',3,'昨天网络还很流畅，今天一早直接断网了呢。','zuó tiān wǎng luò hái hěn liú chàng， jīn tiān yī zǎo zhí jiē duàn wǎng le ne。','Hôm qua mạng vẫn còn chạy mượt lắm, sáng nay tự nhiên mất mạng luôn đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_04','V350','维修师傅',4,'我重新插紧线路，再重置路由器就能恢复。','wǒ chóng xīn chā jǐn xiàn lù， zài zhòng zhì lù yóu qì jiù néng huī fù。','Anh cắm chặt lại dây, rồi khởi động lại router là sẽ có mạng lại thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_05','V350','阮明',5,'维修需要额外收取服务费吗？','wéi xiū xū yào é wài shōu qǔ fú wù fèi ma？','Sửa như vậy có tính thêm phí dịch vụ không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_06','V350','维修师傅',6,'在宽带保修期内，上门检修完全免费。','zài kuān dài bǎo xiū qī nèi， shàng mén jiǎn xiū wán quán miǎn fèi。','Trong thời gian bảo hành mạng thì sửa tận nơi hoàn toàn miễn phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_07','V350','阮明',7,'太好了，辛苦师傅帮忙处理啦。','tài hǎo le， xīn kǔ shī fù bāng máng chǔ lǐ la。','Tuyệt quá, cảm ơn anh đã vất vả giúp em nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT351','S119','Chuyển tiền cho bạn qua app ngân hàng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V351','SIT351','P1','suon_se','ban_chinh_thuc',NULL,'国内手机银行转账实时到账，会自动发送短信通知，转账前务必核对姓名卡号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_01','V351','阮明',1,'你好，我想在手机银行APP给同学转账。','nǐ hǎo， wǒ xiǎng zài shǒu jī yín háng APP gěi tóng xué zhuǎn zhàng。','Chào chị, em muốn chuyển tiền cho bạn học qua app ngân hàng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_02','V351','客服',2,'您好，您需要输入对方银行卡号和姓名核对哦。','nín hǎo， nín xū yào shū rù duì fāng yín háng kǎ hào hé xìng míng hé duì ó。','Chào em, em cần nhập số thẻ ngân hàng và tên của người nhận để đối chiếu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_03','V351','阮明',3,'转账有限额吗，我一次转三千元可以吗？','zhuǎn zhàng yǒu xiàn é ma， wǒ yī cì zhuǎn sān qiān yuán kě yǐ ma？','Chuyển tiền có giới hạn hạn mức không chị, em chuyển một lần ba nghìn tệ được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_04','V351','客服',4,'学生一类银行卡单日转账限额五万元，完全没问题。','xué shēng yī lèi yín háng kǎ dān rì zhuǎn zhàng xiàn é wǔ wàn yuán， wán quán méi wèn tí。','Thẻ ngân hàng loại dành cho học sinh hạn mức chuyển khoản một ngày là năm mươi nghìn tệ, hoàn toàn thoải mái.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_05','V351','阮明',5,'转账成功之后会有短信通知双方吗？','zhuǎn zhàng chéng gōng zhī hòu huì yǒu duǎn xìn tōng zhī shuāng fāng ma？','Chuyển thành công rồi thì có tin nhắn báo cho cả hai bên không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_06','V351','客服',6,'双方都会收到提醒，方便核对交易记录呢。','shuāng fāng dōu huì shōu dào tí xǐng， fāng biàn hé duì jiāo yì jì lù ne。','Cả hai bên đều nhận được thông báo, tiện cho việc đối chiếu giao dịch đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_07','V351','阮明',7,'清楚操作流程了，谢谢你的讲解吧。','qīng chǔ cāo zuò liú chéng le， xiè xiè nǐ de jiǎng jiě ba。','Em hiểu rõ quy trình rồi ạ, cảm ơn chị đã hướng dẫn nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT352','S119','Nhận tiền gia đình gửi từ nước ngoài',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V352','SIT352','P1','twist','chinh_thuc',NULL,'境外跨境汇款需要银行系统清算，无法实时兑换人民币取现，留学生需携带护照办理外汇业务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_01','V352','阮明',1,'您好，我家人从境外给我汇了一笔生活费，我来办理结汇。','nín hǎo， wǒ jiā rén cóng jìng wài gěi wǒ huì le yī bǐ shēng huó fèi， wǒ lái bàn lǐ jié huì。','Chào anh, người nhà em từ nước ngoài gửi cho em một khoản tiền sinh hoạt phí, em đến làm thủ tục đổi tiền ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_02','V352','柜员',2,'请出示你的护照和银行卡，我先查询外汇到账状态。','qǐng chū shì nǐ de hù zhào hé yín háng kǎ， wǒ xiān chá xún wài huì dào zhàng zhuàng tài。','Em cho anh xem hộ chiếu và thẻ ngân hàng, để anh kiểm tra tình trạng khoản ngoại tệ chuyển đến trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_03','V352','阮明',3,'好，证件都在这里，大概昨天傍晚汇出的。','hǎo， zhèng jiàn dōu zài zhè lǐ， dà gài zuó tiān bàng wǎn huì chū de。','Dạ vâng, giấy tờ em mang đầy đủ đây ạ, chắc là chuyển từ chiều tối hôm qua.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_04','V352','柜员',4,'抱歉，这笔汇款还未清算，今天暂时无法提取嘛。','bào qiàn， zhè bǐ huì kuǎn hái wèi qīng suàn， jīn tiān zàn shí wú fǎ tí qǔ ma。','Xin lỗi em, khoản tiền này chưa được thanh toán bù trừ, hôm nay tạm thời chưa rút được đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_05','V352','阮明',5,'啊？那要等到什么时候才能兑换人民币？','a？ nà yào děng dào shén me shí hòu cái néng duì huàn rén mín bì？','Ơ vậy ạ? Vậy phải đợi đến khi nào mới đổi được sang nhân dân tệ ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_06','V352','柜员',6,'明天上午系统完成清算，你再来柜台办理就行。','míng tiān shàng wǔ xì tǒng wán chéng qīng suàn， nǐ zài lái guì tái bàn lǐ jiù xíng。','Sáng mai hệ thống hoàn tất thanh toán bù trừ, em quay lại quầy làm thủ tục là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_07','V352','阮明',7,'好，我明天一早过来，麻烦你登记一下。','hǎo， wǒ míng tiān yī zǎo guò lái， má fán nǐ dēng jì yī xià。','Dạ vâng, sáng mai em qua sớm, phiền anh đăng ký giúp em trước ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT353','S119','Rút tiền tại ATM',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V353','SIT353','P1','suon_se','tuy_y',NULL,'国内ATM取款有现金上限，忘记取卡会被机器回收，需要带身份证去柜台取回。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_01','V353','阮明',1,'学长，这个ATM机怎么取款，我不太会操作啊。','xué zhǎng， zhè ge ATM jī zěn me qǔ kuǎn， wǒ bù tài huì cāo zuò a。','Anh ơi, cái máy ATM này rút tiền kiểu gì vậy, em thao tác không rành lắm.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_02','V353','学长',2,'先插银行卡，输入密码，再选择取款金额就行啦。','xiān chā yín háng kǎ， shū rù mì mǎ， zài xuǎn zé qǔ kuǎn jīn é jiù xíng la。','Cắm thẻ ngân hàng vào trước, nhập mật khẩu, rồi chọn số tiền cần rút là xong ngay ấy mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_03','V353','阮明',3,'单日最多能取多少现金，会不会有限制？','dān rì zuì duō néng qǔ duō shǎo xiàn jīn， huì bú huì yǒu xiàn zhì？','Một ngày rút tối đa được bao nhiêu tiền mặt vậy, có bị giới hạn không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_04','V353','学长',4,'ATM单日限额两万，日常取生活费完全够用呢。','ATM dān rì xiàn é liǎng wàn， rì cháng qǔ shēng huó fèi wán quán gòu yòng ne。','ATM giới hạn hai vạn một ngày, xài chi tiêu sinh hoạt hàng ngày thì dư sức luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_05','V353','阮明',5,'取完钱之后一定要记得拔卡对吧？','qǔ wán qián zhī hòu yí dìng yào jì de bá kǎ duì ba？','Rút tiền xong nhớ rút thẻ ra liền đúng không anh?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_06','V353','学长',6,'没错，超时不取卡机器会自动吞卡的。','méi cuò， chāo shí bù qǔ kǎ jī qì huì zì dòng tūn kǎ de。','Đúng rồi, để quá lâu không rút thẻ là máy tự động nuốt thẻ đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_07','V353','阮明',7,'太感谢你提醒我，不然我很容易忘啦。','tài gǎn xiè nǐ tí xǐng wǒ， bù rán wǒ hěn róng yì wàng la。','Cảm ơn anh nhắc em nha, không thì em kiểu gì cũng quên mất.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT354','S119','Báo mất thẻ và xin khóa thẻ khẩn cấp',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V354','SIT354','P1','suon_se','chinh_thuc',NULL,'银行卡丢失第一时间电话挂失锁卡，能保障账户资金安全，补办卡片必须线下网点办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_01','V354','阮明',1,'您好，我的银行卡遗失了，申请紧急挂失锁卡。','nín hǎo， wǒ de yín háng kǎ yí shī le， shēn qǐng jǐn jí guà shī suǒ kǎ。','Chào chị, tôi bị mất thẻ ngân hàng, muốn xin khóa thẻ khẩn cấp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_02','V354','客服',2,'请告知您姓名、银行卡尾号以及身份证号吧。','qǐng gào zhī nín xìng míng、 yín háng kǎ wěi hào yǐ jí shēn fèn zhèng hào ba。','Vâng, phiền anh cho biết họ tên, số cuối thẻ ngân hàng và số căn cước công dân ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_03','V354','阮明',3,'全部信息我都记好了，现在报给你核对。','quán bù xìn xī wǒ dōu jì hǎo le， xiàn zài bào gěi nǐ hé duì。','Tôi đã chuẩn bị đầy đủ thông tin rồi, để tôi đọc để chị kiểm tra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_04','V354','客服',4,'已经为您临时冻结卡片，资金不会被盗刷呢。','yǐ jīng wèi nín lín shí dòng jié kǎ piàn， zī jīn bú huì bèi dào shuā ne。','Chúng tôi đã tạm thời phong tỏa thẻ của anh rồi, tiền trong tài khoản sẽ không bị đánh cắp đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_05','V354','阮明',5,'那之后补办新卡需要去线下柜台办理吗？','nà zhī hòu bǔ bàn xīn kǎ xū yào qù xiàn xià guì tái bàn lǐ ma？','Vậy sau này làm lại thẻ mới thì có cần ra quầy trực tiếp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_06','V354','客服',6,'是的，携带护照前往就近网点即可补办。','shì de， xié dài hù zhào qián wǎng jiù jìn wǎng diǎn jí kě bǔ bàn。','Vâng, anh mang theo hộ chiếu đến chi nhánh gần nhất là làm lại được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_07','V354','阮明',7,'太感谢了，还好及时打电话挂失啦。','tài gǎn xiè le， hái hǎo jí shí dǎ diàn huà guà shī la。','Cảm ơn chị rất nhiều, may mà tôi gọi điện báo mất kịp thời.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT355','S119','Yêu cầu in sao kê giao dịch',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V355','SIT355','P1','suon_se','ban_chinh_thuc',NULL,'留学生打印银行卡流水用于留学报备，多数银行免费办理，打印文件加盖公章才具备证明效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_01','V355','阮明',1,'你好，我需要打印近半年的银行卡交易流水。','nǐ hǎo， wǒ xū yào dǎ yìn jìn bàn nián de yín háng kǎ jiāo yì liú shuǐ。','Chào anh, tôi cần in sao kê giao dịch thẻ ngân hàng trong nửa năm gần đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_02','V355','柜员',2,'可以，出示你的银行卡和护照，我帮你调取记录哦。','kě yǐ， chū shì nǐ de yín háng kǎ hé hù zhào， wǒ bāng nǐ diào qǔ jì lù ó。','Được ạ, anh cho tôi xem thẻ ngân hàng và hộ chiếu, tôi tra cứu lịch sử giao dịch giúp anh nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_03','V355','阮明',3,'打印流水需要收取手续费吗？','dǎ yìn liú shuǐ xū yào shōu qǔ shǒu xù fèi ma？','In sao kê có phải trả phí gì không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_04','V355','柜员',4,'留学生办理留学相关流水打印是免费的呢。','liú xué shēng bàn lǐ liú xué xiāng guān liú shuǐ dǎ yìn shì miǎn fèi de ne。','Du học sinh làm sao kê phục vụ mục đích du học thì được miễn phí ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_05','V355','阮明',5,'太好了，我要交给学校作为资金证明材料。','tài hǎo le， wǒ yào jiāo gěi xué xiào zuò wéi zī jīn zhèng míng cái liào。','Tuyệt quá, tôi cần nộp cho trường làm giấy tờ chứng minh tài chính.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_06','V355','柜员',6,'我会帮你加盖银行公章，学校可以直接认可。','wǒ huì bāng nǐ jiā gài yín háng gōng zhāng， xué xiào kě yǐ zhí jiē rèn kě。','Tôi sẽ đóng dấu ngân hàng vào cho anh, trường sẽ chấp nhận trực tiếp thôi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_07','V355','阮明',7,'辛苦你了，等下我取完流水就离开。','xīn kǔ nǐ le， děng xià wǒ qǔ wán liú shuǐ jiù lí kāi。','Cảm ơn anh vất vả rồi, lát nữa lấy sao kê xong tôi ra về luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT356','S119','Đổi mã PIN thẻ ngân hàng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V356','SIT356','P1','twist','tuy_y',NULL,'银行取款密码固定六位数，修改时两次输入必须完全相同，不一致则操作失败。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_01','V356','阮明',1,'你好，我想在自助终端修改银行卡取款密码。','nǐ hǎo， wǒ xiǎng zài zì zhù zhōng duān xiū gǎi yín háng kǎ qǔ kuǎn mì mǎ。','Chào anh, tôi muốn đổi mật khẩu rút tiền của thẻ ngân hàng ở máy tự phục vụ này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_02','V356','引导员',2,'先插卡输入旧密码，再设置新的六位数字密码。','xiān chā kǎ shū rù jiù mì mǎ， zài shè zhì xīn de liù wèi shù zì mì mǎ。','Anh cắm thẻ nhập mật khẩu cũ trước, rồi đặt mật khẩu mới sáu chữ số là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_03','V356','阮明',3,'我刚刚输入一遍，提示两次密码不一致嘛。','wǒ gāng gāng shū rù yī biàn， tí shì liǎng cì mì mǎ bù yī zhì ma。','Tôi vừa nhập một lần rồi, nó báo hai lần mật khẩu không khớp nhau nè.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_04','V356','阮明',4,'我没看清屏幕，两次输的数字不一样。','wǒ méi kàn qīng píng mù， liǎng cì shū de shù zì bù yí yàng。','Tôi nhìn màn hình không rõ, hai lần gõ số không giống nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_05','V356','引导员',5,'没关系，重新操作一次，仔细核对数字就行。','méi guān xì， chóng xīn cāo zuò yī cì， zǐ xì hé duì shù zì jiù xíng。','Không sao đâu, anh làm lại lần nữa, chú ý đối chiếu số cho kỹ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_06','V356','阮明',6,'好，我慢慢来，这次一定留意屏幕提示。','hǎo， wǒ màn màn lái， zhè cì yí dìng liú yì píng mù tí shì。','Ừ, để tôi làm từ từ, lần này chắc chắn để ý kỹ thông báo trên màn hình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_07','V356','阮明',7,'终于修改成功了，谢谢你在旁边指导我啦。','zhōng yú xiū gǎi chéng gōng le， xiè xiè nǐ zài páng biān zhǐ dǎo wǒ la。','Cuối cùng cũng đổi thành công rồi, cảm ơn anh đứng bên cạnh chỉ tôi nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT357','S119','Hỏi phí chuyển tiền quốc tế',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V357','SIT357','P1','suon_se','chinh_thuc',NULL,'国际跨境转账手续费固定收取，到账速度受国内外节假日、银行清算时间影响。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_01','V357','阮明',1,'您好，如果我往越南的账户转账，手续费怎么收取？','nín hǎo， rú guǒ wǒ wǎng yuè nán de zhàng hù zhuǎn zhàng， shǒu xù fèi zěn me shōu qǔ？','Chào chị, nếu tôi chuyển tiền về tài khoản ở Việt Nam thì phí giao dịch tính thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_02','V357','柜员',2,'手续费分为固定工本费和跨境电讯费两部分哦。','shǒu xù fèi fēn wéi gù dìng gōng běn fèi hé kuà jìng diàn xùn fèi liǎng bù fèn ó。','Phí giao dịch gồm hai phần: phí công tơ cố định và phí điện tín xuyên biên giới ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_03','V357','阮明',3,'转账金额不同，手续费价格会变化吗？','zhuǎn zhàng jīn é bù tóng， shǒu xù fèi jià gé huì biàn huà ma？','Số tiền chuyển khác nhau thì phí giao dịch có thay đổi theo không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_04','V357','柜员',4,'手续费统一标准，不会随转账金额增减呢。','shǒu xù fèi tǒng yī biāo zhǔn， bú huì suí zhuǎn zhàng jīn é zēng jiǎn ne。','Phí giao dịch áp dụng mức cố định, không tăng giảm theo số tiền chuyển ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_05','V357','阮明',5,'那多久能到对方的海外银行卡账户？','nà duō jiǔ néng dào duì fāng de hǎi wài yín háng kǎ zhàng hù？','Vậy mất bao lâu thì tiền đến được tài khoản ngân hàng nước ngoài của người nhận?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_06','V357','柜员',6,'最快两个工作日，节假日会顺延清算时间。','zuì kuài liǎng gè gōng zuò rì， jié jià rì huì shùn yán qīng suàn shí jiān。','Nhanh nhất là hai ngày làm việc, nếu gặp ngày lễ thì thời gian thanh toán sẽ bị lùi lại ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_07','V357','阮明',7,'我全部了解清楚了，感谢你的细致讲解。','wǒ quán bù liǎo jiě qīng chǔ le， gǎn xiè nǐ de xì zhì jiǎng jiě。','Tôi đã hiểu rõ hết rồi, cảm ơn chị đã giải thích tận tình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT358','S119','Khiếu nại giao dịch bị trừ tiền nhưng không nhận được hàng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V358','SIT358','P1','twist','ban_chinh_thuc',NULL,'国内电商平台漏发、丢件，顾客可自主选择补发货物或全额退款，平台客服全程协调处理；商家责任退款自动审核，到账速度更快。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_01','V358','阮明',1,'你好，我要反馈一笔线上订单问题，支付扣款成功，至今没有收到包裹。','nǐ hǎo， wǒ yào fǎn kuì yī bǐ xiàn shàng dìng dān wèn tí， zhī fù kòu kuǎn chéng gōng， zhì jīn méi yǒu shōu dào bāo guǒ。','Chào chị, tôi muốn phản ánh về một đơn hàng online, thanh toán đã bị trừ tiền thành công nhưng đến giờ vẫn chưa nhận được hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_02','V358','客服',2,'您好，麻烦先提供一下完整订单编号，我调取后台物流配送记录哈。','nín hǎo， má fán xiān tí gōng yī xià wán zhěng dìng dān biān hào， wǒ diào qǔ hòu tái wù liú pèi sòng jì lù hā。','Chào anh, phiền anh cung cấp mã đơn hàng đầy đủ trước, để tôi tra thông tin vận chuyển ở hệ thống nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_03','V358','阮明',3,'订单编号我复制在这里发给你，物流页面从下单当天一直显示待揽收状态呢。','dìng dān biān hào wǒ fù zhì zài zhè lǐ fā gěi nǐ， wù liú yè miàn cóng xià dān dàng tiān yì zhí xiǎn shì dài lǎn shōu zhuàng tài ne。','Mã đơn hàng tôi sao chép ở đây gửi cho chị, trang vận chuyển từ lúc đặt hàng đến giờ vẫn báo trạng thái chờ lấy hàng.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_04','V358','客服',4,'我调取仓库发货台账核对，查到是仓库工作人员漏打包商品，实在非常抱歉。','wǒ diào qǔ cāng kù fā huò tái zhàng hé duì， chá dào shì cāng kù gōng zuò rén yuán lòu dǎ bāo shāng pǐn， shí zài fēi cháng bào qiàn。','Tôi kiểm tra sổ xuất kho thì thấy nhân viên kho đã sót không đóng gói sản phẩm, thực sự rất xin lỗi anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_05','V358','阮明',5,'我下单已经七天，一直等待收货，耽误了我的使用计划，心里挺着急的。','wǒ xià dān yǐ jīng qī tiān， yì zhí děng dài shōu huò， dān wù le wǒ de shǐ yòng jì huà， xīn lǐ tǐng zháo jí de。','Tôi đặt hàng đã bảy ngày rồi, cứ chờ mãi mà chưa nhận được, làm ảnh hưởng đến kế hoạch sử dụng của tôi, trong lòng khá sốt ruột.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_06','V358','客服',6,'针对漏发问题平台提供两种解决方案，您可以自由选择，没有强制要求。','zhēn duì lòu fā wèn tí píng tái tí gōng liǎng zhǒng jiě jué fāng àn， nín kě yǐ zì yóu xuǎn zé， méi yǒu qiáng zhì yāo qiú。','Về vấn đề thiếu hàng này bên sàn có hai phương án giải quyết, anh có thể tự chọn, không bắt buộc theo cách nào cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_07','V358','阮明',7,'那现在第一种方案补发商品、第二种全额退款，两种分别需要等待多久？','nà xiàn zài dì yī zhǒng fāng àn bǔ fā shāng pǐn、 dì èr zhǒng quán é tuì kuǎn， liǎng zhǒng fēn bié xū yào děng dài duō jiǔ？','Vậy phương án một là gửi bù hàng, phương án hai là hoàn tiền toàn bộ, hai cách này mỗi cách phải chờ bao lâu vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_08','V358','客服',8,'选择补发需要重新排单发货，仓库备货需要再等三天；退款申请提交当日原路返还资金。','xuǎn zé bǔ fā xū yào chóng xīn pái dān fā huò， cāng kù bèi huò xū yào zài děng sān tiān； tuì kuǎn shēn qǐng tí jiāo dāng rì yuán lù fǎn huán zī jīn。','Nếu chọn gửi bù hàng thì phải xếp đơn giao lại từ đầu, kho cần chuẩn bị hàng thêm ba ngày nữa; còn hoàn tiền thì nộp yêu cầu ngày nào là tiền về ngay ngày đó theo đúng phương thức thanh toán ban đầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_09','V358','阮明',9,'我急需这件商品使用，不想再额外等待三天补发货品。','wǒ jí xū zhè jiàn shāng pǐn shǐ yòng， bù xiǎng zài é wài děng dài sān tiān bǔ fā huò pǐn。','Tôi đang cần gấp món hàng này để dùng, không muốn chờ thêm ba ngày để nhận hàng gửi bù nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_10','V358','客服',10,'我明白您的需求，那我直接为您提交全额退款售后申请。','wǒ míng bái nín de xū qiú， nà wǒ zhí jiē wèi nín tí jiāo quán é tuì kuǎn shòu hòu shēn qǐng。','Tôi hiểu nhu cầu của anh rồi, vậy để tôi nộp thẳng yêu cầu hoàn tiền toàn bộ cho anh luôn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_11','V358','阮明',11,'退款审核会不会需要人工排队，延迟好几天到账？','tuì kuǎn shěn hé huì bú huì xū yào rén gōng pái duì， yán chí hǎo jǐ tiān dào zhàng？','Việc duyệt hoàn tiền có phải xếp hàng chờ xử lý thủ công không, có bị chậm mấy ngày mới về tài khoản không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_12','V358','客服',12,'漏发属于商家全责，退款自动审核，几分钟内就能完成资金返还。','lòu fā shǔ yú shāng jiā quán zé， tuì kuǎn zì dòng shěn hé， jǐ fēn zhōng nèi jiù néng wán chéng zī jīn fǎn huán。','Trường hợp thiếu hàng là lỗi hoàn toàn của người bán, hoàn tiền sẽ được duyệt tự động, chỉ vài phút là tiền về tài khoản thôi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_13','V358','阮明',13,'那就直接办理全额退款吧，我不想继续等待补发货物了。','nà jiù zhí jiē bàn lǐ quán é tuì kuǎn ba， wǒ bù xiǎng jì xù děng dài bǔ fā huò wù le。','Vậy thì làm luôn hoàn tiền toàn bộ đi, tôi không muốn chờ gửi bù hàng nữa.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_14','V358','客服',14,'申请已提交，您留意支付软件的到账通知即可。','shēn qǐng yǐ tí jiāo， nín liú yì zhī fù ruǎn jiàn de dào zhàng tōng zhī jí kě。','Yêu cầu đã được gửi rồi ạ, anh chú ý thông báo nhận tiền trên ứng dụng thanh toán là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_15','V358','阮明',15,'好，感谢快速处理我的售后投诉。','hǎo， gǎn xiè kuài sù chǔ lǐ wǒ de shòu hòu tóu sù。','Vâng, cảm ơn chị đã xử lý nhanh khiếu nại của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT359','S120','Hỏi tuyến xe buýt đến trung tâm thành phố',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V359','SIT359','P1','suon_se','tuy_y',NULL,'国内城市公交支持手机二维码扫码乘车，无需单独购买公交卡，出行更方便。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_01','V359','阮明',1,'大叔您好，我想去市中心步行街，该坐哪一路公交啊？','dà shū nín hǎo， wǒ xiǎng qù shì zhōng xīn bù xíng jiē， gāi zuò nǎ yī lù gōng jiāo a？','Chào chú, con muốn ra phố đi bộ trung tâm thành phố, vậy phải đón xe buýt tuyến nào ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_02','V359','保安大叔',2,'出门右转站台坐12路，终点站就是市中心啦。','chū mén yòu zhuǎn zhàn tái zuò 12 lù， zhōng diǎn zhàn jiù shì shì zhōng xīn la。','Ra khỏi cổng rẽ phải là có trạm, đón tuyến 12, điểm cuối chính là trung tâm thành phố luôn đó.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_03','V359','阮明',3,'一趟车程大概要多久，会不会经常堵车呢？','yī tàng chē chéng dà gài yào duō jiǔ， huì bú huì jīng cháng dǔ chē ne？','Một chuyến đi mất khoảng bao lâu vậy chú, có hay bị kẹt xe không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_04','V359','保安大叔',4,'不堵车四十分钟，下班高峰期会慢一点。','bù dǔ chē sì shí fēn zhōng， xià bān gāo fēng qī huì màn yì diǎn。','Không kẹt xe thì bốn mươi phút, vào giờ tan tầm thì chậm hơn chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_05','V359','阮明',5,'公交支持手机扫码乘车，不用办实体卡对吧？','gōng jiāo zhī chí shǒu jī sǎo mǎ chéng chē， bù yòng bàn shí tǐ kǎ duì ba？','Xe buýt cho quét mã điện thoại để lên xe, không cần làm thẻ vật lý đúng không chú?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_06','V359','保安大叔',6,'没错，调出乘车码直接扫码就能上车。','méi cuò， diào chū chéng chē mǎ zhí jiē sǎo mǎ jiù néng shàng chē。','Đúng rồi, mở mã đi xe ra quét là lên xe được ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_07','V359','阮明',7,'太感谢大叔指路，我现在就去站台等车吧。','tài gǎn xiè dà shū zhǐ lù， wǒ xiàn zài jiù qù zhàn tái děng chē ba。','Cảm ơn chú chỉ đường nhiều nha, giờ con ra trạm đợi xe luôn đây ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT360','S121','Nạp tiền vào thẻ tàu điện',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V360','SIT360','P1','twist','tuy_y',NULL,'地铁自助充值机偶尔出现系统延迟扣款不到账，等待片刻或联系站内工作人员即可解决。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_01','V360','阮明',1,'同学，这个自助机怎么给地铁交通卡充值啊？','tóng xué， zhè ge zì zhù jī zěn me gěi dì tiě jiāo tōng kǎ chōng zhí a？','Bạn ơi, cái máy tự phục vụ này nạp tiền vào thẻ tàu điện ngầm kiểu gì vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_02','V360','志愿者',2,'先把卡片放在感应区，再选择充值金额扫码付款。','xiān bǎ kǎ piàn fàng zài gǎn yìng qū， zài xuǎn zé chōng zhí jīn é sǎo mǎ fù kuǎn。','Đặt thẻ vào khu vực cảm ứng trước, rồi chọn số tiền cần nạp và quét mã thanh toán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_03','V360','阮明',3,'我扫码支付之后，机器提示充值失败嘛。','wǒ sǎo mǎ zhī fù zhī hòu， jī qì tí shì chōng zhí shī bài ma。','Mình quét mã thanh toán xong rồi, máy báo nạp tiền thất bại nè.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_04','V360','阮明',4,'手机扣款了，但是卡里余额没有增加。','shǒu jī kòu kuǎn le， dàn shì kǎ lǐ yú é méi yǒu zēng jiā。','Điện thoại đã bị trừ tiền rồi, nhưng số dư trong thẻ không tăng lên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_05','V360','志愿者',5,'别着急，系统延迟，五分钟后再查询余额就行。','bié zháo jí， xì tǒng yán chí， wǔ fēn zhōng hòu zài chá xún yú é jiù xíng。','Đừng lo, do hệ thống bị trễ thôi, năm phút sau kiểm tra lại số dư là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_06','V360','阮明',6,'原来是系统卡顿，我等一会儿再看余额。','yuán lái shì xì tǒng kǎ dùn， wǒ děng yī huì er zài kàn yú é。','Thì ra là hệ thống bị đơ, để mình đợi một lát rồi xem lại số dư.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_07','V360','阮明',7,'还好有你帮忙讲解，不然我都不知道怎么办啦。','hái hǎo yǒu nǐ bāng máng jiǎng jiě， bù rán wǒ dōu bù zhī dào zěn me bàn la。','May mà có bạn giúp giải thích, không thì mình chẳng biết phải làm sao luôn á.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT361','S122','Mở khóa và thuê xe đạp công cộng qua app',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V361','SIT361','P1','twist','tuy_y',NULL,'国内共享单车依靠手机App扫码、蓝牙联动解锁，故障车辆可免费更换，不会扣费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_01','V361','阮明',1,'同学，我扫码共享单车怎么一直开锁失败啊？','tóng xué， wǒ sǎo mǎ gòng xiǎng dān chē zěn me yì zhí kāi suǒ shī bài a？','Bạn ơi, sao mình quét mã xe đạp chung mà mở khóa hoài không được vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_02','V361','小杨',2,'你看看手机蓝牙开了吗，骑车必须打开蓝牙呢。','nǐ kàn kàn shǒu jī lán yá kāi le ma， qí chē bì xū dǎ kāi lán yá ne。','Cậu xem thử điện thoại đã bật Bluetooth chưa, muốn đi xe là phải bật Bluetooth đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_03','V361','阮明',3,'蓝牙是打开的，页面一直显示车辆故障。','lán yá shì dǎ kāi de， yè miàn yì zhí xiǎn shì chē liàng gù zhàng。','Bluetooth thì mình bật rồi, mà màn hình cứ báo xe bị lỗi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_04','V361','小杨',4,'那这辆车出问题了，直接点换车按钮就行啦。','nà zhè liàng chē chū wèn tí le， zhí jiē diǎn huàn chē àn niǔ jiù xíng la。','Vậy là xe này bị hỏng rồi, cậu bấm nút đổi xe khác là được mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_05','V361','阮明',5,'原来是这样，我还以为是我的账号有问题。','yuán lái shì zhè yàng， wǒ hái yǐ wéi shì wǒ de zhàng hào yǒu wèn tí。','Thì ra là vậy, mình cứ tưởng tài khoản của mình có vấn đề chứ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_06','V361','小杨',6,'路边很多备用单车，换一辆很快就能解锁。','lù biān hěn duō bèi yòng dān chē， huàn yī liàng hěn kuài jiù néng jiě suǒ。','Bên đường có nhiều xe dự phòng lắm, đổi xe khác là mở khóa được ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_07','V361','阮明',7,'太谢谢你提醒我，不然我要在这里耗好久。','tài xiè xiè nǐ tí xǐng wǒ， bù rán wǒ yào zài zhè lǐ hào hǎo jiǔ。','Cảm ơn cậu nhắc mình nhiều nha, không thì mình phải đứng đây lâu lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT362','S123','Thuê xe máy điện ngắn ngày',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V362','SIT362','P1','suon_se','ban_chinh_thuc',NULL,'国内电动车租赁门店大多需要押证件，归还车辆无损坏后立即返还证件押金。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_01','V362','阮明',1,'老板你好，我想租一辆电动车，只用半天可以吗？','lǎo bǎn nǐ hǎo， wǒ xiǎng zū yī liàng diàn dòng chē， zhǐ yòng bàn tiān kě yǐ ma？','Chào anh, tôi muốn thuê một chiếc xe điện, chỉ dùng nửa ngày thôi có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_02','V362','老板',2,'没问题，半天三十块，需要押你的护照登记哦。','méi wèn tí， bàn tiān sān shí kuài， xū yào yā nǐ de hù zhào dēng jì ó。','Không vấn đề gì, nửa ngày là ba mươi tệ, cần giữ hộ chiếu của bạn để đăng ký nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_03','V362','阮明',3,'骑车去城郊景点，电量来回足够吗？','qí chē qù chéng jiāo jǐng diǎn， diàn liàng lái huí zú gòu ma？','Tôi định đi xe ra khu du lịch ngoại ô, pin đi về như vậy có đủ không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_04','V362','老板',4,'满电续航五十公里，短途出行完全够用的。','mǎn diàn xù háng wǔ shí gōng lǐ， duǎn tú chū xíng wán quán gòu yòng de。','Sạc đầy chạy được năm mươi ki-lô-mét, đi quãng đường ngắn thì thoải mái đủ dùng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_05','V362','阮明',5,'路上万一没电，店里有应急充电设备吧？','lù shàng wàn yī méi diàn， diàn lǐ yǒu yìng jí chōng diàn shè bèi ba？','Lỡ giữa đường hết pin thì cửa hàng có thiết bị sạc khẩn cấp chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_06','V362','老板',6,'店里有便携充电器，你可以随身带着备用。','diàn lǐ yǒu biàn xié chōng diàn qì， nǐ kě yǐ suí shēn dài zhe bèi yòng。','Cửa hàng có sạc dự phòng cầm tay, bạn có thể mang theo để phòng khi cần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_07','V362','阮明',7,'好，那我现在登记租车，麻烦你啦。','hǎo， nà wǒ xiàn zài dēng jì zū chē， má fán nǐ la。','Vâng, vậy giờ tôi đăng ký thuê xe luôn, phiền anh giúp nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT363','S124','Mua vé tàu cao tốc về quê vào kỳ nghỉ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V363','SIT363','P1','twist','ban_chinh_thuc',NULL,'外籍留学生使用护照购买高铁票，部分自助设备无法识别，必须前往人工窗口办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_01','V363','阮明',1,'你好，我想用自助机买一张周末去邻市的高铁票。','nǐ hǎo， wǒ xiǎng yòng zì zhù jī mǎi yī zhāng zhōu mò qù lín shì de gāo tiě piào。','Chào bạn, tôi muốn dùng máy tự động mua một vé tàu cao tốc đi thành phố bên cạnh vào cuối tuần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_02','V363','引导员',2,'先把护照放在读卡区，再输入目的地站点就行。','xiān bǎ hù zhào fàng zài dú kǎ qū， zài shū rù mù dì dì zhàn diǎn jiù xíng。','Bạn đặt hộ chiếu vào khu vực đọc thẻ trước, sau đó nhập ga đến là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_03','V363','阮明',3,'我选好车次，系统提示外籍证件无法线上核验嘛。','wǒ xuǎn hǎo chē cì， xì tǒng tí shì wài jí zhèng jiàn wú fǎ xiàn shàng hé yàn ma。','Tôi chọn chuyến rồi mà hệ thống báo giấy tờ nước ngoài không xác thực trực tuyến được.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_04','V363','引导员',4,'这种情况要去人工窗口，工作人员手动录入信息。','zhè zhǒng qíng kuàng yào qù rén gōng chuāng kǒu， gōng zuò rén yuán shǒu dòng lù rù xìn xī。','Trường hợp này bạn phải ra quầy giao dịch trực tiếp, nhân viên sẽ nhập thông tin thủ công cho bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_05','V363','阮明',5,'人工窗口排队人多吗，大概要等多久呢？','rén gōng chuāng kǒu pái duì rén duō ma， dà gài yào děng duō jiǔ ne？','Quầy giao dịch có đông người xếp hàng không, ước chừng phải đợi bao lâu vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_06','V363','引导员',6,'现在人不多，十分钟左右就能完成购票。','xiàn zài rén bù duō， shí fēn zhōng zuǒ yòu jiù néng wán chéng gòu piào。','Bây giờ không đông lắm, khoảng mười phút là mua xong vé thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_07','V363','阮明',7,'好，我马上过去人工窗口办理，感谢指引。','hǎo， wǒ mǎ shàng guò qù rén gōng chuāng kǒu bàn lǐ， gǎn xiè zhǐ yǐn。','Vâng, tôi ra quầy làm ngay đây, cảm ơn bạn đã chỉ dẫn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT364','S124','Đổi vé tàu cao tốc vì thay đổi lịch trình',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V364','SIT364','P1','suon_se','ban_chinh_thuc',NULL,'高铁车票发车前可免费改签一次，仅变更乘车时间，目的地不变无需额外付费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_01','V364','阮明',1,'您好，我买了明天上午的高铁票，想改签成下午班次。','nín hǎo， wǒ mǎi le míng tiān shàng wǔ de gāo tiě piào， xiǎng gǎi qiān chéng xià wǔ bān cì。','Chào chị, tôi đã mua vé tàu cao tốc sáng mai, giờ muốn đổi sang chuyến buổi chiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_02','V364','售票员',2,'出示购票用的护照，我帮你查询余票情况哈。','chū shì gòu piào yòng de hù zhào， wǒ bāng nǐ chá xún yú piào qíng kuàng hā。','Bạn cho tôi xem hộ chiếu đã dùng để mua vé, tôi kiểm tra vé còn trống giúp bạn nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_03','V364','阮明',3,'改签需要额外收取手续费吗？','gǎi qiān xū yào é wài shōu qǔ shǒu xù fèi ma？','Đổi vé như vậy có phải trả thêm phí gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_04','V364','售票员',4,'发车前免费改签一次，第二次改签才会收费呢。','fā chē qián miǎn fèi gǎi qiān yī cì， dì èr cì gǎi qiān cái huì shōu fèi ne。','Trước giờ tàu chạy được đổi vé miễn phí một lần, đổi lần thứ hai mới tính phí đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_05','V364','阮明',5,'下午三点那趟还有空余座位对吧？','xià wǔ sān diǎn nà tàng hái yǒu kòng yú zuò wèi duì ba？','Chuyến ba giờ chiều vẫn còn chỗ trống đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_06','V364','售票员',6,'还有二等座，我直接帮你更改车次信息。','hái yǒu èr děng zuò， wǒ zhí jiē bāng nǐ gēng gǎi chē cì xìn xī。','Còn ghế hạng hai, để tôi đổi luôn thông tin chuyến tàu cho bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_07','V364','阮明',7,'辛苦你了，行程临时变动实在不好意思。','xīn kǔ nǐ le， xíng chéng lín shí biàn dòng shí zài bù hǎo yì sī。','Cảm ơn chị vất vả rồi, lịch trình đổi đột xuất thế này thật ngại quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT365','S125','Đặt taxi đi khám bệnh gấp',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V365','SIT365','P1','suon_se','ban_chinh_thuc',NULL,'网约车支持目的地精准定位，紧急就医可备注需求，司机会优先规划快速路线。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_01','V365','阮明',1,'师傅麻烦快一点，我身体不舒服要赶去医院啊。','shī fù má fán kuài yì diǎn， wǒ shēn tǐ bù shū fú yào gǎn qù yī yuàn a。','Anh tài xế ơi làm ơn chạy nhanh giúp tôi chút, tôi đang khó chịu trong người cần đến bệnh viện gấp.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_02','V365','司机',2,'放心，我避开堵车路段，尽量缩短路上时间。','fàng xīn， wǒ bì kāi dǔ chē lù duàn， jǐn liàng suō duǎn lù shàng shí jiān。','Anh yên tâm, tôi sẽ tránh đoạn kẹt xe, cố gắng rút ngắn thời gian trên đường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_03','V365','阮明',3,'到医院正门下车，不用停地下车库可以吧？','dào yī yuàn zhèng mén xià chē， bù yòng tíng dì xià chē kù kě yǐ ba？','Cho tôi xuống ở cổng chính bệnh viện, không cần vào hầm để xe được chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_04','V365','司机',4,'没问题，正门临时上下客区域可以短暂停靠。','méi wèn tí， zhèng mén lín shí shàng xià kè qū yù kě yǐ duǎn zàn tíng kào。','Không vấn đề gì, khu vực đón trả khách tạm thời ở cổng chính có thể dừng ngắn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_05','V365','阮明',5,'我头晕得厉害，麻烦开车平稳一点呢。','wǒ tóu yūn dé lì hài， má fán kāi chē píng wěn yì diǎn ne。','Tôi chóng mặt dữ lắm, phiền anh chạy xe êm một chút giúp tôi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_06','V365','司机',6,'我放慢车速，有不舒服你随时跟我说。','wǒ fàng màn chē sù， yǒu bù shū fú nǐ suí shí gēn wǒ shuō。','Tôi sẽ chạy chậm lại, có khó chịu gì thì cứ nói với tôi bất cứ lúc nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_07','V365','阮明',7,'太感谢师傅体谅我，到地方我立刻付款。','tài gǎn xiè shī fù tǐ liàng wǒ， dào dì fāng wǒ lì kè fù kuǎn。','Cảm ơn anh đã thông cảm cho tôi nhiều, đến nơi tôi thanh toán ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT366','S120','Hỏi giờ chuyến xe buýt cuối cùng trong ngày',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V366','SIT366','P1','twist','tuy_y',NULL,'公交末班时间会根据工作日、节假日临时调整，站台工作人员可实时查询当日运营时刻。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_01','V366','阮明',1,'您好，请问18路公交今晚末班车几点发车呀？','nín hǎo， qǐng wèn 18 lù gōng jiāo jīn wǎn mò bān chē jǐ diǎn fā chē ya？','Chào bạn, cho hỏi xe buýt tuyến 18 tối nay chuyến cuối chạy lúc mấy giờ vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_02','V366','工作人员',2,'平常九点半，今天线路临时调整，九点就收班了嘛。','píng cháng jiǔ diǎn bàn， jīn tiān xiàn lù lín shí diào zhěng， jiǔ diǎn jiù shōu bān le ma。','Bình thường là chín giờ rưỡi, nhưng hôm nay tuyến đổi lịch đột xuất, chín giờ là hết chuyến rồi đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_03','V366','阮明',3,'这么早？那错过这趟车还有别的换乘路线吗？','zhè me zǎo？ nà cuò guò zhè tàng chē hái yǒu bié de huàn chéng lù xiàn ma？','Sớm vậy sao? Vậy lỡ chuyến này thì còn tuyến nào chuyển sang được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_04','V366','工作人员',4,'可以转地铁，地铁末班车十一点才停运。','kě yǐ zhuǎn dì tiě， dì tiě mò bān chē shí yì diǎn cái tíng yùn。','Có thể chuyển qua tàu điện ngầm, chuyến cuối của tàu điện phải mười một giờ mới ngừng chạy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_05','V366','阮明',5,'步行到地铁站大概需要几分钟呢？','bù xíng dào dì tiě zhàn dà gài xū yào jǐ fēn zhōng ne？','Đi bộ đến ga tàu điện ngầm khoảng mấy phút vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_06','V366','工作人员',6,'七八分钟，顺着人行道直走就能看见入口。','qī bā fēn zhōng， shùn zhe rén xíng dào zhí zǒu jiù néng kàn jiàn rù kǒu。','Khoảng bảy tám phút thôi, đi thẳng theo vỉa hè là thấy lối vào ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_07','V366','阮明',7,'好，那我提前出发去坐地铁，多谢告知。','hǎo， nà wǒ tí qián chū fā qù zuò dì tiě， duō xiè gào zhī。','Được rồi, vậy mình đi sớm để bắt tàu điện, cảm ơn bạn nhiều nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT367','S121','Hỏi lối ra gần nhất tới địa điểm cần đến',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V367','SIT367','P1','suon_se','tuy_y',NULL,'大型商场划分专门网约车上下客出口，普通主干道禁止车辆临时停靠，避免拥堵。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_01','V367','阮明',1,'师傅，我想打车，最近的商场出口往哪边走呢？','shī fù， wǒ xiǎng dǎ chē， zuì jìn de shāng chǎng chū kǒu wǎng nǎ biān zǒu ne？','Anh ơi, tôi muốn bắt taxi, lối ra gần nhất của trung tâm thương mại đi hướng nào vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_02','V367','安保人员',2,'直走到中庭右转，一号门就是打车专用出口哦。','zhí zǒu dào zhōng tíng yòu zhuǎn， yī hào mén jiù shì dǎ chē zhuān yòng chū kǒu ó。','Đi thẳng tới sảnh giữa rồi rẽ phải, cổng số 1 chính là lối ra dành riêng cho taxi đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_03','V367','阮明',3,'一号门外面有专门的等候区域吧？','yī hào mén wài miàn yǒu zhuān mén de děng hòu qū yù ba？','Bên ngoài cổng số 1 có khu vực chờ riêng đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_04','V367','安保人员',4,'有的，路边不能随便停车，只能在指定区域等车。','yǒu de， lù biān bù néng suí biàn tíng chē， zhǐ néng zài zhǐ dìng qū yù děng chē。','Có chứ, ven đường không được dừng xe tùy tiện đâu, chỉ được chờ xe ở khu vực quy định thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_05','V367','阮明',5,'我拎了不少东西，这条路线没有台阶对吗？','wǒ līn le bù shǎo dōng xī， zhè tiáo lù xiàn méi yǒu tái jiē duì ma？','Tôi xách khá nhiều đồ, đường này không có bậc thềm gì đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_06','V367','安保人员',6,'全程平坦通道，推行李箱、拎重物都方便。','quán chéng píng tǎn tōng dào， tuī xíng lǐ xiāng、 līn zhòng wù dōu fāng biàn。','Cả đoạn đường đều bằng phẳng, đẩy vali hay xách đồ nặng cũng thoải mái.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_07','V367','阮明',7,'清楚了，麻烦你指路啦。','qīng chǔ le， má fán nǐ zhǐ lù la。','Rõ rồi, cảm ơn anh chỉ đường nha.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT368','S123','Trả xe thuê trễ giờ, hỏi phụ phí',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V368','SIT368','P1','twist','ban_chinh_thuc',NULL,'共享电单车设置固定免费时长，超时产生溢价费用，平台优惠券一般仅抵扣基础租赁费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_01','V368','阮明',1,'你好，我租的共享电车超时半小时，要补多少钱？','nǐ hǎo， wǒ zū de gòng xiǎng diàn chē chāo shí bàn xiǎo shí， yào bǔ duō shǎo qián？','Chào anh, xe điện chia sẻ tôi thuê bị quá giờ nửa tiếng, vậy phải trả thêm bao nhiêu ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_02','V368','运维员',2,'基础时长两小时，超出后每半小时加收五元哈。','jī chǔ shí cháng liǎng xiǎo shí， chāo chū hòu měi bàn xiǎo shí jiā shōu wǔ yuán hā。','Thời gian cơ bản là hai tiếng, quá giờ thì mỗi nửa tiếng tính thêm năm tệ nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_03','V368','阮明',3,'页面提示有超时罚款，不能直接抵扣优惠券嘛？','yè miàn tí shì yǒu chāo shí fá kuǎn， bù néng zhí jiē dǐ kòu yōu huì quàn ma？','Trên màn hình báo có phí phạt quá giờ, không dùng phiếu giảm giá để trừ trực tiếp được à?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_04','V368','运维员',4,'超时产生的额外费用不支持优惠券抵扣的。','chāo shí chǎn shēng de é wài fèi yòng bù zhī chí yōu huì quàn dǐ kòu de。','Phí phát sinh do quá giờ thì không áp dụng phiếu giảm giá được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_05','V368','阮明',5,'原来是这样，那我直接微信扫码支付就行？','yuán lái shì zhè yàng， nà wǒ zhí jiē wēi xìn sǎo mǎ zhī fù jiù xíng？','Thì ra là vậy, vậy tôi quét mã WeChat thanh toán trực tiếp là được chứ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_06','V368','运维员',6,'对，站点二维码扫码就能结清所有费用。','duì， zhàn diǎn èr wéi mǎ sǎo mǎ jiù néng jié qīng suǒ yǒu fèi yòng。','Đúng rồi, quét mã QR tại trạm là thanh toán xong hết tất cả chi phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_07','V368','阮明',7,'好，我马上付款，下次一定看好还车时限。','hǎo， wǒ mǎ shàng fù kuǎn， xià cì yí dìng kàn hǎo hái chē shí xiàn。','Được, tôi thanh toán ngay đây, lần sau nhất định phải để ý giờ trả xe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT369','S126','Báo mất hộ chiếu với cảnh sát',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V369','SIT369','P1','suon_se','chinh_thuc',NULL,'外籍人士丢失护照必须先到派出所开具遗失报案回执，再前往出入境大厅办理临时通行证明，后续可凭回执到本国驻华大使馆补办正式护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_01','V369','阮明',1,'警官您好，我有紧急情况，今天出门逛街把本人护照弄丢了，前来派出所报案。','jǐng guān nín hǎo， wǒ yǒu jǐn jí qíng kuàng， jīn tiān chū mén guàng jiē bǎ běn rén hù zhào nòng diū le， qián lái pài chū suǒ bào àn。','Chào công an, tôi có việc gấp, hôm nay ra ngoài dạo phố bị mất hộ chiếu, tôi đến đồn để trình báo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_02','V369','民警',2,'你先平复一下情绪，我们一步步核对信息，先告诉我你的基础个人信息。','nǐ xiān píng fù yī xià qíng xù， wǒ men yí bù bù hé duì xìn xī， xiān gào sù wǒ nǐ de jī chǔ gè rén xìn xī。','Anh/chị bình tĩnh lại một chút, chúng tôi sẽ đối chiếu thông tin từng bước, trước tiên cho tôi biết thông tin cá nhân cơ bản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_03','V369','阮明',3,'我叫阮明，二十二岁越南留学生，在本市高校就读汉语言专业。','wǒ jiào ruǎn míng， èr shí èr suì yuè nán liú xué shēng， zài běn shì gāo xiào jiù dú hàn yǔ yán zhuān yè。','Tôi tên Nguyễn Minh, hai mươi hai tuổi, du học sinh Việt Nam, đang học ngành tiếng Trung tại một trường đại học ở thành phố này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_04','V369','民警',4,'接下来详细描述今天完整出行路线，从出门到发现遗失护照的全过程。','jiē xià lái xiáng xì miáo shù jīn tiān wán zhěng chū xíng lù xiàn， cóng chū mén dào fā xiàn yí shī hù zhào de quán guò chéng。','Tiếp theo hãy mô tả chi tiết toàn bộ lộ trình di chuyển hôm nay, từ lúc ra khỏi nhà đến lúc phát hiện mất hộ chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_05','V369','阮明',5,'中午十二点从学校宿舍出发，先去街边小吃店吃饭，下午两点抵达中心商业街。','zhōng wǔ shí èr diǎn cóng xué xiào sù shè chū fā， xiān qù jiē biān xiǎo chī diàn chī fàn， xià wǔ liǎng diǎn dǐ dá zhōng xīn shāng yè jiē。','Trưa mười hai giờ tôi xuất phát từ ký túc xá, trước tiên ghé quán ăn vặt ven đường ăn trưa, đến hai giờ chiều thì tới khu phố thương mại trung tâm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_06','V369','民警',6,'商业街范围很大，精确回忆遗失护照的时间段和具体店铺名称吧。','shāng yè jiē fàn wéi hěn dà， jīng què huí yì yí shī hù zhào de shí jiān duàn hé jù tǐ diàn pù míng chēng ba。','Khu phố thương mại rộng lắm, cố nhớ chính xác khoảng thời gian mất hộ chiếu và tên cửa hàng cụ thể nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_07','V369','阮明',7,'下午三点左右，在商业街二楼文具店结账付款，走出店铺口袋就空了，护照不见了呢。','xià wǔ sān diǎn zuǒ yòu， zài shāng yè jiē èr lóu wén jù diàn jié zhàng fù kuǎn， zǒu chū diàn pù kǒu dài jiù kōng le， hù zhào bú jiàn le ne。','Khoảng ba giờ chiều, tôi thanh toán ở cửa hàng văn phòng phẩm tầng hai khu thương mại, vừa bước ra khỏi cửa thì túi đã trống trơn, hộ chiếu biến mất luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_08','V369','民警',8,'遗失之后你有没有原路返回店铺寻找，或者向店内店员求助查看监控？','yí shī zhī hòu nǐ yǒu méi yǒu yuán lù fǎn huí diàn pù xún zhǎo， huò zhě xiàng diàn nèi diàn yuán qiú zhù chá kàn jiān kòng？','Sau khi mất, anh có quay lại cửa hàng tìm không, hoặc nhờ nhân viên trong cửa hàng kiểm tra camera an ninh giúp không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_09','V369','阮明',9,'我返回文具店询问店员，他们柜台没有捡到护照，商铺监控只能由派出所出具证明才能调取。','wǒ fǎn huí wén jù diàn xún wèn diàn yuán， tā men guì tái méi yǒu jiǎn dào hù zhào， shāng pù jiān kòng zhǐ néng yóu pài chū suǒ chū jù zhèng míng cái néng diào qǔ。','Tôi có quay lại cửa hàng văn phòng phẩm hỏi nhân viên, quầy của họ không nhặt được hộ chiếu, còn camera cửa hàng thì phải có giấy xác nhận của công an mới trích xuất được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_10','V369','民警',10,'我现在为你制作一份标准遗失报案记录，需要你填写国籍、护照编号、在校信息。','wǒ xiàn zài wèi nǐ zhì zuò yī fèn biāo zhǔn yí shī bào àn jì lù， xū yào nǐ tián xiě guó jí、 hù zhào biān hào、 zài xiào xìn xī。','Bây giờ tôi lập biên bản trình báo mất giấy tờ theo mẫu chuẩn, cần anh điền quốc tịch, số hộ chiếu và thông tin trường học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_11','V369','阮明',11,'我手机里存了护照复印件照片，可以直接对照填写表格上的全部信息。','wǒ shǒu jī lǐ cún le hù zhào fù yìn jiàn zhào piān， kě yǐ zhí jiē duì zhào tián xiě biǎo gé shàng de quán bù xìn xī。','Trong điện thoại tôi có lưu ảnh chụp bản photo hộ chiếu, có thể đối chiếu để điền đầy đủ thông tin vào biểu mẫu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_12','V369','民警',12,'笔录填写完毕核对无误后签字，我打印报案回执交给你保管。','bǐ lù tián xiě wán bì hé duì wú wù hòu qiān zì， wǒ dǎ yìn bào àn huí zhí jiāo gěi nǐ bǎo guǎn。','Sau khi điền xong biên bản và kiểm tra không sai sót thì ký tên, tôi sẽ in biên nhận trình báo đưa cho anh giữ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_13','V369','阮明',13,'做完这份遗失笔录，拿着纸质回执就能直接去出入境大厅办理临时通行证件吗？','zuò wán zhè fèn yí shī bǐ lù， ná zhe zhǐ zhì huí zhí jiù néng zhí jiē qù chū rù jìng dà tīng bàn lǐ lín shí tōng xíng zhèng jiàn ma？','Làm xong biên bản mất giấy tờ này, cầm biên nhận giấy là có thể đến thẳng phòng xuất nhập cảnh để làm giấy thông hành tạm thời được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_14','V369','民警',14,'是的，这份派出所开具的报案回执是外籍人员补办证件必需的官方材料。','shì de， zhè fèn pài chū suǒ kāi jù de bào àn huí zhí shì wài jí rén yuán bǔ bàn zhèng jiàn bì xū de guān fāng cái liào。','Đúng vậy, biên nhận trình báo do đồn công an cấp là giấy tờ chính thức bắt buộc để người nước ngoài làm lại giấy tờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_15','V369','阮明',15,'给警官增添办案工作量实在不好意思，辛苦您帮忙登记备案。','gěi jǐng guān zēng tiān bàn àn gōng zuò liàng shí zài bù hǎo yì sī， xīn kǔ nín bāng máng dēng jì bèi àn。','Làm phiền anh mất công việc nhiều quá, thật ngại quá, cảm ơn anh đã giúp đăng ký hồ sơ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_16','V369','民警',16,'保护外籍留学生证件安全是我们的工作，后续补办遇到问题可以再来咨询。','bǎo hù wài jí liú xué shēng zhèng jiàn ān quán shì wǒ men de gōng zuò， hòu xù bǔ bàn yù dào wèn tí kě yǐ zài lái zī xún。','Bảo vệ an toàn giấy tờ cho du học sinh nước ngoài là công việc của chúng tôi, sau này làm lại giấy tờ có gì cứ đến hỏi thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_17','V369','阮明',17,'太感谢警官耐心登记信息！','tài gǎn xiè jǐng guān nài xīn dēng jì xìn xī！','Cảm ơn công an rất nhiều vì đã kiên nhẫn ghi nhận thông tin ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT370','S126','Báo mất ví tiền nơi công cộng',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V370','SIT370','P1','twist','ban_chinh_thuc',NULL,'商场、餐厅等公共场所设有失物招领处，捡到私人物品大多会统一送至前台保管；领取失物需要核对专属标识确认归属。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_01','V370','阮明',1,'你好，我刚才在商场三楼餐饮区用餐，离开后发现黑色钱包丢失，想申请广播寻物。','nǐ hǎo， wǒ gāng cái zài shāng chǎng sān lóu cān yǐn qū yòng cān， lí kāi hòu fā xiàn hēi sè qián bāo diū shī， xiǎng shēn qǐng guǎng bō xún wù。','Chào chị, lúc nãy tôi ăn ở khu ẩm thực tầng ba trung tâm thương mại, rời đi thì phát hiện mất ví màu đen, muốn nhờ phát loa tìm giúp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_02','V370','客服',2,'您好，先跟您确认，丢失的钱包里面包含哪些重要物品，方便广播描述特征哦。','nín hǎo， xiān gēn nín què rèn， diū shī de qián bāo lǐ miàn bāo hán nǎ xiē zhòng yào wù pǐn， fāng biàn guǎng bō miáo shù tè zhēng ó。','Chào anh, để tôi xác nhận trước, trong ví bị mất có những vật dụng quan trọng nào, để tiện mô tả đặc điểm khi phát loa nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_03','V370','阮明',3,'里面有人民币现金、国内储蓄卡、留学生校园卡，全部对我非常重要。','lǐ miàn yǒu rén mín bì xiàn jīn、 guó nèi chǔ xù kǎ、 liú xué shēng xiào yuán kǎ， quán bù duì wǒ fēi cháng zhòng yào。','Bên trong có tiền mặt Việt Nam đồng... à không, có tiền nhân dân tệ, thẻ ngân hàng trong nước, thẻ sinh viên quốc tế, tất cả đều rất quan trọng với tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_04','V370','客服',4,'我现在立刻播放全场寻物广播，麻烦完整描述钱包外观细节，提高捡到者识别概率。','wǒ xiàn zài lì kè bō fàng quán chǎng xún wù guǎng bō， má fán wán zhěng miáo shù qián bāo wài guān xì jié， tí gāo jiǎn dào zhě shí bié gài lǜ。','Tôi phát loa tìm đồ trên toàn khu ngay bây giờ, phiền anh mô tả đầy đủ chi tiết bề ngoài của ví để tăng khả năng người nhặt được nhận ra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_05','V370','阮明',5,'纯黑色短款皮质钱包，侧面有一道浅色划痕，里面放着越南留学生专属校园卡。','chún hēi sè duǎn kuǎn pí zhì qián bāo， cè miàn yǒu yī dào qiǎn sè huà hén， lǐ miàn fàng zhe yuè nán liú xué shēng zhuān shǔ xiào yuán kǎ。','Ví da ngắn màu đen trơn, mặt bên có một vết xước màu nhạt, bên trong có thẻ sinh viên riêng của du học sinh Việt Nam.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_06','V370','客服',6,'刚好半小时前商场保洁阿姨打扫餐厅，捡到一个黑色钱包送到前台保管，我拿给你核对嘛。','gāng hǎo bàn xiǎo shí qián shāng chǎng bǎo jié ā yí dǎ sǎo cān tīng， jiǎn dào yí gè hēi sè qián bāo sòng dào qián tái bǎo guǎn， wǒ ná gěi nǐ hé duì ma。','Vừa đúng nửa tiếng trước cô lao công của trung tâm thương mại dọn dẹp khu ẩm thực có nhặt được một chiếc ví màu đen mang lên quầy lễ tân giữ, để tôi lấy cho anh kiểm tra nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_07','V370','阮明',7,'真的吗？里面一定会有印有越南国旗标识的留学生校园卡对吧？','zhēn de ma？ lǐ miàn yí dìng huì yǒu yìn yǒu yuè nán guó qí biāo shí de liú xué shēng xiào yuán kǎ duì ba？','Thật ạ? Bên trong chắc chắn có thẻ sinh viên in cờ Việt Nam đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_08','V370','客服',8,'没错，钱包内确实有这张校园卡，你当面清点里面所有物品确认齐全再拿走。','méi cuò， qián bāo nèi què shí yǒu zhè zhāng xiào yuán kǎ， nǐ dāng miàn qīng diǎn lǐ miàn suǒ yǒu wù pǐn què rèn qí quán zài ná zǒu。','Đúng vậy, trong ví đúng là có thẻ sinh viên này, anh kiểm đếm trực tiếp tất cả đồ vật bên trong xem có đủ không rồi hãy nhận lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_09','V370','阮明',9,'现金、银行卡、校园卡全部完好，一样东西都没有缺少，太幸运了。','xiàn jīn、 yín háng kǎ、 xiào yuán kǎ quán bù wán hǎo， yī yàng dōng xī dōu méi yǒu quē shǎo， tài xìng yùn le。','Tiền mặt, thẻ ngân hàng, thẻ sinh viên đều còn nguyên, không thiếu thứ gì cả, may quá đi mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_10','V370','客服',10,'商场所有拾获私人物品都会统一送至前台失物招领处登记保管。','shāng chǎng suǒ yǒu shí huò sī rén wù pǐn dōu huì tǒng yī sòng zhì qián tái shī wù zhāo lǐng chù dēng jì bǎo guǎn。','Tất cả đồ nhặt được ở trung tâm thương mại đều được gom về quầy thất lạc để đăng ký và bảo quản chung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_11','V370','阮明',11,'还好保洁阿姨细心捡到上交，不然补办银行卡、证件要耗费大量时间。','hái hǎo bǎo jié ā yí xì xīn jiǎn dào shàng jiāo， bù rán bǔ bàn yín háng kǎ、 zhèng jiàn yào hào fèi dà liàng shí jiān。','May mà cô lao công cẩn thận nhặt được rồi nộp lại, chứ không thì làm lại thẻ ngân hàng, giấy tờ sẽ tốn rất nhiều thời gian.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_12','V370','客服',12,'下次出门贵重物品尽量贴身放好，避免遗失。','xià cì chū mén guì zhòng wù pǐn jǐn liàng tiē shēn fàng hǎo， bì miǎn yí shī。','Lần sau ra ngoài đồ vật quý giá nên cố gắng mang sát người để tránh bị mất nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_13','V370','阮明',13,'我记住了，非常感谢你们帮忙妥善保管我的钱包。','wǒ jì zhù le， fēi cháng gǎn xiè nǐ men bāng máng tuǒ shàn bǎo guǎn wǒ de qián bāo。','Tôi ghi nhớ rồi, cảm ơn mọi người rất nhiều vì đã giúp bảo quản ví cho tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_14','V370','客服',14,'不用客气，这是我们商场该做的。','bù yòng kè qì， zhè shì wǒ men shāng chǎng gāi zuò de。','Không có gì đâu, đây là việc chúng tôi nên làm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_15','V370','阮明',15,'麻烦各位工作人员了！','má fán gè wèi gōng zuò rén yuán le！','Làm phiền các anh chị nhân viên nhiều quá!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT371','S126','Báo mất điện thoại, xin khóa SIM từ xa',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V371','SIT371','P1','suon_se','chinh_thuc',NULL,'手机丢失后可致电运营商紧急挂失SIM卡，补办卡片可保留原有手机号，不会更换号码；首次挂失补卡大多免除工本费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_01','V371','阮明',1,'您好，紧急求助，我的手机外出遗失，需要立刻远程锁定本人电话SIM卡。','nín hǎo， jǐn jí qiú zhù， wǒ de shǒu jī wài chū yí shī， xū yào lì kè yuǎn chéng suǒ dìng běn rén diàn huà SIM kǎ。','Chào chị, tôi cần hỗ trợ gấp, điện thoại của tôi bị mất khi ra ngoài, cần khóa SIM từ xa ngay lập tức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_02','V371','客服',2,'您好，为完成挂失锁卡操作，需要核实实名登记的全部身份信息，请您配合。','nín hǎo， wèi wán chéng guà shī suǒ kǎ cāo zuò， xū yào hé shí shí míng dēng jì de quán bù shēn fèn xìn xī， qǐng nín pèi hé。','Chào anh, để hoàn tất việc báo mất và khóa SIM, cần xác minh toàn bộ thông tin đăng ký chính chủ, mong anh phối hợp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_03','V371','阮明',3,'我清楚实名核验流程，您需要什么信息我全部如实报给您核对。','wǒ qīng chǔ shí míng hé yàn liú chéng， nín xū yào shén me xìn xī wǒ quán bù rú shí bào gěi nín hé duì。','Tôi hiểu rõ quy trình xác minh chính chủ, chị cần thông tin gì tôi sẽ khai báo đầy đủ để đối chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_04','V371','客服',4,'依次提供遗失手机号、实名登记姓名、本人护照完整编号吧。','yī cì tí gōng yí shī shǒu jī hào、 shí míng dēng jì xìng míng、 běn rén hù zhào wán zhěng biān hào ba。','Anh cung cấp lần lượt số điện thoại bị mất, tên đăng ký chính chủ, và số hộ chiếu đầy đủ của anh nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_05','V371','阮明',5,'手机号、姓名、护照号码我全部记录在备忘录，现在逐条念给您。','shǒu jī hào、 xìng míng、 hù zhào hào mǎ wǒ quán bù jì lù zài bèi wàng lù， xiàn zài zhú tiáo niàn gěi nín。','Số điện thoại, tên, số hộ chiếu tôi đã lưu hết trong ghi chú, giờ tôi đọc từng mục cho chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_06','V371','客服',6,'信息核验全部匹配，系统已经完成紧急挂失锁卡，他人无法使用你的号码呢。','xìn xī hé yàn quán bù pǐ pèi， xì tǒng yǐ jīng wán chéng jǐn jí guà shī suǒ kǎ， tā rén wú fǎ shǐ yòng nǐ de hào mǎ ne。','Thông tin khớp hết rồi, hệ thống đã hoàn tất khóa SIM khẩn cấp, người khác sẽ không dùng được số của anh nữa đâu.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_07','V371','阮明',7,'锁卡之后手机里绑定的支付软件、社交账号就不会被盗刷盗用了对吗？','suǒ kǎ zhī hòu shǒu jī lǐ bǎng dìng de zhī fù ruǎn jiàn、 shè jiāo zhàng hào jiù bú huì bèi dào shuā dào yòng le duì ma？','Sau khi khóa SIM thì các ứng dụng thanh toán, tài khoản mạng xã hội liên kết với điện thoại sẽ không bị đánh cắp hay dùng trộm nữa đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_08','V371','客服',8,'SIM卡锁定后无法接收验证码，能最大程度保护你的账户、资金安全。','SIM kǎ suǒ dìng hòu wú fǎ jiē shōu yàn zhèng mǎ， néng zuì dà chéng dù bǎo hù nǐ de zhàng hù、 zī jīn ān quán。','Sau khi khóa SIM sẽ không nhận được mã xác thực nữa, nên sẽ bảo vệ tối đa tài khoản và tài sản của anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_09','V371','阮明',9,'挂失锁卡只是临时冻结，后续补办新卡还能保留原来的手机号码吗？','guà shī suǒ kǎ zhǐ shì lín shí dòng jié， hòu xù bǔ bàn xīn kǎ hái néng bǎo liú yuán lái de shǒu jī hào mǎ ma？','Khóa SIM chỉ là tạm ngưng thôi, sau này làm lại SIM mới thì vẫn giữ được số điện thoại cũ chứ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_10','V371','客服',10,'完全可以，携带本人护照前往线下任意营业厅就能补办同号SIM卡。','wán quán kě yǐ， xié dài běn rén hù zhào qián wǎng xiàn xià rèn yì yíng yè tīng jiù néng bǔ bàn tóng hào SIM kǎ。','Hoàn toàn được, anh mang hộ chiếu đến bất kỳ điểm giao dịch nào là có thể làm lại SIM cùng số ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_11','V371','阮明',11,'补办卡片需要额外支付工本费，还是免费办理？','bǔ bàn kǎ piàn xū yào é wài zhī fù gōng běn fèi， hái shì miǎn fèi bàn lǐ？','Làm lại SIM có phải trả thêm phí không hay là miễn phí ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_12','V371','客服',12,'首次挂失补卡免收工本费，一年内多次补卡才会收取卡片费用。','shǒu cì guà shī bǔ kǎ miǎn shōu gōng běn fèi， yī nián nèi duō cì bǔ kǎ cái huì shōu qǔ kǎ piàn fèi yòng。','Lần đầu báo mất làm lại SIM thì được miễn phí, nếu làm lại nhiều lần trong một năm mới bị tính phí thẻ SIM.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_13','V371','阮明',13,'清楚全部规则了，太感谢您第一时间帮我冻结手机号。','qīng chǔ quán bù guī zé le， tài gǎn xiè nín dì yī shí jiān bāng wǒ dòng jié shǒu jī hào。','Tôi hiểu hết các quy định rồi, cảm ơn chị rất nhiều vì đã giúp khóa số điện thoại kịp thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_14','V371','客服',14,'后续补办有任何疑问，随时拨打官方客服热线咨询。','hòu xù bǔ bàn yǒu rèn hé yí wèn， suí shí bō dǎ guān fāng kè fú rè xiàn zī xún。','Sau này làm lại có thắc mắc gì cứ gọi tổng đài chăm sóc khách hàng chính thức để hỏi bất cứ lúc nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_15','V371','阮明',15,'多亏及时挂失，避免财产受损，十分感谢！','duō kuī jí shí guà shī， bì miǎn cái chǎn shòu sǔn， shí fēn gǎn xiè！','May mà khóa SIM kịp thời, tránh thiệt hại về tài sản, cảm ơn chị rất nhiều!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT372','S126','Gọi số cấp cứu khi có người bị thương',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V372','SIT372','P1','suon_se','chinh_thuc',NULL,'国内急救电话120免费拨打，接线员会同步指导简单急救措施，并快速调配就近医院车辆；伤者骨折、出血不可随意挪动，防止二次伤害。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_01','V372','阮明',1,'您好，这里发生人员摔倒受伤事故，情况紧急，麻烦尽快派遣救护车过来啊！','nín hǎo， zhè lǐ fā shēng rén yuán shuāi dǎo shòu shāng shì gù， qíng kuàng jǐn jí， má fán jǐn kuài pài qiǎn jiù hù chē guò lái a！','Alo, ở đây có người bị té ngã chấn thương, tình hình khẩn cấp, làm ơn điều xe cứu thương đến gấp giúp tôi với!','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_02','V372','接线员',2,'请先保持冷静，不要慌乱，分步骤告知我精准地址与伤者详细状况吧。','qǐng xiān bǎo chí lěng jìng， bú yào huāng luàn， fēn bù zhòu gào zhī wǒ jīng zhǔn dì zhǐ yǔ shāng zhě xiáng xì zhuàng kuàng ba。','Anh bình tĩnh, đừng hoảng, cho tôi biết địa chỉ chính xác và tình trạng người bị thương theo từng bước nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_03','V372','阮明',3,'事发地点在大学南门沿街小吃街，伤者下楼梯摔倒，腿部大面积出血，暂时无法自主站立呢。','shì fā dì diǎn zài dà xué nán mén yán jiē xiǎo chī jiē， shāng zhě xià lóu tī shuāi dǎo， tuǐ bù dà miàn jī chū xiě， zàn shí wú fǎ zì zhǔ zhàn lì ne。','Địa điểm là dãy phố ăn vặt ở cổng nam trường đại học, người bị thương bị ngã cầu thang, chân chảy máu nhiều, tạm thời không tự đứng dậy được.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_04','V372','接线员',4,'现场千万不要随意挪动、拖拽伤者，避免造成二次骨骼损伤，医护人员十分钟内抵达现场。','xiàn chǎng qiān wàn bú yào suí yì nuó dòng、 tuō zhuāi shāng zhě， bì miǎn zào chéng èr cì gǔ gé sǔn shāng， yī hù rén yuán shí fēn zhōng nèi dǐ dá xiàn chǎng。','Tuyệt đối không được tự ý di chuyển hay kéo lê người bị thương, tránh gây tổn thương xương thêm lần nữa, nhân viên y tế sẽ đến trong vòng mười phút nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_05','V372','阮明',5,'我会守在路口显眼位置等候救护车，指引医护车辆快速找到事发点位。','wǒ huì shǒu zài lù kǒu xiǎn yǎn wèi zhì děng hòu jiù hù chē， zhǐ yǐn yī hù chē liàng kuài sù zhǎo dào shì fā diǎn wèi。','Tôi sẽ đứng chờ ở vị trí dễ thấy ở đầu đường để chỉ đường cho xe cứu thương đến nhanh chóng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_06','V372','接线员',6,'全程保持通话畅通，如果伤者出血量变大、意识模糊，立刻同步告知我。','quán chéng bǎo chí tōng huà chàng tōng， rú guǒ shāng zhě chū xiě liàng biàn dà、 yì shí mó hú， lì kè tóng bù gào zhī wǒ。','Giữ đường dây liên lạc thông suốt, nếu người bị thương chảy máu nhiều hơn hoặc lơ mơ mất tỉnh táo thì báo cho tôi ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_07','V372','阮明',7,'我随身带纸巾按压伤口止血，暂时没有出现意识不清的情况。','wǒ suí shēn dài zhǐ jīn àn yā shāng kǒu zhǐ xuè， zàn shí méi yǒu chū xiàn yì shí bù qīng de qíng kuàng。','Tôi mang theo khăn giấy để ấn cầm máu vết thương, hiện tại chưa thấy có dấu hiệu mất tỉnh táo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_08','V372','接线员',8,'医护抵达前持续按压出血部位，减少血液流失。','yī hù dǐ dá qián chí xù àn yā chū xiě bù wèi， jiǎn shǎo xuè yè liú shī。','Trước khi nhân viên y tế đến, cứ tiếp tục ấn giữ vết thương để giảm mất máu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_09','V372','阮明',9,'我会严格按照您的指引简单处理伤口，不擅自移动伤者。','wǒ huì yán gé àn zhào nín de zhǐ yǐn jiǎn dān chǔ lǐ shāng kǒu， bù shàn zì yí dòng shāng zhě。','Tôi sẽ làm đúng theo hướng dẫn của chị, xử lý vết thương đơn giản thôi, không tự ý di chuyển người bị thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_10','V372','接线员',10,'救护车已经驶出医院，距离现场还有三分钟路程。','jiù hù chē yǐ jīng shǐ chū yī yuàn， jù lí xiàn chǎng hái yǒu sān fēn zhōng lù chéng。','Xe cứu thương đã xuất phát từ bệnh viện rồi, còn cách hiện trường khoảng ba phút nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_11','V372','阮明',11,'我现在站在校门口马路边挥手示意车辆。','wǒ xiàn zài zhàn zài xiào mén kǒu mǎ lù biān huī shǒu shì yì chē liàng。','Tôi đang đứng ở lề đường trước cổng trường vẫy tay ra hiệu cho xe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_12','V372','接线员',12,'辛苦你现场协助看护伤者，医护马上抵达。','xīn kǔ nǐ xiàn chǎng xié zhù kān hù shāng zhě， yī hù mǎ shàng dǐ dá。','Cảm ơn anh đã hỗ trợ trông chừng người bị thương tại chỗ, nhân viên y tế sắp đến rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_13','V372','阮明',13,'好的，我全程在这里等候，辛苦你们火速赶来！','hǎo de， wǒ quán chéng zài zhè lǐ děng hòu， xīn kǔ nǐ men huǒ sù gǎn lái！','Vâng, tôi sẽ đợi ở đây suốt, mong mọi người đến thật nhanh nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT373','S126','Báo cháy nhỏ trong khu bếp chung ký túc',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V373','SIT373','P1','twist','ban_chinh_thuc',NULL,'油锅起火严禁浇水，正确方式为隔绝氧气盖锅盖；国内宿舍厨房明令禁止无人看管明火，无人值守属于违规行为。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_01','V373','阮明',1,'宿管老师，紧急跟您汇报，宿舍楼公共厨房炒锅起火，我已经第一时间关闭燃气总阀。','sù guǎn lǎo shī， jǐn jí gēn nín huì bào， sù shè lóu gōng gòng chú fáng chǎo guō qǐ huǒ， wǒ yǐ jīng dì yī shí jiān guān bì rán qì zǒng fá。','Cô quản lý ơi, con báo gấp cho cô, chảo chiên trong bếp chung ký túc xá bị bốc cháy, con đã tắt van tổng gas ngay rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_02','V373','宿管老师',2,'你先远离起火厨具，我先确认一件事，有没有直接用水浇灭锅里的火源嘛？','nǐ xiān yuǎn lí qǐ huǒ chú jù， wǒ xiān què rèn yī jiàn shì， yǒu méi yǒu zhí jiē yòng shuǐ jiāo miè guō lǐ de huǒ yuán ma？','Con tránh xa dụng cụ đang cháy trước đi, cô hỏi con một chuyện, con có dùng nước dội trực tiếp vào lửa trong chảo không?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_03','V373','阮明',3,'我之前上过宿舍安全培训，牢记油锅起火不能浇水，立刻拿锅盖完整盖住锅体隔绝氧气灭火。','wǒ zhī qián shàng guò sù shè ān quán péi xùn， láo jì yóu guō qǐ huǒ bù néng jiāo shuǐ， lì kè ná guō gài wán zhěng gài zhù guō tǐ gé jué yǎng qì miè huǒ。','Con từng học tập huấn an toàn ký túc xá, nhớ kỹ lửa dầu cháy thì không được dội nước, con lập tức lấy nắp đậy kín chảo để chặn oxy dập lửa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_04','V373','宿管老师',4,'还好你掌握正确灭火方法，没有盲目泼水引发火势扩散，我现在携带灭火器赶往厨房。','hái hǎo nǐ zhǎng wò zhèng què miè huǒ fāng fǎ， méi yǒu máng mù pō shuǐ yǐn fā huǒ shì kuò sàn， wǒ xiàn zài xié dài miè huǒ qì gǎn wǎng chú fáng。','May mà con biết cách dập lửa đúng, không dội nước bừa làm lửa lan rộng, cô mang bình chữa cháy đến bếp ngay đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_05','V373','阮明',5,'明火已经完全熄灭，只是墙面瓷砖被烟火轻微熏黑，没有蔓延到周边厨具、橱柜对吧？','míng huǒ yǐ jīng wán quán xī miè， zhǐ shì qiáng miàn cí zhuān bèi yān huǒ qīng wēi xūn hēi， méi yǒu màn yán dào zhōu biān chú jù、 chú guì duì ba？','Lửa đã tắt hẳn rồi, chỉ có gạch tường bị ám khói đen nhẹ thôi, không lan sang các dụng cụ bếp hay tủ bếp xung quanh đúng không cô?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_06','V373','宿管老师',6,'只要没有引燃橱柜、纸巾等易燃物品，就不算重大火情，仅轻微安全隐患。','zhǐ yào méi yǒu yǐn rán chú guì、 zhǐ jīn děng yì rán wù pǐn， jiù bù suàn zhòng dà huǒ qíng， jǐn qīng wēi ān quán yǐn huàn。','Chỉ cần không bén lửa vào tủ bếp, khăn giấy hay các vật dễ cháy khác thì không tính là sự cố nghiêm trọng, chỉ là nguy cơ an toàn nhẹ thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_07','V373','阮明',7,'这次起火是我熬汤忘记看管，离开几分钟汤水烧干才引燃锅底，是我的疏忽。','zhè cì qǐ huǒ shì wǒ áo tāng wàng jì kān guǎn， lí kāi jǐ fēn zhōng tāng shuǐ shāo gàn cái yǐn rán guō dǐ， shì wǒ de shū hū。','Lần này cháy là do con nấu canh mà quên trông, đi vắng vài phút nước cạn cháy đáy nồi rồi bắt lửa, là lỗi bất cẩn của con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_08','V373','宿管老师',8,'宿舍公共厨房明确规定明火烹饪必须有人全程看管，无人值守极易引发火灾。','sù shè gōng gòng chú fáng míng què guī dìng míng huǒ pēng rèn bì xū yǒu rén quán chéng kān guǎn， wú rén zhí shǒu jí yì yǐn fā huǒ zāi。','Bếp chung ký túc xá đã quy định rõ nấu ăn có lửa phải có người trông suốt, không ai trông coi rất dễ gây cháy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_09','V373','阮明',9,'我深刻记住这条安全规定，之后做饭绝不擅自离开灶台半步。','wǒ shēn kè jì zhù zhè tiáo ān quán guī dìng， zhī hòu zuò fàn jué bù shàn zì lí kāi zào tái bàn bù。','Con ghi nhớ kỹ quy định an toàn này rồi, sau này nấu ăn con tuyệt đối không rời bếp dù chỉ một bước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_10','V373','宿管老师',10,'我到现场检查残留隐患，确认无复燃风险之后再通知大家使用厨房。','wǒ dào xiàn chǎng jiǎn chá cán liú yǐn huàn， què rèn wú fù rán fēng xiǎn zhī hòu zài tōng zhī dà jiā shǐ yòng chú fáng。','Cô đến hiện trường kiểm tra nguy cơ còn sót lại, xác nhận không có khả năng bén lửa lại rồi mới thông báo cho mọi người dùng bếp tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_11','V373','阮明',11,'需要我留在厨房配合您清点厨具、说明起火全过程吗？','xū yào wǒ liú zài chú fáng pèi hé nín qīng diǎn chú jù、 shuō míng qǐ huǒ quán guò chéng ma？','Con có cần ở lại bếp phối hợp với cô kiểm đếm dụng cụ, trình bày lại toàn bộ quá trình cháy không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_12','V373','宿管老师',12,'你可以在值班室等候，检查完毕我会跟你说明后续注意事项。','nǐ kě yǐ zài zhí bān shì děng hòu， jiǎn chá wán bì wǒ huì gēn nǐ shuō míng hòu xù zhù yì shì xiàng。','Con cứ chờ ở phòng trực, kiểm tra xong cô sẽ nói cho con biết những điều cần lưu ý tiếp theo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_13','V373','阮明',13,'给老师带来安全巡查的额外工作，实在抱歉。','gěi lǎo shī dài lái ān quán xún chá de é wài gōng zuò， shí zài bào qiàn。','Con làm phiền cô phải đi kiểm tra an toàn thêm việc, con thật sự xin lỗi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_14','V373','宿管老师',14,'吸取教训就好，安全第一不用过度自责。','xī qǔ jiào xùn jiù hǎo， ān quán dì yī bù yòng guò dù zì zé。','Rút kinh nghiệm là được rồi, an toàn là trên hết, không cần tự trách bản thân quá mức đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_15','V373','阮明',15,'我之后做饭一定时刻留意火源，不会再出现这种情况。','wǒ zhī hòu zuò fàn yí dìng shí kè liú yì huǒ yuán， bú huì zài chū xiàn zhè zhǒng qíng kuàng。','Sau này con nấu ăn nhất định sẽ luôn để ý lửa, sẽ không để xảy ra chuyện như thế này nữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT374','S126','Trình báo tai nạn giao thông nhẹ',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V374','SIT374','P1','suon_se','chinh_thuc',NULL,'无人员伤亡的轻微交通事故，可通过交管平台线上处理，无需等待交警到场；外籍当事人护照可作为辅助身份凭证上传备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_01','V374','阮明',1,'您好，城市主干道十字路口发生两车轻微剐蹭，事故双方均无人员受伤。','nín hǎo， chéng shì zhǔ gàn dào shí zì lù kǒu fā shēng liǎng chē qīng wēi guǎ cèng， shì gù shuāng fāng jūn wú rén yuán shòu shāng。','Chào anh, tại ngã tư đường chính trong thành phố có hai xe va quệt nhẹ, hai bên đều không có ai bị thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_02','V374','交警接线员',2,'先做好两件事，第一双方车辆挪至路边非机动车道，第二多角度拍摄完整现场照片留存证据吧。','xiān zuò hǎo liǎng jiàn shì， dì yī shuāng fāng chē liàng nuó zhì lù biān fēi jī dòng chē dào， dì èr duō jiǎo dù pāi shè wán zhěng xiàn chǎng zhào piān liú cún zhèng jù ba。','Trước tiên làm hai việc này nhé, một là đưa hai xe vào làn xe thô sơ ven đường, hai là chụp ảnh hiện trường đầy đủ nhiều góc độ để làm bằng chứng.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_03','V374','阮明',3,'我们已经共同把车辆停靠在不阻碍主路通行的非机动车道，前后、侧面、碰撞位置都拍好了多角度现场照片呢。','wǒ men yǐ jīng gòng tóng bǎ chē liàng tíng kào zài bù zǔ ài zhǔ lù tōng xíng de fēi jī dòng chē dào， qián hòu、 cè miàn、 pèng zhuàng wèi zhì dōu pāi hǎo le duō jiǎo dù xiàn chǎng zhào piān ne。','Chúng tôi đã cùng nhau đưa xe vào làn xe thô sơ không cản trở giao thông chính, đã chụp đủ ảnh hiện trường từ phía trước, bên hông, chỗ va chạm rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_04','V374','接线员',4,'无人员伤亡、仅轻微车身剐蹭的小型事故，可通过交管线上平台快速定责，不需要交警线下现场出警。','wú rén yuán shāng wáng、 jǐn qīng wēi chē shēn guǎ cèng de xiǎo xíng shì gù， kě tōng guò jiāo guǎn xiàn shàng píng tái kuài sù dìng zé， bù xū yào jiāo jǐng xiàn xià xiàn chǎng chū jǐng。','Sự cố nhỏ không có thương vong, chỉ va quệt thân xe nhẹ thì có thể xử lý phân định trách nhiệm nhanh qua nền tảng trực tuyến của cảnh sát giao thông, không cần cảnh sát đến hiện trường trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_05','V374','阮明',5,'线上平台处理事故，需要上传哪些证件照片，外籍留学生的护照可以作为有效证件使用吗？','xiàn shàng píng tái chǔ lǐ shì gù， xū yào shàng chuán nǎ xiē zhèng jiàn zhào piān， wài jí liú xué shēng de hù zhào kě yǐ zuò wéi yǒu xiào zhèng jiàn shǐ yòng ma？','Xử lý trên nền tảng trực tuyến cần tải lên những giấy tờ gì, hộ chiếu của du học sinh nước ngoài có được dùng làm giấy tờ hợp lệ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_06','V374','接线员',6,'需要上传机动车行驶证、驾驶员驾驶证，外加当事人护照照片，全部拍照上传系统即可。','xū yào shàng chuán jī dòng chē xíng shǐ zhèng、 jià shǐ yuán jià shǐ zhèng， wài jiā dāng shì rén hù zhào zhào piān， quán bù pāi zhào shàng chuán xì tǒng jí kě。','Cần tải lên giấy đăng ký xe, bằng lái xe của tài xế, cùng với ảnh hộ chiếu của người liên quan, chụp ảnh và tải lên hệ thống là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_07','V374','阮明',7,'定责完成之后，理赔流程也是直接在线上操作，不用前往交警大队线下办理？','dìng zé wán chéng zhī hòu， lǐ péi liú chéng yě shì zhí jiē zài xiàn shàng cāo zuò， bù yòng qián wǎng jiāo jǐng dà duì xiàn xià bàn lǐ？','Sau khi phân định trách nhiệm xong, quy trình bồi thường cũng thực hiện trực tuyến luôn, không cần đến đội cảnh sát giao thông xử lý trực tiếp đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_08','V374','接线员',8,'全责方保险公司线上对接理赔，全程线上办结，省去线下跑腿时间。','quán zé fāng bǎo xiǎn gōng sī xiàn shàng duì jiē lǐ péi， quán chéng xiàn shàng bàn jié， shěng qù xiàn xià pǎo tuǐ shí jiān。','Công ty bảo hiểm của bên chịu toàn bộ trách nhiệm sẽ kết nối bồi thường trực tuyến, xử lý xong toàn bộ online, khỏi mất công đi lại trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_09','V374','阮明',9,'我现在和对方车主整理全部证件照片，马上上传交管小程序。','wǒ xiàn zài hé duì fāng chē zhǔ zhěng lǐ quán bù zhèng jiàn zhào piān， mǎ shàng shàng chuán jiāo guǎn xiǎo chéng xù。','Tôi đang cùng chủ xe bên kia tổng hợp toàn bộ ảnh giấy tờ, sẽ tải lên ứng dụng của giao thông ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_10','V374','接线员',10,'上传完成等待系统自动分配交警线上审核，半小时内出具责任认定书。','shàng chuán wán chéng děng dài xì tǒng zì dòng fēn pèi jiāo jǐng xiàn shàng shěn hé， bàn xiǎo shí nèi chū jù zé rèn rèn dìng shū。','Tải lên xong thì chờ hệ thống tự động phân cho cảnh sát duyệt trực tuyến, trong vòng nửa tiếng sẽ có văn bản xác định trách nhiệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_11','V374','阮明',11,'清楚完整线上处理流程，不用耽误双方过多时间。','qīng chǔ wán zhěng xiàn shàng chǔ lǐ liú chéng， bù yòng dān wù shuāng fāng guò duō shí jiān。','Tôi đã hiểu rõ toàn bộ quy trình xử lý trực tuyến rồi, không làm mất thời gian của hai bên nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_12','V374','接线员',12,'后续理赔有纠纷，可再次拨打交警热线咨询。','hòu xù lǐ péi yǒu jiū fēn， kě zài cì bō dǎ jiāo jǐng rè xiàn zī xún。','Sau này bồi thường có tranh chấp gì thì có thể gọi lại đường dây nóng cảnh sát giao thông để hỏi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_13','V374','阮明',13,'感谢您清晰告知线上快速处理流程！','gǎn xiè nín qīng xī gào zhī xiàn shàng kuài sù chǔ lǐ liú chéng！','Cảm ơn anh đã hướng dẫn rõ ràng quy trình xử lý nhanh trực tuyến!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT375','S126','Trình báo bị lừa chuyển tiền qua mạng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V375','SIT375','P1','twist','chinh_thuc',NULL,'遭遇网络诈骗第一时间联系反诈中心冻结对方账户，再线下报案，是国内标准维权流程；完整聊天、转账截图是关键办案证据，不可删除。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_01','V375','阮明',1,'您好，我遭到网络虚假客服诱导转账，资金已经成功转入对方陌生账户，前来求助拦截。','nín hǎo， wǒ zāo dào wǎng luò xū jiǎ kè fú yòu dǎo zhuǎn zhàng， zī jīn yǐ jīng chéng gōng zhuǎn rù duì fāng mò shēng zhàng hù， qián lái qiú zhù lán jié。','Chào chị, tôi bị dụ chuyển tiền bởi một dịch vụ chăm sóc khách hàng giả mạo trên mạng, tiền đã chuyển thành công vào tài khoản lạ của đối phương, tôi đến nhờ hỗ trợ chặn lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_02','V375','反诈客服',2,'请立刻提供三项关键信息，对方收款账号、精确转账时间、完整转账金额哈。','qǐng lì kè tí gōng sān xiàng guān jiàn xìn xī， duì fāng shōu kuǎn zhàng hào、 jīng què zhuǎn zhàng shí jiān、 wán zhěng zhuǎn zhàng jīn é hā。','Anh cung cấp ngay ba thông tin quan trọng này nhé, số tài khoản nhận tiền của đối phương, thời gian chuyển tiền chính xác, và số tiền chuyển đầy đủ.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_03','V375','阮明',3,'我刚刚完成转账立刻察觉对方是骗子，想要操作转账撤回功能却系统提示失败嘛。','wǒ gāng gāng wán chéng zhuǎn zhàng lì kè chá jué duì fāng shì piàn zi， xiǎng yào cāo zuò zhuǎn zhàng chè huí gōng néng què xì tǒng tí shì shī bài ma。','Tôi vừa chuyển tiền xong thì phát hiện ngay đối phương là lừa đảo, tôi định thu hồi giao dịch nhưng hệ thống báo lỗi thất bại.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_04','V375','反诈客服',4,'资金一旦成功转入私人第三方账户，无法由用户自主撤回，我现在紧急提交账户冻结指令。','zī jīn yí dàn chéng gōng zhuǎn rù sī rén dì sān fāng zhàng hù， wú fǎ yóu yòng hù zì zhǔ chè huí， wǒ xiàn zài jǐn jí tí jiāo zhàng hù dòng jié zhǐ lìng。','Một khi tiền đã chuyển thành công vào tài khoản bên thứ ba của tư nhân thì người dùng không thể tự thu hồi được, giờ tôi sẽ khẩn cấp gửi lệnh phong tỏa tài khoản đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_05','V375','阮明',5,'账户冻结之后，我转出的资金还有机会拦截追回，避免全部损失吗？','zhàng hù dòng jié zhī hòu， wǒ zhuǎn chū de zī jīn hái yǒu jī huì lán jié zhuī huí， bì miǎn quán bù sǔn shī ma？','Sau khi phong tỏa tài khoản, số tiền tôi đã chuyển đi liệu có còn cơ hội chặn lại thu hồi để tránh mất trắng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_06','V375','反诈客服',6,'冻结对方账户可以锁住未被转出的资金，后续需要你到辖区派出所完成报案笔录留存证据。','dòng jié duì fāng zhàng hù kě yǐ suǒ zhù wèi bèi zhuǎn chū de zī jīn， hòu xù xū yào nǐ dào xiá qū pài chū suǒ wán chéng bào àn bǐ lù liú cún zhèng jù。','Phong tỏa tài khoản của đối phương có thể khóa lại phần tiền chưa bị chuyển đi tiếp, sau đó anh cần đến đồn công an nơi cư trú để làm biên bản trình báo lưu bằng chứng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_07','V375','阮明',7,'请问报案的派出所地址在哪里，办理笔录需要携带什么证件？','qǐng wèn bào àn de pài chū suǒ dì zhǐ zài nǎ lǐ， bàn lǐ bǐ lù xū yào xié dài shén me zhèng jiàn？','Cho tôi hỏi địa chỉ đồn công an để trình báo ở đâu, làm biên bản cần mang theo giấy tờ gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_08','V375','反诈客服',8,'携带本人护照前往就近辖区派出所，工作人员会同步对接反诈中心留存线索。','xié dài běn rén hù zhào qián wǎng jiù jìn xiá qū pài chū suǒ， gōng zuò rén yuán huì tóng bù duì jiē fǎn zhà zhōng xīn liú cún xiàn suǒ。','Mang theo hộ chiếu của anh đến đồn công an gần nhất, nhân viên sẽ đồng thời kết nối với trung tâm chống lừa đảo để lưu manh mối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_09','V375','阮明',9,'笔录做完提交线索，警方会持续跟进追查诈骗账户吗？','bǐ lù zuò wán tí jiāo xiàn suǒ， jǐng fāng huì chí xù gēn jìn zhuī chá zhà piàn zhàng hù ma？','Sau khi làm biên bản và nộp manh mối, cảnh sát có tiếp tục theo dõi truy tìm tài khoản lừa đảo không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_10','V375','反诈客服',10,'警方会登记全部涉案线索，持续追踪资金流向，尽力挽回群众损失。','jǐng fāng huì dēng jì quán bù shè àn xiàn suǒ， chí xù zhuī zōng zī jīn liú xiàng， jìn lì wǎn huí qún zhòng sǔn shī。','Cảnh sát sẽ ghi nhận toàn bộ manh mối liên quan đến vụ việc, tiếp tục truy theo dòng tiền, cố gắng hết sức thu hồi thiệt hại cho người dân.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_11','V375','阮明',11,'我现在记下派出所地址，立刻动身前往线下登记报案。','wǒ xiàn zài jì xià pài chū suǒ dì zhǐ， lì kè dòng shēn qián wǎng xiàn xià dēng jì bào àn。','Tôi ghi lại địa chỉ đồn công an rồi, sẽ đi trình báo trực tiếp ngay bây giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_12','V375','反诈客服',12,'路上保管好转账截图、聊天记录等全部证据，不要删除。','lù shàng bǎo guǎn hǎo zhuǎn zhàng jié tú、 liáo tiān jì lù děng quán bù zhèng jù， bú yào shān chú。','Trên đường đi nhớ giữ lại đầy đủ ảnh chụp giao dịch, lịch sử trò chuyện làm bằng chứng, đừng xóa đi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_13','V375','阮明',13,'所有聊天、转账记录我都完整保存，不会丢失。','suǒ yǒu liáo tiān、 zhuǎn zhàng jì lù wǒ dōu wán zhěng bǎo cún， bú huì diū shī。','Toàn bộ tin nhắn, lịch sử chuyển tiền tôi đều đã lưu đầy đủ, sẽ không bị mất đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_14','V375','反诈客服',14,'后续案件进展派出所会同步通知你。','hòu xù àn jiàn jìn zhǎn pài chū suǒ huì tóng bù tōng zhī nǐ。','Tiến triển vụ việc sau này đồn công an sẽ thông báo cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_15','V375','阮明',15,'感谢紧急冻结对方账户，降低我的财产损失！','gǎn xiè jǐn jí dòng jié duì fāng zhàng hù， jiàng dī wǒ de cái chǎn sǔn shī！','Cảm ơn chị đã khẩn cấp phong tỏa tài khoản của đối phương, giúp giảm thiểu thiệt hại tài sản của tôi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT376','S126','Báo khóa cửa phòng bị hỏng, không vào được phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V376','SIT376','P1','suon_se','ban_chinh_thuc',NULL,'出租公寓门锁自然老化损坏，物业免费上门维修；租客人为撬动、暴力损坏门锁，则需自行支付配件与工时费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_01','V376','阮明',1,'物业您好，我租住公寓的入户门锁出现故障，钥匙插入锁孔完全转动不开，无法进门。','wù yè nín hǎo， wǒ zū zhù gōng yù de rù hù mén suǒ chū xiàn gù zhàng， yào shi chā rù suǒ kǒng wán quán zhuǎn dòng bù kāi， wú fǎ jìn mén。','Chào bên quản lý, ổ khóa cửa ra vào căn hộ tôi thuê bị hỏng, tra chìa vào không xoay được, không vào nhà được luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_02','V376','维修专员',2,'先跟我确认，你尝试转动钥匙的时候，有没有暴力掰扯、大力敲击门锁？','xiān gēn wǒ què rèn， nǐ cháng shì zhuǎn dòng yào shi de shí hòu， yǒu méi yǒu bào lì bāi chě、 dà lì qiāo jī mén suǒ？','Anh xác nhận giúp tôi, lúc anh xoay chìa khóa có dùng lực mạnh bẻ hay đập mạnh vào ổ khóa không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_03','V376','阮明',3,'我只是平稳插入钥匙左右轻转，没有用力掰动锁芯，不存在人为破坏的情况。','wǒ zhǐ shì píng wěn chā rù yào shi zuǒ yòu qīng zhuǎn， méi yǒu yòng lì bāi dòng suǒ xīn， bù cún zài rén wéi pò huài de qíng kuàng。','Tôi chỉ tra chìa vào nhẹ nhàng xoay qua xoay lại thôi, không hề dùng lực bẻ lõi khóa, không có chuyện phá hoại do con người đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_04','V376','维修专员',4,'你先到楼下单元门禁处等候，我携带全套维修工具，十分钟之内抵达楼栋哦。','nǐ xiān dào lóu xià dān yuán mén jìn chù děng hòu， wǒ xié dài quán tào wéi xiū gōng jù， shí fēn zhōng zhī nèi dǐ dá lóu dòng ó。','Anh xuống chờ ở cửa an ninh của tòa nhà trước nhé, tôi mang đầy đủ dụng cụ sửa chữa, sẽ đến tòa nhà trong mười phút nữa.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_05','V376','阮明',5,'锁芯内部完全卡死，我尝试家里三把备用钥匙，全部都没办法转动开门呢。','suǒ xīn nèi bù wán quán kǎ sǐ， wǒ cháng shì jiā lǐ sān bǎ bèi yòng yào shi， quán bù dōu méi bàn fǎ zhuǎn dòng kāi mén ne。','Lõi khóa bị kẹt cứng hoàn toàn bên trong, tôi thử cả ba chìa dự phòng ở nhà mà không cái nào xoay mở được cả.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_06','V376','维修专员',6,'大概率是锁芯内部金属零件老化断裂，这种自然老化故障需要直接更换整套门锁。','dà gài lǜ shì suǒ xīn nèi bù jīn shǔ líng jiàn lǎo huà duàn liè， zhè zhǒng zì rán lǎo huà gù zhàng xū yào zhí jiē gēng huàn zhěng tào mén suǒ。','Nhiều khả năng là linh kiện kim loại bên trong lõi khóa bị lão hóa gãy, kiểu hỏng do lão hóa tự nhiên này cần thay hẳn cả bộ khóa mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_07','V376','阮明',7,'更换整套门锁产生的配件费、人工费，是由我租房住户自行承担吗？','gēng huàn zhěng tào mén suǒ chǎn shēng de pèi jiàn fèi、 rén gōng fèi， shì yóu wǒ zū fáng zhù hù zì xíng chéng dān ma？','Chi phí phụ kiện, tiền công thay cả bộ khóa mới, có phải do tôi là người thuê nhà tự chi trả không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_08','V376','维修专员',8,'区分损坏原因，房屋设施自然老化损坏由物业全额免费上门维修；租客人为损坏才需要自费支付配件工时费。','qū fēn sǔn huài yuán yīn， fáng wū shè shī zì rán lǎo huà sǔn huài yóu wù yè quán é miǎn fèi shàng mén wéi xiū； zū kè rén wéi sǔn huài cái xū yào zì fèi zhī fù pèi jiàn gōng shí fèi。','Phân biệt theo nguyên nhân hư hỏng, thiết bị nhà bị hỏng do lão hóa tự nhiên thì bên quản lý sửa miễn phí toàn bộ; còn người thuê làm hỏng do tác động thì mới phải tự trả phí phụ kiện và công thợ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_09','V376','阮明',9,'全程轻柔试钥匙，没有磕碰、撬动门锁，属于自然老化故障对吧？','quán chéng qīng róu shì yào shi， méi yǒu kē pèng、 qiào dòng mén suǒ， shǔ yú zì rán lǎo huà gù zhàng duì ba？','Suốt quá trình tôi chỉ thử chìa nhẹ nhàng, không va đập hay cạy khóa gì cả, thuộc trường hợp lão hóa tự nhiên đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_10','V376','维修专员',10,'抵达现场查看锁体磨损情况后判定，自然老化无需你支付任何费用。','dǐ dá xiàn chǎng chá kàn suǒ tǐ mó sǔn qíng kuàng hòu pàn dìng， zì rán lǎo huà wú xū nǐ zhī fù rèn hé fèi yòng。','Đến hiện trường kiểm tra mức độ mòn của lõi khóa rồi mới xác định được, nếu là lão hóa tự nhiên thì anh không cần trả bất kỳ chi phí nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_11','V376','阮明',11,'我在楼下门禁处安静等候，麻烦您尽快过来检修门锁。','wǒ zài lóu xià mén jìn chù ān jìng děng hòu， má fán nín jǐn kuài guò lái jiǎn xiū mén suǒ。','Tôi đang chờ yên tại cửa an ninh dưới tòa nhà, phiền anh đến kiểm tra sửa khóa sớm giúp tôi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_12','V376','维修专员',12,'马上出发，到楼下我给你打电话。','mǎ shàng chū fā， dào lóu xià wǒ gěi nǐ dǎ diàn huà。','Tôi xuất phát ngay đây, đến dưới tòa tôi sẽ gọi điện cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_13','V376','阮明',13,'辛苦专员专程上门处理故障，耽误您工作时间实在不好意思。','xīn kǔ zhuān yuán zhuān chéng shàng mén chǔ lǐ gù zhàng， dān wù nín gōng zuò shí jiān shí zài bù hǎo yì sī。','Cảm ơn anh đã vất vả đến tận nơi xử lý sự cố, làm mất thời gian làm việc của anh thật ngại quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_14','V376','维修专员',14,'房屋维修是物业本职工作，不用客气。','fáng wū wéi xiū shì wù yè běn zhí gōng zuò， bù yòng kè qì。','Sửa chữa nhà cửa là công việc chính của bên quản lý mà, anh không cần khách sáo đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_15','V376','阮明',15,'十分感谢，我在这里等您！','shí fēn gǎn xiè， wǒ zài zhè lǐ děng nín！','Cảm ơn anh nhiều lắm, tôi sẽ chờ anh ở đây!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT377','S126','Xin cấp lại giấy tờ tạm thời khi mất hộ chiếu',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V377','SIT377','P1','twist','chinh_thuc',NULL,'外籍留学生护照丢失后，出入境大厅可开具临时通行证明，用于回国或补办护照；现场自助拍照符合涉外证件标准，无需提前线下照相馆拍摄。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_01','V377','阮明',1,'您好，本人越南护照不慎遗失，前来大厅申请临时出入境通行证明。','nín hǎo， běn rén yuè nán hù zhào bù shèn yí shī， qián lái dà tīng shēn qǐng lín shí chū rù jìng tōng xíng zhèng míng。','Chào chị, tôi bị mất hộ chiếu Việt Nam, đến quầy để xin cấp giấy chứng nhận xuất nhập cảnh tạm thời ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_02','V377','工作人员',2,'办理临时通行证明需要两份核心材料，派出所开具的遗失报案回执、标准一寸白底证件照片吧。','bàn lǐ lín shí tōng xíng zhèng míng xū yào liǎng fèn hé xīn cái liào， pài chū suǒ kāi jù de yí shī bào àn huí zhí、 biāo zhǔn yī cùn bái dǐ zhèng jiàn zhào piān ba。','Làm giấy chứng nhận tạm thời cần hai giấy tờ chính: biên nhận trình báo mất giấy tờ của công an và một tấm ảnh thẻ 1 inch nền trắng đúng chuẩn.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_03','V377','阮明',3,'派出所出具的遗失回执我已经随身携带，但是出门匆忙，没有提前准备一寸白底证件照嘛。','pài chū suǒ chū jù de yí shī huí zhí wǒ yǐ jīng suí shēn xié dài， dàn shì chū mén cōng máng， méi yǒu tí qián zhǔn bèi yī cùn bái dǐ zhèng jiàn zhào ma。','Biên nhận trình báo mất của công an tôi mang theo người rồi, nhưng đi vội quá nên chưa chuẩn bị sẵn ảnh thẻ 1 inch nền trắng.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_04','V377','工作人员',4,'大厅大厅入口设有自助拍照机，专门办理涉外证件拍摄，一套照片收费二十元。','dà tīng dà tīng rù kǒu shè yǒu zì zhù pāi zhào jī， zhuān mén bàn lǐ shè wài zhèng jiàn pāi shè， yī tào zhào piān shōu fèi èr shí yuán。','Ở cửa ra vào sảnh có máy chụp ảnh tự động, chuyên chụp ảnh giấy tờ cho người nước ngoài, một bộ ảnh giá hai mươi tệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_05','V377','阮明',5,'现场拍摄完证件照片，当天递交全部材料就能直接拿到临时通行证件吗？','xiàn chǎng pāi shè wán zhèng jiàn zhào piān， dàng tiān dì jiāo quán bù cái liào jiù néng zhí jiē ná dào lín shí tōng xíng zhèng jiàn ma？','Nếu tôi chụp ảnh tại chỗ rồi nộp đủ hồ sơ luôn trong ngày hôm nay thì có thể lấy được giấy chứng nhận tạm thời ngay không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_06','V377','工作人员',6,'只要回执、照片、护照信息全部材料齐全，窗口当场办结出证，无需等候。','zhǐ yào huí zhí、 zhào piān、 hù zhào xìn xī quán bù cái liào qí quán， chuāng kǒu dāng chǎng bàn jié chū zhèng， wú xū děng hòu。','Chỉ cần đủ biên nhận, ảnh và thông tin hộ chiếu là quầy sẽ giải quyết xong tại chỗ, không phải chờ đợi gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_07','V377','阮明',7,'这份临时通行证明有效期多长时间，能用来回国补办正式护照吗？','zhè fèn lín shí tōng xíng zhèng míng yǒu xiào qī duō zhǎng shí jiān， néng yòng lái huí guó bǔ bàn zhèng shì hù zhào ma？','Giấy chứng nhận tạm thời này có thời hạn bao lâu, dùng để về nước làm lại hộ chiếu chính thức được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_08','V377','工作人员',8,'临时证明有效期三十天，可用于搭乘国际航班出境，也能前往驻华大使馆补办护照。','lín shí zhèng míng yǒu xiào qī sān shí tiān， kě yòng yú dā chéng guó jì háng bān chū jìng， yě néng qián wǎng zhù huá dà shǐ guǎn bǔ bàn hù zhào。','Giấy tạm thời có hiệu lực ba mươi ngày, dùng để lên chuyến bay quốc tế xuất cảnh được, cũng có thể đến đại sứ quán để làm lại hộ chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_09','V377','阮明',9,'那我先去自助拍照机拍摄证件照，拍完立刻返回窗口提交全部材料。','nà wǒ xiān qù zì zhù pāi zhào jī pāi shè zhèng jiàn zhào， pāi wán lì kè fǎn huí chuāng kǒu tí jiāo quán bù cái liào。','Vậy tôi ra máy tự động chụp ảnh trước, chụp xong sẽ quay lại quầy nộp đủ hồ sơ ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_10','V377','工作人员',10,'拍照后记得核对人像清晰度，不合格需要重新拍摄。','pāi zhào hòu jì de hé duì rén xiàng qīng xī dù， bù hé gé xū yào chóng xīn pāi shè。','Chụp xong nhớ kiểm tra ảnh có rõ nét không nhé, không đạt là phải chụp lại đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_11','V377','阮明',11,'我会仔细检查照片标准，不耽误窗口办理流程。','wǒ huì zǐ xì jiǎn chá zhào piàn biāo zhǔn， bù dān wù chuāng kǒu bàn lǐ liú chéng。','Tôi sẽ kiểm tra kỹ ảnh cho đúng chuẩn, không làm chậm quy trình của quầy đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_12','V377','工作人员',12,'拍完直接到三号窗口递交材料即可。','pāi wán zhí jiē dào sān hào chuāng kǒu dì jiāo cái liào jí kě。','Chụp xong thì đến thẳng quầy số ba để nộp hồ sơ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_13','V377','阮明',13,'感谢工作人员清晰告知全部办理步骤！','gǎn xiè gōng zuò rén yuán qīng xī gào zhī quán bù bàn lǐ bù zhòu！','Cảm ơn anh/chị đã hướng dẫn rõ ràng toàn bộ các bước!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT378','S126','Liên hệ đại sứ quán khi gặp sự cố nghiêm trọng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V378','SIT378','P1','suon_se','chinh_thuc',NULL,'外籍公民在中国发生重大人身意外，可联系本国驻华大使馆获取领事协助，包含对接家属、证件补办、事故手续协调等服务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_01','V378','阮明',1,'您好，我是在华就读的越南留学生，途中遭遇严重交通事故，紧急寻求使馆协助。','nín hǎo， wǒ shì zài huá jiù dú de yuè nán liú xué shēng， tú zhōng zāo yù yán zhòng jiāo tōng shì gù， jǐn jí xún qiú shǐ guǎn xié zhù。','Chào các anh chị, tôi là du học sinh Việt Nam đang học tại Trung Quốc, trên đường đi gặp phải tai nạn giao thông nghiêm trọng, khẩn cấp cần sự hỗ trợ của đại sứ quán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_02','V378','接线员',2,'请你先保持冷静，逐条告知我你的完整姓名、就读院校、事故精确详细地点呢。','qǐng nǐ xiān bǎo chí lěng jìng， zhú tiáo gào zhī wǒ nǐ de wán zhěng xìng míng、 jiù dú yuàn xiào、 shì gù jīng què xiáng xì dì diǎn ne。','Bạn hãy bình tĩnh trước đã, cho tôi biết lần lượt họ tên đầy đủ, trường đang theo học và địa điểm chính xác xảy ra tai nạn nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_03','V378','阮明',3,'我叫阮明，本市高校汉语言专业留学生，事故发生在市中心主干道十字路口，交警与救护车已经抵达现场处置。','wǒ jiào ruǎn míng， běn shì gāo xiào hàn yǔ yán zhuān yè liú xué shēng， shì gù fā shēng zài shì zhōng xīn zhǔ gàn dào shí zì lù kǒu， jiāo jǐng yǔ jiù hù chē yǐ jīng dǐ dá xiàn chǎng chǔ zhì。','Tôi tên Nguyễn Minh, là du học sinh ngành tiếng Trung của một trường đại học trong thành phố này, tai nạn xảy ra ở ngã tư trên trục đường chính trung tâm thành phố, cảnh sát giao thông và xe cứu thương đã có mặt tại hiện trường để xử lý.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_04','V378','接线员',4,'我们会第一时间同步联系当地辖区交警大队跟进本次事故完整处置流程，后续协助处理各类手续。','wǒ men huì dì yī shí jiān tóng bù lián xì dāng dì xiá qū jiāo jǐng dà duì gēn jìn běn cì shì gù wán zhěng chǔ zhì liú chéng， hòu xù xié zhù chǔ lǐ gè lèi shǒu xù。','Chúng tôi sẽ liên hệ ngay với đội cảnh sát giao thông khu vực để theo sát toàn bộ quá trình xử lý vụ việc này, sau đó sẽ hỗ trợ bạn làm các thủ tục liên quan.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_05','V378','阮明',5,'后续治疗、证件补办、对接国内家属等全部相关事宜，都能寻求大使馆提供领事协助吧？','hòu xù zhì liáo、 zhèng jiàn bǔ bàn、 duì jiē guó nèi jiā shǔ děng quán bù xiāng guān shì yí， dōu néng xún qiú dà shǐ guǎn tí gōng lǐng shì xié zhù ba？','Những việc sau này như điều trị, làm lại giấy tờ, liên hệ với gia đình ở trong nước, đều có thể nhờ đại sứ quán hỗ trợ lãnh sự chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_06','V378','接线员',6,'是的，所有境外公民在中国遭遇重大人身意外，本国驻华大使馆均会提供全套领事协助服务。','shì de， suǒ yǒu jìng wài gōng mín zài zhōng guó zāo yù zhòng dà rén shēn yì wài， běn guó zhù huá dà shǐ guǎn jūn huì tí gōng quán tào lǐng shì xié zhù fú wù。','Đúng vậy, mọi công dân nước ngoài gặp tai nạn nghiêm trọng tại Trung Quốc đều sẽ được đại sứ quán nước mình hỗ trợ lãnh sự đầy đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_07','V378','阮明',7,'现在伤者正在接受医护检查，暂时无法确认伤情轻重，有新情况我会再次致电汇报。','xiàn zài shāng zhě zhèng zài jiē shòu yī hù jiǎn chá， zàn shí wú fǎ què rèn shāng qíng qīng zhòng， yǒu xīn qíng kuàng wǒ huì zài cì zhì diàn huì bào。','Hiện người bị thương đang được khám, tạm thời chưa xác định được mức độ nặng nhẹ, có tình hình mới tôi sẽ gọi lại báo cáo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_08','V378','接线员',8,'记下这条官方联系热线，后续任何手续难题随时来电咨询。','jì xià zhè tiáo guān fāng lián xì rè xiàn， hòu xù rèn hé shǒu xù nán tí suí shí lái diàn zī xún。','Bạn ghi lại số đường dây nóng chính thức này, sau này có khó khăn về thủ tục gì cứ gọi điện hỏi bất cứ lúc nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_09','V378','阮明',9,'我会保存热线号码，有需要第一时间联系使馆工作人员。','wǒ huì bǎo cún rè xiàn hào mǎ， yǒu xū yào dì yī shí jiān lián xì shǐ guǎn gōng zuò rén yuán。','Tôi sẽ lưu lại số đường dây nóng, có cần gì sẽ liên hệ ngay với nhân viên đại sứ quán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_10','V378','接线员',10,'祝你平安，有进展及时沟通。','zhù nǐ píng ān， yǒu jìn zhǎn jí shí gōu tōng。','Chúc bạn bình an, có tiến triển gì thì báo lại kịp thời nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_11','V378','阮明',11,'太感谢使馆提供应急协助，缓解我的慌乱。','tài gǎn xiè shǐ guǎn tí gōng yìng jí xié zhù， huǎn jiě wǒ de huāng luàn。','Cảm ơn đại sứ quán rất nhiều vì đã hỗ trợ khẩn cấp, giúp tôi bớt hoảng loạn hẳn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT379','S127','Viết CV xin việc làm thêm bán thời gian',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V379','SIT379','P1','twist','tuy_y',NULL,'国内兼职简历注重简洁清晰，留学生求职必须标注在校合法务工资质，方便用人单位审核。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_01','V379','阮明',1,'溪溪，我想写简历申请中文助教兼职，不知道怎么排版啊。','xī xī， wǒ xiǎng xiě jiǎn lì shēn qǐng zhōng wén zhù jiào jiān zhí， bù zhī dào zěn me pái bǎn a。','Khê Khê, tớ muốn viết CV xin làm trợ giảng tiếng Trung bán thời gian mà không biết trình bày sao cho ổn nữa.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_02','V379','林溪',2,'简历分基础信息、语言能力、实践经历三大块就行啦。','jiǎn lì fēn jī chǔ xìn xī、 yǔ yán néng lì、 shí jiàn jīng lì sān dà kuài jiù xíng la。','CV thì chia làm ba phần chính thôi: thông tin cơ bản, khả năng ngôn ngữ, kinh nghiệm thực tế là xong ấy mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_03','V379','阮明',3,'留学生需要额外标注签证和合法打工证明吗？','liú xué shēng xū yào é wài biāo zhù qiān zhèng hé hé fǎ dǎ gōng zhèng míng ma？','Du học sinh có cần ghi thêm visa với giấy phép làm thêm hợp pháp không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_04','V379','林溪',4,'一定要写，很多商家不清楚留学生打工规定呢。','yí dìng yào xiě， hěn duō shāng jiā bù qīng chǔ liú xué shēng dǎ gōng guī dìng ne。','Nhất định phải ghi đấy, nhiều nơi tuyển dụng không rõ quy định làm thêm của du học sinh đâu.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_05','V379','阮明',5,'我写完一份草稿，里面实践经历写得太简单。','wǒ xiě wán yī fèn cǎo gǎo， lǐ miàn shí jiàn jīng lì xiě dé tài jiǎn dān。','Tớ viết xong một bản nháp rồi, nhưng phần kinh nghiệm thực tế viết sơ sài quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_06','V379','林溪',6,'没关系，发给我，我帮你修改补充细节。','méi guān xì， fā gěi wǒ， wǒ bāng nǐ xiū gǎi bǔ chōng xì jié。','Không sao, gửi cho tớ, tớ sửa và bổ sung chi tiết giúp cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_07','V379','阮明',7,'太谢谢你，改完我就能直接投递岗位。','tài xiè xiè nǐ， gǎi wán wǒ jiù néng zhí jiē tóu dì gǎng wèi。','Cảm ơn cậu nhiều lắm, sửa xong là tớ nộp hồ sơ ứng tuyển luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT380','S127','Trả lời phỏng vấn xin việc làm thêm',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V380','SIT380','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职面试注重实操能力与空闲时间匹配度，面试官一般会在三日内统一反馈录用结果。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_01','V380','阮明',1,'主管您好，我是阮明，今天来面试少儿汉语助教兼职。','zhǔ guǎn nín hǎo， wǒ shì ruǎn míng， jīn tiān lái miàn shì shào ér hàn yǔ zhù jiào jiān zhí。','Chào quản lý, em là Nguyễn Minh, hôm nay đến phỏng vấn vị trí trợ giảng tiếng Trung thiếu nhi bán thời gian ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_02','V380','主管',2,'请坐，先简单介绍一下你的语言水平和空闲时间吧。','qǐng zuò， xiān jiǎn dān jiè shào yī xià nǐ de yǔ yán shuǐ píng hé kòng xián shí jiān ba。','Mời ngồi, em giới thiệu sơ qua về trình độ ngôn ngữ và thời gian rảnh của mình nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_03','V380','阮明',3,'我汉语日常交流流利，工作日傍晚和周末全天有空呢。','wǒ hàn yǔ rì cháng jiāo liú liú lì， gōng zuò rì bàng wǎn hé zhōu mò quán tiān yǒu kòng ne。','Em giao tiếp tiếng Trung hàng ngày khá trôi chảy, buổi tối các ngày trong tuần và cả ngày cuối tuần em đều rảnh ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_04','V380','主管',4,'你有和小朋友相处的相关经验，擅长课堂互动吗？','nǐ yǒu hé xiǎo péng yǒu xiāng chǔ de xiāng guān jīng yàn， shàn cháng kè táng hù dòng ma？','Em có kinh nghiệm tiếp xúc với trẻ nhỏ, có giỏi tương tác trong lớp học không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_05','V380','阮明',5,'我之前在校园活动带过低龄学生，很喜欢和孩子沟通。','wǒ zhī qián zài xiào yuán huó dòng dài guò dī líng xué shēng， hěn xǐ huān hé hái zi gōu tōng。','Trước đây em từng phụ trách các bé nhỏ tuổi trong hoạt động ở trường, em rất thích trò chuyện với trẻ con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_06','V380','主管',6,'整体条件符合岗位需求，三天内通知你入职结果。','zhěng tǐ tiáo jiàn fú hé gǎng wèi xū qiú， sān tiān nèi tōng zhī nǐ rù zhí jié guǒ。','Về cơ bản điều kiện của em phù hợp với yêu cầu công việc, trong vòng ba ngày sẽ báo kết quả tuyển dụng cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_07','V380','阮明',7,'感谢您给予面试机会，我耐心等候通知。','gǎn xiè nín jǐ yǔ miàn shì jī huì， wǒ nài xīn děng hòu tōng zhī。','Em cảm ơn anh/chị đã cho em cơ hội phỏng vấn, em sẽ kiên nhẫn chờ tin ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT381','S127','Ký hợp đồng lao động thời vụ',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V381','SIT381','P1','twist','chinh_thuc',NULL,'国内兼职临时用工必须签署劳务合同，薪资、加班、离职相关条款全部需要白纸黑字标注。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_01','V381','阮明',1,'您好，这份临时劳务合同我仔细看完，有一处想确认。','nín hǎo， zhè fèn lín shí láo wù hé tóng wǒ zǐ xì kàn wán， yǒu yī chù xiǎng què rèn。','Chào anh/chị, hợp đồng lao động tạm thời này tôi đã xem kỹ rồi, có một chỗ muốn xác nhận lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_02','V381','人事专员',2,'你对哪一条条款有疑问，直接提出来就可以哈。','nǐ duì nǎ yī tiáo tiáo kuǎn yǒu yí wèn， zhí jiē tí chū lái jiù kě yǐ hā。','Bạn thấy điều khoản nào chưa rõ thì cứ nói thẳng ra là được nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_03','V381','阮明',3,'合同标注每月二十号发薪，但是没有写明加班补贴标准嘛。','hé tóng biāo zhù měi yuè èr shí hào fā xīn， dàn shì méi yǒu xiě míng jiā bān bǔ tiē biāo zhǔn ma。','Hợp đồng ghi rõ ngày hai mươi hàng tháng trả lương, nhưng lại không nêu rõ mức phụ cấp làm thêm giờ mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_04','V381','人事专员',4,'加班薪资细则附在合同补充页，我拿给你核对。','jiā bān xīn zī xì zé fù zài hé tóng bǔ chōng yè， wǒ ná gěi nǐ hé duì。','Quy định chi tiết về lương làm thêm giờ nằm ở trang phụ lục của hợp đồng, tôi lấy cho bạn đối chiếu nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_05','V381','阮明',5,'补充条款签字之后，两份合同双方各留存一份对吧？','bǔ chōng tiáo kuǎn qiān zì zhī hòu， liǎng fèn hé tóng shuāng fāng gè liú cún yī fèn duì ba？','Sau khi ký vào phần điều khoản bổ sung, hai bên mỗi bên giữ một bản hợp đồng đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_06','V381','人事专员',6,'没错，一份门店存档，一份由你本人保管。','méi cuò， yī fèn mén diàn cún dàng， yī fèn yóu nǐ běn rén bǎo guǎn。','Đúng rồi, một bản lưu tại cửa hàng, một bản do chính bạn giữ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_07','V381','阮明',7,'清楚全部条款，我现在签字确认。','qīng chǔ quán bù tiáo kuǎn， wǒ xiàn zài qiān zì què rèn。','Tôi đã hiểu rõ toàn bộ điều khoản rồi, giờ tôi ký xác nhận luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT382','S127','Xin nghỉ làm vì trùng giờ thi',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V382','SIT382','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职允许学生因学业请假，门店会灵活调整排班，不会随意克扣薪资；学生备考类请假大多可以协调同事顶替，无需自行补工时。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_01','V382','阮明',1,'店长您好，有一件事提前跟您沟通，下周三我无法到门店上班。','diàn zhǎng nín hǎo， yǒu yī jiàn shì tí qián gēn nín gōu tōng， xià zhōu sān wǒ wú fǎ dào mén diàn shàng bān。','Chào cửa hàng trưởng, có việc này em muốn báo trước với anh/chị, thứ Tư tuần sau em không thể đến cửa hàng làm việc được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_02','V382','店长',2,'你先说说是什么原因，门店排班需要提前协调人员顶替岗位吧。','nǐ xiān shuō shuō shì shén me yuán yīn， mén diàn pái bān xū yào tí qián xié tiáo rén yuán dǐng tì gǎng wèi ba。','Em nói lý do xem nào, lịch trực của cửa hàng cần sắp xếp trước người thay ca chứ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_03','V382','阮明',3,'下周三全天进行汉语专业期末考试，从上午八点考到下午五点，全天都无法到岗，实在抱歉呢。','xià zhōu sān quán tiān jìn xíng hàn yǔ zhuān yè qī mò kǎo shì， cóng shàng wǔ bā diǎn kǎo dào xià wǔ wǔ diǎn， quán tiān dōu wú fǎ dào gǎng， shí zài bào qiàn ne。','Thứ Tư tuần sau em có kỳ thi cuối kỳ chuyên ngành tiếng Trung cả ngày, từ tám giờ sáng đến năm giờ chiều, cả ngày em không thể có mặt được, em thật sự xin lỗi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_04','V382','店长',4,'学生学业优先是理所应当的，你提前一周告知，我有充足时间调整整体排班。','xué shēng xué yè yōu xiān shì lǐ suǒ yīng dāng de， nǐ tí qián yī zhōu gào zhī， wǒ yǒu chōng zú shí jiān tiáo zhěng zhěng tǐ pái bān。','Việc học của sinh viên là ưu tiên hàng đầu, chuyện đương nhiên thôi, em báo trước một tuần thì anh/chị có đủ thời gian để điều chỉnh lịch trực chung rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_05','V382','阮明',5,'我担心缺一天班次，月度工时达不到门店规定标准，影响当月薪资发放。','wǒ dān xīn quē yī tiān bān cì， yuè dù gōng shí dá bú dào mén diàn guī dìng biāo zhǔn， yǐng xiǎng dàng yuè xīn zī fā fàng。','Em lo là nghỉ mất một ca sẽ khiến số giờ làm trong tháng không đạt chuẩn quy định của cửa hàng, ảnh hưởng đến lương tháng này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_06','V382','店长',6,'我会安排其他空闲同事顶替你的全天班次，不用有心理负担。','wǒ huì ān pái qí tā kòng xián tóng shì dǐng tì nǐ de quán tiān bān cì， bù yòng yǒu xīn lǐ fù dān。','Anh/chị sẽ sắp xếp đồng nghiệp khác rảnh thay ca cả ngày cho em, em đừng lo lắng gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_07','V382','阮明',7,'考完试之后，我可以主动多上两天晚班，补上本次缺失的工时。','kǎo wán shì zhī hòu， wǒ kě yǐ zhǔ dòng duō shàng liǎng tiān wǎn bān， bǔ shàng běn cì quē shī de gōng shí。','Sau khi thi xong, em có thể chủ động làm thêm hai buổi tối để bù lại số giờ đã thiếu lần này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_08','V382','店长',8,'不用刻意额外加班补工时，你后续正常出勤就满足月度最低工时要求。','bù yòng kè yì é wài jiā bān bǔ gōng shí， nǐ hòu xù zhèng cháng chū qín jiù mǎn zú yuè dù zuì dī gōng shí yāo qiú。','Không cần cố tình làm thêm để bù giờ đâu, em cứ đi làm bình thường sau đó là đủ đạt mức giờ tối thiểu trong tháng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_09','V382','阮明',9,'太感谢店长体谅学生备考，我会提前一天完成手头所有工作交接。','tài gǎn xiè diàn zhǎng tǐ liàng xué shēng bèi kǎo， wǒ huì tí qián yī tiān wán chéng shǒu tóu suǒ yǒu gōng zuò jiāo jiē。','Em cảm ơn cửa hàng trưởng rất nhiều vì đã thông cảm cho việc thi cử của sinh viên, em sẽ bàn giao xong hết công việc trước một ngày ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_10','V382','店长',10,'交接不用复杂，把当日需要整理的货品清单留在收银台就行。','jiāo jiē bù yòng fù zá， bǎ dāng rì xū yào zhěng lǐ de huò pǐn qīng dān liú zài shōu yín tái jiù xíng。','Bàn giao không cần phức tạp đâu, em chỉ cần để danh sách hàng hóa cần sắp xếp trong ngày ở quầy thu ngân là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_11','V382','阮明',11,'考试结束后我会第一时间回门店正常上班，不耽误后续排班。','kǎo shì jié shù hòu wǒ huì dì yī shí jiān huí mén diàn zhèng cháng shàng bān， bù dān wù hòu xù pái bān。','Thi xong em sẽ quay lại cửa hàng đi làm bình thường ngay, không làm ảnh hưởng đến lịch trực sau đó ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_12','V382','店长',12,'专心备考，不用分心担心门店工作。','zhuān xīn bèi kǎo， bù yòng fēn xīn dān xīn mén diàn gōng zuò。','Em cứ tập trung ôn thi đi, đừng bận tâm chuyện cửa hàng làm gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_13','V382','阮明',13,'我一定好好复习，不辜负您的包容。','wǒ yí dìng hǎo hǎo fù xí， bù gū fù nín de bāo róng。','Em nhất định sẽ ôn tập thật tốt, không phụ lòng bao dung của cửa hàng trưởng đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_14','V382','店长',14,'有任何考试变动提前跟我说，方便我重新调班。','yǒu rèn hé kǎo shì biàn dòng tí qián gēn wǒ shuō， fāng biàn wǒ chóng xīn diào bān。','Nếu có thay đổi gì về lịch thi thì báo trước cho anh/chị nhé, để tiện sắp xếp lại ca trực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_15','V382','阮明',15,'多谢店长体谅！','duō xiè diàn zhǎng tǐ liàng！','Em cảm ơn cửa hàng trưởng rất nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT383','S127','Hỏi rõ mức lương và hình thức trả lương',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V383','SIT383','P1','suon_se','ban_chinh_thuc',NULL,'企业发放兼职薪资仅支持国内储蓄卡，境外银行卡无法完成对公转账。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_01','V383','阮明',1,'您好，我想确认这份兼职的时薪标准和发薪渠道。','nín hǎo， wǒ xiǎng què rèn zhè fèn jiān zhí de shí xīn biāo zhǔn hé fā xīn qú dào。','Chào anh/chị, tôi muốn xác nhận lại mức lương theo giờ và cách trả lương của công việc bán thời gian này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_02','V383','人事专员',2,'每小时二十二元，每月二十号银行卡统一转账哦。','měi xiǎo shí èr shí èr yuán， měi yuè èr shí hào yín háng kǎ tǒng yī zhuǎn zhàng ó。','Hai mươi hai tệ một giờ, ngày hai mươi hàng tháng chuyển khoản qua thẻ ngân hàng đồng loạt nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_03','V383','阮明',3,'薪资会扣除社保或者其他手续费之类的费用吗？','xīn zī huì kòu chú shè bǎo huò zhě qí tā shǒu xù fèi zhī lèi de fèi yòng ma？','Lương có bị trừ bảo hiểm xã hội hay các loại phí thủ tục gì khác không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_04','V383','人事专员',4,'学生短期兼职不缴纳社保，到手工资无扣除呢。','xué shēng duǎn qī jiān zhí bù jiǎo nà shè bǎo， dào shǒu gōng zī wú kòu chú ne。','Sinh viên làm thêm ngắn hạn không phải đóng bảo hiểm xã hội, lương thực nhận không bị trừ khoản nào cả.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_05','V383','阮明',5,'只能绑定国内银行卡接收工资对吧？','zhǐ néng bǎng dìng guó nèi yín háng kǎ jiē shōu gōng zī duì ba？','Chỉ có thể dùng thẻ ngân hàng trong nước để nhận lương thôi đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_06','V383','人事专员',6,'是的，境外银行卡无法对接公司财务系统。','shì de， jìng wài yín háng kǎ wú fǎ duì jiē gōng sī cái wù xì tǒng。','Đúng vậy, thẻ ngân hàng nước ngoài không kết nối được với hệ thống tài chính của công ty.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_07','V383','阮明',7,'明白了，我尽快办理专用工资卡。','míng bái le， wǒ jǐn kuài bàn lǐ zhuān yòng gōng zī kǎ。','Tôi hiểu rồi, tôi sẽ sớm làm thẻ lương riêng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT384','S127','Hỏi về việc đóng thuế thu nhập làm thêm',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V384','SIT384','P1','twist','chinh_thuc',NULL,'国内劳务报酬设有免税额度，用人单位统一代扣个税，完税证明可用于留学生签证续办。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_01','V384','阮明',1,'您好，留学生兼职获得的收入，需要申报个人所得税吗？','nín hǎo， liú xué shēng jiān zhí huò dé de shōu rù， xū yào shēn bào gè rén suǒ dé shuì ma？','Chào chị, thu nhập từ công việc làm thêm của du học sinh có cần phải kê khai thuế thu nhập cá nhân không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_02','V384','财务',2,'月度收入超过八百元，超出部分需要缴纳劳务个税哈。','yuè dù shōu rù chāo guò bā bǎi yuán， chāo chū bù fèn xū yào jiǎo nà láo wù gè shuì hā。','Thu nhập trong tháng vượt quá tám trăm tệ thì phần vượt quá phải nộp thuế thu nhập cá nhân theo lao động dịch vụ đó nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_03','V384','阮明',3,'个税会直接从当月工资里扣除，还是我自行申报嘛？','gè shuì huì zhí jiē cóng dàng yuè gōng zī lǐ kòu chú， hái shì wǒ zì xíng shēn bào ma？','Thuế thu nhập cá nhân sẽ bị trừ thẳng vào lương tháng đó, hay là em phải tự kê khai vậy?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_04','V384','财务',4,'公司统一代扣代缴，工资条会标注扣税明细。','gōng sī tǒng yí dài kòu dài jiǎo， gōng zī tiáo huì biāo zhù kòu shuì míng xì。','Công ty sẽ khấu trừ và nộp thuế thay thống nhất, trên phiếu lương sẽ ghi rõ chi tiết khoản thuế bị trừ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_05','V384','阮明',5,'年末可以打印全年纳税记录用作签证材料吗？','nián mò kě yǐ dǎ yìn quán nián nà shuì jì lù yòng zuò qiān zhèng cái liào ma？','Cuối năm em có thể in bản ghi nộp thuế cả năm để làm hồ sơ visa được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_06','V384','财务',6,'可以，年末我统一打印完整纳税单据交给你。','kě yǐ， nián mò wǒ tǒng yī dǎ yìn wán zhěng nà shuì dān jù jiāo gěi nǐ。','Được chứ, cuối năm chị sẽ in đầy đủ chứng từ nộp thuế và đưa cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_07','V384','阮明',7,'好，相关规则我记下来，感谢细致讲解。','hǎo， xiāng guān guī zé wǒ jì xià lái， gǎn xiè xì zhì jiǎng jiě。','Dạ vâng, em ghi nhớ các quy định liên quan rồi, cảm ơn chị đã giải thích tỉ mỉ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT385','S128','Mở tài khoản ngân hàng riêng để nhận lương',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V385','SIT385','P1','suon_se','chinh_thuc',NULL,'外籍留学生凭护照、在校证明可办理学生储蓄卡，多数银行学生账户免除年费与小额管理费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_01','V385','阮明',1,'您好，我是在校留学生，想开一张储蓄卡专门接收兼职工资。','nín hǎo， wǒ shì zài xiào liú xué shēng， xiǎng kāi yī zhāng chǔ xù kǎ zhuān mén jiē shōu jiān zhí gōng zī。','Chào chị, em là du học sinh đang theo học tại trường, em muốn mở một thẻ tiết kiệm chuyên để nhận lương làm thêm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_02','V385','柜员',2,'请出示你的护照、在校学生证，填写开户申请单吧。','qǐng chū shì nǐ de hù zhào、 zài xiào xué shēng zhèng， tián xiě kāi hù shēn qǐng dān ba。','Em vui lòng xuất trình hộ chiếu và thẻ sinh viên, rồi điền vào đơn xin mở tài khoản này ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_03','V385','阮明',3,'这张卡只用来收工资，平时不存放大额资金可以吗？','zhè zhāng kǎ zhǐ yòng lái shōu gōng zī， píng shí bù cún fàng dà é zī jīn kě yǐ ma？','Thẻ này em chỉ dùng để nhận lương thôi, bình thường không giữ số tiền lớn trong đó có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_04','V385','柜员',4,'完全没问题，普通一类储蓄卡支持企业对公转账呢。','wán quán méi wèn tí， pǔ tōng yī lèi chǔ xù kǎ zhī chí qǐ yè duì gōng zhuàn zhàng ne。','Hoàn toàn không vấn đề gì, thẻ tiết kiệm loại thường vẫn nhận được chuyển khoản từ doanh nghiệp đấy ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_05','V385','阮明',5,'开户有没有年费、短信通知这类额外收费项目？','kāi hù yǒu méi yǒu nián fèi、 duǎn xìn tōng zhī zhè lèi é wài shōu fèi xiàng mù？','Mở tài khoản có phải đóng phí thường niên hay phí báo tin nhắn gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_06','V385','柜员',6,'学生账户免年费，免费开通资金变动短信提醒。','xué shēng zhàng hù miǎn nián fèi， miǎn fèi kāi tōng zī jīn biàn dòng duǎn xìn tí xǐng。','Tài khoản sinh viên được miễn phí thường niên, đăng ký báo biến động số dư qua tin nhắn cũng miễn phí luôn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_07','V385','阮明',7,'好，我现在填写单据办理开户手续。','hǎo， wǒ xiàn zài tián xiě dān jù bàn lǐ kāi hù shǒu xù。','Vâng, giờ em điền đơn để làm thủ tục mở tài khoản luôn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT386','S127','Xin nghỉ việc trước thời hạn hợp đồng',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V386','SIT386','P1','twist','ban_chinh_thuc',NULL,'国内临时劳务用工规范要求员工提前三十天申请离职，企业可根据门店人手、员工实际情况适度放宽离职期限；离职必须填写书面申请存档，口头离职不生效。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_01','V386','阮明',1,'店长，我今天过来跟您沟通离职事宜，下学期专业课数量大幅增加。','diàn zhǎng， wǒ jīn tiān guò lái gēn nín gōu tōng lí zhí shì yí， xià xué qī zhuān yè kè shù liàng dà fú zēng jiā。','Anh ơi, hôm nay em qua trao đổi với anh về chuyện xin nghỉ việc, học kỳ tới số môn chuyên ngành của em tăng nhiều lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_02','V386','店长',2,'我大致了解留学生课程安排，你计划什么时候正式结束兼职工作？','wǒ dà zhì liǎo jiě liú xué shēng kè chéng ān pái， nǐ jì huà shén me shí hòu zhèng shì jié shù jiān zhí gōng zuò？','Anh cũng nắm sơ lịch học của du học sinh rồi, em định khi nào thì chính thức nghỉ làm thêm?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_03','V386','阮明',3,'原本合同约定做到学期末，我想申请提前半个月办理离职手续。','yuán běn hé tóng yuē dìng zuò dào xué qī mò， wǒ xiǎng shēn qǐng tí qián bàn gè yuè bàn lǐ lí zhí shǒu xù。','Theo hợp đồng ban đầu em làm đến hết học kỳ, nhưng em muốn xin nghỉ sớm nửa tháng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_04','V386','店长',4,'门店劳务用工有统一规范，离职需要提前三十天书面提交申请，只提前半个月不符合规定嘛。','mén diàn láo wù yòng gōng yǒu tǒng yī guī fàn， lí zhí xū yào tí qián sān shí tiān shū miàn tí jiāo shēn qǐng， zhǐ tí qián bàn gè yuè bù fú hé guī dìng ma。','Cửa hàng có quy định chung về lao động, nghỉ việc phải báo trước bằng văn bản ba mươi ngày, chỉ báo trước nửa tháng thì không đúng quy định đâu nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_05','V386','阮明',5,'新学期课程表全部排满白天晚上，完全抽不出空余时间兼顾兼职工作。','xīn xué qī kè chéng biǎo quán bù pái mǎn bái tiān wǎn shàng， wán quán chōu bù chū kòng yú shí jiān jiān gù jiān zhí gōng zuò。','Lịch học kỳ mới của em kín cả ngày lẫn tối, thật sự không sắp xếp được thời gian để làm thêm nữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_06','V386','店长',6,'我能理解留学生课业压力大，直接按三十天标准离职时间执行对你压力太大。','wǒ néng lǐ jiě liú xué shēng kè yè yā lì dà， zhí jiē àn sān shí tiān biāo zhǔn lí zhí shí jiān zhí xíng duì nǐ yā lì tài dà。','Anh hiểu áp lực học hành của du học sinh nặng lắm, nếu bắt em theo đúng chuẩn ba mươi ngày thì cũng quá sức với em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_07','V386','阮明',7,'我这段时间可以全力做好客户对接、货品盘点等全部工作交接。','wǒ zhè duàn shí jiān kě yǐ quán lì zuò hào kè hù duì jiē、 huò pǐn pán diǎn děng quán bù gōng zuò jiāo jiē。','Trong thời gian này em có thể tập trung làm hết việc bàn giao, từ liên hệ khách hàng đến kiểm kê hàng hóa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_08','V386','店长',8,'结合门店近期人手充足的现状，我向上级人事申请，最多协调缩短到二十天离职周期。','jié hé mén diàn jìn qī rén shǒu chōng zú de xiàn zhuàng， wǒ xiàng shàng jí rén shì shēn qǐng， zuì duō xié tiáo suō duǎn dào èr shí tiān lí zhí zhōu qī。','Xét tình hình cửa hàng gần đây cũng đủ người, anh sẽ xin cấp trên bên nhân sự, cố gắng rút ngắn xuống hai mươi ngày cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_09','V386','阮明',9,'二十天的周期我完全可以接受，这段时间我逐项梳理所有工作内容做好交接。','èr shí tiān de zhōu qī wǒ wán quán kě yǐ jiē shòu， zhè duàn shí jiān wǒ zhú xiàng shū lǐ suǒ yǒu gōng zuò nèi róng zuò hǎo jiāo jiē。','Hai mươi ngày thì em hoàn toàn chấp nhận được, thời gian này em sẽ rà soát từng phần công việc để bàn giao cho chu đáo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_10','V386','店长',10,'今天填写纸质离职申请表，我签字之后统一交给人事部门存档备案。','jīn tiān tián xiě zhǐ zhì lí zhí shēn qǐng biǎo， wǒ qiān zì zhī hòu tǒng yī jiāo gěi rén shì bù mén cún dàng bèi àn。','Hôm nay em điền đơn xin nghỉ việc bản giấy đi, anh ký xong sẽ chuyển thẳng cho phòng nhân sự lưu hồ sơ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_11','V386','阮明',11,'交接清单我每天整理一部分，离职当天完整交给接替岗位的同事。','jiāo jiē qīng dān wǒ měi tiān zhěng lǐ yī bù fèn， lí zhí dàng tiān wán zhěng jiāo gěi jiē tì gǎng wèi de tóng shì。','Danh sách bàn giao em sẽ soạn dần mỗi ngày một phần, đến ngày nghỉ chính thức sẽ giao đầy đủ cho người thay thế ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_12','V386','店长',12,'交接过程中有不清楚的地方随时来办公室找我沟通。','jiāo jiē guò chéng zhōng yǒu bù qīng chǔ de dì fāng suí shí lái bàn gōng shì zhǎo wǒ gōu tōng。','Trong lúc bàn giao có gì chưa rõ thì cứ lên văn phòng tìm anh trao đổi bất cứ lúc nào nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_13','V386','阮明',13,'麻烦店长帮忙审批这份离职申请，这段时间也多谢门店所有人照顾我。','má fán diàn zhǎng bāng máng shěn pī zhè fèn lí zhí shēn qǐng， zhè duàn shí jiān yě duō xiè mén diàn suǒ yǒu rén zhào gù wǒ。','Phiền anh duyệt giúp em đơn xin nghỉ này, với lại cảm ơn mọi người trong cửa hàng đã giúp đỡ em suốt thời gian qua ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_14','V386','店长',14,'没事，学业为重，后续有空闲假期也欢迎再来短期兼职。','méi shì， xué yè wèi zhòng， hòu xù yǒu kòng xián jià qī yě huān yíng zài lái duǎn qī jiān zhí。','Không sao, việc học là quan trọng nhất, sau này rảnh dịp nghỉ nào cứ quay lại làm thêm ngắn hạn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_15','V386','阮明',15,'十分感谢您通融调整离职周期！','shí fēn gǎn xiè nín tōng róng tiáo zhěng lí zhí zhōu qī！','Em cảm ơn anh rất nhiều vì đã linh động điều chỉnh thời gian nghỉ việc cho em!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT387','S127','Hỏi quy định giờ làm tối đa cho sinh viên quốc tế',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V387','SIT387','P1','suon_se','chinh_thuc',NULL,'中国法律明确规定外籍留学生务工时长，超时务工将影响签证续签，学校会定期核查兼职情况。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_01','V387','阮明',1,'老师您好，我想咨询留学生校内、校外兼职时长限制。','lǎo shī nín hǎo， wǒ xiǎng zī xún liú xué shēng xiào nèi、 xiào wài jiān zhí shí cháng xiàn zhì。','Chào thầy/cô, em muốn hỏi về quy định giới hạn thời gian làm thêm trong và ngoài trường cho du học sinh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_02','V387','国际处老师',2,'学期内每周打工总时长不能超过二十小时哦。','xué qī nèi měi zhōu dǎ gōng zǒng shí cháng bù néng chāo guò èr shí xiǎo shí ó。','Trong học kỳ, tổng thời gian làm thêm mỗi tuần không được vượt quá hai mươi tiếng đâu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_03','V387','阮明',3,'寒暑假期间，时长限制会适当放宽一些吗？','hán shǔ jià qī jiān， shí cháng xiàn zhì huì shì dàng fàng kuān yī xiē ma？','Vào kỳ nghỉ hè, đông thì giới hạn đó có được nới lỏng hơn một chút không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_04','V387','国际处老师',4,'假期每周最多四十小时，超出属于违规务工呢。','jià qī měi zhōu zuì duō sì shí xiǎo shí， chāo chū shǔ yú wéi guī wù gōng ne。','Vào kỳ nghỉ thì tối đa bốn mươi tiếng mỗi tuần, quá mức đó là làm việc trái quy định đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_05','V387','阮明',5,'超时打工会不会影响我的签证续办审核？','chāo shí dǎ gōng huì bú huì yǐng xiǎng wǒ de qiān zhèng xù bàn shěn hé？','Làm thêm quá giờ có ảnh hưởng đến việc xét gia hạn visa của em không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_06','V387','国际处老师',6,'会有影响，出入境管理局会核查务工时长记录。','huì yǒu yǐng xiǎng， chū rù jìng guǎn lǐ jú huì hé chá wù gōng shí cháng jì lù。','Có ảnh hưởng chứ, cơ quan quản lý xuất nhập cảnh sẽ kiểm tra hồ sơ thời gian làm thêm đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_07','V387','阮明',7,'我清楚规定了，一定会严格控制上班时长。','wǒ qīng chǔ guī dìng le， yí dìng huì yán gé kòng zhì shàng bān shí cháng。','Em hiểu quy định rồi ạ, nhất định em sẽ kiểm soát chặt thời gian làm việc của mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT388','S127','Trao đổi ca làm việc với đồng nghiệp',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V388','SIT388','P1','twist','tuy_y',NULL,'兼职员工私下换班必须告知主管登记，避免岗位无人值守，产生运营问题。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_01','V388','阮明',1,'小秦，我周四下午有汉语测验，能和你互换班次吗？','xiǎo qín， wǒ zhōu sì xià wǔ yǒu hàn yǔ cè yàn， néng hé nǐ hù huàn bān cì ma？','Tiểu Tần ơi, chiều thứ Năm này mình có bài kiểm tra tiếng Trung, đổi ca với mình được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_02','V388','小秦',2,'我周四全天有社团活动，那天也没办法上班嘛。','wǒ zhōu sì quán tiān yǒu shè tuán huó dòng， nà tiān yě méi bàn fǎ shàng bān ma。','Cả ngày thứ Năm mình có hoạt động câu lạc bộ rồi, hôm đó mình cũng không đi làm được đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_03','V388','阮明',3,'原来是这样，那周五的班次你方便和我调换不？','yuán lái shì zhè yàng， nà zhōu wǔ de bān cì nǐ fāng biàn hé wǒ diào huàn bù？','Ra vậy à, thế ca thứ Sáu bạn có tiện đổi cho mình không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_04','V388','小秦',4,'周五我空闲，我们调换之后跟店长报备一下就行。','zhōu wǔ wǒ kòng xián， wǒ men diào huàn zhī hòu gēn diàn zhǎng bào bèi yī xià jiù xíng。','Thứ Sáu mình rảnh, đổi xong tụi mình báo lại với quản lý một tiếng là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_05','V388','阮明',5,'太好了，调换班次需要填写纸质调换申请单吗？','tài hǎo le， diào huàn bān cì xū yào tián xiě zhǐ zhì diào huàn shēn qǐng dān ma？','Tuyệt quá, đổi ca thế này có cần điền đơn giấy gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_06','V388','小秦',6,'不用，微信跟店长说一声登记备案就可以。','bù yòng， wēi xìn gēn diàn zhǎng shuō yī shēng dēng jì bèi àn jiù kě yǐ。','Không cần đâu, chỉ cần nhắn Wechat báo quản lý ghi nhận lại là xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_07','V388','阮明',7,'太谢谢你，解决了我的难题。','tài xiè xiè nǐ， jiě jué le wǒ de nán tí。','Cảm ơn cậu nhiều nha, giúp mình gỡ được cái khó này rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT389','S127','Báo cáo sự cố trong ca làm với quản lý',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V389','SIT389','P1','suon_se','ban_chinh_thuc',NULL,'服务行业工作中出现客户突发状况，员工第一时间上报主管并留存记录，是标准工作流程。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_01','V389','阮明',1,'主管，刚刚上课出现突发情况，我来跟您汇报一下。','zhǔ guǎn， gāng gāng shàng kè chū xiàn tū fā qíng kuàng， wǒ lái gēn nín huì bào yī xià。','Quản lý ơi, vừa nãy trong giờ dạy có chuyện bất ngờ xảy ra, em qua báo cáo với anh/chị một chút ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_02','V389','主管',2,'别着急，慢慢说，课堂上发生什么意外了吧？','bié zháo jí， màn màn shuō， kè táng shàng fā shēng shén me yì wài le ba？','Đừng vội, từ từ kể xem, trong lớp có chuyện gì xảy ra vậy?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_03','V389','阮明',3,'一名小朋友身体不舒服，家长临时赶来把孩子接走了呢。','yī míng xiǎo péng yǒu shēn tǐ bù shū fú， jiā zhǎng lín shí gǎn lái bǎ hái zi jiē zǒu le ne。','Có một bé học sinh khó chịu trong người, phụ huynh đã đến đón bé về rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_04','V389','主管',4,'孩子有没有出现发烧、呕吐这类严重不适症状？','hái zi yǒu méi yǒu chū xiàn fā shāo、 ǒu tù zhè lèi yán zhòng bù shì zhèng zhuàng？','Bé có bị sốt hay nôn ói gì nghiêm trọng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_05','V389','阮明',5,'只是轻微头晕，休息片刻就好转，家长已经带离校区。','zhǐ shì qīng wēi tóu yūn， xiū xī piàn kè jiù hǎo zhuǎn， jiā zhǎng yǐ jīng dài lí xiào qū。','Chỉ hơi chóng mặt thôi, nghỉ một lát là đỡ, phụ huynh đã đưa bé rời khỏi trường rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_06','V389','主管',6,'记录好学生信息，后续跟进询问孩子身体状况。','jì lù hào xué shēng xìn xī， hòu xù gēn jìn xún wèn hái zi shēn tǐ zhuàng kuàng。','Ghi lại đầy đủ thông tin học sinh, sau đó theo dõi hỏi thăm tình hình sức khỏe của bé nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_07','V389','阮明',7,'好，我马上整理情况记录，同步发给您查看。','hǎo， wǒ mǎ shàng zhěng lǐ qíng kuàng jì lù， tóng bù fā gěi nín chá kàn。','Vâng, em sẽ lập tức tổng hợp lại tình hình rồi gửi cho anh/chị xem ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT390','S127','Xin thư giới thiệu từ nơi thực tập',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V390','SIT390','P1','twist','chinh_thuc',NULL,'企业开具实习推荐信加盖公章需行政部门审核，私人手写无公章的推荐信不具备官方证明效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_01','V390','阮明',1,'领导您好，我的实习周期即将结束，想申请一份实习推荐信。','lǐng dǎo nín hǎo， wǒ de shí xí zhōu qī jí jiāng jié shù， xiǎng shēn qǐng yī fèn shí xí tuī jiàn xìn。','Chào anh/chị, kỳ thực tập của em sắp kết thúc rồi, em muốn xin một thư giới thiệu thực tập ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_02','V390','负责人',2,'可以，推荐信用于升学还是后续求职使用呢？','kě yǐ， tuī jiàn xìn yòng yú shēng xué hái shì hòu xù qiú zhí shǐ yòng ne？','Được chứ, thư giới thiệu này em dùng để học tiếp hay để đi xin việc sau này vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_03','V390','阮明',3,'用于境外深造申请，需要加盖公司官方公章对吧？','yòng yú jìng wài shēn zào shēn qǐng， xū yào jiā gài gōng sī guān fāng gōng zhāng duì ba？','Em dùng để nộp hồ sơ du học nước ngoài, cần đóng dấu chính thức của công ty đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_04','V390','负责人',4,'推荐信内容我可以撰写，但公章需要行政部门统一审批嘛。','tuī jiàn xìn nèi róng wǒ kě yǐ zhuàn xiě， dàn gōng zhāng xū yào xíng zhèng bù mén tǒng yī shěn pī ma。','Nội dung thư anh/chị có thể soạn cho em, nhưng con dấu thì phải qua bộ phận hành chính duyệt thống nhất nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_05','V390','阮明',5,'审批流程大概需要几天，我下周就要提交申请材料。','shěn pī liú chéng dà gài xū yào jǐ tiān， wǒ xià zhōu jiù yào tí jiāo shēn qǐng cái liào。','Quy trình duyệt mất khoảng mấy ngày ạ, tuần sau em phải nộp hồ sơ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_06','V390','负责人',6,'三天内完成审批盖章，到时候我通知你来领取。','sān tiān nèi wán chéng shěn pī gài zhāng， dào shí hòu wǒ tōng zhī nǐ lái lǐng qǔ。','Trong ba ngày sẽ duyệt và đóng dấu xong, lúc đó anh/chị sẽ báo em đến lấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_07','V390','阮明',7,'麻烦领导费心帮忙，非常感谢。','má fán lǐng dǎo fèi xīn bāng máng， fēi cháng gǎn xiè。','Phiền anh/chị giúp đỡ em, em cảm ơn nhiều lắm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT391','S129','Xin cấp bảng điểm chính thức',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V391','SIT391','P1','twist','ban_chinh_thuc',NULL,'留学生用于出境、升学的成绩单必须由学校教务盖章，电子版文件不具备官方效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_01','V391','阮明',1,'老师您好，我毕业需要正式成绩单，想申请打印几份。','lǎo shī nín hǎo， wǒ bì yè xū yào zhèng shì chéng jì dān， xiǎng shēn qǐng dǎ yìn jǐ fèn。','Chào thầy/cô, em sắp tốt nghiệp cần bảng điểm chính thức, em muốn xin in vài bản ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_02','V391','教务老师',2,'没问题，填好这份申请表，带上你的护照原件哦。','méi wèn tí， tián hǎo zhè fèn shēn qǐng biǎo， dài shàng nǐ de hù zhào yuán jiàn ó。','Không vấn đề gì, em điền đơn này rồi mang theo hộ chiếu gốc đến nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_03','V391','阮明',3,'申请表我已经填完了，但是护照昨天拿去办签证了嘛。','shēn qǐng biǎo wǒ yǐ jīng tián wán le， dàn shì hù zhào zuó tiān ná qù bàn qiān zhèng le ma。','Đơn thì em điền xong rồi ạ, nhưng hộ chiếu hôm qua em mang đi làm visa mất rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_04','V391','教务老师',4,'没有证件不能办理，你改天带护照再来登记吧。','méi yǒu zhèng jiàn bù néng bàn lǐ， nǐ gǎi tiān dài hù zhào zài lái dēng jì ba。','Không có giấy tờ thì không làm được đâu, em để hôm khác mang hộ chiếu đến đăng ký lại nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_05','V391','阮明',5,'那我明天一早把护照带过来，当天就能拿到成绩单吗？','nà wǒ míng tiān yī zǎo bǎ hù zhào dài guò lái， dàng tiān jiù néng ná dào chéng jì dān ma？','Vậy sáng mai em mang hộ chiếu đến sớm, hôm đó em nhận được bảng điểm luôn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_06','V391','教务老师',6,'纸质成绩单当场打印盖章，不用额外等候。','zhǐ zhì chéng jì dān dāng chǎng dǎ yìn gài zhāng， bù yòng é wài děng hòu。','Bảng điểm giấy in và đóng dấu ngay tại chỗ, không phải chờ thêm gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_07','V391','阮明',7,'好，辛苦老师，我明天准时过来办理。','hǎo， xīn kǔ lǎo shī， wǒ míng tiān zhǔn shí guò lái bàn lǐ。','Vâng, cảm ơn thầy/cô vất vả, mai em sẽ đến đúng giờ để làm thủ tục ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT392','S129','Xin cấp bằng tốt nghiệp và công chứng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V392','SIT392','P1','suon_se','chinh_thuc',NULL,'外国留学生回国使用国内学历证件，必须办理涉外公证，境外机构才认可学历效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_01','V392','阮明',1,'您好，我课程全部修完，来领取毕业证并申请校内公证。','nín hǎo， wǒ kè chéng quán bù xiū wán， lái lǐng qǔ bì yè zhèng bìng shēn qǐng xiào nèi gōng zhèng。','Chào anh/chị, em đã hoàn thành hết các môn học, em đến nhận bằng tốt nghiệp và xin công chứng trong trường ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_02','V392','工作人员',2,'先核对你的全部考勤和缴费记录，没有欠费才能办理呢。','xiān hé duì nǐ de quán bù kǎo qín hé jiǎo fèi jì lù， méi yǒu qiàn fèi cái néng bàn lǐ ne。','Để anh/chị kiểm tra lại toàn bộ hồ sơ điểm danh và đóng học phí của em, không nợ gì mới làm được nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_03','V392','阮明',3,'学费、住宿费我都按时交清，没有任何欠费记录。','xué fèi、 zhù sù fèi wǒ dōu àn shí jiāo qīng， méi yǒu rèn hé qiàn fèi jì lù。','Học phí với tiền ký túc xá em đều đóng đúng hạn hết rồi, không có khoản nào còn nợ cả ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_04','V392','工作人员',4,'毕业证当场发放，公证文件三个工作日后可取。','bì yè zhèng dāng chǎng fā fàng， gōng zhèng wén jiàn sān gè gōng zuò rì hòu kě qǔ。','Bằng tốt nghiệp sẽ phát ngay tại chỗ, còn văn bản công chứng thì sau ba ngày làm việc mới lấy được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_05','V392','阮明',5,'公证文件可以多打印两份，方便我带回越南使用吧？','gōng zhèng wén jiàn kě yǐ duō dǎ yìn liǎng fèn， fāng biàn wǒ dài huí yuè nán shǐ yòng ba？','Văn bản công chứng anh/chị in giúp em thêm hai bản nữa được không, để em tiện mang về Việt Nam dùng ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_06','V392','工作人员',6,'没问题，每份公证只收取基础工本费。','méi wèn tí， měi fèn gōng zhèng zhǐ shōu qǔ jī chǔ gōng běn fèi。','Không vấn đề gì, mỗi bản công chứng chỉ thu phí làm hồ sơ cơ bản thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_07','V392','阮明',7,'麻烦您帮忙办理，这份材料对我后续深造很重要。','má fán nín bāng máng bàn lǐ， zhè fèn cái liào duì wǒ hòu xù shēn zào hěn zhòng yào。','Phiền anh/chị giúp em làm thủ tục này, hồ sơ này rất quan trọng cho việc học tiếp sau này của em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT393','S130','Làm thủ tục trả phòng ký túc xá',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V393','SIT393','P1','twist','ban_chinh_thuc',NULL,'高校宿舍退房会逐一清点室内设施，人为造成大面积破损，学校会从住宿押金中扣除维修费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_01','V393','阮明',1,'阿姨，我今天来办宿舍退房，麻烦检查一下房间。','ā yí， wǒ jīn tiān lái bàn sù shè tuì fáng， má fán jiǎn chá yī xià fáng jiān。','Cô ơi, hôm nay em đến làm thủ tục trả phòng ký túc xá, phiền cô kiểm tra giúp em phòng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_02','V393','宿管阿姨',2,'我看看桌椅、墙面和电器，破损会扣押金哈。','wǒ kàn kàn zhuō yǐ、 qiáng miàn hé diàn qì， pò sǔn huì kòu yā jīn hā。','Để cô xem bàn ghế, tường và đồ điện, hư hỏng gì là bị trừ tiền cọc đó nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_03','V393','阮明',3,'我平时很爱惜房间，只有书桌边角有一点小划痕嘛。','wǒ píng shí hěn ài xī fáng jiān， zhǐ yǒu shū zhuō biān jiǎo yǒu yì diǎn xiǎo huà hén ma。','Em vẫn giữ gìn phòng cẩn thận lắm, chỉ có góc bàn học bị trầy nhẹ một chút thôi mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_04','V393','宿管阿姨',4,'轻微划痕不影响，不需要扣除押金。','qīng wēi huà hén bù yǐng xiǎng， bù xū yào kòu chú yā jīn。','Trầy nhẹ vậy thì không sao, không cần trừ tiền cọc đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_05','V393','阮明',5,'那我的行李可以暂时放在楼道等同学帮忙搬运吗？','nà wǒ de xíng lǐ kě yǐ zàn shí fàng zài lóu dào děng tóng xué bāng máng bān yùn ma？','Vậy đồ đạc của em có thể để tạm ở hành lang chờ bạn học phụ khiêng được không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_06','V393','宿管阿姨',6,'短时间放置没问题，不要堵塞消防通道就行。','duǎn shí jiān fàng zhì méi wèn tí， bú yào dǔ sè xiāo fáng tōng dào jiù xíng。','Để tạm một lúc thì không vấn đề gì, chỉ cần đừng để chắn lối thoát hiểm là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_07','V393','阮明',7,'太感谢阿姨通融，我收拾完立刻离开宿舍楼。','tài gǎn xiè ā yí tōng róng， wǒ shōu shí wán lì kè lí kāi sù shè lóu。','Em cảm ơn cô đã thông cảm nhiều, em thu dọn xong sẽ rời khỏi tòa ký túc ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT394','S130','Thanh lý hợp đồng thuê nhà ngoài',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V394','SIT394','P1','suon_se','ban_chinh_thuc',NULL,'提前退租需和房东当面清点房屋物品，确认无损坏、无欠费后，房东才会全额返还租房押金。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_01','V394','阮明',1,'房东您好，我马上毕业回国，想提前终止租房合同。','fáng dōng nín hǎo， wǒ mǎ shàng bì yè huí guó， xiǎng tí qián zhōng zhǐ zū fáng hé tóng。','Chào chủ nhà, em sắp tốt nghiệp về nước rồi nên muốn xin chấm dứt hợp đồng thuê nhà sớm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_02','V394','房东',2,'可以，我们按合同约定清点家具，结清水电杂费吧。','kě yǐ， wǒ men àn hé tóng yuē dìng qīng diǎn jiā jù， jié qīng shuǐ diàn zá fèi ba。','Được thôi, mình kiểm kê đồ đạc theo hợp đồng rồi thanh toán tiền điện nước linh tinh cho gọn nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_03','V394','阮明',3,'所有家具完好无损，水电费我已经全部缴清了呢。','suǒ yǒu jiā jù wán hǎo wú sǔn， shuǐ diàn fèi wǒ yǐ jīng quán bù jiǎo qīng le ne。','Đồ đạc còn nguyên vẹn hết, tiền điện nước em cũng đóng đủ hết rồi đó ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_04','V394','房东',4,'墙面没有污渍、家电能正常使用，我全额退还押金。','qiáng miàn méi yǒu wū zì、 jiā diàn néng zhèng cháng shǐ yòng， wǒ quán é tuì huán yā jīn。','Tường không có vết bẩn, đồ điện dùng bình thường, vậy tôi hoàn lại đủ tiền cọc cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_05','V394','阮明',5,'押金可以直接转账到我的银行卡里对吗？','yā jīn kě yǐ zhí jiē zhuǎn zhàng dào wǒ de yín háng kǎ lǐ duì ma？','Tiền cọc chuyển thẳng vào thẻ ngân hàng của em được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_06','V394','房东',6,'没问题，验收完房屋当天就给你转账。','méi wèn tí， yàn shōu wán fáng wū dàng tiān jiù gěi nǐ zhuǎn zhàng。','Được chứ, kiểm tra nhà xong hôm nay là chuyển khoản cho em luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_07','V394','阮明',7,'辛苦您抽空过来验房，麻烦您多费心。','xīn kǔ nín chōu kòng guò lái yàn fáng， má fán nín duō fèi xīn。','Cảm ơn chủ nhà đã dành thời gian đến kiểm tra nhà, phiền chủ nhà nhiều rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT395','S119','Đóng tài khoản ngân hàng trước khi về nước',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V395','SIT395','P1','twist','chinh_thuc',NULL,'外籍人员长期离境建议注销国内闲置银行卡，避免长期休眠账户产生管理风险。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_01','V395','阮明',1,'您好，我即将回国，想要注销这张留学生储蓄卡。','nín hǎo， wǒ jí jiāng huí guó， xiǎng yào zhù xiāo zhè zhāng liú xué shēng chǔ xù kǎ。','Chào chị, em sắp về nước nên muốn đóng thẻ tiết kiệm dành cho du học sinh này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_02','V395','柜员',2,'先把卡里余额全部取出，再填写销户申请单哦。','xiān bǎ kǎ lǐ yú é quán bù qǔ chū， zài tián xiě xiāo hù shēn qǐng dān ó。','Em rút hết số dư trong thẻ ra trước, rồi điền đơn xin đóng tài khoản nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_03','V395','阮明',3,'我刚刚查询，账户还有十几块零钱没法线上转出嘛。','wǒ gāng gāng chá xún， zhàng hù hái yǒu shí jǐ kuài líng qián méi fǎ xiàn shàng zhuǎn chū ma。','Em vừa kiểm tra, tài khoản còn dư mấy chục nghìn lẻ không chuyển online được mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_04','V395','柜员',4,'小额现金柜台可以直接取出，不影响销户流程。','xiǎo é xiàn jīn guì tái kě yǐ zhí jiē qǔ chū， bù yǐng xiǎng xiāo hù liú chéng。','Số tiền lẻ đó có thể rút trực tiếp ở quầy, không ảnh hưởng đến việc đóng tài khoản đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_05','V395','阮明',5,'销户完成后，银行会开具销户证明给我吗？','xiāo hù wán chéng hòu， yín háng huì kāi jù xiāo hù zhèng míng gěi wǒ ma？','Sau khi đóng tài khoản xong, ngân hàng có cấp giấy xác nhận đóng tài khoản cho em không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_06','V395','柜员',6,'可以，纸质销户回执会加盖公章交给你留存。','kě yǐ， zhǐ zhì xiāo hù huí zhí huì jiā gài gōng zhāng jiāo gěi nǐ liú cún。','Có chứ, biên nhận đóng tài khoản bản giấy sẽ được đóng dấu và giao cho em giữ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_07','V395','阮明',7,'好，我现在办理取现，再完成销户手续。','hǎo， wǒ xiàn zài bàn lǐ qǔ xiàn， zài wán chéng xiāo hù shǒu xù。','Dạ, vậy em làm thủ tục rút tiền mặt ngay bây giờ, rồi hoàn tất thủ tục đóng tài khoản ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT396','S131','Hủy SIM điện thoại trước khi về nước',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V396','SIT396','P1','suon_se','ban_chinh_thuc',NULL,'留学生离境前务必注销手机卡，若长期欠费停机，会影响本人后续再次办理国内通信业务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_01','V396','阮明',1,'你好，我毕业要回国，打算注销名下这张手机电话卡。','nǐ hǎo， wǒ bì yè yào huí guó， dǎ suàn zhù xiāo míng xià zhè zhāng shǒu jī diàn huà kǎ。','Chào anh, em tốt nghiệp phải về nước nên muốn hủy sim điện thoại đứng tên em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_02','V396','客服',2,'出示办卡时的护照，我先查询套餐是否有未结清费用呢。','chū shì bàn kǎ shí de hù zhào， wǒ xiān chá xún tào cān shì fǒu yǒu wèi jié qīng fèi yòng ne。','Em cho anh xem hộ chiếu lúc đăng ký sim, anh kiểm tra xem gói cước còn nợ cước gì không nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_03','V396','阮明',3,'上个月话费已经缴完，没有欠费、没有合约捆绑。','shàng gè yuè huà fèi yǐ jīng jiǎo wán， méi yǒu qiàn fèi、 méi yǒu hé yuē kǔn bǎng。','Cước tháng trước em đóng hết rồi, không nợ cước, cũng không bị ràng buộc hợp đồng gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_04','V396','客服',4,'那现在就能当场注销，卡里剩余话费可以现金退还。','nà xiàn zài jiù néng dāng chǎng zhù xiāo， kǎ lǐ shèng yú huà fèi kě yǐ xiàn jīn tuì huán。','Vậy thì hủy sim ngay bây giờ được luôn, tiền cước còn dư trong thẻ có thể hoàn lại bằng tiền mặt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_05','V396','阮明',5,'注销之后，会不会收到后续短信或者扣费通知吧？','zhù xiāo zhī hòu， huì bú huì shōu dào hòu xù duǎn xìn huò zhě kòu fèi tōng zhī ba？','Sau khi hủy sim rồi, có còn nhận được tin nhắn hay thông báo trừ tiền gì nữa không anh?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_06','V396','客服',6,'不会，销户后号码直接回收，和你不再有关联。','bú huì， xiāo hù hòu hào mǎ zhí jiē huí shōu， hé nǐ bù zài yǒu guān lián。','Không đâu, sau khi hủy số điện thoại được thu hồi ngay, không còn liên quan gì đến em nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_07','V396','阮明',7,'那就麻烦你帮我办理注销业务了。','nà jiù má fán nǐ bāng wǒ bàn lǐ zhù xiāo yè wù le。','Vậy phiền anh làm thủ tục hủy sim giúp em nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT397','S119','Xin hoàn lại tiền đặt cọc phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V397','SIT397','P1','twist','ban_chinh_thuc',NULL,'学校各类押金退款均留存电子档案，票据丢失可凭本人有效证件核对记录办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_01','V397','阮明',1,'老师您好，我毕业离校，申请退还宿舍住宿押金。','lǎo shī nín hǎo， wǒ bì yè lí xiào， shēn qǐng tuì huán sù shè zhù sù yā jīn。','Chào thầy, em tốt nghiệp rời trường rồi, muốn xin hoàn lại tiền cọc ở ký túc xá ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_02','V397','财务老师',2,'带好退房回执和缴费票据，我登记后走退款流程哈。','dài hǎo tuì fáng huí zhí hé jiǎo fèi piào jù， wǒ dēng jì hòu zǒu tuì kuǎn liú chéng hā。','Em mang theo biên nhận trả phòng và hóa đơn đóng tiền, tôi ghi nhận xong sẽ làm thủ tục hoàn tiền nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_03','V397','阮明',3,'退房回执我带来了，但是押金票据不小心弄丢了嘛。','tuì fáng huí zhí wǒ dài lái le， dàn shì yā jīn piào jù bù xiǎo xīn nòng diū le ma。','Biên nhận trả phòng em mang theo rồi, nhưng hóa đơn tiền cọc em lỡ làm mất mất rồi ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_04','V397','财务老师',4,'没关系，系统有缴费记录，凭护照也能核对退款。','méi guān xì， xì tǒng yǒu jiǎo fèi jì lù， píng hù zhào yě néng hé duì tuì kuǎn。','Không sao, hệ thống có lưu lại thông tin đóng tiền, dùng hộ chiếu cũng đối chiếu để hoàn tiền được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_05','V397','阮明',5,'押金是原路退回银行卡，还是现场领取现金？','yā jīn shì yuán lù tuì huí yín háng kǎ， hái shì xiàn chǎng lǐng qǔ xiàn jīn？','Tiền cọc sẽ hoàn về đúng thẻ ngân hàng ban đầu, hay em nhận tiền mặt tại chỗ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_06','V397','财务老师',6,'统一银行卡转账，三个工作日内到账。','tǒng yī yín háng kǎ zhuǎn zhàng， sān gè gōng zuò rì nèi dào zhàng。','Đều chuyển khoản qua thẻ ngân hàng hết, trong vòng ba ngày làm việc sẽ vào tài khoản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_07','V397','阮明',7,'太感谢老师帮忙核对，省去我不少麻烦。','tài gǎn xiè lǎo shī bāng máng hé duì， shěng qù wǒ bù shǎo má fán。','Em cảm ơn thầy đã giúp đối chiếu, đỡ cho em bao nhiêu là phiền phức ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT398','S132','Làm thủ tục ra sân bay về nước',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V398','SIT398','P1','suon_se','ban_chinh_thuc',NULL,'国内国际航班充电宝只能随身携带，严禁放入托运行李，超规行李需要额外支付运费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_01','V398','阮明',1,'您好，我乘坐飞往越南的航班，办理行李托运和值机。','nín hǎo， wǒ chéng zuò fēi wǎng yuè nán de háng bān， bàn lǐ xíng lǐ tuō yùn hé zhí jī。','Chào chị, em bay chuyến đi Việt Nam, muốn làm thủ tục ký gửi hành lý và check-in ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_02','V398','工作人员',2,'出示你的护照和电子机票，行李不要超重哦。','chū shì nǐ de hù zhào hé diàn zi jī piào， xíng lǐ bú yào chāo zhòng ó。','Em đưa hộ chiếu và vé điện tử đây, hành lý đừng để quá cân nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_03','V398','阮明',3,'两件行李箱总重量二十公斤，符合免费托运标准呢。','liǎng jiàn xíng lǐ xiāng zǒng zhòng liàng èr shí gōng jīn， fú hé miǎn fèi tuō yùn biāo zhǔn ne。','Hai vali của em tổng cộng nặng hai mươi ký, đúng tiêu chuẩn ký gửi miễn phí rồi đó ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_04','V398','工作人员',4,'行李贴好标签，登机口在二楼，提前一小时等候登机。','xíng lǐ tiē hǎo biāo qiān， dēng jī kǒu zài èr lóu， tí qián yī xiǎo shí děng hòu dēng jī。','Hành lý đã dán nhãn xong, cổng lên máy bay ở tầng hai, ra sớm một tiếng để chờ lên máy bay nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_05','V398','阮明',5,'随身包里有电子产品，过安检需要单独拿出来对吧？','suí shēn bāo lǐ yǒu diàn zi chǎn pǐn， guò ān jiǎn xū yào dān dú ná chū lái duì ba？','Trong túi xách tay của em có đồ điện tử, qua an ninh phải lấy riêng ra đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_06','V398','工作人员',6,'没错，电脑、充电宝都要单独过机检查。','méi cuò， diàn nǎo、 chōng diàn bǎo dōu yào dān dú guò jī jiǎn chá。','Đúng rồi, laptop với sạc dự phòng đều phải để riêng qua máy soi kiểm tra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_07','V398','阮明',7,'清楚流程了，辛苦你指引我办理。','qīng chǔ liú chéng le， xīn kǔ nǐ zhǐ yǐn wǒ bàn lǐ。','Em hiểu quy trình rồi ạ, cảm ơn chị đã hướng dẫn em làm thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT399','S129','Xin giấy xác nhận đã hoàn thành khóa học',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V399','SIT399','P1','suon_se','ban_chinh_thuc',NULL,'海外院校会要求留学生提供课程完成证明，以此核实学生完整完成在校学习。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_01','V399','阮明',1,'老师，我回国升学需要课程完成证明，麻烦帮忙开具。','lǎo shī， wǒ huí guó shēng xué xū yào kè chéng wán chéng zhèng míng， má fán bāng máng kāi jù。','Thầy ơi, em về nước học tiếp cần giấy chứng nhận hoàn thành khóa học, phiền thầy cấp giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_02','V399','教务老师',2,'所有课程、论文全部合格，才能出具这份官方证明吧。','suǒ yǒu kè chéng、 lùn wén quán bù hé gé， cái néng chū jù zhè fèn guān fāng zhèng míng ba。','Tất cả các môn học, luận văn đều đạt hết thì mới cấp được giấy chứng nhận chính thức này nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_03','V399','阮明',3,'我的全部课程考核通过，论文也顺利答辩完成了呢。','wǒ de quán bù kè chéng kǎo hé tōng guò， lùn wén yě shùn lì dá biàn wán chéng le ne。','Tất cả các môn em đều đạt hết, luận văn cũng bảo vệ thành công rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_04','V399','教务老师',4,'我现在打印两份，加盖学院公章交给你带走。','wǒ xiàn zài dǎ yìn liǎng fèn， jiā gài xué yuàn gōng zhāng jiāo gěi nǐ dài zǒu。','Vậy giờ tôi in hai bản, đóng dấu của khoa rồi đưa em mang đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_05','V399','阮明',5,'证明上面会标注我的在校学习时长和专业信息吗？','zhèng míng shàng miàn huì biāo zhù wǒ de zài xiào xué xí shí cháng hé zhuān yè xìn xī ma？','Trên giấy chứng nhận có ghi rõ thời gian học và thông tin chuyên ngành của em không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_06','V399','教务老师',6,'全部信息完整标注，国外院校完全认可。','quán bù xìn xī wán zhěng biāo zhù， guó wài yuàn xiào wán quán rèn kě。','Ghi đầy đủ hết thông tin, trường nước ngoài công nhận hoàn toàn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_07','V399','阮明',7,'太感谢老师，这份证明对我的深造至关重要。','tài gǎn xiè lǎo shī， zhè fèn zhèng míng duì wǒ de shēn zào zhì guān zhòng yào。','Em cảm ơn thầy nhiều lắm, giấy chứng nhận này rất quan trọng với việc học tiếp của em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT400','S133','Nói lời chia tay và cảm ơn thầy cô, bạn bè',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V400','SIT400','P1','suon_se','ban_chinh_thuc',NULL,'学生毕业离校前主动和老师当面道别是尊师礼仪，中国人习惯祝福对方前路顺遂、常保持联络。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_01','V400','阮明',1,'李老师，我下周就要回国了，今天特地来和您道别。','lǐ lǎo shī， wǒ xià zhōu jiù yào huí guó le， jīn tiān tè dì lái hé nín dào bié。','Thầy Lý ơi, tuần sau em về nước rồi, hôm nay em đến đặc biệt để chào tạm biệt thầy ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_02','V400','李老师',2,'时间过得真快，这两年你的汉语进步特别明显啊。','shí jiān guò dé zhēn kuài， zhè liǎng nián nǐ de hàn yǔ jìn bù tè bié míng xiǎn a。','Thời gian trôi nhanh thật đấy, hai năm nay tiếng Trung của em tiến bộ rõ rệt luôn.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_03','V400','阮明',3,'多亏您一直耐心辅导我，我心里特别感激呢。','duō kuī nín yì zhí nài xīn fǔ dǎo wǒ， wǒ xīn lǐ tè bié gǎn jī ne。','Nhờ thầy kiên nhẫn kèm cặp em suốt mà, trong lòng em cảm kích lắm ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_04','V400','李老师',4,'以后回国也要坚持练习汉语，有空常联系吧。','yǐ hòu huí guó yě yào jiān chí liàn xí hàn yǔ， yǒu kòng cháng lián xì ba。','Về nước rồi cũng phải duy trì luyện tiếng Trung nhé, rảnh thì thường xuyên liên lạc nha.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_05','V400','阮明',5,'我回国会经常给您发消息，也会记得和同学们保持联络。','wǒ huí guó huì jīng cháng gěi nín fā xiāo xī， yě huì jì de hé tóng xué men bǎo chí lián luò。','Em về nước sẽ nhắn tin cho thầy thường xuyên, cũng sẽ nhớ giữ liên lạc với các bạn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_06','V400','李老师',6,'一路平安，祝你回国之后一切顺利。','yí lù píng ān， zhù nǐ huí guó zhī hòu yī qiè shùn lì。','Chúc em thượng lộ bình an, mong mọi thứ sau khi về nước đều suôn sẻ với em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_07','V400','阮明',7,'谢谢老师两年的照顾，我永远不会忘记这段时光。','xiè xiè lǎo shī liǎng nián de zhào gù， wǒ yǒng yuǎn bú huì wàng jì zhè duàn shí guāng。','Em cảm ơn thầy đã chăm sóc em suốt hai năm qua, em sẽ không bao giờ quên khoảng thời gian này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT501','SV1','入境30天内前往国际学院登记备案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V501','SIT501','P1','twist','ban_chinh_thuc',NULL,'外籍留学生入境后必须30日内完成校内住宿登记，超期会影响后续居留许可办理，甚至产生罚款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_01','V501','阮明',1,'老师您好，我上周刚从越南入境，过来做新生入境登记。','lǎo shī nín hǎo， wǒ shàng zhōu gāng cóng yuè nán rù jìng， guò lái zuò xīn shēng rù jìng dēng jì。','Chào cô/thầy, em vừa từ Việt Nam nhập cảnh tuần trước, em qua đây làm đăng ký nhập cảnh cho sinh viên mới ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_02','V501','老师',2,'先把你的护照、入境海关盖章页拿给我核对一下吧。','xiān bǎ nǐ de hù zhào、 rù jìng hǎi guān gài zhāng yè ná gěi wǒ hé duì yī xià ba。','Em đưa hộ chiếu và trang có đóng dấu hải quan nhập cảnh cho tôi kiểm tra nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_03','V501','阮明',3,'护照在这里，但是我没打印入境盖章页的复印件嘛。','hù zhào zài zhè lǐ， dàn shì wǒ méi dǎ yìn rù jìng gài zhāng yè de fù yìn jiàn ma。','Hộ chiếu đây ạ, nhưng em chưa in bản photo trang đóng dấu nhập cảnh mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_04','V501','老师',4,'登记系统需要留存纸质复印件，楼下打印店可以当场复印。','dēng jì xì tǒng xū yào liú cún zhǐ zhì fù yìn jiàn， lóu xià dǎ yìn diàn kě yǐ dāng chǎng fù yìn。','Hệ thống đăng ký cần lưu bản photo giấy, tiệm photo dưới lầu có thể photo ngay tại chỗ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_05','V501','阮明',5,'那我先下楼复印，回来还需要填写什么登记表格吗？','nà wǒ xiān xià lóu fù yìn， huí lái hái xū yào tián xiě shén me dēng jì biǎo gé ma？','Vậy em xuống photo trước, quay lại còn cần điền thêm mẫu đăng ký nào nữa không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_06','V501','老师',6,'要填入境信息登记表，写明抵达日期、居住宿舍房间号。','yào tián rù jìng xìn xī dēng jì biǎo， xiě míng dǐ dá rì qī、 jū zhù sù shě fáng jiān hào。','Cần điền tờ khai thông tin nhập cảnh, ghi rõ ngày đến và số phòng ký túc xá đang ở.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_07','V501','阮明',7,'登记完成后，才可以预约出入境办居留许可对吗？','dēng jì wán chéng hòu， cái kě yǐ yù yuē chū rù jìng bàn jū liú xǔ kě duì ma？','Đăng ký xong rồi mới được đặt lịch làm thẻ tạm trú ở phòng xuất nhập cảnh đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_08','V501','老师',8,'没错，未完成校内登记，出入境大厅不会受理签证申请。','méi cuò， wèi wán chéng xiào nèi dēng jì， chū rù jìng dà tīng bú huì shòu lǐ qiān zhèng shēn qǐng。','Đúng vậy, chưa hoàn tất đăng ký trong trường thì phòng xuất nhập cảnh sẽ không tiếp nhận hồ sơ xin visa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_09','V501','阮明',9,'好，我马上复印材料，十分钟回来办理登记。','hǎo， wǒ mǎ shàng fù yìn cái liào， shí fēn zhōng huí lái bàn lǐ dēng jì。','Dạ vâng, em đi photo tài liệu ngay, mười phút nữa quay lại làm đăng ký ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT502','SV1','提交护照、录取材料申请首次居留许可',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V502','SIT502','P1','suon_se','chinh_thuc',NULL,'首次学生居留许可全套材料缺一不可，缺少任意一项都会直接退回不予受理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_01','V502','阮明',1,'您好，我是新生留学生，来递交首次居留许可申请材料。','nín hǎo， wǒ shì xīn shēng liú xué shēng， lái dì jiāo shǒu cì jū liú xǔ kě shēn qǐng cái liào。','Xin chào, tôi là du học sinh mới, tôi đến nộp hồ sơ xin cấp thẻ tạm trú lần đầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_02','V502','工作人员',2,'依次递交护照、录取通知书、体检报告、住宿登记单哦。','yī cì dì jiāo hù zhào、 lù qǔ tōng zhī shū、 tǐ jiǎn bào gào、 zhù sù dēng jì dān ó。','Anh/chị nộp lần lượt hộ chiếu, giấy báo nhập học, giấy khám sức khỏe và phiếu đăng ký lưu trú nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_03','V502','阮明',3,'全部材料都整理齐全，一式两份已经分好。','quán bù cái liào dōu zhěng lǐ qí quán， yī shì liǎng fèn yǐ jīng fēn hǎo。','Toàn bộ giấy tờ tôi đã sắp xếp đầy đủ, mỗi loại đã chia thành hai bản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_04','V502','工作人员',4,'我核对一遍，信息匹配无误，给你一张受理回执。','wǒ hé duì yī biàn， xìn xī pǐ pèi wú wù， gěi nǐ yī zhāng shòu lǐ huí zhí。','Tôi kiểm tra lại một lượt, thông tin khớp chính xác, đây là phiếu biên nhận cho anh/chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_05','V502','阮明',5,'大概几个工作日能拿到办好的居留贴纸呢？','dà gài jǐ gè gōng zuò rì néng ná dào bàn hǎo de jū liú tiē zhǐ ne？','Khoảng mấy ngày làm việc thì có thể nhận được tem tạm trú đã hoàn tất vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_06','V502','工作人员',6,'标准七个工作日，加急业务三个工作日办结。','biāo zhǔn qī gè gōng zuò rì， jiā jí yè wù sān gè gōng zuò rì bàn jié。','Trường hợp thông thường là bảy ngày làm việc, dịch vụ khẩn thì ba ngày làm việc là xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_07','V502','阮明',7,'取件可以凭回执代领，还是必须本人到场？','qǔ jiàn kě yǐ píng huí zhí dài lǐng， hái shì bì xū běn rén dào chǎng？','Khi nhận giấy tờ có thể nhờ người khác cầm biên nhận lấy hộ, hay bắt buộc phải đích thân đến?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_08','V502','工作人员',8,'本人携带回执、身份证（护照）才能领取证件。','běn rén xié dài huí zhí、 shēn fèn zhèng （hù zhào） cái néng lǐng qǔ zhèng jiàn。','Phải đích thân mang theo biên nhận và giấy tờ tùy thân (hộ chiếu) mới được nhận giấy tờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_09','V502','阮明',9,'清楚了，辛苦您受理我的签证材料！','qīng chǔ le， xīn kǔ nín shòu lǐ wǒ de qiān zhèng cái liào！','Rõ rồi ạ, cảm ơn anh/chị đã tiếp nhận hồ sơ visa của tôi, vất vả cho anh/chị rồi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT503','SV1','体检不合格，需要重新预约出入境体检',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V503','SIT503','P1','that_bai_nhe','ban_chinh_thuc',NULL,'留学生签证专用体检必须在出入境指定医院完成，体检不合格无法提交居留申请，复查需全额自费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_01','V503','阮明',1,'医生，我昨天拿到出入境体检报告，被告知体检不合格。','yī shēng， wǒ zuó tiān ná dào chū rù jìng tǐ jiǎn bào gào， bèi gào zhī tǐ jiǎn bù hé gé。','Bác sĩ ơi, hôm qua em nhận kết quả khám sức khỏe xuất nhập cảnh, bị báo là không đạt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_02','V503','校医',2,'我看看报告，是肝功能指标临时偏高，无法提交签证使用。','wǒ kàn kàn bào gào， shì gān gōng néng zhǐ biāo lín shí piān gāo， wú fǎ tí jiāo qiān zhèng shǐ yòng。','Để tôi xem lại kết quả, chỉ số chức năng gan đang tạm thời cao hơn bình thường nên không thể dùng nộp visa được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_03','V503','阮明',3,'那这种情况只能重新全套体检吗，没有补救办法？','nà zhè zhǒng qíng kuàng zhǐ néng chóng xīn quán tào tǐ jiǎn ma， méi yǒu bǔ jiù bàn fǎ？','Vậy trường hợp này chỉ có cách khám lại toàn bộ thôi ạ, không còn cách khắc phục nào khác sao?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_04','V503','校医',4,'需要间隔一周清淡饮食后重新预约，只复查异常项目不行嘛。','xū yào jiàn gé yī zhōu qīng dàn yǐn shí hòu chóng xīn yù yuē， zhǐ fù chá yì cháng xiàng mù bù xíng ma。','Cần cách ra một tuần ăn uống thanh đạm rồi đặt lịch khám lại, chỉ kiểm tra riêng mục bất thường thôi thì không được đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_05','V503','阮明',5,'重新体检还要再交一次全套体检费用对吧？','chóng xīn tǐ jiǎn hái yào zài jiāo yī cì quán tào tǐ jiǎn fèi yòng duì ba？','Khám lại thì lại phải đóng toàn bộ phí khám sức khỏe một lần nữa đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_06','V503','校医',6,'是的，出入境指定体检中心复查需要全额重新缴费。','shì de， chū rù jìng zhǐ dìng tǐ jiǎn zhōng xīn fù chá xū yào quán é chóng xīn jiǎo fèi。','Đúng vậy, khám lại ở trung tâm khám sức khỏe chỉ định của xuất nhập cảnh thì phải đóng đầy đủ lệ phí lần nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_07','V503','阮明',7,'一周后直接线上预约体检中心就能重新检测吗？','yī zhōu hòu zhí jiē xiàn shàng yù yuē tǐ jiǎn zhōng xīn jiù néng chóng xīn jiǎn cè ma？','Một tuần sau em chỉ cần đặt lịch online với trung tâm khám sức khỏe là có thể khám lại được luôn phải không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_08','V503','校医',8,'线上预约后带旧报告，方便医生对比两次检测数据。','xiàn shàng yù yuē hòu dài jiù bào gào， fāng biàn yī shēng duì bǐ liǎng cì jiǎn cè shù jù。','Đặt lịch online xong thì mang theo kết quả cũ, để bác sĩ tiện so sánh số liệu hai lần khám.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_09','V503','阮明',9,'我记好时间调整作息，下周再来做全套体检。','wǒ jì hǎo shí jiān tiáo zhěng zuò xī， xià zhōu zài lái zuò quán tào tǐ jiǎn。','Em ghi nhớ thời gian để điều chỉnh sinh hoạt, tuần sau sẽ quay lại khám sức khỏe toàn diện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT504','SV1','忘记携带境外录取通知书原件，无法提交签证材料',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V504','SIT504','P1','that_bai_nhe','chinh_thuc',NULL,'出入境办理居留许可严格核验纸质原件，电子照片、复印件均不具备受理效力，必须线下现场核验。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_01','V504','阮明',1,'您好，我今天过来递交居留许可申请材料。','nín hǎo， wǒ jīn tiān guò lái dì jiāo jū liú xǔ kě shēn qǐng cái liào。','Xin chào, hôm nay tôi đến nộp hồ sơ xin cấp thẻ tạm trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_02','V504','工作人员',2,'麻烦出示境外院校发放的纸质录取通知书原件。','má fán chū shì jìng wài yuàn xiào fā fàng de zhǐ zhì lù qǔ tōng zhī shū yuán jiàn。','Phiền anh/chị xuất trình bản gốc giấy báo nhập học bằng giấy do trường nước ngoài cấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_03','V504','阮明',3,'糟糕，我只带了复印件，原件放在宿舍忘记带来了啊。','zāo gāo， wǒ zhǐ dài le fù yìn jiàn， yuán jiàn fàng zài sù shè wàng jì dài lái le a。','Chết rồi, tôi chỉ mang bản photo thôi, bản gốc để ở ký túc xá quên mang theo mất tiêu.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_04','V504','工作人员',4,'签证审核必须核验原件，复印件不能单独作为受理材料。','qiān zhèng shěn hé bì xū hé yàn yuán jiàn， fù yìn jiàn bù néng dān dú zuò wéi shòu lǐ cái liào。','Việc xét duyệt visa bắt buộc phải kiểm tra bản gốc, bản photo không thể dùng riêng làm hồ sơ tiếp nhận được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_05','V504','阮明',5,'手机里存有原件高清照片，能不能先帮我受理后续补交？','shǒu jī lǐ cún yǒu yuán jiàn gāo qīng zhào piān， néng bù néng xiān bāng wǒ shòu lǐ hòu xù bǔ jiāo？','Trong điện thoại tôi có lưu ảnh chụp rõ nét bản gốc, anh/chị có thể tiếp nhận trước rồi cho tôi bổ sung sau được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_06','V504','工作人员',6,'系统硬性规定，材料不齐无法建档，只能改天带原件再来。','xì tǒng yìng xìng guī dìng， cái liào bù qí wú fǎ jiàn dàng， zhǐ néng gǎi tiān dài yuán jiàn zài lái。','Hệ thống quy định cứng, hồ sơ chưa đủ thì không thể lập hồ sơ, chỉ có thể hẹn hôm khác mang bản gốc đến lại thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_07','V504','阮明',7,'那我明天一早带齐全部原件再来窗口办理可以吗？','nà wǒ míng tiān yī zǎo dài qí quán bù yuán jiàn zài lái chuāng kǒu bàn lǐ kě yǐ ma？','Vậy sáng mai tôi mang đầy đủ tất cả bản gốc đến quầy làm lại được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_08','V504','工作人员',8,'明天正常上班，上午人少，建议早点过来排队。','míng tiān zhèng cháng shàng bān， shàng wǔ rén shǎo， jiàn yì zǎo diǎn guò lái pái duì。','Mai làm việc bình thường, buổi sáng ít người, anh/chị nên đến sớm để xếp hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_09','V504','阮明',9,'好的，实在抱歉漏带关键证件，耽误您工作了。','hǎo de， shí zài bào qiàn lòu dài guān jiàn zhèng jiàn， dān wù nín gōng zuò le。','Vâng, thật ngại quá vì tôi quên mang giấy tờ quan trọng, làm mất thời gian của anh/chị rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT505','SV1','咨询留学生居留许可有效时长与入境截止规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V505','SIT505','P1','suon_se','ban_chinh_thuc',NULL,'学生居留许可最长与学制同步，到期断签属于非法滞留，会产生罚款并影响后续再次来华签证。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_01','V505','阮明',1,'警官您好，想咨询留学生居留许可的有效期相关规定。','jǐng guān nín hǎo， xiǎng zī xún liú xué shēng jū liú xǔ kě de yǒu xiào qī xiāng guān guī dìng。','Chào anh, tôi muốn hỏi về quy định thời hạn hiệu lực của thẻ tạm trú dành cho du học sinh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_02','V505','辅警',2,'居留时长和你的学制匹配，本科一般一次发放一年哦。','jū liú shí cháng hé nǐ de xué zhì pǐ pèi， běn kē yì bān yī cì fā fàng yī nián ó。','Thời hạn tạm trú tương ứng với thời gian học của em, hệ đại học thường thì mỗi lần cấp một năm đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_03','V505','阮明',3,'如果寒暑假短期回国，在居留有效期内往返不受限制吧？','rú guǒ hán shǔ jià duǎn qī huí guó， zài jū liú yǒu xiào qī nèi wǎng fǎn bù shòu xiàn zhì ba？','Nếu nghỉ hè nghỉ đông về nước ngắn ngày, trong thời hạn tạm trú còn hiệu lực thì đi lại không bị hạn chế đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_04','V505','辅警',4,'有效期内多次出入境无需额外报备，超期滞留会有处罚。','yǒu xiào qī nèi duō cì chū rù jìng wú xū é wài bào bèi， chāo qī zhì liú huì yǒu chǔ fá。','Trong thời hạn hiệu lực xuất nhập cảnh nhiều lần không cần báo cáo thêm, nhưng ở quá hạn sẽ bị xử phạt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_05','V505','阮明',5,'居留证到期前最晚多久要提交续办申请呢？','jū liú zhèng dào qī qián zuì wǎn duō jiǔ yào tí jiāo xù bàn shēn qǐng ne？','Trước khi thẻ tạm trú hết hạn thì chậm nhất bao lâu phải nộp hồ sơ gia hạn ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_06','V505','辅警',6,'建议提前三十天递交，预留审核时间避免断签。','jiàn yì tí qián sān shí tiān dì jiāo， yù liú shěn hé shí jiān bì miǎn duàn qiān。','Nên nộp trước ba mươi ngày, để dành thời gian xét duyệt tránh bị gián đoạn visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_07','V505','阮明',7,'入境时签证上标注的最晚入境日期有什么约束？','rù jìng shí qiān zhèng shàng biāo zhù de zuì wǎn rù jìng rì qī yǒu shén me yuē shù？','Ngày nhập cảnh muộn nhất ghi trên visa khi nhập cảnh có ràng buộc gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_08','V505','辅警',8,'必须在标注日期前入境，逾期签证直接作废失效。','bì xū zài biāo zhù rì qī qián rù jìng， yú qī qiān zhèng zhí jiē zuò fèi shī xiào。','Bắt buộc phải nhập cảnh trước ngày ghi trên đó, visa quá hạn sẽ trực tiếp bị hủy và mất hiệu lực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_09','V505','阮明',9,'全部规则我记清楚了，非常感谢您细致讲解！','quán bù guī zé wǒ jì qīng chǔ le， fēi cháng gǎn xiè nín xì zhì jiǎng jiě！','Toàn bộ quy định em đã nắm rõ rồi, cảm ơn anh đã giải thích tận tình!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT506','SV1','学校统一代办居留签证，补交缺失的白底证件照',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V506','SIT506','P1','twist','tuy_y',NULL,'出入境签证证件照有统一尺寸、底色标准，照相馆会区分普通证件照与涉外签证专用照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_01','V506','老师',1,'阮明，学校统一代办居留签证，还差你的证件照没交。','ruǎn míng， xué xiào tǒng yí dài bàn jū liú qiān zhèng， hái chà nǐ de zhèng jiàn zhào méi jiāo。','Nguyễn Minh ơi, trường đang làm thủ tục visa tạm trú chung, còn thiếu ảnh thẻ của em chưa nộp đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_02','V506','阮明',2,'我上周交过一版照片，是尺寸不符合要求嘛？','wǒ shàng zhōu jiāo guò yī bǎn zhào piān， shì chǐ cùn bù fú hé yāo qiú ma？','Tuần trước em nộp một tấm ảnh rồi mà, hay là kích thước không đúng yêu cầu ạ?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_03','V506','老师',3,'普通生活照不行，必须小二寸白底免冠证件照哈。','pǔ tōng shēng huó zhào bù xíng， bì xū xiǎo èr cùn bái dǐ miǎn guān zhèng jiàn zhào hā。','Ảnh sinh hoạt bình thường không được đâu, phải là ảnh thẻ nền trắng không đội mũ cỡ 3x4 mới đúng nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_04','V506','阮明',4,'楼下照相馆能拍符合出入境标准的签证照片吗？','lóu xià zhào xiàng guǎn néng pāi fú hé chū rù jìng biāo zhǔn de qiān zhèng zhào piān ma？','Tiệm chụp ảnh dưới lầu có chụp được ảnh visa đúng chuẩn xuất nhập cảnh không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_05','V506','老师',5,'可以，直接跟摄影师说办居留许可用，他知道规格。','kě yǐ， zhí jiē gēn shè yǐng shī shuō bàn jū liú xǔ kě yòng， tā zhī dào guī gé。','Được đó, cứ nói thẳng với thợ chụp là chụp để làm thẻ tạm trú, họ biết quy cách rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_06','V506','阮明',6,'拍完下午送过来，还需要额外填写补充表格吗？','pāi wán xià wǔ sòng guò lái， hái xū yào é wài tián xiě bǔ chōng biǎo gé ma？','Chụp xong chiều nay em mang qua, còn cần điền thêm tờ khai bổ sung gì nữa không thầy/cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_07','V506','老师',7,'只交纸质照片就行，其余信息系统里都有存档。','zhǐ jiāo zhǐ zhì zhào piān jiù xíng， qí yú xìn xī xì tǒng lǐ dōu yǒu cún dàng。','Chỉ cần nộp ảnh giấy thôi là được, thông tin còn lại hệ thống đều đã lưu sẵn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_08','V506','阮明',8,'好嘞，我现在下楼拍照，很快送过来给您。','hǎo lei， wǒ xiàn zài xià lóu pāi zhào， hěn kuài sòng guò lái gěi nín。','Dạ được, giờ em xuống lầu chụp ảnh liền, xong sẽ mang qua đưa thầy/cô ngay.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT507','SV1','入境停留超期，前往出入境大厅办理逾期说明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V507','SIT507','P1','twist','chinh_thuc',NULL,'外籍人员在华签证超期属于非法滞留，会根据超期天数罚款，多次逾期会被限制入境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_01','V507','阮明',1,'警官您好，我上次出境旅游延误返程，在境内停留超期五天。','jǐng guān nín hǎo， wǒ shàng cì chū jìng lǚ yóu yán wù fǎn chéng， zài jìng nèi tíng liú chāo qī wǔ tiān。','Chào anh, lần trước tôi đi du lịch nước ngoài bị trễ chuyến bay về nên đã ở quá hạn trong nước năm ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_02','V507','民警',2,'先说明超期原因，提供机票行程单、学校在读证明吧。','xiān shuō míng chāo qī yuán yīn， tí gōng jī piào xíng chéng dān、 xué xiào zài dú zhèng míng ba。','Trước hết anh trình bày lý do quá hạn, cung cấp lịch trình vé máy bay và giấy xác nhận đang học tại trường nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_03','V507','阮明',3,'航班大面积延误导致无法按时离境，机票行程单在这里。','háng bān dà miàn jī yán wù dǎo zhì wú fǎ àn shí lí jìng， jī piào xíng chéng dān zài zhè lǐ。','Chuyến bay bị delay trên diện rộng khiến tôi không thể rời đi đúng hạn, lịch trình vé máy bay đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_04','V507','民警',4,'短期超期十五天内可书面说明，超过十五天处罚会加重嘛。','duǎn qī chāo qī shí wǔ tiān nèi kě shū miàn shuō míng， chāo guò shí wǔ tiān chǔ fá huì jiā zhòng ma。','Quá hạn ngắn trong vòng mười lăm ngày thì có thể làm bản tường trình bằng văn bản, quá mười lăm ngày thì mức xử phạt sẽ nặng hơn đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_05','V507','阮明',5,'本次超期会留下不良记录，影响下次续签居留吗？','běn cì chāo qī huì liú xià bù liáng jì lù， yǐng xiǎng xià cì xù qiān jū liú ma？','Lần quá hạn này có để lại tiền sử xấu, ảnh hưởng đến việc gia hạn tạm trú lần sau không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_06','V507','民警',6,'如实说明客观原因且首次违规，记录不会严重影响续签。','rú shí shuō míng kè guān yuán yīn qiě shǒu cì wéi guī， jì lù bú huì yán zhòng yǐng xiǎng xù qiān。','Nếu trình bày trung thực lý do khách quan và là vi phạm lần đầu thì hồ sơ sẽ không bị ảnh hưởng nghiêm trọng đến việc gia hạn sau này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_07','V507','阮明',7,'需要手写书面逾期情况说明，当场签字上交对吗？','xū yào shǒu xiě shū miàn yú qī qíng kuàng shuō míng， dāng chǎng qiān zì shàng jiāo duì ma？','Tôi cần viết tay bản tường trình về việc quá hạn, ký tên và nộp lại ngay tại chỗ đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_08','V507','民警',8,'没错，写完核对信息签字，再缴纳对应逾期罚款即可。','méi cuò， xiě wán hé duì xìn xī qiān zì， zài jiǎo nà duì yìng yú qī fá kuǎn jí kě。','Đúng vậy, viết xong kiểm tra lại thông tin rồi ký tên, sau đó nộp khoản tiền phạt quá hạn tương ứng là xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_09','V507','阮明',9,'我马上书写说明，配合完成全部处理流程。','wǒ mǎ shàng shū xiě shuō míng， pèi hé wán chéng quán bù chǔ lǐ liú chéng。','Tôi viết bản tường trình ngay đây, sẽ phối hợp hoàn tất toàn bộ quy trình xử lý.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT508','SV1','咨询单人宿舍住宿登记如何录入居留系统',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V508','SIT508','P1','suon_se','tuy_y',NULL,'所有外籍居住人员必须完成住宿登记，校内宿舍由宿管开具登记证明，校外租房由房东陪同社区备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_01','V508','阮明',1,'阿姨，我住单人宿舍，住宿登记怎么录入签证系统呢？','ā yí， wǒ zhù dān rén sù shè， zhù sù dēng jì zěn me lù rù qiān zhèng xì tǒng ne？','Cô ơi, con ở ký túc xá một mình, vậy đăng ký lưu trú nhập vào hệ thống visa thế nào ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_02','V508','宿管阿姨',2,'我这边给你打印住宿登记单，盖宿舍楼公章就行啦。','wǒ zhè biān gěi nǐ dǎ yìn zhù sù dēng jì dān， gài sù shè lóu gōng zhāng jiù xíng la。','Để cô in phiếu đăng ký lưu trú cho con, đóng dấu của tòa ký túc xá là xong à.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_03','V508','阮明',3,'多人宿舍和单人宿舍的登记单据格式是一样的吗？','duō rén sù shè hé dān rén sù shè de dēng jì dān jù gé shì shì yī yàng de ma？','Mẫu đăng ký của phòng nhiều người và phòng một người có giống nhau không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_04','V508','宿管阿姨',4,'单据通用，只需要在房间人数一栏填写单人。','dān jù tōng yòng， zhǐ xū yào zài fáng jiān rén shù yī lán tián xiě dān rén。','Mẫu dùng chung thôi, chỉ cần ghi số người trong phòng là một người là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_05','V508','阮明',5,'拿到登记单直接带去出入境大厅递交签证材料？','ná dào dēng jì dān zhí jiē dài qù chū rù jìng dà tīng dì jiāo qiān zhèng cái liào？','Con cầm phiếu đăng ký này đi thẳng đến phòng xuất nhập cảnh để nộp hồ sơ visa luôn được không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_06','V508','宿管阿姨',6,'对，这份单据是证明你合法住宿的核心材料。','duì， zhè fèn dān jù shì zhèng míng nǐ hé fǎ zhù sù de hé xīn cái liào。','Được đó, tờ này là giấy tờ cốt lõi chứng minh con cư trú hợp pháp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_07','V508','阮明',7,'麻烦您打印一份给我，我下午就去办居留申请。','má fán nín dǎ yìn yī fèn gěi wǒ， wǒ xià wǔ jiù qù bàn jū liú shēn qǐng。','Phiền cô in giúp con một bản, chiều nay con đi làm thủ tục xin tạm trú luôn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT509','SV2','居留许可快到期，提前咨询续办流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V509','SIT509','P1','suon_se','ban_chinh_thuc',NULL,'居留续签不能使用过期住宿登记、旧流水，所有辅助材料要求近期开具，保证信息实时有效。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_01','V509','阮明',1,'老师，我的居留许可还有四十天到期，想咨询续签流程。','lǎo shī， wǒ de jū liú xǔ kě hái yǒu sì shí tiān dào qī， xiǎng zī xún xù qiān liú chéng。','Thầy ơi, thẻ tạm trú của em còn bốn mươi ngày nữa là hết hạn, em muốn hỏi về thủ tục gia hạn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_02','V509','老师',2,'第一步先开在校在读证明，再准备银行存款流水哦。','dì yī bù xiān kāi zài xiào zài dú zhèng míng， zài zhǔn bèi yín háng cún kuǎn liú shuǐ ó。','Bước đầu tiên là xin giấy xác nhận đang học tại trường, sau đó chuẩn bị sao kê tài khoản ngân hàng nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_03','V509','阮明',3,'存款流水有最低金额要求吗，需要存多久的记录？','cún kuǎn liú shuǐ yǒu zuì dī jīn é yāo qiú ma， xū yào cún duō jiǔ de jì lù？','Sao kê tài khoản có yêu cầu số dư tối thiểu không ạ, cần lưu trữ giao dịch trong bao lâu?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_04','V509','老师',4,'留学生建议提供至少一万元、连续三个月以上流水。','liú xué shēng jiàn yì tí gōng zhì shǎo yī wàn yuán、 lián xù sān gè yuè yǐ shàng liú shuǐ。','Du học sinh nên có tối thiểu mười nghìn tệ, sao kê liên tục từ ba tháng trở lên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_05','V509','阮明',5,'住宿登记单还要重新打印，上次办签证的旧单据能用吗？','zhù sù dēng jì dān hái yào chóng xīn dǎ yìn， shàng cì bàn qiān zhèng de jiù dān jù néng yòng ma？','Giấy đăng ký tạm trú cũng phải in lại, giấy tờ cũ dùng lúc xin visa lần trước có dùng lại được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_06','V509','老师',6,'续签需要近一个月内新开具的住宿登记证明，旧的失效。','xù qiān xū yào jìn yí gè yuè nèi xīn kāi jù de zhù sù dēng jì zhèng míng， jiù de shī xiào。','Gia hạn cần giấy đăng ký tạm trú mới cấp trong vòng một tháng gần đây, giấy cũ hết hiệu lực rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_07','V509','阮明',7,'材料备齐后，线上预约出入境办理号就可以递交？','cái liào bèi qí hòu， xiàn shàng yù yuē chū rù jìng bàn lǐ hào jiù kě yǐ dì jiāo？','Chuẩn bị đầy đủ giấy tờ xong, em đặt lịch hẹn online lấy số xuất nhập cảnh rồi nộp là được đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_08','V509','老师',8,'线上预约优先办理，无预约只能现场排队等候。','xiàn shàng yù yuē yōu xiān bàn lǐ， wú yù yuē zhǐ néng xiàn chǎng pái duì děng hòu。','Đặt lịch online sẽ được ưu tiên xử lý, không đặt trước thì chỉ có thể xếp hàng tại chỗ chờ thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_09','V509','阮明',9,'我会提前整理全部材料，避免临近到期手忙脚乱。','wǒ huì tí qián zhěng lǐ quán bù cái liào， bì miǎn lín jìn dào qī shǒu máng jiǎo luàn。','Em sẽ chuẩn bị đầy đủ giấy tờ từ trước, tránh để gần hết hạn mới cuống cuồng lo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT510','SV2','续签证时银行存款证明余额不足，需重新开流水',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V510','SIT510','P1','that_bai_nhe','chinh_thuc',NULL,'留学生续签居留许可有活期存款最低额度要求，出入境只认可活期账户流水，定期、理财不计入审核余额。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_01','V510','阮明',1,'您好，我递交居留续签材料，麻烦帮忙核对一下。','nín hǎo， wǒ dì jiāo jū liú xù qiān cái liào， má fán bāng máng hé duì yī xià。','Chào chị, tôi nộp hồ sơ gia hạn thẻ tạm trú, phiền chị kiểm tra giúp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_02','V510','工作人员',2,'这份银行流水月末余额不足一万元，达不到签证标准。','zhè fèn yín háng liú shuǐ yuè mò yú é bù zú yī wàn yuán， dá bú dào qiān zhèng biāo zhǔn。','Sao kê ngân hàng này số dư cuối tháng chưa đủ mười nghìn tệ, không đạt tiêu chuẩn xin visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_03','V510','阮明',3,'我卡里有定期存款，能不能把定期存单一起当作资产证明？','wǒ kǎ lǐ yǒu dìng qī cún kuǎn， néng bù néng bǎ dìng qī cún dān yì qǐ dàng zuò zī chǎn zhèng míng？','Tôi có khoản tiền gửi kỳ hạn trong thẻ, có thể dùng sổ tiết kiệm kỳ hạn làm chứng minh tài sản không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_04','V510','工作人员',4,'系统只认可活期流水实时余额，定期存单不能抵扣要求嘛。','xì tǒng zhǐ rèn kě huó qī liú shuǐ shí shí yú é， dìng qī cún dān bù néng dǐ kòu yāo qiú ma。','Hệ thống chỉ chấp nhận số dư thực tế trong tài khoản thanh toán, tiền gửi kỳ hạn không được tính vào yêu cầu đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_05','V510','阮明',5,'那我转入资金后，隔天再来打印新流水重新递交可以吗？','nà wǒ zhuǎn rù zī jīn hòu， gé tiān zài lái dǎ yìn xīn liú shuǐ chóng xīn dì jiāo kě yǐ ma？','Vậy sau khi tôi chuyển tiền vào, hôm sau quay lại in sao kê mới rồi nộp lại được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_06','V510','工作人员',6,'可以，资金到账次日打印流水，余额达标再重新取号办理。','kě yǐ， zī jīn dào zhàng cì rì dǎ yìn liú shuǐ， yú é dá biāo zài chóng xīn qǔ hào bàn lǐ。','Được, hôm sau khi tiền vào tài khoản thì in sao kê, nếu số dư đạt yêu cầu thì lấy số mới làm lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_07','V510','阮明',7,'今天先把其余材料带回，明天补足资金重新打印流水。','jīn tiān xiān bǎ qí yú cái liào dài huí， míng tiān bǔ zú zī jīn chóng xīn dǎ yìn liú shuǐ。','Hôm nay tôi mang các giấy tờ còn lại về trước, mai bổ sung đủ tiền rồi in sao kê lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_08','V510','工作人员',8,'记得流水打印当日不要大额转出资金。','jì de liú shuǐ dǎ yìn dāng rì bú yào dà é zhuǎn chū zī jīn。','Nhớ là hôm in sao kê thì đừng chuyển đi số tiền lớn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_09','V510','阮明',9,'明白了，感谢告知存款流水审核标准。','míng bái le， gǎn xiè gào zhī cún kuǎn liú shuǐ shěn hé biāo zhǔn。','Tôi hiểu rồi, cảm ơn chị đã cho biết tiêu chuẩn xét duyệt sao kê tài khoản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT511','SV2','在校出勤率不够，学校不给开具签证在读证明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V511','SIT511','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内高校对留学生出勤有硬性考核，出勤率不达标学校有权拒开在读证明，无法办理居留续签，严重者会要求限期离境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_01','V511','阮明',1,'辅导员您好，我需要在读证明办理居留续签，麻烦帮我开具。','fǔ dǎo yuán nín hǎo， wǒ xū yào zài dú zhèng míng bàn lǐ jū liú xù qiān， má fán bāng wǒ kāi jù。','Chào cô chủ nhiệm, em cần giấy xác nhận đang học để làm thủ tục gia hạn tạm trú, phiền cô cấp giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_02','V511','辅导员',2,'系统显示你本学期旷课次数超标，出勤率未达到学校标准。','xì tǒng xiǎn shì nǐ běn xué qī kuàng kè cì shù chāo biāo， chū qín lǜ wèi dá dào xué xiào biāo zhǔn。','Hệ thống hiển thị học kỳ này em nghỉ học vượt quá số buổi cho phép, tỷ lệ đi học chưa đạt chuẩn của trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_03','V511','阮明',3,'前段时间身体不舒服请假缺课，全部有医院病假单留存。','qián duàn shí jiān shēn tǐ bù shū fú qǐng jià quē kè， quán bù yǒu yī yuàn bìng jià dān liú cún。','Thời gian trước em bị ốm nên xin nghỉ, đều có giấy nghỉ ốm của bệnh viện lưu lại đầy đủ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_04','V511','辅导员',4,'病假需要提前报备学院，事后补交单据不计入合规请假记录嘛。','bìng jià xū yào tí qián bào bèi xué yuàn， shì hòu bǔ jiāo dān jù bù jì rù hé guī qǐng jià jì lù ma。','Nghỉ ốm phải báo trước với khoa, sau đó mới nộp giấy tờ bổ sung thì không được tính là nghỉ phép hợp lệ đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_05','V511','阮明',5,'那现在有什么办法可以补全出勤记录，拿到在读证明？','nà xiàn zài yǒu shén me bàn fǎ kě yǐ bǔ quán chū qín jì lù， ná dào zài dú zhèng míng？','Vậy bây giờ có cách nào để bổ sung đủ số buổi đi học, để lấy được giấy xác nhận không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_06','V511','辅导员',6,'接下来一个月全程不缺课，月末核查出勤后才能开具证明。','jiē xià lái yí gè yuè quán chéng bù quē kè， yuè mò hé chá chū qín hòu cái néng kāi jù zhèng míng。','Một tháng tới em không được nghỉ buổi nào, cuối tháng kiểm tra chuyên cần rồi mới cấp giấy xác nhận được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_07','V511','阮明',7,'我的签证马上到期，延迟开证明会导致签证断签啊。','wǒ de qiān zhèng mǎ shàng dào qī， yán chí kāi zhèng míng huì dǎo zhì qiān zhèng duàn qiān a。','Visa của em sắp hết hạn rồi, chậm cấp giấy xác nhận sẽ khiến em bị đứt hạn tạm trú mất ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_08','V511','辅导员',8,'我给你开临时情况说明，先去出入境申请短期缓冲受理。','wǒ gěi nǐ kāi lín shí qíng kuàng shuō míng， xiān qù chū rù jìng shēn qǐng duǎn qī huǎn chōng shòu lǐ。','Cô sẽ viết cho em giấy giải trình tình huống tạm thời, em cứ ra xuất nhập cảnh xin xử lý gia hạn ngắn hạn trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_09','V511','阮明',9,'太感谢您帮忙协调，我之后一定准时上课不缺勤。','tài gǎn xiè nín bāng máng xié tiáo， wǒ zhī hòu yí dìng zhǔn shí shàng kè bù quē qín。','Em cảm ơn cô rất nhiều đã giúp thu xếp, sau này em nhất định đi học đúng giờ, không nghỉ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT512','SV2','咨询寒暑假居留延期是否需要额外材料',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V512','SIT512','P1','suon_se','tuy_y',NULL,'留学生寒暑假留校，续签必须额外提交加盖学院公章的留校申请，证明假期在校学习安排。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_01','V512','阮明',1,'警官，寒暑假不回国，续居留和学期内续签材料一样吗？','jǐng guān， hán shǔ jià bù huí guó， xù jū liú hé xué qī nèi xù qiān cái liào yī yàng ma？','Chú công an ơi, dịp hè đông không về nước thì hồ sơ gia hạn tạm trú có giống lúc trong học kỳ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_02','V512','辅警',2,'大体材料相同，额外需要一份假期留校申请书哈。','dà tǐ cái liào xiāng tóng， é wài xū yào yī fèn jià qī liú xiào shēn qǐng shū hā。','Về cơ bản giấy tờ giống nhau, chỉ cần thêm một đơn xin ở lại trường trong kỳ nghỉ thôi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_03','V512','阮明',3,'留校申请书手写就可以，还是必须打印盖章？','liú xiào shēn qǐng shū shǒu xiě jiù kě yǐ， hái shì bì xū dǎ yìn gài zhāng？','Đơn xin ở lại trường viết tay được không hay bắt buộc phải in ra và đóng dấu ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_04','V512','辅警',4,'打印填写后学院国际处盖章，手写无公章无效。','dǎ yìn tián xiě hòu xué yuàn guó jì chù gài zhāng， shǒu xiě wú gōng zhāng wú xiào。','In ra điền xong rồi đưa phòng quốc tế của trường đóng dấu, viết tay không có dấu thì không có giá trị đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_05','V512','阮明',5,'假期留校居留有效期也是一年，还是只给到开学？','jià qī liú xiào jū liú yǒu xiào qī yě shì yī nián， hái shì zhǐ gěi dào kāi xué？','Tạm trú ở lại trường trong kỳ nghỉ cũng có hiệu lực một năm, hay chỉ đến lúc khai giảng thôi ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_06','V512','辅警',6,'统一按学制发放一年有效期，不受寒暑假限制。','tǒng yī àn xué zhì fā fàng yī nián yǒu xiào qī， bù shòu hán shǔ jià xiàn zhì。','Đều cấp thống nhất theo thời hạn khóa học là một năm, không bị giới hạn bởi kỳ nghỉ hè đông đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_07','V512','阮明',7,'清楚了，我回去打印申请书找老师盖章。','qīng chǔ le， wǒ huí qù dǎ yìn shēn qǐng shū zhǎo lǎo shī gài zhāng。','Em rõ rồi ạ, em về in đơn rồi nhờ thầy cô đóng dấu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT513','SV2','校外租房居住，房东不配合办理住宿登记单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V513','SIT513','P1','twist','ban_chinh_thuc',NULL,'出租房屋房东有法定义务配合外籍租客完成社区住宿备案，拒不配合社区可依法约谈整改。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_01','V513','阮明',1,'网格员您好，我在外租房办签证需要住宿登记，房东不肯配合。','wǎng gé yuán nín hǎo， wǒ zài wài zū fáng bàn qiān zhèng xū yào zhù sù dēng jì， fáng dōng bù kěn pèi hé。','Chào anh tổ trưởng dân phố, em thuê nhà ở ngoài để làm visa cần đăng ký tạm trú, nhưng chủ nhà không chịu hợp tác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_02','V513','网格员',2,'先跟我说一下房东拒绝配合的具体原因是什么呢？','xiān gēn wǒ shuō yī xià fáng dōng jù jué pèi hé de jù tǐ yuán yīn shì shén me ne？','Em nói cho anh biết cụ thể lý do chủ nhà từ chối hợp tác là gì đã nhé?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_03','V513','阮明',3,'房东说登记要上交房产证复印件，担心信息泄露不愿意提供。','fáng dōng shuō dēng jì yào shàng jiāo fáng chǎn zhèng fù yìn jiàn， dān xīn xìn xī xiè lòu bù yuàn yì tí gōng。','Chủ nhà bảo đăng ký phải nộp bản sao giấy chứng nhận nhà đất, sợ lộ thông tin nên không muốn cung cấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_04','V513','网格员',4,'外籍租客住宿备案是法定要求，房东有义务配合登记嘛。','wài jí zū kè zhù sù bèi àn shì fǎ dìng yāo qiú， fáng dōng yǒu yì wù pèi hé dēng jì ma。','Đăng ký tạm trú cho người nước ngoài thuê nhà là quy định pháp luật, chủ nhà có nghĩa vụ phải hợp tác đăng ký chứ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_05','V513','阮明',5,'如果房东始终拒绝到场备案，我还有别的办理渠道吗？','rú guǒ fáng dōng shǐ zhōng jù jué dào chǎng bèi àn， wǒ hái yǒu bié de bàn lǐ qú dào ma？','Nếu chủ nhà cứ nhất quyết không chịu đến làm đăng ký, thì em còn cách nào khác để làm thủ tục không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_06','V513','网格员',6,'我上门和房东沟通劝导，沟通无果会下发书面告知单。','wǒ shàng mén hé fáng dōng gōu tōng quàn dǎo， gōu tōng wú guǒ huì xià fā shū miàn gào zhī dān。','Anh sẽ đến gặp chủ nhà để trao đổi thuyết phục, nếu không được thì sẽ gửi văn bản thông báo chính thức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_07','V513','阮明',7,'今天您能联系房东上门办理，我现在在出租屋等候。','jīn tiān nín néng lián xì fáng dōng shàng mén bàn lǐ， wǒ xiàn zài zài chū zū wū děng hòu。','Hôm nay anh liên hệ được chủ nhà đến làm thủ tục không, giờ em đang ở nhà trọ chờ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_08','V513','网格员',8,'半小时内到房屋现场，携带备案表格、拍照留存房屋信息。','bàn xiǎo shí nèi dào fáng wū xiàn chǎng， xié dài bèi àn biǎo gé、 pāi zhào liú cún fáng wū xìn xī。','Trong nửa tiếng nữa anh sẽ có mặt tại nhà, mang theo biểu mẫu đăng ký, chụp ảnh lưu lại thông tin căn nhà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_09','V513','阮明',9,'麻烦您出面协调，没有登记单我没法续办居留签证。','má fán nín chū miàn xié tiáo， méi yǒu dēng jì dān wǒ méi fǎ xù bàn jū liú qiān zhèng。','Phiền anh ra mặt giúp em giải quyết, không có giấy đăng ký thì em không thể gia hạn visa được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT514','SV2','续居留预约号约满，咨询线下现场取号方案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V514','SIT514','P1','twist','tuy_y',NULL,'出入境线上预约号资源紧张，线下应急号数量有限，仅针对签证续签人群，新办居留不开放线下现场号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_01','V514','阮明',1,'你好，线上预约系统近七天的续签号全部约满了。','nǐ hǎo， xiàn shàng yù yuē xì tǒng jìn qī tiān de xù qiān hào quán bù yuē mǎn le。','Chào bạn, hệ thống đặt lịch online gia hạn trong bảy ngày tới đã hết số hết rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_02','V514','引导员',2,'线上号源每日定时发放抢号，线下保留少量应急现场号哦。','xiàn shàng hào yuán měi rì dìng shí fā fàng qiǎng hào， xiàn xià bǎo liú shǎo liàng yìng jí xiàn chǎng hào ó。','Số online mỗi ngày phát theo giờ cố định, phải canh giành, còn lại có một ít số ứng cứu tại chỗ nè.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_03','V514','阮明',3,'现场号几点开始发放，需要一早来排队等候吗？','xiàn chǎng hào jǐ diǎn kāi shǐ fā fàng， xū yào yī zǎo lái pái duì děng hòu ma？','Số tại chỗ phát lúc mấy giờ vậy, có phải đến xếp hàng từ sáng sớm không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_04','V514','引导员',4,'早上八点大厅开门发放当日现场号，发完即止不追加。','zǎo shàng bā diǎn dà tīng kāi mén fā fàng dāng rì xiàn chǎng hào， fā wán jí zhǐ bù zhuī jiā。','Tám giờ sáng sảnh mở cửa phát số tại chỗ trong ngày, phát hết là thôi không phát thêm đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_05','V514','阮明',5,'现场号只受理续签业务，首次办居留不能用现场号对吧？','xiàn chǎng hào zhǐ shòu lǐ xù qiān yè wù， shǒu cì bàn jū liú bù néng yòng xiàn chǎng hào duì ba？','Số tại chỗ chỉ nhận xử lý gia hạn thôi, làm tạm trú lần đầu không dùng số tại chỗ được đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_06','V514','引导员',6,'没错，首次居留只能线上预约，续签才有应急线下号。','méi cuò， shǒu cì jū liú zhǐ néng xiàn shàng yù yuē， xù qiān cái yǒu yìng jí xiàn xià hào。','Đúng rồi, làm tạm trú lần đầu chỉ được đặt online thôi, gia hạn mới có số tại chỗ để ứng cứu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_07','V514','阮明',7,'那我明天七点半过来排队抢当日现场办理号。','nà wǒ míng tiān qī diǎn bàn guò lái pái duì qiǎng dāng rì xiàn chǎng bàn lǐ hào。','Vậy để mai bảy giờ rưỡi mình qua xếp hàng giành số xử lý tại chỗ trong ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT515','SV2','签证办理期间护照上交，申请临时出行证明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V515','SIT515','P1','suon_se','chinh_thuc',NULL,'护照上交出入境办理签证期间，无法乘坐交通、入住酒店，必须申请临时出行证明作为替代身份证件。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_01','V515','阮明',1,'您好，我的护照上交办理居留续签，周末需要短途出行。','nín hǎo， wǒ de hù zhào shàng jiāo bàn lǐ jū liú xù qiān， zhōu mò xū yào duǎn tú chū xíng。','Chào anh, tôi đang nộp hộ chiếu để làm gia hạn tạm trú, nhưng cuối tuần cần đi ra ngoài ngắn ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_02','V515','工作人员',2,'可以申请《外国人临时出行证明》，有效期七天呢。','kě yǐ shēn qǐng 《 wài guó rén lín shí chū xíng zhèng míng 》， yǒu xiào qī qī tiān ne。','Anh có thể xin cấp "Giấy chứng nhận đi lại tạm thời cho người nước ngoài", có hiệu lực bảy ngày.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_03','V515','阮明',3,'办理临时出行证明需要额外提交什么纸质材料？','bàn lǐ lín shí chū xíng zhèng míng xū yào é wài tí jiāo shén me zhǐ zhì cái liào？','Làm giấy chứng nhận đi lại tạm thời cần nộp thêm giấy tờ gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_04','V515','工作人员',4,'递交一张白底证件照，填写出行目的地即可。','dì jiāo yī zhāng bái dǐ zhèng jiàn zhào， tián xiě chū xíng mù dì dì jí kě。','Nộp một tấm ảnh thẻ nền trắng, điền nơi đến là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_05','V515','阮明',5,'这份临时证明可以乘坐高铁、酒店入住正常使用吗？','zhè fèn lín shí zhèng míng kě yǐ chéng zuò gāo tiě、 jiǔ diàn rù zhù zhèng cháng shǐ yòng ma？','Giấy chứng nhận tạm thời này có dùng để đi tàu cao tốc, nhận phòng khách sạn bình thường được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_06','V515','工作人员',6,'国内交通、住宿全部通用，等同于临时身份证件。','guó nèi jiāo tōng、 zhù sù quán bù tōng yòng， děng tóng yú lín shí shēn fèn zhèng jiàn。','Giao thông, lưu trú trong nước đều dùng được hết, coi như giấy tờ tùy thân tạm thời vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_07','V515','阮明',7,'等下取办好的居留贴纸时，要同步归还临时证明吧？','děng xià qǔ bàn hǎo de jū liú tiē zhǐ shí， yào tóng bù guī huán lín shí zhèng míng ba？','Lát nữa lấy thẻ tạm trú xong thì phải nộp lại giấy chứng nhận tạm thời cùng lúc đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_08','V515','工作人员',8,'是的，领取护照当日回收临时出行纸质证明。','shì de， lǐng qǔ hù zhào dāng rì huí shōu lín shí chū xíng zhǐ zhì zhèng míng。','Đúng vậy, hôm nhận lại hộ chiếu là phải thu hồi giấy chứng nhận đi lại tạm thời luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_09','V515','阮明',9,'麻烦帮我同步办理，周末出行不用滞留市内了。','má fán bāng wǒ tóng bù bàn lǐ， zhōu mò chū xíng bù yòng zhì liú shì nèi le。','Phiền anh làm giúp tôi luôn thể, để cuối tuần đi chơi khỏi phải ở lì trong thành phố nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT516','SV2','中途休学，咨询居留签证暂停与恢复手续',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V516','SIT516','P1','twist','chinh_thuc',NULL,'留学生休学、退学导致学籍失效，学生居留许可自动失效，需在规定缓冲期内离境，滞留会产生行政处罚。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_01','V516','阮明',1,'老师，我身体原因申请休学半年，想了解居留签证处理方式。','lǎo shī， wǒ shēn tǐ yuán yīn shēn qǐng xiū xué bàn nián， xiǎng liǎo jiě jū liú qiān zhèng chǔ lǐ fāng shì。','Thầy ơi, em xin nghỉ học nửa năm vì lý do sức khỏe, em muốn hỏi cách xử lý visa tạm trú thế nào ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_02','V516','老师',2,'休学期间学籍暂停，现有居留许可同步失效，需要限期离境。','xiū xué qī jiān xué jí zàn tíng， xiàn yǒu jū liú xǔ kě tóng bù shī xiào， xū yào xiàn qī lí jìng。','Trong thời gian nghỉ học thì tư cách học sinh bị tạm dừng, thẻ tạm trú hiện tại cũng mất hiệu lực theo, em phải xuất cảnh trong thời hạn quy định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_03','V516','阮明',3,'不能办理临时居留留在国内休养，必须返回越南吗？','bù néng bàn lǐ lín shí jū liú liú zài guó nèi xiū yǎng， bì xū fǎn huí yuè nán ma？','Không thể xin tạm trú tạm thời để ở lại trong nước dưỡng bệnh sao, bắt buộc phải về Việt Nam ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_04','V516','老师',4,'休学无有效在校学籍，不符合学生居留审批标准嘛。','xiū xué wú yǒu xiào zài xiào xué jí， bù fú hé xué shēng jū liú shěn pī biāo zhǔn ma。','Nghỉ học thì không còn tư cách học sinh hợp lệ tại trường, không đáp ứng tiêu chuẩn xét duyệt tạm trú cho học sinh đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_05','V516','阮明',5,'半年后复学返校，重新办居留要从头提交全套材料？','bàn nián hòu fù xué fǎn xiào， chóng xīn bàn jū liú yào cóng tóu tí jiāo quán tào cái liào？','Nửa năm sau quay lại học, làm tạm trú lại là phải nộp lại toàn bộ hồ sơ từ đầu ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_06','V516','老师',6,'复学后凭复学通知书，按新生流程重新申请居留许可。','fù xué hòu píng fù xué tōng zhī shū， àn xīn shēng liú chéng chóng xīn shēn qǐng jū liú xǔ kě。','Sau khi quay lại học thì cầm giấy thông báo phục học, làm theo quy trình như học sinh mới để xin cấp tạm trú lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_07','V516','阮明',7,'休学手续办完后，给我几天缓冲时间收拾行李离境？','xiū xué shǒu xù bàn wán hòu， gěi wǒ jǐ tiān huǎn chōng shí jiān shōu shí xíng lǐ lí jìng？','Sau khi làm xong thủ tục nghỉ học, thầy cho em mấy ngày để thu xếp hành lý rồi xuất cảnh ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_08','V516','老师',8,'休学备案当日起，给予三十天合法停留缓冲期。','xiū xué bèi àn dāng rì qǐ， jǐ yǔ sān shí tiān hé fǎ tíng liú huǎn chōng qī。','Từ ngày đăng ký nghỉ học, em được cho ba mươi ngày thời gian lưu trú hợp pháp để chuẩn bị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_09','V516','阮明',9,'我清楚规则了，会在缓冲期内安排回国休养。','wǒ qīng chǔ guī zé le， huì zài huǎn chōng qī nèi ān pái huí guó xiū yǎng。','Em rõ quy định rồi ạ, em sẽ sắp xếp về nước dưỡng bệnh trong thời gian đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT517','SV2','短期出境旅游，咨询居留证是否需要备案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V517','SIT517','P1','suon_se','tuy_y',NULL,'持有有效长期学生居留许可，短期出境旅游无需向出入境报备，仅毕业、休学、永久离境才需要注销备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_01','V517','阮明',1,'警官，我下周出境旅游，有效居留证需要提前备案吗？','jǐng guān， wǒ xià zhōu chū jìng lǚ yóu， yǒu xiào jū liú zhèng xū yào tí qián bèi àn ma？','Anh ơi, tuần sau em ra nước ngoài du lịch, thẻ tạm trú còn hạn thì có cần đăng ký trước không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_02','V517','辅警',2,'短期出国旅游不用线下备案，居留有效期内自由往返哈。','duǎn qī chū guó lǚ yóu bù yòng xiàn xià bèi àn， jū liú yǒu xiào qī nèi zì yóu wǎng fǎn hā。','Du lịch ngắn ngày ra nước ngoài thì không cần đăng ký trực tiếp đâu, còn hạn tạm trú là cứ tự do đi lại thôi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_03','V517','阮明',3,'出境的时候只需要同时出示护照和居留贴纸对吧？','chū jìng de shí hòu zhǐ xū yào tóng shí chū shì hù zhào hé jū liú tiē zhǐ duì ba？','Vậy lúc xuất cảnh chỉ cần xuất trình hộ chiếu với tem tạm trú cùng lúc là được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_04','V517','辅警',4,'对，两样证件一并交给海关查验即可。','duì， liǎng yàng zhèng jiàn yī bìng jiāo gěi hǎi guān chá yàn jí kě。','Đúng rồi, đưa cả hai giấy tờ cho hải quan kiểm tra là xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_05','V517','阮明',5,'如果出境超过一个月，回来签证会不会受影响？','rú guǒ chū jìng chāo guò yí gè yuè， huí lái qiān zhèng huì bú huì shòu yǐng xiǎng？','Nếu em đi quá một tháng thì lúc về visa có bị ảnh hưởng gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_06','V517','辅警',6,'只要居留没到期，无论出境时长都不影响入境。','zhǐ yào jū liú méi dào qī， wú lùn chū jìng shí cháng dōu bù yǐng xiǎng rù jìng。','Miễn là tạm trú chưa hết hạn thì đi bao lâu cũng không ảnh hưởng đến việc nhập cảnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_07','V517','阮明',7,'明白了，不用额外跑大厅办理出境报备。','míng bái le， bù yòng é wài pǎo dà tīng bàn lǐ chū jìng bào bèi。','Em hiểu rồi, vậy không cần chạy ra sảnh làm thủ tục báo xuất cảnh gì thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT518','SV3','护照丢失，派出所开遗失证明用于补办签证',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V518','SIT518','P1','suon_se','chinh_thuc',NULL,'外籍护照遗失必须先到派出所报案获取回执，无回执无法办理临时通行证明、新护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_01','V518','阮明',1,'警官您好，我的越南护照丢失，前来开具遗失报案回执。','jǐng guān nín hǎo， wǒ de yuè nán hù zhào diū shī， qián lái kāi jù yí shī bào àn huí zhí。','Chào anh, hộ chiếu Việt Nam của em bị mất, em đến xin biên nhận trình báo mất giấy tờ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_02','V518','民警',2,'详细说明丢失时间、路线、随身携带的全部物品吧。','xiáng xì shuō míng diū shī shí jiān、 lù xiàn、 suí shēn xié dài de quán bù wù pǐn ba。','Em nói rõ thời gian mất, lộ trình đi lại, và tất cả những gì mang theo người nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_03','V518','阮明',3,'昨天下午商圈逛街，结账后口袋内护照连同钱包一同遗失。','zuó tiān xià wǔ shāng quān guàng jiē， jié zhàng hòu kǒu dài nèi hù zhào lián tóng qián bāo yī tóng yí shī。','Chiều hôm qua em đi mua sắm ở khu trung tâm thương mại, sau khi thanh toán thì hộ chiếu với ví trong túi bị mất luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_04','V518','民警',4,'我制作遗失笔录，签字后打印两份报案回执给你留存。','wǒ zhì zuò yí shī bǐ lù， qiān zì hòu dǎ yìn liǎng fèn bào àn huí zhí gěi nǐ liú cún。','Tôi lập biên bản mất giấy tờ, sau khi em ký thì tôi in hai bản biên nhận cho em giữ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_05','V518','阮明',5,'一份回执去出入境办临时通行，一份去大使馆补办护照对吗？','yī fèn huí zhí qù chū rù jìng bàn lín shí tōng xíng， yī fèn qù dà shǐ guǎn bǔ bàn hù zhào duì ma？','Một bản để em đi làm giấy thông hành tạm ở phòng xuất nhập cảnh, một bản đem đến đại sứ quán làm lại hộ chiếu, đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_06','V518','民警',6,'两份回执用途分开，务必妥善保管不能丢失。','liǎng fèn huí zhí yòng tú fēn kāi， wù bì tuǒ shàn bǎo guǎn bù néng diū shī。','Hai bản dùng cho hai mục đích khác nhau, em nhớ giữ cẩn thận, đừng để mất nữa nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_07','V518','阮明',7,'没有这份报案回执，无法办理任何补办证件手续吧？','méi yǒu zhè fèn bào àn huí zhí， wú fǎ bàn lǐ rèn hé bǔ bàn zhèng jiàn shǒu xù ba？','Nếu không có biên nhận này thì không thể làm bất cứ thủ tục cấp lại giấy tờ nào đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_08','V518','民警',8,'没错，使馆与出入境均强制要求派出所遗失证明。','méi cuò， shǐ guǎn yǔ chū rù jìng jūn qiáng zhì yāo qiú pài chū suǒ yí shī zhèng míng。','Đúng vậy, cả đại sứ quán lẫn phòng xuất nhập cảnh đều bắt buộc phải có giấy xác nhận mất của công an.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_09','V518','阮明',9,'辛苦您登记备案，证件丢失给大家添麻烦了。','xīn kǔ nín dēng jì bèi àn， zhèng jiàn diū shī gěi dà jiā tiān má fán le。','Cảm ơn anh đã ghi nhận giúp em, mất giấy tờ làm phiền mọi người quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT519','SV3','居留许可贴纸损毁模糊，申请换发居留贴纸',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V519','SIT519','P1','twist','ban_chinh_thuc',NULL,'居留贴纸磨损、撕毁、信息模糊属于证件损毁，必须换发，旧照片超出半年有效期不能用于新证件办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_01','V519','阮明',1,'您好，我护照上的居留贴纸磨损掉色，信息看不清了。','nín hǎo， wǒ hù zhào shàng de jū liú tiē zhǐ mó sǔn diào sè， xìn xī kàn bù qīng le。','Chào anh, tem tạm trú trên hộ chiếu của em bị mờ, phai màu, không nhìn rõ thông tin nữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_02','V519','工作人员',2,'贴纸损毁需要换发居留许可，先提交白底证件照哦。','tiē zhǐ sǔn huǐ xū yào huàn fā jū liú xǔ kě， xiān tí jiāo bái dǐ zhèng jiàn zhào ó。','Tem hỏng thì phải làm lại tem tạm trú, trước tiên nộp ảnh thẻ nền trắng nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_03','V519','阮明',3,'上次办签证的旧照片还有剩余，直接用旧照片可以吗？','shàng cì bàn qiān zhèng de jiù zhào piān hái yǒu shèng yú， zhí jiē yòng jiù zhào piān kě yǐ ma？','Ảnh cũ từ lần làm visa trước em còn dư, dùng ảnh cũ luôn được không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_04','V519','工作人员',4,'换发证件要求近六个月内新拍摄照片，旧照不予受理嘛。','huàn fā zhèng jiàn yāo qiú jìn liù gè yuè nèi xīn pāi shè zhào piān， jiù zhào bù yǔ shòu lǐ ma。','Làm lại giấy tờ yêu cầu ảnh chụp mới trong vòng sáu tháng gần đây, ảnh cũ không được chấp nhận đâu nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_05','V519','阮明',5,'楼下大厅自助拍照机可以当场拍摄签证专用照片吗？','lóu xià dà tīng zì zhù pāi zhào jī kě yǐ dāng chǎng pāi shè qiān zhèng zhuān yòng zhào piān ma？','Máy chụp ảnh tự động dưới sảnh có chụp được ảnh chuyên dùng cho visa luôn tại chỗ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_06','V519','工作人员',6,'可以，拍完直接带纸质照片回来取号办理换发。','kě yǐ， pāi wán zhí jiē dài zhǐ zhì zhào piān huí lái qǔ hào bàn lǐ huàn fā。','Được, chụp xong thì mang ảnh giấy quay lại đây lấy số làm thủ tục cấp lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_07','V519','阮明',7,'换发期间护照需要上交，还是可以自行保管？','huàn fā qī jiān hù zhào xū yào shàng jiāo， hái shì kě yǐ zì xíng bǎo guǎn？','Trong lúc làm lại thì hộ chiếu phải nộp lại hay em tự giữ được ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_08','V519','工作人员',8,'全程留存护照七个工作日，如需出行办临时证明。','quán chéng liú cún hù zhào qī gè gōng zuò rì， rú xū chū xíng bàn lín shí zhèng míng。','Hộ chiếu sẽ được giữ lại suốt bảy ngày làm việc, nếu cần đi đâu thì làm giấy xác nhận tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_09','V519','阮明',9,'我现在去拍照，回来递交换发居留贴纸的材料。','wǒ xiàn zài qù pāi zhào， huí lái dì jiāo huàn fā jū liú tiē zhǐ de cái liào。','Vậy giờ em đi chụp ảnh, xong quay lại nộp hồ sơ đổi tem tạm trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT520','SV3','护照补办完成后，重新补办在华居留许可',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V520','SIT520','P1','suon_se','chinh_thuc',NULL,'补办护照后不能直接沿用旧居留，必须同步补办居留贴纸，新旧护照搭配使用仅短期有效，长期必须换发居留。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_01','V520','阮明',1,'您好，我的新护照已经从使馆取回，补办丢失的居留许可。','nín hǎo， wǒ de xīn hù zhào yǐ jīng cóng shǐ guǎn qǔ huí， bǔ bàn diū shī de jū liú xǔ kě。','Chào anh, hộ chiếu mới của em đã lấy từ đại sứ quán về rồi, giờ em xin làm lại thẻ tạm trú bị mất ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_02','V520','工作人员',2,'递交新护照、派出所遗失回执、在读证明、住宿登记单。','dì jiāo xīn hù zhào、 pài chū suǒ yí shī huí zhí、 zài dú zhèng míng、 zhù sù dēng jì dān。','Nộp hộ chiếu mới, biên nhận trình báo mất của công an, giấy xác nhận đang học, và phiếu đăng ký tạm trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_03','V520','阮明',3,'旧护照上过期的签证页复印件，也需要一并上交核对吗？','jiù hù zhào shàng guò qī de qiān zhèng yè fù yìn jiàn， yě xū yào yī bìng shàng jiāo hé duì ma？','Bản photo trang visa đã hết hạn trên hộ chiếu cũ có cần nộp kèm để đối chiếu không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_04','V520','工作人员',4,'是的，复印件留存系统，用于核对原有居留期限。','shì de， fù yìn jiàn liú cún xì tǒng， yòng yú hé duì yuán yǒu jū liú qī xiàn。','Có, bản photo sẽ được lưu vào hệ thống để đối chiếu thời hạn tạm trú trước đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_05','V520','阮明',5,'补办居留许可的办理时长和首次办理一样是七个工作日？','bǔ bàn jū liú xǔ kě de bàn lǐ shí cháng hé shǒu cì bàn lǐ yī yàng shì qī gè gōng zuò rì？','Thời gian làm lại thẻ tạm trú có giống lần đầu, là bảy ngày làm việc không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_06','V520','工作人员',6,'流程一致，加急通道三个工作日可取证。','liú chéng yí zhì， jiā jí tōng dào sān gè gōng zuò rì kě qǔ zhèng。','Quy trình giống nhau, nếu làm nhanh thì ba ngày làm việc là lấy được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_07','V520','阮明',7,'补办的居留有效期和原来丢失的证件剩余时长相同吧？','bǔ bàn de jū liú yǒu xiào qī hé yuán lái diū shī de zhèng jiàn shèng yú shí cháng xiāng tóng ba？','Hạn tạm trú làm lại có trùng với thời hạn còn lại của thẻ bị mất trước đây không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_08','V520','工作人员',8,'完全同步原有到期日期，不会重新计算一年有效期。','wán quán tóng bù yuán yǒu dào qī rì qī， bú huì chóng xīn jì suàn yī nián yǒu xiào qī。','Hoàn toàn giữ nguyên ngày hết hạn cũ, không tính lại thời hạn một năm mới đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_09','V520','阮明',9,'全部材料齐全，麻烦受理我的补办申请。','quán bù cái liào qí quán， má fán shòu lǐ wǒ de bǔ bàn shēn qǐng。','Hồ sơ em đã chuẩn bị đầy đủ, phiền anh tiếp nhận giúp em hồ sơ xin cấp lại ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT521','SV3','出境紧急情况无证件，申请出入境临时通行纸',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V521','SIT521','P1','twist','chinh_thuc',NULL,'临时出入境通行证明仅限单次出境，不可用于再次入境中国，回国后需在本国驻华使馆补办正式护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_01','V521','阮明',1,'警官，我明天一早航班回国，护照丢失急需临时通行证件。','jǐng guān， wǒ míng tiān yī zǎo háng bān huí guó， hù zhào diū shī jí xū lín shí tōng xíng zhèng jiàn。','Anh ơi, sáng mai em có chuyến bay về nước, hộ chiếu bị mất nên cần gấp giấy thông hành tạm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_02','V521','民警',2,'先出示派出所遗失回执，我核对你的全部备案信息。','xiān chū shì pài chū suǒ yí shī huí zhí， wǒ hé duì nǐ de quán bù bèi àn xìn xī。','Em xuất trình biên nhận trình báo mất trước đã, để tôi kiểm tra toàn bộ thông tin đăng ký của em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_03','V521','阮明',3,'回执随身携带，但是今天自助拍照机已经停止营业了嘛。','huí zhí suí shēn xié dài， dàn shì jīn tiān zì zhù pāi zhào jī yǐ jīng tíng zhǐ yíng yè le ma。','Biên nhận em mang theo người rồi, nhưng máy chụp ảnh tự động hôm nay đã đóng cửa mất rồi ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_04','V521','民警',4,'紧急出境可免纸质照片，系统调取之前留存的证件照片。','jǐn jí chū jìng kě miǎn zhǐ zhì zhào piān， xì tǒng diào qǔ zhī qián liú cún de zhèng jiàn zhào piān。','Xuất cảnh gấp thì có thể miễn ảnh giấy, hệ thống sẽ lấy lại ảnh giấy tờ đã lưu trước đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_05','V521','阮明',5,'这份临时通行纸只能用于本次出境，不能再次入境国内对吗？','zhè fèn lín shí tōng xíng zhǐ zhǐ néng yòng yú běn cì chū jìng， bù néng zài cì rù jìng guó nèi duì ma？','Giấy thông hành tạm này chỉ dùng để xuất cảnh lần này thôi, không thể dùng để nhập cảnh lại trong nước đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_06','V521','民警',6,'单次出境有效，抵达越南后前往使馆办理新护照。','dān cì chū jìng yǒu xiào， dǐ dá yuè nán hòu qián wǎng shǐ guǎn bàn lǐ xīn hù zhào。','Chỉ có giá trị một lần xuất cảnh thôi, khi về đến Việt Nam thì em ra đại sứ quán làm hộ chiếu mới nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_07','V521','阮明',7,'办理完成当场就能领取通行纸质证明，不用等候工作日？','bàn lǐ wán chéng dāng chǎng jiù néng lǐng qǔ tōng xíng zhǐ zhì zhèng míng， bù yòng děng hòu gōng zuò rì？','Làm xong là lấy được giấy thông hành ngay tại chỗ chứ không cần chờ ngày làm việc ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_08','V521','民警',8,'紧急出境业务当场办结，十分钟打印完成交付本人。','jǐn jí chū jìng yè wù dāng chǎng bàn jié， shí fēn zhōng dǎ yìn wán chéng jiāo fù běn rén。','Việc gấp thì xử lý xong ngay tại chỗ, mười phút là in xong giao tận tay cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_09','V521','阮明',9,'太感谢开通紧急通道，不然我明天无法搭乘航班。','tài gǎn xiè kāi tōng jǐn jí tōng dào， bù rán wǒ míng tiān wú fǎ dā chéng háng bān。','Cảm ơn anh nhiều vì đã mở đường xử lý gấp, không thì mai em không kịp chuyến bay mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT522','SV3','居留卡片丢失，线上挂失后线下补办',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V522','SIT522','P1','suon_se','tuy_y',NULL,'外国人居留卡丢失需线上立即挂失，挂失后原卡直接作废，无法恢复使用，只能线下重新制卡。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_01','V522','阮明',1,'你好，我的外国人居留卡片弄丢了，怎么挂失补办？','nǐ hǎo， wǒ de wài guó rén jū liú kǎ piàn nòng diū le， zěn me guà shī bǔ bàn？','Chào bạn, thẻ tạm trú người nước ngoài của mình bị mất rồi, làm sao để báo mất rồi xin cấp lại vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_02','V522','引导员',2,'先在出入境官方小程序线上挂失锁卡，防止他人冒用哦。','xiān zài chū rù jìng guān fāng xiǎo chéng xù xiàn shàng guà shī suǒ kǎ， fáng zhǐ tā rén mào yòng ó。','Đầu tiên bạn vào app xuất nhập cảnh chính thức báo mất và khóa thẻ online trước đã, để tránh người khác lợi dụng nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_03','V522','阮明',3,'线上挂失完成，再带什么材料线下补办实体卡片？','xiàn shàng guà shī wán chéng， zài dài shén me cái liào xiàn xià bǔ bàn shí tǐ kǎ piàn？','Báo mất online xong rồi, giờ cần mang thêm giấy tờ gì để làm lại thẻ cứng trực tiếp vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_04','V522','引导员',4,'白底证件照、护照、在读证明、住宿登记单四样材料。','bái dǐ zhèng jiàn zhào、 hù zhào、 zài dú zhèng míng、 zhù sù dēng jì dān sì yàng cái liào。','Bốn thứ nè, ảnh thẻ nền trắng, hộ chiếu, giấy xác nhận đang học, và phiếu đăng ký tạm trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_05','V522','阮明',5,'挂失之后如果捡到卡片，还能解除挂失继续使用吗？','guà shī zhī hòu rú guǒ jiǎn dào kǎ piàn， hái néng jiě chú guà shī jì xù shǐ yòng ma？','Sau khi báo mất mà lỡ tìm lại được thẻ thì có gỡ báo mất để dùng tiếp được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_06','V522','引导员',6,'挂失后卡片永久失效，无论找回都必须重新补办。','guà shī hòu kǎ piàn yǒng jiǔ shī xiào， wú lùn zhǎo huí dōu bì xū chóng xīn bǔ bàn。','Báo mất rồi là thẻ vô hiệu vĩnh viễn luôn, dù có tìm lại được cũng phải làm thẻ mới thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_07','V522','阮明',7,'挂失操作我现在手机完成，之后取号递交补办材料。','guà shī cāo zuò wǒ xiàn zài shǒu jī wán chéng， zhī hòu qǔ hào dì jiāo bǔ bàn cái liào。','Giờ mình làm thao tác báo mất trên điện thoại trước, xong rồi quay lại lấy số nộp hồ sơ làm lại nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT523','SV3','旧护照签证页剪角，咨询新旧护照联用规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V523','SIT523','P1','twist','ban_chinh_thuc',NULL,'旧护照到期剪角，居留贴纸短期可新旧护照联用，缓冲期三十天，超时无法正常出入境，必须转移居留许可至新护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_01','V523','阮明',1,'警官，我的旧护照到期剪角换新，居留贴纸还在旧护照上。','jǐng guān， wǒ de jiù hù zhào dào qī jiǎn jiǎo huàn xīn， jū liú tiē zhǐ hái zài jiù hù zhào shàng。','Anh ơi, hộ chiếu cũ của em hết hạn nên bị cắt góc đổi mới, nhưng tem tạm trú vẫn còn trên hộ chiếu cũ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_02','V523','辅警',2,'短期出入境可以新旧两本护照一并出示海关查验呢。','duǎn qī chū rù jìng kě yǐ xīn jiù liǎng běn hù zhào yī bìng chū shì hǎi guān chá yàn ne。','Xuất nhập cảnh ngắn hạn thì có thể xuất trình cả hai hộ chiếu cũ mới cho hải quan kiểm tra cùng lúc đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_03','V523','阮明',3,'新旧护照联用有时间限制，不能长期一直这样使用吗？','xīn jiù hù zhào lián yòng yǒu shí jiān xiàn zhì， bù néng cháng qī yì zhí zhè yàng shǐ yòng ma？','Việc dùng chung hai hộ chiếu có giới hạn thời gian không, chứ không thể dùng mãi như vậy được đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_04','V523','辅警',4,'联用仅允许三十天缓冲期，超期必须转移居留至新护照嘛。','lián yòng jǐn yǔn xǔ sān shí tiān huǎn chōng qī， chāo qī bì xū zhuǎn yí jū liú zhì xīn hù zhào ma。','Chỉ được dùng chung trong ba mươi ngày đệm thôi, quá hạn là bắt buộc phải chuyển tạm trú sang hộ chiếu mới đó nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_05','V523','阮明',5,'转移居留贴纸需要单独预约换发业务，还是续签同步办理？','zhuǎn yí jū liú tiē zhǐ xū yào dān dú yù yuē huàn fā yè wù， hái shì xù qiān tóng bù bàn lǐ？','Chuyển tem tạm trú thì cần đặt lịch riêng cho thủ tục cấp đổi, hay là làm luôn cùng lúc gia hạn visa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_06','V523','辅警',6,'单独预约居留信息变更业务，无需等到签证到期。','dān dú yù yuē jū liú xìn xī biàn gēng yè wù， wú xū děng dào qiān zhèng dào qī。','Đặt lịch riêng cho việc thay đổi thông tin tạm trú, không cần đợi đến khi visa hết hạn đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_07','V523','阮明',7,'那我三天内预约窗口，把居留贴纸转移到新护照上。','nà wǒ sān tiān nèi yù yuē chuāng kǒu， bǎ jū liú tiē zhǐ zhuǎn yí dào xīn hù zhào shàng。','Vậy trong ba ngày tới em sẽ đặt lịch, để chuyển tem tạm trú sang hộ chiếu mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT524','SV4','校内转专业，办理居留许可信息变更',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V524','SIT524','P1','suon_se','ban_chinh_thuc',NULL,'留学生校内转专业、更换学院，必须三十日内到出入境更新居留证件信息，信息不符会被判定证件失效。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_01','V524','阮明',1,'您好，我校内转换专业，来办理居留证件信息变更。','nín hǎo， wǒ xiào nèi zhuǎn huàn zhuān yè， lái bàn lǐ jū liú zhèng jiàn xìn xī biàn gēng。','Chào anh, em chuyển ngành học trong trường, đến đây làm thủ tục thay đổi thông tin trên thẻ tạm trú ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_02','V524','工作人员',2,'递交新专业录取调整证明、护照、白底证件照。','dì jiāo xīn zhuān yè lù qǔ tiáo zhěng zhèng míng、 hù zhào、 bái dǐ zhèng jiàn zhào。','Em nộp giấy xác nhận điều chỉnh chuyên ngành mới, hộ chiếu, và ảnh thẻ nền trắng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_03','V524','阮明',3,'只是专业变更，居留到期日会不会同步延后调整？','zhǐ shì zhuān yè biàn gēng， jū liú dào qī rì huì bú huì tóng bù yán hòu tiáo zhěng？','Chỉ đổi chuyên ngành thôi thì hạn tạm trú có bị lùi lại theo không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_04','V524','工作人员',4,'到期日期不变，仅更新证件上标注的就读专业。','dào qī rì qī bù biàn， jǐn gēng xīn zhèng jiàn shàng biāo zhù de jiù dú zhuān yè。','Ngày hết hạn không đổi đâu, chỉ cập nhật lại chuyên ngành đang học ghi trên thẻ thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_05','V524','阮明',5,'变更业务办理时长多久，当天可以取证吗？','biàn gēng yè wù bàn lǐ shí cháng duō jiǔ， dàng tiān kě yǐ qǔ zhèng ma？','Thủ tục thay đổi này mất bao lâu ạ, có lấy được ngay trong ngày không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_06','V524','工作人员',6,'三个工作日办结，不能当场领取变更后的居留卡。','sān gè gōng zuò rì bàn jié， bù néng dāng chǎng lǐng qǔ biàn gēng hòu de jū liú kǎ。','Ba ngày làm việc là xong, không lấy thẻ đã đổi ngay tại chỗ được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_07','V524','阮明',7,'信息变更不收取额外手续费，只需要提交材料对吧？','xìn xī biàn gēng bù shōu qǔ é wài shǒu xù fèi， zhǐ xū yào tí jiāo cái liào duì ba？','Thay đổi thông tin không thu thêm phí gì, chỉ cần nộp hồ sơ thôi đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_08','V524','工作人员',8,'校内专业变更属于免费业务，无任何工本费。','xiào nèi zhuān yè biàn gēng shǔ yú miǎn fèi yè wù， wú rèn hé gōng běn fèi。','Đổi chuyên ngành trong trường là dịch vụ miễn phí, không mất phí làm hồ sơ gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_09','V524','阮明',9,'材料全部备好，麻烦受理信息变更申请。','cái liào quán bù bèi hǎo， má fán shòu lǐ xìn xī biàn gēng shēn qǐng。','Hồ sơ em đã chuẩn bị đầy đủ hết rồi, phiền anh tiếp nhận giúp em đơn xin thay đổi thông tin ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT525','SV4','从A校转学至另一城市高校，办理居留迁出迁入',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V525','SIT525','P1','twist','chinh_thuc',NULL,'跨城市转学居留无法异地转移，原城市居留注销失效，抵达新城市三十日内必须重新申请本地学生居留许可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_01','V525','阮明',1,'老师，我转学去另一城市大学，咨询居留迁出流程。','lǎo shī， wǒ zhuǎn xué qù lìng yī chéng shì dà xué， zī xún jū liú qiān chū liú chéng。','Thầy ơi, em chuyển trường sang đại học ở thành phố khác, muốn hỏi về thủ tục chuyển đi cư trú ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_02','V525','老师',2,'先开具转学离校证明，再去本地出入境办理居留迁出备案。','xiān kāi jù zhuǎn xué lí xiào zhèng míng， zài qù běn dì chū rù jìng bàn lǐ jū liú qiān chū bèi àn。','Trước tiên em xin giấy xác nhận chuyển trường thôi học, sau đó đến xuất nhập cảnh địa phương làm thủ tục đăng ký chuyển đi cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_03','V525','阮明',3,'迁出备案完成，原有居留许可还能继续使用一段时间吗？','qiān chū bèi àn wán chéng， yuán yǒu jū liú xǔ kě hái néng jì xù shǐ yòng yī duàn shí jiān ma？','Sau khi làm xong thủ tục chuyển đi, giấy phép cư trú cũ có còn dùng được một thời gian nữa không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_04','V525','老师',4,'迁出当日原居留自动失效，抵达新城市必须三十日内重新办居留嘛。','qiān chū dāng rì yuán jū liú zì dòng shī xiào， dǐ dá xīn chéng shì bì xū sān shí rì nèi chóng xīn bàn jū liú ma。','Ngay ngày làm thủ tục chuyển đi thì cư trú cũ tự động hết hiệu lực, đến thành phố mới bắt buộc phải làm lại cư trú trong vòng ba mươi ngày đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_05','V525','阮明',5,'转学途中跨城市出行，没有有效居留可以凭转学证明通行？','zhuǎn xué tú zhōng kuà chéng shì chū xíng， méi yǒu yǒu xiào jū liú kě yǐ píng zhuǎn xué zhèng míng tōng xíng？','Trong lúc di chuyển giữa các thành phố để chuyển trường, không có cư trú hợp lệ thì có thể dùng giấy xác nhận chuyển trường để đi lại không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_06','V525','老师',6,'迁出时出入境会开具三十天过渡临时停留证明用于中转。','qiān chū shí chū rù jìng huì kāi jù sān shí tiān guò dù lín shí tíng liú zhèng míng yòng yú zhōng zhuǎn。','Lúc làm thủ tục chuyển đi, xuất nhập cảnh sẽ cấp giấy tạm trú quá cảnh ba mươi ngày để dùng cho việc di chuyển.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_07','V525','阮明',7,'新学校接收后，全套居留材料要重新提交一遍？','xīn xué xiào jiē shōu hòu， quán tào jū liú cái liào yào chóng xīn tí jiāo yī biàn？','Sau khi trường mới tiếp nhận, toàn bộ hồ sơ cư trú có phải nộp lại từ đầu không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_08','V525','老师',8,'全部材料重新递交，按新生标准办理当地居留许可。','quán bù cái liào chóng xīn dì jiāo， àn xīn shēng biāo zhǔn bàn lǐ dāng dì jū liú xǔ kě。','Nộp lại toàn bộ hồ sơ, làm thủ tục cư trú tại địa phương theo tiêu chuẩn sinh viên mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_09','V525','阮明',9,'我先办好离校转学证明，再去大厅做迁出备案。','wǒ xiān bàn hǎo lí xiào zhuǎn xué zhèng míng， zài qù dà tīng zuò qiān chū bèi àn。','Vậy em làm xong giấy xác nhận thôi học chuyển trường trước, rồi ra sảnh làm thủ tục đăng ký chuyển đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT526','SV4','更换校外租房地址，10日内办理居留地址变更',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V526','SIT526','P1','that_bai_nhe','tuy_y',NULL,'外籍人员更换居住地址法定十日内向社区更新住宿信息，多次逾期备案会影响后续居留续签审核。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_01','V526','阮明',1,'网格员，我刚换出租房，超过十天没办住宿变更登记。','wǎng gé yuán， wǒ gāng huàn chū zū fáng， chāo guò shí tiān méi bàn zhù sù biàn gēng dēng jì。','Anh tổ trưởng ơi, em vừa chuyển chỗ trọ, quá mười ngày rồi mà chưa đăng ký thay đổi chỗ ở.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_02','V526','网格员',2,'外籍人员换居住地址必须十日之内备案，逾期会有警告记录。','wài jí rén yuán huàn jū zhù dì zhǐ bì xū shí rì zhī nèi bèi àn， yú qī huì yǒu jǐng gào jì lù。','Người nước ngoài đổi địa chỉ cư trú bắt buộc phải đăng ký trong vòng mười ngày, quá hạn sẽ bị ghi cảnh cáo đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_03','V526','阮明',3,'我搬家后忙着上课完全忘记，现在补办还会罚款吗？','wǒ bān jiā hòu máng zhe shàng kè wán quán wàng jì， xiàn zài bǔ bàn hái huì fá kuǎn ma？','Em chuyển nhà xong bận đi học nên quên mất luôn, giờ làm bù có bị phạt tiền không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_04','V526','网格员',4,'首次轻微超期仅书面警告，多次超期才会产生行政处罚嘛。','shǒu cì qīng wēi chāo qī jǐn shū miàn jǐng gào， duō cì chāo qī cái huì chǎn shēng xíng zhèng chǔ fá ma。','Lần đầu trễ hạn nhẹ thì chỉ cảnh cáo bằng văn bản thôi, trễ nhiều lần mới bị xử phạt hành chính chứ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_05','V526','阮明',5,'补办地址变更需要房东带房产证一起来社区备案吗？','bǔ bàn dì zhǐ biàn gēng xū yào fáng dōng dài fáng chǎn zhèng yì qǐ lái shè qū bèi àn ma？','Làm bù thay đổi địa chỉ có cần chủ nhà mang giấy chứng nhận nhà đất đến khu phố cùng đăng ký không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_06','V526','网格员',6,'需要房东到场签字备案，同步打印新住宿登记单。','xū yào fáng dōng dào chǎng qiān zì bèi àn， tóng bù dǎ yìn xīn zhù sù dēng jì dān。','Cần chủ nhà có mặt ký tên đăng ký, đồng thời in phiếu đăng ký chỗ ở mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_07','V526','阮明',7,'我现在联系房东过来社区，立刻补办地址变更登记。','wǒ xiàn zài lián xì fáng dōng guò lái shè qū， lì kè bǔ bàn dì zhǐ biàn gēng dēng jì。','Vậy giờ em liên hệ chủ nhà đến khu phố ngay, làm bù đăng ký thay đổi địa chỉ liền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT527','SV4','护照个人信息更新，同步更新居留证件信息',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V527','SIT527','P1','suon_se','chinh_thuc',NULL,'护照姓名、国籍、证件编号等核心信息变动后，必须同步更新居留许可，证件信息不一致会被判定无效证件。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_01','V527','阮明',1,'您好，我的新护照姓名拼写更新，同步变更居留卡信息。','nín hǎo， wǒ de xīn hù zhào xìng míng pīn xiě gēng xīn， tóng bù biàn gēng jū liú kǎ xìn xī。','Chào chị, hộ chiếu mới của em cập nhật lại cách viết tên, em muốn đồng bộ cập nhật thông tin trên thẻ cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_02','V527','工作人员',2,'递交新护照、使馆出具的信息变更说明文件、证件照片。','dì jiāo xīn hù zhào、 shǐ guǎn chū jù de xìn xī biàn gēng shuō míng wén jiàn、 zhèng jiàn zhào piān。','Em nộp hộ chiếu mới, văn bản xác nhận thay đổi thông tin do đại sứ quán cấp, và ảnh thẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_03','V527','阮明',3,'居留卡信息变更完成，有效期延续原来的到期时间？','jū liú kǎ xìn xī biàn gēng wán chéng， yǒu xiào qī yán xù yuán lái de dào qī shí jiān？','Sau khi cập nhật xong thông tin thẻ cư trú, thời hạn có được giữ nguyên như trước không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_04','V527','工作人员',4,'有效期不变，仅更新证件上的姓名、护照编号信息。','yǒu xiào qī bù biàn， jǐn gēng xīn zhèng jiàn shàng de xìng míng、 hù zhào biān hào xìn xī。','Thời hạn không đổi, chỉ cập nhật lại tên và số hộ chiếu trên thẻ thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_05','V527','阮明',5,'变更完成后出入境、高铁酒店查验不会出现信息不符？','biàn gēng wán chéng hòu chū rù jìng、 gāo tiě jiǔ diàn chá yàn bú huì chū xiàn xìn xī bù fú？','Sau khi cập nhật xong, lúc kiểm tra ở xuất nhập cảnh hay khách sạn, tàu cao tốc sẽ không bị sai lệch thông tin chứ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_06','V527','工作人员',6,'系统实时同步更新，全国查验终端同步刷新信息。','xì tǒng shí shí tóng bù gēng xīn， quán guó chá yàn zhōng duān tóng bù shuā xīn xìn xī。','Hệ thống cập nhật đồng bộ theo thời gian thực, các thiết bị kiểm tra trên toàn quốc cũng sẽ tự động làm mới thông tin.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_07','V527','阮明',7,'全套材料整理完毕，麻烦受理信息变更业务。','quán tào cái liào zhěng lǐ wán bì， má fán shòu lǐ xìn xī biàn gēng yè wù。','Em chuẩn bị xong hết hồ sơ rồi, nhờ chị tiếp nhận xử lý thay đổi thông tin giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT528','SV5','咨询留学生合法校外实习签证备案流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V528','SIT528','P1','twist','ban_chinh_thuc',NULL,'外籍留学生无备案校外实习属于非法务工，一旦查实会行政处罚，严重者不予续签居留许可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_01','V528','阮明',1,'老师，我想找校外企业实习，咨询留学生务工备案流程。','lǎo shī， wǒ xiǎng zhǎo xiào wài qǐ yè shí xí， zī xún liú xué shēng wù gōng bèi àn liú chéng。','Thầy ơi, em muốn xin thực tập ở doanh nghiệp bên ngoài trường, hỏi thầy về thủ tục đăng ký làm thêm cho du học sinh với ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_02','V528','老师',2,'校外实习必须企业、学校、学生三方签订实习协议备案。','xiào wài shí xí bì xū qǐ yè、 xué xiào、 xué shēng sān fāng qiān dìng shí xí xié yì bèi àn。','Thực tập ngoài trường bắt buộc phải có doanh nghiệp, nhà trường và sinh viên ký thỏa thuận thực tập ba bên rồi đăng ký.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_03','V528','阮明',3,'不提前备案直接去实习，会不会影响我的居留续签呢？','bù tí qián bèi àn zhí jiē qù shí xí， huì bú huì yǐng xiǎng wǒ de jū liú xù qiān ne？','Nếu không đăng ký trước mà đi thực tập luôn, có ảnh hưởng đến việc gia hạn cư trú của em không thầy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_04','V528','老师',4,'无备案校外务工属于非法就业，查到会罚款并缩短居留期限嘛。','wú bèi àn xiào wài wù gōng shǔ yú fēi fǎ jiù yè， chá dào huì fá kuǎn bìng suō duǎn jū liú qī xiàn ma。','Làm việc ngoài trường mà không đăng ký thì coi như làm việc bất hợp pháp, bị phát hiện sẽ bị phạt tiền và rút ngắn thời hạn cư trú đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_05','V528','阮明',5,'实习备案每个学期只能办理一次，中途更换企业能重新备案吗？','shí xí bèi àn měi gè xué qī zhǐ néng bàn lǐ yī cì， zhōng tú gēng huàn qǐ yè néng chóng xīn bèi àn ma？','Mỗi học kỳ chỉ được đăng ký thực tập một lần thôi, giữa chừng đổi doanh nghiệp thì có đăng ký lại được không thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_06','V528','老师',6,'中途更换实习单位需要注销原有备案，重新提交三方协议。','zhōng tú gēng huàn shí xí dān wèi xū yào zhù xiāo yuán yǒu bèi àn， chóng xīn tí jiāo sān fāng xié yì。','Giữa chừng đổi nơi thực tập thì cần hủy đăng ký cũ, rồi nộp lại thỏa thuận ba bên mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_07','V528','阮明',7,'办理备案需要企业提供营业执照复印件加盖公章吧？','bàn lǐ bèi àn xū yào qǐ yè tí gōng yíng yè zhí zhào fù yìn jiàn jiā gài gōng zhāng ba？','Làm đăng ký thì cần doanh nghiệp cung cấp bản sao giấy phép kinh doanh có đóng dấu đúng không thầy?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_08','V528','老师',8,'没错，企业资质文件是实习备案必备核心材料。','méi cuò， qǐ yè zī zhì wén jiàn shì shí xí bèi àn bì bèi hé xīn cái liào。','Đúng vậy, giấy tờ chứng minh tư cách pháp nhân của doanh nghiệp là hồ sơ cốt lõi bắt buộc phải có.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_09','V528','阮明',9,'我先和实习企业沟通准备资质材料，再来办理备案。','wǒ xiān hé shí xí qǐ yè gōu tōng zhǔn bèi zī zhì cái liào， zài lái bàn lǐ bèi àn。','Vậy em trao đổi với doanh nghiệp thực tập để chuẩn bị giấy tờ trước, rồi quay lại làm đăng ký sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT529','SV5','办理留学生校内勤工助学务工备案证明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V529','SIT529','P1','suon_se','tuy_y',NULL,'留学生校内勤工助学同样有严格时长限制，校内备案仅学院留存，校外实习必须同步向出入境备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_01','V529','阮明',1,'老师，我申请校内图书馆助教兼职，需要办务工备案吗？','lǎo shī， wǒ shēn qǐng xiào nèi tú shū guǎn zhù jiào jiān zhí， xū yào bàn wù gōng bèi àn ma？','Thầy ơi, em xin làm trợ giảng bán thời gian ở thư viện trong trường, có cần đăng ký làm thêm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_02','V529','老师',2,'校内勤工助学也需要开具勤工助学备案单留存系统哦。','xiào nèi qín gōng zhù xué yě xū yào kāi jù qín gōng zhù xué bèi àn dān liú cún xì tǒng ó。','Làm thêm vừa học vừa làm trong trường cũng cần lập phiếu đăng ký lưu vào hệ thống đấy nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_03','V529','阮明',3,'校内兼职每周务工时长上限还是二十小时对吧？','xiào nèi jiān zhí měi zhōu wù gōng shí cháng shàng xiàn hái shì èr shí xiǎo shí duì ba？','Làm thêm trong trường thì giới hạn giờ làm mỗi tuần vẫn là hai mươi tiếng đúng không thầy?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_04','V529','老师',4,'学期内每周不超二十小时，寒暑假放宽至四十小时。','xué qī nèi měi zhōu bù chāo èr shí xiǎo shí， hán shǔ jià fàng kuān zhì sì shí xiǎo shí。','Trong học kỳ thì không quá hai mươi tiếng mỗi tuần, nghỉ hè nghỉ đông thì được nới lên bốn mươi tiếng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_05','V529','阮明',5,'这份备案单需要带去出入境更新居留证件信息？','zhè fèn bèi àn dān xū yào dài qù chū rù jìng gēng xīn jū liú zhèng jiàn xìn xī？','Phiếu đăng ký này có cần mang đến xuất nhập cảnh để cập nhật thông tin thẻ cư trú không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_06','V529','老师',6,'校内兼职无需去出入境，仅学院内部系统备案存档。','xiào nèi jiān zhí wú xū qù chū rù jìng， jǐn xué yuàn nèi bù xì tǒng bèi àn cún dàng。','Làm thêm trong trường không cần ra xuất nhập cảnh đâu, chỉ đăng ký lưu trữ trong hệ thống nội bộ của khoa thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_07','V529','阮明',7,'那我填好勤工助学申请表，麻烦老师盖章备案。','nà wǒ tián hǎo qín gōng zhù xué shēn qǐng biǎo， má fán lǎo shī gài zhāng bèi àn。','Vậy em điền xong đơn đăng ký làm thêm, nhờ thầy đóng dấu xác nhận giúp em nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT530','SV5','咨询逾期打工、超时务工对签证续签的影响',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V530','SIT530','P1','twist','chinh_thuc',NULL,'中国法律严格限制外籍留学生务工时长与务工范围，非法就业会直接影响居留续签，甚至限期离境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_01','V530','阮明',1,'警官，如果留学生超时打工或者无备案务工，续签居留会怎样？','jǐng guān， rú guǒ liú xué shēng chāo shí dǎ gōng huò zhě wú bèi àn wù gōng， xù qiān jū liú huì zěn yàng？','Chú công an ơi, nếu du học sinh làm thêm quá giờ hoặc làm việc không đăng ký, thì việc gia hạn cư trú sẽ bị ảnh hưởng thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_02','V530','辅警',2,'首次查实非法务工罚款，居留许可缩短有效期半年呢。','shǒu cì chá shí fēi fǎ wù gōng fá kuǎn， jū liú xǔ kě suō duǎn yǒu xiào qī bàn nián ne。','Lần đầu bị phát hiện làm việc bất hợp pháp thì phạt tiền, giấy phép cư trú bị rút ngắn thời hạn nửa năm đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_03','V530','阮明',3,'多次违规超时务工，会直接拒绝续签学生居留吗？','duō cì wéi guī chāo shí wù gōng， huì zhí jiē jù jué xù qiān xué shēng jū liú ma？','Nếu vi phạm làm thêm quá giờ nhiều lần, có bị từ chối thẳng việc gia hạn cư trú sinh viên không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_04','V530','辅警',4,'两次及以上非法务工记录，出入境直接驳回续签申请嘛。','liǎng cì jí yǐ shàng fēi fǎ wù gōng jì lù， chū rù jìng zhí jiē bó huí xù qiān shēn qǐng ma。','Từ hai lần vi phạm làm việc bất hợp pháp trở lên, xuất nhập cảnh sẽ trực tiếp bác đơn xin gia hạn luôn.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_05','V530','阮明',5,'寒暑假四十小时上限，如果超过时长也算违规务工？','hán shǔ jià sì shí xiǎo shí shàng xiàn， rú guǒ chāo guò shí cháng yě suàn wéi guī wù gōng？','Giới hạn bốn mươi tiếng vào kỳ nghỉ hè đông, nếu vượt quá thời gian đó cũng tính là làm việc vi phạm ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_06','V530','辅警',6,'无论学期还是假期，超出规定时长均判定非法就业。','wú lùn xué qī hái shì jià qī， chāo chū guī dìng shí cháng jūn pàn dìng fēi fǎ jiù yè。','Dù là trong học kỳ hay kỳ nghỉ, hễ vượt quá thời gian quy định đều bị coi là việc làm bất hợp pháp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_07','V530','阮明',7,'合法备案实习，更换单位忘记注销旧备案会有记录吗？','hé fǎ bèi àn shí xí， gēng huàn dān wèi wàng jì zhù xiāo jiù bèi àn huì yǒu jì lù ma？','Thực tập đã đăng ký hợp lệ, nhưng đổi công ty mà quên hủy đăng ký cũ thì có bị ghi nhận vi phạm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_08','V530','辅警',8,'旧备案未注销会判定多单位同时务工，同样违规。','jiù bèi àn wèi zhù xiāo huì pàn dìng duō dān wèi tóng shí wù gōng， tóng yàng wéi guī。','Đăng ký cũ chưa hủy sẽ bị coi là làm việc cùng lúc ở nhiều nơi, cũng tính là vi phạm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_09','V530','阮明',9,'我会严格遵守务工时长规定，提前办好全部实习备案。','wǒ huì yán gé zūn shǒu wù gōng shí cháng guī dìng， tí qián bàn hǎo quán bù shí xí bèi àn。','Em sẽ tuân thủ nghiêm quy định về giờ làm thêm, làm đầy đủ đăng ký thực tập từ trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT531','SV6','毕业申请短期停留签证（毕业生留华缓冲期）',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V531','SIT531','P1','suon_se','ban_chinh_thuc',NULL,'留学生毕业后可申请最长180天短期停留缓冲签证，该签证禁止任何形式务工、实习，到期必须离境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_01','V531','阮明',1,'您好，我顺利完成学业毕业，申请毕业生短期停留签证。','nín hǎo， wǒ shùn lì wán chéng xué yè bì yè， shēn qǐng bì yè shēng duǎn qī tíng liú qiān zhèng。','Chào chị, em đã hoàn thành khóa học và tốt nghiệp rồi, em xin làm visa lưu trú ngắn hạn cho sinh viên mới tốt nghiệp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_02','V531','工作人员',2,'递交毕业证、毕业离校证明、住宿登记单、证件照片。','dì jiāo bì yè zhèng、 bì yè lí xiào zhèng míng、 zhù sù dēng jì dān、 zhèng jiàn zhào piān。','Em nộp bằng tốt nghiệp, giấy xác nhận thôi học sau tốt nghiệp, phiếu đăng ký chỗ ở và ảnh thẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_03','V531','阮明',3,'短期停留签证最长能办理多久，是三十天还是九十天？','duǎn qī tíng liú qiān zhèng zuì zhǎng néng bàn lǐ duō jiǔ， shì sān shí tiān hái shì jiǔ shí tiān？','Visa lưu trú ngắn hạn này tối đa được bao lâu ạ, ba mươi ngày hay chín mươi ngày ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_04','V531','工作人员',4,'毕业生缓冲居留最长一百八十天，可自由选择时长。','bì yè shēng huǎn chōng jū liú zuì zhǎng yì bǎi bā shí tiān， kě zì yóu xuǎn zé shí cháng。','Cư trú đệm cho sinh viên mới tốt nghiệp tối đa một trăm tám mươi ngày, có thể tự chọn thời hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_05','V531','阮明',5,'这段短期居留期间，能不能正常办理校外实习备案？','zhè duàn duǎn qī jū liú qī jiān， néng bù néng zhèng cháng bàn lǐ xiào wài shí xí bèi àn？','Trong thời gian cư trú ngắn hạn này, em có được làm đăng ký thực tập ngoài trường bình thường không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_06','V531','工作人员',6,'毕业短期停留签证禁止务工、实习，仅用于旅游采购。','bì yè duǎn qī tíng liú qiān zhèng jìn zhǐ wù gōng、 shí xí， jǐn yòng yú lǚ yóu cǎi gòu。','Visa lưu trú ngắn hạn sau tốt nghiệp không được phép làm việc, thực tập, chỉ dùng để du lịch mua sắm thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_07','V531','阮明',7,'缓冲期到期必须离境，无法再次延期对吗？','huǎn chōng qī dào qī bì xū lí jìng， wú fǎ zài cì yán qī duì ma？','Hết thời gian đệm thì bắt buộc phải xuất cảnh, không thể gia hạn thêm lần nữa đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_08','V531','工作人员',8,'无特殊重大事由，毕业短期签证不予二次延期。','wú tè shū zhòng dà shì yóu， bì yè duǎn qī qiān zhèng bù yǔ èr cì yán qī。','Nếu không có lý do đặc biệt nghiêm trọng thì visa ngắn hạn sau tốt nghiệp sẽ không được gia hạn lần hai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_09','V531','阮明',9,'全部材料备齐，麻烦受理短期停留签证申请。','quán bù cái liào bèi qí， má fán shòu lǐ duǎn qī tíng liú qiān zhèng shēn qǐng。','Em chuẩn bị đầy đủ hồ sơ rồi, nhờ chị tiếp nhận xử lý đơn xin visa lưu trú ngắn hạn giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT532','SV6','办理留学回国人员证明，用于境外学历认证',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V532','SIT532','P1','twist','ban_chinh_thuc',NULL,'留学回国人员证明是境外学历认证必备材料，需要完整留存全部在华居留、出入境记录，证件丢失需打印官方流水补充。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_01','V532','阮明',1,'老师，我毕业要办留学回国证明，用来回国做学历认证。','lǎo shī， wǒ bì yè yào bàn liú xué huí guó zhèng míng， yòng lái huí guó zuò xué lì rèn zhèng。','Thầy ơi, em tốt nghiệp rồi cần làm giấy chứng nhận du học sinh về nước, để dùng công nhận bằng cấp khi về nước ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_02','V532','老师',2,'需要提交护照全套签证页复印件、毕业证、毕业离校回执。','xū yào tí jiāo hù zhào quán tào qiān zhèng yè fù yìn jiàn、 bì yè zhèng、 bì yè lí xiào huí zhí。','Cần nộp bản sao toàn bộ các trang visa trong hộ chiếu, bằng tốt nghiệp, và biên nhận thôi học sau tốt nghiệp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_03','V532','阮明',3,'我的旧护照剪角丢失，只有新护照复印件可以提交吗？','wǒ de jiù hù zhào jiǎn jiǎo diū shī， zhǐ yǒu xīn hù zhào fù yìn jiàn kě yǐ tí jiāo ma？','Hộ chiếu cũ của em bị cắt góc và thất lạc rồi, chỉ có bản sao hộ chiếu mới thôi thì nộp được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_04','V532','老师',4,'缺少完整在华居留记录页面，暂时无法开具回国证明嘛。','quē shǎo wán zhěng zài huá jū liú jì lù yè miàn， zàn shí wú fǎ kāi jù huí guó zhèng míng ma。','Thiếu các trang ghi nhận đầy đủ quá trình cư trú tại Trung Quốc thì tạm thời chưa thể cấp giấy chứng nhận về nước được đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_05','V532','阮明',5,'派出所能打印出入境全部入境出境记录替代旧护照复印件吗？','pài chū suǒ néng dǎ yìn chū rù jìng quán bù rù jìng chū jìng jì lù tì dài jiù hù zhào fù yìn jiàn ma？','Công an phường có thể in toàn bộ hồ sơ xuất nhập cảnh để thay cho bản sao hộ chiếu cũ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_06','V532','老师',6,'可以，去出入境大厅打印完整出入境流水作为补充材料。','kě yǐ， qù chū rù jìng dà tīng dǎ yìn wán zhěng chū rù jìng liú shuǐ zuò wéi bǔ chōng cái liào。','Được, em ra sảnh xuất nhập cảnh in đầy đủ lịch sử xuất nhập cảnh để bổ sung làm tài liệu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_07','V532','阮明',7,'我先去打印出入境记录，补齐材料再来申请回国证明。','wǒ xiān qù dǎ yìn chū rù jìng jì lù， bǔ qí cái liào zài lái shēn qǐng huí guó zhèng míng。','Vậy em đi in hồ sơ xuất nhập cảnh trước, bổ sung đầy đủ rồi quay lại xin giấy chứng nhận về nước sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT533','SV6','退学终止学业，注销有效居留许可限期离境',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V533','SIT533','P1','that_bai_nhe','chinh_thuc',NULL,'退学学籍终止，学生居留许可注销，缓冲期仅用于收拾行李离境，缓冲到期无合法续签渠道，超期属于非法滞留。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_01','V533','阮明',1,'警官，我办理退学手续，前来注销现有的学生居留许可。','jǐng guān， wǒ bàn lǐ tuì xué shǒu xù， qián lái zhù xiāo xiàn yǒu de xué shēng jū liú xǔ kě。','Chào cán bộ, tôi làm thủ tục thôi học, đến để hủy giấy phép cư trú diện sinh viên hiện tại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_02','V533','民警',2,'递交退学离校证明，系统注销居留后给予三十天合法停留缓冲期。','dì jiāo tuì xué lí xiào zhèng míng， xì tǒng zhù xiāo jū liú hòu jǐ yǔ sān shí tiān hé fǎ tíng liú huǎn chōng qī。','Nộp giấy xác nhận thôi học rồi, hệ thống hủy cư trú xong sẽ cho anh 30 ngày lưu trú hợp pháp để thu xếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_03','V533','阮明',3,'三十天缓冲期内可以外出旅游，不受出行限制吗？','sān shí tiān huǎn chōng qī nèi kě yǐ wài chū lǚ yóu， bù shòu chū xíng xiàn zhì ma？','Trong 30 ngày đệm đó tôi có thể đi du lịch, không bị hạn chế đi lại đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_04','V533','民警',4,'出行不受限，但缓冲到期必须离境，不能申请续签延期。','chū xíng bù shòu xiàn， dàn huǎn chōng dào qī bì xū lí jìng， bù néng shēn qǐng xù qiān yán qī。','Đi lại thì không bị hạn chế, nhưng hết 30 ngày là bắt buộc phải xuất cảnh, không được xin gia hạn thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_05','V533','阮明',5,'如果三十天内没有买到回国机票，超期停留会如何处罚？','rú guǒ sān shí tiān nèi méi yǒu mǎi dào huí guó jī piào， chāo qī tíng liú huì rú hé chǔ fá？','Nếu trong 30 ngày mà tôi chưa mua được vé máy bay về nước thì ở quá hạn sẽ bị xử phạt thế nào?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_06','V533','民警',6,'退学后无有效学籍，超期一日产生对应罚款，还留下不良入境记录。','tuì xué hòu wú yǒu xiào xué jí， chāo qī yī rì chǎn shēng duì yìng fá kuǎn， hái liú xià bù liáng rù jìng jì lù。','Sau khi thôi học thì không còn tư cách lưu trú hợp lệ nữa, quá hạn một ngày là bị phạt tương ứng, còn để lại vết xấu trong hồ sơ xuất nhập cảnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_07','V533','阮明',7,'缓冲期内只能单次出境，中途回国后无法再次入境中国？','huǎn chōng qī nèi zhǐ néng dān cì chū jìng， zhōng tú huí guó hòu wú fǎ zài cì rù jìng zhōng guó？','Trong thời gian đệm chỉ được xuất cảnh một lần thôi à, nếu về nước giữa chừng thì không thể quay lại Trung Quốc nữa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_08','V533','民警',8,'居留注销后签证同步失效，离境后不能再次入境。','jū liú zhù xiāo hòu qiān zhèng tóng bù shī xiào， lí jìng hòu bù néng zài cì rù jìng。','Sau khi hủy cư trú thì visa cũng mất hiệu lực theo, xuất cảnh rồi là không thể nhập cảnh lại được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_09','V533','阮明',9,'我会在三十天缓冲期内订购机票按时返回越南。','wǒ huì zài sān shí tiān huǎn chōng qī nèi dìng gòu jī piào àn shí fǎn huí yuè nán。','Tôi sẽ đặt vé máy bay trong 30 ngày đệm để về Việt Nam đúng hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT534','SV6','签证到期前彻底回国，咨询居留注销流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V534','SIT534','P1','suon_se','tuy_y',NULL,'留学生永久离境建议主动注销居留许可，证件到期自动失效虽无罚款，但会提升下次来华签证的审核严格程度。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_01','V534','阮明',1,'警官，我毕业直接回国不再来华，需要注销居留许可吗？','jǐng guān， wǒ bì yè zhí jiē huí guó bù zài lái huá， xū yào zhù xiāo jū liú xǔ kě ma？','Cán bộ ơi, em tốt nghiệp là về nước luôn không quay lại Trung Quốc nữa, vậy có cần hủy giấy phép cư trú không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_02','V534','辅警',2,'长期离境建议提前注销居留，避免休眠证件产生异常记录哈。','cháng qī lí jìng jiàn yì tí qián zhù xiāo jū liú， bì miǎn xiū mián zhèng jiàn chǎn shēng yì cháng jì lù hā。','Nếu rời đi lâu dài thì nên chủ động hủy cư trú trước, tránh để giấy tờ ''ngủ đông'' rồi phát sinh ghi nhận bất thường nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_03','V534','阮明',3,'不主动注销，居留到期自动失效会不会留下负面记录？','bù zhǔ dòng zhù xiāo， jū liú dào qī zì dòng shī xiào huì bú huì liú xià fù miàn jì lù？','Không chủ động hủy thì để cư trú tự động hết hạn, vậy có bị ghi nhận tiêu cực không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_04','V534','辅警',4,'到期自动失效无处罚，但下次申请来华签证会增加审核难度。','dào qī zì dòng shī xiào wú chǔ fá， dàn xià cì shēn qǐng lái huá qiān zhèng huì zēng jiā shěn hé nán dù。','Tự động hết hạn thì không bị phạt gì, nhưng lần sau xin visa quay lại Trung Quốc sẽ bị xét duyệt khó hơn đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_05','V534','阮明',5,'注销居留只需要带护照，不用额外准备其他证明？','zhù xiāo jū liú zhǐ xū yào dài hù zhào， bù yòng é wài zhǔn bèi qí tā zhèng míng？','Hủy cư trú chỉ cần mang hộ chiếu thôi, không cần chuẩn bị thêm giấy tờ gì khác à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_06','V534','辅警',6,'携带毕业证、护照现场办理注销，当场打印注销回执。','xié dài bì yè zhèng、 hù zhào xiàn chǎng bàn lǐ zhù xiāo， dāng chǎng dǎ yìn zhù xiāo huí zhí。','Mang bằng tốt nghiệp với hộ chiếu ra làm trực tiếp, xong là in biên nhận hủy cư trú luôn tại chỗ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_07','V534','阮明',7,'回国之后如果再来留学，凭注销回执办理新签证更顺畅？','huí guó zhī hòu rú guǒ zài lái liú xué， píng zhù xiāo huí zhí bàn lǐ xīn qiān zhèng gèng shùn chàng？','Sau này về nước rồi mà quay lại du học tiếp, cầm biên nhận hủy này xin visa mới sẽ thuận lợi hơn đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_08','V534','辅警',8,'是的，完整注销记录有利于后续签证审核。','shì de， wán zhěng zhù xiāo jì lù yǒu lì yú hòu xù qiān zhèng shěn hé。','Đúng vậy, hồ sơ hủy đầy đủ sẽ có lợi cho việc xét duyệt visa sau này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_09','V534','阮明',9,'那我离校前提前来大厅办理居留注销手续。','nà wǒ lí xiào qián tí qián lái dà tīng bàn lǐ jū liú zhù xiāo shǒu xù。','Vậy để em tranh thủ trước khi rời trường sẽ ra sảnh làm thủ tục hủy cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT535','SV6','毕业短期签证到期无法按时离境，申请延期缓冲',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V535','SIT535','P1','twist','chinh_thuc',NULL,'毕业生短期缓冲签证一般不可延期，仅航班取消、重病住院等不可抗力可短期延长停留期限，且需缴纳签证工本费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_01','V535','阮明',1,'您好，我的毕业短期停留签证即将到期，机票延误无法按时离境。','nín hǎo， wǒ de bì yè duǎn qī tíng liú qiān zhèng jí jiāng dào qī， jī piào yán wù wú fǎ àn shí lí jìng。','Xin chào, visa lưu trú ngắn hạn sau tốt nghiệp của tôi sắp hết hạn rồi, nhưng chuyến bay bị hoãn nên không thể xuất cảnh đúng hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_02','V535','工作人员',2,'毕业短期签证原则上不予延期，仅突发客观事由可特殊审批。','bì yè duǎn qī qiān zhèng yuán zé shàng bù yǔ yán qī， jǐn tū fā kè guān shì yóu kě tè shū shěn pī。','Về nguyên tắc thì visa ngắn hạn sau tốt nghiệp không được gia hạn, chỉ trường hợp bất khả kháng khách quan mới được xét duyệt đặc biệt thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_03','V535','阮明',3,'国际航班大面积取消，航空公司开具了延误证明作为凭证。','guó jì háng bān dà miàn jī qǔ xiāo， háng kōng gōng sī kāi jù le yán wù zhèng míng zuò wéi píng zhèng。','Các chuyến bay quốc tế bị hủy hàng loạt, hãng hàng không đã cấp giấy xác nhận hoãn chuyến làm bằng chứng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_04','V535','工作人员',4,'航班延误属于客观特殊情况，最多给予十五天短期延期嘛。','háng bān yán wù shǔ yú kè guān tè shū qíng kuàng， zuì duō jǐ yǔ shí wǔ tiān duǎn qī yán qī ma。','Chuyến bay bị hoãn thuộc trường hợp khách quan đặc biệt, tối đa sẽ được gia hạn ngắn hạn 15 ngày nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_05','V535','阮明',5,'十五天延期需要额外收取签证手续费，还是免费办理？','shí wǔ tiān yán qī xū yào é wài shōu qǔ qiān zhèng shǒu xù fèi， hái shì miǎn fèi bàn lǐ？','Gia hạn 15 ngày này có phải đóng thêm phí thủ tục visa không, hay được làm miễn phí?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_06','V535','工作人员',6,'短期延期统一收取标准签证工本费，无法免除费用。','duǎn qī yán qī tǒng yī shōu qǔ biāo zhǔn qiān zhèng gōng běn fèi， wú fǎ miǎn chú fèi yòng。','Gia hạn ngắn hạn thì vẫn thu phí làm giấy tờ visa theo mức chuẩn, không thể miễn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_07','V535','阮明',7,'递交航空公司延误证明、护照、白底照片即可受理对吗？','dì jiāo háng kōng gōng sī yán wù zhèng míng、 hù zhào、 bái dǐ zhào piān jí kě shòu lǐ duì ma？','Vậy tôi nộp giấy xác nhận hoãn chuyến của hãng bay, hộ chiếu, ảnh nền trắng là được tiếp nhận đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_08','V535','工作人员',8,'全部材料齐全，三个工作日完成延期审批制证。','quán bù cái liào qí quán， sān gè gōng zuò rì wán chéng yán qī shěn pī zhì zhèng。','Đầy đủ giấy tờ thì trong ba ngày làm việc sẽ hoàn tất xét duyệt và cấp giấy gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_09','V535','阮明',9,'我携带航班延误证明，现在递交延期申请材料。','wǒ xié dài háng bān yán wù zhèng míng， xiàn zài dì jiāo yán qī shēn qǐng cái liào。','Tôi mang theo giấy xác nhận hoãn chuyến bay, bây giờ xin nộp hồ sơ xin gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT601','SF1','下载注册国际通用视频软件，和父母跨国视频通话',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V601','SIT601','P1','suon_se','tuy_y',NULL,'国内本土社交软件海外受限，留学生普遍使用国际通用通讯软件和境外家人联络。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_01','V601','阮明',1,'小林，我想装一款国外能用的视频软件跟爸妈通话，你知道哪款好用吗？','xiǎo lín， wǒ xiǎng zhuāng yī kuǎn guó wài néng yòng de shì pín ruǎn jiàn gēn bà mā tōng huà， nǐ zhī dào nǎ kuǎn hǎo yòng ma？','Tiểu Lâm ơi, tớ muốn cài một phần mềm gọi video dùng được ở nước ngoài để gọi cho ba mẹ, cậu biết app nào ngon không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_02','V601','小林',2,'这款APP国内外都能互通，下载之后用邮箱注册就行啦。','zhè kuǎn APP guó nèi wài dōu néng hù tōng， xià zài zhī hòu yòng yóu xiāng zhù cè jiù xíng la。','App này trong nước ngoài nước đều dùng liên thông được hết, tải xong đăng ký bằng email là xong ngay ấy mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_03','V601','阮明',3,'国内手机号注册的话，越南那边收得到验证码吗？','guó nèi shǒu jī hào zhù cè de huà， yuè nán nà biān shōu dé dào yàn zhèng mǎ ma？','Nếu đăng ký bằng số điện thoại trong nước, thì bên Việt Nam có nhận được mã xác nhận không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_04','V601','小林',4,'手机号跨国有延迟，直接绑定邮箱登录最稳妥呢。','shǒu jī hào kuà guó yǒu yán chí， zhí jiē bǎng dìng yóu xiāng dēng lù zuì wěn tuǒ ne。','Số điện thoại xuyên quốc gia hay bị trễ mã lắm, cứ gắn thẳng email để đăng nhập là chắc ăn nhất đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_05','V601','阮明',5,'注册完成后，直接搜索爸妈的账号就能发起视频吗？','zhù cè wán chéng hòu， zhí jiē sōu suǒ bà mā de zhàng hào jiù néng fā qǐ shì pín ma？','Đăng ký xong là chỉ cần tìm tài khoản của ba mẹ là gọi video được luôn hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_06','V601','小林',6,'没错，还能发照片、短视频，日常报平安很方便。','méi cuò， hái néng fā zhào piān、 duǎn shì pín， rì cháng bào píng ān hěn fāng biàn。','Đúng rồi, còn gửi được ảnh, video ngắn nữa, báo bình an hằng ngày tiện lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_07','V601','阮明',7,'太好了，你教我一步步注册，今晚就能跟家里视频。','tài hǎo le， nǐ jiāo wǒ yí bù bù zhù cè， jīn wǎn jiù néng gēn jiā lǐ shì pín。','Tuyệt quá, cậu chỉ tớ đăng ký từng bước nhé, tối nay là gọi video về nhà được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT602','SF1','宿舍WiFi卡顿，求助室友调试网络方便和家人打电话',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V602','SIT602','P1','twist','tuy_y',NULL,'高校宿舍晚八点至十点是网络使用高峰，多人同时联网会造成网速变慢、跨国视频卡顿。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_01','V602','阮明',1,'我一打开视频软件网络就卡顿，根本没法跟爸妈正常通话啊。','wǒ yī dǎ kāi shì pín ruǎn jiàn wǎng luò jiù kǎ dùn， gēn běn méi fǎ gēn bà mā zhèng cháng tōng huà a。','Vừa mở phần mềm video lên là mạng giật lag luôn, gọi cho ba mẹ chả được bình thường gì cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_02','V602','小林',2,'是不是宿舍同时好几个人连WiFi，带宽被占满了？','shì bú shì sù shè tóng shí hǎo jǐ gè rén lián WiFi， dài kuān bèi zhàn mǎn le？','Chắc lúc đó ký túc xá có mấy người cùng dùng WiFi, băng thông bị chiếm hết rồi phải không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_03','V602','阮明',3,'刚才隔壁宿舍也在刷视频，我切换手机流量试试还是卡嘛。','gāng cái gé bì sù shè yě zài shuā shì pín， wǒ qiè huàn shǒu jī liú liàng shì shì hái shì kǎ ma。','Vừa nãy phòng bên cạnh cũng đang xem video, tớ chuyển qua dùng 4G thử mà vẫn giật quá.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_04','V602','小林',4,'我教你断开自动连接的多余设备，路由器重启一下会流畅很多。','wǒ jiāo nǐ duàn kāi zì dòng lián jiē de duō yú shè bèi， lù yóu qì zhòng qǐ yī xià huì liú chàng hěn duō。','Để tớ chỉ cậu ngắt bớt mấy thiết bị tự động kết nối, khởi động lại router chút là mượt hơn nhiều đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_05','V602','阮明',5,'重启路由器之后，跨国视频延迟能降低多少？','chóng qǐ lù yóu qì zhī hòu， kuà guó shì pín yán chí néng jiàng dī duō shǎo？','Khởi động lại router rồi thì độ trễ gọi video xuyên quốc gia có giảm được bao nhiêu không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_06','V602','小林',6,'至少少一半卡顿，避开晚间八点上网高峰效果更好。','zhì shǎo shǎo yí bàn kǎ dùn， bì kāi wǎn jiān bā diǎn shàng wǎng gāo fēng xiào guǒ gèng hǎo。','Giảm ít nhất một nửa độ giật, tránh giờ cao điểm tối 8 giờ dùng mạng thì càng mượt hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_07','V602','阮明',7,'我现在跟着你的步骤操作，等下再打视频电话。','wǒ xiàn zài gēn zhe nǐ de bù zhòu cāo zuò， děng xià zài dǎ shì pín diàn huà。','Giờ tớ làm theo các bước cậu chỉ luôn, lát nữa gọi video lại thử xem sao.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT603','SF1','时差冲突，错过和父母固定视频时间，重新约定时段',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V603','SIT603','P1','suon_se','tuy_y',NULL,'跨国跨时区留学生和家人一般会约定固定通话时间，临时无法上线必须提前留言报平安，避免家人过度担忧。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_01','V603','阮明',1,'昨天上课拖堂，错过了和爸妈约定的视频时间，他们一直等我。','zuó tiān shàng kè tuō táng， cuò guò le hé bà mā yuē dìng de shì pín shí jiān， tā men yì zhí děng wǒ。','Hôm qua tớ học kéo dài giờ, bị lỡ mất giờ hẹn gọi video với ba mẹ, ông bà đợi tớ mãi luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_02','V603','苏雯',2,'越南和国内有一小时时差，你可以提前调整固定联络时段哦。','yuè nán hé guó nèi yǒu yī xiǎo shí shí chà， nǐ kě yǐ tí qián tiáo zhěng gù dìng lián luò shí duàn ó。','Việt Nam và Trung Quốc lệch nhau một tiếng, cậu nên chủ động điều chỉnh giờ liên lạc cố định trước nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_03','V603','阮明',3,'我这边晚上七点，越南就是傍晚六点，这个时间他们刚好下班。','wǒ zhè biān wǎn shàng qī diǎn， yuè nán jiù shì bàng wǎn liù diǎn， zhè ge shí jiān tā men gāng hǎo xià bān。','Bên đây tớ 7 giờ tối thì bên Việt Nam là 6 giờ chiều, đúng lúc ba mẹ tớ vừa tan làm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_04','V603','苏雯',4,'那你跟家里重新敲定这个时间，提前发消息提醒他们上线吧。','nà nǐ gēn jiā lǐ chóng xīn qiāo dìng zhè ge shí jiān， tí qián fā xiāo xī tí xǐng tā men shàng xiàn ba。','Vậy thì cậu chốt lại giờ đó với gia đình đi, nhớ nhắn tin báo trước để ông bà lên mạng cho kịp nha.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_05','V603','阮明',5,'我昨天临时缺场，爸妈还以为我出了什么事，特别担心。','wǒ zuó tiān lín shí quē chǎng， bà mā hái yǐ wéi wǒ chū le shén me shì， tè bié dān xīn。','Hôm qua tớ đột xuất vắng mặt, ba mẹ tớ tưởng tớ gặp chuyện gì, lo lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_06','V603','苏雯',6,'下次如果有课，提前发文字留言告知家人，免得他们焦虑。','xià cì rú guǒ yǒu kè， tí qián fā wén zì liú yán gào zhī jiā rén， miǎn de tā men jiāo lǜ。','Lần sau nếu có tiết học thì nhắn tin báo trước cho gia đình, kẻo mọi người lại sốt ruột.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_07','V603','阮明',7,'我记下了，今晚提前跟家里敲定新的视频时段。','wǒ jì xià le， jīn wǎn tí qián gēn jiā lǐ qiāo dìng xīn de shì pín shí duàn。','Tớ ghi nhớ rồi, tối nay sẽ chốt trước với gia đình giờ gọi video mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT604','SF1','软件登录失败、账号被锁，找同学帮忙找回账号',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V604','SIT604','P1','that_bai_nhe','tuy_y',NULL,'公共网络存在安全风险，跨国通讯软件检测到异地登录会自动锁号，保护用户隐私与账号安全。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_01','V604','阮明',1,'糟糕，我的视频软件账号提示异常登录，直接被系统锁住了。','zāo gāo， wǒ de shì pín ruǎn jiàn zhàng hào tí shì yì cháng dēng lù， zhí jiē bèi xì tǒng suǒ zhù le。','Chết rồi, tài khoản phần mềm video của tớ báo đăng nhập bất thường, bị hệ thống khóa luôn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_02','V604','小林',2,'你是不是切换手机、频繁换WiFi登录，系统判定有风险？','nǐ shì bú shì qiè huàn shǒu jī、 pín fán huàn WiFi dēng lù， xì tǒng pàn dìng yǒu fēng xiǎn？','Có phải cậu hay đổi máy, đổi WiFi liên tục để đăng nhập nên hệ thống thấy rủi ro không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_03','V604','阮明',3,'昨天去图书馆连公共网络登录过，之后回家就登不上去嘛。','zuó tiān qù tú shū guǎn lián gōng gòng wǎng luò dēng lù guò， zhī hòu huí jiā jiù dēng bù shàng qù ma。','Hôm qua tớ ra thư viện dùng mạng công cộng đăng nhập, xong về nhà là không vào được nữa luôn.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_04','V604','小林',4,'解锁需要邮箱收验证链接，你注册时绑定的邮箱还能正常使用吗？','jiě suǒ xū yào yóu xiāng shōu yàn zhèng liàn jiē， nǐ zhù cè shí bǎng dìng de yóu xiāng hái néng zhèng cháng shǐ yòng ma？','Mở khóa cần email nhận link xác nhận, cái email cậu gắn lúc đăng ký còn dùng được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_05','V604','阮明',5,'邮箱密码我记混了，现在双重验证全部卡住没法操作。','yóu xiāng mì mǎ wǒ jì hùn le， xiàn zài shuāng chóng yàn zhèng quán bù kǎ zhù méi fǎ cāo zuò。','Tớ nhớ nhầm mật khẩu email rồi, giờ xác thực hai lớp bị kẹt cứng không thao tác được gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_06','V604','小林',6,'只能先找回邮箱密码，才能解锁通讯软件账号，一步一步来。','zhǐ néng xiān zhǎo huí yóu xiāng mì mǎ， cái néng jiě suǒ tōng xùn ruǎn jiàn zhàng hào， yí bù yí bù lái。','Vậy phải tìm lại mật khẩu email trước đã, mới mở khóa được tài khoản phần mềm liên lạc, làm từng bước một thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_07','V604','阮明',7,'麻烦你陪我操作，不然我今天完全联系不上家里人。','má fán nǐ péi wǒ cāo zuò， bù rán wǒ jīn tiān wán quán lián xì bù shàng jiā lǐ rén。','Phiền cậu ngồi cùng tớ làm với, không thì hôm nay tớ chịu, không liên lạc được với nhà luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT605','SF1','不会操作美颜、屏幕共享，请教室友教自己给家人展示校园',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V605','SIT605','P1','suon_se','tuy_y',NULL,'国际视频软件自带基础美颜、屏幕共享功能，留学生常用来实时展示校园、宿舍生活给海外亲人。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_01','V605','阮明',1,'我想给爸妈看看校园风景，不知道怎么打开屏幕共享功能啊。','wǒ xiǎng gěi bà mā kàn kàn xiào yuán fēng jǐng， bù zhī dào zěn me dǎ kāi píng mù gòng xiǎng gōng néng a。','Tớ muốn cho ba mẹ xem cảnh trường, mà không biết mở tính năng chia sẻ màn hình kiểu gì cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_02','V605','小林',2,'视频通话界面下方有分享按钮，点一下就能同步实景画面呢。','shì pín tōng huà jiè miàn xià fāng yǒu fēn xiǎng àn niǔ， diǎn yī xià jiù néng tóng bù shí jǐng huà miàn ne。','Ở giao diện gọi video có nút chia sẻ phía dưới đó, bấm một cái là truyền hình ảnh thực tế luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_03','V605','阮明',3,'另外画面光线不好，有没有简单的美颜提亮功能？','lìng wài huà miàn guāng xiàn bù hǎo， yǒu méi yǒu jiǎn dān de měi yán tí liàng gōng néng？','Với lại ánh sáng hình không đẹp lắm, có tính năng làm đẹp làm sáng đơn giản nào không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_04','V605','小林',4,'侧边工具栏有基础提亮滤镜，不用复杂调整，一键开启就行。','cè biān gōng jù lán yǒu jī chǔ tí liàng lǜ jìng， bù yòng fù zá tiáo zhěng， yī jiàn kāi qǐ jiù xíng。','Thanh công cụ bên cạnh có bộ lọc làm sáng cơ bản, không cần chỉnh phức tạp gì, bấm một phát là bật thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_05','V605','阮明',5,'共享画面的时候，手机里的照片相册也能同步展示给家人吗？','gòng xiǎng huà miàn de shí hòu， shǒu jī lǐ de zhào piān xiàng cè yě néng tóng bù zhǎn shì gěi jiā rén ma？','Lúc chia sẻ màn hình, ảnh trong thư viện điện thoại có đồng bộ cho gia đình xem được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_06','V605','小林',6,'可以，共享时切换相册，宿舍、教学楼照片都能直接看。','kě yǐ， gòng xiǎng shí qiè huàn xiàng cè， sù shè、 jiào xué lóu zhào piān dōu néng zhí jiē kàn。','Được chứ, lúc chia sẻ chuyển qua thư viện ảnh, ảnh ký túc xá, giảng đường đều xem trực tiếp được hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_07','V605','阮明',7,'太实用了，今晚视频带爸妈逛一遍我们整个校园。','tài shí yòng le， jīn wǎn shì pín dài bà mā guàng yī biàn wǒ men zhěng gè xiào yuán。','Hay quá đi, tối nay gọi video dẫn ba mẹ đi dạo một vòng quanh trường luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT606','SF1','境外手机号收不到软件验证码，改用邮箱登录联系家人',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V606','SIT606','P1','twist','ban_chinh_thuc',NULL,'境内外运营商短信互通存在延迟、丢失问题，跨国软件优先推荐邮箱作为备用验证渠道。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_01','V606','阮明',1,'我更换新手机，软件登录要验证码，越南手机号一直收不到短信。','wǒ gēng huàn xīn shǒu jī， ruǎn jiàn dēng lù yào yàn zhèng mǎ， yuè nán shǒu jī hào yì zhí shōu bú dào duǎn xìn。','Em vừa đổi điện thoại mới, phần mềm đăng nhập cần mã xác nhận, mà số điện thoại Việt Nam của em cứ không nhận được tin nhắn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_02','V606','苏雯',2,'跨国短信运营商通道不稳定，境外号码接收验证码延迟很常见。','kuà guó duǎn xìn yùn yíng shāng tōng dào bù wěn dìng， jìng wài hào mǎ jiē shōu yàn zhèng mǎ yán chí hěn cháng jiàn。','Kênh truyền tin nhắn xuyên quốc gia của các nhà mạng không ổn định, số điện thoại nước ngoài bị chậm nhận mã xác nhận là chuyện thường gặp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_03','V606','阮明',3,'那除了手机号验证，还有别的登录方式可以选择吗？','nà chú le shǒu jī hào yàn zhèng， hái yǒu bié de dēng lù fāng shì kě yǐ xuǎn zé ma？','Vậy ngoài xác thực bằng số điện thoại ra, còn cách đăng nhập nào khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_04','V606','苏雯',4,'注册时绑定的电子邮箱是备用渠道，用邮件验证码就能登录哈。','zhù cè shí bǎng dìng de diàn zi yóu xiāng shì bèi yòng qú dào， yòng yóu jiàn yàn zhèng mǎ jiù néng dēng lù hā。','Email đăng ký lúc trước chính là kênh dự phòng đó, dùng mã xác nhận gửi qua email là đăng nhập được ngay.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_05','V606','阮明',5,'我之前没留意邮箱验证功能，差点一整天没法联系父母。','wǒ zhī qián méi liú yì yóu xiāng yàn zhèng gōng néng， chà diǎn yī zhěng tiān méi fǎ lián xì fù mǔ。','Trước giờ em không để ý đến chức năng xác thực email, suýt nữa cả ngày không liên lạc được với bố mẹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_06','V606','苏雯',6,'之后记得把邮箱设为主要验证方式，避免跨国短信失效。','zhī hòu jì de bǎ yóu xiāng shè wéi zhǔ yào yàn zhèng fāng shì， bì miǎn kuà guó duǎn xìn shī xiào。','Sau này nhớ đặt email làm phương thức xác thực chính, tránh trường hợp tin nhắn xuyên quốc gia bị lỗi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_07','V606','阮明',7,'我现在操作邮箱验证，登录之后第一时间给家里报平安。','wǒ xiàn zài cāo zuò yóu xiāng yàn zhèng， dēng lù zhī hòu dì yī shí jiān gěi jiā lǐ bào píng ān。','Em thao tác xác thực qua email ngay đây, đăng nhập xong là báo bình an cho nhà ngay lập tức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT607','SF1','软件内存过大卡顿，清理缓存保证和家人稳定通话',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V607','SIT607','P1','suon_se','tuy_y',NULL,'长期使用通讯软件会产生大量缓存图片、视频碎片，占用手机内存，定期清理是国内年轻人通用的手机维护习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_01','V607','阮明',1,'这款视频软件存了很多聊天照片，手机越用越卡顿。','zhè kuǎn shì pín ruǎn jiàn cún le hěn duō liáo tiān zhào piān， shǒu jī yuè yòng yuè kǎ dùn。','Cái app video này lưu nhiều ảnh chat quá, điện thoại càng dùng càng giật.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_02','V607','小林',2,'长期堆积缓存文件会拖慢运行速度，定期清理就流畅啦。','cháng qī duī jī huǎn cún wén jiàn huì tuō màn yùn xíng sù dù， dìng qī qīng lǐ jiù liú chàng la。','File cache tích tụ lâu ngày sẽ làm chậm máy, dọn dẹp định kỳ là mượt lại ngay ấy mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_03','V607','阮明',3,'清理缓存会不会删掉我和家人之前保存的聊天照片？','qīng lǐ huǎn cún huì bú huì shān diào wǒ hé jiā rén zhī qián bǎo cún de liáo tiān zhào piān？','Dọn cache thì có xóa mất mấy tấm ảnh chat với gia đình mà em lưu trước đó không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_04','V607','小林',4,'清理临时缓存不会删除相册原图，只会清除冗余临时数据呢。','qīng lǐ lín shí huǎn cún bú huì shān chú xiàng cè yuán tú， zhǐ huì qīng chú rǒng yú lín shí shù jù ne。','Dọn cache tạm thời không xóa ảnh gốc trong album đâu, chỉ xóa mấy dữ liệu tạm dư thừa thôi à.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_05','V607','阮明',5,'清理完缓存，跨国视频的延迟、卡顿问题会明显好转吗？','qīng lǐ wán huǎn cún， kuà guó shì pín de yán chí、 kǎ dùn wèn tí huì míng xiǎn hǎo zhuǎn ma？','Dọn cache xong thì tình trạng giật, delay khi gọi video xuyên quốc gia có đỡ hơn rõ rệt không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_06','V607','小林',6,'是的，手机存储空间充足，网络传输才不会被占用。','shì de， shǒu jī cún chǔ kōng jiān chōng zú， wǎng luò chuán shū cái bú huì bèi zhàn yòng。','Đúng vậy, bộ nhớ máy thoải mái thì đường truyền mạng mới không bị chiếm dụng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_07','V607','阮明',7,'我现在清理缓存，晚上跟家里长时间视频聊天。','wǒ xiàn zài qīng lǐ huǎn cún， wǎn shàng gēn jiā lǐ zhǎng shí jiān shì pín liáo tiān。','Giờ em dọn cache đây, tối nay gọi video nói chuyện lâu lâu với nhà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT608','SF2','跟中国同学解释越南与国内时差，调整联系父母的时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V608','SIT608','P1','suon_se','tuy_y',NULL,'中国全境统一使用北京时间，无分时区；东南亚多国时区与中国存在1-2小时时差，留学生需要协调双方作息沟通。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_01','V608','阮明',1,'很多同学不清楚，越南时间比北京时间慢一小时呢。','hěn duō tóng xué bù qīng chǔ， yuè nán shí jiān bǐ běi jīng shí jiān màn yī xiǎo shí ne。','Nhiều bạn không biết đâu, giờ Việt Nam chậm hơn giờ Bắc Kinh một tiếng đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_02','V608','苏雯',2,'难怪你总是傍晚才跟家里打电话，原来是时差错开了作息。','nán guài nǐ zǒng shì bàng wǎn cái gēn jiā lǐ dǎ diàn huà， yuán lái shì shí chà cuò kāi le zuò xī。','Thảo nào lúc nào cậu cũng đợi chiều tối mới gọi điện về nhà, hóa ra là do lệch múi giờ nên lệch cả giờ sinh hoạt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_03','V608','阮明',3,'国内晚上八点，越南才七点，爸妈刚下班有空跟我聊天。','guó nèi wǎn shàng bā diǎn， yuè nán cái qī diǎn， bà mā gāng xià bān yǒu kòng gēn wǒ liáo tiān。','Trong nước tám giờ tối thì bên Việt Nam mới bảy giờ, bố mẹ tớ vừa tan làm nên rảnh nói chuyện với tớ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_04','V608','苏雯',4,'要是你晚上有晚自习，只能白天课间发文字消息联系家里？','yào shì nǐ wǎn shàng yǒu wǎn zì xí， zhǐ néng bái tiān kè jiān fā wén zì xiāo xī lián xì jiā lǐ？','Nếu tối cậu học phụ đạo thì chỉ có thể tranh thủ giờ ra chơi ban ngày nhắn tin cho nhà thôi à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_05','V608','阮明',5,'对，白天我这边下午，越南中午，他们午休能看消息。','duì， bái tiān wǒ zhè biān xià wǔ， yuè nán zhōng wǔ， tā men wǔ xiū néng kàn xiāo xī。','Ừ, ban ngày bên này là buổi chiều, Việt Nam là buổi trưa, họ nghỉ trưa xem tin nhắn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_06','V608','苏雯',6,'时差错开确实不方便，固定时段联系家人会省心很多。','shí chà cuò kāi què shí bù fāng biàn， gù dìng shí duàn lián xì jiā rén huì shěng xīn hěn duō。','Lệch múi giờ đúng là bất tiện thật, cố định giờ liên lạc với gia đình sẽ đỡ lo hơn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_07','V608','阮明',7,'我已经把通话时间标注在备忘录，不会再错过。','wǒ yǐ jīng bǎ tōng huà shí jiān biāo zhù zài bèi wàng lù， bú huì zài cuò guò。','Em ghi giờ gọi điện vào ghi chú rồi, sẽ không bỏ lỡ nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT609','SF2','生病不舒服，视频隐瞒病情，怕远方家人担心',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V609','SIT609','P1','twist','ban_chinh_thuc',NULL,'在外留学生生病时大多会下意识向家人隐瞒严重不适，不想让远方亲人担忧，是十分普遍的心理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_01','V609','阮明',1,'我发烧头晕，等下跟爸妈视频，不想让他们看出我不舒服。','wǒ fā shāo tóu yūn， děng xià gēn bà mā shì pín， bù xiǎng ràng tā men kàn chū wǒ bù shū fú。','Em bị sốt với chóng mặt, lát nữa gọi video với bố mẹ, không muốn để họ nhận ra em khó chịu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_02','V609','小林',2,'你脸色很苍白，视频一开家人一眼就能察觉到不对劲嘛。','nǐ liǎn sè hěn cāng bái， shì pín yī kāi jiā rén yī yǎn jiù néng chá jué dào bú duì jìn ma。','Mặt em xanh mét thế này, video vừa mở lên là gia đình nhận ra không ổn ngay chứ chẳng cần nói gì luôn.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_03','V609','阮明',3,'他们离这么远，没办法过来照顾我，知道我生病只会干着急。','tā men lí zhè me yuǎn， méi bàn fǎ guò lái zhào gù wǒ， zhī dào wǒ shēng bìng zhǐ huì gān zháo jí。','Bố mẹ ở xa vậy, không thể qua chăm em được, biết em bệnh chỉ càng thêm lo lắng suông thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_04','V609','小林',4,'那你可以只发文字简单提一句轻微感冒，不用隐瞒全部情况。','nà nǐ kě yǐ zhǐ fā wén zì jiǎn dān tí yī jù qīng wēi gǎn mào， bù yòng yǐn mán quán bù qíng kuàng。','Vậy thì em chỉ cần nhắn tin đơn giản là bị cảm nhẹ thôi, không cần giấu hết mọi chuyện đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_05','V609','阮明',5,'我想等完全康复再细说，现在只说一切正常就好。','wǒ xiǎng děng wán quán kāng fù zài xì shuō， xiàn zài zhǐ shuō yī qiè zhèng cháng jiù hǎo。','Em muốn đợi khỏe hẳn rồi kể chi tiết sau, giờ cứ nói mọi thứ bình thường là được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_06','V609','小林',6,'但如果病情加重没人陪同，家人不知情反而更危险。','dàn rú guǒ bìng qíng jiā zhòng méi rén péi tóng， jiā rén bù zhī qíng fǎn ér gèng wēi xiǎn。','Nhưng nếu bệnh nặng hơn mà không ai bên cạnh, gia đình không biết thì lại càng nguy hiểm hơn đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_07','V609','阮明',7,'我会控制视频时长，尽量不提身体难受的地方。','wǒ huì kòng zhì shì pín shí cháng， jǐn liàng bù tí shēn tǐ nán shòu de dì fāng。','Em sẽ hạn chế thời gian gọi video, cố gắng không nhắc đến chỗ nào khó chịu trong người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT610','SF2','期末备考压力大，和家人倾诉焦虑，家人远程安抚',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V610','SIT610','P1','suon_se','ban_chinh_thuc',NULL,'国内家庭普遍重视学业，但父母更在意子女身心健康，子女倾诉学习压力时，家人优先安抚情绪而非一味要求成绩。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_01','V610','阮明',1,'妈，期末要考四门专业课，每天复习到凌晨，压力好大啊。','mā， qī mò yào kǎo sì mén zhuān yè kè， měi tiān fù xí dào líng chén， yā lì hǎo dà a。','Mẹ ơi, kỳ này con phải thi bốn môn chuyên ngành, ngày nào cũng ôn tới khuya, áp lực quá mẹ ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_02','V610','母亲',2,'不用逼自己太紧，劳逸结合，身体比成绩重要呢。','bù yòng bī zì jǐ tài jǐn， láo yì jié hé， shēn tǐ bǐ chéng jì zhòng yào ne。','Đừng ép mình quá vậy, phải cân bằng nghỉ ngơi với học hành, sức khỏe quan trọng hơn điểm số nhiều đó con.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_03','V610','阮明',3,'汉语写作难度很高，我怕期末分数太低影响签证续签。','hàn yǔ xiě zuò nán dù hěn gāo， wǒ pà qī mò fēn shù tài dī yǐng xiǎng qiān zhèng xù qiān。','Viết luận tiếng Trung khó lắm, con sợ điểm cuối kỳ thấp quá ảnh hưởng đến việc gia hạn visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_04','V610','母亲',4,'尽力就好，我们不会要求你必须考高分，放平心态吧。','jìn lì jiù hǎo， wǒ men bú huì yāo qiú nǐ bì xū kǎo gāo fēn， fàng píng xīn tài ba。','Cố hết sức là được rồi, bố mẹ không bắt con phải đạt điểm cao đâu, thoải mái tâm lý lên nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_05','V610','阮明',5,'身边同学进度都很快，我总担心自己跟不上大家。','shēn biān tóng xué jìn dù dōu hěn kuài， wǒ zǒng dān xīn zì jǐ gēn bù shàng dà jiā。','Mấy bạn xung quanh con tiến độ nhanh lắm, con cứ lo mình theo không kịp mọi người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_06','V610','母亲',6,'每天抽空休息半小时，有空多跟我们聊聊，释放压力。','měi tiān chōu kòng xiū xī bàn xiǎo shí， yǒu kòng duō gēn wǒ men liáo liáo， shì fàng yā lì。','Mỗi ngày dành nửa tiếng nghỉ ngơi, rảnh thì nói chuyện nhiều với bố mẹ, xả bớt áp lực đi con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_07','V610','阮明',7,'听完您说的话，心里轻松不少，谢谢妈妈安慰我。','tīng wán nín shuō de huà， xīn lǐ qīng sōng bù shǎo， xiè xiè mā mā ān wèi wǒ。','Nghe mẹ nói xong con thấy nhẹ lòng hẳn, cảm ơn mẹ đã an ủi con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT611','SF2','忘记每日给父母报平安，家人连续多天联系不上十分着急',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V611','SIT611','P1','that_bai_nhe','ban_chinh_thuc',NULL,'留学生在外，国内家人习惯每日收到平安消息，多日失联极易引发家人恐慌，甚至直接联系学校老师求助。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_01','V611','阮明',1,'辅导员，我连续三天忙于备考，忘了给爸妈发消息报平安。','fǔ dǎo yuán， wǒ lián xù sān tiān máng yú bèi kǎo， wàng le gěi bà mā fā xiāo xī bào píng ān。','Thầy/Cô chủ nhiệm ơi, ba ngày nay em bận ôn thi nên quên nhắn tin báo bình an cho bố mẹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_02','V611','辅导员',2,'你母亲昨天打电话到学院，一直联系不上你，特别慌乱。','nǐ mǔ qīn zuó tiān dǎ diàn huà dào xué yuàn， yì zhí lián xì bù shàng nǐ， tè bié huāng luàn。','Hôm qua mẹ em gọi điện lên khoa, liên lạc mãi không được với em, lo lắng lắm đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_03','V611','阮明',3,'我以为不回复一两天没关系，没想到家人会这么担心。','wǒ yǐ wéi bù huí fù yī liǎng tiān méi guān xì， méi xiǎng dào jiā rén huì zhè me dān xīn。','Em cứ nghĩ một hai ngày không trả lời thì không sao, không ngờ gia đình lại lo đến vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_04','V611','辅导员',4,'境外子女长期失联，父母很容易往危险的方向联想嘛。','jìng wài zǐ nǚ cháng qī shī lián， fù mǔ hěn róng yì wǎng wēi xiǎn de fāng xiàng lián xiǎng ma。','Con cái ở nước ngoài mất liên lạc lâu ngày thì bố mẹ rất dễ nghĩ theo hướng xấu đấy chứ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_05','V611','阮明',5,'我现在立刻打视频电话，好好跟家里解释这几天的情况。','wǒ xiàn zài lì kè dǎ shì pín diàn huà， hǎo hǎo gēn jiā lǐ jiě shì zhè jǐ tiān de qíng kuàng。','Em gọi video ngay bây giờ, giải thích rõ ràng tình hình mấy ngày qua cho gia đình yên tâm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_06','V611','辅导员',6,'之后再忙也要抽一分钟发一句简短文字，让家人放心。','zhī hòu zài máng yě yào chōu yì fēn zhōng fā yī jù jiǎn duǎn wén zì， ràng jiā rén fàng xīn。','Sau này dù bận cỡ nào cũng nên dành một phút nhắn vài chữ ngắn gọn, để gia đình an tâm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_07','V611','阮明',7,'我记住教训，以后每天固定简单留言报平安。','wǒ jì zhù jiào xùn， yǐ hòu měi tiān gù dìng jiǎn dān liú yán bào píng ān。','Em rút kinh nghiệm rồi, từ nay mỗi ngày sẽ nhắn tin ngắn báo bình an đều đặn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT612','SF2','学校放长假规划出行，提前和父母商量行程并实时分享定位',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V612','SIT612','P1','suon_se','tuy_y',NULL,'子女独自外出旅行，中国父母普遍要求实时分享定位、每日报备行程，优先关注出行安全。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_01','V612','阮明',1,'妈，寒假我打算和同学去周边城市短途旅行，跟您商量一下。','mā， hán jià wǒ dǎ suàn hé tóng xué qù zhōu biān chéng shì duǎn tú lǚ xíng， gēn nín shāng liáng yī xià。','Mẹ ơi, nghỉ đông này con định cùng bạn đi du lịch ngắn ngày mấy thành phố lân cận, con bàn với mẹ chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_02','V612','母亲',2,'路途远不远，住宿安全吗，出门一定要实时共享定位给我们哦。','lù tú yuǎn bù yuǎn， zhù sù ān quán ma， chū mén yí dìng yào shí shí gòng xiǎng dìng wèi gěi wǒ men ó。','Đường xa không con, chỗ ở có an toàn không, ra ngoài nhớ chia sẻ định vị trực tiếp cho bố mẹ nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_03','V612','阮明',3,'全程高铁出行，住正规连锁酒店，每天晚上同步行程定位。','quán chéng gāo tiě chū xíng， zhù zhèng guī lián suǒ jiǔ diàn， měi tiān wǎn shàng tóng bù xíng chéng dìng wèi。','Cả chuyến đi tụi con toàn đi tàu cao tốc, ở khách sạn chuỗi chính quy, tối nào cũng đồng bộ định vị lịch trình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_04','V612','母亲',4,'每天晚上十点前发消息，告诉我们当天去了哪些地方吧。','měi tiān wǎn shàng shí diǎn qián fā xiāo xī， gào sù wǒ men dàng tiān qù le nǎ xiē dì fāng ba。','Trước mười giờ tối mỗi ngày nhắn tin cho bố mẹ biết hôm đó đi những đâu nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_05','V612','阮明',5,'我每到一个景点都拍照片发给家里，不让你们担心。','wǒ měi dào yí gè jǐng diǎn dōu pāi zhào piān fā gěi jiā lǐ， bù ràng nǐ men dān xīn。','Con đi đến điểm nào cũng chụp ảnh gửi về cho nhà, để bố mẹ không phải lo lắng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_06','V612','母亲',6,'在外结伴出行，不要单独去偏僻人少的地方。','zài wài jié bàn chū xíng， bú yào dān dú qù piān pì rén shǎo de dì fāng。','Ra ngoài phải đi cùng bạn bè, đừng đi một mình đến mấy chỗ vắng vẻ hẻo lánh nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_07','V612','阮明',7,'我会牢记您的叮嘱，出行全程和同学结伴行动。','wǒ huì láo jì nín de dīng zhǔ， chū xíng quán chéng hé tóng xué jié bàn xíng dòng。','Con sẽ ghi nhớ lời mẹ dặn, suốt chuyến đi sẽ luôn đi cùng các bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT613','SF2','深夜在图书馆自习，怕打扰家人休息只发文字消息不打视频',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V613','SIT613','P1','suon_se','tuy_y',NULL,'国人普遍重视夜间休息，深夜语音、视频通话会被视作打扰他人，非紧急情况只用文字留言沟通。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_01','V613','阮明',1,'现在国内已经深夜十一点，我不敢发起视频打扰爸妈休息。','xiàn zài guó nèi yǐ jīng shēn yè shí yì diǎn， wǒ bù gǎn fā qǐ shì pín dǎ rǎo bà mā xiū xī。','Giờ trong nước đã mười một giờ đêm rồi, tớ không dám gọi video sợ làm phiền giấc ngủ của bố mẹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_02','V613','苏雯',2,'时差叠加熬夜，一通视频会直接打断他们睡眠呢。','shí chà dié jiā áo yè， yí tòng shì pín huì zhí jiē dǎ duàn tā men shuì mián ne。','Lệch múi giờ cộng với thức khuya nữa, một cuộc gọi video là cắt ngang giấc ngủ của họ luôn đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_03','V613','阮明',3,'我简单发一段文字，说明我在图书馆自习，一切平安。','wǒ jiǎn dān fā yī duàn wén zì， shuō míng wǒ zài tú shū guǎn zì xí， yī qiè píng ān。','Tớ nhắn vài dòng đơn giản thôi, nói là đang tự học ở thư viện, mọi thứ đều bình an.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_04','V613','苏雯',4,'文字留言他们明天一早醒来就能看到，不会被深夜来电惊扰。','wén zì liú yán tā men míng tiān yī zǎo xǐng lái jiù néng kàn dào， bú huì bèi shēn yè lái diàn jīng rǎo。','Tin nhắn thì sáng mai họ thức dậy là thấy ngay, không bị cuộc gọi khuya làm giật mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_05','V613','阮明',5,'要是遇到急事，才会选择打电话联系家里。','yào shì yù dào jí shì， cái huì xuǎn zé dǎ diàn huà lián xì jiā lǐ。','Nếu có việc gấp thì tớ mới gọi điện về nhà thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_06','V613','苏雯',6,'这样体贴家人作息，长辈心里也会觉得你懂事贴心。','zhè yàng tǐ tiē jiā rén zuò xī， zhǎng bèi xīn lǐ yě huì jué de nǐ dǒng shì tiē xīn。','Cậu quan tâm đến giờ giấc sinh hoạt của gia đình như vậy, người lớn trong nhà sẽ thấy cậu hiểu chuyện và chu đáo lắm đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_07','V613','阮明',7,'嗯，我简单编辑平安消息发送给父母。','ń， wǒ jiǎn dān biān jí píng ān xiāo xī fā sòng gěi fù mǔ。','Ừm, tớ soạn tin nhắn báo bình an ngắn gọn gửi cho bố mẹ đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT614','SF3','生活费不足，委婉跟父母说明开销，协商每月转账额度',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V614','SIT614','P1','suon_se','ban_chinh_thuc',NULL,'子女向家长说明生活费不足时，多委婉说明开销用途，家长一般会适度上调生活费，同时叮嘱合理消费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_01','V614','阮明',1,'爸，最近物价小幅上涨，食堂、生活用品开销比之前多一些。','bà， zuì jìn wù jià xiǎo fú shàng zhǎng， shí táng、 shēng huó yòng pǐn kāi xiāo bǐ zhī qián duō yī xiē。','Ba ơi, dạo này vật giá tăng nhẹ, chi phí ăn ở căng tin với đồ dùng sinh hoạt cũng nhiều hơn trước một chút ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_02','V614','父亲',2,'每月给你的生活费不够支撑日常开销了是吗？','měi yuè gěi nǐ de shēng huó fèi bù gòu zhī chēng rì cháng kāi xiāo le shì ma？','Vậy tiền sinh hoạt ba mẹ gửi hàng tháng không đủ trang trải chi tiêu hàng ngày phải không con?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_03','V614','阮明',3,'除去吃饭、水电，还要买汉语教材，手头经常月底紧张呢。','chú qù chī fàn、 shuǐ diàn， hái yào mǎi hàn yǔ jiào cái， shǒu tóu jīng cháng yuè dǐ jǐn zhāng ne。','Trừ tiền ăn, điện nước ra, con còn phải mua giáo trình tiếng Trung nữa, nên cuối tháng thường xuyên eo hẹp lắm ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_04','V614','父亲',4,'那我们每个月上调一部分汇款额度，保证你不用拮据生活。','nà wǒ men měi gè yuè shàng diào yī bù fèn huì kuǎn é dù， bǎo zhèng nǐ bù yòng jié jū shēng huó。','Vậy ba mẹ sẽ tăng thêm một khoản chuyển khoản hàng tháng, để đảm bảo con không phải sống chật vật.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_05','V614','阮明',5,'我也会减少不必要的网购，合理控制日常消费。','wǒ yě huì jiǎn shǎo bù bì yào de wǎng gòu， hé lǐ kòng zhì rì cháng xiāo fèi。','Con cũng sẽ hạn chế mua sắm online không cần thiết, chi tiêu hàng ngày sẽ tính toán hợp lý hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_06','V614','父亲',6,'不用太节俭，该花的学习、生活开支不用省。','bù yòng tài jié jiǎn， gāi huā de xué xí、 shēng huó kāi zhī bù yòng shěng。','Không cần tiết kiệm quá đâu, khoản nào cần cho học tập với sinh hoạt thì cứ chi, không phải dè xẻn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_07','V614','阮明',7,'谢谢您体谅，我会做好消费规划，不乱花钱。','xiè xiè nín tǐ liàng， wǒ huì zuò hǎo xiāo fèi guī huà， bù luàn huā qián。','Con cảm ơn ba mẹ đã thông cảm, con sẽ lên kế hoạch chi tiêu cẩn thận, không tiêu xài lung tung đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT615','SF3','家人不会操作跨境汇款软件，一步步远程指导父母操作',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V615','SIT615','P1','twist','tuy_y',NULL,'中老年境外亲属不熟悉国内银行跨境汇款线上系统，留学生常通过屏幕共享远程手把手指导操作，避免操作失误转错账户。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_01','V615','阮明',1,'妈，跨境汇款手机软件操作不难，我开屏幕共享一步步教您。','mā， kuà jìng huì kuǎn shǒu jī ruǎn jiàn cāo zuò bù nán， wǒ kāi píng mù gòng xiǎng yí bù bù jiào nín。','Mẹ ơi, cái app chuyển tiền quốc tế này thao tác không khó đâu, con chia sẻ màn hình rồi hướng dẫn mẹ từng bước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_02','V615','母亲',2,'页面全是外文，我看不懂按钮，怕点错造成资金损失啊。','yè miàn quán shì wài wén， wǒ kàn bù dǒng àn niǔ， pà diǎn cuò zào chéng zī jīn sǔn shī a。','Cả trang toàn chữ nước ngoài, mẹ nhìn không hiểu nút nào với nút nào, sợ bấm nhầm mất tiền lắm.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_03','V615','阮明',3,'我指给您看汇款、收款人信息输入的固定位置，不用点其他按钮嘛。','wǒ zhǐ gěi nín kàn huì kuǎn、 shōu kuǎn rén xìn xī shū rù de gù dìng wèi zhì， bù yòng diǎn qí tā àn niǔ ma。','Con chỉ cho mẹ mấy chỗ cố định để nhập thông tin chuyển khoản với người nhận, còn lại mẹ đừng bấm vào chỗ khác nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_04','V615','母亲',4,'输入我的护照号码的时候，字母大小写需要严格区分吗？','shū rù wǒ de hù zhào hào mǎ de shí hòu， zì mǔ dà xiǎo xiě xū yào yán gé qū fēn ma？','Lúc nhập số hộ chiếu của mẹ, chữ hoa chữ thường có cần phân biệt kỹ không con?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_05','V615','阮明',5,'系统不区分大小写，但是姓名拼音必须和护照完全一致。','xì tǒng bù qū fēn dà xiǎo xiě， dàn shì xìng míng pīn yīn bì xū hé hù zhào wán quán yí zhì。','Hệ thống không phân biệt hoa thường đâu mẹ, nhưng tên phiên âm phải khớp y hệt hộ chiếu nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_06','V615','母亲',6,'我操作到一半跳转验证页面，不知道怎么填写信息。','wǒ cāo zuò dào yí bàn tiào zhuǎn yàn zhèng yè miàn， bù zhī dào zěn me tián xiě xìn xī。','Mẹ làm tới nửa chừng thì nó nhảy qua trang xác minh, mẹ không biết điền thông tin sao nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_07','V615','阮明',7,'您别退出页面，我放慢语速，逐项告诉你怎么填写。','nín bié tuì chū yè miàn， wǒ fàng màn yǔ sù， zhú xiàng gào sù nǐ zěn me tián xiě。','Mẹ đừng thoát trang đó nha, con nói chậm lại, chỉ mẹ điền từng mục một nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT616','SF3','转账手续费过高，和家人商量换更划算的汇款渠道',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V616','SIT616','P1','suon_se','ban_chinh_thuc',NULL,'不同跨境汇款渠道手续费标准差异大，大额资金线下银行电汇性价比更高，小额线上便捷但手续费占比更高。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_01','V616','阮明',1,'之前用的汇款渠道手续费比例很高，一笔钱扣不少手续费呢。','zhī qián yòng de huì kuǎn qú dào shǒu xù fèi bǐ lì hěn gāo， yī bǐ qián kòu bù shǎo shǒu xù fèi ne。','Kênh chuyển tiền trước giờ mình dùng phí cao quá, mỗi lần chuyển bị trừ phí kha khá đấy ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_02','V616','父亲',2,'那有没有手续费更低、到账速度稳定的跨境汇款方式？','nà yǒu méi yǒu shǒu xù fèi gèng dī、 dào zhàng sù dù wěn dìng de kuà jìng huì kuǎn fāng shì？','Vậy có cách chuyển tiền quốc tế nào phí thấp hơn mà tiền về ổn định không con?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_03','V616','阮明',3,'银行线下柜台跨境电汇手续费固定，大额汇款会划算很多。','yín háng xiàn xià guì tái kuà jìng diàn huì shǒu xù fèi gù dìng， dà é huì kuǎn huì huá suàn hěn duō。','Chuyển khoản quốc tế tại quầy ngân hàng phí cố định, nếu chuyển số tiền lớn thì lợi hơn nhiều ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_04','V616','父亲',4,'下次大额生活费，我直接去线下银行柜台办理汇款吧。','xià cì dà é shēng huó fèi， wǒ zhí jiē qù xiàn xià yín háng guì tái bàn lǐ huì kuǎn ba。','Vậy lần sau khoản sinh hoạt phí lớn, ba sẽ ra quầy ngân hàng làm trực tiếp.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_05','V616','阮明',5,'小额日常零花钱可以线上软件，大额走线下银行渠道。','xiǎo é rì cháng líng huā qián kě yǐ xiàn shàng ruǎn jiàn， dà é zǒu xiàn xià yín háng qú dào。','Còn tiền tiêu vặt hàng ngày ít thì dùng app online, còn khoản lớn thì đi qua kênh ngân hàng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_06','V616','父亲',6,'两种渠道分开使用，能省下不少手续费长期积累。','liǎng zhǒng qú dào fēn kāi shǐ yòng， néng shěng xià bù shǎo shǒu xù fèi cháng qī jī lěi。','Tách riêng hai kênh như vậy, về lâu dài sẽ tiết kiệm được kha khá phí đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_07','V616','阮明',7,'好，我们分开渠道汇款，减少不必要的手续费损耗。','hǎo， wǒ men fēn kāi qú dào huì kuǎn， jiǎn shǎo bù bì yào de shǒu xù fèi sǔn hào。','Vâng, mình chuyển tiền theo hai kênh riêng như vậy để giảm bớt phí không cần thiết ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT617','SF3','银行卡接收境外汇款被银行拦截，第一时间电话告知父母',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V617','SIT617','P1','twist','chinh_thuc',NULL,'国内银行对大额境外汇款有资金来源核查机制，留学生生活费汇款需携带护照线下申报，防止跨境资金违规流动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_01','V617','阮明',1,'爸，您刚刚汇过来的生活费，被银行系统临时拦截了。','bà， nín gāng gāng huì guò lái de shēng huó fèi， bèi yín háng xì tǒng lín shí lán jié le。','Ba ơi, khoản tiền sinh hoạt ba vừa chuyển bị hệ thống ngân hàng tạm giữ lại rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_02','V617','父亲',2,'怎么会拦截正常留学生生活费，是不是信息填写出错？','zěn me huì lán jié zhèng cháng liú xué shēng shēng huó fèi， shì bú shì xìn xī tián xiě chū cuò？','Sao lại giữ tiền sinh hoạt bình thường của du học sinh được, hay là điền sai thông tin gì rồi?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_03','V617','阮明',3,'银行需要我携带护照去柜台申报资金来源，才能入账嘛。','yín háng xū yào wǒ xié dài hù zhào qù guì tái shēn bào zī jīn lái yuán， cái néng rù zhàng ma。','Ngân hàng yêu cầu con mang hộ chiếu ra quầy khai báo nguồn tiền thì mới ghi có được ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_04','V617','父亲',4,'那这笔资金会原路退回我的账户，还是暂时冻结等待申报？','nà zhè bǐ zī jīn huì yuán lù tuì huí wǒ de zhàng hù， hái shì zàn shí dòng jié děng dài shēn bào？','Vậy khoản tiền đó sẽ chuyển hoàn về tài khoản của ba, hay tạm thời bị đóng băng chờ khai báo?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_05','V617','阮明',5,'资金暂时冻结，今天办完申报手续，明天就能正常入账。','zī jīn zàn shí dòng jié， jīn tiān bàn wán shēn bào shǒu xù， míng tiān jiù néng zhèng cháng rù zhàng。','Tiền đang tạm thời bị đóng băng ạ, hôm nay con làm xong thủ tục khai báo thì ngày mai sẽ vào tài khoản bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_06','V617','父亲',6,'我这边暂时不再追加汇款，等你确认资金到账再说。','wǒ zhè biān zàn shí bù zài zhuī jiā huì kuǎn， děng nǐ què rèn zī jīn dào zhàng zài shuō。','Vậy tạm thời ba chưa chuyển thêm nữa, đợi con xác nhận tiền về rồi tính tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_07','V617','阮明',7,'我办完银行手续第一时间给您回电话告知结果。','wǒ bàn wán yín háng shǒu xù dì yī shí jiān gěi nín huí diàn huà gào zhī jié guǒ。','Con làm xong thủ tục ngân hàng là gọi báo kết quả cho ba ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT618','SF3','想买电子产品，和家人沟通预算，协商分期添置',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V618','SIT618','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内家庭购置大额电子产品会综合考量子女备用资金，优先留存应急生活费，再规划数码产品采购预算。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_01','V618','阮明',1,'我旧手机卡顿严重，想更换一台新手机用于上课录课件。','wǒ jiù shǒu jī kǎ dùn yán zhòng， xiǎng gēng huàn yī tái xīn shǒu jī yòng yú shàng kè lù kè jiàn。','Con điện thoại cũ bị lag nặng rồi, con muốn đổi máy mới để dùng quay bài giảng trên lớp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_02','V618','母亲',2,'新款机型总价偏高，一次性拿出全部资金压力比较大。','xīn kuǎn jī xíng zǒng jià piān gāo， yí cì xìng ná chū quán bù zī jīn yā lì bǐ jiào dà。','Mấy dòng máy mới giá cao lắm, bỏ hết một lần thì áp lực tài chính khá lớn đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_03','V618','阮明',3,'我平时兼职有少量收入，可以自己承担一半购机费用。','wǒ píng shí jiān zhí yǒu shǎo liàng shōu rù， kě yǐ zì jǐ chéng dān yí bàn gòu jī fèi yòng。','Con có làm thêm chút thu nhập, con có thể tự lo một nửa tiền mua máy ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_04','V618','父亲',4,'兼职收入要留存作应急备用金，不能全部拿来买电子产品嘛。','jiān zhí shōu rù yào liú cún zuò yìng jí bèi yòng jīn， bù néng quán bù ná lái mǎi diàn zi chǎn pǐn ma。','Tiền làm thêm phải để dành làm quỹ dự phòng khẩn cấp chứ, không thể dồn hết vào mua đồ điện tử được.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_05','V618','阮明',5,'那我们分两个月，分两次凑齐预算购置手机可以吗？','nà wǒ men fēn liǎng gè yuè， fēn liǎng cì còu qí yù suàn gòu zhì shǒu jī kě yǐ ma？','Vậy mình chia làm hai tháng, góp hai lần để đủ tiền mua điện thoại có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_06','V618','母亲',6,'可以，先预留应急生活费，剩余资金再安排购置设备。','kě yǐ， xiān yù liú yìng jí shēng huó fèi， shèng yú zī jīn zài ān pái gòu zhì shè bèi。','Được, để dành sinh hoạt phí dự phòng trước đã, tiền còn lại thì tính chuyện mua sắm sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_07','V618','阮明',7,'我理解家里的顾虑，不急于一次性换新手机。','wǒ lǐ jiě jiā lǐ de gù lǜ， bù jí yú yí cì xìng huàn xīn shǒu jī。','Con hiểu những lo lắng của gia đình mà, con không vội đổi máy mới ngay đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT619','SF4','中国传统节日，拍校园节日活动视频发给父母讲解习俗',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V619','SIT619','P1','suon_se','tuy_y',NULL,'中秋、春节是中国人核心团圆节日，留学生常会拍摄校园节日活动分享给海外家人，对比两国民俗差异。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_01','V619','阮明',1,'妈，今天校园举办中秋晚会，我拍一段视频发给您看看。','mā， jīn tiān xiào yuán jǔ bàn zhōng qiū wǎn huì， wǒ pāi yī duàn shì pín fā gěi nín kàn kàn。','Mẹ ơi, hôm nay trường tổ chức đêm hội Trung thu, con quay một đoạn video gửi mẹ xem nè.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_02','V619','母亲',2,'画面里大家都在吃月饼、赏月，这就是中国中秋习俗对吧？','huà miàn lǐ dà jiā dōu zài chī yuè bǐng、 shǎng yuè， zhè jiù shì zhōng guó zhōng qiū xí sú duì ba？','Trong hình mọi người đang ăn bánh trung thu, ngắm trăng, đây là phong tục Trung thu của Trung Quốc đúng không con?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_03','V619','阮明',3,'没错，中秋代表团圆，家家户户都会吃月饼、家人相聚呢。','méi cuò， zhōng qiū dài biǎo tuán yuán， jiā jiā hù hù dōu huì chī yuè bǐng、 jiā rén xiāng jù ne。','Đúng rồi mẹ, Trung thu tượng trưng cho đoàn viên, nhà nào cũng ăn bánh trung thu, người thân sum vầy bên nhau nè.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_04','V619','母亲',4,'越南也有类似团圆节日，只是美食和庆祝方式不一样。','yuè nán yě yǒu lèi sì tuán yuán jié rì， zhǐ shì měi shí hé qìng zhù fāng shì bù yí yàng。','Việt Nam mình cũng có ngày lễ đoàn viên tương tự, chỉ khác món ăn với cách tổ chức thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_05','V619','阮明',5,'我今晚分到一块月饼，等下拍照发给您看看样式。','wǒ jīn wǎn fēn dào yī kuài yuè bǐng， děng xià pāi zhào fā gěi nín kàn kàn yàng shì。','Tối nay con được chia một miếng bánh trung thu, lát nữa con chụp hình gửi mẹ xem kiểu dáng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_06','V619','母亲',6,'身在异国也能体验他国节日，多感受不同文化挺好。','shēn zài yì guó yě néng tǐ yàn tā guó jié rì， duō gǎn shòu bù tóng wén huà tǐng hǎo。','Ở xứ người mà vẫn được trải nghiệm lễ hội của nước bạn, cảm nhận thêm văn hóa khác cũng hay đó con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_07','V619','阮明',7,'之后过春节、端午，我都拍校园活动分享给家里。','zhī hòu guò chūn jié、 duān wǔ， wǒ dōu pāi xiào yuán huó dòng fēn xiǎng gěi jiā lǐ。','Sau này tới Tết, Tết Đoan Ngọ, con cũng sẽ quay hoạt động ở trường gửi về cho nhà xem.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT620','SF4','越南传统节日无法回国，视频和家里亲友线上过节',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V620','SIT620','P1','suon_se','tuy_y',NULL,'跨国留学生无法回国过节时，全家会集体视频连线线上团圆，弥补不能线下相聚的遗憾。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_01','V620','阮明',1,'各位长辈，今年节日我没法回国，只能线上和大家一起过节啦。','gè wèi zhǎng bèi， jīn nián jié rì wǒ méi fǎ huí guó， zhǐ néng xiàn shàng hé dà jiā yì qǐ guò jié la。','Cả nhà ơi, năm nay con không về nước được nên chỉ có thể ăn Tết cùng mọi người qua mạng thôi ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_02','V620','亲戚长辈',2,'我们准备了节日特色饭菜，屏幕这边分一份给你看看。','wǒ men zhǔn bèi le jié rì tè sè fàn cài， píng mù zhè biān fēn yī fèn gěi nǐ kàn kàn。','Tụi cô chú chuẩn bị mấy món đặc trưng ngày Tết rồi nè, để cô chia cho con xem qua màn hình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_03','V620','阮明',3,'我在食堂也点了相似风味菜品，也算同步过节了呢。','wǒ zài shí táng yě diǎn le xiāng sì fēng wèi cài pǐn， yě suàn tóng bù guò jié le ne。','Con ở căng tin cũng gọi món có hương vị tương tự, coi như ăn Tết đồng thời với mọi người luôn ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_04','V620','亲戚长辈',4,'在外好好照顾自己，不用挂念家里的节日聚餐。','zài wài hǎo hǎo zhào gù zì jǐ， bù yòng guà niàn jiā lǐ de jié rì jù cān。','Ở bên đó tự chăm sóc bản thân cho tốt nha con, đừng lo bữa tiệc sum họp ở nhà làm gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_05','V620','阮明',5,'虽然相隔很远，视频连线也像坐在一张桌子吃饭。','suī rán xiāng gé hěn yuǎn， shì pín lián xiàn yě xiàng zuò zài yī zhāng zhuō zi chī fàn。','Dù cách xa nhau, nhưng gọi video vậy cũng như ngồi chung một bàn ăn với nhau vậy đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_06','V620','亲戚长辈',6,'假期有空多视频，常跟家里说说日常校园生活。','jià qī yǒu kòng duō shì pín， cháng gēn jiā lǐ shuō shuō rì cháng xiào yuán shēng huó。','Rảnh dịp lễ thì gọi video nhiều nha con, kể chuyện trường lớp thường ngày cho nhà nghe với.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_07','V620','阮明',7,'好，每年传统节日我都会准时上线和大家团聚。','hǎo， měi nián chuán tǒng jié rì wǒ dōu huì zhǔn shí shàng xiàn hé dà jiā tuán jù。','Dạ, năm nào tới lễ Tết truyền thống con cũng sẽ lên mạng đúng giờ sum họp cùng mọi người ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT621','SF4','拍食堂饭菜、宿舍环境视频，实时展示在华日常给家人',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V621','SIT621','P1','suon_se','tuy_y',NULL,'远在境外的父母十分关心子女居住、饮食环境，实时实景视频是最直观让家人安心的方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_01','V621','阮明',1,'爸，我现在共享画面，带您看看我的宿舍和学校食堂。','bà， wǒ xiàn zài gòng xiǎng huà miàn， dài nín kàn kàn wǒ de sù shè hé xué xiào shí táng。','Ba ơi, giờ con chia sẻ màn hình, cho ba xem phòng ký túc xá với căng tin trường con nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_02','V621','父亲',2,'宿舍整洁宽敞，食堂菜品种类看着很丰富，放心多了。','sù shè zhěng jié kuān chǎng， shí táng cài pǐn zhǒng lèi kàn zhe hěn fēng fù， fàng xīn duō le。','Phòng ốc gọn gàng rộng rãi, món ăn ở căng tin nhìn cũng phong phú, ba yên tâm hơn nhiều rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_03','V621','阮明',3,'每天三餐都在食堂解决，价格实惠，口味也能适应。','měi tiān sān cān dōu zài shí táng jiě jué， jià gé shí huì， kǒu wèi yě néng shì yìng。','Ba bữa mỗi ngày con đều ăn ở căng tin, giá cả phải chăng, khẩu vị con cũng hợp được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_04','V621','父亲',4,'日常居住环境安全整洁，我们在家不用一直担心你的生活。','rì cháng jū zhù huán jìng ān quán zhěng jié， wǒ men zài jiā bù yòng yì zhí dān xīn nǐ de shēng huó。','Môi trường sống hàng ngày an toàn sạch sẽ vậy, ba mẹ ở nhà cũng đỡ phải lo lắng suốt cho cuộc sống của con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_05','V621','阮明',5,'楼下还有超市、药店，日常生活用品采购很方便。','lóu xià hái yǒu chāo shì、 yào diàn， rì cháng shēng huó yòng pǐn cǎi gòu hěn fāng biàn。','Dưới tầng còn có siêu thị, nhà thuốc nữa, mua đồ dùng sinh hoạt hàng ngày tiện lắm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_06','V621','父亲',6,'多拍日常视频发给我们，直观知道你在校的生活状态。','duō pāi rì cháng shì pín fā gěi wǒ men， zhí guān zhī dào nǐ zài xiào de shēng huó zhuàng tài。','Con quay thêm video đời thường gửi cho ba mẹ nha, để biết trực tiếp con sống ở trường thế nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_07','V621','阮明',7,'之后每周固定拍一段校园日常视频发给家里。','zhī hòu měi zhōu gù dìng pāi yī duàn xiào yuán rì cháng shì pín fā gěi jiā lǐ。','Sau này mỗi tuần con sẽ quay đều một đoạn video sinh hoạt ở trường gửi về cho nhà xem ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT622','SF4','教父母简单中文短句，方便以后来华出行沟通',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V622','SIT622','P1','twist','tuy_y',NULL,'不少外籍留学生父母计划来华探亲，子女会远程教授基础中文短句，方便线下出行、购物沟通。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_01','V622','阮明',1,'妈，我教您几句简单中文，以后来中国旅游能用得上。','mā， wǒ jiào nín jǐ jù jiǎn dān zhōng wén， yǐ hòu lái zhōng guó lǚ yóu néng yòng dé shàng。','Mẹ ơi, con dạy mẹ vài câu tiếng Trung đơn giản, sau này qua Trung Quốc du lịch dùng được đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_02','V622','母亲',2,'中文发音太难了，我记不住声调，读出来很奇怪啊。','zhōng wén fā yīn tài nán le， wǒ jì bú zhù shēng diào， dú chū lái hěn qí guài a。','Phát âm tiếng Trung khó quá, mẹ không nhớ nổi thanh điệu, đọc ra nghe kỳ kỳ à.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_03','V622','阮明',3,'不用纠结标准声调，简单短句能让店员听懂意思就行嘛。','bù yòng jiū jié biāo zhǔn shēng diào， jiǎn dān duǎn jù néng ràng diàn yuán tīng dǒng yì si jiù xíng ma。','Mẹ không cần chuẩn thanh điệu đâu, câu ngắn đơn giản miễn nhân viên hiểu ý là được mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_04','V622','母亲',4,'比如点餐、问路这类基础句子，您一句一句慢速教我。','bǐ rú diǎn cān、 wèn lù zhè lèi jī chǔ jù zi， nín yī jù yī jù màn sù jiāo wǒ。','Kiểu như gọi món, hỏi đường ấy, con dạy mẹ từng câu một, chậm chậm thôi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_05','V622','阮明',5,'先学"多少钱""请问卫生间在哪里"两句最常用的。','xiān xué " duō shǎo qián "" qǐng wèn wèi shēng jiān zài nǎ lǐ " liǎng jù zuì cháng yòng de。','Trước tiên học hai câu hay dùng nhất là "bao nhiêu tiền" với "xin hỏi nhà vệ sinh ở đâu".',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_06','V622','母亲',6,'我反复跟读几遍，下次来华就能简单沟通不慌张。','wǒ fǎn fù gēn dú jǐ biàn， xià cì lái huá jiù néng jiǎn dān gōu tōng bù huāng zhāng。','Mẹ đọc lại vài lần cho quen, lần sau qua Trung là giao tiếp đơn giản được, khỏi cuống.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_07','V622','阮明',7,'我每天视频花十分钟教您短句，慢慢积累就熟练了。','wǒ měi tiān shì pín huā shí fēn zhōng jiào nín duǎn jù， màn màn jī lěi jiù shú liàn le。','Mỗi ngày con gọi video dạy mẹ mấy câu chừng mười phút, tích lũy dần là quen thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT623','SF4','父母好奇中国课堂，申请老师允许录制简短上课片段发给家人',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V623','SIT623','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂课件拥有教学版权，随意完整录制传播属于违规；仅无课件、不暴露他人肖像的短实景片段可适度拍摄。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_01','V623','阮明',1,'老师您好，我的父母十分好奇中国课堂，想申请录制一小段授课视频。','lǎo shī nín hǎo， wǒ de fù mǔ shí fēn hào qí zhōng guó kè táng， xiǎng shēn qǐng lù zhì yī xiǎo duàn shòu kè shì pín。','Chào cô, bố mẹ em rất tò mò về lớp học ở Trung Quốc, muốn xin quay một đoạn video ngắn buổi học ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_02','V623','老师',2,'课堂内容涉及课件版权，完整整节课录制是不允许的。','kè táng nèi róng shè jí kè jiàn bǎn quán， wán zhěng zhěng jié kè lù zhì shì bù yǔn xǔ de。','Nội dung lớp học liên quan đến bản quyền giáo án, quay trọn vẹn cả buổi thì không được phép.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_03','V623','阮明',3,'那只录制教室环境、课堂互动，不拍摄课件文字可以吗？','nà zhǐ lù zhì jiào shì huán jìng、 kè táng hù dòng， bù pāi shè kè jiàn wén zì kě yǐ ma？','Vậy nếu chỉ quay không gian lớp học, phần tương tác trên lớp thôi, không quay chữ trên giáo án thì có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_04','V623','老师',4,'无课件文字的实景互动片段可以短时间录制，时长控制在一分钟内嘛。','wú kè jiàn wén zì de shí jǐng hù dòng piàn duàn kě yǐ duǎn shí jiān lù zhì， shí cháng kòng zhì zài yì fēn zhōng nèi ma。','Đoạn tương tác thực tế không có chữ giáo án thì có thể quay trong thời gian ngắn, giới hạn trong một phút thôi nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_05','V623','阮明',5,'一分钟短视频足够发给家人了解课堂氛围，不会泄露教学内容。','yì fēn zhōng duǎn shì pín zú gòu fā gěi jiā rén liǎo jiě kè táng fēn wéi， bú huì xiè lòu jiào xué nèi róng。','Một phút video ngắn cũng đủ để gửi cho gia đình xem không khí lớp học rồi ạ, sẽ không lộ nội dung giảng dạy đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_06','V623','老师',6,'录制时不要拍到其他同学清晰面部，保护同班同学隐私。','lù zhì shí bú yào pāi dào qí tā tóng xué qīng xī miàn bù， bǎo hù tóng bān tóng xué yǐn sī。','Khi quay đừng để lộ rõ mặt các bạn học khác, phải bảo vệ quyền riêng tư cho các bạn cùng lớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_07','V623','阮明',7,'我会避开其他同学镜头，只拍摄讲台与教室环境，感谢老师通融。','wǒ huì bì kāi qí tā tóng xué jìng tóu， zhǐ pāi shè jiǎng tái yǔ jiào shì huán jìng， gǎn xiè lǎo shī tōng róng。','Em sẽ tránh ống kính các bạn khác, chỉ quay bục giảng và không gian lớp học thôi, cảm ơn cô đã linh động giúp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT624','SF5','护照丢失，第一时间视频联系家人说明情况寻求建议',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V624','SIT624','P1','suon_se','chinh_thuc',NULL,'留学生丢失护照属于重大紧急事件，第一时间同步家人，家人会协助梳理资金、证件补办相关方案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_01','V624','阮明',1,'爸妈，我今天出门逛街不慎丢失护照，现在在派出所报案。','bà mā， wǒ jīn tiān chū mén guàng jiē bù shèn diū shī hù zhào， xiàn zài zài pài chū suǒ bào àn。','Bố mẹ ơi, hôm nay con đi dạo phố lỡ làm mất hộ chiếu rồi, giờ đang ở đồn công an trình báo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_02','V624','母亲',2,'怎么这么不小心，补办证件流程复杂，资金、证件都有麻烦。','zěn me zhè me bù xiǎo xīn， bǔ bàn zhèng jiàn liú chéng fù zá， zī jīn、 zhèng jiàn dōu yǒu má fán。','Sao lại bất cẩn như vậy, làm lại giấy tờ quy trình rắc rối lắm, tiền bạc, giấy tờ đều phiền phức đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_03','V624','阮明',3,'民警告知我先开遗失回执，再分别去出入境、大使馆补办呢。','mín jǐng gào zhī wǒ xiān kāi yí shī huí zhí， zài fēn bié qù chū rù jìng、 dà shǐ guǎn bǔ bàn ne。','Công an bảo con trước tiên làm biên nhận mất, sau đó lần lượt qua xuất nhập cảnh với đại sứ quán để làm lại.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_04','V624','父亲',4,'需要加急汇款给你吗，补办护照、临时通行证明会产生费用？','xū yào jiā jí huì kuǎn gěi nǐ ma， bǔ bàn hù zhào、 lín shí tōng xíng zhèng míng huì chǎn shēng fèi yòng？','Có cần chuyển tiền gấp cho con không, làm lại hộ chiếu, giấy thông hành tạm thời chắc phải tốn phí?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_05','V624','阮明',5,'暂时不用，校内还有备用生活费，足够支付全部手续工本费。','zàn shí bù yòng， xiào nèi hái yǒu bèi yòng shēng huó fèi， zú gòu zhī fù quán bù shǒu xù gōng běn fèi。','Tạm thời chưa cần đâu ạ, trong trường con còn tiền sinh hoạt dự phòng, đủ trả hết các khoản lệ phí thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_06','V624','母亲',6,'全程保留所有报案单据，每一步办理完及时跟我们同步进度。','quán chéng bǎo liú suǒ yǒu bào àn dān jù， měi yī bù bàn lǐ wán jí shí gēn wǒ men tóng bù jìn dù。','Con nhớ giữ lại toàn bộ giấy tờ trình báo, mỗi bước làm xong nhớ báo lại tiến độ cho bố mẹ liền nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_07','V624','阮明',7,'我每办完一项手续立刻视频同步情况，不让你们一直焦虑。','wǒ měi bàn wán yī xiàng shǒu xù lì kè shì pín tóng bù qíng kuàng， bù ràng nǐ men yì zhí jiāo lǜ。','Con làm xong thủ tục nào là gọi video báo ngay tình hình cho bố mẹ, không để bố mẹ lo lắng mãi đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT625','SF5','轻微摔伤生病，先简单文字报平安，再视频细说伤情',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V625','SIT625','P1','twist','ban_chinh_thuc',NULL,'遇到轻微意外，留学生习惯先发简短文字稳住家人情绪，再短时间视频说明具体情况，防止家人瞬间恐慌。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_01','V625','阮明',1,'（文字）妈，下楼不小心轻微摔伤，无大碍，先跟您报平安。','（wén zì） mā， xià lóu bù xiǎo xīn qīng wēi shuāi shāng， wú dà ài， xiān gēn nín bào píng ān。','(Nhắn tin) Mẹ ơi, con xuống cầu thang lỡ bị té nhẹ, không sao đâu, báo mẹ yên tâm trước đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_02','V625','母亲',2,'看到消息立刻很担心，方便开视频让我看看伤口情况吗？','kàn dào xiāo xī lì kè hěn dān xīn， fāng biàn kāi shì pín ràng wǒ kàn kàn shāng kǒu qíng kuàng ma？','Thấy tin nhắn là mẹ lo ngay, con mở video cho mẹ xem vết thương được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_03','V625','阮明',3,'刚处理完伤口，纱布包裹住，视频画面看着会让人揪心嘛。','gāng chǔ lǐ wán shāng kǒu， shā bù bāo guǒ zhù， shì pín huà miàn kàn zhe huì ràng rén jiū xīn ma。','Con vừa xử lý xong vết thương, băng gạc quấn kín rồi, hình video nhìn vậy sợ mẹ xót thôi mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_04','V625','母亲',4,'就算轻微擦伤也要让我直观看看，判断需不需要去医院复查。','jiù suàn qīng wēi cā shāng yě yào ràng wǒ zhí guān kàn kàn， pàn duàn xū bù xū yào qù yī yuàn fù chá。','Dù chỉ là trầy xước nhẹ mẹ cũng muốn nhìn tận mắt, để xem có cần đi bệnh viện kiểm tra lại không.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_05','V625','阮明',5,'那我简短开五分钟视频，只展示腿部擦伤，不细说难受感受。','nà wǒ jiǎn duǎn kāi wǔ fēn zhōng shì pín， zhǐ zhǎn shì tuǐ bù cā shāng， bù xì shuō nán shòu gǎn shòu。','Vậy con mở video ngắn khoảng năm phút, chỉ chiếu chỗ trầy ở chân thôi, không kể chi tiết đau đớn đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_06','V625','母亲',6,'之后出门走路小心，上下楼梯放慢速度，避免再次受伤。','zhī hòu chū mén zǒu lù xiǎo xīn， shàng xià lóu tī fàng màn sù dù， bì miǎn zài cì shòu shāng。','Sau này đi lại nhớ cẩn thận, lên xuống cầu thang đi chậm lại, tránh bị thương lần nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_07','V625','阮明',7,'我会多加注意，之后受伤第一时间同步文字平安消息。','wǒ huì duō jiā zhù yì， zhī hòu shòu shāng dì yī shí jiān tóng bù wén zì píng ān xiāo xī。','Con sẽ chú ý hơn, sau này bị thương là nhắn tin báo bình an ngay lập tức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT626','SF5','签证续签材料资金不足，远程和父母沟通加急汇款',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V626','SIT626','P1','suon_se','chinh_thuc',NULL,'签证材料资金不达标会直接驳回续签申请，遇到资金缺口家人会优先选择加急汇款渠道，不计较高额手续费保障证件办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_01','V626','阮明',1,'爸，下周就要递交居留续签材料，活期存款余额还差一部分标准。','bà， xià zhōu jiù yào dì jiāo jū liú xù qiān cái liào， huó qī cún kuǎn yú é hái chà yī bù fèn biāo zhǔn。','Bố ơi, tuần sau con phải nộp hồ sơ gia hạn cư trú rồi, số dư tài khoản vãng lai còn thiếu một ít so với mức yêu cầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_02','V626','父亲',2,'还差多少，我今天立刻走加急跨境电汇给你补足流水。','hái chà duō shǎo， wǒ jīn tiān lì kè zǒu jiā jí kuà jìng diàn huì gěi nǐ bǔ zú liú shuǐ。','Còn thiếu bao nhiêu, hôm nay bố chuyển khoản quốc tế khẩn cho con bù đủ ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_03','V626','阮明',3,'还差四千元，加急汇款隔天就能到账，刚好赶上办理日期。','hái chà sì qiān yuán， jiā jí huì kuǎn gé tiān jiù néng dào zhàng， gāng hǎo gǎn shàng bàn lǐ rì qī。','Còn thiếu bốn nghìn tệ ạ, chuyển gấp thì hôm sau tới liền, vừa kịp ngày làm thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_04','V626','父亲',4,'加急渠道手续费更高，但是能保证不耽误你的签证办理。','jiā jí qú dào shǒu xù fèi gèng gāo， dàn shì néng bǎo zhèng bù dān wù nǐ de qiān zhèng bàn lǐ。','Kênh chuyển gấp phí cao hơn, nhưng đảm bảo không trễ việc làm visa của con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_05','V626','阮明',5,'我计算好金额，等资金到账次日立刻打印银行流水。','wǒ jì suàn hǎo jīn é， děng zī jīn dào zhàng cì rì lì kè dǎ yìn yín háng liú shuǐ。','Con đã tính sẵn số tiền rồi, đợi tiền vào tài khoản là hôm sau in sao kê ngân hàng ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_06','V626','父亲',6,'收到汇款短信第一时间告知我，确认入账再去大厅办手续。','shōu dào huì kuǎn duǎn xìn dì yī shí jiān gào zhī wǒ， què rèn rù zhàng zài qù dà tīng bàn shǒu xù。','Nhận được tin nhắn báo chuyển tiền là báo bố ngay nhé, xác nhận tiền vào rồi hẵng ra sảnh làm thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_07','V626','阮明',7,'感谢您加急处理汇款，避免签证断签影响在校学习。','gǎn xiè nín jiā jí chǔ lǐ huì kuǎn， bì miǎn qiān zhèng duàn qiān yǐng xiǎng zài xiào xué xí。','Cảm ơn bố đã chuyển gấp giúp con, để không bị gián đoạn visa ảnh hưởng việc học ở trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT627','SF5','航班延误、行程变动，立刻发消息同步家人避免担忧',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V627','SIT627','P1','suon_se','tuy_y',NULL,'出行航班延误、取消属于高频突发变动，国内家长十分在意行程实时动态，子女必须第一时间同步变动消息。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_01','V627','阮明',1,'妈，我原定今天返程航班大面积延误，起飞推迟六个小时。','mā， wǒ yuán dìng jīn tiān fǎn chéng háng bān dà miàn jī yán wù， qǐ fēi tuī chí liù gè xiǎo shí。','Mẹ ơi, chuyến bay về hôm nay của con bị delay diện rộng, giờ cất cánh trễ mất sáu tiếng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_02','V627','母亲',2,'还好你及时发消息，我一直在盯着航班时刻表担心你落地太晚。','hái hǎo nǐ jí shí fā xiāo xī， wǒ yì zhí zài dīng zhe háng bān shí kè biǎo dān xīn nǐ luò dì tài wǎn。','May mà con báo kịp, mẹ cứ dán mắt vào bảng giờ bay lo con đáp xuống quá khuya đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_03','V627','阮明',3,'机场安排临时休息区域，提供简餐，不会让我长时间干等。','jī chǎng ān pái lín shí xiū xī qū yù， tí gōng jiǎn cān， bú huì ràng wǒ zhǎng shí jiān gàn děng。','Sân bay có bố trí khu nghỉ tạm, có cả suất ăn nhẹ, không để con phải ngồi chờ dài dằng dặc đâu mẹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_04','V627','母亲',4,'落地到达目的地之后，第一时间给我发一条平安消息吧。','luò dì dào dá mù dì dì zhī hòu， dì yī shí jiān gěi wǒ fā yī tiáo píng ān xiāo xī ba。','Đáp xuống tới nơi rồi thì nhắn tin báo bình an cho mẹ ngay nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_05','V627','阮明',5,'落地取完行李、坐上交通车辆，立刻同步文字报平安。','luò dì qǔ wán xíng lǐ、 zuò shàng jiāo tōng chē liàng， lì kè tóng bù wén zì bào píng ān。','Đáp xuống lấy hành lý xong, lên xe rồi là con nhắn tin báo bình an liền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_06','V627','母亲',6,'路途奔波注意休息，不用硬撑着长时间跟我们视频。','lù tú bēn bō zhù yì xiū xī， bù yòng yìng chēng zhe zhǎng shí jiān gēn wǒ men shì pín。','Đi đường mệt thì nhớ nghỉ ngơi, đừng cố gọi video lâu với bố mẹ làm gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_07','V627','阮明',7,'我会随时同步航班动态，不让您一直悬着心。','wǒ huì suí shí tóng bù háng bān dòng tài， bù ràng nín yì zhí xuán zhe xīn。','Con sẽ cập nhật tình hình chuyến bay liên tục, không để mẹ cứ thấp thỏm mãi đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT628','SF6','和父母商量寒暑假回国机票时间，对比价格选择合适航班',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V628','SIT628','P1','twist','tuy_y',NULL,'家长选购国际机票会同时考量票价、落地时段、夜间出行安全，不会单纯选择最低价航班。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_01','V628','阮明',1,'寒暑假有两档回国机票，早一点的班次价格贵三成，晚班性价比更高。','hán shǔ jià yǒu liǎng dàng huí guó jī piào， zǎo yì diǎn de bān cì jià gé guì sān chéng， wǎn bān xìng jià bǐ gèng gāo。','Kỳ nghỉ hè đông có hai loại vé máy bay về nước, chuyến sớm giá đắt hơn ba phần mười, chuyến muộn thì hời hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_02','V628','母亲',2,'晚班抵达越南是深夜，独自打车回家安全方面我们不放心嘛。','wǎn bān dǐ dá yuè nán shì shēn yè， dú zì dǎ chē huí jiā ān quán fāng miàn wǒ men bù fàng xīn ma。','Chuyến muộn đáp xuống Việt Nam là nửa đêm, một mình bắt taxi về nhà bố mẹ không yên tâm về khoản an toàn đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_03','V628','阮明',3,'深夜机场有正规接驳大巴直达市区，比单独打车安全很多。','shēn yè jī chǎng yǒu zhèng guī jiē bó dà bā zhí dá shì qū， bǐ dān dú dǎ chē ān quán hěn duō。','Nửa đêm sân bay có xe buýt trung chuyển chính thức đi thẳng vào trung tâm, an toàn hơn taxi một mình nhiều mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_04','V628','父亲',4,'差价不小，如果接驳交通稳妥，可以选择平价晚班航班。','chā jià bù xiǎo， rú guǒ jiē bó jiāo tōng wěn tuǒ， kě yǐ xuǎn zé píng jià wǎn bān háng bān。','Chênh lệch giá không nhỏ, nếu xe trung chuyển ổn thì chọn chuyến muộn giá rẻ cũng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_05','V628','阮明',5,'我查询了机场大巴运营时间，深夜落地仍有专线班车运行。','wǒ chá xún le jī chǎng dà bā yùn yíng shí jiān， shēn yè luò dì réng yǒu zhuān xiàn bān chē yùn xíng。','Con đã tra giờ hoạt động xe buýt sân bay rồi, nửa đêm đáp xuống vẫn có tuyến chạy bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_06','V628','母亲',6,'那我们折中选择午间航班，价格适中、落地时间也安全。','nà wǒ men zhé zhōng xuǎn zé wǔ jiān háng bān， jià gé shì zhōng、 luò dì shí jiān yě ān quán。','Vậy thôi mình chọn giải pháp trung dung là chuyến buổi trưa, giá vừa phải mà giờ đáp cũng an toàn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_07','V628','阮明',7,'我对比三个航班价格与落地时段，把最优方案发给你们确认。','wǒ duì bǐ sān gè háng bān jià gé yǔ luò dì shí duàn， bǎ zuì yōu fāng àn fā gěi nǐ men què rèn。','Con so sánh giá và giờ đáp của ba chuyến bay rồi, gửi phương án tốt nhất cho bố mẹ duyệt nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT629','SF6','讨论毕业后规划（留华深造/回国工作），和家人交换想法',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V629','SIT629','P1','suon_se','ban_chinh_thuc',NULL,'中国家庭在子女升学、就业选择上，大多会先倾听子女自身意愿，共同商量长远规划，不强行安排人生道路。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_01','V629','阮明',1,'毕业有两条路线，留在中国读硕士，或者直接回国找相关工作。','bì yè yǒu liǎng tiáo lù xiàn， liú zài zhōng guó dú shuò shì， huò zhě zhí jiē huí guó zhǎo xiāng guān gōng zuò。','Sau khi tốt nghiệp có hai hướng, một là ở lại Trung Quốc học thạc sĩ, hai là về nước tìm việc liên quan luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_02','V629','父亲',2,'留在国内深造汉语专业，未来就业选择会更广阔一些。','liú zài guó nèi shēn zào hàn yǔ zhuān yè， wèi lái jiù yè xuǎn zé huì gèng guǎng kuò yī xiē。','Ở lại nước ngoài học chuyên sâu tiếng Trung thì sau này cơ hội việc làm sẽ rộng mở hơn đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_03','V629','阮明',3,'回国本地外贸行业也有对口岗位，离家近方便照顾你们。','huí guó běn dì wài mào háng yè yě yǒu duì kǒu gǎng wèi， lí jiā jìn fāng biàn zhào gù nǐ men。','Về nước thì ngành ngoại thương ở quê cũng có vị trí phù hợp, gần nhà tiện chăm sóc bố mẹ hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_04','V629','母亲',4,'我们尊重你的个人发展意愿，不会强迫你固定选择一条路。','wǒ men zūn zhòng nǐ de gè rén fā zhǎn yì yuàn， bú huì qiǎng pò nǐ gù dìng xuǎn zé yī tiáo lù。','Bố mẹ tôn trọng nguyện vọng phát triển cá nhân của con, không ép con phải chọn cố định một hướng đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_05','V629','阮明',5,'我先实习半年，感受两边行业环境，再确定最终发展方向。','wǒ xiān shí xí bàn nián， gǎn shòu liǎng biān háng yè huán jìng， zài què dìng zuì zhōng fā zhǎn fāng xiàng。','Con định thực tập nửa năm trước, trải nghiệm môi trường ngành nghề cả hai bên rồi mới xác định hướng đi cuối cùng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_06','V629','父亲',6,'实习期间每月同步你的感受，我们一起分析利弊再做决定。','shí xí qī jiān měi yuè tóng bù nǐ de gǎn shòu， wǒ men yì qǐ fēn xī lì bì zài zuò jué dìng。','Trong thời gian thực tập mỗi tháng con cập nhật cảm nhận cho bố mẹ, cùng nhau phân tích lợi hại rồi quyết định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_07','V629','阮明',7,'谢谢爸妈尊重我的规划，有想法第一时间和你们沟通。','xiè xiè bà mā zūn zhòng wǒ de guī huà， yǒu xiǎng fǎ dì yī shí jiān hé nǐ men gōu tōng。','Cảm ơn bố mẹ đã tôn trọng kế hoạch của con, có ý gì con sẽ trao đổi với bố mẹ ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT630','SF6','签证有效期快到期，视频和父母说明续办流程、所需资金',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V630','SIT630','P1','twist','chinh_thuc',NULL,'居留续签存在固定办理周期，证件上交期间无法出行，留学生需要提前和家人沟通资金、时间安排，预留充足缓冲时间。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_01','V630','阮明',1,'我的学生居留许可还有三十天到期，现在开始准备续签全套材料。','wǒ de xué shēng jū liú xǔ kě hái yǒu sān shí tiān dào qī， xiàn zài kāi shǐ zhǔn bèi xù qiān quán tào cái liào。','Thẻ tạm trú diện học sinh của con còn ba mươi ngày nữa là hết hạn, giờ con bắt đầu chuẩn bị đầy đủ hồ sơ để gia hạn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_02','V630','父亲',2,'续签需要额外支付手续费，存款流水也有最低余额要求对吧？','xù qiān xū yào é wài zhī fù shǒu xù fèi， cún kuǎn liú shuǐ yě yǒu zuì dī yú é yāo qiú duì ba？','Gia hạn thì phải đóng thêm phí thủ tục, sao kê tài khoản cũng có yêu cầu số dư tối thiểu đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_03','V630','阮明',3,'工本费金额不高，但是活期流水需要稳定一万元以上留存三个月嘛。','gōng běn fèi jīn é bù gāo， dàn shì huó qī liú shuǐ xū yào wěn dìng yī wàn yuán yǐ shàng liú cún sān gè yuè ma。','Phí làm hồ sơ thì không cao, nhưng số dư tài khoản vãng lai phải duy trì ổn định trên mười nghìn tệ trong ba tháng ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_04','V630','父亲',4,'卡里流动资金不足的话，提前一周告诉我，我提前汇款补足。','kǎ lǐ liú dòng zī jīn bù zú de huà， tí qián yī zhōu gào sù wǒ， wǒ tí qián huì kuǎn bǔ zú。','Nếu tiền trong thẻ không đủ thì báo cho ba trước một tuần, ba sẽ chuyển khoản bổ sung kịp thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_05','V630','阮明',5,'材料齐全七个工作日办结，办理期间护照要上交出入境大厅。','cái liào qí quán qī gè gōng zuò rì bàn jié， bàn lǐ qī jiān hù zhào yào shàng jiāo chū rù jìng dà tīng。','Hồ sơ đầy đủ thì bảy ngày làm việc là xong, trong thời gian xử lý phải nộp hộ chiếu lên phòng xuất nhập cảnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_06','V630','父亲',6,'上交护照期间出行不方便，记得提前办好临时出行证明。','shàng jiāo hù zhào qī jiān chū xíng bù fāng biàn， jì de tí qián bàn hǎo lín shí chū xíng zhèng míng。','Trong lúc nộp hộ chiếu thì đi lại sẽ bất tiện đấy, nhớ làm giấy chứng nhận đi lại tạm thời trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_07','V630','阮明',7,'我会把控办理时间，预留缓冲期，不会出现签证断签的情况。','wǒ huì bǎ kòng bàn lǐ shí jiān， yù liú huǎn chōng qī， bú huì chū xiàn qiān zhèng duàn qiān de qíng kuàng。','Con sẽ canh thời gian làm hồ sơ, để dư thời gian đệm, sẽ không để xảy ra tình trạng gián đoạn visa đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT701','SSH1','入住新生宿舍，向宿管领取钥匙、核对宿舍物品清单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V701','SIT701','P1','suon_se','ban_chinh_thuc',NULL,'高校宿舍入住必须现场核验室内设施并签字登记，人为损坏物品退房会从住宿押金扣除维修费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_01','V701','阮明',1,'阿姨您好，今天办理入住，麻烦给我宿舍钥匙和门禁卡吧。','ā yí nín hǎo， jīn tiān bàn lǐ rù zhù， má fán gěi wǒ sù shè yào shi hé mén jìn kǎ ba。','Cô ơi, hôm nay con làm thủ tục nhập ở, cô cho con xin chìa khóa phòng với thẻ ra vào ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_02','V701','宿管阿姨',2,'先出示你的录取证件，我们一起进屋核对屋内家具清单哦。','xiān chū shì nǐ de lù qǔ zhèng jiàn， wǒ men yì qǐ jìn wū hé duì wū nèi jiā jù qīng dān ó。','Con xuất trình giấy báo trúng tuyển trước đã, rồi cô cháu mình vào phòng kiểm tra danh mục nội thất trong phòng nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_03','V701','阮明',3,'清单上写书桌、衣柜、椅子、空调，我需要逐一检查完好度吗？','qīng dān shàng xiě shū zhuō、 yī guì、 yǐ zi、 kōng tiáo， wǒ xū yào zhú yī jiǎn chá wán hǎo dù ma？','Trong danh mục ghi bàn học, tủ quần áo, ghế, máy lạnh, con phải kiểm tra từng món xem có còn nguyên vẹn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_04','V701','宿管阿姨',4,'对，有划痕、损坏当场标注，退房时就不会扣押金了。','duì， yǒu huà hén、 sǔn huài dāng chǎng biāo zhù， tuì fáng shí jiù bú huì kòu yā jīn le。','Đúng rồi, có vết trầy xước hay hư hỏng gì thì ghi chú luôn tại chỗ, để lúc trả phòng khỏi bị trừ tiền đặt cọc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_05','V701','阮明',5,'墙面很干净，家电都能正常使用，没有破损地方。','qiáng miàn hěn gān jìng， jiā diàn dōu néng zhèng cháng shǐ yòng， méi yǒu pò sǔn dì fāng。','Tường thì sạch sẽ, đồ điện đều dùng bình thường, không có chỗ nào hư hỏng cả cô ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_06','V701','宿管阿姨',6,'确认无误就在物品清单签字，钥匙一共两把收好。','què rèn wú wù jiù zài wù pǐn qīng dān qiān zì， yào shi yī gòng liǎng bǎ shōu hǎo。','Xác nhận không có vấn đề gì thì ký tên vào danh mục đồ đạc, chìa khóa có hai cái nhớ giữ kỹ nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_07','V701','阮明',7,'好的，清单我签字，后续宿舍有问题再来找您报修。','hǎo de， qīng dān wǒ qiān zì， hòu xù sù shè yǒu wèn tí zài lái zhǎo nín bào xiū。','Dạ, con ký vào danh mục rồi, sau này phòng có vấn đề gì con sẽ tìm cô để báo sửa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT702','SSH1','宿舍空调故障不制冷，报修物业上门检修',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V702','SIT702','P1','twist','tuy_y',NULL,'校内宿舍家电基础检修、滤网清洗免费，制冷剂、配件更换属于耗材，会统一登记收费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_01','V702','阮明',1,'师傅，我宿舍空调吹出来全是热风，完全没法制冷啊。','shī fù， wǒ sù shè kōng tiáo chuī chū lái quán shì rè fēng， wán quán méi fǎ zhì lěng a。','Chú ơi, máy lạnh phòng cháu thổi ra toàn hơi nóng, chẳng làm mát tí nào cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_02','V702','维修师傅',2,'我先开机检测，大概率滤网积灰堵塞，也可能缺制冷剂。','wǒ xiān kāi jī jiǎn cè， dà gài lǜ lǜ wǎng jī huī dǔ sè， yě kě néng quē zhì lěng jì。','Để chú bật máy kiểm tra trước, khả năng cao là lưới lọc bám bụi bị nghẹt, cũng có thể là thiếu gas lạnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_03','V702','阮明',3,'上周还正常使用，昨晚突然出故障，没有人为磕碰损坏嘛。','shàng zhōu hái zhèng cháng shǐ yòng， zuó wǎn tū rán chū gù zhàng， méi yǒu rén wéi kē pèng sǔn huài ma。','Tuần trước còn dùng bình thường mà, tối qua tự nhiên hỏng, đâu có ai va chạm làm hỏng đâu ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_04','V702','维修师傅',4,'滤网我拆下来清洗，如果缺氟就要登记预约次日加制冷剂。','lǜ wǎng wǒ chāi xià lái qīng xǐ， rú guǒ quē fú jiù yào dēng jì yù yuē cì rì jiā zhì lěng jì。','Chú tháo lưới lọc ra vệ sinh, nếu thiếu ga thì phải đăng ký hẹn hôm sau đến bơm thêm ga.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_05','V702','阮明',5,'清洗滤网免费吗，加制冷剂需要我额外支付费用？','qīng xǐ lǜ wǎng miǎn fèi ma， jiā zhì lěng jì xū yào wǒ é wài zhī fù fèi yòng？','Vệ sinh lưới lọc có miễn phí không chú, bơm ga thì cháu có phải trả thêm phí không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_06','V702','维修师傅',6,'日常清洗免费，制冷剂损耗需要统一走后勤耗材计费。','rì cháng qīng xǐ miǎn fèi， zhì lěng jì sǔn hào xū yào tǒng yī zǒu hòu qín hào cái jì fèi。','Vệ sinh định kỳ thì miễn phí, còn ga hao hụt thì phải tính chung theo vật tư hậu cần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_07','V702','阮明',7,'先清洗滤网看看效果，不够制冷再预约加氟。','xiān qīng xǐ lǜ wǎng kàn kàn xiào guǒ， bù gòu zhì lěng zài yù yuē jiā fú。','Vậy chú vệ sinh lưới lọc trước xem hiệu quả thế nào, không đủ mát thì cháu hẹn bơm ga sau vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT703','SSH1','宿舍断电跳闸，找宿管排查电路、恢复供电',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V703','SIT703','P1','that_bai_nhe','tuy_y',NULL,'高校宿舍限制大功率电器，多设备同时使用极易触发过载保护跳闸，违规电器引发故障需学生承担维修费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_01','V703','阮明',1,'阿姨，我宿舍突然全屋断电，插座和顶灯全都没电了。','ā yí， wǒ sù shè tū rán quán wū duàn diàn， chā zuò hé dǐng dēng quán dōu méi diàn le。','Cô ơi, phòng con tự nhiên mất điện cả phòng luôn, ổ cắm với đèn trần đều không có điện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_02','V703','宿管阿姨',2,'是不是同时使用吹风机、电煮锅大功率电器跳闸？','shì bú shì tóng shí shǐ yòng chuī fēng jī、 diàn zhǔ guō dà gōng lǜ diàn qì tiào zhá？','Có phải dùng cùng lúc máy sấy tóc với nồi điện công suất lớn nên nhảy át-tô-mát không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_03','V703','阮明',3,'我只用电脑和台灯，没有违规大功率电器，不清楚原因。','wǒ zhǐ yòng diàn nǎo hé tái dēng， méi yǒu wéi guī dà gōng lǜ diàn qì， bù qīng chǔ yuán yīn。','Con chỉ dùng máy tính với đèn bàn thôi, không có thiết bị công suất lớn gì cả, không rõ nguyên nhân luôn cô.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_04','V703','宿管阿姨',4,'宿舍总闸在楼道配电箱，我去合闸，如果再次跳闸就要断电检修线路。','sù shè zǒng zhá zài lóu dào pèi diàn xiāng， wǒ qù hé zhá， rú guǒ zài cì tiào zhá jiù yào duàn diàn jiǎn xiū xiàn lù。','Cầu dao tổng của phòng ở tủ điện hành lang, để cô đóng lại, nếu nhảy lần nữa thì phải cắt điện kiểm tra đường dây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_05','V703','阮明',5,'合闸之后要是反复断电，今晚没法开灯学习怎么办？','hé zhá zhī hòu yào shì fǎn fù duàn diàn， jīn wǎn méi fǎ kāi dēng xué xí zěn me bàn？','Đóng cầu dao xong mà cứ mất điện liên tục thì tối nay con không bật đèn học bài được thì sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_06','V703','宿管阿姨',6,'反复跳闸说明线路隐患，今晚临时安排隔壁空宿舍让你自习。','fǎn fù tiào zhá shuō míng xiàn lù yǐn huàn， jīn wǎn lín shí ān pái gé bì kōng sù shè ràng nǐ zì xí。','Nhảy lặp lại nhiều lần là có nguy cơ về đường dây rồi, tối nay cô sắp xếp tạm phòng trống bên cạnh cho con học bài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_07','V703','阮明',7,'麻烦您先合闸恢复供电，我之后不用多余电器避免跳闸。','má fán nín xiān hé zhá huī fù gōng diàn， wǒ zhī hòu bù yòng duō yú diàn qì bì miǎn tiào zhá。','Phiền cô đóng cầu dao khôi phục điện trước giúp con, sau này con sẽ không dùng thêm thiết bị điện để tránh nhảy át nữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT704','SSH1','宿舍楼道公共热水机不出热水，咨询宿管使用规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V704','SIT704','P1','suon_se','tuy_y',NULL,'校园公共热水设备统一定时启停，夜间停止加热节约水电，是国内高校通用管理方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_01','V704','阮明',1,'阿姨，楼道热水机按了出水键，一直没有热水流出呢。','ā yí， lóu dào rè shuǐ jī àn le chū shuǐ jiàn， yì zhí méi yǒu rè shuǐ liú chū ne。','Cô ơi, máy nước nóng ở hành lang con bấm nút lấy nước rồi mà mãi không thấy nước nóng chảy ra gì cả.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_02','V704','宿管阿姨',2,'机器有定时加热时段，早上六点到晚上十一点才有热水哦。','jī qì yǒu dìng shí jiā rè shí duàn， zǎo shàng liù diǎn dào wǎn shàng shí yì diǎn cái yǒu rè shuǐ ó。','Máy có khung giờ đun nước cố định, từ sáu giờ sáng đến mười một giờ tối mới có nước nóng đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_03','V704','阮明',3,'现在十一点半，刚好过了加热时段，难怪不出热水。','xiàn zài shí yì diǎn bàn， gāng hǎo guò le jiā rè shí duàn， nán guài bù chū rè shuǐ。','Giờ đã mười một rưỡi rồi, vừa hết khung giờ đun nước, thảo nào không có nước nóng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_04','V704','宿管阿姨',4,'如果中途停水，机器缺水也会暂停出水，明天一早恢复。','rú guǒ zhōng tú tíng shuǐ， jī qì quē shuǐ yě huì zàn tíng chū shuǐ， míng tiān yī zǎo huī fù。','Nếu giữa chừng mà cúp nước, máy thiếu nước cũng sẽ tạm ngừng cấp nước, sáng mai sẽ hoạt động lại bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_05','V704','阮明',5,'那我只能明天早上再来接热水洗漱、泡热水杯。','nà wǒ zhǐ néng míng tiān zǎo shàng zài lái jiē rè shuǐ xǐ shù、 pào rè shuǐ bēi。','Vậy chắc con phải đợi sáng mai lấy nước nóng để rửa mặt với pha ly nước nóng thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_06','V704','宿管阿姨',6,'尽量避开晚间高峰，八点左右热水出水最稳定。','jǐn liàng bì kāi wǎn jiān gāo fēng， bā diǎn zuǒ yòu rè shuǐ chū shuǐ zuì wěn dìng。','Cố tránh giờ cao điểm buổi tối nha, khoảng tám giờ là nước nóng ra ổn định nhất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_07','V704','阮明',7,'我记好热水供应时间，不再错过取水时段。','wǒ jì hǎo rè shuǐ gōng yìng shí jiān， bù zài cuò guò qǔ shuǐ shí duàn。','Con ghi nhớ khung giờ cấp nước nóng rồi, sẽ không bỏ lỡ giờ lấy nước nữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT705','SSH1','想加装简易收纳架，询问宿管宿舍墙面能否打孔粘贴',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V705','SIT705','P1','twist','ban_chinh_thuc',NULL,'学生宿舍墙面严禁打孔、钉钉子，保护墙体完整，避免退房产生墙面修补扣款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_01','V705','阮明',1,'阿姨，我想买墙上收纳架，能不能在墙面打孔固定？','ā yí， wǒ xiǎng mǎi qiáng shàng shōu nà jià， néng bù néng zài qiáng miàn dǎ kǒng gù dìng？','Cô ơi, con muốn mua kệ để đồ gắn tường, không biết có được khoan lỗ vào tường để cố định không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_02','V705','宿管阿姨',2,'宿舍墙体不能打孔，打孔留下孔洞退房要扣修补押金。','sù shè qiáng tǐ bù néng dǎ kǒng， dǎ kǒng liú xià kǒng dòng tuì fáng yào kòu xiū bǔ yā jīn。','Tường phòng không được khoan lỗ đâu, khoan để lại lỗ thì lúc trả phòng sẽ bị trừ tiền cọc sửa chữa đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_03','V705','阮明',3,'那无痕粘钩、免钉粘贴式置物架可以使用吗？','nà wú hén zhān gōu、 miǎn dīng zhān tiē shì zhì wù jià kě yǐ shǐ yòng ma？','Vậy dùng móc dán không để lại vết, kệ dán không cần đóng đinh thì được sử dụng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_04','V705','宿管阿姨',4,'无痕粘胶可以，但退房必须完整撕掉，不能残留胶印嘛。','wú hén zhān jiāo kě yǐ， dàn tuì fáng bì xū wán zhěng sī diào， bù néng cán liú jiāo yìn ma。','Keo dán không để lại vết thì được, nhưng lúc trả phòng phải bóc sạch hoàn toàn, không được để lại vết keo nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_05','V705','阮明',5,'如果粘胶撕掉留有痕迹，会收取墙面清洁费对吗？','rú guǒ zhān jiāo sī diào liú yǒu hén jì， huì shōu qǔ qiáng miàn qīng jié fèi duì ma？','Nếu bóc keo mà vẫn còn để lại vết, thì có bị tính phí vệ sinh tường không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_06','V705','宿管阿姨',6,'少量胶印擦拭干净即可，大面积顽固污渍才收费。','shǎo liàng jiāo yìn cā shì gān jìng jí kě， dà miàn jī wán gù wū zì cái shōu fèi。','Vết keo ít thì lau sạch là được, chỉ khi nào vết bẩn cứng đầu diện tích lớn mới bị tính phí thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_07','V705','阮明',7,'我只买免钉粘贴款收纳架，不破坏墙面墙体。','wǒ zhǐ mǎi miǎn dīng zhān tiē kuǎn shōu nà jià， bù pò huài qiáng miàn qiáng tǐ。','Vậy con chỉ mua loại kệ dán không cần đóng đinh thôi, không làm hỏng tường đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT706','SSH1','室友作息差异，协商关灯、安静学习的作息时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V706','SIT706','P1','suon_se','tuy_y',NULL,'多人宿舍室友作息不同是普遍情况，国内学生一般会互相协商灯光、噪音、休息时间，彼此迁就包容。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_01','V706','阮明',1,'小林，我习惯十一点关灯休息，你晚上复习灯光会影响我睡觉。','xiǎo lín， wǒ xí guàn shí yì diǎn guān dēng xiū xī， nǐ wǎn shàng fù xí dēng guāng huì yǐng xiǎng wǒ shuì jiào。','Tiểu Lâm, mình quen tắt đèn ngủ lúc mười một giờ, đèn cậu bật ôn bài buổi tối làm ảnh hưởng giấc ngủ của mình đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_02','V706','小林',2,'我专业课作业多，经常要学到十二点，咱们折中调整一下吧。','wǒ zhuān yè kè zuò yè duō， jīng cháng yào xué dào shí èr diǎn， zán men zhé zhōng tiáo zhěng yī xià ba。','Môn chuyên ngành của mình bài tập nhiều lắm, thường phải học đến mười hai giờ, hai đứa mình điều chỉnh dung hòa một chút đi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_03','V706','阮明',3,'那你用桌面小台灯，十一点后关掉头顶大灯可以吗？','nà nǐ yòng zhuō miàn xiǎo tái dēng， shí yì diǎn hòu guān diào tóu dǐng dà dēng kě yǐ ma？','Vậy cậu dùng đèn bàn nhỏ, sau mười một giờ tắt đèn trần lớn được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_04','V706','小林',4,'没问题，我搭配静音鼠标，不发出敲击键盘噪音打扰你。','méi wèn tí， wǒ dā pèi jìng yīn shǔ biāo， bù fā chū qiāo jī jiàn pán zào yīn dǎ rǎo nǐ。','Không vấn đề gì, mình sẽ dùng chuột không tiếng, không gõ bàn phím ồn làm phiền cậu đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_05','V706','阮明',5,'早上七点我会早起洗漱，我动作轻一点不吵醒你休息。','zǎo shàng qī diǎn wǒ huì zǎo qǐ xǐ shù， wǒ dòng zuò qīng yì diǎn bù chǎo xǐng nǐ xiū xī。','Bảy giờ sáng mình dậy sớm rửa mặt, mình sẽ nhẹ tay để không đánh thức cậu dậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_06','V706','小林',6,'互相体谅作息，宿舍居住才能舒服不产生矛盾。','hù xiāng tǐ liàng zuò xī， sù shè jū zhù cái néng shū fú bù chǎn shēng máo dùn。','Hai đứa thông cảm cho nhau về giờ giấc thì ở ký túc xá mới thoải mái, không sinh mâu thuẫn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_07','V706','阮明',7,'太好了，咱们就按这个作息约定长期配合。','tài hǎo le， zán men jiù àn zhè ge zuò xī yuē dìng cháng qī pèi hé。','Tuyệt quá, vậy hai đứa mình cứ theo giờ giấc này mà phối hợp lâu dài nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT707','SSH1','宿舍晾晒衣物空间不足，咨询楼顶晾晒区开放时段',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V707','SIT707','P1','twist','tuy_y',NULL,'楼顶露天晾晒区夜间关闭，防止衣物夜间受潮、丢失，同时避免高空坠物安全隐患。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_01','V707','阮明',1,'阿姨，阳台晾衣杆挂满衣服，没有位置晾晒刚洗的床单。','ā yí， yáng tái liàng yī gān guà mǎn yī fú， méi yǒu wèi zhì liàng shài gāng xǐ de chuáng dān。','Cô ơi, sào phơi đồ ở ban công treo kín đồ hết rồi, không còn chỗ phơi ga giường vừa giặt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_02','V707','宿管阿姨',2,'宿舍楼顶有公共晾晒区，但是只白天七点到十八点开放。','sù shè lóu dǐng yǒu gōng gòng liàng shài qū， dàn shì zhǐ bái tiān qī diǎn dào shí bā diǎn kāi fàng。','Trên sân thượng ký túc xá có khu phơi đồ chung, nhưng chỉ mở cửa ban ngày từ bảy giờ đến sáu giờ chiều thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_03','V707','阮明',3,'现在傍晚六点半，马上到关闭时间，今天还能上楼顶晾衣服吗？','xiàn zài bàng wǎn liù diǎn bàn， mǎ shàng dào guān bì shí jiān， jīn tiān hái néng shàng lóu dǐng liàng yī fú ma？','Giờ đã sáu giờ rưỡi chiều rồi, sắp đến giờ đóng cửa, hôm nay con còn kịp lên sân thượng phơi đồ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_04','V707','宿管阿姨',4,'十八点保洁会收回露天衣物，晚一点容易夜间受潮发霉嘛。','shí bā diǎn bǎo jié huì shōu huí lù tiān yī wù， wǎn yì diǎn róng yì yè jiān shòu cháo fā méi ma。','Sáu giờ chiều là tổ vệ sinh sẽ thu đồ phơi ngoài trời rồi, phơi muộn dễ bị ẩm mốc qua đêm lắm đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_05','V707','阮明',5,'那我明天一早七点上楼顶，抢占晾晒位置晒大件被褥。','nà wǒ míng tiān yī zǎo qī diǎn shàng lóu dǐng， qiǎng zhàn liàng shài wèi zhì shài dà jiàn bèi rù。','Vậy sáng mai con lên sân thượng đúng bảy giờ, tranh chỗ phơi để phơi mấy món to như chăn ga.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_06','V707','宿管阿姨',6,'楼顶风大，记得带夹子固定衣物，防止被风吹落丢失。','lóu dǐng fēng dà， jì de dài jiā zi gù dìng yī wù， fáng zhǐ bèi fēng chuī luò diū shī。','Trên sân thượng gió lớn lắm, nhớ mang kẹp để cố định đồ, tránh bị gió thổi bay mất đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_07','V707','阮明',7,'好，我明天提前上楼晾晒大件床上用品。','hǎo， wǒ míng tiān tí qián shàng lóu liàng shài dà jiàn chuáng shàng yòng pǐn。','Dạ vâng, mai con sẽ lên sớm để phơi mấy món đồ giường cỡ lớn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT708','SSH1','宿舍公共垃圾桶满溢，询问保洁阿姨清运时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V708','SIT708','P1','suon_se','tuy_y',NULL,'国内校园推行垃圾分类，楼道垃圾桶定时清运，满溢时可使用楼下备用分类垃圾桶。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_01','V708','阮明',1,'阿姨，楼道垃圾桶全部装满垃圾，没法再投放废弃物了。','ā yí， lóu dào lā jī tǒng quán bù zhuāng mǎn lā jī， méi fǎ zài tóu fàng fèi qì wù le。','Cô ơi, thùng rác ở hành lang đầy ắp rồi, không đổ thêm rác vào được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_02','V708','保洁李阿姨',2,'我每天上午九点、下午四点各清运一次垃圾哈。','wǒ měi tiān shàng wǔ jiǔ diǎn、 xià wǔ sì diǎn gè qīng yùn yī cì lā jī hā。','Cô mỗi ngày dọn rác hai lần, chín giờ sáng với bốn giờ chiều nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_03','V708','阮明',3,'现在下午两点，还要等两小时才能清空垃圾桶吗？','xiàn zài xià wǔ liǎng diǎn， hái yào děng liǎng xiǎo shí cái néng qīng kōng lā jī tǒng ma？','Giờ mới hai giờ chiều, vậy phải đợi thêm hai tiếng nữa mới đổ được thùng rác à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_04','V708','保洁李阿姨',4,'楼下门口有备用分类垃圾桶，可以暂时投放垃圾。','lóu xià mén kǒu yǒu bèi yòng fēn lèi lā jī tǒng， kě yǐ zàn shí tóu fàng lā jī。','Dưới cửa tầng dưới có thùng rác phân loại dự phòng, con có thể tạm bỏ rác vào đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_05','V708','阮明',5,'我先把垃圾带到楼下备用桶，等您四点再来清运。','wǒ xiān bǎ lā jī dài dào lóu xià bèi yòng tǒng， děng nín sì diǎn zài lái qīng yùn。','Con mang rác xuống thùng dự phòng ở dưới trước, đợi bốn giờ cô lên dọn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_06','V708','保洁李阿姨',6,'垃圾分类记得分开投放，纸类、塑料不要混在一起。','lā jī fēn lèi jì de fēn kāi tóu fàng， zhǐ lèi、 sù liào bú yào hùn zài yì qǐ。','Nhớ phân loại rác cẩn thận đấy, giấy với nhựa đừng để lẫn vào nhau nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_07','V708','阮明',7,'我会做好垃圾分类投放，不给您增加分拣工作量。','wǒ huì zuò hǎo lā jī fēn lèi tóu fàng， bù gěi nín zēng jiā fēn jiǎn gōng zuò liàng。','Con sẽ phân loại rác cho đàng hoàng, không để cô phải phân loại lại đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT709','SSH1','宿舍门禁卡丢失，到宿管处挂失补办门禁卡',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V709','SIT709','P1','that_bai_nhe','ban_chinh_thuc',NULL,'宿舍门禁卡丢失必须第一时间挂失锁卡，保障宿舍财物安全；补办卡片统一收取工本费，制卡设备故障会发放临时通行凭证。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_01','V709','阮明',1,'阿姨，我的宿舍门禁卡昨天外出弄丢了，前来挂失补办。','ā yí， wǒ de sù shè mén jìn kǎ zuó tiān wài chū nòng diū le， qián lái guà shī bǔ bàn。','Cô ơi, thẻ ra vào ký túc xá của con hôm qua đi ra ngoài bị làm mất rồi, con đến báo mất và xin làm lại thẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_02','V709','宿管阿姨',2,'先登记挂失，旧卡立刻锁死，防止别人开门进入宿舍。','xiān dēng jì guà shī， jiù kǎ lì kè suǒ sǐ， fáng zhǐ bié rén kāi mén jìn rù sù shè。','Đăng ký báo mất trước đã, thẻ cũ sẽ bị khóa ngay để tránh người khác dùng mở cửa vào phòng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_03','V709','阮明',3,'补办新门禁卡需要支付工本费吗，当场就能拿到卡片？','bǔ bàn xīn mén jìn kǎ xū yào zhī fù gōng běn fèi ma， dāng chǎng jiù néng ná dào kǎ piàn？','Làm lại thẻ mới có phải đóng phí không cô, và con có thể nhận thẻ ngay không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_04','V709','宿管阿姨',4,'补办一张门禁卡二十元工本费，制卡机器今天故障维修嘛。','bǔ bàn yī zhāng mén jìn kǎ èr shí yuán gōng běn fèi， zhì kǎ jī qì jīn tiān gù zhàng wéi xiū ma。','Làm lại một thẻ mất hai mươi tệ phí làm thẻ, nhưng máy làm thẻ hôm nay đang hỏng phải sửa đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_05','V709','阮明',5,'那今天拿不到新卡，晚上怎么刷卡回宿舍休息？','nà jīn tiān ná bú dào xīn kǎ， wǎn shàng zěn me shuā kǎ huí sù shè xiū xī？','Vậy hôm nay chưa lấy được thẻ mới, thì tối nay con quẹt thẻ kiểu gì để về phòng nghỉ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_06','V709','宿管阿姨',6,'我给你开具临时纸质通行条，今晚凭纸条进出楼栋。','wǒ gěi nǐ kāi jù lín shí zhǐ zhì tōng xíng tiáo， jīn wǎn píng zhǐ tiáo jìn chū lóu dòng。','Cô sẽ viết cho con một giấy thông hành tạm thời, tối nay con cầm giấy đó ra vào tòa nhà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_07','V709','阮明',7,'明天机器修好我再来缴费领新门禁卡。','míng tiān jī qì xiū hǎo wǒ zài lái jiǎo fèi lǐng xīn mén jìn kǎ。','Vậy mai máy sửa xong con sẽ quay lại đóng tiền và nhận thẻ mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT710','SSH1','校外租房看房，和房东核对家具家电完好情况',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V710','SIT710','P1','suon_se','ban_chinh_thuc',NULL,'校外租房入住前必须逐项核对房屋设施并书面记录原有损坏，避免退租时房东以破损为由克扣押金。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_01','V710','阮明',1,'刘哥，我们一起核对屋内家电、家具，记录破损地方吧。','liú gē， wǒ men yì qǐ hé duì wū nèi jiā diàn、 jiā jù， jì lù pò sǔn dì fāng ba。','Anh Lưu ơi, mình cùng kiểm tra lại đồ điện với đồ nội thất trong phòng, ghi chú chỗ nào hư hỏng nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_02','V710','房东',2,'冰箱、洗衣机、空调全部试机，有问题当场写进租房合同。','bīng xiāng、 xǐ yī jī、 kōng tiáo quán bù shì jī， yǒu wèn tí dāng chǎng xiě jìn zū fáng hé tóng。','Tủ lạnh, máy giặt, máy lạnh đều thử chạy hết, có vấn đề gì thì ghi ngay vào hợp đồng thuê nhà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_03','V710','阮明',3,'衣柜门板有一道小划痕，墙面墙角轻微掉皮，我标注下来。','yī guì mén bǎn yǒu yī dào xiǎo huà hén， qiáng miàn qiáng jiǎo qīng wēi diào pí， wǒ biāo zhù xià lái。','Cửa tủ quần áo có một vết xước nhỏ, góc tường bị tróc nhẹ, để em ghi chú lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_04','V710','房东',4,'这些原有轻微损伤全部备注，退房不会扣你的押金。','zhè xiē yuán yǒu qīng wēi sǔn shāng quán bù bèi zhù， tuì fáng bú huì kòu nǐ de yā jīn。','Những hư hỏng nhỏ có sẵn này đều được ghi chú hết, khi trả nhà sẽ không bị trừ tiền cọc của em đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_05','V710','阮明',5,'水电表初始读数也一起记录，避免结算时产生争议。','shuǐ diàn biǎo chū shǐ dú shù yě yì qǐ jì lù， bì miǎn jié suàn shí chǎn shēng zhēng yì。','Số công tơ điện nước ban đầu cũng ghi lại luôn, để tránh phát sinh tranh cãi khi tính tiền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_06','V710','房东',6,'没问题，所有物品、读数核对完，我们签署纸质租房合同。','méi wèn tí， suǒ yǒu wù pǐn、 dú shù hé duì wán， wǒ men qiān shǔ zhǐ zhì zū fáng hé tóng。','Không vấn đề gì, sau khi kiểm tra hết đồ đạc và số liệu xong, mình ký hợp đồng thuê nhà giấy luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_07','V710','阮明',7,'全部设备正常使用，破损全部登记，可以签约入住。','quán bù shè bèi zhèng cháng shǐ yòng， pò sǔn quán bù dēng jì， kě yǐ qiān yuē rù zhù。','Tất cả thiết bị đều dùng bình thường, hư hỏng cũng ghi lại hết rồi, có thể ký hợp đồng dọn vào ở luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT711','SSH2','食堂充值机无法读卡，找食堂工作人员处理饭卡故障',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V711','SIT711','P1','twist','tuy_y',NULL,'校园饭卡内置磁条，手机、钥匙长期放在一起容易消磁失效，消磁卡片无法修复只能补办。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_01','V711','阮明',1,'你好，校园饭卡放到充值机，机器完全识别不出卡片啊。','nǐ hǎo， xiào yuán fàn kǎ fàng dào chōng zhí jī， jī qì wán quán shí bié bù chū kǎ piàn a。','Chào chị, em để thẻ ăn vào máy nạp tiền mà máy không nhận diện được thẻ gì hết á.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_02','V711','工作人员',2,'是不是卡片弯折、消磁了，放到读卡窗口多试两次。','shì bú shì kǎ piàn wān zhé、 xiāo cí le， fàng dào dú kǎ chuāng kǒu duō shì liǎng cì。','Có phải thẻ bị cong hay mất từ không, em thử đặt vào khe đọc thẻ vài lần xem.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_03','V711','阮明',3,'反复摆放五次都无反应，昨天还正常充值用餐嘛。','fǎn fù bǎi fàng wǔ cì dōu wú fǎn yìng， zuó tiān hái zhèng cháng chōng zhí yòng cān ma。','Em thử năm lần rồi mà vẫn không có phản ứng gì, hôm qua vẫn nạp tiền ăn bình thường mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_04','V711','工作人员',4,'卡片消磁只能补办新卡，旧卡余额可以转移到新卡里。','kǎ piàn xiāo cí zhǐ néng bǔ bàn xīn kǎ， jiù kǎ yú é kě yǐ zhuǎn yí dào xīn kǎ lǐ。','Thẻ mất từ thì chỉ có cách làm thẻ mới thôi, số dư thẻ cũ có thể chuyển sang thẻ mới được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_05','V711','阮明',5,'补办饭卡需要携带什么证件，多久能拿到新卡片？','bǔ bàn fàn kǎ xū yào xié dài shén me zhèng jiàn， duō jiǔ néng ná dào xīn kǎ piàn？','Làm lại thẻ ăn cần mang giấy tờ gì, và bao lâu thì lấy được thẻ mới ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_06','V711','工作人员',6,'带护照、学生证，十分钟制卡完成，当场转移余额。','dài hù zhào、 xué shēng zhèng， shí fēn zhōng zhì kǎ wán chéng， dāng chǎng zhuǎn yí yú é。','Mang hộ chiếu, thẻ sinh viên, mười phút là làm xong thẻ, chuyển số dư luôn tại chỗ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_07','V711','阮明',7,'我现在回宿舍拿证件，过来补办饭卡转移余额。','wǒ xiàn zài huí sù shè ná zhèng jiàn， guò lái bǔ bàn fàn kǎ zhuǎn yí yú é。','Vậy giờ em về phòng lấy giấy tờ, rồi quay lại làm thẻ ăn và chuyển số dư.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT712','SSH2','丢失校园饭卡，挂失冻结余额、补办新饭卡',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V712','SIT712','P1','suon_se','ban_chinh_thuc',NULL,'饭卡丢失第一时间挂失可保护卡内余额，挂失后旧卡永久失效，余额完整迁移至新卡片。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_01','V712','阮明',1,'您好，我的校园饭卡丢失，麻烦先帮我挂失冻结余额。','nín hǎo， wǒ de xiào yuán fàn kǎ diū shī， má fán xiān bāng wǒ guà shī dòng jié yú é。','Chào anh/chị, thẻ ăn của em bị mất rồi, phiền anh/chị giúp em báo mất và đóng băng số dư trước ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_02','V712','工作人员',2,'报你的姓名、学号，系统马上锁定旧卡，无法刷卡消费。','bào nǐ de xìng míng、 xué hào， xì tǒng mǎ shàng suǒ dìng jiù kǎ， wú fǎ shuā kǎ xiāo fèi。','Em cho tôi tên với mã số sinh viên, hệ thống sẽ khóa thẻ cũ ngay, không quẹt tiêu được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_03','V712','阮明',3,'卡里还有一百二十元余额，挂失后能完整转移到新卡吗？','kǎ lǐ hái yǒu yì bǎi èr shí yuán yú é， guà shī hòu néng wán zhěng zhuǎn yí dào xīn kǎ ma？','Trong thẻ còn một trăm hai mươi tệ, báo mất xong thì có chuyển hết sang thẻ mới được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_04','V712','工作人员',4,'全部余额无损转移，仅收取十元新卡工本费。','quán bù yú é wú sǔn zhuǎn yí， jǐn shōu qǔ shí yuán xīn kǎ gōng běn fèi。','Toàn bộ số dư sẽ chuyển nguyên vẹn, chỉ thu mười tệ phí làm thẻ mới thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_05','V712','阮明',5,'挂失之后如果有人捡到旧卡，也不能刷卡消费了对吧？','guà shī zhī hòu rú guǒ yǒu rén jiǎn dào jiù kǎ， yě bù néng shuā kǎ xiāo fèi le duì ba？','Sau khi báo mất, nếu có ai nhặt được thẻ cũ thì cũng không quẹt tiêu được nữa đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_06','V712','工作人员',6,'没错，挂失永久锁死旧卡，捡到也无法使用。','méi cuò， guà shī yǒng jiǔ suǒ sǐ jiù kǎ， jiǎn dào yě wú fǎ shǐ yòng。','Đúng vậy, báo mất là khóa vĩnh viễn thẻ cũ, nhặt được cũng không dùng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_07','V712','阮明',7,'我现在补办新卡，今晚就能正常去食堂吃饭。','wǒ xiàn zài bǔ bàn xīn kǎ， jīn wǎn jiù néng zhèng cháng qù shí táng chī fàn。','Vậy giờ em làm lại thẻ mới, tối nay là có thể đi ăn cơm bình thường rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT713','SSH2','食堂错打不喜欢的菜品，询问能否免费更换菜品',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V713','SIT713','P1','twist','tuy_y',NULL,'食堂菜品盛出后无法回收更换，防止交叉污染、食品安全问题，点餐提前告知忌口是更稳妥的方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_01','V713','阮明',1,'阿姨，我不爱吃青椒，刚刚窗口误打了青椒炒肉，能换一份别的菜吗？','ā yí， wǒ bù ài chī qīng jiāo， gāng gāng chuāng kǒu wù dǎ le qīng jiāo chǎo ròu， néng huàn yī fèn bié de cài ma？','Cô ơi, con không ăn được ớt chuông, lúc nãy quầy múc nhầm cho con món thịt xào ớt chuông, đổi cho con món khác được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_02','V713','打菜阿姨',2,'已经盛到餐盘里的菜品，没法回收更换，会影响食品安全嘛。','yǐ jīng shèng dào cān pán lǐ de cài pǐn， méi fǎ huí shōu gēng huàn， huì yǐng xiǎng shí pǐn ān quán ma。','Món đã múc vào khay rồi thì không thu hồi đổi lại được đâu, sẽ ảnh hưởng đến an toàn thực phẩm đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_03','V713','阮明',3,'我一口都没动，只是拿到手才发现里面全是青椒。','wǒ yī kǒu dōu méi dòng， zhǐ shì ná dào shǒu cái fā xiàn lǐ miàn quán shì qīng jiāo。','Con chưa đụng vào miếng nào hết, chỉ là lúc cầm lên mới phát hiện toàn ớt chuông thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_04','V713','打菜阿姨',4,'未食用也不能退回，下次排队提前跟我说避开青椒菜品。','wèi shí yòng yě bù néng tuì huí， xià cì pái duì tí qián gēn wǒ shuō bì kāi qīng jiāo cài pǐn。','Chưa ăn cũng không trả lại được, lần sau xếp hàng thì nói trước với cô để tránh món có ớt chuông.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_05','V713','阮明',5,'那只能下次点餐提前说明忌口，这份我打包送给同学。','nà zhǐ néng xià cì diǎn cān tí qián shuō míng jì kǒu， zhè fèn wǒ dǎ bāo sòng gěi tóng xué。','Vậy chỉ còn cách lần sau gọi món báo trước món kiêng thôi, phần này con gói lại cho bạn ăn vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_06','V713','打菜阿姨',6,'下次点餐提前告知忌口食材，我给你单独打别的菜品。','xià cì diǎn cān tí qián gào zhī jì kǒu shí cái， wǒ gěi nǐ dān dú dǎ bié de cài pǐn。','Lần sau gọi món cứ báo trước nguyên liệu con kiêng, cô sẽ múc riêng món khác cho con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_07','V713','阮明',7,'我记住了，下次打菜提前说明不吃的食材。','wǒ jì zhù le， xià cì dǎ cài tí qián shuō míng bù chī de shí cái。','Con nhớ rồi ạ, lần sau lấy món con sẽ nói trước những gì con không ăn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT714','SSH2','校园奶茶店点单，询问甜度、冰度可选标准',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V714','SIT714','P1','suon_se','tuy_y',NULL,'国内奶茶饮品可自由调整甜度、冰量，基础小料大多免费添加，是茶饮店通用服务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_01','V714','阮明',1,'你好，一杯原味奶茶，甜度和冰度有几种选择呢？','nǐ hǎo， yī bēi yuán wèi nǎi chá， tián dù hé bīng dù yǒu jǐ zhǒng xuǎn zé ne？','Chào chị, cho em một ly trà sữa vị nguyên bản, độ ngọt với độ đá có mấy mức lựa chọn vậy chị?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_02','V714','店员',2,'甜度分无糖、三分糖、五分糖、七分糖、全糖五档哦。','tián dù fēn wú táng、 sān fēn táng、 wǔ fēn táng、 qī fēn táng、 quán táng wǔ dàng ó。','Độ ngọt có năm mức: không đường, ba phần đường, năm phần đường, bảy phần đường, và full đường nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_03','V714','阮明',3,'冰度常温、少冰、正常冰、去冰，全部都能选吗？','bīng dù cháng wēn、 shǎo bīng、 zhèng cháng bīng、 qù bīng， quán bù dōu néng xuǎn ma？','Vậy độ đá bình thường, ít đá, đá vừa, không đá, đều chọn được hết đúng không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_04','V714','店员',4,'是的，任意搭配，另外可以免费加珍珠、椰果两种小料。','shì de， rèn yì dā pèi， lìng wài kě yǐ miǎn fèi jiā zhēn zhū、 yē guǒ liǎng zhǒng xiǎo liào。','Đúng rồi, kết hợp thoải mái, với lại còn được thêm miễn phí trân châu hoặc thạch dừa nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_05','V714','阮明',5,'那五分糖、少冰，再加一份珍珠，麻烦帮我制作。','nà wǔ fēn táng、 shǎo bīng， zài jiā yī fèn zhēn zhū， má fán bāng wǒ zhì zuò。','Vậy cho em năm phần đường, ít đá, thêm một phần trân châu, phiền chị làm giúp em nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_06','V714','店员',6,'好的，一共八元，扫码付款后在取餐口等候就行。','hǎo de， yī gòng bā yuán， sǎo mǎ fù kuǎn hòu zài qǔ cān kǒu děng hòu jiù xíng。','Được rồi, tổng cộng tám tệ, em quét mã thanh toán rồi đợi ở chỗ lấy đồ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_07','V714','阮明',7,'好，我扫码支付，在这里等奶茶做好。','hǎo， wǒ sǎo mǎ zhī fù， zài zhè lǐ děng nǎi chá zuò hǎo。','Dạ được, em quét mã thanh toán, em đứng đây đợi trà sữa làm xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT715','SSH2','自带饭盒去食堂打包饭菜，咨询打包收费规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V715','SIT715','P1','suon_se','tuy_y',NULL,'国内倡导减少一次性塑料用品，自带饭盒打包可免收餐盒打包费，是校园食堂环保规定。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_01','V715','阮明',1,'您好，我自带饭盒打包饭菜，还要额外收取打包费吗？','nín hǎo， wǒ zì dài fàn hé dǎ bāo fàn cài， hái yào é wài shōu qǔ dǎ bāo fèi ma？','Chào anh/chị, em tự mang hộp cơm đi mua đồ ăn, vậy có bị tính thêm phí đóng gói không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_02','V715','工作人员',2,'自带容器不使用食堂一次性餐盒，免收打包费哈。','zì dài róng qì bù shǐ yòng shí táng yí cì xìng cān hé， miǎn shōu dǎ bāo fèi hā。','Tự mang hộp không dùng hộp dùng một lần của căng tin thì miễn phí đóng gói nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_03','V715','阮明',3,'要是忘记带饭盒，用食堂塑料盒打包多少钱一份？','yào shì wàng jì dài fàn hé， yòng shí táng sù liào hé dǎ bāo duō shǎo qián yī fèn？','Còn nếu lỡ quên mang hộp cơm, dùng hộp nhựa của căng tin thì bao nhiêu tiền một phần vậy ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_04','V715','工作人员',4,'一次性餐盒一元一个，筷子、塑料袋免费提供。','yí cì xìng cān hé yī yuán yí gè， kuài zi、 sù liào dài miǎn fèi tí gōng。','Hộp dùng một lần một tệ một cái, đũa với túi ni lông thì cho miễn phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_05','V715','阮明',5,'我以后每天带饭盒，既省钱也更环保。','wǒ yǐ hòu měi tiān dài fàn hé， jì shěng qián yě gèng huán bǎo。','Vậy từ nay em ngày nào cũng mang hộp cơm, vừa tiết kiệm vừa bảo vệ môi trường nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_06','V715','工作人员',6,'自带餐具打包我们十分鼓励，减少塑料垃圾。','zì dài cān jù dǎ bāo wǒ men shí fēn gǔ lì， jiǎn shǎo sù liào lā jī。','Tự mang hộp đựng đồ là chúng tôi khuyến khích lắm luôn, giảm được rác thải nhựa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_07','V715','阮明',7,'好，我每天自备饭盒来食堂打包饭菜。','hǎo， wǒ měi tiān zì bèi fàn hé lái shí táng dǎ bāo fàn cài。','Dạ, từ giờ ngày nào em cũng tự mang hộp cơm đến căng tin để đựng đồ ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT716','SSH2','食堂高峰期排队久，和同学交流错峰就餐时段',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V716','SIT716','P1','suon_se','tuy_y',NULL,'国内高校十二点是下课就餐最高峰，提前或延后半小时就餐可大幅缩短排队时长。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_01','V716','阮明',1,'中午十二点食堂人挤人，排队二十分钟才能打到饭啊。','zhōng wǔ shí èr diǎn shí táng rén jǐ rén， pái duì èr shí fēn zhōng cái néng dǎ dào fàn a。','Trưa mười hai giờ căng tin đông nghẹt người, xếp hàng hai chục phút mới lấy được cơm đó.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_02','V716','苏雯',2,'可以十一点四十提前下课去食堂，几乎不用排队呢。','kě yǐ shí yì diǎn sì shí tí qián xià kè qù shí táng， jī hū bù yòng pái duì ne。','Cậu có thể xin ra sớm lúc mười một giờ bốn mươi đi xuống căng tin, gần như không phải xếp hàng luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_03','V716','阮明',3,'要是上午有课走不开，下午一点再去是不是人很少？','yào shì shàng wǔ yǒu kè zǒu bù kāi， xià wǔ yì diǎn zài qù shì bú shì rén hěn shǎo？','Nếu sáng có tiết không đi được, chiều một giờ đi thì chắc ít người hơn nhỉ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_04','V716','苏雯',4,'一点大部分学生吃完回宿舍，窗口菜品选择也还算多。','yì diǎn dà bù fèn xué shēng chī wán huí sù shè， chuāng kǒu cài pǐn xuǎn zé yě hái suàn duō。','Một giờ thì phần lớn sinh viên ăn xong về ký túc xá rồi, các quầy món ăn vẫn còn khá nhiều lựa chọn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_05','V716','阮明',5,'那我分两种时段，早下课就提前去，晚下课一点再就餐。','nà wǒ fēn liǎng zhǒng shí duàn， zǎo xià kè jiù tí qián qù， wǎn xià kè yì diǎn zài jiù cān。','Vậy mình chia làm hai khung giờ, hôm nào ra sớm thì đi trước, hôm nào ra muộn thì một giờ mới ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_06','V716','苏雯',6,'避开十二点整的高峰，能节省很多排队等待时间。','bì kāi shí èr diǎn zhěng de gāo fēng， néng jié shěng hěn duō pái duì děng dài shí jiān。','Tránh đúng giờ cao điểm mười hai giờ trưa thì tiết kiệm được kha khá thời gian xếp hàng chờ đợi đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_07','V716','阮明',7,'我之后错开高峰，不用长时间排队等餐。','wǒ zhī hòu cuò kāi gāo fēng， bù yòng zhǎng shí jiān pái duì děng cān。','Từ giờ mình sẽ tránh giờ cao điểm, khỏi phải xếp hàng chờ ăn lâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT717','SSH2','咨询食堂清真窗口开放时间、菜品范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V717','SIT717','P1','suon_se','ban_chinh_thuc',NULL,'国内高校设有独立清真餐窗口，厨具、食材完全隔离，满足有饮食禁忌的学生就餐需求。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_01','V717','阮明',1,'您好，想咨询食堂清真窗口每日开放时段有哪些？','nín hǎo， xiǎng zī xún shí táng qīng zhēn chuāng kǒu měi rì kāi fàng shí duàn yǒu nǎ xiē？','Chào anh/chị, tôi muốn hỏi quầy đồ Halal của căng tin mở cửa vào những khung giờ nào trong ngày ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_02','V717','工作人员',2,'早七点至八点半早餐，十一点到十三点午餐，十七点半至十九点晚餐哦。','zǎo qī diǎn zhì bā diǎn bàn zǎo cān， shí yì diǎn dào shí sān diǎn wǔ cān， shí qī diǎn bàn zhì shí jiǔ diǎn wǎn cān ó。','Bảy giờ đến tám giờ rưỡi sáng là bữa sáng, mười một giờ đến mười ba giờ là bữa trưa, mười bảy giờ rưỡi đến mười chín giờ là bữa tối nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_03','V717','阮明',3,'清真窗口只供应牛羊肉、素食，完全不出现猪肉菜品对吧？','qīng zhēn chuāng kǒu zhǐ gōng yìng niú yáng ròu、 sù shí， wán quán bù chū xiàn zhū ròu cài pǐn duì ba？','Quầy Halal chỉ phục vụ thịt bò, thịt cừu và đồ chay, hoàn toàn không có món nào từ thịt heo phải không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_04','V717','工作人员',4,'没错，厨具、操作台独立分开，杜绝混炒普通菜品。','méi cuò， chú jù、 cāo zuò tái dú lì fēn kāi， dù jué hùn chǎo pǔ tōng cài pǐn。','Đúng vậy, dụng cụ nấu nướng và bàn chế biến đều tách riêng hoàn toàn, tuyệt đối không xào lẫn với món thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_05','V717','阮明',5,'明天早上我早点过来，去清真窗口吃早餐。','míng tiān zǎo shàng wǒ zǎo diǎn guò lái， qù qīng zhēn chuāng kǒu chī zǎo cān。','Sáng mai tôi sẽ đến sớm hơn, ra quầy Halal ăn sáng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_06','V717','工作人员',6,'窗口每日定时供应，太晚抵达会菜品售罄。','chuāng kǒu měi rì dìng shí gōng yìng， tài wǎn dǐ dá huì cài pǐn shòu qìng。','Quầy phục vụ theo giờ cố định mỗi ngày, đến quá muộn là hết món đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_07','V717','阮明',7,'我把控好时间，在窗口开放时段内就餐。','wǒ bǎ kòng hǎo shí jiān， zài chuāng kǒu kāi fàng shí duàn nèi jiù cān。','Tôi sẽ canh giờ cho chuẩn, đến ăn trong khung giờ quầy mở cửa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT718','SSH2','餐后忘记归还食堂餐盘，被工作人员提醒规范就餐',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V718','SIT718','P1','that_bai_nhe','tuy_y',NULL,'校园食堂餐盘、汤碗属于公共耗材，禁止带出就餐区域，餐后统一送至店内回收处是通用就餐规范。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_01','V718','阮明',1,'阿姨不好意思，吃完饭后我把餐盘直接带出食堂了，现在送回来。','ā yí bù hǎo yì sī， chī wán fàn hòu wǒ bǎ cān pán zhí jiē dài chū shí táng le， xiàn zài sòng huí lái。','Cô ơi cháu xin lỗi, ăn xong cháu lỡ mang luôn khay ra khỏi căng tin, giờ cháu mang trả lại đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_02','V718','保洁李阿姨',2,'食堂规定餐盘必须在店内回收台归还，不能带出就餐区嘛。','shí táng guī dìng cān pán bì xū zài diàn nèi huí shōu tái guī huán， bù néng dài chū jiù cān qū ma。','Căng tin quy định khay phải trả tại quầy thu hồi trong khu vực ăn uống, không được mang ra ngoài đâu nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_03','V718','阮明',3,'刚才着急赶课，一时忘记食堂就餐规定，下次一定注意。','gāng cái zháo jí gǎn kè， yī shí wàng jì shí táng jiù cān guī dìng， xià cì yí dìng zhù yì。','Lúc nãy cháu vội đi học nên nhất thời quên mất quy định của căng tin, lần sau cháu sẽ chú ý ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_04','V718','保洁李阿姨',4,'餐盘餐具外流容易丢失、破损，增加食堂耗材成本。','cān pán cān jù wài liú róng yì diū shī、 pò sǔn， zēng jiā shí táng hào cái chéng běn。','Khay với dụng cụ ăn bị mang ra ngoài dễ bị mất, bị vỡ, làm tăng chi phí vật tư của căng tin lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_05','V718','阮明',5,'我之后吃完立刻送到回收台，绝不带出食堂大门。','wǒ zhī hòu chī wán lì kè sòng dào huí shōu tái， jué bù dài chū shí táng dà mén。','Sau này ăn xong cháu sẽ mang trả ngay tại quầy thu hồi, tuyệt đối không mang ra khỏi cổng căng tin nữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_06','V718','保洁李阿姨',6,'记住规则就好，下次不用再特意送回来。','jì zhù guī zé jiù hǎo， xià cì bù yòng zài tè yì sòng huí lái。','Nhớ quy định là được rồi, lần sau không cần cố tình mang trả lại như vậy đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_07','V718','阮明',7,'十分抱歉给您增加额外工作，我严格遵守食堂规定。','shí fēn bào qiàn gěi nín zēng jiā é wài gōng zuò， wǒ yán gé zūn shǒu shí táng guī dìng。','Cháu thật sự xin lỗi vì đã làm phiền cô thêm việc, cháu sẽ tuân thủ nghiêm quy định của căng tin ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT719','SSH3','图书馆办理借阅证，学习图书借还、逾期罚款规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V719','SIT719','P1','suon_se','ban_chinh_thuc',NULL,'国内高校图书馆图书超期会收取每日罚金，逾期过久会暂停借阅权限，直至缴清罚款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_01','V719','阮明',1,'老师您好，我是新生留学生，前来办理图书馆借阅证件。','lǎo shī nín hǎo， wǒ shì xīn shēng liú xué shēng， qián lái bàn lǐ tú shū guǎn jiè yuè zhèng jiàn。','Chào thầy/cô, em là sinh viên quốc tế mới, em đến làm thẻ thư viện ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_02','V719','馆员王老师',2,'出示学生证、护照，登记信息后绑定校园卡就能借书哦。','chū shì xué shēng zhèng、 hù zhào， dēng jì xìn xī hòu bǎng dìng xiào yuán kǎ jiù néng jiè shū ó。','Em xuất trình thẻ sinh viên, hộ chiếu, đăng ký thông tin xong rồi liên kết với thẻ sinh viên là mượn sách được nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_03','V719','阮明',3,'单次最多能借几本书，最长借阅期限是多少天？','dān cì zuì duō néng jiè jǐ běn shū， zuì zhǎng jiè yuè qī xiàn shì duō shǎo tiān？','Mỗi lần được mượn tối đa bao nhiêu cuốn ạ, thời hạn mượn lâu nhất là bao nhiêu ngày?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_04','V719','馆员王老师',4,'一次六本，三十天借阅期，可线上续借一次延长十五天。','yī cì liù běn， sān shí tiān jiè yuè qī， kě xiàn shàng xù jiè yī cì yán cháng shí wǔ tiān。','Mỗi lần sáu cuốn, thời hạn mượn ba mươi ngày, có thể gia hạn online một lần thêm mười lăm ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_05','V719','阮明',5,'超过三十天未续借，每天会产生多少逾期罚款呢？','chāo guò sān shí tiān wèi xù jiè， měi tiān huì chǎn shēng duō shǎo yú qī fá kuǎn ne？','Nếu quá ba mươi ngày mà không gia hạn thì mỗi ngày bị phạt bao nhiêu tiền ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_06','V719','馆员王老师',6,'每本书每日零点一元罚款，超期越久费用累加越高。','měi běn shū měi rì líng diǎn yī yuán fá kuǎn， chāo qī yuè jiǔ fèi yòng lěi jiā yuè gāo。','Mỗi cuốn bị phạt không phẩy một tệ một ngày, càng để lâu thì tiền phạt càng cộng dồn nhiều lên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_07','V719','阮明',7,'我会按时续借或者归还，避免产生逾期罚金。','wǒ huì àn shí xù jiè huò zhě guī huán， bì miǎn chǎn shēng yú qī fá jīn。','Em sẽ gia hạn hoặc trả sách đúng hạn, để tránh bị phạt quá hạn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT720','SSH3','图书馆自习座位被占，咨询管理员占座管理规定',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V720','SIT720','P1','twist','ban_chinh_thuc',NULL,'图书馆严禁用书、水杯长期霸占自习座位，临时离开超过一小时管理员会清理占位物品，保障座位公平使用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_01','V720','阮明',1,'您好，这个自习座位放着书本一整天没人，我可以坐这里吗？','nín hǎo， zhè ge zì xí zuò wèi fàng zhe shū běn yī zhěng tiān méi rén， wǒ kě yǐ zuò zhè lǐ ma？','Chào anh/chị, cái ghế tự học này để sách cả ngày mà không thấy ai ngồi, tôi ngồi đây được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_02','V720','管理员',2,'图书馆禁止长期占座，离开超过一小时物品会统一清收。','tú shū guǎn jìn zhǐ cháng qī zhàn zuò， lí kāi chāo guò yī xiǎo shí wù pǐn huì tǒng yī qīng shōu。','Thư viện cấm chiếm chỗ lâu dài, rời khỏi chỗ quá một tiếng là đồ đạc sẽ bị thu gom hết đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_03','V720','阮明',3,'书本、水杯全都留在桌面，座位空了整整一下午嘛。','shū běn、 shuǐ bēi quán dōu liú zài zhuō miàn， zuò wèi kōng le zhěng zhěng yī xià wǔ ma。','Sách vở, cốc nước để nguyên trên bàn, chỗ ngồi trống suốt cả buổi chiều luôn mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_04','V720','管理员',4,'我先把占位物品收到失物存放区，你可以正常使用这个座位。','wǒ xiān bǎ zhàn wèi wù pǐn shōu dào shī wù cún fàng qū， nǐ kě yǐ zhèng cháng shǐ yòng zhè ge zuò wèi。','Tôi sẽ thu đồ chiếm chỗ đó vào khu lưu giữ đồ thất lạc trước, bạn có thể sử dụng chỗ này bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_05','V720','阮明',5,'那物品主人回来，去哪里领取自己的书本、水杯？','nà wù pǐn zhǔ rén huí lái， qù nǎ lǐ lǐng qǔ zì jǐ de shū běn、 shuǐ bēi？','Vậy khi chủ nhân đồ đạc quay lại thì họ lấy lại sách vở, cốc nước ở đâu ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_06','V720','管理员',6,'一楼服务台报姓名、物品特征就能取回存放物品。','yī lóu fú wù tái bào xìng míng、 wù pǐn tè zhēng jiù néng qǔ huí cún fàng wù pǐn。','Xuống quầy dịch vụ ở tầng một, nói tên và đặc điểm đồ vật là lấy lại được ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_07','V720','阮明',7,'我以后临时离开自习室，随身带走全部私人物品。','wǒ yǐ hòu lín shí lí kāi zì xí shì， suí shēn dài zǒu quán bù sī rén wù pǐn。','Sau này tôi rời phòng tự học tạm thời sẽ mang theo hết đồ cá nhân của mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT721','SSH3','图书馆电脑无法登录校园内网，求助值班管理员',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V721','SIT721','P1','suon_se','tuy_y',NULL,'校园内网会定期服务器维护，维护期间图书馆电脑无法访问校内论文数据库，属于常规网络维护安排。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_01','V721','阮明',1,'你好，图书馆台式机输入学号，一直登录不上校园内网啊。','nǐ hǎo， tú shū guǎn tái shì jī shū rù xué hào， yì zhí dēng lù bù shàng xiào yuán nèi wǎng a。','Chào anh, máy tính bàn ở thư viện tôi nhập mã số sinh viên mà cứ đăng nhập mãi không vào được mạng nội bộ trường đó.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_02','V721','管理员',2,'是不是校园网账号欠费停机，或者密码输入错误呢？','shì bú shì xiào yuán wǎng zhàng hào qiàn fèi tíng jī， huò zhě mì mǎ shū rù cuò wù ne？','Có phải tài khoản mạng trường bị nợ phí nên bị khóa, hay là bạn nhập sai mật khẩu không?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_03','V721','阮明',3,'昨天还正常登录查阅文献，没有修改过账号密码。','zuó tiān hái zhèng cháng dēng lù chá yuè wén xiàn， méi yǒu xiū gǎi guò zhàng hào mì mǎ。','Hôm qua tôi vẫn đăng nhập bình thường để tra tài liệu mà, cũng đâu có đổi mật khẩu tài khoản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_04','V721','管理员',4,'今天校内服务器临时维护，部分电脑网络不稳定。','jīn tiān xiào nèi fú wù qì lín shí wéi hù， bù fèn diàn nǎo wǎng luò bù wěn dìng。','Hôm nay máy chủ trong trường đang bảo trì tạm thời, nên một số máy tính mạng không ổn định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_05','V721','阮明',5,'那大概多久恢复内网访问，我需要查阅专业论文。','nà dà gài duō jiǔ huī fù nèi wǎng fǎng wèn， wǒ xū yào chá yuè zhuān yè lùn wén。','Vậy khoảng bao lâu thì mạng nội bộ khôi phục lại, tôi đang cần tra luận văn chuyên ngành gấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_06','V721','管理员',6,'预计四十分钟维护结束，你可以先用手机流量临时查资料。','yù jì sì shí fēn zhōng wéi hù jié shù， nǐ kě yǐ xiān yòng shǒu jī liú liàng lín shí chá zī liào。','Dự kiến bốn mươi phút nữa bảo trì xong, bạn cứ dùng tạm 4G điện thoại để tra tài liệu trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_07','V721','阮明',7,'我先等服务器维护完成，再使用电脑下载文献。','wǒ xiān děng fú wù qì wéi hù wán chéng， zài shǐ yòng diàn nǎo xià zài wén xiàn。','Vậy tôi đợi máy chủ bảo trì xong rồi mới dùng máy tính tải tài liệu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT722','SSH3','借阅书籍超期，咨询罚款标准、补缴流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V722','SIT722','P1','that_bai_nhe','ban_chinh_thuc',NULL,'图书逾期罚金必须线下结清，未缴清罚款会永久限制图书借阅、数据库使用权限。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_01','V722','阮明',1,'老师，我借阅的两本专业书忘记续借，已经超期八天了。','lǎo shī， wǒ jiè yuè de liǎng běn zhuān yè shū wàng jì xù jiè， yǐ jīng chāo qī bā tiān le。','Thầy/cô ơi, em mượn hai cuốn sách chuyên ngành mà quên gia hạn, giờ đã quá hạn tám ngày rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_02','V722','馆员王老师',2,'先把图书归还，系统自动核算每日逾期罚款金额。','xiān bǎ tú shū guī huán， xì tǒng zì dòng hé suàn měi rì yú qī fá kuǎn jīn é。','Em trả sách trước đã, hệ thống sẽ tự tính số tiền phạt quá hạn theo ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_03','V722','阮明',3,'两本书分开计算罚金，还是合并统一收取费用？','liǎng běn shū fēn kāi jì suàn fá jīn， hái shì hé bìng tǒng yī shōu qǔ fèi yòng？','Hai cuốn sách tính tiền phạt riêng hay là gộp chung lại thu một lần ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_04','V722','馆员王老师',4,'每本单独计费，两本书八天一共十六元逾期罚金嘛。','měi běn dān dú jì fèi， liǎng běn shū bā tiān yī gòng shí liù yuán yú qī fá jīn ma。','Mỗi cuốn tính riêng, hai cuốn tám ngày là mười sáu tệ tiền phạt quá hạn đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_05','V722','阮明',5,'罚金只能线下在图书馆服务台扫码缴纳，不能线上支付吗？','fá jīn zhǐ néng xiàn xià zài tú shū guǎn fú wù tái sǎo mǎ jiǎo nà， bù néng xiàn shàng zhī fù ma？','Tiền phạt chỉ có thể quét mã nộp trực tiếp tại quầy thư viện thôi ạ, không thanh toán online được sao?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_06','V722','馆员王老师',6,'仅支持线下现场缴费，缴清罚金才能恢复借阅权限。','jǐn zhī chí xiàn xià xiàn chǎng jiǎo fèi， jiǎo qīng fá jīn cái néng huī fù jiè yuè quán xiàn。','Chỉ nộp trực tiếp tại chỗ thôi, nộp hết tiền phạt rồi mới khôi phục lại quyền mượn sách được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_07','V722','阮明',7,'我现在扫码缴纳罚金，之后一定记好续借日期。','wǒ xiàn zài sǎo mǎ jiǎo nà fá jīn， zhī hòu yí dìng jì hǎo xù jiè rì qī。','Vậy em quét mã nộp phạt ngay bây giờ, sau này em nhớ kỹ ngày gia hạn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT723','SSH3','图书馆打印复印设备卡纸，找工作人员维修',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V723','SIT723','P1','suon_se','tuy_y',NULL,'自助打印设备卡纸禁止用户自行拆机拉扯纸张，容易造成硬件损坏，需工作人员专业处理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_01','V723','阮明',1,'你好，自助复印机打印到一半卡纸，纸张卡在机器里面了。','nǐ hǎo， zì zhù fù yìn jī dǎ yìn dào yí bàn kǎ zhǐ， zhǐ zhāng kǎ zài jī qì lǐ miàn le。','Chào anh, máy photocopy tự động đang in nửa chừng thì bị kẹt giấy, giấy kẹt cứng trong máy luôn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_02','V723','运维工作人员',2,'别手动拉扯纸张，容易损坏打印机内部齿轮。','bié shǒu dòng lā chě zhǐ zhāng， róng yì sǔn huài dǎ yìn jī nèi bù chǐ lún。','Đừng tự kéo giấy ra nhé, làm vậy dễ hỏng bánh răng bên trong máy in lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_03','V723','阮明',3,'我只是按了停止键，没有强行拽取卡住的打印纸。','wǒ zhǐ shì àn le tíng zhǐ jiàn， méi yǒu qiáng xíng zhuāi qǔ kǎ zhù de dǎ yìn zhǐ。','Tôi chỉ bấm nút dừng thôi, không có cố kéo tờ giấy bị kẹt ra đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_04','V723','运维工作人员',4,'我打开机盖取出卡纸，清理之后就能恢复打印啦。','wǒ dǎ kāi jī gài qǔ chū kǎ zhǐ， qīng lǐ zhī hòu jiù néng huī fù dǎ yìn la。','Để tôi mở nắp máy lấy giấy kẹt ra, dọn xong là in lại bình thường thôi mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_05','V723','阮明',5,'刚才已经扣取打印费用，卡纸没有完整出纸会返还余额吗？','gāng cái yǐ jīng kòu qǔ dǎ yìn fèi yòng， kǎ zhǐ méi yǒu wán zhěng chū zhǐ huì fǎn huán yú é ma？','Lúc nãy tiền in đã bị trừ rồi, giấy kẹt không ra được trọn vẹn thì có được hoàn lại tiền không vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_06','V723','运维工作人员',6,'单次卡纸未出纸，系统自动退还本次打印扣费。','dān cì kǎ zhǐ wèi chū zhǐ， xì tǒng zì dòng tuì huán běn cì dǎ yìn kòu fèi。','Kẹt giấy mà không ra được trang nào thì hệ thống sẽ tự động hoàn lại tiền in lần đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_07','V723','阮明',7,'麻烦您检修机器，我等下继续打印复习资料。','má fán nín jiǎn xiū jī qì， wǒ děng xià jì xù dǎ yìn fù xí zī liào。','Phiền anh sửa máy giúp tôi, lát nữa tôi in tiếp tài liệu ôn tập.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT724','SSH3','自习到闭馆时间，咨询夜间留校自习申请渠道',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V724','SIT724','P1','twist','ban_chinh_thuc',NULL,'图书馆夜间统一闭馆安保巡查，国内高校单独设置通宵自习教室满足期末备考学生需求。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_01','V724','阮明',1,'距离期末考还有两周，图书馆九点闭馆太早，想夜间留校自习。','jù lí qī mò kǎo hái yǒu liǎng zhōu， tú shū guǎn jiǔ diǎn bì guǎn tài zǎo， xiǎng yè jiān liú xiào zì xí。','Còn hai tuần nữa là thi cuối kỳ rồi, mà thư viện đóng cửa lúc chín giờ tối thì sớm quá, em muốn ở lại trường tự học ban đêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_02','V724','管理员',2,'图书馆晚间九点统一闭馆，不允许学生留在馆内过夜自习。','tú shū guǎn wǎn jiān jiǔ diǎn tǒng yī bì guǎn， bù yǔn xǔ xué shēng liú zài guǎn nèi guò yè zì xí。','Thư viện quy định đóng cửa thống nhất lúc chín giờ tối, không cho phép sinh viên ở lại qua đêm tự học đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_03','V724','阮明',3,'有没有专门通宵自习教室，或者申请延长图书馆开放时间？','yǒu méi yǒu zhuān mén tōng xiāo zì xí jiào shì， huò zhě shēn qǐng yán cháng tú shū guǎn kāi fàng shí jiān？','Vậy có phòng tự học thâu đêm riêng không, hoặc có thể xin gia hạn giờ mở cửa thư viện không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_04','V724','管理员',4,'教学楼有两间通宵自习室，图书馆无延时开放审批通道嘛。','jiào xué lóu yǒu liǎng jiān tōng xiāo zì xí shì， tú shū guǎn wú yán shí kāi fàng shěn pī tōng dào ma。','Tòa nhà giảng đường có hai phòng tự học thâu đêm, còn thư viện thì không có kênh xin gia hạn giờ mở cửa đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_05','V724','阮明',5,'教学楼通宵教室晚上十一点之后还能正常开灯自习吗？','jiào xué lóu tōng xiāo jiào shì wǎn shàng shí yì diǎn zhī hòu hái néng zhèng cháng kāi dēng zì xí ma？','Vậy phòng tự học thâu đêm ở giảng đường sau mười một giờ đêm vẫn bật đèn học bình thường được chứ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_06','V724','管理员',6,'全天供电，门禁可刷校园卡二十四小时自由进出。','quán tiān gōng diàn， mén jìn kě shuā xiào yuán kǎ èr shí sì xiǎo shí zì yóu jìn chū。','Cấp điện cả ngày, chỉ cần quẹt thẻ sinh viên là ra vào tự do hai mươi bốn tiếng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_07','V724','阮明',7,'今晚开始转移到教学楼通宵教室复习备考。','jīn wǎn kāi shǐ zhuǎn yí dào jiào xué lóu tōng xiāo jiào shì fù xí bèi kǎo。','Vậy từ tối nay em chuyển sang phòng tự học thâu đêm ở giảng đường để ôn thi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT725','SSH3','借阅外文专业参考书，咨询馆员查找馆藏方法',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V725','SIT725','P1','suon_se','ban_chinh_thuc',NULL,'高校图书馆外文藏书单独分区管理，为保护原版书籍，不开放学生自行入内取阅，由馆员统一调取。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_01','V725','阮明',1,'老师，我需要越南语原版专业参考书，不知道怎么检索馆藏。','lǎo shī， wǒ xū yào yuè nán yǔ yuán bǎn zhuān yè cān kǎo shū， bù zhī dào zěn me jiǎn suǒ guǎn cáng。','Thưa cô, em cần tìm sách tham khảo chuyên ngành bản gốc tiếng Việt, nhưng không biết tra cứu kho sách kiểu gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_02','V725','馆员王老师',2,'图书馆检索系统左上角切换外文分类，输入语种关键词即可。','tú shū guǎn jiǎn suǒ xì tǒng zuǒ shàng jiǎo qiè huàn wài wén fēn lèi， shū rù yǔ zhǒng guān jiàn cí jí kě。','Ở góc trên bên trái hệ thống tra cứu của thư viện có mục chuyển sang phân loại sách ngoại văn, em nhập từ khóa ngôn ngữ vào là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_03','V725','阮明',3,'检索出来显示在三楼外文馆藏区，需要凭借阅证入内取书对吧？','jiǎn suǒ chū lái xiǎn shì zài sān lóu wài wén guǎn cáng qū， xū yào píng jiè yuè zhèng rù nèi qǔ shū duì ba？','Tra ra thì thấy hiển thị ở khu sách ngoại văn tầng ba, vậy em cần dùng thẻ mượn sách mới vào lấy được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_04','V725','馆员王老师',4,'外文图书区域不对外开放自由取书，报书名由我调取。','wài wén tú shū qū yù bú duì wài kāi fàng zì yóu qǔ shū， bào shū míng yóu wǒ diào qǔ。','Khu sách ngoại văn không mở cho sinh viên tự vào lấy sách đâu, em báo tên sách để cô lấy giúp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_05','V725','阮明',5,'那我把书籍编号发给您，麻烦帮忙调取这本参考书。','nà wǒ bǎ shū jí biān hào fā gěi nín， má fán bāng máng diào qǔ zhè běn cān kǎo shū。','Vậy em gửi cô mã số sách nhé, phiền cô lấy giúp em cuốn sách tham khảo này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_06','V725','馆员王老师',6,'十分钟内找到书籍，你在服务台等候领取。','shí fēn zhōng nèi zhǎo dào shū jí， nǐ zài fú wù tái děng hòu lǐng qǔ。','Trong mười phút cô sẽ tìm được sách, em ra quầy dịch vụ đợi lấy nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_07','V725','阮明',7,'好，我在这里等候，感谢协助查找外文藏书。','hǎo， wǒ zài zhè lǐ děng hòu， gǎn xiè xié zhù chá zhǎo wài wén cáng shū。','Dạ vâng, em đứng đây đợi, cảm ơn cô đã giúp tìm sách ngoại văn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT726','SSH4','办理校园统一公交优惠学生卡，提交证件材料',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V726','SIT726','P1','suon_se','ban_chinh_thuc',NULL,'国内在校学生可办理公交学生卡，市内通勤公交享受半价优惠，长途客运不参与学生折扣政策。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_01','V726','阮明',1,'老师您好，想办理公交学生优惠卡，出门乘坐公交半价乘车。','lǎo shī nín hǎo， xiǎng bàn lǐ gōng jiāo xué shēng yōu huì kǎ， chū mén chéng zuò gōng jiāo bàn jià chéng chē。','Thưa cô, em muốn làm thẻ ưu đãi xe buýt cho sinh viên, để đi xe buýt được giảm nửa giá ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_02','V726','办事老师',2,'准备好护照、学生证、一寸证件照，填写办卡申请表哦。','zhǔn bèi hǎo hù zhào、 xué shēng zhèng、 yī cùn zhèng jiàn zhào， tián xiě bàn kǎ shēn qǐng biǎo ó。','Em chuẩn bị sẵn hộ chiếu, thẻ sinh viên, ảnh thẻ cỡ một inch, rồi điền vào đơn đăng ký làm thẻ nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_03','V726','阮明',3,'办好公交卡，全市所有公交线路都能享受学生折扣吗？','bàn hǎo gōng jiāo kǎ， quán shì suǒ yǒu gōng jiāo xiàn lù dōu néng xiǎng shòu xué shēng zhé kòu ma？','Làm xong thẻ xe buýt rồi thì tất cả các tuyến xe buýt trong thành phố đều được hưởng ưu đãi sinh viên đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_04','V726','办事老师',4,'市内常规公交全部半价，长途城际公交不适用优惠。','shì nèi cháng guī gōng jiāo quán bù bàn jià， cháng tú chéng jì gōng jiāo bù shì yòng yōu huì。','Xe buýt thường trong nội thành thì được giảm nửa giá hết, còn xe buýt liên tỉnh đường dài thì không áp dụng ưu đãi đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_05','V726','阮明',5,'公交卡丢失可以挂失转移余额，和校园饭卡规则一样？','gōng jiāo kǎ diū shī kě yǐ guà shī zhuǎn yí yú é， hé xiào yuán fàn kǎ guī zé yī yàng？','Nếu thẻ xe buýt bị mất thì có thể báo mất và chuyển số dư sang thẻ mới, giống quy định của thẻ ăn trong trường không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_06','V726','办事老师',6,'没错，携带证件到服务中心挂失补办，余额完整保留。','méi cuò， xié dài zhèng jiàn dào fú wù zhōng xīn guà shī bǔ bàn， yú é wán zhěng bǎo liú。','Đúng rồi, em mang giấy tờ đến trung tâm dịch vụ báo mất và làm lại thẻ, số dư sẽ được giữ nguyên đầy đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_07','V726','阮明',7,'我备齐材料，今天办理学生公交优惠卡。','wǒ bèi qí cái liào， jīn tiān bàn lǐ xué shēng gōng jiāo yōu huì kǎ。','Em chuẩn bị đủ giấy tờ rồi, hôm nay em làm thẻ ưu đãi xe buýt sinh viên luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT727','SSH4','共享单车扫码失败、车辆故障，咨询换车流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V727','SIT727','P1','twist','tuy_y',NULL,'共享单车故障车辆免费换车，短时间内切换新车不重复收取起步费用，是平台通用售后规则。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_01','V727','阮明',1,'师傅，这辆单车扫码开锁一直失败，页面提示车辆故障啊。','shī fù， zhè liàng dān chē sǎo mǎ kāi suǒ yì zhí shī bài， yè miàn tí shì chē liàng gù zhàng a。','Anh ơi, chiếc xe đạp này quét mã mở khóa mãi không được, màn hình báo xe bị hỏng ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_02','V727','运维员',2,'故障车辆后台锁定无法解锁，直接在APP点更换车辆按钮。','gù zhàng chē liàng hòu tái suǒ dìng wú fǎ jiě suǒ， zhí jiē zài APP diǎn gēng huàn chē liàng àn niǔ。','Xe hỏng thì hệ thống đã khóa lại rồi, không mở khóa được đâu, em cứ vào app bấm nút đổi xe khác là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_03','V727','阮明',3,'换车会不会重复收取骑行起步费，两辆车分开计费吗？','huàn chē huì bú huì chóng fù shōu qǔ qí xíng qǐ bù fèi， liǎng liàng chē fēn kāi jì fèi ma？','Đổi xe thì có bị tính lại phí mở chuyến không, hai xe có tính tiền riêng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_04','V727','运维员',4,'故障换车十分钟内切换新车，不会二次扣费，自动取消订单嘛。','gù zhàng huàn chē shí fēn zhōng nèi qiè huàn xīn chē， bú huì èr cì kòu fèi， zì dòng qǔ xiāo dìng dān ma。','Đổi xe do hỏng trong vòng mười phút thì chuyển sang xe mới thôi, không bị trừ tiền lần hai đâu, đơn cũ tự động hủy mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_05','V727','阮明',5,'那我直接换旁边完好单车，不用手动结束当前订单？','nà wǒ zhí jiē huàn páng biān wán hǎo dān chē， bù yòng shǒu dòng jié shù dāng qián dìng dān？','Vậy em cứ đổi luôn sang chiếc xe nguyên vẹn bên cạnh, không cần tự tay kết thúc đơn hiện tại đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_06','V727','运维员',6,'APP一键换车系统自动处理，不用额外操作订单。','APP yī jiàn huàn chē xì tǒng zì dòng chǔ lǐ， bù yòng é wài cāo zuò dìng dān。','App có nút đổi xe một chạm, hệ thống tự xử lý hết, em không cần thao tác thêm gì với đơn đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_07','V727','阮明',7,'我现在操作更换车辆，正常骑行前往教学楼。','wǒ xiàn zài cāo zuò gēng huàn chē liàng， zhèng cháng qí xíng qián wǎng jiào xué lóu。','Vậy giờ em thao tác đổi xe, rồi đạp bình thường đến giảng đường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT728','SSH4','校内电动车限速规定，被安保提醒减速慢行',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V728','SIT728','P1','that_bai_nhe','tuy_y',NULL,'国内大学校园非机动车统一低速限速，保护步行学生安全，多次超速会暂扣车辆进行安全教育。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_01','V728','阮明',1,'保安大叔，怎么拦下我，是电动车行驶有违规地方吗？','bǎo ān dà shū， zěn me lán xià wǒ， shì diàn dòng chē háng shǐ yǒu wéi guī dì fāng ma？','Chú bảo vệ ơi, sao chú chặn cháu lại vậy, xe điện cháu chạy có vi phạm gì à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_02','V728','安保大叔',2,'校内道路限速十五公里每小时，你车速过快存在安全隐患。','xiào nèi dào lù xiàn sù shí wǔ gōng lǐ měi xiǎo shí， nǐ chē sù guò kuài cún zài ān quán yǐn huàn。','Đường trong trường giới hạn tốc độ mười lăm km một giờ, cháu chạy nhanh quá là có nguy cơ mất an toàn đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_03','V728','阮明',3,'我赶去上课没留意限速标识，没有注意控制骑行速度嘛。','wǒ gǎn qù shàng kè méi liú yì xiàn sù biāo shí， méi yǒu zhù yì kòng zhì qí xíng sù dù ma。','Cháu vội đi học nên không để ý biển giới hạn tốc độ, không chú ý kiểm soát tốc độ luôn ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_04','V728','安保大叔',4,'校园行人多，电动车超速容易撞到散步、赶路的学生。','xiào yuán xíng rén duō， diàn dòng chē chāo sù róng yì zhuàng dào sàn bù、 gǎn lù de xué shēng。','Trong trường người đi bộ đông, xe điện chạy quá tốc độ dễ va phải mấy bạn đang đi dạo hay đang vội đi học lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_05','V728','阮明',5,'第一次超速提醒，会不会扣除校园通行积分或者罚款？','dì yī cì chāo sù tí xǐng， huì bú huì kòu chú xiào yuán tōng xíng jī fēn huò zhě fá kuǎn？','Lần đầu bị nhắc vượt tốc độ như này thì có bị trừ điểm ra vào trường hay bị phạt tiền không chú?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_06','V728','安保大叔',6,'首次口头警告，多次超速会暂扣电动车半天教育。','shǒu cì kǒu tóu jǐng gào， duō cì chāo sù huì zàn kòu diàn dòng chē bàn tiān jiào yù。','Lần đầu thì chỉ nhắc nhở bằng miệng thôi, chạy quá tốc độ nhiều lần thì bị tạm giữ xe điện nửa ngày để giáo dục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_07','V728','阮明',7,'之后在校内骑行放慢车速，严格遵守限速规定。','zhī hòu zài xiào nèi qí xíng fàng màn chē sù， yán gé zūn shǒu xiàn sù guī dìng。','Vậy sau này cháu sẽ chạy chậm lại trong trường, tuân thủ nghiêm giới hạn tốc độ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT729','SSH4','快递驿站取件忘记取件码，凭护照核对身份取件',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V729','SIT729','P1','suon_se','tuy_y',NULL,'快递驿站可凭实名有效证件核对身份取件，不止局限于短信取件码，方便遗失短信的顾客。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_01','V729','阮明',1,'你好，我网购的快递到驿站，但是手机弄丢取件短信码了。','nǐ hǎo， wǒ wǎng gòu de kuài dì dào yì zhàn， dàn shì shǒu jī nòng diū qǔ jiàn duǎn xìn mǎ le。','Chào chị, em có kiện hàng mua online gửi về điểm tập kết, nhưng em làm mất tin nhắn mã lấy hàng rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_02','V729','驿站店员',2,'报你的收件姓名、手机号，出示有效证件就能核对包裹。','bào nǐ de shōu jiàn xìng míng、 shǒu jī hào， chū shì yǒu xiào zhèng jiàn jiù néng hé duì bāo guǒ。','Em cho chị tên người nhận, số điện thoại, xuất trình giấy tờ hợp lệ là chị kiểm tra được gói hàng thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_03','V729','阮明',3,'我出示留学生护照，上面有我的姓名拼音可以核对身份吗？','wǒ chū shì liú xué shēng hù zhào， shàng miàn yǒu wǒ de xìng míng pīn yīn kě yǐ hé duì shēn fèn ma？','Em xuất trình hộ chiếu du học sinh, trên đó có tên phiên âm của em, vậy có đối chiếu được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_04','V729','驿站店员',4,'可以，姓名、手机号匹配无误就能直接找出快递包裹。','kě yǐ， xìng míng、 shǒu jī hào pǐ pèi wú wù jiù néng zhí jiē zhǎo chū kuài dì bāo guǒ。','Được chứ, tên và số điện thoại khớp là chị tìm ra ngay gói hàng cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_05','V729','阮明',5,'麻烦帮我查找今天送达的小件包裹，是学习文具。','má fán bāng wǒ chá zhǎo jīn tiān sòng dá de xiǎo jiàn bāo guǒ， shì xué xí wén jù。','Phiền chị tìm giúp em kiện hàng nhỏ gửi đến hôm nay, là đồ dùng học tập ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_06','V729','驿站店员',6,'查到了，这个快递，你核对包裹面单信息再拿走。','chá dào le， zhè ge kuài dì， nǐ hé duì bāo guǒ miàn dān xìn xī zài ná zǒu。','Tìm thấy rồi nè, kiện hàng này, em kiểm tra lại thông tin trên mặt đơn rồi mang về nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_07','V729','阮明',7,'信息全部匹配，感谢不用取件码也能取件。','xìn xī quán bù pǐ pèi， gǎn xiè bù yòng qǔ jiàn mǎ yě néng qǔ jiàn。','Thông tin khớp hết rồi ạ, cảm ơn chị, không cần mã lấy hàng vẫn nhận được hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT730','SSH4','大件快递无法上楼，和驿站协商送货上门服务',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V730','SIT730','P1','twist','ban_chinh_thuc',NULL,'校园快递驿站以自取为主，大件重物单独上门配送会收取少量配送服务费，用于补贴人工运力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_01','V730','阮明',1,'我这个纸箱是被褥大件，楼梯没有电梯，自己搬不动上楼。','wǒ zhè ge zhǐ xiāng shì bèi rù dà jiàn， lóu tī méi yǒu diàn tī， zì jǐ bān bù dòng shàng lóu。','Cái thùng này của em là chăn đệm cỡ lớn, cầu thang lại không có thang máy, em tự khiêng lên không nổi đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_02','V730','驿站店员',2,'校园驿站规定小件自取，大件上门需要额外支付配送服务费。','xiào yuán yì zhàn guī dìng xiǎo jiàn zì qǔ， dà jiàn shàng mén xū yào é wài zhī fù pèi sòng fú wù fèi。','Điểm tập kết trong trường quy định hàng nhỏ tự lấy, còn hàng cồng kềnh muốn giao tận nơi thì phải trả thêm phí dịch vụ giao hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_03','V730','阮明',3,'宿舍就在校内宿舍楼，距离驿站步行三分钟也要额外收费嘛？','sù shè jiù zài xiào nèi sù shè lóu， jù lí yì zhàn bù xíng sān fēn zhōng yě yào é wài shōu fèi ma？','Ký túc xá em ở ngay trong khu ký túc xá trong trường, đi bộ ba phút là tới điểm tập kết mà cũng phải tính thêm phí à chị?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_04','V730','驿站店员',4,'配送人员批量派送楼栋，单独上门单件加收三元配送费嘛。','pèi sòng rén yuán pī liàng pài sòng lóu dòng， dān dú shàng mén dān jiàn jiā shōu sān yuán pèi sòng fèi ma。','Nhân viên giao hàng theo tòa nhà theo đợt, còn giao riêng từng đơn tận nơi thì phụ thu thêm ba đồng phí giao hàng đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_05','V730','阮明',5,'那我今天下午有空，能不能傍晚统一顺路送货上门？','nà wǒ jīn tiān xià wǔ yǒu kòng， néng bù néng bàng wǎn tǒng yī shùn lù sòng huò shàng mén？','Vậy chiều nay em rảnh, chị có thể sắp xếp giao tận nơi luôn vào buổi tối tiện đường không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_06','V730','驿站店员',6,'傍晚六点批量配送，你留好宿舍房间号等候送货。','bàng wǎn liù diǎn pī liàng pèi sòng， nǐ liú hǎo sù shè fáng jiān hào děng hòu sòng huò。','Sáu giờ chiều nay giao hàng theo đợt, em nhớ để lại số phòng ký túc xá rồi đợi nhận hàng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_07','V730','阮明',7,'我同意支付配送费，傍晚等工作人员送被褥上楼。','wǒ tóng yì zhī fù pèi sòng fèi， bàng wǎn děng gōng zuò rén yuán sòng bèi rù shàng lóu。','Em đồng ý trả phí giao hàng, chiều tối em đợi nhân viên mang chăn đệm lên phòng giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT731','SSH4','咨询校园医务室就诊流程、医保报销范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V731','SIT731','P1','suon_se','ban_chinh_thuc',NULL,'国内高校统一购买大学生医保，校内医务室基础诊疗、常用药品可按比例报销，大幅降低就医开支。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_01','V731','阮明',1,'护士您好，轻微咳嗽不舒服，想咨询医务室就诊流程。','hù shì nín hǎo， qīng wēi ké sòu bù shū fú， xiǎng zī xún yī wù shì jiù zhěn liú chéng。','Chào cô, em bị ho nhẹ khó chịu trong người, muốn hỏi cô quy trình khám ở phòng y tế ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_02','V731','护士',2,'携带校园医保凭证、学生证，一楼分诊台登记排队就诊哦。','xié dài xiào yuán yī bǎo píng zhèng、 xué shēng zhèng， yī lóu fēn zhěn tái dēng jì pái duì jiù zhěn ó。','Em mang theo thẻ bảo hiểm y tế của trường, thẻ sinh viên, ra bàn phân loại ở tầng một đăng ký rồi xếp hàng khám nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_03','V731','阮明',3,'校内医务室拿药可以直接医保报销，不用全额自费吗？','xiào nèi yī wù shì ná yào kě yǐ zhí jiē yī bǎo bào xiāo， bù yòng quán é zì fèi ma？','Lấy thuốc ở phòng y tế trong trường thì được bảo hiểm y tế thanh toán luôn, không cần trả toàn bộ tiền túi đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_04','V731','护士',4,'基础感冒、消炎药品报销七成，美容、滋补类药品不参与报销。','jī chǔ gǎn mào、 xiāo yán yào pǐn bào xiāo qī chéng， měi róng、 zī bǔ lèi yào pǐn bù cān yù bào xiāo。','Thuốc cảm cúm thông thường, thuốc kháng viêm cơ bản thì được thanh toán bảy mươi phần trăm, còn thuốc làm đẹp, bồi bổ thì không được thanh toán đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_05','V731','阮明',5,'就诊之后如果需要输液，也是同样报销比例对吗？','jiù zhěn zhī hòu rú guǒ xū yào shū yè， yě shì tóng yàng bào xiāo bǐ lì duì ma？','Sau khi khám nếu cần truyền dịch thì cũng được áp dụng tỷ lệ thanh toán như vậy đúng không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_06','V731','护士',6,'普通诊疗、输液均纳入医保报销，仅自费耗材除外。','pǔ tōng zhěn liáo、 shū yè jūn nà rù yī bǎo bào xiāo， jǐn zì fèi hào cái chú wài。','Khám bệnh thông thường và truyền dịch đều nằm trong diện bảo hiểm y tế thanh toán hết, chỉ trừ vật tư tự chi trả thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_07','V731','阮明',7,'我带好证件，现在登记排队问诊拿药。','wǒ dài hǎo zhèng jiàn， xiàn zài dēng jì pái duì wèn zhěn ná yào。','Em chuẩn bị sẵn giấy tờ rồi, giờ em đăng ký xếp hàng khám và lấy thuốc ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT732','SSH5','宿舍线上缴纳水电费，系统缴费失败咨询后勤',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V732','SIT732','P1','twist','ban_chinh_thuc',NULL,'校园线上缴费系统夜间服务器负载高容易卡顿，水电欠费设有三天缓冲期，不会立刻断供。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_01','V732','阮明',1,'您好，线上小程序缴纳宿舍电费，提交支付一直提示缴费失败。','nín hǎo， xiàn shàng xiǎo chéng xù jiǎo nà sù shè diàn fèi， tí jiāo zhī fù yì zhí tí shì jiǎo fèi shī bài。','Chào bạn, mình đóng tiền điện ký túc xá qua app trên điện thoại nhưng cứ bấm thanh toán là báo lỗi thất bại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_02','V732','后勤客服',2,'核对宿舍房间编号，近期是否输入错误楼栋号导致匹配失败？','hé duì sù shè fáng jiān biān hào， jìn qī shì fǒu shū rù cuò wù lóu dòng hào dǎo zhì pǐ pèi shī bài？','Bạn kiểm tra lại số phòng ký túc xá xem, gần đây có nhập nhầm số tòa nhà nên bị sai không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_03','V732','阮明',3,'楼栋、房间号全部核对无误，银行卡扣款短信也没有收到嘛。','lóu dòng、 fáng jiān hào quán bù hé duì wú wù， yín háng kǎ kòu kuǎn duǎn xìn yě méi yǒu shōu dào ma。','Tòa nhà, số phòng em kiểm tra hết rồi, không sai đâu, mà tin nhắn trừ tiền thẻ ngân hàng cũng chẳng thấy gửi về gì cả.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_04','V732','后勤客服',4,'小程序晚间服务器拥堵，夜间零点至早八点系统不稳定。','xiǎo chéng xù wǎn jiān fú wù qì yōng dǔ， yè jiān líng diǎn zhì zǎo bā diǎn xì tǒng bù wěn dìng。','Server của app hay bị nghẽn vào buổi tối, từ 12 giờ đêm đến 8 giờ sáng hệ thống không ổn định lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_05','V732','阮明',5,'那我明天上午再重新提交缴费，不会产生停水断电吧？','nà wǒ míng tiān shàng wǔ zài chóng xīn tí jiāo jiǎo fèi， bú huì chǎn shēng tíng shuǐ duàn diàn ba？','Vậy sáng mai em nộp lại tiền, chắc không bị cắt nước cắt điện chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_06','V732','后勤客服',6,'宿舍水电欠费缓冲三天，三天内缴费不会切断供应。','sù shè shuǐ diàn qiàn fèi huǎn chōng sān tiān， sān tiān nèi jiǎo fèi bú huì qiē duàn gōng yìng。','Tiền điện nước ký túc xá có thời gian gia hạn ba ngày, đóng trong ba ngày thì không bị ngắt cung cấp đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_07','V732','阮明',7,'明天一早完成缴费，避免宿舍水电临时关停。','míng tiān yī zǎo wán chéng jiǎo fèi， bì miǎn sù shè shuǐ diàn lín shí guān tíng。','Sáng mai em đóng tiền sớm luôn, để khỏi bị cắt điện nước tạm thời ở phòng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT733','SSH5','校园校园网账号欠费断网，线上续费恢复网络',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V733','SIT733','P1','suon_se','tuy_y',NULL,'校园内网按月计费，欠费立刻断网，校内图书馆、论文数据库均依托校园网访问。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_01','V733','阮明',1,'电脑显示校园网欠费停机，网页视频、学习软件全都打不开。','diàn nǎo xiǎn shì xiào yuán wǎng qiàn fèi tíng jī， wǎng yè shì pín、 xué xí ruǎn jiàn quán dōu dǎ bù kāi。','Máy tính báo mạng trường bị khóa do nợ cước, video trên web với phần mềm học tập đều không mở được luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_02','V733','小林',2,'打开校园网小程序，输入学号就能线上充值续费啦。','dǎ kāi xiào yuán wǎng xiǎo chéng xù， shū rù xué hào jiù néng xiàn shàng chōng zhí xù fèi la。','Mở app mạng trường lên, nhập mã số sinh viên vào là nạp tiền gia hạn online được ngay ấy.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_03','V733','阮明',3,'包月套餐三十元，充值之后是立刻恢复网络吗？','bāo yuè tào cān sān shí yuán， chōng zhí zhī hòu shì lì kè huī fù wǎng luò ma？','Gói tháng ba mươi nghìn, nạp xong là mạng khôi phục liền hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_04','V733','小林',4,'充值成功十秒内自动联网，不用重启电脑路由器。','chōng zhí chéng gōng shí miǎo nèi zì dòng lián wǎng， bù yòng chóng qǐ diàn nǎo lù yóu qì。','Nạp thành công là trong mười giây tự động kết nối mạng luôn, không cần khởi động lại máy tính hay router đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_05','V733','阮明',5,'要是忘记续费，断网之后校内论文数据库也没法访问？','yào shì wàng jì xù fèi， duàn wǎng zhī hòu xiào nèi lùn wén shù jù kù yě méi fǎ fǎng wèn？','Nếu lỡ quên gia hạn, mất mạng thì thư viện luận văn nội bộ trường cũng không vào được à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_06','V733','小林',6,'没错，内网文献库依赖校园网，断网完全无法登录查阅。','méi cuò， nèi wǎng wén xiàn kù yī lài xiào yuán wǎng， duàn wǎng wán quán wú fǎ dēng lù chá yuè。','Đúng vậy, thư viện tài liệu nội bộ phụ thuộc vào mạng trường, mất mạng là không đăng nhập tra cứu được luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_07','V733','阮明',7,'我现在线上充值续费，恢复网络继续写作业。','wǒ xiàn zài xiàn shàng chōng zhí xù fèi， huī fù wǎng luò jì xù xiě zuò yè。','Thôi giờ mình nạp tiền online liền, có mạng lại rồi làm tiếp bài tập.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT734','SSH5','手机话费余额不足停机，便利店线下充值缴费',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V734','SIT734','P1','suon_se','tuy_y',NULL,'国内线下便利店可办理手机话费充值，适合线上支付故障、手机停机无法收验证码的情况。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_01','V734','阮明',1,'你好，手机停机没法收短信，能不能线下充值话费？','nǐ hǎo， shǒu jī tíng jī méi fǎ shōu duǎn xìn， néng bù néng xiàn xià chōng zhí huà fèi？','Chào chị, điện thoại em bị khóa hai chiều không nhận được tin nhắn, ở đây có nạp tiền trực tiếp được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_02','V734','便利店店员',2,'支持五十、一百面额线下充值，输入手机号就能充值哈。','zhī chí wǔ shí、 yì bǎi miàn é xiàn xià chōng zhí， shū rù shǒu jī hào jiù néng chōng zhí hā。','Có nạp mệnh giá năm mươi với một trăm nè, cứ đọc số điện thoại là nạp được luôn.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_03','V734','阮明',3,'充值成功之后，多久手机能恢复通话、短信功能？','chōng zhí chéng gōng zhī hòu， duō jiǔ shǒu jī néng huī fù tōng huà、 duǎn xìn gōng néng？','Nạp xong thì bao lâu điện thoại gọi được, nhắn tin lại bình thường vậy chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_04','V734','便利店店员',4,'充值到账两分钟内自动复机，不用重启手机。','chōng zhí dào zhàng liǎng fēn zhōng nèi zì dòng fù jī， bù yòng chóng qǐ shǒu jī。','Nạp vào tài khoản trong hai phút là tự động mở máy lại, khỏi cần khởi động lại điện thoại luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_05','V734','阮明',5,'那充值一百元，报我的手机号码给你。','nà chōng zhí yì bǎi yuán， bào wǒ de shǒu jī hào mǎ gěi nǐ。','Vậy chị nạp giúp em một trăm nghìn, đây là số điện thoại của em nè.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_06','V734','便利店店员',6,'充值完成，手机很快就能恢复正常通讯。','chōng zhí wán chéng， shǒu jī hěn kuài jiù néng huī fù zhèng cháng tōng xùn。','Nạp xong rồi đó, chút nữa là điện thoại liên lạc lại bình thường ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_07','V734','阮明',7,'太好了，终于可以联系家人和同学。','tài hǎo le， zhōng yú kě yǐ lián xì jiā rén hé tóng xué。','Tuyệt quá, cuối cùng cũng liên lạc được với gia đình với bạn học rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT735','SSH5','干洗店送洗衣物，询问污渍清洗、取件时效',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V735','SIT735','P1','twist','tuy_y',NULL,'重度油污、陈年污渍无法保证完全洗净，干洗店会根据清洗效果调整收费，提前告知顾客预期。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_01','V735','阮明',1,'你好，这件外套沾了油污，送过来干洗能完全洗掉污渍吗？','nǐ hǎo， zhè jiàn wài tào zhān le yóu wū， sòng guò lái gān xǐ néng wán quán xǐ diào wū zì ma？','Chào anh, cái áo khoác này dính dầu mỡ, đem giặt khô có sạch hết vết bẩn được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_02','V735','干洗店员',2,'大面积油污需要特殊去渍剂，不一定能彻底清除干净。','dà miàn jī yóu wū xū yào tè shū qù zì jì， bù yí dìng néng chè dǐ qīng chú gān jìng。','Vết dầu mỡ diện tích lớn phải dùng chất tẩy đặc biệt, chưa chắc tẩy sạch hoàn toàn được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_03','V735','阮明',3,'要是洗完还有残留油污，会收取全套干洗费用嘛？','yào shì xǐ wán hái yǒu cán liú yóu wū， huì shōu qǔ quán tào gān xǐ fèi yòng ma？','Nếu giặt xong vẫn còn sót vết dầu, thì có tính đủ tiền giặt khô nguyên bộ không anh?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_04','V735','干洗店员',4,'尽力清洗，无法去除重度污渍仅收取基础洗护半价嘛。','jìn lì qīng xǐ， wú fǎ qù chú zhòng dù wū zì jǐn shōu qǔ jī chǔ xǐ hù bàn jià ma。','Tụi anh cố gắng giặt sạch hết mức, còn nếu vết bẩn nặng không tẩy được thì chỉ tính nửa giá giặt cơ bản thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_05','V735','阮明',5,'正常洗护多久可以取件，三天后过来取来得及吗？','zhèng cháng xǐ hù duō jiǔ kě yǐ qǔ jiàn， sān tiān hòu guò lái qǔ lái de jí ma？','Giặt bình thường thì bao lâu lấy được, ba ngày sau em đến lấy có kịp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_06','V735','干洗店员',6,'标准洗护两天完工，三天来取完全没有问题。','biāo zhǔn xǐ hù liǎng tiān wán gōng， sān tiān lái qǔ wán quán méi yǒu wèn tí。','Giặt tiêu chuẩn hai ngày là xong, ba ngày sau đến lấy hoàn toàn ổn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_07','V735','阮明',7,'那我把外套留在店里，后天下午前来取衣服。','nà wǒ bǎ wài tào liú zài diàn lǐ， hòu tiān xià wǔ qián lái qǔ yī fú。','Vậy em để áo khoác lại tiệm nha, chiều mốt em ghé lấy đồ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT736','SSH5','上门保洁预约，和保洁阿姨确认清洁范围与时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V736','SIT736','P1','suon_se','ban_chinh_thuc',NULL,'上门保洁分基础清扫、深度清洁两类服务，厨房重度油污清理属于额外增值服务，需要增加时长与费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_01','V736','阮明',1,'阿姨，我预约两小时全屋保洁，跟您确认清洁区域吧。','ā yí， wǒ yù yuē liǎng xiǎo shí quán wū bǎo jié， gēn nín què rèn qīng jié qū yù ba。','Chị ơi, em đặt lịch dọn dẹp toàn bộ nhà hai tiếng, mình xác nhận lại khu vực dọn dẹp nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_02','V736','保洁阿姨',2,'客厅、卧室、卫生间常规清扫，厨房油污深度清洗需要额外加时。','kè tīng、 wò shì、 wèi shēng jiān cháng guī qīng sǎo， chú fáng yóu wū shēn dù qīng xǐ xū yào é wài jiā shí。','Phòng khách, phòng ngủ, nhà vệ sinh thì lau dọn thông thường, còn bếp mà dọn sâu vết dầu mỡ thì phải tính thêm giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_03','V736','阮明',3,'厨房简单擦拭台面即可，不用深度清理厚重油污。','chú fáng jiǎn dān cā shì tái miàn jí kě， bù yòng shēn dù qīng lǐ hòu zhòng yóu wū。','Bếp thì lau mặt bàn qua thôi là được, không cần dọn sâu lớp dầu mỡ dày đâu chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_04','V736','保洁阿姨',4,'两小时只做基础除尘拖地，不含重度厨房油污清理。','liǎng xiǎo shí zhǐ zuò jī chǔ chú chén tuō dì， bù hán zhòng dù chú fáng yóu wū qīng lǐ。','Hai tiếng chỉ làm quét bụi lau nhà cơ bản thôi, không bao gồm dọn dầu mỡ nặng trong bếp đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_05','V736','阮明',5,'本周六上午九点上门，我提前把桌面杂物收纳好。','běn zhōu liù shàng wǔ jiǔ diǎn shàng mén， wǒ tí qián bǎ zhuō miàn zá wù shōu nà hǎo。','Thứ Bảy tuần này chín giờ sáng chị đến nhé, em sẽ dọn đồ đạc trên bàn gọn gàng trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_06','V736','保洁阿姨',6,'到点准时上门，杂物收纳干净清洁效率更高。','dào diǎn zhǔn shí shàng mén， zá wù shōu nà gān jìng qīng jié xiào lǜ gèng gāo。','Chị đến đúng giờ luôn, đồ đạc thu dọn gọn thì hiệu quả dọn dẹp cũng cao hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_07','V736','阮明',7,'我提前整理房间，方便阿姨快速完成全屋保洁。','wǒ tí qián zhěng lǐ fáng jiān， fāng biàn ā yí kuài sù wán chéng quán wū bǎo jié。','Em dọn phòng trước, để chị tiện làm vệ sinh toàn bộ nhà cho nhanh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT737','SSH6','报名校园羽毛球社团，咨询会费、活动固定时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V737','SIT737','P1','suon_se','tuy_y',NULL,'国内高校学生社团会费低廉，仅用于活动耗材、场地租赁，定期开展免费校内文体活动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_01','V737','阮明',1,'学长，我想加入羽毛球社团，请问入社需要缴纳会费吗？','xué zhǎng， wǒ xiǎng jiā rù yǔ máo qiú shè tuán， qǐng wèn rù shè xū yào jiǎo nà huì fèi ma？','Anh ơi, em muốn tham gia câu lạc bộ cầu lông, vào câu lạc bộ có phải đóng hội phí không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_02','V737','学长',2,'一年二十元会费，全部用于采购羽毛球、场地租赁哦。','yī nián èr shí yuán huì fèi， quán bù yòng yú cǎi gòu yǔ máo qiú、 chǎng dì zū lìn ó。','Hội phí hai mươi nghìn một năm, dùng hết để mua cầu lông với thuê sân đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_03','V737','阮明',3,'社团固定活动周几开展，是校内体育馆场地吗？','shè tuán gù dìng huó dòng zhōu jǐ kāi zhǎn， shì xiào nèi tǐ yù guǎn chǎng dì ma？','Câu lạc bộ sinh hoạt cố định vào thứ mấy vậy anh, có phải ở sân thể dục trong trường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_04','V737','学长',4,'每周四傍晚六点到八点，校内羽毛球馆专属场地。','měi zhōu sì bàng wǎn liù diǎn dào bā diǎn， xiào nèi yǔ máo qiú guǎn zhuān shǔ chǎng dì。','Mỗi thứ Năm từ sáu giờ đến tám giờ tối, tại nhà thi đấu cầu lông riêng trong trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_05','V737','阮明',5,'没有自带球拍，社团可以临时借用训练球拍吗？','méi yǒu zì dài qiú pāi， shè tuán kě yǐ lín shí jiè yòng xùn liàn qiú pāi ma？','Em không có vợt riêng, câu lạc bộ có cho mượn vợt tập tạm không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_06','V737','学长',6,'新人可免费借用公用球拍，长期参与建议自备球拍。','xīn rén kě miǎn fèi jiè yòng gōng yòng qiú pāi， cháng qī cān yù jiàn yì zì bèi qiú pāi。','Thành viên mới thì được mượn vợt chung miễn phí, còn tham gia lâu dài thì nên tự sắm vợt riêng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_07','V737','阮明',7,'我今天缴纳会费入社，周四准时参加社团活动。','wǒ jīn tiān jiǎo nà huì fèi rù shè， zhōu sì zhǔn shí cān jiā shè tuán huó dòng。','Hôm nay em đóng hội phí vào câu lạc bộ luôn, thứ Năm sẽ tham gia sinh hoạt đúng giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT738','SSH6','校园操场运动扭伤，前往医务室简单处理伤口',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V738','SIT738','P1','twist','ban_chinh_thuc',NULL,'校内医务室跌打损伤、消炎外敷药品均可医保报销，运动受伤可免费冷敷理疗处理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_01','V738','阮明',1,'护士，操场跑步崴到脚踝，现在肿胀疼痛没法正常走路。','hù shì， cāo chǎng pǎo bù wǎi dào jiǎo huái， xiàn zài zhǒng zhàng téng tòng méi fǎ zhèng cháng zǒu lù。','Cô ơi, em chạy bộ ngoài sân bị trẹo mắt cá chân, giờ sưng đau không đi lại bình thường được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_02','V738','护士',2,'先坐下抬高腿部冷敷消肿，我给你开外用消炎药膏。','xiān zuò xià tái gāo tuǐ bù lěng fū xiāo zhǒng， wǒ gěi nǐ kāi wài yòng xiāo yán yào gāo。','Em ngồi xuống kê chân cao lên chườm lạnh cho giảm sưng trước, cô kê cho em thuốc mỡ kháng viêm dùng ngoài da.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_03','V738','阮明',3,'冷敷需要持续多久，今晚还能正常下床行走吗？','lěng fū xū yào chí xù duō jiǔ， jīn wǎn hái néng zhèng cháng xià chuáng xíng zǒu ma？','Chườm lạnh phải chườm bao lâu ạ, tối nay em có xuống giường đi lại bình thường được không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_04','V738','护士',4,'连续冷敷二十分钟，三天之内尽量减少走路、剧烈运动嘛。','lián xù lěng fū èr shí fēn zhōng， sān tiān zhī nèi jǐn liàng jiǎn shǎo zǒu lù、 jù liè yùn dòng ma。','Chườm lạnh liên tục hai mươi phút, trong ba ngày cố gắng hạn chế đi lại và vận động mạnh nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_05','V738','阮明',5,'药膏医保可以报销吗，还是需要全额自费购买？','yào gāo yī bǎo kě yǐ bào xiāo ma， hái shì xū yào quán é zì fèi gòu mǎi？','Thuốc mỡ này bảo hiểm y tế có chi trả không cô, hay là em phải tự trả toàn bộ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_06','V738','护士',6,'外用跌打药膏纳入学生医保，只需要自费三成费用。','wài yòng diē dǎ yào gāo nà rù xué shēng yī bǎo， zhǐ xū yào zì fèi sān chéng fèi yòng。','Thuốc bôi trị bong gân nằm trong danh mục bảo hiểm y tế sinh viên, em chỉ cần tự trả ba mươi phần trăm thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_07','V738','阮明',7,'我拿药之后回宿舍静养，不再剧烈运动加重扭伤。','wǒ ná yào zhī hòu huí sù shè jìng yǎng， bù zài jù liè yùn dòng jiā zhòng niǔ shāng。','Em lấy thuốc xong về ký túc xá nghỉ ngơi tĩnh dưỡng, không vận động mạnh nữa kẻo trẹo nặng thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT739','SSH6','咨询校园奖学金申请条件、提交材料截止日期',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V739','SIT739','P1','suon_se','chinh_thuc',NULL,'留学生奖学金对出勤率、期末分数有硬性门槛，逾期不接受补报，错过只能等待下一学年申报。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_01','V739','阮明',1,'老师您好，想咨询留学生校级奖学金的申请基础条件。','lǎo shī nín hǎo， xiǎng zī xún liú xué shēng xiào jí jiǎng xué jīn de shēn qǐng jī chǔ tiáo jiàn。','Chào thầy/cô, em muốn hỏi về điều kiện cơ bản để nộp đơn xin học bổng cấp trường dành cho lưu học sinh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_02','V739','教务老师',2,'全年出勤率达标、期末平均分七十五分以上方可申报。','quán nián chū qín lǜ dá biāo、 qī mò píng jūn fēn qī shí wǔ fēn yǐ shàng fāng kě shēn bào。','Tỷ lệ chuyên cần cả năm phải đạt chuẩn, điểm trung bình học kỳ đạt từ bảy mươi lăm điểm trở lên mới được đăng ký.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_03','V739','阮明',3,'申请需要提交成绩单、在校证明，截止提交日期是哪天？','shēn qǐng xū yào tí jiāo chéng jì dān、 zài xiào zhèng míng， jié zhǐ tí jiāo rì qī shì nǎ tiān？','Hồ sơ cần nộp bảng điểm, giấy xác nhận đang học, vậy hạn chót nộp là ngày nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_04','V739','教务老师',4,'本月二十五号下午五点关闭申报通道，逾期不予受理。','běn yuè èr shí wǔ hào xià wǔ wǔ diǎn guān bì shēn bào tōng dào， yú qī bù yǔ shòu lǐ。','Cổng đăng ký sẽ đóng vào lúc năm giờ chiều ngày hai mươi lăm tháng này, quá hạn sẽ không được tiếp nhận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_05','V739','阮明',5,'材料线上系统提交，还是纸质复印件线下上交学院？','cái liào xiàn shàng xì tǒng tí jiāo， hái shì zhǐ zhì fù yìn jiàn xiàn xià shàng jiāo xué yuàn？','Hồ sơ nộp qua hệ thống trực tuyến, hay là bản giấy phô tô nộp trực tiếp cho khoa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_06','V739','教务老师',6,'线上填报信息，纸质材料线下送至国际学院办公室。','xiàn shàng tián bào xìn xī， zhǐ zhì cái liào xiàn xià sòng zhì guó jì xué yuàn bàn gōng shì。','Thông tin thì khai báo trực tuyến, còn bản giấy thì nộp trực tiếp tại văn phòng Học viện Quốc tế.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_07','V739','阮明',7,'我这周整理好全部材料，提前完成奖学金申报。','wǒ zhè zhōu zhěng lǐ hǎo quán bù cái liào， tí qián wán chéng jiǎng xué jīn shēn bào。','Tuần này em sẽ chuẩn bị đầy đủ hồ sơ, hoàn thành đăng ký học bổng sớm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT740','SSH6','校内丢失水杯、雨伞，去失物招领处登记寻物',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V740','SIT740','P1','that_bai_nhe','tuy_y',NULL,'校园失物招领处仅短期保管遗失物品，超过一周无人认领会统一收纳，长期无人认领定期清理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_01','V740','阮明',1,'你好，我昨天操场丢失黑色水杯、折叠雨伞，前来登记寻物。','nǐ hǎo， wǒ zuó tiān cāo chǎng diū shī hēi sè shuǐ bēi、 zhé dié yǔ sǎn， qián lái dēng jì xún wù。','Chào bạn, hôm qua mình bị mất cái cốc nước màu đen với cây dù gấp ở sân vận động, mình đến đăng ký báo mất đồ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_02','V740','工作人员',2,'登记物品外观、丢失地点、你的联系方式，有人上交会通知你。','dēng jì wù pǐn wài guān、 diū shī dì diǎn、 nǐ de lián xì fāng shì， yǒu rén shàng jiāo huì tōng zhī nǐ。','Bạn ghi lại đặc điểm đồ vật, chỗ mất và số điện thoại liên hệ, nếu có ai nộp lên bên mình sẽ báo cho bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_03','V740','阮明',3,'水杯侧面印有越南文字标识，雨伞是深蓝色，特征很明显。','shuǐ bēi cè miàn yìn yǒu yuè nán wén zì biāo shí， yǔ sǎn shì shēn lán sè， tè zhēng hěn míng xiǎn。','Cái cốc có in chữ tiếng Việt ở mặt bên, còn cây dù màu xanh navy, đặc điểm khá rõ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_04','V740','工作人员',4,'今日上交失物清单没有匹配物品，大概率还未被捡拾上交嘛。','jīn rì shàng jiāo shī wù qīng dān méi yǒu pǐ pèi wù pǐn， dà gài lǜ hái wèi bèi jiǎn shí shàng jiāo ma。','Danh sách đồ thất lạc nộp lên hôm nay không có món nào khớp cả, chắc là chưa ai nhặt được với nộp lên đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_05','V740','阮明',5,'要是之后有人送到招领处，麻烦打电话通知我过来领取。','yào shì zhī hòu yǒu rén sòng dào zhāo lǐng chù， má fán dǎ diàn huà tōng zhī wǒ guò lái lǐng qǔ。','Nếu sau này có ai mang đến chỗ nhận đồ, phiền bạn gọi điện báo mình đến lấy nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_06','V740','工作人员',6,'登记信息留存一周，一周无人认领物品统一清理存放。','dēng jì xìn xī liú cún yī zhōu， yī zhōu wú rén rèn lǐng wù pǐn tǒng yī qīng lǐ cún fàng。','Thông tin đăng ký sẽ lưu trong một tuần, hết một tuần không ai nhận thì đồ sẽ được gom lại cất riêng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_07','V740','阮明',7,'我三天后再来招领处询问，看看有没有捡到我的物品。','wǒ sān tiān hòu zài lái zhāo lǐng chù xún wèn， kàn kàn yǒu méi yǒu jiǎn dào wǒ de wù pǐn。','Ba hôm nữa mình quay lại chỗ nhận đồ hỏi lại xem có nhặt được đồ của mình không nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT801','SHT1','向同班同学借课件PPT，拷贝到自己电脑复习',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V801','SIT801','P1','suon_se','tuy_y',NULL,'国内课堂老师大多会课后分享电子课件，同学之间互相转发课件、笔记是很普遍的互助学习习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_01','V801','阮明',1,'苏雯，昨天专业课老师的课件我忘记拷贝，能发我一份PPT吗？','sū wén， zuó tiān zhuān yè kè lǎo shī de kè jiàn wǒ wàng jì kǎo bèi， néng fā wǒ yī fèn PPT ma？','Tô Văn ơi, hôm qua slide bài giảng chuyên ngành của thầy mình quên copy, gửi mình một bản PPT được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_02','V801','苏雯',2,'没问题，我把完整课件打包，微信文件传输发给你就行啦。','méi wèn tí， wǒ bǎ wán zhěng kè jiàn dǎ bāo， wēi xìn wén jiàn chuán shū fā gěi nǐ jiù xíng la。','Không vấn đề gì, mình đóng gói cả slide đầy đủ rồi gửi qua truyền file WeChat cho bạn là được ấy.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_03','V801','阮明',3,'文件内存很大，微信会不会压缩模糊里面的表格内容？','wén jiàn nèi cún hěn dà， wēi xìn huì bú huì yā suō mó hú lǐ miàn de biǎo gé nèi róng？','File dung lượng lớn vậy, WeChat có bị nén làm mờ mấy cái bảng biểu trong đó không nhỉ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_04','V801','苏雯',4,'我发原文件不压缩，要是打不开我再分享网盘链接给你呢。','wǒ fā yuán wén jiàn bù yā suō， yào shì dǎ bù kāi wǒ zài fēn xiǎng wǎng pán liàn jiē gěi nǐ ne。','Mình gửi file gốc không nén đâu, nếu mà mở không được thì mình chia sẻ link ổ đĩa mạng cho bạn nha.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_05','V801','阮明',5,'太好了，我今晚对照课件梳理今天课堂没听懂的知识点。','tài hǎo le， wǒ jīn wǎn duì zhào kè jiàn shū lǐ jīn tiān kè táng méi tīng dǒng de zhī shí diǎn。','Tuyệt quá, tối nay mình xem lại slide để gỡ mấy chỗ hôm nay nghe không hiểu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_06','V801','苏雯',6,'课件里标注了期末重点，复习的时候可以优先看标红部分。','kè jiàn lǐ biāo zhù le qī mò zhòng diǎn， fù xí de shí hòu kě yǐ yōu xiān kàn biāo hóng bù fèn。','Trong slide có đánh dấu trọng tâm cuối kỳ đó, lúc ôn thì ưu tiên xem phần bôi đỏ trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_07','V801','阮明',7,'太感谢你，有完整课件复习会轻松很多。','tài gǎn xiè nǐ， yǒu wán zhěng kè jiàn fù xí huì qīng sōng hěn duō。','Cảm ơn bạn nhiều lắm, có slide đầy đủ ôn bài sẽ nhẹ nhàng hơn hẳn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT802','SHT1','询问老师课堂录音是否允许，方便课后复盘知识点',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V802','SIT802','P1','twist','ban_chinh_thuc',NULL,'课堂自用录音一般老师都会许可，但传播授课录音、课件属于侵犯教学版权，会被制止。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_01','V802','阮明',1,'李老师，我汉语听力反应慢一点，请问上课可以手机录音吗？','lǐ lǎo shī， wǒ hàn yǔ tīng lì fǎn yìng màn yì diǎn， qǐng wèn shàng kè kě yǐ shǒu jī lù yīn ma？','Cô Lý ơi, khả năng nghe tiếng Trung của em hơi chậm, cho em xin phép ghi âm bằng điện thoại trong giờ học được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_02','V802','李老师',2,'单纯自己课后复习录音是可以的，但禁止转发、上传网络平台。','dān chún zì jǐ kè hòu fù xí lù yīn shì kě yǐ de， dàn jìn zhǐ zhuǎn fā、 shàng chuán wǎng luò píng tái。','Nếu chỉ để tự ôn lại sau giờ học thì được, nhưng tuyệt đối không được chia sẻ hay đăng lên mạng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_03','V802','阮明',3,'我只自己私下复盘，绝对不会分享录音给其他同学或者发到网上。','wǒ zhǐ zì jǐ sī xià fù pán， jué duì bú huì fēn xiǎng lù yīn gěi qí tā tóng xué huò zhě fā dào wǎng shàng。','Em chỉ nghe lại một mình thôi ạ, tuyệt đối sẽ không chia sẻ bản ghi âm cho bạn nào khác hay đăng lên mạng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_04','V802','李老师',4,'还有一点，录音不能遮挡其他同学，手机音量一定要完全静音嘛。','hái yǒu yì diǎn， lù yīn bù néng zhē dǎng qí tā tóng xué， shǒu jī yīn liàng yí dìng yào wán quán jìng yīn ma。','Còn một điều nữa, ghi âm không được che khuất các bạn khác, và âm lượng điện thoại phải để im lặng hoàn toàn đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_05','V802','阮明',5,'我把手机调成飞行模式，只开启本地录音，不会弹出消息打扰课堂。','wǒ bǎ shǒu jī diào chéng fēi xíng mó shì， zhǐ kāi qǐ běn dì lù yīn， bú huì dàn chū xiāo xī dǎ rǎo kè táng。','Em sẽ để điện thoại ở chế độ máy bay, chỉ bật ghi âm nội bộ thôi, sẽ không có thông báo nào bật lên làm phiền lớp đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_06','V802','李老师',6,'如果后期有听不懂的地方，结合录音再来办公室问我也可以。','rú guǒ hòu qī yǒu tīng bù dǒng de dì fāng， jié hé lù yīn zài lái bàn gōng shì wèn wǒ yě kě yǐ。','Nếu sau này có chỗ nào không hiểu, em cứ nghe lại bản ghi âm rồi lên văn phòng hỏi cô cũng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_07','V802','阮明',7,'谢谢您允许录音，课后我能反复梳理课堂难点。','xiè xiè nín yǔn xǔ lù yīn， kè hòu wǒ néng fǎn fù shū lǐ kè táng nán diǎn。','Em cảm ơn cô đã cho phép ghi âm, sau giờ học em có thể xem lại nhiều lần những phần khó ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT803','SHT1','课堂听不懂专业词汇，课后找同学一对一讲解',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V803','SIT803','P1','suon_se','tuy_y',NULL,'课后同学之间一对一拆解难点、互相讲题是高校主流互助学习方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_01','V803','阮明',1,'今天课上老师讲的几个贸易专业术语，我完全没理解含义啊。','jīn tiān kè shàng lǎo shī jiǎng de jǐ gè mào yì zhuān yè shù yǔ， wǒ wán quán méi lǐ jiě hán yì a。','Hôm nay mấy thuật ngữ chuyên ngành thương mại thầy giảng trên lớp, mình chẳng hiểu gì luôn ấy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_02','V803','苏雯',2,'这几个词是国内外贸常用词汇，我举简单例子给你拆解意思。','zhè jǐ gè cí shì guó nèi wài mào cháng yòng cí huì， wǒ jǔ jiǎn dān lì zi gěi nǐ chāi jiě yì si。','Mấy từ này là từ vựng ngoại thương thông dụng trong và ngoài nước đó, mình lấy ví dụ đơn giản giải thích cho bạn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_03','V803','阮明',3,'每个词汇搭配例句讲一遍，我才能分清使用场景对吧？','měi gè cí huì dā pèi lì jù jiǎng yī biàn， wǒ cái néng fēn qīng shǐ yòng chǎng jǐng duì ba？','Mỗi từ phải kèm câu ví dụ giảng lại thì mình mới phân biệt được cách dùng đúng không ta?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_04','V803','苏雯',4,'没错，我结合课本习题举例，方便你区分易混淆词汇。','méi cuò， wǒ jié hé kè běn xí tí jǔ lì， fāng biàn nǐ qū fēn yì hùn xiáo cí huì。','Đúng rồi, mình sẽ lấy ví dụ từ bài tập trong sách, cho bạn dễ phân biệt mấy từ dễ nhầm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_05','V803','阮明',5,'耽误你半小时休息时间，实在不好意思麻烦你。','dān wù nǐ bàn xiǎo shí xiū xī shí jiān， shí zài bù hǎo yì sī má fán nǐ。','Làm mất nửa tiếng nghỉ ngơi của bạn rồi, thật ngại quá đi mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_06','V803','苏雯',6,'互相讲题很正常，之后我有语言难题也会找你帮忙。','hù xiāng jiǎng tí hěn zhèng cháng， zhī hòu wǒ yǒu yǔ yán nán tí yě huì zhǎo nǐ bāng máng。','Giảng bài qua lại cho nhau là chuyện bình thường mà, sau này mình gặp khó về ngôn ngữ cũng sẽ nhờ bạn giúp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_07','V803','阮明',7,'太感谢，听完讲解一下子清晰多了。','tài gǎn xiè， tīng wán jiǎng jiě yī xià zi qīng xī duō le。','Cảm ơn bạn nhiều ghê, nghe bạn giảng xong là thấy rõ ràng hẳn ra luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT804','SHT1','咨询老师课程平时分构成：出勤、课堂发言、小测占比',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V804','SIT804','P1','suon_se','ban_chinh_thuc',NULL,'国内大学课程普遍实行平时分+期末试卷综合打分，不会仅凭一次期末成绩定总分，鼓励日常课堂参与。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_01','V804','阮明',1,'老师，想向您咨询这门课期末总评分数的分配标准。','lǎo shī， xiǎng xiàng nín zī xún zhè mén kè qī mò zǒng píng fēn shù de fēn pèi biāo zhǔn。','Thầy ơi, em muốn hỏi thầy về cách phân bổ điểm tổng kết cuối kỳ của môn này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_02','V804','李老师',2,'总评由三部分组成：出勤20%、课堂发言与随堂小测30%、期末试卷50%哦。','zǒng píng yóu sān bù fèn zǔ chéng： chū qín 20%、 kè táng fā yán yǔ suí táng xiǎo cè 30%、 qī mò shì juàn 50% ó。','Điểm tổng kết gồm ba phần: điểm danh 20%, phát biểu trên lớp cùng kiểm tra nhỏ 30%, bài thi cuối kỳ 50% đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_03','V804','阮明',3,'随堂小测每节课都会有吗，缺课一次会直接扣掉出勤分？','suí táng xiǎo cè měi jié kè dōu huì yǒu ma， quē kè yī cì huì zhí jiē kòu diào chū qín fēn？','Kiểm tra nhỏ trên lớp buổi nào cũng có ạ, nghỉ học một buổi là bị trừ thẳng điểm chuyên cần luôn ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_04','V804','李老师',4,'无故缺课单次扣5分，请假备案不扣分；小测每月一次，错过可补。','wú gù quē kè dān cì kòu 5 fēn， qǐng jià bèi àn bù kòu fēn； xiǎo cè měi yuè yī cì， cuò guò kě bǔ。','Nghỉ không phép một lần trừ 5 điểm, còn xin phép có ghi nhận thì không trừ; kiểm tra nhỏ mỗi tháng một lần, lỡ thì được thi bù.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_05','V804','阮明',5,'课堂发言只要主动回答问题，就能拿到对应的平时分吗？','kè táng fā yán zhǐ yào zhǔ dòng huí dá wèn tí， jiù néng ná dào duì yìng de píng shí fēn ma？','Chỉ cần chủ động phát biểu trả lời câu hỏi là được tính điểm chuyên cần tương ứng đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_06','V804','李老师',6,'主动思考作答、有完整观点，都会记录课堂表现分。','zhǔ dòng sī kǎo zuò dá、 yǒu wán zhěng guān diǎn， dōu huì jì lù kè táng biǎo xiàn fēn。','Chỉ cần chủ động suy nghĩ trả lời, có quan điểm rõ ràng, đều sẽ được ghi nhận vào điểm thể hiện trên lớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_07','V804','阮明',7,'我清楚分值规则了，之后多主动参与课堂互动。','wǒ qīng chǔ fēn zhí guī zé le， zhī hòu duō zhǔ dòng cān yù kè táng hù dòng。','Em hiểu rõ quy tắc tính điểm rồi ạ, sau này em sẽ tích cực tham gia phát biểu trên lớp hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT805','SHT1','忘记带课本，和同桌共用一本书听课',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V805','SIT805','P1','twist','tuy_y',NULL,'课堂忘记带教材和同桌共用书本很常见，但不建议长期如此，会影响双方记笔记效率。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_01','V805','阮明',1,'糟糕，早上出门匆忙，把专业课课本落在宿舍了，能和你共用一本吗？','zāo gāo， zǎo shàng chū mén cōng máng， bǎ zhuān yè kè kè běn luò zài sù shè le， néng hé nǐ gòng yòng yī běn ma？','Chết rồi, sáng nay vội quá nên bỏ quên sách chuyên ngành ở ký túc xá, dùng chung sách với cậu được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_02','V805','小林',2,'可以一起看，不过书本放在中间，记笔记会有点挤不方便。','kě yǐ yì qǐ kàn， bù guò shū běn fàng zài zhōng jiān， jì bǐ jì huì yǒu diǎn jǐ bù fāng biàn。','Xem chung cũng được, nhưng để sách ở giữa thì ghi chép sẽ hơi chật, bất tiện đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_03','V805','阮明',3,'我只对照书页听讲解，笔记先记在草稿纸上，下课再整理。','wǒ zhǐ duì zhào shū yè tīng jiǎng jiě， bǐ jì xiān jì zài cǎo gǎo zhǐ shàng， xià kè zài zhěng lǐ。','Mình chỉ nhìn theo trang sách nghe giảng thôi, ghi chú thì mình ghi ra giấy nháp trước, hết tiết rồi chép lại sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_04','V805','小林',4,'老师等下要勾画重点段落，我们分开两边各自标注会不会混乱嘛。','lǎo shī děng xià yào gōu huà zhòng diǎn duàn luò， wǒ men fēn kāi liǎng biān gè zì biāo zhù huì bú huì hùn luàn ma。','Lát nữa thầy sẽ gạch chân mấy đoạn trọng tâm, mình mỗi người để một bên tự đánh dấu vậy có lộn xộn không ta.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_05','V805','阮明',5,'我手机拍课本页面，重点自己在照片上标记，不影响你看书。','wǒ shǒu jī pāi kè běn yè miàn， zhòng diǎn zì jǐ zài zhào piān shàng biāo jì， bù yǐng xiǎng nǐ kàn shū。','Mình chụp lại trang sách bằng điện thoại, chỗ nào quan trọng tự đánh dấu trên ảnh, không ảnh hưởng đến cậu xem sách đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_06','V805','小林',6,'这样也行，有看不懂的段落随时指给我一起讨论。','zhè yàng yě xíng， yǒu kàn bù dǒng de duàn luò suí shí zhǐ gěi wǒ yì qǐ tǎo lùn。','Vậy cũng được, đoạn nào không hiểu thì cứ chỉ cho mình xem rồi cùng bàn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_07','V805','阮明',7,'今天多亏你，不然整节课没法跟上老师进度。','jīn tiān duō kuī nǐ， bù rán zhěng jié kè méi fǎ gēn shàng lǎo shī jìn dù。','Hôm nay may có cậu giúp, không thì cả tiết học mình theo không kịp tiến độ của thầy mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT806','SHT1','上课手机静音没做到，被老师提醒课堂纪律',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V806','SIT806','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂严格管控手机声响，震动、响铃都会被老师提醒，多次违规会扣除课堂表现分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_01','V806','阮明',1,'老师对不起，刚刚手机消息突然响铃，打断您讲课了。','lǎo shī duì bù qǐ， gāng gāng shǒu jī xiāo xī tū rán xiǎng líng， dǎ duàn nín jiǎng kè le。','Thầy ơi em xin lỗi, vừa nãy điện thoại em tự nhiên reo, làm gián đoạn bài giảng của thầy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_02','V806','李老师',2,'课堂要求所有手机必须完全静音或关机，你忘记调整设置了？','kè táng yāo qiú suǒ yǒu shǒu jī bì xū wán quán jìng yīn huò guān jī， nǐ wàng jì tiáo zhěng shè zhì le？','Trên lớp yêu cầu tất cả điện thoại phải để im lặng hoàn toàn hoặc tắt máy, em quên chỉnh lại à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_03','V806','阮明',3,'早上调了震动，没想到震动声响也很明显，干扰全班听课嘛。','zǎo shàng diào le zhèn dòng， méi xiǎng dào zhèn dòng shēng xiǎng yě hěn míng xiǎn， gān rǎo quán bān tīng kè ma。','Sáng nay em để chế độ rung, không ngờ tiếng rung cũng khá rõ, làm ảnh hưởng đến cả lớp nghe giảng luôn ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_04','V806','李老师',4,'一次警告不计入扣分，之后如果再出现声响会扣除课堂平时分。','yī cì jǐng gào bù jì rù kòu fēn， zhī hòu rú guǒ zài chū xiàn shēng xiǎng huì kòu chú kè táng píng shí fēn。','Lần này nhắc nhở thôi không tính trừ điểm, sau này nếu còn xảy ra tiếng động sẽ bị trừ vào điểm chuyên cần đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_05','V806','阮明',5,'我现在直接关机，整节课不再开启手机接收消息。','wǒ xiàn zài zhí jiē guān jī， zhěng jié kè bù zài kāi qǐ shǒu jī jiē shōu xiāo xī。','Em tắt máy luôn bây giờ ạ, cả tiết học em sẽ không mở điện thoại nhận tin nhắn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_06','V806','李老师',6,'课堂需要安静的听讲环境，还请遵守班级课堂规定。','kè táng xū yào ān jìng de tīng jiǎng huán jìng， hái qǐng zūn shǒu bān jí kè táng guī dìng。','Lớp học cần môi trường yên tĩnh để nghe giảng, mong em tuân thủ quy định của lớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_07','V806','阮明',7,'我记住教训，之后课前一定检查手机静音状态。','wǒ jì zhù jiào xùn， zhī hòu kè qián yí dìng jiǎn chá shǒu jī jìng yīn zhuàng tài。','Em ghi nhớ bài học này rồi ạ, sau này trước giờ học em sẽ luôn kiểm tra điện thoại đã để im lặng chưa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT807','SHT1','咨询课程课外拓展阅读书目、图书馆馆藏位置',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V807','SIT807','P1','suon_se','ban_chinh_thuc',NULL,'大学专业课会配套拓展阅读书目，图书馆专业馆藏区集中存放对应书籍，支持学生课外自主拓展学习。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_01','V807','阮明',1,'老师，想提升专业水平，请问这门课配套拓展阅读书籍有哪些？','lǎo shī， xiǎng tí shēng zhuān yè shuǐ píng， qǐng wèn zhè mén kè pèi tào tuò zhǎn yuè dú shū jí yǒu nǎ xiē？','Thầy ơi, em muốn nâng cao trình độ chuyên môn, cho em hỏi môn này có những sách đọc mở rộng nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_02','V807','李老师',2,'我列三本核心参考书，全部存放在图书馆三楼外文专业区哦。','wǒ liè sān běn hé xīn cān kǎo shū， quán bù cún fàng zài tú shū guǎn sān lóu wài wén zhuān yè qū ó。','Thầy liệt kê ba cuốn sách tham khảo cốt lõi, tất cả đều để ở khu chuyên ngành ngoại văn tầng ba thư viện đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_03','V807','阮明',3,'这几本书可以外借带回家长期阅读，还是只能馆内阅览？','zhè jǐ běn shū kě yǐ wài jiè dài huí jiā zhǎng qī yuè dú， hái shì zhǐ néng guǎn nèi yuè lǎn？','Mấy cuốn sách này có thể mượn về nhà đọc lâu dài không ạ, hay chỉ đọc tại thư viện thôi ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_04','V807','李老师',4,'均可借阅三十天，线上系统还能办理续借延长阅读时间。','jūn kě jiè yuè sān shí tiān， xiàn shàng xì tǒng hái néng bàn lǐ xù jiè yán cháng yuè dú shí jiān。','Đều mượn được ba mươi ngày, hệ thống trực tuyến còn có thể gia hạn thêm thời gian đọc nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_05','V807','阮明',5,'我记下书名，下课直接去图书馆检索借阅。','wǒ jì xià shū míng， xià kè zhí jiē qù tú shū guǎn jiǎn suǒ jiè yuè。','Em ghi lại tên sách rồi ạ, hết tiết em sẽ ra thư viện tra cứu mượn luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_06','V807','李老师',6,'阅读完有疑问，随时来办公室和我交流书中观点。','yuè dú wán yǒu yí wèn， suí shí lái bàn gōng shì hé wǒ jiāo liú shū zhōng guān diǎn。','Đọc xong có gì thắc mắc, cứ lên văn phòng trao đổi với thầy về nội dung sách nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_07','V807','阮明',7,'感谢老师推荐书目，对我的专业学习帮助很大。','gǎn xiè lǎo shī tuī jiàn shū mù， duì wǒ de zhuān yè xué xí bāng zhù hěn dà。','Em cảm ơn thầy đã giới thiệu sách, giúp ích rất nhiều cho việc học chuyên ngành của em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT808','SHT1','小组讨论时观点分歧，和组员温和协商统一思路',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V808','SIT808','P1','suon_se','tuy_y',NULL,'国内小组作业鼓励充分发表不同观点，通过讨论、分工、投票协商统一方案，不强行听从单一人员想法。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_01','V808','阮明',1,'我对小组报告案例选取有不同想法，和大家现在选定的方向不一样。','wǒ duì xiǎo zǔ bào gào àn lì xuǎn qǔ yǒu bù tóng xiǎng fǎ， hé dà jiā xiàn zài xuǎn dìng de fāng xiàng bù yí yàng。','Mình có ý kiến khác về việc chọn case cho bài báo cáo nhóm, khác với hướng mà mọi người đang chọn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_02','V808','苏雯',2,'你说说你的思路，我们一起对比两个方案的优劣再做决定。','nǐ shuō shuō nǐ de sī lù， wǒ men yì qǐ duì bǐ liǎng gè fāng àn de yōu liè zài zuò jué dìng。','Cậu nói thử hướng của cậu xem, tụi mình so sánh ưu nhược điểm của hai phương án rồi quyết định luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_03','V808','阮明',3,'我选的案例数据更贴近留学生视角，更容易结合我们课堂所学。','wǒ xuǎn de àn lì shù jù gèng tiē jìn liú xué shēng shì jiǎo， gèng róng yì jié hé wǒ men kè táng suǒ xué。','Case mình chọn có dữ liệu sát với góc nhìn của du học sinh hơn, dễ gắn với kiến thức đã học trên lớp hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_04','V808','苏雯',4,'原有案例优势是资料充足，你的案例需要额外查找外文资料嘛。','yuán yǒu àn lì yōu shì shì zī liào chōng zú， nǐ de àn lì xū yào é wài chá zhǎo wài wén zī liào ma。','Case cũ có ưu điểm là tài liệu đầy đủ sẵn rồi, còn case của cậu chắc phải tìm thêm tài liệu nước ngoài đó nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_05','V808','阮明',5,'我可以负责全部外文资料检索，分担小组搜集素材的工作量。','wǒ kě yǐ fù zé quán bù wài wén zī liào jiǎn suǒ， fēn dān xiǎo zǔ sōu jí sù cái de gōng zuò liàng。','Mình có thể nhận luôn phần tra cứu hết tài liệu nước ngoài, san sẻ bớt khối lượng thu thập tư liệu cho nhóm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_06','V808','苏雯',6,'那我们投票，多数人认可你的方案就调整报告选题。','nà wǒ men tóu piào， duō shù rén rèn kě nǐ de fāng àn jiù tiáo zhěng bào gào xuǎn tí。','Vậy tụi mình biểu quyết đi, nếu đa số đồng ý phương án của cậu thì đổi đề tài báo cáo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_07','V808','阮明',7,'谢谢大家愿意一起讨论，综合所有人想法完善作业。','xiè xiè dà jiā yuàn yì yì qǐ tǎo lùn， zōng hé suǒ yǒu rén xiǎng fǎ wán shàn zuò yè。','Cảm ơn mọi người đã chịu bàn bạc cùng nhau, tổng hợp ý kiến của tất cả để bài làm hoàn thiện hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT809','SHT1','询问老师课堂发言加分规则，主动争取平时分',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V809','SIT809','P1','suon_se','ban_chinh_thuc',NULL,'大学课堂鼓励学生主动发言提问，以此折算平时分，平衡期末试卷单一考核的局限性。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_01','V809','阮明',1,'老师，想咨询课堂发言加分的详细规则，我想多争取平时表现分。','lǎo shī， xiǎng zī xún kè táng fā yán jiā fēn de xiáng xì guī zé， wǒ xiǎng duō zhēng qǔ píng shí biǎo xiàn fēn。','Thưa cô, em muốn hỏi rõ quy định cộng điểm khi phát biểu trên lớp, em muốn cố gắng lấy thêm điểm chuyên cần ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_02','V809','李老师',2,'主动举手回答、提出有价值疑问、上台简短分享，都能累加课堂分。','zhǔ dòng jǔ shǒu huí dá、 tí chū yǒu jià zhí yí wèn、 shàng tái jiǎn duǎn fēn xiǎng， dōu néng lěi jiā kè táng fēn。','Chủ động giơ tay trả lời, đặt câu hỏi có giá trị, hay lên bảng chia sẻ ngắn gọn, tất cả đều được cộng điểm chuyên cần nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_03','V809','阮明',3,'每次发言加分分值相同，还是完整长篇回答分值更高？','měi cì fā yán jiā fēn fēn zhí xiāng tóng， hái shì wán zhěng cháng piān huí dá fēn zhí gèng gāo？','Mỗi lần phát biểu điểm cộng có bằng nhau không ạ, hay trả lời đầy đủ, dài hơn thì điểm cao hơn?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_04','V809','李老师',4,'不看长短，只要独立思考、贴合课堂主题，每次统一加2分。','bù kàn cháng duǎn， zhǐ yào dú lì sī kǎo、 tiē hé kè táng zhǔ tí， měi cì tǒng yī jiā 2 fēn。','Không tính theo độ dài đâu, chỉ cần suy nghĩ độc lập và bám sát chủ đề bài học, mỗi lần đều cộng đều 2 điểm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_05','V809','阮明',5,'每节课最多能几次发言，有没有单次课堂加分上限？','měi jié kè zuì duō néng jǐ cì fā yán， yǒu méi yǒu dān cì kè táng jiā fēn shàng xiàn？','Mỗi tiết học tối đa được phát biểu mấy lần ạ, có giới hạn điểm cộng cho một buổi học không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_06','V809','李老师',6,'无次数上限，只要不占用过多课堂时间均可主动发言。','wú cì shù shàng xiàn， zhǐ yào bù zhàn yòng guò duō kè táng shí jiān jūn kě zhǔ dòng fā yán。','Không giới hạn số lần, miễn là không chiếm quá nhiều thời gian lớp học thì cứ chủ động phát biểu thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_07','V809','阮明',7,'之后每节课我主动思考提问、回答，积极参与课堂互动。','zhī hòu měi jié kè wǒ zhǔ dòng sī kǎo tí wèn、 huí dá， jī jí cān yù kè táng hù dòng。','Từ giờ mỗi tiết học em sẽ chủ động suy nghĩ, đặt câu hỏi, trả lời, tích cực tham gia tương tác trên lớp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT810','SHT2','论文引用格式不懂，请教专业课老师规范要求',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V810','SIT810','P1','twist','chinh_thuc',NULL,'国内高校毕业论文统一执行国家标准参考文献格式，自媒体网络内容认可度低，学术写作优先纸质期刊、专著。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_01','V810','阮明',1,'老师，毕业论文参考文献引用格式我始终把握不准，想向您请教标准。','lǎo shī， bì yè lùn wén cān kǎo wén xiàn yǐn yòng gé shì wǒ shǐ zhōng bǎ wò bù zhǔn， xiǎng xiàng nín qǐng jiào biāo zhǔn。','Thưa cô, em cứ nắm không chắc cách trình bày trích dẫn tài liệu tham khảo trong luận văn tốt nghiệp, em muốn hỏi cô về chuẩn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_02','V810','李老师',2,'校内统一使用GB/T7714国家标准格式，课件最后附完整范例。','xiào nèi tǒng yī shǐ yòng GB/T7714 guó jiā biāo zhǔn gé shì， kè jiàn zuì hòu fù wán zhěng fàn lì。','Trong trường thống nhất dùng định dạng chuẩn quốc gia GB/T7714, cuối slide bài giảng có kèm ví dụ đầy đủ rồi đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_03','V810','阮明',3,'外文书籍、期刊、网页资料三种文献格式区分很大对吗？','wài wén shū jí、 qī kān、 wǎng yè zī liào sān zhǒng wén xiàn gé shì qū fēn hěn dà duì ma？','Ba loại tài liệu sách nước ngoài, tạp chí, và trang web có khác nhau nhiều về định dạng phải không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_04','V810','李老师',4,'网页自媒体资源不建议大量引用，书籍、正规期刊优先使用嘛。','wǎng yè zì méi tǐ zī yuán bù jiàn yì dà liàng yǐn yòng， shū jí、 zhèng guī qī kān yōu xiān shǐ yòng ma。','Nguồn từ trang mạng, tự truyền thông thì không nên trích dẫn nhiều, ưu tiên dùng sách và tạp chí chính thống hơn nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_05','V810','阮明',5,'我按照课件范例调整格式，修改完成后能麻烦您帮忙检查一遍吗？','wǒ àn zhào kè jiàn fàn lì tiáo zhěng gé shì， xiū gǎi wán chéng hòu néng má fán nín bāng máng jiǎn chá yī biàn ma？','Em sẽ chỉnh sửa theo mẫu trong slide bài giảng, sau khi sửa xong phiền cô giúp em kiểm tra lại một lượt được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_06','V810','李老师',6,'初稿定稿前可以发我线上预览，指出格式错误再修改。','chū gǎo dìng gǎo qián kě yǐ fā wǒ xiàn shàng yù lǎn， zhǐ chū gé shì cuò wù zài xiū gǎi。','Trước khi hoàn thiện bản cuối, em có thể gửi bản online cho cô xem trước, cô sẽ chỉ ra chỗ sai để em sửa lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_07','V810','阮明',7,'谢谢您耐心指导引用规范，避免论文大量格式扣分。','xiè xiè nín nài xīn zhǐ dǎo yǐn yòng guī fàn， bì miǎn lùn wén dà liàng gé shì kòu fēn。','Cảm ơn cô đã kiên nhẫn hướng dẫn quy chuẩn trích dẫn, để luận văn tránh bị trừ điểm nhiều vì lỗi định dạng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT811','SHT2','查重重复率超标，咨询老师降重修改方法',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V811','SIT811','P1','that_bai_nhe','ban_chinh_thuc',NULL,'高校毕业论文查重有硬性重复率阈值，复制粘贴原文会判定学术不端，必须自行转述降重。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_01','V811','阮明',1,'老师，我的初稿论文查重重复率超过30%，达不到学校合格标准。','lǎo shī， wǒ de chū gǎo lùn wén chá chóng chóng fù lǜ chāo guò 30%， dá bú dào xué xiào hé gé biāo zhǔn。','Thưa cô, bản nháp luận văn của em bị trùng lặp hơn 30% khi kiểm tra đạo văn, chưa đạt chuẩn của trường ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_02','V811','李老师',2,'合格重复率要求控制在20%以内，超标需要大面积改写降重。','hé gé chóng fù lǜ yāo qiú kòng zhì zài 20% yǐ nèi， chāo biāo xū yào dà miàn jī gǎi xiě jiàng zhòng。','Tỷ lệ trùng lặp đạt chuẩn phải giữ trong 20% trở xuống, vượt mức thì phải sửa lại diện rộng để giảm trùng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_03','V811','阮明',3,'我只是直接摘抄文献句子，不清楚转述改写的技巧啊。','wǒ zhǐ shì zhí jiē zhāi chāo wén xiàn jù zi， bù qīng chǔ zhuǎn shù gǎi xiě de jì qiǎo a。','Em chỉ trích thẳng câu chữ từ tài liệu thôi, chưa rành kỹ thuật diễn đạt lại, viết lại theo ý mình đâu ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_04','V811','李老师',4,'不能简单替换同义词，要调整句子语序、拆分长句、补充自己的分析嘛。','bù néng jiǎn dān tì huàn tóng yì cí， yào tiáo zhěng jù zi yǔ xù、 chāi fēn cháng jù、 bǔ chōng zì jǐ de fēn xī ma。','Không thể chỉ đơn giản thay từ đồng nghĩa được, phải đảo trật tự câu, tách câu dài ra, thêm phân tích của riêng mình vào nữa.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_05','V811','阮明',5,'图表数据、公式部分会不会计入重复率，需要重新绘制吗？','tú biǎo shù jù、 gōng shì bù fèn huì bú huì jì rù chóng fù lǜ， xū yào chóng xīn huì zhì ma？','Phần biểu đồ, số liệu, công thức có bị tính vào tỷ lệ trùng lặp không ạ, có cần vẽ lại hết không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_06','V811','李老师',6,'通用公式不计入，文字分析段落必须全部重新转述改写。','tōng yòng gōng shì bù jì rù， wén zì fēn xī duàn luò bì xū quán bù chóng xīn zhuǎn shù gǎi xiě。','Công thức thông dụng thì không tính, còn đoạn phân tích chữ viết bắt buộc phải viết lại toàn bộ theo cách diễn đạt khác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_07','V811','阮明',7,'我按照您的方法逐段改写，修改完成后再次提交查重。','wǒ àn zhào nín de fāng fǎ zhú duàn gǎi xiě， xiū gǎi wán chéng hòu zài cì tí jiāo chá zhòng。','Em sẽ viết lại từng đoạn theo cách cô hướng dẫn, sửa xong sẽ nộp kiểm tra đạo văn lại lần nữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT812','SHT2','找不到外文参考文献，求助图书馆馆员检索外文数据库',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V812','SIT812','P1','suon_se','ban_chinh_thuc',NULL,'高校图书馆购买多语种外文数据库，仅校园内网、校园VPN可免费下载全文外文文献。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_01','V812','阮明',1,'老师，我写论文需要越南、东南亚相关外文文献，自己检索不到。','lǎo shī， wǒ xiě lùn wén xū yào yuè nán、 dōng nán yà xiāng guān wài wén wén xiàn， zì jǐ jiǎn suǒ bú dào。','Thưa cô, em viết luận văn cần tài liệu nước ngoài liên quan đến Việt Nam, Đông Nam Á, mà tự tra không ra ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_02','V812','王馆员',2,'校内开通多国外文数据库，我带你进入外文检索专属页面。','xiào nèi kāi tōng duō guó wài wén shù jù kù， wǒ dài nǐ jìn rù wài wén jiǎn suǒ zhuān shǔ yè miàn。','Trường có mở nhiều cơ sở dữ liệu ngoại văn của các nước, cô dẫn em vào trang tra cứu ngoại văn riêng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_03','V812','阮明',3,'输入关键词只能检索中文文献，需要切换语种检索入口对吧？','shū rù guān jiàn cí zhǐ néng jiǎn suǒ zhōng wén wén xiàn， xū yào qiè huàn yǔ zhǒng jiǎn suǒ rù kǒu duì ba？','Nhập từ khóa thì chỉ ra được tài liệu tiếng Trung thôi, chắc phải chuyển sang cổng tra cứu ngôn ngữ khác đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_04','V812','王馆员',4,'没错，切换外文语种后，限定地区、出版年份缩小检索范围。','méi cuò， qiè huàn wài wén yǔ zhǒng hòu， xiàn dìng dì qū、 chū bǎn nián fèn suō xiǎo jiǎn suǒ fàn wéi。','Đúng rồi, sau khi chuyển sang ngôn ngữ nước ngoài, em có thể giới hạn khu vực, năm xuất bản để thu hẹp phạm vi tìm kiếm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_05','V812','阮明',5,'检索到的外文文献可以直接下载全文PDF吗？','jiǎn suǒ dào de wài wén wén xiàn kě yǐ zhí jiē xià zài quán wén PDF ma？','Tài liệu nước ngoài tìm được có thể tải trực tiếp bản PDF đầy đủ được không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_06','V812','王馆员',6,'校内IP可免费下载，校外需要登录校园网VPN访问数据库。','xiào nèi IP kě miǎn fèi xià zài， xiào wài xū yào dēng lù xiào yuán wǎng VPN fǎng wèn shù jù kù。','Dùng IP trong trường thì tải miễn phí, còn ngoài trường phải đăng nhập VPN mạng trường mới truy cập được cơ sở dữ liệu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_07','V812','阮明',7,'麻烦您带我操作一遍检索流程，之后我自己查找文献。','má fán nín dài wǒ cāo zuò yī biàn jiǎn suǒ liú chéng， zhī hòu wǒ zì jǐ chá zhǎo wén xiàn。','Phiền cô dẫn em thao tác thử một lượt quy trình tra cứu, sau đó em tự tìm tài liệu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT813','SHT2','打印论文装订格式错误，打印店重新调整排版',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V813','SIT813','P1','twist','tuy_y',NULL,'各学院毕业论文有统一打印排版模板，页眉、行距、页边距、装订线均有硬性规范，打印店常备模板供学生使用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_01','V813','阮明',1,'你好，刚打印的毕业论文装订不对，页码、页眉格式不符合学院要求。','nǐ hǎo， gāng dǎ yìn de bì yè lùn wén zhuāng dìng bú duì， yè mǎ、 yè méi gé shì bù fú hé xué yuàn yāo qiú。','Chào anh/chị, luận văn tốt nghiệp em vừa in xong đóng gáy không đúng, số trang, phần đầu trang không đúng theo yêu cầu của khoa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_02','V813','店员',2,'学院有统一排版模板，你刚才直接上传文档没有套用标准模板嘛。','xué yuàn yǒu tǒng yī pái bǎn mú bǎn， nǐ gāng cái zhí jiē shàng chuán wén dàng méi yǒu tào yòng biāo zhǔn mú bǎn ma。','Khoa có mẫu định dạng thống nhất, lúc nãy em tải file lên in trực tiếp mà không áp mẫu chuẩn đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_03','V813','阮明',3,'我不知道学校专用模板，直接用自己电脑里的格式导出打印了。','wǒ bù zhī dào xué xiào zhuān yòng mú bǎn， zhí jiē yòng zì jǐ diàn nǎo lǐ de gé shì dǎo chū dǎ yìn le。','Em không biết trường có mẫu riêng, cứ dùng định dạng trong máy tính của mình xuất ra in luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_04','V813','店员',4,'我现在套用学院官方模板重新调整，页眉、页码、行距全部统一修改。','wǒ xiàn zài tào yòng xué yuàn guān fāng mú bǎn chóng xīn tiáo zhěng， yè méi、 yè mǎ、 háng jù quán bù tǒng yī xiū gǎi。','Giờ mình áp mẫu chính thức của khoa chỉnh lại, phần đầu trang, số trang, giãn dòng sửa lại đồng bộ hết nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_05','V813','阮明',5,'重新排版打印会额外收取一次打印费用吗？','chóng xīn pái bǎn dǎ yìn huì é wài shōu qǔ yī cì dǎ yìn fèi yòng ma？','In lại theo định dạng mới thì có tính thêm phí in lần nữa không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_06','V813','店员',6,'格式调整失误首次免费重打，多次修改才会叠加收费。','gé shì tiáo zhěng shī wù shǒu cì miǎn fèi zhòng dǎ， duō cì xiū gǎi cái huì dié jiā shōu fèi。','Lỗi định dạng thì lần đầu in lại miễn phí, sửa nhiều lần mới cộng dồn phí thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_07','V813','阮明',7,'辛苦重新排版，调整完我检查无误再装订成册。','xīn kǔ chóng xīn pái bǎn， tiáo zhěng wán wǒ jiǎn chá wú wù zài zhuāng dìng chéng cè。','Cảm ơn anh/chị đã dàn trang lại giúp em, chỉnh xong em kiểm tra không sai gì rồi mới đóng thành quyển.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT814','SHT2','小组论文有人拖延进度，和组员沟通制定截止时间表',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V814','SIT814','P1','suon_se','tuy_y',NULL,'国内小组作业普遍设置分段截止日期，避免临近交稿集体赶工、质量粗糙。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_01','V814','阮明',1,'距离小组论文提交只剩五天，有部分板块素材还没有收集完成。','jù lí xiǎo zǔ lùn wén tí jiāo zhǐ shèng wǔ tiān， yǒu bù fèn bǎn kuài sù cái hái méi yǒu shōu jí wán chéng。','Còn có năm ngày nữa là nộp luận văn nhóm rồi mà một số phần tư liệu vẫn chưa thu thập xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_02','V814','苏雯',2,'有两位组员进度滞后，我们统一拆分每日任务，设置分段小截止期。','yǒu liǎng wèi zǔ yuán jìn dù zhì hòu， wǒ men tǒng yī chāi fēn měi rì rèn wù， shè zhì fēn duàn xiǎo jié zhǐ qī。','Có hai bạn trong nhóm đang chậm tiến độ, tụi mình chia đều công việc từng ngày, đặt mốc hạn nhỏ từng chặng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_03','V814','小林',3,'每天晚上八点群内同步当日完成内容，避免最后一天集中赶工。','měi tiān wǎn shàng bā diǎn qún nèi tóng bù dāng rì wán chéng nèi róng， bì miǎn zuì hòu yī tiān jí zhōng gǎn gōng。','Mỗi tối tám giờ báo cáo trong nhóm phần đã hoàn thành trong ngày, tránh để dồn hết vào ngày cuối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_04','V814','阮明',4,'我负责外文文献翻译，最晚后天完成全部翻译素材交付。','wǒ fù zé wài wén wén xiàn fān yì， zuì wǎn hòu tiān wán chéng quán bù fān yì sù cái jiāo fù。','Mình phụ trách dịch tài liệu nước ngoài, chậm nhất là ngày kia sẽ hoàn thành nộp toàn bộ tư liệu dịch.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_05','V814','苏雯',5,'每人明确标注自己的分工与完成时间，逾期提前在群内说明困难。','měi rén míng què biāo zhù zì jǐ de fēn gōng yǔ wán chéng shí jiān， yú qī tí qián zài qún nèi shuō míng kùn nán。','Mỗi người ghi rõ phần việc và thời gian hoàn thành của mình, nếu trễ hẹn thì báo trước khó khăn trong nhóm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_06','V814','阮明',6,'如果有人遇到检索、写作难题，群内大家一起协助解决。','rú guǒ yǒu rén yù dào jiǎn suǒ、 xiě zuò nán tí， qún nèi dà jiā yì qǐ xié zhù jiě jué。','Nếu ai gặp khó khi tra cứu, viết bài thì cả nhóm cùng hỗ trợ giải quyết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_07','V814','小林',7,'按时间表分段推进，保证论文完整、高质量按时上交。','àn shí jiān biǎo fēn duàn tuī jìn， bǎo zhèng lùn wén wán zhěng、 gāo zhì liàng àn shí shàng jiāo。','Cứ theo lịch mà chia chặng tiến hành, đảm bảo luận văn hoàn chỉnh, chất lượng và nộp đúng hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT815','SHT2','咨询论文致谢、摘要、关键词标准写作规范',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V815','SIT815','P1','suon_se','chinh_thuc',NULL,'国内本科毕业论文强制要求中文摘要+英文摘要、规范关键词、简短致谢，三部分有固定字数与格式标准。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_01','V815','阮明',1,'老师，想请教毕业论文摘要、关键词、致谢三段写作规范。','lǎo shī， xiǎng qǐng jiào bì yè lùn wén zhāi yào、 guān jiàn cí、 zhì xiè sān duàn xiě zuò guī fàn。','Thưa cô, em muốn hỏi quy chuẩn viết ba phần tóm tắt, từ khóa và lời cảm ơn trong luận văn tốt nghiệp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_02','V815','李老师',2,'摘要三百字以内，完整概括研究目的、方法、结论；关键词3-5个。','zhāi yào sān bǎi zì yǐ nèi， wán zhěng gài kuò yán jiū mù dì、 fāng fǎ、 jié lùn； guān jiàn cí 3-5 gè。','Tóm tắt trong khoảng ba trăm chữ, khái quát đầy đủ mục đích, phương pháp, kết luận nghiên cứu; từ khóa từ 3 đến 5 từ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_03','V815','阮明',3,'致谢部分可以感谢家人、同学、授课老师，篇幅有限制吗？','zhì xiè bù fèn kě yǐ gǎn xiè jiā rén、 tóng xué、 shòu kè lǎo shī， piān fú yǒu xiàn zhì ma？','Phần cảm ơn có thể cảm ơn gia đình, bạn học, thầy cô giảng dạy, có giới hạn độ dài không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_04','V815','李老师',4,'致谢篇幅一页以内，简洁真诚即可，不用过度冗长抒情嘛。','zhì xiè piān fú yī yè yǐ nèi， jiǎn jié zhēn chéng jí kě， bù yòng guò dù rǒng cháng shū qíng ma。','Phần cảm ơn tối đa một trang, viết ngắn gọn chân thành là được, không cần lan man cảm xúc quá dài đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_05','V815','阮明',5,'摘要需要中英文双语版本，翻译关键词也要对应准确？','zhāi yào xū yào zhōng yīng wén shuāng yǔ bǎn běn， fān yì guān jiàn cí yě yào duì yìng zhǔn què？','Tóm tắt cần có bản song ngữ Việt Trung, còn từ khóa dịch cũng phải chính xác tương ứng đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_06','V815','李老师',6,'本科毕业论文摘要中英文对照，关键词逐词精准翻译。','běn kē bì yè lùn wén zhāi yào zhōng yīng wén duì zhào， guān jiàn cí zhú cí jīng zhǔn fān yì。','Luận văn tốt nghiệp đại học tóm tắt phải đối chiếu Trung - Anh, từ khóa dịch chính xác từng từ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_07','V815','阮明',7,'我按照规范撰写三段内容，初稿写完发给您检查。','wǒ àn zhào guī fàn zhuàn xiě sān duàn nèi róng， chū gǎo xiě wán fā gěi nín jiǎn chá。','Em sẽ viết ba phần theo đúng quy chuẩn, viết xong bản nháp sẽ gửi cô kiểm tra ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT816','SHT2','电脑崩溃丢失作业初稿，向老师说明情况申请延后上交',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V816','SIT816','P1','twist','ban_chinh_thuc',NULL,'学生设备故障丢失作业属于合理客观事由，多数老师会适度放宽提交期限，但会提醒养成云端备份文件的习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_01','V816','阮明',1,'老师不好意思，昨晚电脑系统崩溃，存储的课程论文初稿全部丢失。','lǎo shī bù hǎo yì sī， zuó wǎn diàn nǎo xì tǒng bēng kuì， cún chǔ de kè chéng lùn wén chū gǎo quán bù diū shī。','Thầy ơi em xin lỗi, tối qua máy tính của em bị sập hệ thống, bản thảo tiểu luận môn học lưu trong máy mất sạch rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_02','V816','李老师',2,'有没有云端备份、U盘备份，能找回一部分写作内容吗？','yǒu méi yǒu yún duān bèi fèn、U pán bèi fèn， néng zhǎo huí yī bù fèn xiě zuò nèi róng ma？','Em không có sao lưu trên đám mây hay USB gì để lấy lại được phần nào không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_03','V816','阮明',3,'没有及时云端同步，只保留少量手写草稿，完整电子版全部丢失嘛。','méi yǒu jí shí yún duān tóng bù， zhǐ bǎo liú shǎo liàng shǒu xiě cǎo gǎo， wán zhěng diàn zi bǎn quán bù diū shī ma。','Em không kịp đồng bộ lên cloud, chỉ còn giữ được vài trang bản thảo viết tay thôi, còn bản điện tử đầy đủ thì mất hết rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_04','V816','李老师',4,'正常截止时间今天下午，突发设备故障可以延后一天提交。','zhèng cháng jié zhǐ shí jiān jīn tiān xià wǔ， tū fā shè bèi gù zhàng kě yǐ yán hòu yī tiān tí jiāo。','Hạn nộp bình thường là chiều nay, nhưng nếu sự cố thiết bị bất ngờ thì có thể gia hạn thêm một ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_05','V816','阮明',5,'我今天通宵重新撰写，明天上午一定完整上交定稿。','wǒ jīn tiān tōng xiāo chóng xīn zhuàn xiě， míng tiān shàng wǔ yí dìng wán zhěng shàng jiāo dìng gǎo。','Em sẽ thức xuyên đêm nay viết lại, chắc chắn sáng mai nộp đủ bản hoàn chỉnh cho thầy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_06','V816','李老师',6,'下次重要作业记得云端备份，避免设备故障丢失全部文稿。','xià cì zhòng yào zuò yè jì de yún duān bèi fèn， bì miǎn shè bèi gù zhàng diū shī quán bù wén gǎo。','Lần sau làm bài quan trọng nhớ sao lưu trên cloud, kẻo thiết bị hỏng là mất trắng cả bài đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_07','V816','阮明',7,'感谢老师通融延后提交，之后一定养成备份文件的习惯。','gǎn xiè lǎo shī tōng róng yán hòu tí jiāo， zhī hòu yí dìng yǎng chéng bèi fèn wén jiàn de xí guàn。','Em cảm ơn thầy đã thông cảm cho gia hạn, sau này em sẽ tập thói quen sao lưu file cẩn thận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT817','SHT2','分不清直接引用、间接转述，找助教讲解论文写作规范',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V817','SIT817','P1','suon_se','tuy_y',NULL,'学术写作严格区分直接引用与间接转述，大段无标注摘抄会判定抄袭，大幅拉高查重重复率。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_01','V817','阮明',1,'学长，写论文分不清直接引用和间接转述，很容易查重超标。','xué zhǎng， xiě lùn wén fēn bù qīng zhí jiē yǐn yòng hé jiàn jiē zhuǎn shù， hěn róng yì chá zhòng chāo biāo。','Anh ơi, viết luận văn em cứ lẫn lộn giữa trích dẫn trực tiếp với diễn giải gián tiếp, dễ bị vượt tỷ lệ trùng lặp lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_02','V817','张学长',2,'直接引用加引号标注页码，篇幅不能过长；转述改写句式无需引号。','zhí jiē yǐn yòng jiā yǐn hào biāo zhù yè mǎ， piān fú bù néng guò cháng； zhuǎn shù gǎi xiě jù shì wú xū yǐn hào。','Trích dẫn trực tiếp thì cho vào ngoặc kép và ghi số trang, không được dài quá; còn diễn giải thì viết lại theo câu chữ của mình, không cần ngoặc kép.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_03','V817','阮明',3,'大段文献观点只能全部改写转述，不能连续直接摘抄原文对吧？','dà duàn wén xiàn guān diǎn zhǐ néng quán bù gǎi xiě zhuǎn shù， bù néng lián xù zhí jiē zhāi chāo yuán wén duì ba？','Vậy những đoạn quan điểm tài liệu dài thì chỉ được diễn giải lại hết, không được chép nguyên văn liên tục đúng không anh?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_04','V817','张学长',4,'单次直接引用不能超过三行，长观点必须拆分转述融合自己分析。','dān cì zhí jiē yǐn yòng bù néng chāo guò sān xíng， zhǎng guān diǎn bì xū chāi fēn zhuǎn shù róng hé zì jǐ fēn xī。','Đúng rồi, mỗi lần trích dẫn trực tiếp không được quá ba dòng, quan điểm dài phải tách ra diễn giải kết hợp với phân tích của bản thân.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_05','V817','阮明',5,'我拿一段自己写的文字，麻烦你标出哪里引用格式出错。','wǒ ná yī duàn zì jǐ xiě de wén zì， má fán nǐ biāo chū nǎ lǐ yǐn yòng gé shì chū cuò。','Em có một đoạn tự viết, phiền anh chỉ giúp em chỗ nào format trích dẫn bị sai với.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_06','V817','张学长',6,'没问题，逐句给你修改示范，方便你之后独立写作。','méi wèn tí， zhú jù gěi nǐ xiū gǎi shì fàn， fāng biàn nǐ zhī hòu dú lì xiě zuò。','Không vấn đề gì, để anh sửa mẫu từng câu cho em, để lần sau em tự viết được luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_07','V817','阮明',7,'听完示范清晰很多，不会再出现引用违规问题。','tīng wán shì fàn qīng xī hěn duō， bú huì zài chū xiàn yǐn yòng wéi guī wèn tí。','Nghe anh chỉ xong em rõ ràng hơn nhiều rồi, chắc không còn bị lỗi trích dẫn nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT818','SHT2','询问期末课程论文字数下限、允许浮动范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V818','SIT818','P1','suon_se','ban_chinh_thuc',NULL,'课程论文、毕业论文有硬性最低正文字数要求，篇幅不足会被判定内容单薄，大幅扣分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_01','V818','阮明',1,'老师，期末课程论文要求最低字数五千字，上下浮动多少算合格？','lǎo shī， qī mò kè chéng lùn wén yāo qiú zuì dī zì shù wǔ qiān zì， shàng xià fú dòng duō shǎo suàn hé gé？','Thầy ơi, tiểu luận cuối kỳ yêu cầu tối thiểu năm nghìn chữ, dao động lên xuống bao nhiêu thì vẫn được tính đạt ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_02','V818','李老师',2,'正文五千字不含摘要参考文献，上下浮动五百字以内都可接受哦。','zhèng wén wǔ qiān zì bù hán zhāi yào cān kǎo wén xiàn， shàng xià fú dòng wǔ bǎi zì yǐ nèi dōu kě jiē shòu ó。','Phần thân bài năm nghìn chữ không tính tóm tắt và tài liệu tham khảo, dao động trong khoảng năm trăm chữ là chấp nhận được nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_03','V818','阮明',3,'字数不足四千五，会直接扣除论文基础分数吗？','zì shù bù zú sì qiān wǔ， huì zhí jiē kòu chú lùn wén jī chǔ fēn shù ma？','Nếu số chữ không đủ bốn nghìn năm trăm thì có bị trừ thẳng điểm cơ bản của bài không thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_04','V818','李老师',4,'低于四千五会判定内容单薄，基础分直接减半。','dī yú sì qiān wǔ huì pàn dìng nèi róng dān bó， jī chǔ fēn zhí jiē jiǎn bàn。','Dưới bốn nghìn năm trăm chữ sẽ bị coi là nội dung sơ sài, điểm cơ bản sẽ bị trừ ngay một nửa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_05','V818','阮明',5,'图表、注释文字算不算入正文字数统计？','tú biǎo、 zhù shì wén zì suàn bù suàn rù zhèng wén zì shù tǒng jì？','Vậy hình ảnh, bảng biểu, chú thích có tính vào số chữ thân bài không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_06','V818','李老师',6,'图表说明、页下注释不计入，仅主体论述段落统计字数。','tú biǎo shuō míng、 yè xià zhù shì bù jì rù， jǐn zhǔ tǐ lùn shù duàn luò tǒng jì zì shù。','Chú thích hình bảng, chú thích cuối trang không tính, chỉ tính số chữ ở các đoạn văn luận điểm chính thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_07','V818','阮明',7,'我控制正文五千字左右，保证内容完整不缺篇幅。','wǒ kòng zhì zhèng wén wǔ qiān zì zuǒ yòu， bǎo zhèng nèi róng wán zhěng bù quē piān fú。','Vậy em sẽ khống chế thân bài khoảng năm nghìn chữ, đảm bảo nội dung đầy đủ chứ không thiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT819','SHT2','论文提交系统上传失败，咨询学院教务线上补交渠道',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V819','SIT819','P1','twist','ban_chinh_thuc',NULL,'课程、毕业论文线上提交系统有固定截止时间与文件格式、大小限制，超时通道自动关闭不再受理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_01','V819','阮明',1,'老师，论文线上提交系统上传文档一直提示失败，无法完成提交。','lǎo shī， lùn wén xiàn shàng tí jiāo xì tǒng shàng chuán wén dàng yì zhí tí shì shī bài， wú fǎ wán chéng tí jiāo。','Thầy ơi, em cứ tải file lên hệ thống nộp bài trực tuyến là báo lỗi thất bại, không nộp được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_02','V819','教务老师',2,'大概率文档内存过大、格式不是PDF，系统仅支持PDF格式上传嘛。','dà gài lǜ wén dàng nèi cún guò dà、 gé shì bú shì PDF， xì tǒng jǐn zhī chí PDF gé shì shàng chuán ma。','Chắc là dung lượng file quá lớn hoặc không phải định dạng PDF, hệ thống chỉ nhận file PDF thôi đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_03','V819','阮明',3,'我原本是Word文档，直接转换PDF之后文件大小超系统限制。','wǒ yuán běn shì Word wén dàng， zhí jiē zhuǎn huàn PDF zhī hòu wén jiàn dà xiǎo chāo xì tǒng xiàn zhì。','Ban đầu em làm file Word, chuyển sang PDF xong thì dung lượng lại vượt giới hạn hệ thống.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_04','V819','教务老师',4,'压缩PDF文件降低分辨率，缩小内存后重新进入系统提交。','yā suō PDF wén jiàn jiàng dī fēn biàn lǜ， suō xiǎo nèi cún hòu chóng xīn jìn rù xì tǒng tí jiāo。','Em nén file PDF lại, giảm độ phân giải xuống cho nhẹ dung lượng rồi vào hệ thống nộp lại thử xem.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_05','V819','阮明',5,'今天是提交截止日，压缩完成后错过零点还能补交吗？','jīn tiān shì tí jiāo jié zhǐ rì， yā suō wán chéng hòu cuò guò líng diǎn hái néng bǔ jiāo ma？','Hôm nay là hạn chót nộp bài, nếu nén xong mà lỡ qua giờ đúng nửa đêm thì còn nộp bổ sung được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_06','V819','教务老师',6,'系统零点关闭通道，今晚二十三点五十九分前必须上传成功。','xì tǒng líng diǎn guān bì tōng dào， jīn wǎn èr shí sān diǎn wǔ shí jiǔ fēn qián bì xū shàng chuán chéng gōng。','Hệ thống đóng cổng đúng lúc nửa đêm, tối nay bắt buộc phải tải lên thành công trước 23 giờ 59 phút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_07','V819','阮明',7,'我立刻压缩文档，赶在通道关闭前完成论文提交。','wǒ lì kè yā suō wén dàng， gǎn zài tōng dào guān bì qián wán chéng lùn wén tí jiāo。','Vậy em nén file ngay bây giờ, cố gắng nộp xong tiểu luận trước khi cổng đóng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT820','SHT3','想引用网络自媒体资料，咨询老师是否符合学术规范',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V820','SIT820','P1','that_bai_nhe','ban_chinh_thuc',NULL,'自媒体、短视频平台内容不具备学术权威性，高校论文不允许单独以此作为核心论证依据。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_01','V820','阮明',1,'老师，论文里想引用自媒体公众号文章的数据作为论据可以吗？','lǎo shī， lùn wén lǐ xiǎng yǐn yòng zì méi tǐ gōng zhòng hào wén zhāng de shù jù zuò wéi lùn jù kě yǐ ma？','Thầy ơi, em muốn trích dẫn số liệu từ bài viết trên trang tự truyền thông (fanpage) vào luận văn làm luận cứ có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_02','V820','李老师',2,'自媒体无正规学术审核，仅能作为辅助参考，不能当作核心论据。','zì méi tǐ wú zhèng guī xué shù shěn hé， jǐn néng zuò wéi fǔ zhù cān kǎo， bù néng dàng zuò hé xīn lùn jù。','Nội dung tự truyền thông không qua thẩm định học thuật chính quy, chỉ dùng làm tham khảo phụ thôi, không thể dùng làm luận cứ chính được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_03','V820','阮明',3,'如果数据来源只有自媒体，有没有办法合规写入论文内容？','rú guǒ shù jù lái yuán zhǐ yǒu zì méi tǐ， yǒu méi yǒu bàn fǎ hé guī xiě rù lùn wén nèi róng？','Nếu nguồn dữ liệu chỉ có ở trang tự truyền thông thì có cách nào đưa vào luận văn cho hợp lệ không thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_04','V820','李老师',4,'必须搭配官方期刊、统计年鉴佐证，单独自媒体内容不予认可嘛。','bì xū dā pèi guān fāng qī kān、 tǒng jì nián jiàn zuǒ zhèng， dān dú zì méi tǐ nèi róng bù yǔ rèn kě ma。','Bắt buộc phải kèm theo tạp chí chính thống, niên giám thống kê để chứng minh, chứ chỉ dùng riêng nội dung tự truyền thông thì không được công nhận đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_05','V820','阮明',5,'那我放弃自媒体素材，重新检索官方行业报告替换论据。','nà wǒ fàng qì zì méi tǐ sù cái， chóng xīn jiǎn suǒ guān fāng háng yè bào gào tì huàn lùn jù。','Vậy em bỏ tư liệu tự truyền thông đi, tìm lại báo cáo ngành chính thức để thay thế luận cứ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_06','V820','李老师',6,'学术论文优先采用官方、期刊、专著类权威文献资料。','xué shù lùn wén yōu xiān cǎi yòng guān fāng、 qī kān、 zhuān zhù lèi quán wēi wén xiàn zī liào。','Luận văn học thuật nên ưu tiên dùng tài liệu chính thống, tạp chí khoa học, sách chuyên khảo có uy tín.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_07','V820','阮明',7,'我重新查找正规数据源，保证论文引用符合学术标准。','wǒ chóng xīn chá zhǎo zhèng guī shù jù yuán， bǎo zhèng lùn wén yǐn yòng fú hé xué shù biāo zhǔn。','Vậy em sẽ tìm lại nguồn dữ liệu chính quy, đảm bảo trích dẫn trong luận văn đúng chuẩn học thuật.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT821','SHT3','咨询老师期末复习重点、必考章节范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V821','SIT821','P1','suon_se','ban_chinh_thuc',NULL,'期末考前老师会划定大致复习范围，缩小复习体量，但不会直接透露原题，依靠学生自主背诵理解。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_01','V821','阮明',1,'老师，距离期末考还有两周，想咨询课程核心复习重点章节。','lǎo shī， jù lí qī mò kǎo hái yǒu liǎng zhōu， xiǎng zī xún kè chéng hé xīn fù xí zhòng diǎn zhāng jié。','Thầy ơi, còn hai tuần nữa là thi cuối kỳ, em muốn hỏi những chương trọng tâm cần ôn tập của môn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_02','V821','李老师',2,'课本中间四个单元是试卷主要考点，首尾单元仅少量选择题哦。','kè běn zhōng jiān sì gè dān yuán shì shì juàn zhǔ yào kǎo diǎn， shǒu wěi dān yuán jǐn shǎo liàng xuǎn zé tí ó。','Bốn đơn vị bài ở giữa sách là trọng tâm chính của đề thi, các đơn vị đầu và cuối chỉ ra ít câu trắc nghiệm thôi nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_03','V821','阮明',3,'课后拓展阅读书目、课外补充案例会不会出大题？','kè hòu tuò zhǎn yuè dú shū mù、 kè wài bǔ chōng àn lì huì bú huì chū dà tí？','Vậy sách đọc mở rộng và các case study bổ sung ngoài giờ học có ra trong câu tự luận lớn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_04','V821','李老师',4,'大题全部来自课内课本与课堂例题，课外内容仅少量选择填空。','dà tí quán bù lái zì kè nèi kè běn yǔ kè táng lì tí， kè wài nèi róng jǐn shǎo liàng xuǎn zé tián kòng。','Câu tự luận lớn đều lấy từ sách giáo trình và ví dụ trên lớp, phần ngoài chương trình chỉ ra ít câu trắc nghiệm hoặc điền khuyết thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_05','V821','阮明',5,'名词解释、论述题分别对应课本哪一部分内容？','míng cí jiě shì、 lùn shù tí fēn bié duì yìng kè běn nǎ yī bù fèn nèi róng？','Vậy phần giải thích thuật ngữ và phần tự luận tương ứng với nội dung nào trong sách ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_06','V821','李老师',6,'名词解释每单元课后词汇，论述题是课堂反复讲解的核心观点。','míng cí jiě shì měi dān yuán kè hòu cí huì， lùn shù tí shì kè táng fǎn fù jiǎng jiě de hé xīn guān diǎn。','Giải thích thuật ngữ thì lấy từ vựng cuối mỗi đơn vị bài, còn tự luận là những quan điểm cốt lõi được giảng đi giảng lại trên lớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_07','V821','阮明',7,'我优先重点复习核心单元，针对性背诵大题考点。','wǒ yōu xiān zhòng diǎn fù xí hé xīn dān yuán， zhēn duì xìng bèi sòng dà tí kǎo diǎn。','Vậy em sẽ ưu tiên ôn kỹ các đơn vị trọng tâm, học thuộc có định hướng cho các câu tự luận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT822','SHT3','错过随堂小测，询问老师能否安排补测',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V822','SIT822','P1','twist','ban_chinh_thuc',NULL,'因病、公事请假缺测可凭证明补测，无故缺考无补测机会，直接扣除对应平时分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_01','V822','阮明',1,'老师，上周随堂小测我生病请假，没能到场完成测试。','lǎo shī， shàng zhōu suí táng xiǎo cè wǒ shēng bìng qǐng jià， méi néng dào chǎng wán chéng cè shì。','Thầy ơi, tuần trước em bị ốm phải xin nghỉ nên không tham gia bài kiểm tra trên lớp được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_02','V822','李老师',2,'有医院病假证明备案的学生，可以统一参加期末前集中补测。','yǒu yī yuàn bìng jià zhèng míng bèi àn de xué shēng， kě yǐ tǒng yī cān jiā qī mò qián jí zhōng bǔ cè。','Những sinh viên có giấy xác nhận nghỉ ốm của bệnh viện đăng ký lại thì có thể tham gia đợt kiểm tra bù tập trung trước kỳ thi cuối kỳ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_03','V822','阮明',3,'我保留完整医院病历单据，今天带来给您登记备案可以吗？','wǒ bǎo liú wán zhěng yī yuàn bìng lì dān jù， jīn tiān dài lái gěi nín dēng jì bèi àn kě yǐ ma？','Em còn giữ đầy đủ hồ sơ bệnh án của bệnh viện, hôm nay em mang tới để thầy đăng ký được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_04','V822','李老师',4,'病历登记截止本周四，周四之后不再受理补测报名嘛。','bìng lì dēng jì jié zhǐ běn zhōu sì， zhōu sì zhī hòu bù zài shòu lǐ bǔ cè bào míng ma。','Hạn đăng ký hồ sơ bệnh án là hết thứ Năm tuần này, sau thứ Năm sẽ không nhận đăng ký kiểm tra bù nữa đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_05','V822','阮明',5,'补测试卷难度、分值和正常随堂小测完全一致吗？','bǔ cè shì juàn nán dù、 fēn zhí hé zhèng cháng suí táng xiǎo cè wán quán yí zhì ma？','Vậy đề kiểm tra bù độ khó và thang điểm có giống hệt bài kiểm tra trên lớp bình thường không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_06','V822','李老师',6,'题型、分值标准相同，只是作答时间缩短十分钟。','tí xíng、 fēn zhí biāo zhǔn xiāng tóng， zhǐ shì zuò dá shí jiān suō duǎn shí fēn zhōng。','Dạng đề và thang điểm giống nhau, chỉ là thời gian làm bài rút ngắn mười phút thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_07','V822','阮明',7,'我今天上交病假单登记，按时参加统一补测。','wǒ jīn tiān shàng jiāo bìng jià dān dēng jì， àn shí cān jiā tǒng yī bǔ cè。','Vậy hôm nay em nộp giấy nghỉ ốm để đăng ký, rồi tham gia đúng giờ đợt kiểm tra bù tập trung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT823','SHT3','期末挂科，咨询补考报名时间、复习范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V823','SIT823','P1','suon_se','chinh_thuc',NULL,'国内大学补考最高绩点60分，仅标记及格，无法参与奖学金评选，重修才能刷新分数。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_01','V823','阮明',1,'老师，这门专业课期末挂科，想咨询补考报名与复习范围。','lǎo shī， zhè mén zhuān yè kè qī mò guà kē， xiǎng zī xún bǔ kǎo bào míng yǔ fù xí fàn wéi。','Thưa thầy, môn chuyên ngành này em bị rớt trong kỳ thi cuối kỳ, em muốn hỏi về thời gian đăng ký thi lại và phạm vi ôn tập.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_02','V823','教务老师',2,'开学第一周线上系统开放补考报名，逾期视为自动放弃补考。','kāi xué dì yī zhōu xiàn shàng xì tǒng kāi fàng bǔ kǎo bào míng， yú qī shì wèi zì dòng fàng qì bǔ kǎo。','Tuần đầu tiên của học kỳ mới, hệ thống trực tuyến sẽ mở đăng ký thi lại, quá hạn sẽ coi như tự động từ bỏ quyền thi lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_03','V823','阮明',3,'补考试卷考点和期末试卷范围一样，还是会更换全新章节？','bǔ kǎo shì juàn kǎo diǎn hé qī mò shì juàn fàn wéi yī yàng， hái shì huì gēng huàn quán xīn zhāng jié？','Phạm vi kiến thức của đề thi lại có giống với đề thi cuối kỳ không, hay sẽ đổi sang những chương hoàn toàn mới ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_04','V823','教务老师',4,'考点范围完全相同，试卷题目全部重新出题，不会使用原卷。','kǎo diǎn fàn wéi wán quán xiāng tóng， shì juàn tí mù quán bù chóng xīn chū tí， bú huì shǐ yòng yuán juǎn。','Phạm vi kiến thức hoàn toàn giống nhau, nhưng đề thi sẽ được ra mới hoàn toàn, không dùng lại đề cũ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_05','V823','阮明',5,'补考及格即可拿到学分，补考分数会直接替代期末成绩吗？','bǔ kǎo jí gé jí kě ná dào xué fēn， bǔ kǎo fēn shù huì zhí jiē tì dài qī mò chéng jì ma？','Thi lại đạt điểm là được công nhận tín chỉ phải không ạ, và điểm thi lại có thay thế trực tiếp điểm cuối kỳ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_06','V823','教务老师',6,'补考最高记60分及格，无论考多高都不会计入高分。','bǔ kǎo zuì gāo jì 60 fēn jí gé， wú lùn kǎo duō gāo dōu bú huì jì rù gāo fēn。','Điểm thi lại tối đa chỉ được ghi nhận là 60 điểm đạt, dù thi cao đến đâu cũng không được tính điểm cao hơn mức đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_07','V823','阮明',7,'我暑假完整复习课本核心内容，开学顺利通过补考。','wǒ shǔ jià wán zhěng fù xí kè běn hé xīn nèi róng， kāi xué shùn lì tōng guò bǔ kǎo。','Vậy hè này em sẽ ôn tập kỹ nội dung trọng tâm trong sách, để khai giảng là thi lại đạt luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT824','SHT3','补考仍未通过，咨询重修选课流程与缴费标准',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V824','SIT824','P1','that_bai_nhe','chinh_thuc',NULL,'补考不及格必须重修该门课程，按学分收取重修费用，全部考核达标才能拿到对应学分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_01','V824','阮明',1,'老师，补考依旧没有及格，想咨询课程重修办理流程。','lǎo shī， bǔ kǎo yī jiù méi yǒu jí gé， xiǎng zī xún kè chéng chóng xiū bàn lǐ liú chéng。','Thưa thầy/cô, em thi lại vẫn chưa đạt, em muốn hỏi về quy trình đăng ký học lại ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_02','V824','教务老师',2,'下一学期选课周期，线上系统勾选重修课程，缴纳重修学分费。','xià yī xué qī xuǎn kè zhōu qī， xiàn shàng xì tǒng gōu xuǎn chóng xiū kè chéng， jiǎo nà chóng xiū xué fēn fèi。','Vào đợt đăng ký học phần của học kỳ sau, em vào hệ thống trực tuyến chọn học lại và đóng học phí học lại là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_03','V824','阮明',3,'重修需要全程跟班上课、完成全部平时作业与课堂小测吗？','chóng xiū xū yào quán chéng gēn bān shàng kè、 wán chéng quán bù píng shí zuò yè yǔ kè táng xiǎo cè ma？','Em học lại có cần theo học đầy đủ cùng lớp, hoàn thành hết bài tập thường xuyên và kiểm tra trên lớp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_04','V824','教务老师',4,'是的，重修完整复刻正常课程考核规则，出勤、作业、考试全部计分嘛。','shì de， chóng xiū wán zhěng fù kè zhèng cháng kè chéng kǎo hé guī zé， chū qín、 zuò yè、 kǎo shì quán bù jì fēn ma。','Đúng vậy, học lại áp dụng đầy đủ quy chế đánh giá như học bình thường, điểm danh, bài tập, thi cử đều được tính điểm đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_05','V824','阮明',5,'一学分重修收费标准多少，一门完整课程一共几学分？','yī xué fēn chóng xiū shōu fèi biāo zhǔn duō shǎo， yī mén wán zhěng kè chéng yī gòng jǐ xué fēn？','Học phí học lại tính theo mỗi tín chỉ là bao nhiêu, và môn này tổng cộng bao nhiêu tín chỉ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_06','V824','教务老师',6,'每学分一百元，本课程四学分，一次性缴纳四百元重修费。','měi xué fēn yì bǎi yuán， běn kè chéng sì xué fēn， yí cì xìng jiǎo nà sì bǎi yuán chóng xiū fèi。','Mỗi tín chỉ một trăm nghìn, môn này bốn tín chỉ, đóng một lần bốn trăm nghìn tiền học lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_07','V824','阮明',7,'我记下选课时间，下一学期按时报名重修认真学习。','wǒ jì xià xuǎn kè shí jiān， xià yī xué qī àn shí bào míng chóng xiū rèn zhēn xué xí。','Em đã ghi nhớ thời gian đăng ký, học kỳ sau em sẽ đăng ký học lại đúng hạn và học nghiêm túc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT825','SHT3','询问考场允许携带的文具，禁止带入物品清单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V825','SIT825','P1','suon_se','ban_chinh_thuc',NULL,'国内标准化考场严格管控随身物品，电子设备、纸质资料一律禁止带入，草稿纸统一发放回收。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_01','V825','阮明',1,'老师，期末考场允许携带哪些文具，有物品禁止带入考场吗？','lǎo shī， qī mò kǎo chǎng yǔn xǔ xié dài nǎ xiē wén jù， yǒu wù pǐn jìn zhǐ dài rù kǎo chǎng ma？','Thưa thầy/cô, phòng thi cuối kỳ cho phép mang những dụng cụ học tập nào, có vật gì bị cấm mang vào không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_02','V825','李老师',2,'黑色签字笔、2B铅笔、橡皮、直尺可带入；手机、课本、草稿纸全部禁止哦。','hēi sè qiān zì bǐ、2B qiān bǐ、 xiàng pí、 zhí chǐ kě dài rù； shǒu jī、 kè běn、 cǎo gǎo zhǐ quán bù jìn zhǐ ó。','Bút bi mực đen, bút chì 2B, tẩy, thước kẻ thì được mang vào; điện thoại, sách vở, giấy nháp riêng đều bị cấm hết đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_03','V825','阮明',3,'透明文件袋装文具可以，彩色帆布文具袋会不会不让带进考场？','tòu míng wén jiàn dài zhuāng wén jù kě yǐ， cǎi sè fān bù wén jù dài huì bú huì bù ràng dài jìn kǎo chǎng？','Đựng dụng cụ trong túi hồ sơ trong suốt thì được, còn túi vải màu sắc có bị cấm mang vào phòng thi không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_04','V825','李老师',4,'建议透明无图案文具袋，方便监考老师快速检查袋内物品。','jiàn yì tòu míng wú tú àn wén jù dài， fāng biàn jiān kǎo lǎo shī kuài sù jiǎn chá dài nèi wù pǐn。','Nên dùng túi đựng dụng cụ trong suốt không họa tiết, để giám thị dễ kiểm tra đồ bên trong hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_05','V825','阮明',5,'考场会统一发放草稿纸，不需要自己携带白纸对吧？','kǎo chǎng huì tǒng yī fā fàng cǎo gǎo zhǐ， bù xū yào zì jǐ xié dài bái zhǐ duì ba？','Phòng thi sẽ phát giấy nháp chung, không cần tự mang giấy trắng theo đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_06','V825','李老师',6,'每场考试统一分发草稿纸，离场全部回收不允许带出考场。','měi chǎng kǎo shì tǒng yī fēn fā cǎo gǎo zhǐ， lí chǎng quán bù huí shōu bù yǔn xǔ dài chū kǎo chǎng。','Mỗi ca thi đều phát giấy nháp thống nhất, khi ra khỏi phòng phải nộp lại hết, không được mang ra ngoài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_07','V825','阮明',7,'我只准备规定文具，不带任何禁止物品进入考场。','wǒ zhǐ zhǔn bèi guī dìng wén jù， bù dài rèn hé jìn zhǐ wù pǐn jìn rù kǎo chǎng。','Em chỉ chuẩn bị đúng dụng cụ quy định, không mang bất kỳ vật cấm nào vào phòng thi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT826','SHT3','复习资料丢失，找同学拷贝完整复习提纲',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V826','SIT826','P1','twist','tuy_y',NULL,'老师内部复习提纲属于班级专属学习材料，一般不允许跨班级大范围转发。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_01','V826','阮明',1,'我存复习提纲的U盘弄丢了，能不能把你的全套复习资料发我一份？','wǒ cún fù xí tí gāng de U pán nòng diū le， néng bù néng bǎ nǐ de quán tào fù xí zī liào fā wǒ yī fèn？','Em làm mất USB lưu đề cương ôn tập rồi, cậu có thể gửi cho mình trọn bộ tài liệu ôn tập của cậu không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_02','V826','苏雯',2,'可以全部打包发给你，但是提纲内老师标注的内部例题不能转发给其他班级。','kě yǐ quán bù dǎ bāo fā gěi nǐ， dàn shì tí gāng nèi lǎo shī biāo zhù de nèi bù lì tí bù néng zhuǎn fā gěi qí tā bān jí。','Được, mình gửi hết cho cậu, nhưng mấy bài ví dụ nội bộ thầy đánh dấu trong đề cương thì không được chuyển cho lớp khác đâu nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_03','V826','阮明',3,'我只自己复习，绝不外传资料，这点你放心。','wǒ zhǐ zì jǐ fù xí， jué bù wài chuán zī liào， zhè diǎn nǐ fàng xīn。','Mình chỉ tự ôn thôi, tuyệt đối không phát tán ra ngoài, điểm này cậu cứ yên tâm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_04','V826','苏雯',4,'文件很大，微信传输容易卡顿，我分享网盘链接给你下载嘛。','wén jiàn hěn dà， wēi xìn chuán shū róng yì kǎ dùn， wǒ fēn xiǎng wǎng pán liàn jiē gěi nǐ xià zài ma。','File to lắm, gửi qua Zalo dễ bị lag, mình chia sẻ link ổ đĩa mạng cho cậu tải về nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_05','V826','阮明',5,'网盘下载完我立刻核对章节，补齐丢失的背诵提纲。','wǎng pán xià zài wán wǒ lì kè hé duì zhāng jié， bǔ qí diū shī de bèi sòng tí gāng。','Tải xong ổ đĩa mạng mình sẽ đối chiếu từng chương ngay, bổ sung phần đề cương học thuộc bị thiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_06','V826','苏雯',6,'提纲划了必考背诵点，优先背诵标红大题内容。','tí gāng huà le bì kǎo bèi sòng diǎn， yōu xiān bèi sòng biāo hóng dà tí nèi róng。','Đề cương có gạch sẵn phần trọng tâm bắt buộc thi, cậu ưu tiên học thuộc mấy câu lớn được tô đỏ trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_07','V826','阮明',7,'太感谢，丢失资料差点耽误期末复习进度。','tài gǎn xiè， diū shī zī liào chà diǎn dān wù qī mò fù xí jìn dù。','Cảm ơn cậu nhiều lắm, suýt nữa mất tài liệu là trễ hết tiến độ ôn thi cuối kỳ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT827','SHT4','咨询平时分过低，期末卷面需要多少分才能及格',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V827','SIT827','P1','suon_se','ban_chinh_thuc',NULL,'总评分数按固定比例加权计算，平时分偏低时需要更高期末卷面分数才能及格。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_01','V827','阮明',1,'老师，我出勤分、课堂小测得分不高，想问问期末卷面最低多少能总评及格。','lǎo shī， wǒ chū qín fēn、 kè táng xiǎo cè dé fēn bù gāo， xiǎng wèn wèn qī mò juàn miàn zuì dī duō shǎo néng zǒng píng jí gé。','Thưa thầy/cô, điểm chuyên cần và kiểm tra trên lớp của em không cao, em muốn hỏi bài thi cuối kỳ cần tối thiểu bao nhiêu điểm để tổng kết đạt ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_02','V827','李老师',2,'平时分目前只有12分，期末试卷至少考76分，总评才能达到60分及格线。','píng shí fēn mù qián zhǐ yǒu 12 fēn， qī mò shì juàn zhì shǎo kǎo 76 fēn， zǒng píng cái néng dá dào 60 fēn jí gé xiàn。','Điểm quá trình của em hiện chỉ được 12 điểm, bài thi cuối kỳ phải đạt ít nhất 76 điểm thì tổng kết mới đạt mức 60 điểm để qua môn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_03','V827','阮明',3,'试卷满分一百分，76分难度偏高，我需要重点背诵全部大题吗？','shì juàn mǎn fēn yì bǎi fēn，76 fēn nán dù piān gāo， wǒ xū yào zhòng diǎn bèi sòng quán bù dà tí ma？','Bài thi thang điểm một trăm, mà cần 76 điểm thì khá khó, em có cần học thuộc trọng tâm hết các câu lớn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_04','V827','李老师',4,'论述、简答分值占比高，抓住大题就能拉高卷面总分。','lùn shù、 jiǎn dá fēn zhí zhàn bǐ gāo， zhuā zhù dà tí jiù néng lā gāo juàn miàn zǒng fēn。','Phần luận và tự luận ngắn chiếm tỷ trọng điểm cao, nắm chắc các câu lớn là kéo được tổng điểm bài thi lên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_05','V827','阮明',5,'选择题分值低，复习时可以适当减少选择背诵时间？','xuǎn zé tí fēn zhí dī， fù xí shí kě yǐ shì dàng jiǎn shǎo xuǎn zé bèi sòng shí jiān？','Câu trắc nghiệm chiếm ít điểm, vậy khi ôn em có thể giảm bớt thời gian học thuộc phần trắc nghiệm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_06','V827','李老师',6,'选择保证基础分，大题尽量拿满，平衡分配复习精力。','xuǎn zé bǎo zhèng jī chǔ fēn， dà tí jǐn liàng ná mǎn， píng héng fēn pèi fù xí jīng lì。','Trắc nghiệm thì đảm bảo lấy điểm cơ bản, còn câu lớn cố gắng lấy trọn điểm, phân bổ thời gian ôn tập cho cân đối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_07','V827','阮明',7,'我重点攻克主观大题，争取期末卷面达标顺利及格。','wǒ zhòng diǎn gōng kè zhǔ guān dà tí， zhēng qǔ qī mò juàn miàn dá biāo shùn lì jí gé。','Em sẽ tập trung chinh phục các câu tự luận lớn, cố gắng đạt chuẩn để qua môn cuối kỳ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT828','SHT4','选课系统卡顿抢不到心仪选修课，咨询教务调剂方案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V828','SIT828','P1','twist','ban_chinh_thuc',NULL,'高校选修课名额有限，首轮选满只能等待学生退课产生空位，无人工扩容插队渠道。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_01','V828','阮明',1,'老师，线上选课系统卡顿，我心仪的汉语文化选修课已经选满关闭。','lǎo shī， xiàn shàng xuǎn kè xì tǒng kǎ dùn， wǒ xīn yí de hàn yǔ wén huà xuǎn xiū kè yǐ jīng xuǎn mǎn guān bì。','Thưa thầy/cô, hệ thống đăng ký học phần trực tuyến bị lag, môn tự chọn văn hóa Hán ngữ em thích đã đầy và đóng đăng ký rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_02','V828','教务老师',2,'首轮选课结束后有一轮补选调剂通道，三天后系统重新开放空位。','shǒu lún xuǎn kè jié shù hòu yǒu yī lún bǔ xuǎn diào jì tōng dào， sān tiān hòu xì tǒng chóng xīn kāi fàng kōng wèi。','Sau vòng đăng ký đầu tiên sẽ có một đợt đăng ký bổ sung, ba ngày nữa hệ thống sẽ mở lại chỗ trống.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_03','V828','阮明',3,'补选通道是随机释放退课空位，还是可以人工登记插队？','bǔ xuǎn tōng dào shì suí jī shì fàng tuì kè kòng wèi， hái shì kě yǐ rén gōng dēng jì chā duì？','Đợt đăng ký bổ sung là hệ thống tự động phát ngẫu nhiên chỗ trống do người khác hủy, hay có thể đăng ký thủ công xếp hàng trước ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_04','V828','教务老师',4,'无人工插队登记，只能等待其他学生退课后系统自动释放名额嘛。','wú rén gōng chā duì dēng jì， zhǐ néng děng dài qí tā xué shēng tuì kè hòu xì tǒng zì dòng shì fàng míng é ma。','Không có đăng ký thủ công xếp trước đâu, chỉ có thể chờ sinh viên khác hủy môn rồi hệ thống tự động cấp chỗ thôi nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_05','V828','阮明',5,'如果补选依旧抢不到，有没有同类型替代选修课推荐？','rú guǒ bǔ xuǎn yī jiù qiǎng bú dào， yǒu méi yǒu tóng lèi xíng tì dài xuǎn xiū kè tuī jiàn？','Nếu đợt bổ sung vẫn không đăng ký được, thầy/cô có gợi ý môn tự chọn nào tương tự thay thế không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_06','V828','教务老师',6,'有两门民俗类选修课内容相近，难度、学分完全一致。','yǒu liǎng mén mín sú lèi xuǎn xiū kè nèi róng xiāng jìn， nán dù、 xué fēn wán quán yí zhì。','Có hai môn tự chọn về văn hóa dân gian nội dung khá gần, độ khó và số tín chỉ hoàn toàn giống nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_07','V828','阮明',7,'三天后准时登录系统补选，备选同步勾选民俗课程。','sān tiān hòu zhǔn shí dēng lù xì tǒng bǔ xuǎn， bèi xuǎn tóng bù gōu xuǎn mín sú kè chéng。','Ba ngày nữa em sẽ đăng nhập đúng giờ để đăng ký bổ sung, đồng thời chọn thêm môn văn hóa dân gian làm phương án dự phòng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT829','SHT4','选错课程，咨询退课截止时间、退课学分规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V829','SIT829','P1','suon_se','ban_chinh_thuc',NULL,'开学初期设有免费退课窗口期，窗口期外放弃课程会判定弃考挂科，影响学籍学分记录。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_01','V829','阮明',1,'老师，我选课误选高阶汉语课程，自身基础跟不上，想办理退课。','lǎo shī， wǒ xuǎn kè wù xuǎn gāo jiē hàn yǔ kè chéng， zì shēn jī chǔ gēn bù shàng， xiǎng bàn lǐ tuì kè。','Thưa thầy/cô, em đăng ký nhầm môn Hán ngữ nâng cao, trình độ bản thân không theo kịp, em muốn làm thủ tục hủy môn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_02','V829','教务老师',2,'开学第二周周五是免费退课截止日，退课后学分不计入本学期修读记录。','kāi xué dì èr zhōu zhōu wǔ shì miǎn fèi tuì kè jié zhǐ rì， tuì kè hòu xué fēn bù jì rù běn xué qī xiū dú jì lù。','Thứ Sáu tuần thứ hai đầu học kỳ là hạn chót hủy môn miễn phí, hủy sau đó thì tín chỉ sẽ không được ghi vào bảng điểm học kỳ này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_03','V829','阮明',3,'超过截止日期再退课，会标记课程挂科记录在学籍系统吗？','chāo guò jié zhǐ rì qī zài tuì kè， huì biāo jì kè chéng guà kē jì lù zài xué jí xì tǒng ma？','Nếu quá hạn mới hủy môn thì có bị ghi nhận rớt môn vào hồ sơ học tập không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_04','V829','教务老师',4,'逾期退课按弃考处理，直接记挂科，需要后续重修缴费。','yú qī tuì kè àn qì kǎo chǔ lǐ， zhí jiē jì guà kē， xū yào hòu xù chóng xiū jiǎo fèi。','Hủy môn trễ hạn sẽ tính như bỏ thi, ghi thẳng là rớt môn, sau đó phải đăng ký học lại và đóng học phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_05','V829','阮明',5,'今天周二，我现在线上提交退课申请，来得及免费撤销课程。','jīn tiān zhōu èr， wǒ xiàn zài xiàn shàng tí jiāo tuì kè shēn qǐng， lái de jí miǎn fèi chè xiāo kè chéng。','Hôm nay là thứ Ba, em nộp đơn hủy môn trực tuyến ngay bây giờ thì còn kịp hủy miễn phí đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_06','V829','教务老师',6,'线上申请提交后一小时内系统自动审核完成退课。','xiàn shàng shēn qǐng tí jiāo hòu yī xiǎo shí nèi xì tǒng zì dòng shěn hé wán chéng tuì kè。','Sau khi nộp đơn trực tuyến, trong vòng một tiếng hệ thống sẽ tự động duyệt xong việc hủy môn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_07','V829','阮明',7,'我立刻操作退课，重新选择适配我水平的基础选修课。','wǒ lì kè cāo zuò tuì kè， chóng xīn xuǎn zé shì pèi wǒ shuǐ píng de jī chǔ xuǎn xiū kè。','Em sẽ làm thủ tục hủy môn ngay, rồi chọn lại môn tự chọn cơ bản phù hợp hơn với trình độ của em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT830','SHT4','申请开具在校在读证明用于签证、实习',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V830','SIT830','P1','suon_se','chinh_thuc',NULL,'学院加盖公章的在读证明属于官方学籍凭证，出入境、企业实习均认可其法律效力，复印件无公章无效。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_01','V830','阮明',1,'老师，我需要官方在校在读证明，用于续签居留许可和校外实习备案。','lǎo shī， wǒ xū yào guān fāng zài xiào zài dú zhèng míng， yòng yú xù qiān jū liú xǔ kě hé xiào wài shí xí bèi àn。','Thưa thầy/cô, em cần giấy xác nhận đang theo học chính thức, để gia hạn giấy phép cư trú và đăng ký thực tập ngoài trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_02','V830','教务老师',2,'填写纸质申请表，携带护照、学生证，当场打印加盖学院公章哦。','tián xiě zhǐ zhì shēn qǐng biǎo， xié dài hù zhào、 xué shēng zhèng， dāng chǎng dǎ yìn jiā gài xué yuàn gōng zhāng ó。','Em điền vào mẫu đơn giấy, mang theo hộ chiếu và thẻ sinh viên, sẽ được in và đóng dấu của khoa ngay tại chỗ đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_03','V830','阮明',3,'证明可以一次性打印两份，签证、实习分开使用吗？','zhèng míng kě yǐ yí cì xìng dǎ yìn liǎng fèn， qiān zhèng、 shí xí fēn kāi shǐ yòng ma？','Giấy xác nhận có thể in một lần hai bản để dùng riêng cho visa và thực tập không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_04','V830','教务老师',4,'无份数限制，需要几份直接说明，全部同步盖章生效。','wú fèn shù xiàn zhì， xū yào jǐ fèn zhí jiē shuō míng， quán bù tóng bù gài zhāng shēng xiào。','Không giới hạn số bản, cần bao nhiêu bản cứ nói, tất cả đều được đóng dấu có hiệu lực đồng thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_05','V830','阮明',5,'在读证明开具完成，当天就能直接拿去出入境大厅办理签证？','zài dú zhèng míng kāi jù wán chéng， dàng tiān jiù néng zhí jiē ná qù chū rù jìng dà tīng bàn lǐ qiān zhèng？','Sau khi giấy xác nhận làm xong, ngay trong ngày em có thể mang đi thẳng đến phòng xuất nhập cảnh làm visa được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_06','V830','教务老师',6,'盖红色公章的原件具备官方效力，可直接用于签证、实习备案。','gài hóng sè gōng zhāng de yuán jiàn jù bèi guān fāng xiào lì， kě zhí jiē yòng yú qiān zhèng、 shí xí bèi àn。','Bản gốc có đóng dấu đỏ của khoa mang giá trị chính thức, có thể dùng trực tiếp cho visa và đăng ký thực tập.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_07','V830','阮明',7,'我填好申请表，现在提交办理两份在读证明。','wǒ tián hǎo shēn qǐng biǎo， xiàn zài tí jiāo bàn lǐ liǎng fèn zài dú zhèng míng。','Em đã điền xong mẫu đơn, giờ nộp luôn để làm hai bản giấy xác nhận đang học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT831','SHT4','咨询学分修读进度，还差多少学分满足毕业要求',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V831','SIT831','P1','twist','chinh_thuc',NULL,'本科有硬性毕业总学分底线，综测竞赛加分仅用于评优，不能抵扣必修、选修毕业学分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_01','V831','阮明',1,'老师，想核对我已修学分总数，还差多少学分才能达标毕业。','lǎo shī， xiǎng hé duì wǒ yǐ xiū xué fēn zǒng shù， hái chà duō shǎo xué fēn cái néng dá biāo bì yè。','Thưa thầy/cô, em muốn kiểm tra tổng số tín chỉ em đã học, còn thiếu bao nhiêu tín chỉ nữa mới đủ điều kiện tốt nghiệp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_02','V831','教务老师',2,'毕业总学分要求140分，你目前只修满112分，还差28学分。','bì yè zǒng xué fēn yāo qiú 140 fēn， nǐ mù qián zhǐ xiū mǎn 112 fēn， hái chà 28 xué fēn。','Yêu cầu tổng tín chỉ tốt nghiệp là 140, hiện em mới học được 112, còn thiếu 28 tín chỉ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_03','V831','阮明',3,'剩余学分只能靠专业课、选修课补齐，没有其他加分渠道吗？','shèng yú xué fēn zhǐ néng kào zhuān yè kè、 xuǎn xiū kè bǔ qí， méi yǒu qí tā jiā fēn qú dào ma？','Số tín chỉ còn thiếu chỉ có thể bù bằng môn chuyên ngành và môn tự chọn thôi ạ, không còn kênh cộng điểm nào khác sao?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_04','V831','教务老师',4,'竞赛、论文综测加分不抵扣毕业学分，仅用于奖学金评选嘛。','jìng sài、 lùn wén zōng cè jiā fēn bù dǐ kòu bì yè xué fēn， jǐn yòng yú jiǎng xué jīn píng xuǎn ma。','Điểm cộng từ thi đấu, bài luận, đánh giá tổng hợp không được quy đổi trừ vào tín chỉ tốt nghiệp đâu, chỉ dùng để xét học bổng thôi nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_05','V831','阮明',5,'剩余两个学期，平均每学期需要修十四分才能按时毕业？','shèng yú liǎng gè xué qī， píng jūn měi xué qī xū yào xiū shí sì fēn cái néng àn shí bì yè？','Còn hai học kỳ nữa, vậy trung bình mỗi kỳ em cần học đủ mười bốn tín chỉ mới tốt nghiệp đúng hạn phải không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_06','V831','教务老师',6,'没错，每学期至少七门课程，不能大量少选学分课。','méi cuò， měi xué qī zhì shǎo qī mén kè chéng， bù néng dà liàng shǎo xuǎn xué fēn kè。','Đúng vậy, mỗi học kỳ ít nhất bảy môn học, không được đăng ký quá ít tín chỉ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_07','V831','阮明',7,'我之后每学期足额选课，保证按期修满毕业学分。','wǒ zhī hòu měi xué qī zú é xuǎn kè， bǎo zhèng àn qī xiū mǎn bì yè xué fēn。','Từ giờ mỗi học kỳ em sẽ đăng ký đủ số môn, đảm bảo học đủ tín chỉ để tốt nghiệp đúng hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT832','SHT4','咨询辅修专业报名条件、额外课时安排',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V832','SIT832','P1','suon_se','ban_chinh_thuc',NULL,'国内高校辅修专业面向成绩合格无挂科学生开设，授课集中周末，完成后发放独立辅修证明。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_01','V832','阮明',1,'老师，想报名外贸辅修专业，请问报名基础条件有哪些？','lǎo shī， xiǎng bào míng wài mào fǔ xiū zhuān yè， qǐng wèn bào míng jī chǔ tiáo jiàn yǒu nǎ xiē？','Thầy/cô ơi, em muốn đăng ký ngành phụ Ngoại thương, cho em hỏi điều kiện cơ bản để đăng ký là gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_02','V832','教务老师',2,'本专业平均分70分以上，无挂科记录，大二可提交辅修申请。','běn zhuān yè píng jūn fēn 70 fēn yǐ shàng， wú guà kē jì lù， dà èr kě tí jiāo fǔ xiū shēn qǐng。','Điểm trung bình chuyên ngành chính từ 70 trở lên, không có môn nợ, năm hai là có thể nộp đơn đăng ký ngành phụ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_03','V832','阮明',3,'辅修课程全部安排在周末，会不会和本专业课程冲突？','fǔ xiū kè chéng quán bù ān pái zài zhōu mò， huì bú huì hé běn zhuān yè kè chéng chōng tū？','Các môn ngành phụ đều học vào cuối tuần, vậy có bị trùng với môn ngành chính không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_04','V832','教务老师',4,'辅修统一周六全天授课，工作日无额外课时，不会冲突主修课。','fǔ xiū tǒng yī zhōu liù quán tiān shòu kè， gōng zuò rì wú é wài kè shí， bú huì chōng tū zhǔ xiū kè。','Ngành phụ học cả ngày thứ Bảy, không có tiết học thêm vào ngày thường, nên không trùng với môn chính đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_05','V832','阮明',5,'辅修完成后发放辅修证书，证书和主修毕业证一同发放吗？','fǔ xiū wán chéng hòu fā fàng fǔ xiū zhèng shū， zhèng shū hé zhǔ xiū bì yè zhèng yī tóng fā fàng ma？','Sau khi hoàn thành ngành phụ thì có cấp chứng chỉ, chứng chỉ đó có phát cùng lúc với bằng tốt nghiệp ngành chính không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_06','V832','教务老师',6,'毕业时同步发放辅修结业证明，求职可作为专业补充凭证。','bì yè shí tóng bù fā fàng fǔ xiū jié yè zhèng míng， qiú zhí kě zuò wéi zhuān yè bǔ chōng píng zhèng。','Lúc tốt nghiệp sẽ cấp kèm giấy chứng nhận hoàn thành ngành phụ, dùng để bổ sung hồ sơ xin việc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_07','V832','阮明',7,'我本学期稳住平均分，下学期申请报名外贸辅修。','wǒ běn xué qī wěn zhù píng jūn fēn， xià xué qī shēn qǐng bào míng wài mào fǔ xiū。','Em sẽ giữ vững điểm trung bình học kỳ này, học kỳ sau đăng ký ngành phụ Ngoại thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT833','SHT4','教务系统个人信息拼音拼写错误，申请更正学籍信息',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V833','SIT833','P1','twist','chinh_thuc',NULL,'学籍姓名、国籍、证件号属于锁定核心信息，学生无法线上自行修改，必须线下提交证件佐证人工更正。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_01','V833','阮明',1,'老师，教务系统里我的姓名拼音拼写错误，和护照不一致影响办签证。','lǎo shī， jiào wù xì tǒng lǐ wǒ de xìng míng pīn yīn pīn xiě cuò wù， hé hù zhào bù yī zhì yǐng xiǎng bàn qiān zhèng。','Thưa thầy/cô, tên của tôi trong hệ thống giáo vụ bị viết sai phiên âm, không khớp với hộ chiếu nên ảnh hưởng đến việc xin visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_02','V833','教务老师',2,'填写学籍信息变更申请表，附上护照原件复印件佐证正确拼写。','tián xiě xué jí xìn xī biàn gēng shēn qǐng biǎo， fù shàng hù zhào yuán jiàn fù yìn jiàn zuǒ zhèng zhèng què pīn xiě。','Anh/chị điền vào đơn xin thay đổi thông tin học tịch, kèm theo bản photo hộ chiếu gốc để đối chiếu đúng cách viết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_03','V833','阮明',3,'线上系统不能自行修改，必须线下纸质申请人工后台更正嘛。','xiàn shàng xì tǒng bù néng zì xíng xiū gǎi， bì xū xiàn xià zhǐ zhì shēn qǐng rén gōng hòu tái gēng zhèng ma。','Hệ thống trực tuyến không tự sửa được, bắt buộc phải nộp đơn giấy trực tiếp để bộ phận giáo vụ chỉnh sửa thủ công đúng không ạ?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_04','V833','教务老师',4,'学籍核心姓名属于锁定信息，仅教务管理员有权限后台修改。','xué jí hé xīn xìng míng shǔ yú suǒ dìng xìn xī， jǐn jiào wù guǎn lǐ yuán yǒu quán xiàn hòu tái xiū gǎi。','Tên trong hồ sơ học tịch là thông tin cốt lõi bị khóa, chỉ có quản trị viên giáo vụ mới có quyền chỉnh sửa trên hệ thống.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_05','V833','阮明',5,'提交申请表之后，多久能同步更新全校教务系统信息？','tí jiāo shēn qǐng biǎo zhī hòu， duō jiǔ néng tóng bù gēng xīn quán xiào jiào wù xì tǒng xìn xī？','Sau khi nộp đơn thì bao lâu thông tin sẽ được cập nhật đồng bộ trên toàn hệ thống giáo vụ của trường?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_06','V833','教务老师',6,'三个工作日内完成修改，更新后打印成绩单姓名同步更正。','sān gè gōng zuò rì nèi wán chéng xiū gǎi， gēng xīn hòu dǎ yìn chéng jì dān xìng míng tóng bù gēng zhèng。','Trong vòng ba ngày làm việc sẽ hoàn tất chỉnh sửa, sau khi cập nhật thì tên trên bảng điểm in ra cũng sẽ được sửa đồng bộ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_07','V833','阮明',7,'我带好护照复印件，今天提交信息变更申请表。','wǒ dài hǎo hù zhào fù yìn jiàn， jīn tiān tí jiāo xìn xī biàn gēng shēn qǐng biǎo。','Tôi sẽ mang theo bản photo hộ chiếu, hôm nay nộp đơn xin thay đổi thông tin luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT834','SHT5','打印官方成绩单用于升学，咨询打印盖章流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V834','SIT834','P1','suon_se','ban_chinh_thuc',NULL,'境外升学、签证使用的成绩单必须校内官方纸质打印+鲜红公章，自行截图打印无法律效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_01','V834','阮明',1,'老师，我准备升学深造，需要多份加盖公章的官方成绩单。','lǎo shī， wǒ zhǔn bèi shēng xué shēn zào， xū yào duō fèn jiā gài gōng zhāng de guān fāng chéng jì dān。','Thầy/cô ơi, tôi chuẩn bị học lên cao hơn nên cần nhiều bản bảng điểm chính thức có đóng dấu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_02','V834','教务老师',2,'线上系统预约打印，预约完成携带学生证线下领取盖章成绩单哦。','xiàn shàng xì tǒng yù yuē dǎ yìn， yù yuē wán chéng xié dài xué shēng zhèng xiàn xià lǐng qǔ gài zhāng chéng jì dān ó。','Anh/chị đặt lịch in trên hệ thống trực tuyến, sau khi đặt xong thì mang thẻ sinh viên đến nhận bảng điểm đã đóng dấu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_03','V834','阮明',3,'电子版成绩单截图自行打印，能不能加盖学院公章？','diàn zi bǎn chéng jì dān jié tú zì xíng dǎ yìn， néng bù néng jiā gài xué yuàn gōng zhāng？','Nếu tôi tự chụp màn hình bảng điểm điện tử rồi tự in ra thì có được đóng dấu của khoa không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_04','V834','教务老师',4,'仅校内打印机输出的官方纸质成绩单可盖章，自行打印截图无效。','jǐn xiào nèi dǎ yìn jī shū chū de guān fāng zhǐ zhì chéng jì dān kě gài zhāng， zì xíng dǎ yìn jié tú wú xiào。','Chỉ có bảng điểm giấy chính thức in từ máy in trong trường mới được đóng dấu, còn tự in từ ảnh chụp màn hình thì không có giá trị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_05','V834','阮明',5,'一次最多能打印五份，每份都单独加盖红色公章吗？','yī cì zuì duō néng dǎ yìn wǔ fèn， měi fèn dōu dān dú jiā gài hóng sè gōng zhāng ma？','Mỗi lần được in tối đa năm bản, mỗi bản đều được đóng dấu đỏ riêng phải không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_06','V834','教务老师',6,'每份独立盖章，全部具备同等官方效力用于境外升学。','měi fèn dú lì gài zhāng， quán bù jù bèi tóng děng guān fāng xiào lì yòng yú jìng wài shēng xué。','Mỗi bản đều được đóng dấu riêng, tất cả đều có giá trị pháp lý như nhau để dùng du học nước ngoài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_07','V834','阮明',7,'我线上预约打印五份成绩单，下午来办公室领取。','wǒ xiàn shàng yù yuē dǎ yìn wǔ fèn chéng jì dān， xià wǔ lái bàn gōng shì lǐng qǔ。','Tôi sẽ đặt lịch in năm bản bảng điểm trên hệ thống, chiều nay đến văn phòng nhận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT835','SHT5','报名校内汉语辅导小班，咨询上课时段、收费标准',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V835','SIT835','P1','suon_se','ban_chinh_thuc',NULL,'校内留学生汉语辅导小班收费低廉，仅收取教材耗材费，用于针对性提升口语、听力薄弱学生。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_01','V835','阮明',1,'老师，我的汉语口语薄弱，想报名校内留学生汉语辅导小班。','lǎo shī， wǒ de hàn yǔ kǒu yǔ bó ruò， xiǎng bào míng xiào nèi liú xué shēng hàn yǔ fǔ dǎo xiǎo bān。','Thầy/cô ơi, khả năng nói tiếng Trung của em còn yếu, em muốn đăng ký lớp phụ đạo tiếng Trung nhỏ dành cho lưu học sinh trong trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_02','V835','辅导老师',2,'小班每周二、四傍晚两节课，一学期统一收取两百元辅导耗材费。','xiǎo bān měi zhōu èr、 sì bàng wǎn liǎng jié kè， yī xué qī tǒng yī shōu qǔ liǎng bǎi yuán fǔ dǎo hào cái fèi。','Lớp học vào chiều tối thứ Ba và thứ Năm hằng tuần, cả học kỳ chỉ thu 200 tệ phí tài liệu học tập thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_03','V835','阮明',3,'班级人数多少，能保证每个人都有开口练习的机会吗？','bān jí rén shù duō shǎo， néng bǎo zhèng měi gè rén dōu yǒu kāi kǒu liàn xí de jī huì ma？','Lớp có bao nhiêu học viên vậy ạ, có đảm bảo mỗi người đều có cơ hội luyện nói không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_04','V835','辅导老师',4,'每班不超过十人，每节课轮流上台对话练习纠正发音。','měi bān bù chāo guò shí rén， měi jié kè lún liú shàng tái duì huà liàn xí jiū zhèng fā yīn。','Mỗi lớp không quá 10 người, mỗi buổi học sẽ luân phiên lên bảng luyện hội thoại và sửa phát âm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_05','V835','阮明',5,'零基础、中级、高级分班，我需要先参加分班测试吗？','líng jī chǔ、 zhōng jí、 gāo jí fēn bān， wǒ xū yào xiān cān jiā fēn bān cè shì ma？','Có chia lớp theo trình độ mất gốc, trung cấp, cao cấp không, em có cần tham gia kiểm tra xếp lớp trước không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_06','V835','辅导老师',6,'入学简单口语测试，匹配对应难度班级再缴费报名。','rù xué jiǎn dān kǒu yǔ cè shì， pǐ pèi duì yìng nán dù bān jí zài jiǎo fèi bào míng。','Sẽ có bài kiểm tra nói đơn giản khi nhập học, sau khi xếp vào lớp đúng trình độ thì mới đóng tiền đăng ký.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_07','V835','阮明',7,'我今天完成分班测试，合适就报名本学期汉语辅导小班。','wǒ jīn tiān wán chéng fèn bān cè shì， hé shì jiù bào míng běn xué qī hàn yǔ fǔ dǎo xiǎo bān。','Hôm nay em sẽ làm bài kiểm tra xếp lớp, nếu phù hợp em sẽ đăng ký lớp phụ đạo tiếng Trung học kỳ này luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT836','SHT5','图书馆自习被隔壁同学交谈打扰，找管理员协调安静区域',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V836','SIT836','P1','twist','ban_chinh_thuc',NULL,'图书馆分静音自习区、小组研讨室，交谈讨论必须在专用研讨室，阅览区全程保持安静。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_01','V836','阮明',1,'您好，隔壁座位两位同学持续交谈，严重干扰周边自习同学复习。','nín hǎo， gé bì zuò wèi liǎng wèi tóng xué chí xù jiāo tán， yán zhòng gān rǎo zhōu biān zì xí tóng xué fù xí。','Chào anh/chị, hai bạn ngồi bàn bên cạnh cứ nói chuyện liên tục, làm ảnh hưởng nghiêm trọng đến các bạn xung quanh đang ôn bài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_02','V836','管理员',2,'图书馆阅览区禁止大声交谈，我过去提醒两位同学保持安静。','tú shū guǎn yuè lǎn qū jìn zhǐ dà shēng jiāo tán， wǒ guò qù tí xǐng liǎng wèi tóng xué bǎo chí ān jìng。','Khu đọc sách của thư viện cấm nói chuyện lớn tiếng, tôi sẽ qua nhắc nhở hai bạn đó giữ trật tự.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_03','V836','阮明',3,'如果他们需要小组讨论，有没有专门的讨论室可以转移过去？','rú guǒ tā men xū yào xiǎo zǔ tǎo lùn， yǒu méi yǒu zhuān mén de tǎo lùn shì kě yǐ zhuǎn yí guò qù？','Nếu họ cần thảo luận nhóm thì có phòng thảo luận riêng để chuyển qua đó không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_04','V836','管理员',4,'一楼设有独立小组研讨室，交谈类学习活动统一安排在研讨室嘛。','yī lóu shè yǒu dú lì xiǎo zǔ yán tǎo shì， jiāo tán lèi xué xí huó dòng tǒng yī ān pái zài yán tǎo shì ma。','Tầng một có phòng thảo luận nhóm riêng, các hoạt động học tập có trao đổi đều được sắp xếp qua phòng đó nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_05','V836','阮明',5,'我想要全程安静无交谈的区域，能不能调整我的自习座位？','wǒ xiǎng yào quán chéng ān jìng wú jiāo tán de qū yù， néng bù néng tiáo zhěng wǒ de zì xí zuò wèi？','Tôi muốn ngồi ở khu vực hoàn toàn yên tĩnh, không có ai nói chuyện, có thể đổi chỗ tự học cho tôi không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_06','V836','管理员',6,'二楼深度自习区全程静音，我带你去空位落座不受打扰。','èr lóu shēn dù zì xí qū quán chéng jìng yīn， wǒ dài nǐ qù kòng wèi luò zuò bù shòu dǎ rǎo。','Khu tự học chuyên sâu ở tầng hai luôn giữ im lặng tuyệt đối, tôi dẫn bạn đến chỗ trống ngồi, sẽ không bị làm phiền đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_07','V836','阮明',7,'感谢协调安静自习区域，方便我专心复习期末内容。','gǎn xiè xié tiáo ān jìng zì xí qū yù， fāng biàn wǒ zhuān xīn fù xí qī mò nèi róng。','Cảm ơn đã sắp xếp khu tự học yên tĩnh giúp tôi, để tôi tập trung ôn thi cuối kỳ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT837','SHT5','报名校内学术讲座，咨询签到、综测加分规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V837','SIT837','P1','suon_se','tuy_y',NULL,'国内高校综测体系包含学术讲座、竞赛加分，需全程到场完成签到流程才能录入加分记录。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_01','V837','阮明',1,'你好，我想报名本周外贸学术讲座，请问参与能综测加分吗？','nǐ hǎo， wǒ xiǎng bào míng běn zhōu wài mào xué shù jiǎng zuò， qǐng wèn cān yù néng zōng cè jiā fēn ma？','Chào bạn, mình muốn đăng ký tham gia buổi hội thảo học thuật về Ngoại thương tuần này, tham gia có được cộng điểm rèn luyện không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_02','V837','干事',2,'现场签到、听完讲座提交简短心得，一次讲座加0.2综测分哦。','xiàn chǎng qiān dào、 tīng wán jiǎng zuò tí jiāo jiǎn duǎn xīn dé， yī cì jiǎng zuò jiā 0.2 zōng cè fēn ó。','Điểm danh tại chỗ, nghe xong hội thảo nộp một bài thu hoạch ngắn, mỗi buổi hội thảo được cộng 0.2 điểm rèn luyện đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_03','V837','阮明',3,'讲座时长两小时，中途提前离场还能正常计入加分吗？','jiǎng zuò shí cháng liǎng xiǎo shí， zhōng tú tí qián lí chǎng hái néng zhèng cháng jì rù jiā fēn ma？','Hội thảo kéo dài hai tiếng, nếu ra về sớm nửa chừng thì có được tính điểm bình thường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_04','V837','干事',4,'全程听完签到两次（入场、散场），中途离场不予记录加分。','quán chéng tīng wán qiān dào liǎng cì （rù chǎng、 sàn chǎng）， zhōng tú lí chǎng bù yǔ jì lù jiā fēn。','Phải nghe hết toàn bộ và điểm danh hai lần (lúc vào và lúc kết thúc), ra về giữa chừng thì không được ghi nhận cộng điểm đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_05','V837','阮明',5,'讲座名额有限，需要提前线上报名锁定席位吗？','jiǎng zuò míng é yǒu xiàn， xū yào tí qián xiàn shàng bào míng suǒ dìng xí wèi ma？','Số suất tham gia có hạn, mình có cần đăng ký trực tuyến trước để giữ chỗ không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_06','V837','干事',6,'线上小程序提前预约，无预约现场有空位也可临时入场。','xiàn shàng xiǎo chéng xù tí qián yù yuē， wú yù yuē xiàn chǎng yǒu kòng wèi yě kě lín shí rù chǎng。','Đăng ký trước qua mini app trực tuyến, nếu không đăng ký mà tại chỗ còn suất trống thì vẫn vào tạm được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_07','V837','阮明',7,'我线上预约席位，全程参与讲座完成签到拿综测加分。','wǒ xiàn shàng yù yuē xí wèi， quán chéng cān yù jiǎng zuò wán chéng qiān dào ná zōng cè jiā fēn。','Mình sẽ đặt chỗ trực tuyến, tham gia đầy đủ hội thảo và điểm danh để lấy điểm cộng rèn luyện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT838','SHT5','和中国同学结成语言交换搭档，约定每周练习时段',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V838','SIT838','P1','suon_se','tuy_y',NULL,'高校留学生与本国学生结成语言交换搭档是普遍互助学习方式，双方互相教授母语，零成本提升口语能力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_01','V838','阮明',1,'我们结成语言交换搭档吧，我教你越南语，你帮我练习汉语。','wǒ men jié chéng yǔ yán jiāo huàn dā dàng ba， wǒ jiāo nǐ yuè nán yǔ， nǐ bāng wǒ liàn xí hàn yǔ。','Chúng ta kết thành cặp trao đổi ngôn ngữ đi, mình dạy bạn tiếng Việt, bạn giúp mình luyện tiếng Trung nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_02','V838','苏雯',2,'太好了，每周三傍晚两小时，一半时间汉语、一半越南语互换练习。','tài hǎo le， měi zhōu sān bàng wǎn liǎng xiǎo shí， yí bàn shí jiān hàn yǔ、 yí bàn yuè nán yǔ hù huàn liàn xí。','Tuyệt quá, mỗi tuần vào tối thứ Tư hai tiếng, một nửa thời gian luyện tiếng Trung, một nửa luyện tiếng Việt luân phiên nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_03','V838','阮明',3,'练习地点图书馆一楼研讨室，有白板方便写单词、句子讲解对吧？','liàn xí dì diǎn tú shū guǎn yī lóu yán tǎo shì， yǒu bái bǎn fāng biàn xiě dān cí、 jù zi jiǎng jiě duì ba？','Chỗ luyện tập là phòng thảo luận ở tầng một thư viện, có bảng trắng để viết từ vựng, giải thích câu cho dễ đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_04','V838','苏雯',4,'研讨室安静，不会打扰其他人，还能书写词汇互相讲解。','yán tǎo shì ān jìng， bú huì dǎ rǎo qí tā rén， hái néng shū xiě cí huì hù xiāng jiǎng jiě。','Phòng thảo luận yên tĩnh, sẽ không làm phiền người khác, lại có thể viết từ vựng ra để giải thích cho nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_05','V838','阮明',5,'每次结束布置少量口语练习任务，下周见面复盘巩固。','měi cì jié shù bù zhì shǎo liàng kǒu yǔ liàn xí rèn wù， xià zhōu jiàn miàn fù pán gǒng gù。','Mỗi lần kết thúc thì giao một ít bài tập luyện nói, tuần sau gặp lại để ôn lại và củng cố.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_06','V838','苏雯',6,'分工互补互相提升语言，长期坚持进步会很明显。','fēn gōng hù bǔ hù xiāng tí shēng yǔ yán， cháng qī jiān chí jìn bù huì hěn míng xiǎn。','Bổ sung cho nhau như vậy sẽ cùng tiến bộ về ngôn ngữ, kiên trì lâu dài sẽ thấy tiến bộ rõ rệt luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_07','V838','阮明',7,'每周三固定时段见面语言交换，稳步提升双方外语水平。','měi zhōu sān gù dìng shí duàn jiàn miàn yǔ yán jiāo huàn， wěn bù tí shēng shuāng fāng wài yǔ shuǐ píng。','Mỗi thứ Tư hàng tuần cố định giờ gặp nhau trao đổi ngôn ngữ, để cả hai cùng nâng cao trình độ ngoại ngữ dần dần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT839','SHT5','咨询综测加分项目：讲座、竞赛、论文申报规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V839','SIT839','P1','suon_se','ban_chinh_thuc',NULL,'综测分数用于奖学金、评优评先，各类学术活动加分可叠加，但设置单学年加分上限。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_01','V839','阮明',1,'老师，想咨询留学生综合测评加分全部可申报项目细则。','lǎo shī， xiǎng zī xún liú xué shēng zōng hé cè píng jiā fēn quán bù kě shēn bào xiàng mù xì zé。','Thầy/cô ơi, em muốn hỏi chi tiết về tất cả các mục có thể đăng ký để cộng điểm đánh giá tổng hợp cho lưu học sinh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_02','V839','教务老师',2,'分为学术讲座、学科竞赛、期刊论文、社会实践四大类加分。','fēn wéi xué shù jiǎng zuò、 xué kē jìng sài、 qī kān lùn wén、 shè huì shí jiàn sì dà lèi jiā fēn。','Chia thành bốn nhóm lớn để cộng điểm gồm hội thảo học thuật, thi đấu học thuật, bài báo đăng tạp chí và thực tế xã hội.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_03','V839','阮明',3,'校级汉语竞赛拿奖，一次能加多少综测分数？','xiào jí hàn yǔ jìng sài ná jiǎng， yī cì néng jiā duō shǎo zōng cè fēn shù？','Nếu đạt giải trong cuộc thi tiếng Trung cấp trường thì được cộng bao nhiêu điểm đánh giá tổng hợp một lần ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_04','V839','教务老师',4,'校级竞赛三等奖0.3分、二等奖0.5分、一等奖0.8分，逐级递增。','xiào jí jìng sài sān děng jiǎng 0.3 fēn、 èr děng jiǎng 0.5 fēn、 yì děng jiǎng 0.8 fēn， zhú jí dì zēng。','Giải ba cấp trường được 0.3 điểm, giải nhì 0.5 điểm, giải nhất 0.8 điểm, tăng dần theo thứ hạng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_05','V839','阮明',5,'发表普通校园期刊短文，论文加分和竞赛加分可以叠加吗？','fā biǎo pǔ tōng xiào yuán qī kān duǎn wén， lùn wén jiā fēn hé jìng sài jiā fēn kě yǐ dié jiā ma？','Nếu đăng một bài viết ngắn trên tạp chí thông thường của trường thì điểm cộng bài báo và điểm cộng cuộc thi có được cộng dồn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_06','V839','教务老师',6,'全部项目加分可叠加，单学年综测加分上限两分。','quán bù xiàng mù jiā fēn kě dié jiā， dān xué nián zōng cè jiā fēn shàng xiàn liǎng fēn。','Tất cả các mục điểm cộng đều có thể cộng dồn với nhau, nhưng mỗi năm học tổng điểm cộng tối đa là hai điểm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_07','V839','阮明',7,'我多参与讲座、汉语竞赛，争取提升学年综测分数。','wǒ duō cān yù jiǎng zuò、 hàn yǔ jìng sài， zhēng qǔ tí shēng xué nián zōng cè fēn shù。','Em sẽ tham gia nhiều hội thảo và cuộc thi tiếng Trung hơn, cố gắng nâng điểm đánh giá tổng hợp trong năm học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT840','SHT5','报名校级汉语竞赛，咨询参赛材料、评比标准',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V840','SIT840','P1','twist','tuy_y',NULL,'留学生汉语竞赛综合考察发音、逻辑表达，禁止剪辑配音视频，保证真实口语水平比拼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_01','V840','阮明',1,'你好，我想报名校级留学生汉语竞赛，需要准备什么参赛材料？','nǐ hǎo， wǒ xiǎng bào míng xiào jí liú xué shēng hàn yǔ jìng sài， xū yào zhǔn bèi shén me cān sài cái liào？','Chào bạn, mình muốn đăng ký thi Hán ngữ dành cho lưu học sinh cấp trường, cần chuẩn bị tài liệu dự thi gì vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_02','V840','干事',2,'线上提交一分钟汉语自我介绍视频，线下现场参与演讲答题环节。','xiàn shàng tí jiāo yì fēn zhōng hàn yǔ zì wǒ jiè shào shì pín， xiàn xià xiàn chǎng cān yù yǎn jiǎng dá tí huán jié。','Nộp online một video giới thiệu bản thân bằng tiếng Trung dài một phút, còn phần thi nói và trả lời câu hỏi thì tham gia trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_03','V840','阮明',3,'竞赛评分侧重发音标准，还是内容立意、流畅度综合评判？','jìng sài píng fēn cè zhòng fā yīn biāo zhǔn， hái shì nèi róng lì yì、 liú chàng dù zōng hé píng pàn？','Cuộc thi chấm điểm chủ yếu dựa vào phát âm chuẩn, hay là đánh giá tổng hợp cả nội dung, ý tưởng và độ trôi chảy vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_04','V840','干事',4,'发音40%、内容立意30%、表达流畅度30%，三项综合打分嘛。','fā yīn 40%、 nèi róng lì yì 30%、 biǎo dá liú chàng dù 30%， sān xiàng zōng hé dǎ fēn ma。','Phát âm chiếm 40%, nội dung ý tưởng 30%, độ trôi chảy khi diễn đạt 30%, tổng hợp ba phần lại để chấm điểm mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_05','V840','阮明',5,'报名截止后天傍晚，我今天录制自我介绍视频线上提交。','bào míng jié zhǐ hòu tiān bàng wǎn， wǒ jīn tiān lù zhì zì wǒ jiè shào shì pín xiàn shàng tí jiāo。','Hạn đăng ký là chiều tối ngày kia, hôm nay mình quay video giới thiệu bản thân rồi nộp online luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_06','V840','干事',6,'视频不能后期剪辑配音，必须完整现场原声录制。','shì pín bù néng hòu qī jiǎn jí pèi yīn， bì xū wán zhěng xiàn chǎng yuán shēng lù zhì。','Video không được chỉnh sửa lồng tiếng sau đó đâu, phải quay trọn vẹn bằng giọng thật tại chỗ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_07','V840','阮明',7,'我无剪辑完整录制视频，按时提交参赛报名素材。','wǒ wú jiǎn jí wán zhěng lù zhì shì pín， àn shí tí jiāo cān sài bào míng sù cái。','Mình sẽ quay video hoàn chỉnh không chỉnh sửa gì cả, nộp đúng hạn tài liệu đăng ký dự thi.',NULL) ON CONFLICT DO NOTHING;
